CREATE FUNCTION "informix".ischar(pCadena CHAR(255))
RETURNING SMALLINT AS RETORNO,CHAR(100) AS TIPO_ESCRITURA;

DEFINE iNumCaracter		INTEGER;
DEFINE iCantVueltas		INTEGER;
DEFINE iCantError		INTEGER;
DEFINE iEscrituraMayus	INTEGER;
DEFINE iEscrituraNumero	INTEGER;
DEFINE iEscrituraMinus	INTEGER;
DEFINE iEscrituraBlanco	INTEGER;
DEFINE iEscrituraRara	INTEGER;
DEFINE cCodRet			SMALLINT;
DEFINE cLetra			CHAR(1);
DEFINE cTipoEscritura	CHAR(100);

LET iNumCaracter		= 0;
LET iCantVueltas		= 0;
LET iCantError			= 0;
LET iEscrituraMayus		= 0;
LET iEscrituraMinus		= 0;
LET iEscrituraBlanco	= 0;
LET iEscrituraRara		= 0;
LET iEscrituraNumero	= 0;
LET cCodRet				= 0;
LET cLetra				= '';
LET cTipoEscritura		= '';
--SET DEBUG FILE TO "/tmp/Antonio/ischar.out";
--TRACE ON;
BEGIN
	LET iCantVueltas = LENGTH(pCadena);
	FOR iNumCaracter = 1 TO iCantVueltas
		LET cLetra = SUBSTR(pCadena,iNumCaracter,1);
		IF (cLetra  BETWEEN 'A' AND 'Z' OR cLetra = 'Ñ' ) THEN		--OR (NOT cLetra ='Ñ') THEN
			IF iCantError <= 0 THEN
				LET cCodRet = 0;
			ELSE
				LET cCodRet = 1;
			END IF;
				LET iEscrituraMayus = 1;			
		ELIF cLetra BETWEEN 'a' AND 'z' OR cLetra = 'ñ' THEN
			IF iCantError <= 0 THEN
				LET cCodRet = 0;
			ELSE
				LET cCodRet = 1;
			END IF;
				LET iEscrituraMinus = 1;
		ELIF cLetra = ' ' THEN
			IF iCantError <= 0 THEN
				LET cCodRet = 0;
			ELSE
				LET cCodRet = 1;
			END IF;
				LET iEscrituraBlanco = 1;
		ELSE
			LET cCodRet = 1;
			LET iCantError = iCantError + 1;
			IF cLetra BETWEEN '0' AND '9' THEN
				LET iEscrituraNumero = 1;
			ELSE
				LET iEscrituraRara = 1;
			END IF;
		END IF;
		
		
			
			IF iEscrituraBlanco = 1 AND iEscrituraRara = 1 AND iEscrituraMinus = 1 AND iEscrituraMayus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00030.- ESPACIO EN BLANCO,CARACTER NO IDENTIFICADO,NUMEROS,MAYUSCULAS Y MINUSCULAS';
			ELIF iEscrituraBlanco = 1 AND iEscrituraMinus = 1 AND iEscrituraMayus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00029.- ESPACIO EN BLANCO,NUMEROS,MAYUSCULAS Y MINUSCULAS';
			ELIF iEscrituraBlanco = 1 AND iEscrituraRara = 1 AND iEscrituraMayus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00028.- ESPACIO EN BLANCO, CARACTER NO IDENTIFICADO,MAYUSCULAS Y NUMEROS';
			ELIF iEscrituraBlanco = 1 AND iEscrituraRara = 1 AND iEscrituraNumero = 1 AND iEscrituraMinus = 1 THEN
				LET cTipoEscritura = '00027.- ESPACIO EN BLANCO, CARACTER NO IDENTIFICADO,NUMEROS Y MINUSCULAS';
			ELIF iEscrituraBlanco = 1 AND iEscrituraRara = 1 AND iEscrituraMayus = 1 AND iEscrituraMinus = 1 THEN
				LET cTipoEscritura = '00026.- ESPACIO EN BLANCO, CARACTER NO IDENTIFICADO,MAYUSCULAS Y MINUSCULAS';			
			ELIF iEscrituraRara = 1 AND iEscrituraMinus = 1 AND iEscrituraMayus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00025.- CARACTER NO IDENTIFICADO, NUMEROS, MAYUSCULAS Y MINUSCULAS';
			ELIF iEscrituraMinus = 1 AND iEscrituraMayus = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00024.- ESPACIO EN BLANCO, MAYUSCULAS Y MINUSCULAS';
			ELIF iEscrituraNumero = 1 AND iEscrituraMayus = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00023.- ESPACIO EN BLANCO, MAYUSCULAS Y NUMEROS';
			ELIF iEscrituraMinus = 1 AND iEscrituraNumero = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00022.- ESPACIO EN BLANCO, MINUSCULAS Y NUMEROS';
			ELIF iEscrituraMinus = 1 AND iEscrituraRara = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00021.- ESPACIO EN BLANCO, CARACTER NO IDENTIFICADO Y MINUSCULAS';
			ELIF iEscrituraMayus = 1 AND iEscrituraRara = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00020.- ESPACIO EN BLANCO, CARACTER NO IDENTIFICADO Y MAYUSCULAS';
			ELIF iEscrituraNumero = 1 AND iEscrituraRara = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00019.- ESPACIO EN BLANCO, CARACTER NO IDENTIFICADO Y NUMEROS';
			ELIF iEscrituraMinus = 1 AND iEscrituraMayus = 1 AND iEscrituraRara = 1 THEN
				LET cTipoEscritura = '00018.- CARACTER NO IDENTIFICADO, MAYUSCULAS Y MINUSCULAS';
			ELIF iEscrituraNumero = 1 AND iEscrituraMayus = 1 AND iEscrituraRara = 1 THEN
				LET cTipoEscritura = '00017.- CARACTER NO IDENTIFICADO, MAYUSCULAS Y NUMEROS';
			ELIF iEscrituraNumero = 1 AND iEscrituraMinus = 1 AND iEscrituraRara = 1 THEN
				LET cTipoEscritura = '00016.- CARACTER NO IDENTIFICADO, MINUSCULAS Y NUMEROS';
			ELIF iEscrituraMinus = 1 AND iEscrituraMayus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00015.- NUMEROS,MAYUSCULAS Y MINUSCULAS';
			ELIF iEscrituraRara = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00014.- CARACTER NO IDENTIFICADO Y NUMEROS';	
			ELIF iEscrituraMinus = 1 AND iEscrituraRara = 1 THEN
				LET cTipoEscritura = '00013.- CARACTER NO IDENTIFICADO Y MINUSCULAS';
			ELIF iEscrituraMayus = 1 AND iEscrituraRara = 1 THEN
				LET cTipoEscritura = '00012.- CARACTER NO IDENTIFICADO Y MAYUSCULAS';				
			ELIF iEscrituraMayus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00011.- NUMEROS Y MAYUSCULAS';	
			ELIF iEscrituraMinus = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00010.- NUMEROS Y MINUSCULAS';	
			ELIF iEscrituraMinus = 1 AND iEscrituraMayus = 1 THEN
				LET cTipoEscritura = '00009.- MAYUSCULAS Y MINUSCULAS';				
			ELIF iEscrituraMinus = 1 AND iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00008.- ESPACIO EN BLANCO Y MINUSCULAS';
			ELIF iEscrituraBlanco = 1 AND iEscrituraMayus = 1 THEN
				LET cTipoEscritura = '00007.- MAYUSCULAS Y ESPACIO EN BLANCO';
			ELIF iEscrituraBlanco = 1 AND iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00006.- ESPACIO EN BLANCO Y NUMEROS';
			ELIF iEscrituraBlanco = 1 AND iEscrituraRara = 1 THEN
				LET cTipoEscritura = '00005.- ESPACIO EN BLANCO Y CARACTER NO IDENTIFICADO';
			ELIF iEscrituraBlanco = 1 THEN
				LET cTipoEscritura = '00004.- ESPACIO EN BLANCO';
			ELIF iEscrituraMinus = 1 THEN
				LET cTipoEscritura = '00002.- MINUSCULAS';
			ELIF iEscrituraNumero = 1 THEN
				LET cTipoEscritura = '00001.- NUMEROS';
			ELIF iEscrituraMayus = 1 THEN
				LET cTipoEscritura = '00000.- MAYUSCULAS';
			ELSE
				LET cTipoEscritura = '00003.- CARACTER NO IDENTIFICADO';
			END IF;
	END FOR;
	RETURN cCodRet,cTipoEscritura;
END;
END FUNCTION
Document
'DESCRIPCION: Valida una cadena de datos con los posibles tipo de datos excepción del apostrofe ', 
'AUTOR: Antonio Bastidas',
'FECHA: 12 de abril de 2010',
'VERSION: 20100412.1254',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_amconsultaarchivos(pFolio INTEGER,pStatus CHAR(1), pFechaIni CHAR(10), pFechaFin CHAR(10))
            RETURNING 
			CHAR(5) AS CodigoRet,
			INTEGER AS Folio,
			CHAR(1) AS Status,
			CHAR(20) AS NombreArchivo,
			DATE AS FechaRecepcion,
			DATE AS FechaProceso,
			CHAR(3) AS Empresa,
			INTEGER AS TotalReg;
			
DEFINE iSqlErr       	INT;
DEFINE cCodret       	CHAR(5); 
DEFINE iFolio			INT;
DEFINE cStatus			CHAR(1);
DEFINE cNombreArch		CHAR(20);
DEFINE cFecha_recep		DATE;
DEFINE cFecha_Proceso   DATE;
DEFINE cEmpresa			CHAR(3);
DEFINE iTotalReg		INTEGER;


LET cCodret			= '00000';  
LET iSqlErr         = 0;
LET iFolio			= 0;
LET cStatus			= '';
LET cNombreArch		= '';
LET cFecha_recep	= '';
LET cFecha_Proceso  = '';
LET cEmpresa		= '';
LET iTotalReg 		= 0;


BEGIN
   ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
            RETURN cCodret, iFolio, cStatus, cNombreArch,cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg WITH RESUME;
        END IF;
   END EXCEPTION;

	--SET DEBUG FILE TO "/tmp/sp_AMConsultaArchivos.sql.out";
	--TRACE ON;


	IF pFolio IS NULL OR pFolio = 0  THEN --consulta por estatus
		--valida que envien valor de status y fechas inicio y fin
		IF pFechaIni IS NULL OR pFechaIni='' OR pFechaFin IS NULL OR pFechaFin=''  OR pStatus IS NULL OR pStatus = '' THEN  
			LET cCodret= '10000';
			RETURN   cCodret, iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg;
		END IF;		

		IF pStatus = '1' THEN  --status 1 procesado
			
			FOREACH
				SELECT folio_archivo, status, nom_archivo, fecha_genera, fecha_aplicado, cod_empresa, total_registros
				INTO iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg
				FROM bdicheq:sc_amctrlaltasmasivas
				WHERE status = pStatus 
				AND fecha_aplicado::DATE BETWEEN pFechaIni AND pFechaFin
				ORDER BY folio_archivo

				RETURN   cCodret, iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg WITH RESUME;
		
			END FOREACH;

		ELSE  -- status 2 rechazado y 3 por procesar
			
			FOREACH
				SELECT folio_archivo, status, nom_archivo,  fecha_genera, fecha_aplicado, cod_empresa, total_registros
				INTO iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg
				FROM bdicheq:sc_amctrlaltasmasivas
				WHERE status = pStatus
				AND fecha_genera::DATE BETWEEN pFechaIni AND pFechaFin
				ORDER BY folio_archivo		

				RETURN cCodret, iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg WITH RESUME;
		
			END FOREACH;
		END IF;
	

	ELSE --consulta por folio

		FOREACH

			SELECT folio_archivo, status, nom_archivo, fecha_genera, fecha_aplicado, cod_empresa, total_registros
				INTO iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg
				FROM bdicheq:sc_amctrlaltasmasivas
				WHERE folio_archivo = pFolio
				ORDER BY folio_archivo
				
			RETURN   cCodret, iFolio, cStatus, cNombreArch, cFecha_recep, cFecha_Proceso, cEmpresa, iTotalReg WITH RESUME;
		
		END FOREACH;
	END IF;
	
END;    
END PROCEDURE
DOCUMENT
'AUTOR:ABIGAIL VASAVILBAZO CAÑEDO',
'DESCRIPCION:  PROCEDIMIENTO QUE OBTIENE LOS ARCHIVOS DE ALTA MASIVA, FILTRANDO POR ESTUS Y RANGO DE FECHAS O FOLIO',
'MODIFICO:ABIGAIL VASAVILBAZO CAÑEDO ',
'MODIFICACION: SE AGREGA TOTAL DE REGISTROS EN RETORNO',
'FECHA : ABRIL 2010',
'BD    : BDICHEQ',
'VERSION: 20101006.1237';

CREATE PROCEDURE "informix".sp_amconsultaestatus()
RETURNING
	CHAR(5)  AS CodRet,
	CHAR(1)  AS Status,
	CHAR(20) AS Descripcion,
	CHAR(25) AS Union;

-- DECLARA LAS VARIABLES
DEFINE cCodRet CHAR(5);		-- Codigo de error
DEFINE iSqlErr INTEGER;		-- Codigo de error de informix

DEFINE cstatus CHAR(1);		-- Codigo del Estatus
DEFINE cDesc   CHAR(20);		-- Descripcion del Estatus
DEFINE cUnion  CHAR(25);	-- Concatenacion

-- INICIALIZACION DE LAS VARIABLES
LET cCodRet = '00000';
LET iSqlErr	= 0;

LET cstatus = '';
LET cDesc   = '';
LET cUnion  = '';

BEGIN

	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0  THEN
			LET cCodRet  = iSqlErr;
			RETURN cCodret, cstatus, cDesc, cUnion;
		END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO "/tmp/sp_AMConsultaEstatus.out";
	--TRACE ON;

	FOREACH

		SELECT cod_estatus, descripcion
		  INTO cstatus, cDesc
		  FROM bdicheq:sc_amcatestatus
		 WHERE muestra = 'S'

		IF cstatus IS NULL THEN
			LET cCodRet = '00001';
			RETURN cCodret, cstatus, cDesc, cUnion;
		END IF;
		
		LET cUnion = TRIM(cstatus ||' - '|| cDesc);

		RETURN cCodret, TRIM(cstatus), TRIM(cDesc), TRIM(cUnion) WITH RESUME;
	END FOREACH;
END;
END PROCEDURE
DOCUMENT
'AUTOR: Clemente Angulo Ballardo',
'Descripcion: Obtiene los estatus de los archivos que las empresas clientes enviaron a BancCoppel',
'Fecha: 07/04/2010',
'Version: 20100407.1920';

CREATE PROCEDURE "informix".sp_amconsultainfoempresapm(pNumCte CHAR(9), pCodEmp CHAR(3))
RETURNING CHAR(5)  AS CodRet,
          CHAR(9)  AS NumeroCliente,
		  CHAR(60) AS RazonSocial,
		  CHAR(13) AS RFC;


-- DECLARA VARIABLES
DEFINE cCodret CHAR(5);		-- Codigo de error
DEFINE cSqlerr INTEGER;		-- Codigo de error de informix

DEFINE cNumCte CHAR(9);		-- Numero de Cliente
DEFINE cRazon  CHAR(60);	-- Razon Social
DEFINE cRFC    CHAR(13);	-- RFC

-- INICIALIZA VARIABLES
LET cCodret = '00000';
LET cSqlerr = 0;

LET cNumCte = '';
LET cRazon  = '';
LET cRFC    = '';

BEGIN

	ON EXCEPTION SET cSqlerr
        IF cSqlerr <> 0 THEN
            Let cCodret = cSqlerr;
            RETURN cCodret, cNumCte, cRazon, cRFC;
        END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO "/tmp/sp_AMConsultaInfoEmpresaPM.out";
	--TRACE ON;

	IF (pCodEmp = '' OR pCodEmp IS NULL) AND (pNumCte = ''OR pNumCte IS NULL) THEN
		LET cCodret = '00001';
		LET cRazon = 'ERROR AL NO INGRESAR NINGUNO DE LOS PARAMETROS';
		RETURN cCodret, cNumCte, cRazon, cRFC;
	END IF;

	IF ((pCodEmp <> '' ) AND (pNumCte <> '')) THEN
		LET cCodret = '00002';
		LET cRazon = 'ERROR AL NO INGRESAR MAS DE 1 PARAMETRO';
		RETURN cCodret, cNumCte, cRazon, cRFC;
	END IF;

	IF pNumCte <> '' THEN

		SELECT a.numcte, razon_social, rfc
		  INTO cNumCte, cRazon, cRFC
		  FROM bdinteg:si_cliente a
		  JOIN bdinteg:si_ctepm b ON (a.numcte = b.numcte)
		 WHERE a.numcte = pNumCte;

		IF cNumCte IS NULL OR cRazon IS NULL THEN
			LET cCodret = '00003';
			LET cRazon = 'NUMERO DE CLIENTE NO REGISTRADO COMO CLIENTE BANCOPPEL';
			RETURN cCodret, cNumCte, cRazon, cRFC;
		END IF;

		RETURN TRIM(cCodret), TRIM(cNumCte), TRIM(cRazon), TRIM(cRFC);

	ELIF pNumCte = '' AND pCodEmp <> '' THEN

		SELECT numcte
		  INTO cNumCte
		  FROM bdicheq:sc_nominaempresas
		 WHERE codigo = pCodEmp;

		IF cNumCte IS NULL THEN
			LET cCodret = '00004';
			LET cRazon = 'CODIGO DE LA EMPRESA INGRESADO NO VALIDO';
			RETURN cCodret, cNumCte, cRazon, cRFC;
		END IF;

		SELECT razon_social, rfc
		  INTO cRazon, cRFC
		  FROM bdinteg:si_cliente a
		  JOIN bdinteg:si_ctepm b ON (a.numcte = b.numcte)
		 WHERE a.numcte = cNumCte;

		RETURN TRIM(cCodret), TRIM(cNumCte), TRIM(cRazon), TRIM(cRFC);

	END IF;

END;
END PROCEDURE
DOCUMENT
'AUTOR: Clemente Angulo Ballardo',
'Descripcion: Obtiene las empresas o clientes morales dados de alta como clientes Bancoppel',
'Fecha: 05/04/2010',
'Version: 20100405.1330';

CREATE PROCEDURE "informix".sp_amconsultainfrepexitoam(pCodEmpresa CHAR(3), pFolioArchivo INTEGER, pStatus CHAR(1))
RETURNING CHAR  (5) AS CodigoRetorno, 
		  CHAR (75) AS MensajeEjecucion,
		  CHAR  (3) AS CodigoEmpresa,
		  CHAR (20) AS NumeroCliente,
		  CHAR (20) AS NumeroCuenta,
		  CHAR(120) AS NombreCompleto,
		  CHAR (30) AS NumeroEmpleado;
		  
DEFINE iSqlErr INTEGER;				-- ERROR DE INFORMIX
DEFINE cCodRet CHAR(5);				-- CODIGO DEL ERROR
		  
DEFINE cMensajeEjec CHAR (75);		-- MENSAJE DE EJECUCION DEL PROCEDIMIENTO
DEFINE cNumCliente  CHAR (20);		-- NUMERO DE CLIENTE BANCOPPEL
DEFINE cNumCuenta   CHAR (20);		-- NUMERO DE CUENTA BANCOPPEL
DEFINE cNomCompleto CHAR(120);		-- NOMBRE COMPLETO DEL CLIENTE BANCOPPEL
DEFINE cNumEmpleado CHAR (20);		-- NUMERO DE EMPLEADO DE LA EMPRESA A LA QUE PERTENECE
DEFINE cCodEmpresa  CHAR (20);		-- CODIGO DE LA EMPRESA EXTERNA

LET iSqlErr = 0;
LET cCodRet = '00000';

LET cMensajeEjec = 'PROCEDIMIENTO EJECUTADO EXITOSAMENTE';
LET cNumCliente  = '';
LET cNumCuenta   = '';
LET cNomCompleto = '';
LET cNumEmpleado = '';
LET cCodEmpresa  = '';

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodRet= iSqlErr;			
			RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado);
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_AMConsultaInfRepExitoAM.out";
	--TRACE ON;
	
	IF pCodEmpresa = '' OR pCodEmpresa IS NULL THEN
		LET cCodRet = '00001';
		LET cMensajeEjec = 'ERROR EN EL PARAMETRO CODIGO DE LA EMPRESA; INGRESAR UN VALOR VALIDO';
		RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado);
	END IF;
	
	IF pFolioArchivo = 0 OR pFolioArchivo IS NULL THEN
		LET cCodRet = '00002';
		LET cMensajeEjec = 'ERROR EN EL PARAMETRO FOLIO DEL ARCHIVO; INGRESAR UN VALOR VALIDO';
		RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado);
	END IF;	
	
	IF pStatus = '' OR pStatus IS NULL THEN
		LET cCodRet = '00003';
		LET cMensajeEjec = 'ERROR EN EL PARAMETRO ESTATUS DEL ARCHIVO; INGRESAR UN VALOR VALIDO';
		RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado);
	END IF;
	
	IF pStatus = 1 THEN		
		
		FOREACH	
			SELECT a.numcte, a.cuenta, TRIM(a.nombre1) ||' '|| TRIM(a.nombre2) ||' '|| TRIM(a.apell_paterno) ||' '|| TRIM(a.apell_materno), a.num_empleado, a.cod_empresa
			  INTO cNumCliente, cNumCuenta, cNomCompleto, cNumEmpleado, cCodEmpresa
			  FROM bdicheq:sc_AMaltasmasivas a
			  JOIN bdicheq:sc_amctrlaltasmasivas b ON (a.cod_empresa = b.cod_empresa) AND (a.folio_archivo = b.folio_archivo)
			 WHERE a.cod_empresa = pCodEmpresa
			   AND a.folio_archivo = pFolioArchivo
			   AND b.status = pStatus
		  ORDER BY a.nombre1
			   
			RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado) WITH RESUME;
		END FOREACH;
	ELSE
		LET cCodRet = '00004';
		LET cMensajeEjec = 'ESTATUS NO VALIDO; FAVOR DE INGRESA EL ESTATUS EXITOSO';
		RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado);
	END IF;	

	IF cNumCliente = "" OR cNumCliente IS NULL THEN
		LET cCodRet = '00005';
		LET cMensajeEjec = 'NO EXISTE EL ARCHIVO PROCESADO EXITOSAMENTE CONSULTADO';		                   
		RETURN TRIM(cCodRet), TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumCliente), TRIM(cNumCuenta), TRIM(cNomCompleto), TRIM(cNumEmpleado);
	END IF;	
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Obtiene la informacion correspondiente a un archivo exitoso de una empresa externa en particular',
'AUTOR: Clemente Angulo Ballardo',
'FECHA: 19 de Abril de 2010',
'VERSION: 20100419.0930',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_amconsultainfreprechazo(pCodEmpresa CHAR(3))
RETURNING CHAR  (5) AS CodigoRetorno, 
		  CHAR (75) AS MensajeEjecucion,
		  CHAR (10) AS CodigoEmpresa,
		  CHAR (10) AS NumeroEmpleado,
		  CHAR (30) AS PrimerNombreEmpleado,
		  CHAR (30) AS SegundoNombreEmpleado,
		  CHAR (30) AS ApellidoPaternoEmpleado,
		  CHAR (30) AS ApellidoMaternoEmpleado,		  
		  CHAR (10) AS FechaNacimientoEmpleado,
		  CHAR (13) AS RfcEmpleado,
		  CHAR  (1) AS SexoEmpleado,
		  CHAR  (1) AS EstadoCivilEmpleado,
		  CHAR  (3) AS NacionalidadEmpleado,
		  CHAR  (1) AS IdentificacionEmpleado,
		  CHAR (20) AS NumeroIdentificacionEmpleado,
		  CHAR(200) AS Observaciones;
		  
DEFINE iSqlErr INTEGER;				-- ERROR DE INFORMIX
DEFINE cCodRet CHAR(5);				-- CODIGO DEL ERROR
		  
DEFINE cMensajeEjec CHAR (75);		-- MENSAJE DE EJECUCION DEL PROCEDIMIENTO
DEFINE cCodEmpresa  CHAR (10);		-- CODIGO DE LA EMPRESA EXTERNA
DEFINE cNumEmpleado CHAR (10);		-- NUMERO DE EMPLEADO DE LA EMPRESA A LA QUE PERTENECE
DEFINE cPrimNom     CHAR (30);		-- PRIMER NOMBRE DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cSegNom      CHAR (30);		-- SEGUNDO NOMBRE DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cApePat      CHAR (30);		-- APELLIDO PATERNO DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cApeMat      CHAR (30);		-- APELLIDO MATERNO DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cFecNac      CHAR (10);		-- FECHA DE NACIMIENTO DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cRfc 		CHAR (13);		-- RFC DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cSexo 		CHAR  (1);		-- SEXO DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cEdoCivil    CHAR  (1);		-- ESTADO CIVIL DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cNac			CHAR  (3);		-- NACIONALIDAD DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cIdent		CHAR  (1);		-- IDENTIFICACION DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cNumIdent	CHAR (30);		-- NUMERO DE LA IDENTIFICACION DEL EMPLEADO DE LA EMPRESA EXTERNA
DEFINE cObserv		CHAR(255);		-- OBSERVACIONES DEL RECHAZO
DEFINE iCont		INTEGER  ;		-- CONTADOR DE REGISTROS

LET iSqlErr = 0;
LET cCodRet = '00000';

LET cMensajeEjec = 'PROCEDIMIENTO EJECUTADO EXITOSAMENTE';
LET cCodEmpresa  = '';
LET cNumEmpleado = '';
LET cPrimNom     = '';
LET cSegNom      = '';
LET cApePat      = '';
LET cApeMat      = '';
LET cFecNac      = '';
LET cRfc         = '';
LET cSexo        = '';
LET cEdoCivil    = '';
LET cNac         = '';
LET cIdent       = '';
LET cNumIdent    = '';
LET cObserv      = '';
LET iCont        =  0;

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodRet= iSqlErr;			
			RETURN cCodRet, TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumEmpleado), TRIM(cPrimNom), TRIM(cSegNom), TRIM(cApePat),
			                TRIM(cApeMat), cFecNac, TRIM(cRfc), TRIM(cSexo), TRIM(cEdoCivil), TRIM(cNac), TRIM(cIdent),
							TRIM(cNumIdent), TRIM(cObserv);
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_AMConsultaInfRepRechazo.out";
	--TRACE ON;
	
	IF pCodEmpresa = '' OR pCodEmpresa IS NULL THEN
		LET cCodRet = '00001';
		LET cMensajeEjec = 'ERROR EN EL PARAMETRO CODIGO DE LA EMPRESA; INGRESAR UN VALOR VALIDO';
		RETURN cCodRet, TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumEmpleado), TRIM(cPrimNom), TRIM(cSegNom), TRIM(cApePat),
						TRIM(cApeMat), cFecNac, TRIM(cRfc), TRIM(cSexo), TRIM(cEdoCivil), TRIM(cNac), TRIM(cIdent), TRIM(cNumIdent),
						TRIM(cObserv);
	END IF;
	
	FOREACH
	
		SELECT a.cod_empresa, a.num_empleado, a.primer_nombre, a.segundo_nombre, a.apell_pat, a.apell_mat, a.fecha_nac, a.rfc, a.sexo,
			   a.estadocivil, a.nacionalidad, a.identificacion, a.num_identificacion, a.observaciones
		  INTO cCodEmpresa, cNumEmpleado, cPrimNom, cSegNom, cApePat, cApeMat, cFecNac, cRfc, cSexo,
			   cEdoCivil, cNac, cIdent, cNumIdent, cObserv
		  FROM BDICHEQ:sc_amaltasmasivastemp a
		  JOIN BDICHEQ:sc_amctrlaltasmasivas b ON (a.cod_empresa = b.cod_empresa) AND (a.folio_archivo = b.folio_archivo)
		 WHERE a.cod_empresa = pCodEmpresa
		   AND b.status = '2'
	  ORDER BY a.num_empleado DESC  
		
		LET iCont = iCont + 1;		
			   
		RETURN cCodRet, TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumEmpleado), TRIM(cPrimNom), TRIM(cSegNom), TRIM(cApePat),
		                TRIM(cApeMat), cFecNac, TRIM(cRfc), TRIM(cSexo), TRIM(cEdoCivil), TRIM(cNac), TRIM(cIdent), TRIM(cNumIdent),
						TRIM(cObserv) WITH RESUME;
	END FOREACH;

	IF iCont = 0 THEN
		LET cCodRet = '00002';
		LET cMensajeEjec = 'NO EXISTE EL ARCHIVO PROCESADO DE RECHAZO PARA EL CODIGO DE LA EMPRESA CONSULTADO';
		RETURN cCodRet, TRIM(cMensajeEjec), TRIM(cCodEmpresa), TRIM(cNumEmpleado), TRIM(cPrimNom), TRIM(cSegNom), TRIM(cApePat),
		                TRIM(cApeMat), cFecNac, TRIM(cRfc), TRIM(cSexo), TRIM(cEdoCivil), cNac, TRIM(cIdent), TRIM(cNumIdent),
						TRIM(cObserv);
	END IF;	
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Obtiene la informacion correspondiente a un archivo rechazado de una empresa externa en particular',
'AUTOR: Clemente Angulo Ballardo',
'FECHA: 20 de Abril de 2010',
'VERSION: 20100420.1730',
