'DESCRIPCION: Procedimiento que consulta los firmantes relacionados con una cuenta',
'AUTOR: César Valdéz Figueroa',
'FECHA: 23 de Febrero de 2010',
'VERSION: 20100223.1830',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_actualizasaldos_maenoc()
    RETURNING CHAR(5);
    
    DEFINE saldo_mns2010                        DECIMAL(14,2);
    DEFINE vcodret                              CHAR(5);
    DEFINE cuenta_maenoc                        CHAR(20);
    DEFINE anio2010                             CHAR (4);

    BEGIN

   	--	SET DEBUG FILE TO "/ids10_1uc5/tmp/sp_actualizasaldos_maenoc.err";
   	--	TRACE ON;

	LET anio2010 = '2010';
		
		FOREACH
			select a.cuenta, a.capvigprom12
   			into cuenta_maenoc, saldo_mns2010
                	from bdicheq:sc_sdomensualc2010 a, bdicheq:sc_maenoc b
                	where
                	a.anio = anio2010 and
                	a.cuenta = b.cuenta and a.cuenta like '19%'

               		update sc_maenoc
			set sdo_prom_mesant = saldo_mns2010
			where
                	cuenta = cuenta_maenoc;
									
 		END FOREACH;
 			
    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarbintarjetacopia(p_NumTarjeta CHAR(16))

	RETURNING
	CHAR(5) AS COD_RET,
    CHAR(6) AS BINS,
    CHAR(2) AS ID,
    CHAR(1) AS TIPTARJ,
	CHAR(25)	AS BANCO,
    CHAR(3) AS CLAVE;

	---DECLARACIONES
	DEFINE v_cod_ret   CHAR(5);
	DEFINE v_cod_ret2  CHAR(5);
	DEFINE iSqlErr     INTEGER;
	DEFINE iSamErr     INTEGER;
    
	DEFINE cBIN        CHAR(6);
    DEFINE cIdBco      CHAR(2);
    DEFINE cCredDeb    CHAR(1);
	DEFINE cBanco	   CHAR(25);
	DEFINE cCveBanco   CHAR(3);
    

	---INICIALIZACIONES
	LET v_cod_ret	= "00000";
	LET v_cod_ret2	= "00000";
    
	LET cBIN		= "";
    LET cIdBco      = "";
    LET cCredDeb    = "";
	LET cBanco		= "";
	LET cCveBanco	= "";

	--SET DEBUG FILE TO "/tmp/hass/sp_ValidarBINDeTarjetas.out";
	--TRACE ON;

	BEGIN

		ON EXCEPTION
			SET iSqlErr, iSamErr
			IF iSqlErr <> 0 THEN
				LET v_cod_ret = iSqlErr;
			END IF;
			RETURN v_cod_ret, cBIN, cIdBco, cCredDeb, cBanco, cCveBanco;
		END EXCEPTION;

		-- Valida que el numero no sea vacio o nulo
		IF (p_NumTarjeta IS NULL OR p_NumTarjeta = '') THEN
			LET v_cod_ret = "00055";
			RETURN v_cod_ret, cBIN, cIdBco, cCredDeb, cBanco, cCveBanco;
		END IF
        
        -- Verifica que el numero de tarjeta sea American Express
        IF LENGTH (p_NumTarjeta) = 15 THEN
            LET cBIN = SUBSTR(p_NumTarjeta,1,2);
            SELECT cod_param, valor INTO cBIN, cBanco FROM bdisac:sac_param WHERE cod_param = cBIN;
            IF NVL(cBanco, "") <> ""  AND NVL(cBIN, 0) = 37 THEN
                SELECT valor INTO cCveBanco FROM bdisac:sac_param WHERE cod_param = 38;
                LET cIdBco    = "";
                LET cCredDeb  = "c";
            ELSE
                LET v_cod_ret = "00055";
                LET cBanco = "Bin de la tarjeta invalido";
            END IF;
        ELSE
            -- Obtiene el BIN de los primeros 6 degitos del numero de tarjeta
            LET cBIN = SUBSTR(p_NumTarjeta,1,6);

            -- Obtiene clave y banco al que pertenece el BIN
            SELECT {INDEX (bdicheq:sc_bines i_bin_cd)} bin, id_bco, creditodebito, banco_prosa, cve_banco
            INTO cBIN, cIdBco, cCredDeb, cBanco, cCveBanco
            FROM bdicheq:sc_bines
            WHERE bin = cBIN and LOWER(creditodebito) = 'c';
            
            -- Valida que se halla obtenido la clave del banco y la descripcion
            IF NVL(cCveBanco, "") = "" OR NVL(cBanco, "") = "" Then
                LET v_cod_ret = "00055";
                LET cBanco = "Bin de la tarjeta invalido";
                RETURN v_cod_ret, cBIN, cIdBco, cCredDeb, cBanco, cCveBanco;
            END IF

            -- Valida que la tarjeta no sea Bancoppel
            IF TRIM(cCveBanco) = "137" THEN
                LET v_cod_ret = "00056";
                LET cBanco = "La tarjeta no puede ser Bancoppel";
                RETURN v_cod_ret, cBIN, cIdBco, cCredDeb, cBanco, cCveBanco;
            END IF
            
        END IF;
		RETURN v_cod_ret, cBIN, cIdBco, cCredDeb, cBanco, cCveBanco;
	END;
END PROCEDURE
DOCUMENT
'AUTOR: Adrian Lara',
'DESCRIPCION: Procedimiento que valida el bin de la tarjeta y obtiene la clave del banco.',
'FECHA: Septiembre 2010',
'VERSION: 20100930.1105';

CREATE PROCEDURE "informix".corrige_prov_31012011(pempresa CHAR(3))
    
    RETURNING CHAR(5), CHAR(5), INTEGER;
    
    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vsql             CHAR(200);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(14,2);    
    DEFINE vtransacc        CHAR(4);
    DEFINE vdescripcion     CHAR(40);
    DEFINE vsucursal        CHAR(4);  
    
    LET vcodret	     = '000';
    LET vcodret2     = '000';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET vcontador    = -1;
    LET ven_transacc = 0;
    
    LET vsql         = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vcuenta      = '';
    LET vmonto       = 0.00;
    LET vtransacc    = '';
    LET vdescripcion = '';
    LET vsucursal    = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_prov_31012011.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret, vcodret2, vcontador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_prov_31012011.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum > 0 AND tabname = 'ctasxcorregir') THEN
        DROP TABLE "informix".ctasxcorregir;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxcorregir
      (
        cuenta      char(20)    not null,
        monto       money(14,2) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctasxcorr ON "informix".ctasxcorregir(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/ints_31012011.unl INSERT INTO ctasxcorregir" > /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    LET vsql = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasxcorreg.sql';
    --- LET vsql = 'dbaccess bdicheq /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxcorregir;
    
    FOREACH WITH HOLD
        SELECT cuenta, monto
          INTO vcuenta, vmonto
          FROM ctasxcorregir
        
        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
            LET ven_transacc = 1;
        END IF;
        
        UPDATE sc_sdodiarioc
           SET intprovnp31 = vmonto
         WHERE cuenta = vcuenta
           AND aniomes = '201101';
        
        LET vcontador = vcontador + 1;
        
        LET vcuenta = '';
        LET vmonto  = 0.00;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret, vcodret2, vcontador;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarbintarjeta(p_NumTarjeta CHAR(16))

	RETURNING
	CHAR(5)		AS COD_RET,
	CHAR(25)	AS BANCO;

	---DECLARACIONES
	DEFINE v_cod_ret   CHAR(5);
	DEFINE v_cod_ret2  CHAR(5);
	DEFINE iSqlErr     INTEGER;
	DEFINE iSamErr     INTEGER;
	DEFINE sBIN        CHAR(6);
	DEFINE sBanco	   CHAR(25);
	DEFINE sCveBanco   CHAR(3);

	---INICIALIZACIONES
	LET v_cod_ret	= "00000";
	LET v_cod_ret2	= "00000";
	LET sBIN		= "";
	LET sBanco		= "";
	LET sCveBanco	= "";

	-- SET DEBUG FILE TO "/tmp/pitdc/sp_validarbintarjetas.out";
	-- TRACE ON;

	BEGIN

		ON EXCEPTION
			SET iSqlErr, iSamErr
			IF iSqlErr <> 0 THEN
				LET v_cod_ret = iSqlErr;
			END IF;
			RETURN v_cod_ret, sBanco;
		END EXCEPTION;

		--- VALIDA QUE LA TARJETA NO VENGA VACIA O NULA
		IF (p_NumTarjeta IS NULL OR p_NumTarjeta = '') THEN
			LET v_cod_ret = "00001";
			RETURN v_cod_ret, sBanco;
		END IF

        ---- 06-05-2010 
        IF LENGTH (p_NumTarjeta) = 15 THEN
            LET sBIN = SUBSTR(p_NumTarjeta,1,2);
            IF EXISTS (SELECT valor FROM bdisac:sac_param WHERE cod_param = sBIN) THEN
                SELECT valor INTO sBanco FROM bdisac:sac_param WHERE cod_param = sBIN;
            ELSE
--                LET v_cod_ret = "00055";
                LET v_cod_ret = "00058";
            END IF;
        ELSE
            ---- OBTIENE EL BIN POR MEDIO LOS PRIMEROS SEIS DIGITOS DE LA TARJETA
            LET sBIN = SUBSTR(p_NumTarjeta,1,6);

            ---- VALIDA QUE EXISTA EL BIN EN EL CATALOGO
            IF NOT EXISTS (SELECT {INDEX (bdicheq:sc_bines i_bin_cd)} bin FROM bdicheq:sc_bines WHERE bin = sBIN and LOWER(creditodebito) = 'c') THEN
--                LET v_cod_ret = "00055";
                LET v_cod_ret = "00058";
                RETURN v_cod_ret, sBanco;
            ELSE
                --- OBTIENE EL BANCO AL CUAL PERTENECE EL BIN
                SELECT {INDEX (bdicheq:sc_bines i_bin_cd)} banco_prosa, cve_banco
                INTO sBanco, sCveBanco
                FROM bdicheq:sc_bines
                WHERE bin = sBIN and LOWER(creditodebito) = 'c';

                -- DSB 14/04/2010
                IF TRIM(sCveBanco) = "137" THEN
--                    LET v_cod_ret = "00056";
                    LET v_cod_ret = "00059";
                    RETURN v_cod_ret,sBanco;
                END IF;
            END IF;
        END IF;
		RETURN v_cod_ret,sBanco;
	END;
END PROCEDURE
DOCUMENT
'AUTOR: Mohamed Carreón',
'DESCRIPCION: Procedimiento que valida el bin de la tarjeta',
'FECHA: MARZO 2010',
'VERSION: 20100325.1800',
'DSB 14/04/2010 - Se agrega validacion de la clave banco para que cuando se BanCoppel lo rechaze',
'MODIFICO: Iris Arias Zazueta',
'06-05-2010 - Se agrega validacion para que en caso de que la tarjeta sea de AMEX obtenga descripion del banco de sac_param',
'MODIFICO: Jesus Montoya',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_dispersiontraspasomovtos()
RETURNING CHAR(5);

--Declaracion de variables
DEFINE cCodRet            	    	CHAR(5);
DEFINE iSqlError            	    INTEGER;
DEFINE iIsamErr            	    	INTEGER;
DEFINE iEmpleado           	    	INTEGER;
DEFINE iNumRegMov           	    INTEGER;
DEFINE iNumRegEnc           	    INTEGER;

LET cCodRet  = '00000';
LET iSqlError  = 0;
LET iIsamErr = 0;
LET iEmpleado = 0;
LET iNumRegMov = 0;
LET iNumRegEnc = 0;

--*********************************************
--SET DEBUG FILE TO '/tmp/sp_dispersiontraspasomovtos.out';
--TRACE ON;
--*********************************************

BEGIN
	ON EXCEPTION SET iSqlError, iIsamErr
		IF iSqlError != 0 THEN
				LET cCodRet = iSqlError;
				RETURN cCodRet;
		END IF;
    END EXCEPTION;

	INSERT INTO bdicheq:sc_nominamovimientoshist (nombre_archivo,num_empleado,apell_paterno,apell_materno,nombres,cuenta_abono,importe,concepto,status)
	SELECT nombre_archivo,num_empleado,apell_paterno,apell_materno,nombres,cuenta_abono,importe,concepto,status
	FROM bdicheq:sc_nominamovimientos
	WHERE status <> 0;

	LET iNumRegMov = DBINFO("sqlca.sqlerrd2");

	INSERT INTO bdicheq:sc_nominaencabezadosumariohist (empresa,fecha_gen,folio_archivo,nombre_archivo,sentido,cuenta_cargo,fecha_aplicacion,
	total_registros,importe_tot,status,	fecha_insert,importe_aplicado,importe_no_aplicado,folio_acuserecibo,folio_dispersion,iva,comision,
	fecha_aplicado,hora_aplicado)
	SELECT empresa,fecha_gen,folio_archivo,nombre_archivo,sentido,cuenta_cargo,fecha_aplicacion,total_registros,importe_tot,status,
	fecha_insert,importe_aplicado,importe_no_aplicado,folio_acuserecibo,folio_dispersion,iva,comision,fecha_aplicado,hora_aplicado
	FROM bdicheq:sc_nominaencabezadosumario
	WHERE status <> 1;
	
	LET iNumRegEnc = DBINFO("sqlca.sqlerrd2");

	IF iNumRegMov <= 0 OR iNumRegEnc <= 0 THEN
		LET cCodRet = '00001';
	ELSE
		DELETE FROM bdicheq:sc_nominamovimientos WHERE status <> 0;
		DELETE FROM bdicheq:sc_nominaencabezadosumario WHERE status <> 1;
	END IF;

 RETURN cCodRet;
END
END PROCEDURE
DOCUMENT
'AUTOR: Jesus Antonio Bastidas Lopez',
'DESCRIPCION: Se genera el proceso para realizar el traspaso de la informacion a las tablas historicas. ',
'FECHA : 16/12/2010',
'VERSION: 20101216.1158',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_nominamovimientos(pNombreArchivo CHAR(17))
	RETURNING CHAR(5), CHAR(10), CHAR(30), CHAR(20), CHAR(30), CHAR(20), MONEY(16,2), CHAR(60), CHAR(30);

---- VARIABLES  GENERALES---
DEFINE cSqlerr			INTEGER;
DEFINE cCodret      	CHAR(5);
DEFINE vsSQL    		CHAR(100);
DEFINE isam_err			INTEGER;
DEFINE cNum_empleado		CHAR(10);
DEFINE cApell_paterno	CHAR(30);
DEFINE cApell_materno	CHAR(20);
DEFINE cNombres			CHAR(30);
DEFINE cCuenta_abono	CHAR(20);
DEFINE mImporte			MONEY(16,2);
DEFINE cConcepto		CHAR(60);
DEFINE iContador		INTEGER;
DEFINE cStatus 			CHAR(30);

--VALORES INICIALES
LET cSqlerr 			= 0;
LET cCodret 			= '00000';
LET vsSQL 				= '';
LET isam_err 			= 0;
LET cNum_empleado		= '';
LET cApell_paterno 		= '';
LET cApell_materno 		= '';
LET cNombres 			= '';
LET cCuenta_abono 		= '';
LET mImporte	 			= 0.00;
LET cConcepto 			= '';
LET cStatus 				= '';
LET iContador = 0;

--SET debug FILE TO "/tmp/sp_NominaMovimientos.out";
--Trace ON;

Begin
	------  Control de Errores no Controlados
    ON EXCEPTION SET cSqlerr
        IF cSqlerr <> 0 THEN
            Let cCodret = cSqlerr;  
            RETURN NVL(cCodret,''),NVL(cNum_empleado,''),NVL(cApell_paterno,''),NVL(cApell_materno,''),NVL(cNombres,''),NVL(cCuenta_abono,''),NVL(mImporte,''),NVL(cConcepto,''),NVL(cStatus,'');
        END IF;
	END EXCEPTION;

	--Se obtiene la lista de cuentas a regresar
	FOREACH WITH HOLD
		
	SELECT {+INDEX(sc_nominamovimientos idx_nominamovimientos2)} mov.num_empleado, mov.apell_paterno, mov.apell_materno, mov.nombres, mov.cuenta_abono, mov.importe, con.descripcion, est.descripcion 
	INTO cNum_empleado, cApell_paterno, cApell_materno, cNombres, cCuenta_abono, mImporte, cConcepto, cStatus
	FROM bdicheq:sc_nominamovimientos AS mov, 
	     bdicheq:sc_nominaestatus AS est, bdicheq:sc_nominaconceptos AS con 
	WHERE est.tpo_status = '02' 
	AND est.cod_status = mov.status 
	AND mov.nombre_archivo = pNombreArchivo 
	AND mov.status = est.cod_status
	AND  mov.concepto = con.codigoconcepto
	
	UNION ALL
	
	SELECT {+INDEX(sc_nominamovimientoshist idx_nominamovimientoshist2)} mov.num_empleado, mov.apell_paterno, mov.apell_materno, mov.nombres, mov.cuenta_abono, mov.importe, con.descripcion, est.descripcion 
	FROM bdicheq:sc_nominamovimientoshist AS mov, 
	     bdicheq:sc_nominaestatus AS est, bdicheq:sc_nominaconceptos AS con 
	WHERE est.tpo_status = '02' 
	AND est.cod_status = mov.status 
	AND mov.nombre_archivo = pNombreArchivo 
	AND mov.status = est.cod_status
	AND  mov.concepto = con.codigoconcepto

		LET iContador = iContador + 1;
		RETURN NVL(cCodret,''),NVL(cNum_empleado,''),NVL(cApell_paterno,''),NVL(cApell_materno,''),NVL(cNombres,''),NVL(cCuenta_abono,''),NVL(mImporte,''),NVL(cConcepto,''),NVL(cStatus,'') WITH RESUME;
	END FOREACH;
	IF iContador = 0 THEN
		--no hay registros  para regresar
		LET cCodret = '00001';
		RETURN NVL(cCodret,''),NVL(cNum_empleado,''),NVL(cApell_paterno,''),NVL(cApell_materno,''),NVL(cNombres,''),NVL(cCuenta_abono,''),NVL(mImporte,''),NVL(cConcepto,''),NVL(cStatus,'');
	END IF
END
END PROCEDURE
DOCUMENT
'AUTOR :César Valdéz Figueroa',
'DESCRIPCION:  Obtener las cuentas para la dispersion manual, con el fin de regresar la informacion de cuentas al reporte de dispersion manual',
'FECHA : Noviembre de 2009',
'BD    : BDICHEQ',
'VERSION: 20091119.0730',
'MODIFICÓ :Maria Elena Angulo Aispuro',
'DESCRIPCION:  Se agrega union a una nueva consulta a la tabla de sc_nominamovimientoshist con el fin de regresar la informacion de cuentas al reporte de dispersion manual que se encuentran en la historica',
'FECHA : Enero del 2011',
'BD    : BDICHEQ',
'VERSION: 20110112.1806';

create procedure "informix".reg_cheque_doc( pempresa   char(3),  -- Empresa
                                            pcuenta    char(20), -- Cuenta
                                            psucursal  char(4), -- Sucursal
                                            pnumcheq   integer, -- No. Cheque
                                            pcodigo    char(2), -- codigo devolucion
                                            pmonto     decimal(12,2), -- importe
                                            pfolio_suc char(16), -- folio sucursal
                                            ptransacc  char(4), -- transaccion
                                            pejecutivo char(8)    --Usuario
                                            )
RETURNING     CHAR(5);   -- vcodret

   -- ********************************************************************
   --
   -- Nombre:              reg_cheque_doc
   --
   -- Version              1.0.1
   -- Objetivo:            Registro detalle de movimientos de chequeras.........................
   -- Supuestos:           Ninguno
   -- Creado por:          Alejandro Rueda Sanchez
   -- ModIFicado por:      
   -- Ultima ModIFicacion: Junio  - 2010
   --
   --                      Reingenieria de SPL
   --
   -- ********************************************************************

   -- // Definicion de variables
   DEFINE vcodret         char(5);
   DEFINE vcodreterr      char(5);
   DEFINE vsqlerr         integer;
   DEFINE vconsec         smallint;
   DEFINE vdummy          char(100);
   DEFINE vfecha_hoy   	  DATE;
   DEFINE vhora           char(15);
   DEFINE vfecha_alta 	  DATE;
   DEFINE vt_estado 	  CHAR(1);

   LET vcodret      = " ";
   LET vsqlerr      = 0;
   LET vconsec      = 0;
   LET vdummy       = " ";
   LET vt_estado    = " ";

--   SET DEBUG FILE TO "/tmp/reg_cheque_doc.out";
--   TRACE ON;

begin
    on exception set vsqlerr
       IF vsqlerr <> 0 then
          LET vcodret = vsqlerr;
          RETURN vcodret;
       END IF;
    END exception;

   --// Selecciona la fecha del dia.
   SELECT fecha_hoy 
     INTO vfecha_hoy 
     FROM bdicheq:sc_fechas;

   SELECT CURRENT HOUR TO second
     INTO vhora
     FROM bdinteg:dual;

   --//Validaciones de nulos en parametros de entrada
   IF pempresa = " " or pcuenta = " " or psucursal = " " or pnumcheq = 0 or pcodigo = " "  or pejecutivo = " " then
      LET vcodret = "110";
      RETURN vcodret;
   END IF

let pempresa = pempresa;
let pcuenta = pcuenta;
let pnumcheq = pnumcheq;

   --// Selecciona el numero maximo de cheques.
   SELECT max(secuencia)
     INTO vconsec
     FROM bdicheq:sc_contch_hist
    WHERE empresa = pempresa
      AND cuenta = pcuenta
      AND numchq = pnumcheq;

   IF vconsec IS NOT NULL THEN
      LET vconsec = vconsec + 1;
   ELSE
      LET vconsec = 1;
   END IF


   --// SI fue pagado en sucursal, regisstra el cambio del documento
   If pcodigo = "00" then
      --//Inserta el detalle
-- METER ACTUALIZACION POR SEPARADO PARA CHEQUES POR CAMARA'
    if ptransacc = '0231' then
      INSERT INTO sc_contch_hist(empresa, cuenta, numchq, secuencia, sucursal, monto, fecha_alta, hora_alta, folio_suc, transaccion, status, motivo_dev, usuario)
       VALUES(pempresa, pcuenta, pnumcheq,vconsec, psucursal, pmonto, vfecha_hoy, vhora , pfolio_suc, ptransacc, "M", "", pejecutivo);
    else
      INSERT INTO sc_contch_hist(empresa, cuenta, numchq, secuencia, sucursal, monto, fecha_alta, hora_alta, folio_suc, transaccion, status, motivo_dev, usuario)
       VALUES(pempresa, pcuenta, pnumcheq,vconsec, psucursal, pmonto, vfecha_hoy, vhora , pfolio_suc, ptransacc, "P", "", pejecutivo);

       UPDATE sc_contch SET estado = "P", fecha_alta = vfecha_hoy, importe = pmonto 
        WHERE empresa = pempresa
          AND cuenta = pcuenta
          AND numero = pnumcheq;
    end if
   ELSE --//No fue pagado
      --//Verifica el estatus actual del cheque
      SELECT estado 
        INTO vt_estado 
        FROM bdicheq:sc_contch
       WHERE empresa = pempresa
         AND cuenta = pcuenta
         AND numero = pnumcheq;
  
      IF vt_estado = "P" THEN
         LET vcodret = "600";
         RETURN vcodret;
      END IF  

      --//Inserta el detalle
     IF ptransacc in ('3314','3313','3228','0260') THEN -- PRESENTADO POR CAMARA Y DEVUELTO
      INSERT INTO sc_contch_hist(empresa, cuenta, numchq, secuencia, sucursal, monto, fecha_alta, hora_alta, folio_suc, transaccion, status, motivo_dev, usuario)
       VALUES(pempresa, pcuenta, pnumcheq, vconsec, psucursal, pmonto, vfecha_hoy, vhora , pfolio_suc, ptransacc, "N", pcodigo, pejecutivo);
     ELSE
      INSERT INTO sc_contch_hist(empresa, cuenta, numchq, secuencia, sucursal, monto, fecha_alta, hora_alta, folio_suc, transaccion, status, motivo_dev, usuario)
       VALUES(pempresa, pcuenta, pnumcheq, vconsec, psucursal, pmonto, vfecha_hoy, vhora , pfolio_suc, ptransacc, "U", pcodigo, pejecutivo);
     IF vt_estado = "A" or vt_estado = "U" THEN
       UPDATE sc_contch SET estado = "U", fecha_alta = vfecha_hoy, importe = pmonto
        WHERE empresa = pempresa
          AND cuenta = pcuenta
          AND numero = pnumcheq;
     END IF  
     END IF	 
   END IF

   LET vcodret = "000";
   RETURN vcodret;
end
END procedure;

CREATE PROCEDURE "informix".sp_geninfsociodemo(pempresa CHAR(3))

RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vdesccodret      CHAR(50);
    DEFINE vsqlerr          INTEGER;
    DEFINE visamerr         INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfechahoy        DATE; 
    DEFINE vmincta          CHAR(20);
    DEFINE vmaxcta          CHAR(20);
    DEFINE vfecha           CHAR(8);
    DEFINE vsql             CHAR(500);
    
    DEFINE vnumcte          CHAR(20);
    DEFINE vsucursal	    CHAR(4);
    DEFINE vproducto	    CHAR(4);
    DEFINE vcuenta          CHAR(20);
    DEFINE vsexo	  	    CHAR(1);
    DEFINE vedocivil		CHAR(2);
    DEFINE vfecha_nac       DATE;
    DEFINE vsdo_dia_ant     DECIMAL(14,2);
    DEFINE vfecha_alta      DATE;
    DEFINE vfechultimomov   DATE;
    
    LET vcodret1        = "000";
    LET vcodret2        = "000";
    LET vdesccodret     = " ";
    LET vsqlerr         = 0;
    LET visamerr        = 0;
    LET vcomienza       = -1;
    LET vcontador1      = 0;
    LET vcontador2      = 0;
    LET vcontador3      = 0;
    LET ven_transacc    = 0; 
    
    LET vfechahoy        = "";
    LET vmincta          = '';
    LET vmaxcta          = '';
    LET vfecha           = '';
    LET vsql             = '';
    
    LET vnumcte         = "";
    LET vcuenta         = "";
    LET vsucursal       = "";
    LET vproducto       = "";
    LET vedocivil       = "";
    LET vsexo           = "";
    LET vfecha_nac      = '';
    LET vsdo_dia_ant    = 0;
    LET vfecha_alta     = '';
    LET vfechultimomov  = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, visamerr
        SET debug file to "/resplogifx/conciliachq/sp_geninfsociodemo.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret1 = vsqlerr;
            LET vcodret2 = visamerr;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vdesccodret, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET debug file to "/resplogifx/conciliachq/sp_geninfsociodemo.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vfechahoy
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum > 0 AND tabname = 'sc_infsociodemocap') THEN
        DROP TABLE bdicheq:"informix".sc_infsociodemocap;        
    END IF;
    
    CREATE RAW TABLE "informix".sc_infsociodemocap
        (
            numcte       CHAR(20)     NOT NULL, 
            sucursal     CHAR(4)      NOT NULL, 
            producto     CHAR(4)      NOT NULL, 
            cuenta       CHAR(20)     NOT NULL, 
            sdo_fin_mes  MONEY(18,2)  NOT NULL, 
            fecha_alta   DATE         NOT NULL, 
            fech_ult_mov DATE, 
            sexo         CHAR(1), 
            edocivil     CHAR(1), 
            fecha_nac    DATE 
        )
    EXTENT SIZE 351562 NEXT SIZE 35156 LOCK MODE ROW;
    CREATE INDEX "informix".idx_socdemcap ON "informix".sc_infsociodemocap(numcte) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE sc_infsociodemocap;
    
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vmincta, vmaxcta
      FROM sc_maechq;
    
    /* -- CLIENTES -- */
    FOREACH WITH HOLD
        SELECT UNIQUE num_cte
          INTO vnumcte
          FROM bdicheq:sc_maechq
         WHERE empresa = pempresa 
           AND cuenta BETWEEN vmincta AND vmaxcta
           AND status_cta <> '2' 
        
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        /* -- Obtiene los datos socioeconomicos del cliente -- */
        SELECT sexo, estado_civil, fecha_nac
          INTO vsexo, vedocivil, vfecha_nac
          FROM bdinteg:si_ctepf
         WHERE numcte = vnumcte;
           
        /* -- CUENTAS -- */
        FOREACH 
            SELECT mae.sucursal, mae.producto, mae.cuenta, mae.fec_ult_mov, mae.sdo_dia_ant, noc.fecha_alta 
              INTO vsucursal, vproducto, vcuenta, vfechultimomov, vsdo_dia_ant, vfecha_alta 
              FROM bdicheq:sc_maechq mae,
                   bdicheq:sc_maenoc noc
             WHERE mae.num_cte = vnumcte
               AND mae.status_cta <> '2'
               AND noc.empresa = mae.empresa
               AND noc.cuenta = mae.cuenta       

            -- // Inserta datos en tabla sc_infsociodemocap
            INSERT INTO sc_infsociodemocap 
            ( numcte, sucursal, producto, cuenta, sdo_fin_mes, fecha_alta, fech_ult_mov, sexo, edocivil, fecha_nac ) 
            VALUES 
            ( vnumcte, vsucursal, vproducto, vcuenta, vsdo_dia_ant, vfecha_alta, vfechultimomov, vsexo, vedocivil, vfecha_nac );
              
            LET vcontador2 = vcontador2 + 1;
            LET vcontador3 = vcontador3 + 1;
            
            LET vsucursal       = "";
            LET vproducto       = "";
            LET vcuenta	        = "";
            LET vsdo_dia_ant    = 0;
            LET vfecha_alta     = "";
            LET vfechultimomov  = '';
        END FOREACH;
        
        /* -- PAGARES -- */
        FOREACH 
            SELECT mae.sucursal, mae.cod_instrum, mae.cuenta, mae.fec_ult_mov, mae.capital, mae.fecha_alta 
              INTO vsucursal, vproducto, vcuenta, vfechultimomov, vsdo_dia_ant, vfecha_alta 
              FROM bdinvers:sv_maeinv mae
             WHERE mae.num_cte = vnumcte
               AND mae.status_cta = '1'      

            /* -- Inserta datos en tabla sc_infsociodemocap -- */
            INSERT INTO sc_infsociodemocap 
            ( numcte, sucursal, producto, cuenta, sdo_fin_mes, fecha_alta, fech_ult_mov, sexo, edocivil, fecha_nac ) 
            VALUES 
            ( vnumcte, vsucursal, vproducto, vcuenta, vsdo_dia_ant, vfecha_alta, vfechultimomov, vsexo, vedocivil, vfecha_nac );
              
            LET vcontador2 = vcontador2 + 1;
            LET vcontador3 = vcontador3 + 1;
            
            LET vsucursal       = "";
            LET vproducto       = "";
            LET vcuenta	        = "";
            LET vsdo_dia_ant    = 0;
            LET vfecha_alta     = "";
            LET vfechultimomov  = '';
        END FOREACH;
        
        LET vcontador1 = vcontador1 + 1;
        
        IF vcontador3 >= 7500 THEN
            LET vcontador3 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vnumcte         = "";
        LET vsexo           = "";
        LET vedocivil       = "";
        LET vfecha_nac      = "";
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    UPDATE STATISTICS MEDIUM FOR TABLE sc_infsociodemocap;
    
    LET vfecha = TO_CHAR(vfechahoy, '%d%m%Y');
    
    LET vsql = '';
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/infosociodemograficacaptacion_'||vfecha||'.txt'||
               ' SELECT numcte, sucursal, producto, cuenta, sdo_fin_mes, fecha_alta, fech_ult_mov, sexo, edocivil, fecha_nac'||
               ' FROM sc_infsociodemocap ORDER BY numcte;" > /resplogifx/conciliachq/infsociodemocap.sql';
    SYSTEM vsql;
    LET vsql = '';
    --- LET vsql = "dbaccess bdicheq /resplogifx/conciliachq/infsociodemocap.sql"; 
    LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/infsociodemocap.sql"; 
    SYSTEM vsql;
    LET vsql = '';
    
    LET vdesccodret = "EL PROCESO SE REALIZO SATISFACTORIAMENTE";
    
    RETURN vcodret1, vcodret2, vdesccodret, vcontador1, vcontador2;
    
    END;

END PROCEDURE;

