CREATE PROCEDURE "informix".corrige_prov_28022011(pempresa CHAR(3))
    
    RETURNING CHAR(5), CHAR(5), INTEGER;
    
    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vsql             CHAR(200);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(14,2);    
    DEFINE vtransacc        CHAR(4);
    DEFINE vdescripcion     CHAR(40);
    DEFINE vsucursal        CHAR(4);  
    
    LET vcodret	     = '000';
    LET vcodret2     = '000';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET vcontador    = -1;
    LET ven_transacc = 0;
    
    LET vsql         = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vcuenta      = '';
    LET vmonto       = 0.00;
    LET vtransacc    = '';
    LET vdescripcion = '';
    LET vsucursal    = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_prov_28022011.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret, vcodret2, vcontador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_prov_28022011.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum > 0 AND tabname = 'ctasxcorregir') THEN
        DROP TABLE "informix".ctasxcorregir;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxcorregir
      (
        cuenta      char(20)    not null,
        monto       money(14,2) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctasxcorr ON "informix".ctasxcorregir(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/ints_28022011.unl INSERT INTO ctasxcorregir" > /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    LET vsql = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasxcorreg.sql';
    --- LET vsql = 'dbaccess bdicheq /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxcorregir;
    
    FOREACH WITH HOLD
        SELECT cuenta, monto
          INTO vcuenta, vmonto
          FROM ctasxcorregir
        
        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
            LET ven_transacc = 1;
        END IF;
        
        UPDATE sc_sdodiarioc
           SET intprovnp28 = vmonto
         WHERE cuenta = vcuenta
           AND aniomes = '201102';
        
        LET vcontador = vcontador + 1;
        
        LET vcuenta = '';
        LET vmonto  = 0.00;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret, vcodret2, vcontador;

END PROCEDURE;

CREATE PROCEDURE "informix".pasamovshisttemp(pempresa CHAR(3))

RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcuantos         INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfecha           DATE;
    DEFINE vfecha2          CHAR(10);
    DEFINE vexiste          SMALLINT;
    DEFINE vexistefin       SMALLINT;
    DEFINE vmin_cta         CHAR(20);
    DEFINE vmax_cta         CHAR(20);
    DEFINE vcuenta          CHAR(20);
    DEFINE vsql             char(600);
    DEFINE vstmt            char(250);
    
    LET vcodret1        = '000';
    LET vcodret2        = '000';
    LET sql_err	        = 0;
    LET isam_err        = 0;
    LET vcomienza       = -1;
    LET vcontador1      = 0;
    LET vcontador2      = 0;
    LET vcuantos        = 0;
    LET ven_transacc    = 0; 
    
    LET vfecha          = ''; 
    LET vfecha2         = '';
    LET vexiste         = 0;
    LET vexistefin      = 0;
    LET vmin_cta        = '';
    LET vmax_cta        = '';
    LET vcuenta         = ''; 
    LET vsql            = '';
    LET vstmt           = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshisttemp.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            
            LET vsql = 'echo "UPDATE {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||'informix'||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT {+INDEX(bdicheq:sc:fechas idx_fechas1)} CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas where empresa = "001") '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||'PasaMovsHistTemp'||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||'01'||''';" > /tmp/horaspasamovstmp.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovstmp.sql';
            SYSTEM vstmt;
            
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;

    -- SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshisttemp.out";
    -- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT {+INDEX(sc_param idx_param1 )} valor 
      INTO vfecha
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PasoMovhis_MovhisTmp';
     
    -- // Guarda inicio de proceso     
    SELECT {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} COUNT(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'PasaMovsHistTemp'
       AND fecha   = vfecha
       AND sistema = '01';

    IF vexiste = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||'PasaMovsHistTemp'||''', '''||vfecha||''', '''||'01'||''', '''||'I'||''', '''||'informix'||''','||
                   '(SELECT {+INDEX(bdicheq:sc:fechas idx_fechas1)} CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas where empresa = "001"), NULL, NULL);" > /tmp/horaspasamovstmp.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovstmp.sql';
        SYSTEM vstmt;
    ELSE
        SELECT {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} COUNT(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = 'PasaMovsHistTemp'
           AND fecha   = vfecha
           AND sistema = '01'
           AND (status_proc = "F" OR codret = '958');
    
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||'informix'||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT {+INDEX(bdicheq:sc:fechas idx_fechas1)} CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas where empresa = "001") '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||'PasaMovsHistTemp'||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||'01'||''';" > /tmp/horaspasamovstmp.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovstmp.sql';
            SYSTEM vstmt;
        ELSE
            LET vcodret1 = "958";
            
            LET vsql = 'echo "UPDATE {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||'informix'||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT {+INDEX(bdicheq:sc:fechas idx_fechas1)} CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas where empresa = "001") '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||'PasaMovsHistTemp'||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||'01'||''';" > /tmp/horaspasamovstmp.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovstmp.sql';
            SYSTEM vstmt;
            
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END IF;
    
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vmin_cta, vmax_cta
      FROM sc_movhis;
      
    SELECT 
           COUNT(*)
      INTO vcontador1
      FROM sc_movhis
     WHERE fech_alt = vfecha; 
       
    FOREACH WITH HOLD 
        SELECT 
               UNIQUE cuenta
          INTO vcuenta
          FROM sc_movhis
         WHERE fech_alt = vfecha
           AND producto NOT IN('1200','1600','9900','9901')
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        INSERT INTO sc_movhis_temp
        SELECT {+INDEX(sc_movhis idx_movhisnew1)} mov.*
          FROM sc_movhis mov
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.fech_alt = vfecha;
           
        LET vcontador2 = vcontador2 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        LET vcomienza = -1;
        COMMIT WORK;
    END IF;
    
    FOREACH WITH HOLD 
        SELECT 
               UNIQUE cuenta
          INTO vcuenta
          FROM sc_movhis
         WHERE fech_alt = vfecha
           AND producto IN('1200','1600','9900','9901')
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        INSERT INTO sc_movhis_temp
        SELECT {+INDEX(sc_movhis idx_movhisnew1)} mov.*
          FROM sc_movhis mov
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.fech_alt = vfecha;
           
        LET vcontador2 = vcontador2 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    LET vfecha2 = TO_CHAR(vfecha + 1 UNITS DAY, '%m/%d/%Y');
    
    IF vcodret1 = '000' THEN
        UPDATE {+INDEX(sc_param idx_param1)} sc_param
           SET valor = vfecha2
         WHERE empresa = '001'
           AND codparam = 'PasoMovhis_MovhisTmp';
           
        LET vsql = 'echo "UPDATE {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||'informix'||''','||
                   'status_proc   = '''||'F'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT {+INDEX(bdicheq:sc:fechas idx_fechas1)} CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas where empresa = "001") '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||'PasaMovsHistTemp'||''' '||
                   'AND fecha     = '''||vfecha||''' '||
                   'AND sistema   = '''||'01'||''';" > /tmp/horaspasamovstmp.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovstmp.sql';
        SYSTEM vstmt;
    ELSE
    
        LET vsql = 'echo "UPDATE {+INDEX(bdinteg:sx_contproc idx_xcontproc1)} bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||'informix'||''','||
                   'status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT {+INDEX(bdicheq:sc:fechas idx_fechas1)} CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas where empresa = "001") '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||'PasaMovsHistTemp'||''' '||
                   'AND fecha     = '''||vfecha||''' '||
                   'AND sistema   = '''||'01'||''';" > /tmp/horaspasamovstmp.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovstmp.sql';
        SYSTEM vstmt;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_proac_traectasexistecte(pCuenta CHAR(11),pNum_Cte CHAR(9),pTarjeta CHAR (20),pRegistro smallint)
Returning CHAR(5),CHAR(20),CHAR(40),CHAR(10),CHAR(10),CHAR(1),CHAR(50),CHAR(50),CHAR(50),CHAR(50),CHAR (20),CHAR(10);
--cuenta,tipo de cuenta,fecha de inscripcion,fecha de cancelacion y status

DEFINE vcodret 						CHAR(5);
DEFINE vsqlerr,iExiste,iCteBusq		INTEGER;
DEFINE cCta_Eje 					CHAR(20);
DEFINE cProducto					CHAR(15);
DEFINE cDescripProd					CHAR(100);
DEFINE cNCuentas					CHAR(10);
DEFINE cStatus_cta					CHAR(1);
DEFINE cApell_Paterno,cApell_Materno CHAR(50);
DEFINE cNombres,cRfc 				 CHAR(50);
DEFINE iCiclo				 		INTEGER;
DEFINE iNCuentas 					Smallint;
DEFINE dFecha_alta,dFecha_canc		DATE;
DEFINE iLongitudCliente             Smallint;


BEGIN
    ON EXCEPTION SET vsqlerr
      IF vsqlerr <> 0 THEN
        let vcodret = vsqlerr;
        Return vcodret,cCta_Eje,cDescripProd,dFecha_alta,dFecha_canc,cStatus_cta,
		cApell_Paterno,cApell_Materno,cNombres,cRfc,pNum_Cte,cNCuentas With Resume;
      END IF;
	END EXCEPTION;

   --SET DEBUG FILE TO "/tmp/sp_PROAC_TraeCuentasExistentes.out";
   --TRACE ON;

	LET vcodret = "00000";
	LET cCta_Eje = "";
	LET cProducto = "";
	LET iExiste = 0;
	LET dFecha_alta = "01/01/1950";
	LET dFecha_canc = "01/01/1950";
	LET cStatus_cta = "";
	LET cDescripProd = "";
	LET cApell_Paterno = "";
	LET cApell_Materno = "";
	LET cNombres = "";
	LET iCteBusq = 0;
	LET cRfc = "";
	let iCiclo = 0;
	LET iNCuentas = 0;
	LET cNCuentas = "0";
    LET iLongitudCliente = 0;
	

	--Obtengo el valor longitud del numero de cliente		
	SELECT Trim(valor)
	INTO iLongitudCliente 
	FROM bdinteg:si_param 
	WHERE empresa = '001' 
	AND descripcion = ('longitud cliente'); 
	--Se formatea el # de cliente por si envian cadena incompleta
	Let pNum_Cte = lpad(Trim(pNum_Cte),iLongitudCliente,'0');        

	
	-- Consulta por Tarjeta 
	IF Not pTarjeta = "" Then
		Select {+INDEX(sc_tarjeta ix_tarjeta2)} 
		cuenta
		Into pCuenta
		From sc_tarjeta
		Where  empresa = '001' and num_tarjeta = pTarjeta;
	End If;
	
	-- Consulta por Cuenta 	
	IF NOT TRIM(pCuenta) = '' THEN
		
		IF EXISTS (Select 1 FROM bdicheq:sc_maechq WHERE empresa = '001' AND cuenta = pCuenta AND status_cta <> '2') THEN
			
			Select cuenta,'PROAC_'||trim(producto),num_cte Into cCta_Eje, cProducto, pNum_Cte
			From sc_maechq WHERE empresa = '001' AND cuenta = pCuenta 	AND status_cta <> '2';
		ELSE
			LET vcodret = '08308';
			Return vcodret,NVL(cCta_Eje,""),NVL(cDescripProd,""),NVL(dFecha_alta,""),NVL(dFecha_canc,""),NVL(cStatus_cta,"")
			,NVL(cApell_Paterno,""),NVL(cApell_Materno,""),NVL(cNombres,""),NVL(cRfc,""),pNum_Cte,NVL(iCiclo,0) ;
		End If;
	END IF;
	-- Fin Consulta por Cuenta 

	IF iCteBusq = 0 THEN
		LET iCteBusq = 1;
		Select  trim(apell_paterno),trim(apell_materno),trim(nombre1) || ' ' || trim(nombre2) ,rfc
		Into cApell_Paterno,cApell_Materno,cNombres,cRfc
		From bdinteg:si_cliente
		Where numcte = pNum_Cte;
	End IF;
	
  -- TRAE CUENTAS POSIBLES A INSCRIPCIÃ? PROAC POR CLIENTE 
  ForEach
	 Select cuenta,'PROAC_'||trim(producto) Into cCta_Eje,cProducto
     From sc_maechq
     Where num_cte = pNum_Cte
     AND cuenta = (case when pCuenta = "" then cuenta else cCta_Eje END)
	 And status_cta <> '2'
	

	Select count(cta_eje) into iNCuentas
	FROM sc_proac
	Where cta_eje = cCta_Eje;
	LET cNCuentas = iNCuentas;

	Select 1 Into iExiste
	From sc_param
	Where codparam = trim(cProducto);
	LET cProducto = trim(cProducto);

	If iExiste = 1 THEN
		LET iExiste = 0;

		Select nombre Into cDescripProd
		From sc_producto
		Where producto = substr(cProducto,7,4);

		If cProducto Is Null THEN
		Continue ForEach;
		End IF;

		Select fecha_alta,fecha_canc,status_cta
		Into dFecha_alta,dFecha_canc,cStatus_cta
		from sc_proac
		Where cta_eje = cCta_Eje
		And secuencia = (Select Max(secuencia) From sc_proac Where cta_eje = cCta_Eje);
		LET iExiste = 1;
		LET iCiclo = iCiclo + 1;
		IF iCiclo <= pRegistro THEN
			-- PAGINACION
			CONTINUE FOREACH;
		END IF;
		Return vcodret,NVL(cCta_Eje,""),NVL(cDescripProd,""),NVL(dFecha_alta,""),NVL(dFecha_canc,""),NVL(cStatus_cta,"")
					  ,NVL(cApell_Paterno,""),NVL(cApell_Materno,""),NVL(cNombres,""),NVL(cRfc,""),pNum_Cte,cNCuentas With Resume;
	Else
		If iExiste = 0 or iExiste Is Null THEN
			Continue ForEach;
		End IF;
	End If;
	
	LET cProducto = "";
	LET cDescripProd = "";
  End ForEach
  
  -- TRAE CUENTAS NO EXISTENTES AL PROAC PERO INSCRITAS POR CLIENTE 
  ForEach
	Select cta_eje Into cCta_Eje
	From sc_proac
	Where status_cta = '1'
	And num_cte = pNum_Cte

	Select 'PROAC_'||trim(producto) Into cProducto
	From sc_maechq
	where empresa = '001'
	And cuenta = cCta_eje;

	Select 1 into iExiste
	From sc_fechas
	Where trim(cProducto) not in (select  codparam from sc_param Where substr(codparam,1,6) = 'PROAC_');
	LET cProducto = trim(cProducto);

	Select count(cta_eje) into iNCuentas
	FROM sc_proac
	Where cta_eje = cCta_Eje;
	LET cNCuentas = iNCuentas;


	If iExiste = 1 THEN
		LET iExiste = 0;

		Select nombre Into cDescripProd
		From sc_producto
		Where producto = substr(cProducto,7,4);

		If cProducto Is Null THEN
				Continue ForEach;
		End IF;

		Select fecha_alta,fecha_canc,status_cta
		Into dFecha_alta,dFecha_canc,cStatus_cta
		from sc_proac
		Where cta_eje = cCta_Eje
		And status_cta = '1';
		LET iCiclo = iCiclo + 1;
		IF iCiclo <= pRegistro THEN
				-- PAGINACION
				CONTINUE FOREACH;
		END IF;
		Return vcodret,NVL(cCta_Eje,""),NVL(cDescripProd,""),NVL(dFecha_alta,""),NVL(dFecha_canc,""),NVL(cStatus_cta,"")
				  ,NVL(cApell_Paterno,""),NVL(cApell_Materno,""),NVL(cNombres,""),NVL(cRfc,""),pNum_Cte,cNCuentas With Resume;
	Else
	
		If iExiste = 0 or iExiste Is Null THEN
			Continue ForEach;
		End IF;
	End If;
		LET cProducto = "";
		LET cDescripProd = "";
	End ForEach

END
END PROCEDURE
DOCUMENT
    'AUTOR		: Jesus Antonio Bastidas Lopez',
	'DESCRIPCION: Calcular La fecha que recibe de parametro un aÃ±Ã¡considerando el aÃ±isiesto',
					'Y da la fecha_hoy y la fecha proximo aÃ±n el formato 01 de enero de 2009',
	'FECHA		: Febrero 2009',
	'VERSION	: 200902',
    'BD			: BDICHEQ',
	'Modificion : Armando Mercado F',
	'DESCRIPCION: Se modifico para obtener la longitud del num. cte. y formatear el numero de cliente',
	'FECHA		: Julio 2009',
	'VERSION	: 20090716',
	'BD         : BDICHEQ',
	'Modificion : Martin Eduardo Mirada',
	'DESCRIPCION: Se modifico para que no regrese las cuentas con status cancelada y que no puedan ser aperturadas o ligadas',
	'FECHA		: Febrero 2011',
	'VERSION	: 20110209',
    'BD			: BDICHEQ',    
	'Modificion : Martin Eduardo Mirada',
	'DESCRIPCION: Se modifico para que cuando se consulte por No. de Cuenta o No. de Tarjeta solo debe regresar la cuenta consultada',
	'FECHA		: Febrero 2011',
	'VERSION	: 20110215',
    'BD			: BDICHEQ';

CREATE PROCEDURE "informix".sp_marcafecharetiro( pempresa char(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;
    
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    
    DEFINE vcomienza        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    
    DEFINE vfechconmovhis           CHAR(10);
    DEFINE vfechconmovhisold        CHAR(10);
    DEFINE vfechconmovhisold2       CHAR(10);
    DEFINE vfechconmovhisold3       CHAR(10);
    DEFINE vctamin                  CHAR(20);
    DEFINE vctamax                  CHAR(20);
    DEFINE vcuenta                  CHAR(20);
    DEFINE vfecha_ultima_transacc   DATE;
    
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    
    LET vcomienza    = -1;
    LET ven_transacc = 0;
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    
    LET vfechconmovhis         = '';
    LET vfechconmovhisold      = '';
    LET vfechconmovhisold2     = '';
    LET vfechconmovhisold3     = '';
    LET vctamin                = '';
    LET vctamax                = '';
    LET vcuenta                = '';                    
    LET vfecha_ultima_transacc = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_marcafecharetiro.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_marcafecharetiro.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT valor 
      INTO vfechconmovhis
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'fechcon_movhis';
       
    SELECT valor 
      INTO vfechconmovhisold
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechIniCon_movhis_ol';
       
    SELECT valor 
      INTO vfechconmovhisold2
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechaIniMovhisOld2';
       
    SELECT valor 
      INTO vfechconmovhisold3
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechaIniMovhisOld3';
       
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vctamin, vctamax
      FROM sc_maechq;    
    
    FOREACH WITH HOLD
        SELECT cuenta
          INTO vcuenta
          FROM sc_maechq
         WHERE empresa = pempresa
           AND cuenta BETWEEN vctamin AND vctamax
           AND status_cta <> '2'
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET ven_transacc = 1;
        END IF;
        
        SELECT MAX(mov.fech_alt)
          INTO vfecha_ultima_transacc
          FROM sc_movdia mov,
               bdinteg:si_transacc trx
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.cancelad <> 'S'
           AND mov.transacc NOT IN('3381','3382','3276','3277','3353','3354','3280')
           AND trx.numero = mov.transacc
           AND trx.naturaleza = 'C';
           
        IF vfecha_ultima_transacc is null THEN
        
            SELECT {+INDEX(sc_movhis idx_movhisnew4)}
                   MAX(mov.fech_alt)
              INTO vfecha_ultima_transacc
              FROM sc_movhis mov,
                   bdinteg:si_transacc trx
             WHERE mov.empresa = pempresa
               AND mov.cuenta = vcuenta
               AND mov.fech_alt >= vfechconmovhis
               AND mov.cancelad <> 'S'
               AND mov.transacc NOT IN('3381','3382','3276','3277','3353','3354','3280')
               AND trx.numero = mov.transacc
               AND trx.naturaleza = 'C';
               
            IF vfecha_ultima_transacc is null THEN
            
                SELECT {+INDEX(sc_movhis_old movhis1)}
                       MAX(mov.fech_alt)
                  INTO vfecha_ultima_transacc
                  FROM sc_movhis_old mov,
                       bdinteg:si_transacc trx
                 WHERE mov.empresa = pempresa
                   AND mov.cuenta = vcuenta
                   AND mov.fech_alt >= vfechconmovhisold
                   AND mov.fech_alt < vfechconmovhis
                   AND mov.cancelad <> 'S'
                   AND mov.transacc NOT IN('3381','3382','3276','3277','3353','3354','3280')
                   AND trx.numero = mov.transacc
                   AND trx.naturaleza = 'C';
                   
                IF vfecha_ultima_transacc is null THEN
                
                    SELECT {+INDEX(sc_movhis_old2 movhis1_old2)}
                           MAX(mov.fech_alt)
                      INTO vfecha_ultima_transacc
                      FROM sc_movhis_old2 mov,
                           bdinteg:si_transacc trx
                     WHERE mov.empresa = pempresa
                       AND mov.cuenta = vcuenta
                       AND mov.fech_alt >= vfechconmovhisold2
                       AND mov.fech_alt < vfechconmovhisold
                       AND mov.cancelad <> 'S'
                       AND mov.transacc NOT IN('3381','3382','3276','3277','3353','3354','3280')
                       AND trx.numero = mov.transacc
                       AND trx.naturaleza = 'C';
                       
                    IF vfecha_ultima_transacc is null THEN
                
                        SELECT {+INDEX(sc_movhis_old3 movhis1_old3)}
                               MAX(mov.fech_alt)
                          INTO vfecha_ultima_transacc
                          FROM sc_movhis_old3 mov,
                               bdinteg:si_transacc trx
                         WHERE mov.empresa = pempresa
                           AND mov.cuenta = vcuenta
                           AND mov.fech_alt >= vfechconmovhisold3
                           AND mov.fech_alt < vfechconmovhisold2
                           AND mov.cancelad <> 'S'
                           AND mov.transacc NOT IN('3381','3382','3276','3277','3353','3354','3280')
                           AND trx.numero = mov.transacc
                           AND trx.naturaleza = 'C';
                           
                        IF vfecha_ultima_transacc is null THEN
                            
                            SELECT {+INDEX(sc_movhis_old4 movhis1_old4)}
                                   MAX(mov.fech_alt)
                              INTO vfecha_ultima_transacc
                              FROM sc_movhis_old4 mov,
                                   bdinteg:si_transacc trx
                             WHERE mov.empresa = pempresa
                               AND mov.cuenta = vcuenta
                               AND mov.fech_alt < vfechconmovhisold3
                               AND mov.cancelad <> 'S'
                               AND mov.transacc NOT IN('3381','3382','3276','3277','3353','3354','3280')
                               AND trx.numero = mov.transacc
                               AND trx.naturaleza = 'C';
                            
                        END IF;
             
                    END IF;
                    
                END IF;
                
            END IF;
            
        END IF;
        
        IF vfecha_ultima_transacc is not null OR vfecha_ultima_transacc <> '' THEN
            UPDATE sc_maechq
               SET fecultret = vfecha_ultima_transacc
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;

        IF vcontador2 >= 7500 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vcuenta = '';
        LET vfecha_ultima_transacc = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_marcactasinactivas3( pempresa char(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;
    
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    
    DEFINE vcomienza        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    
    DEFINE vFecha_Hoy       DATE;
    DEFINE vfecha_ant       DATE;
    DEFINE vctamin          CHAR(20);
    DEFINE vctamax          CHAR(20);
    DEFINE vcuenta          CHAR(20);
    DEFINE vfecultdep       DATE;
    DEFINE vfecultret       DATE;
    DEFINE vfecha_alta      DATE;
    DEFINE vDias_Inact      INTEGER;
    DEFINE vsdo_actual      DECIMAL(18,2);
    
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    
    LET vcomienza    = -1;
    LET ven_transacc = 0;
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    
    LET vFecha_Hoy  = '';
    LET vfecha_ant  = '';
    LET vctamin     = '';
    LET vctamax     = '';
    LET vcuenta     = '';                    
    LET vfecultdep  = '';
    LET vfecultret  = '';
    LET vfecha_alta = '';
    LET vDias_Inact = 0;
    LET vsdo_actual = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_marcactasinactivas3.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador3;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_marcactasinactivas3.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy, fecha_ant
      INTO vFecha_Hoy, vfecha_ant
      FROM sc_fechas
     WHERE empresa = pEmpresa;
     
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vCtaMin, vCtaMax
      FROM sc_maechq;  

    SELECT valor
      INTO vDias_Inact
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'InactividadCtaGlobal';
    
    FOREACH WITH HOLD
        SELECT mae.cuenta, mae.fecultdep, mae.fecultret, mae.sdo_actual, noc.fecha_alta
          INTO vcuenta, vfecultdep, vfecultret, vsdo_actual, vfecha_alta
          FROM sc_maechq mae,
               sc_maenoc noc
         WHERE mae.empresa = pempresa
           AND mae.cuenta BETWEEN vctamin AND vctamax
           AND mae.status_cta = '4'
           AND (((vFecha_Hoy - mae.fecultdep) > vDias_Inact) OR ((vFecha_Hoy - mae.fecultret) > vDias_Inact) OR (fecultdep is null OR fecultdep = '') OR (fecultret is null OR fecultret = '' ))
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET ven_transacc = 1;
        END IF;
        
        IF vfecultdep is null OR vfecultdep = '' THEN
            LET vfecultdep = vfecha_alta;
        END IF;
        
        IF vfecultret is null OR vfecultret = '' THEN
            LET vfecultret = vfecha_alta;
        END IF;
        
        IF ((vFecha_Hoy - vfecultdep) > vDias_Inact) AND ((vFecha_Hoy - vfecultret) > vDias_Inact) THEN
            UPDATE sc_maechq
               SET status_cta = '5'
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
               
            LET vcontador3 = vcontador3 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;

        COMMIT WORK;
        BEGIN WORK;
        
        LET vcuenta = '';
        LET vfecultdep = '';
        LET vfecultret = '';
        LET vfecha_alta = '';
        LET vsdo_actual = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;
    
    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador3;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_desmarcactasinactivas3( pempresa char(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;
    
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    
    DEFINE vcomienza        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    
    DEFINE vFecha_Hoy       DATE;
    DEFINE vfecha_ant       DATE;
    DEFINE vcuenta          CHAR(20);
    DEFINE vsdo_actual      DECIMAL(18,2);
    
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    
    LET vcomienza    = -1;
    LET ven_transacc = 0;
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    
    LET vFecha_Hoy  = '';
    LET vfecha_ant  = '';
    LET vcuenta     = '';  
    LET vsdo_actual = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_desmarcactasinactivas3.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador3;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_desmarcactasinactivas3.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy, fecha_ant
      INTO vFecha_Hoy, vfecha_ant
      FROM sc_fechas
     WHERE empresa = pEmpresa;
     
    FOREACH WITH HOLD
        SELECT mae.cuenta, mae.sdo_actual
          INTO vcuenta, vsdo_actual
          FROM sc_maechq mae
         WHERE mae.status_cta = '5'
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET ven_transacc = 1;
        END IF;
        
        IF vsdo_actual > 0.00 THEN
            UPDATE sc_maechq
               SET status_cta = '4',
                   fecha_proceso = vFecha_Hoy
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
            
            LET vcontador3 = vcontador3 + 1;
        ELSE
            UPDATE sc_maechq
               SET status_cta = '4'
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
               
            LET vcontador3 = vcontador3 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;

        COMMIT WORK;
        BEGIN WORK;
        
        LET vcuenta = '';
        LET vsdo_actual = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;
    
    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador3;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_bloqueosmasivos(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(40);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(40);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfecha_hoy       DATE;
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vusuario         CHAR(8);
    DEFINE vfecha           CHAR(13);
    
    DEFINE vcuenta          CHAR(20);
    DEFINE vstatus          CHAR(1);
    DEFINE vclave_bloq      CHAR(2);
    DEFINE vopcion_bloq     INTEGER;
    DEFINE vcve_area        CHAR(2);
    DEFINE vcod_area        CHAR(1);
    DEFINE vcve_tipobloq    CHAR(2);
    DEFINE vcod_tipobloq    CHAR(1);
    DEFINE vmonto           MONEY(18,2);    
    DEFINE vusuariobloq     CHAR(8);
    DEFINE vcodret_bloqueo  CHAR(5);
    DEFINE vclave_bloqueo   CHAR(5);
    DEFINE vdescripcion     CHAR(40);
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET vcodret3      = 'PROCESO TERMINADO SATISFACTORIAMENTE';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET desc_err      = '';
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcomienza     = -1;
    LET ven_transacc  = 0;
    
    LET vfecha_hoy   = '';
    LET vsql         = '';
    LET vstmt        = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vusuario     = 'informix';
    LET vfecha       = '';
    
    LET vcuenta         = '';
    LET vstatus         = '';
    LET vclave_bloq     = '';
    LET vopcion_bloq    = 0;
    LET vcve_area       = '';
    LET vcod_area       = '';
    LET vcve_tipobloq   = '';
    LET vcod_tipobloq   = '';
    LET vmonto          = 0.00;
    LET vusuariobloq    = '';
    LET vcodret_bloqueo = '';
    LET vclave_bloqueo  = '';
    LET vdescripcion    = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_bloqueosmasivos.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_bloqueosmasivos.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    -- // TABLA DE CUENTAS POR BLOQUEAR
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxbloquear') THEN
        DROP TABLE "informix".ctasxbloquear;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxbloquear
      (
        cuenta          char(20)    not null,
        clave           char(2)     not null,
        opcion          integer     not null,
        cve_area        char(2)     not null,
        cod_area        char(1)     not null,
        cve_tipobloq    char(2)     not null,
        cod_tipobloq    char(1)     not null,
        monto           money(18,2),
        usuario         char(8)     not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctaxbloq ON "informix".ctasxbloquear(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/ctasxbloquear.unl DELIMITER ''","'' INSERT INTO ctasxbloquear" > /resplogifx/conciliachq/ctasbloq.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasbloq.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxbloquear;
    
    -- // TABLA DE REPORTE DE CUENTAS POR BLOQUEAR
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'repctasxbloquear') THEN
        DROP TABLE "informix".repctasxbloquear;
    END IF;
    
    CREATE RAW TABLE "informix".repctasxbloquear
      (
        cuenta          char(20)    not null,
        codret          char(5)     not null,
        descripcion     char(40)    
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_repctaxbloq ON "informix".repctasxbloquear(cuenta) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE repctasxbloquear;
    
    LET vhora = CURRENT HOUR TO FRACTION;
    LET vfolio = vusuario||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];
    
    FOREACH WITH HOLD
        SELECT cuenta, clave, opcion, cve_area, cod_area, cve_tipobloq, cod_tipobloq, monto, usuario
          INTO vcuenta, vclave_bloq, vopcion_bloq, vcve_area, vcod_area, vcve_tipobloq, vcod_tipobloq, vmonto, vusuariobloq
          FROM ctasxbloquear
        
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        SELECT status_cta
          INTO vstatus
          FROM sc_maechq
         WHERE empresa = pempresa
           AND cuenta = vcuenta;
           
        IF vstatus in ('1','4') THEN
            
            CALL bloqueo_cta(pempresa, vcuenta, vmonto, vclave_bloq, vopcion_bloq, vfecha_hoy, vusuariobloq, '11111', vcve_area, vcod_area, vcve_tipobloq, vcod_tipobloq)
            RETURNING vcodret_bloqueo, vclave_bloqueo;
            
            IF vcodret_bloqueo = '000' THEN
                LET vdescripcion = 'CUENTA BLOQUEADA SATISFACTORIAMENTE';
                LET vcontador2 = vcontador2 + 1;
            ELSE
                SELECT descripcion
                  INTO vdescripcion
                  FROM bdinteg:si_codret
                 WHERE codigo_retorno = vcodret_bloqueo
                   AND sistema = '01';
            END IF;
        
        ELIF vstatus = '2' THEN
        
            LET vcodret_bloqueo = '200';
            LET vdescripcion = 'CUENTA CANCELADA';
        
        ELIF vstatus = '3' THEN
        
            LET vcodret_bloqueo = '303';
            LET vdescripcion = 'CUENTA BLOQUEADA';
        
        ELIF vstatus is null OR vstatus = '' THEN
        
            LET vcodret_bloqueo = '100';
            LET vdescripcion = 'CUENTA NO EXISTE';
        
        END IF;
        
        INSERT INTO repctasxbloquear VALUES(vcuenta, vcodret_bloqueo, vdescripcion);
        
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vcuenta         = '';
        LET vstatus         = '';
        LET vclave_bloq     = '';
        LET vopcion_bloq    = 0;
        LET vcve_area       = '';
        LET vcod_area       = '';
        LET vcve_tipobloq   = '';
        LET vcod_tipobloq   = '';
        LET vmonto          = 0.00;
        LET vusuariobloq    = '';
        LET vcodret_bloqueo = '';
        LET vclave_bloqueo  = '';
        LET vdescripcion    = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    LET vfecha = TO_CHAR(vfecha_hoy, '%d%m%Y') ||'_'|| vhora[1,2] || vhora[4,5];
    
    -- // GENERA EL ARCHIVO DE TODAS LAS CUENTAS
    LET vsql = '';
    LET vsql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/repctasbloq_'||vfecha||'.txt '||
               ' SELECT * FROM repctasxbloquear ORDER BY cuenta" > /resplogifx/conciliachq/repctasbloq.sql';
    SYSTEM vsql;
    
    LET vstmt = '';
    --- LET vstmt = "dbaccess bdicheq /resplogifx/conciliachq/repctasbloq.sql"; 
    LET vstmt = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/repctasbloq.sql"; 
    SYSTEM vstmt;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtienemontontosctas (pEmpresa CHAR(3),	pCuenta CHAR(20),pTipoConsulta CHAR(1))
RETURNING  CHAR(5),VARCHAR(63),VARCHAR(63),VARCHAR(63);

DEFINE cCodRet 			CHAR(5);
DEFINE iSqlErr			INTEGER;
DEFINE iBandera			INTEGER;
DEFINE cAperturacta		VARCHAR(63);
DEFINE cMantenercta		VARCHAR(63);
DEFINE cMensual			VARCHAR(63);
DEFINE cDepositos		VARCHAR(63);
DEFINE cMontodeposito	VARCHAR(63);
DEFINE cRetiros			VARCHAR(63);
DEFINE cMontoretiro		VARCHAR(63);
DEFINE cNoAplica		VARCHAR(63);

LET cCodRet 			 = '00000';
LET iSqlErr				 = 0;
LET iBandera			 = 0;
LET cAperturacta		 = '';
LET cMantenercta		 = '';
LET cMensual			 = '';
LET cDepositos		 	 = '';
LET cMontodeposito	 	 = '';
LET cRetiros			 = '';
LET cMontoretiro		 = '';
LET cNoAplica		 	 = '';


BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodRet= iSqlErr;
			RETURN cCodRet,cAperturacta,cMantenercta,cMensual;
		END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO "/tmp/Antonio/sp_ObtieneMontontosCtAS.out";
	--TRACE ON;

	set isolation to dirty read;

	IF pEmpresa = '' OR pCuenta = '' OR pTipoConsulta = '' THEN
		LET cCodRet = '00001';
		RETURN cCodRet,cAperturacta,cMantenercta,cMensual;
	END IF;

	IF pTipoConsulta = 'A' THEN

	  	SELECT  1,
				TRIM(d.proced_aperturacta)||' '|| TRIM(n.descripcion) AS aperturacta ,
				TRIM(d.proced_mantenercta)||' '||(n.descripcion) AS mantenercta,
				TRIM(d.monto_mensual)||' '||TRIM(k.descripcion) AS mensual
		INTO iBandera,cAperturacta,cMantenercta,cMensual
	    FROM  bdicheq:sc_maechq d, bdinteg:si_tipo_procedencia n, bdinteg:si_tipo_montomes k
		WHERE d.empresa = pEmpresa
			AND d.cuenta = pCuenta
			AND d.proced_aperturacta=n.procedencia
			AND d.proced_mantenercta=n.procedencia
			AND k.codigo=d.monto_mensual;

		IF iBandera = 0 THEN
			LET cCodRet = '00002';
		END IF;

		RETURN cCodRet,cAperturacta,cMantenercta,cMensual;

	END IF;

	IF pTipoConsulta = 'D' THEN

		SELECT {+INDEX(sc_maechq idx_maechq1), +INDEX(bdinteg:si_tipo_nummov idx_nummov), +INDEX(bdinteg:si_tipo_montomov idx_montomov)} 1,
				TRIM(m.depositos_cantidad)||' '||TRIM(t.descripcion) AS depositos,
				TRIM(m.depositos_monto)||' '||TRIM(r.descripcion)AS montodeposito,
				''
		INTO iBandera,cDepositos,cMontodeposito,cNoAplica
	    FROM bdicheq:sc_maechq m, bdinteg:si_tipo_nummov t, bdinteg:si_tipo_montomov r
	    WHERE m.empresa = pEmpresa
			AND m.cuenta = pCuenta
			AND m.depositos_cantidad = t.codnummo
			AND m.depositos_monto = r.codnummonto;

		IF iBandera = 0 THEN
			LET cCodRet = '00003';
		END IF;

		RETURN cCodRet,cDepositos,cMontodeposito,cNoAplica;

	END IF;

	IF pTipoConsulta = 'R' THEN

		SELECT  {+INDEX(sc_maechq idx_maechq1), +INDEX(bdinteg:si_tipo_nummov idx_nummov), +INDEX(bdinteg:si_tipo_montomov idx_montomov)} 1,
				TRIM(m.retiros_cantidad)||' '||TRIM(t.descripcion) AS retiros,
				TRIM(m.retiros_monto)||' '||TRIM(r.descripcion)AS montoretiro,
				''
		INTO iBandera,cRetiros,cMontoretiro,cNoAplica
		FROM bdicheq:sc_maechq m, bdinteg:si_tipo_nummov t, bdinteg:si_tipo_montomov r
		WHERE m.empresa = pEmpresa AND m.cuenta = pCuenta
			AND m.retiros_cantidad = t.codnummo
			AND m.retiros_monto = r.codnummonto;

		IF iBandera = 0 THEN
			LET cCodRet = '00004';
		END IF;

		RETURN cCodRet,cRetiros,cMontoretiro,cNoAplica;

	END IF;
END
END PROCEDURE
