              FROM sc_maechq
             WHERE sucursal = vsucursal
               AND producto = vproducto
               AND status_cta <> '2';
               
            SELECT NVL(COUNT(*),0)
              INTO vno_ctas
              FROM sc_maechq
             WHERE sucursal = vsucursal
               AND producto = vproducto
               AND status_cta <> '2';
               
            SELECT NVL(SUM(sdo_dia_ant),0.00)
              INTO vsdo_fin_mes
              FROM sc_maechq
             WHERE sucursal = vsucursal
               AND producto = vproducto
               AND status_cta <> '2';
               
            SELECT NVL(COUNT(*),0)
