CREATE PROCEDURE "informix".sp_proyeccionsc( pempresa CHAR(3),
                                             psucursal CHAR(4),
                                             pusuario CHAR(8),
                                             pproducto CHAR(4),
                                             pmonto MONEY(14,2),
                                             pInstruc CHAR(2) )
RETURNING CHAR(5), DATE, DATE, DECIMAL(4,2), MONEY(14,2), 
          DECIMAL(4,2), MONEY(14,2), MONEY(14,2), DECIMAL(9,6);

    -- ############################################################################################################################################################
    -- sp_proyeccionsc
    -- Version              1.0.0
    -- Objetivo:            Obtener la proyeccion de una cuenta de cheques tasa variable
    -- Supuestos:           Ninguno
    -- Creado por:
    -- Modificado por:      Alejandro Rueda Sanchez
    -- Ultima Modificacion: Enero - 2009
    -- Modificado por:      Jesús Manuel Aguilar Heredia
    -- Descripcion del cambio: Se agrego paarametro de entrada al procedimiento con el cual se recibira la instruccion de proyeccion, 
    --                         para los casos 01,02 se deja la misma funcionalidad del procedimiento y Se valida que cuando 
    --                         sea el tipo de instruccion sea 03 ó  04 no se sume el interes al capital, y validar que para estas dos opciones 
    --                         el monto sea mayor a 50,000, monto obtendido de un prametro.
    --                         Ademas se le realiza la adecuacion al procedimiento para que cumpla las reglas de informix, 
    --                         por lo cual se le eliminaron algunas variables que no se utilizan, tales como:vferiado,vfecha_tmp1,vfecha_tmp2,vdia_sig,vacumulado
    --                         y se corrigio el nombrado de las variables para cumplir con el standar de programacion.
    -- Fecha de modificacion: 24-Mayo-2011
    -- ############################################################################################################################################################
    
    DEFINE cCodret     CHAR(5);
    DEFINE iSqlerr     INTEGER;
    DEFINE dtFecha_ini  DATE;
    DEFINE dtFecha_fin  DATE;
    DEFINE dtFecha_tmp  DATE;
    DEFINE dtFecha_hoy  DATE;
    DEFINE cMes        CHAR(2);
    DEFINE dTasa       DECIMAL(4,2);
    DEFINE mMonto_int  MONEY(14,2);
    DEFINE dTasa_tot   DECIMAL(4,2);
    DEFINE mMonto_tot  MONEY(14,2);
    DEFINE icontador   SMALLINT;
    DEFINE sDias       SMALLINT;
    DEFINE cTipo_calc  CHAR(1);
    DEFINE cTasa_nom   CHAR(8);
    DEFINE sDia_aper   SMALLINT;
    DEFINE cTipo_tasa  CHAR(1);
    DEFINE mIsr        MONEY(14,2);
    DEFINE dTisr       DECIMAL(9,6);
    DEFINE sNumdias    SMALLINT;
    DEFINE mAnualisr   MONEY(14,2);
    DEFINE dValor      DECIMAL(14,2);

    ON EXCEPTION SET iSqlerr
        IF iSqlerr <> 0 THEN
            LET cCodret = iSqlerr;
            RETURN cCodret,NULL,NULL,0,0,0,0, 0, 0;
        END IF
    END EXCEPTION;
    
    --- set debug file to "/tmp/sp_proyeccionsc.out";
    --- trace on;
    
    LET cCodret    = "000";
    LET dtFecha_ini = "";
    LET dtFecha_fin = "";
    LET cMes       = "";
    LET dTasa      = 0;
    LET mMonto_int = 0;
    LET dTasa_tot  = 0;
    LET mMonto_tot = pmonto;
    LET dtFecha_tmp = "";
    LET dtFecha_hoy = "";
    LET sDias      = 0;
    LET cTipo_calc = "";
    LET dTasa      = "";
    LET cTasa_nom  = "";
    LET sDia_aper  = 0;
    LET cTipo_tasa = "";
    LET mIsr       = 0;
    LET dTisr      = 0;
    LET sNumdias   = 0;
    LET mAnualisr  = 0;
    LET dValor     = 0;
    LET icontador = 1;
    
    IF Trim(pproducto) = "" OR pmonto = 0 OR NVL(pInstruc,"") = "" THEN
        LET cCodret = "110";
        RETURN cCodret,dtFecha_ini,dtFecha_fin,dTasa,mMonto_int,dTasa_tot,mMonto_tot,mIsr, dTisr;
    END IF;
    
    IF pInstruc IN("03","04") THEN
        SELECT valor
          INTO dValor
          FROM bdicheq:"informix".sc_param
         WHERE empresa = pempresa
           AND codparam = "INSVTOINVCRE";

        IF pmonto < dValor THEN
            LET cCodret = "111";
            RETURN cCodret,dtFecha_ini,dtFecha_fin,dTasa,mMonto_int,dTasa_tot,mMonto_tot,mIsr, dTisr;
        END IF;  
    END IF;

    -- // Extrae las Caracteristicas del Producto
    SELECT tipo_anio_calc,tasa
      INTO cTipo_calc,cTasa_nom
      FROM bdicheq:"informix".sc_producto
     WHERE producto = pproducto
       AND empresa = pempresa;

    -- // Obtiene la fecha del Sistema de Captacion
    SELECT fecha_hoy 
      INTO dtFecha_hoy 
      FROM bdicheq:"informix".sc_fechas;

    LET sDia_aper = DAY(dtFecha_hoy);

    SELECT MAX(fecha)
      INTO dtFecha_tmp
      FROM bdinteg:"informix".si_tasa_mes;

    LET dtFecha_ini = dtFecha_hoy;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH
        SELECT mes,valor_tasa,tipo_tasa
          INTO cMes,dTasa,cTipo_tasa
          FROM bdinteg:"informix".si_tasa_mes
         WHERE fecha = dtFecha_tmp
           AND tasa = cTasa_nom
         ORDER BY mes::SMALLINT

        LET icontador = cMes::SMALLINT;

        IF icontador = 13  THEN
            CALL "informix".sp_mes_siguiente(dtFecha_hoy, icontador - 1  ,sDia_aper) RETURNING cCodret, dtFecha_fin, sNumdias;
        ELSE
            CALL "informix".sp_mes_siguiente(dtFecha_ini, 1 ,sDia_aper) RETURNING cCodret, dtFecha_fin, sNumdias;
            
            IF sNumdias > 40 THEN
                CALL "informix".sp_mes_siguiente(dtFecha_ini, 0 ,sDia_aper) RETURNING cCodret, dtFecha_fin, sNumdias;
            END IF
        END IF

        LET sDias = sNumdias;
        
        -- // Aqui esta la Modificacion del Calculo de Intereses
        IF pInstruc IN("03","04") THEN --- se agrega validacion para que cuando sean estos tipos de instruccion, el interes no se sume al capital.
            LET pmonto = pmonto-mIsr;
        ELSE
            LET pmonto = pmonto + mMonto_int - mIsr;
        END IF;

        -- // Aqui Termina la Modificacin ALE Realizada por MEL 17 Enero 2009
        CALL "informix".calc_isr_proy(pempresa, "0000000", dtFecha_hoy, sDias, mMonto_int, pmonto, sDias, "S")
        RETURNING cCodret, mIsr, dTisr;

        -- // Calcula los Intereses
        IF cTipo_calc = "1" THEN
            LET mMonto_int = pmonto * (dTasa/100) / 360 * sDias;
        ELSE
            LET mMonto_int = pmonto * (dTasa/100) / 365 * sDias;
        END IF

        -- // Calcula los Intereses META
        IF cTipo_tasa = "P" THEN
            LET dtFecha_ini = dtFecha_hoy;

            IF cTipo_calc = "1" THEN
                LET mMonto_int = mMonto_tot * (dTasa/100) / 360 * sDias;
                LET dTasa_tot = dTasa;
            ELSE
                LET mMonto_int = mMonto_tot * (dTasa/100) / 365 * sDias;
                LET dTasa_tot = dTasa;
            END  IF

            LET mIsr = mAnualisr;
        ELSE  -- // Calcula Intereses Acumulados
            LET mAnualisr = mAnualisr + mIsr;
        END IF;

        RETURN cCodret,dtFecha_ini,dtFecha_fin,dTasa,mMonto_int,dTasa_tot,mMonto_tot, mIsr, dTisr WITH RESUME;
        
        LET dtFecha_ini = dtFecha_fin;
    END FOREACH
    
END PROCEDURE DOCUMENT "Version 1.00.000";

CREATE PROCEDURE "informix".sp_geninfmovscorresp_201106(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), CHAR(50);

    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    
    DEFINE vfecha_ini       DATE;
    DEFINE vfecha_fin       DATE;
    
    DEFINE vsucursal        CHAR(4);
    DEFINE vfecha           DATE;
    DEFINE vno_transacc     INTEGER;
    DEFINE vmonto_tot       DECIMAL(18,2);
    DEFINE vcuantos         INTEGER;
    DEFINE vmonto           DECIMAL(18,2);
    DEFINE vlocalidad       CHAR(12);
    DEFINE vciudad          CHAR(60);
    
    DEFINE vexiste_suc      INTEGER;
    DEFINE vaniomes         CHAR(6);
    DEFINE vsql             CHAR(500);
    
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    
    LET vfecha_ini   = '';
    LET vfecha_fin   = '';
    
    LET vsucursal    = '';
    LET vfecha       = '';
    LET vno_transacc = 0;
    LET vmonto_tot   = 0.00;
    LET vcuantos     = 0;
    LET vmonto       = 0.00;
    LET vlocalidad   = '';
    LET vciudad      = '';
    
    LET vexiste_suc = 0;
    LET vaniomes    = '';
    LET vsql        = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_geninfmovscorresp_201106.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_geninfmovscorresp_201106.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    LET vfecha_ini = '06/01/2011';
    LET vfecha_fin = '06/30/2011';
    
    -- // MOVIMIENTOS DE CRÉDITO
    CREATE TEMP TABLE sc_movs_cred_corresp(
        sucursal        char(4),
        no_movs_cred    integer,
        monto_cred      decimal(18,2),
        fecha           char(10) ) 
    EXTENT SIZE 1024 NEXT SIZE 512 LOCK MODE ROW;
begin;
    CREATE INDEX idx_movscrecorr ON sc_movs_cred_corresp(sucursal) ONLINE;
commit;
    UPDATE STATISTICS MEDIUM FOR TABLE sc_movs_cred_corresp;
    
    LET vsucursal = '';
    LET vfecha = '';
    LET vno_transacc = 0;
    LET vmonto_tot = 0.00;
    
    FOREACH
        SELECT SUBSTR(folio_suc,1,4), fecha_mov, COUNT(*), SUM(monto)
          INTO vsucursal, vfecha, vno_transacc, vmonto_tot
          FROM bdicred:sd_movhis
         WHERE codigo_fun = '700'
           AND codigo_ref = 1
           AND fecha_mov BETWEEN vfecha_ini AND vfecha_fin
           AND reversado = 'N'
           AND transacc_suc = '6282'
         GROUP BY 1, 2
           
        INSERT INTO sc_movs_cred_corresp(sucursal, no_movs_cred, monto_cred, fecha)
        VALUES(vsucursal, vno_transacc, vmonto_tot, vfecha);
        
        LET vsucursal = '';
        LET vfecha = '';
        LET vno_transacc = 0;
        LET vmonto_tot = 0.00;
    END FOREACH;
    
    UPDATE STATISTICS MEDIUM FOR TABLE sc_movs_cred_corresp;
    
    -- // INSERTA MOVIMIENTOS DE CRÉDITO
    LET vsucursal = '';
    LET vcuantos = 0;
    LET vmonto = 0.00;
    LET vfecha = '';
    LET vexiste_suc = 0;
    
    FOREACH
        SELECT sucursal, no_movs_cred, monto_cred, fecha
          INTO vsucursal, vcuantos, vmonto, vfecha
          FROM sc_movs_cred_corresp
          
        SELECT COUNT(*)
          INTO vexiste_suc
          FROM sc_movs_corresp
         WHERE fecha = vfecha
           AND sucursal = vsucursal;
         
        IF vexiste_suc = 0 THEN
            INSERT INTO sc_movs_corresp(sucursal, no_movs_capt, monto_capt, no_movs_cred, monto_cred, fecha)
            VALUES(vsucursal, 0, 0.00, vcuantos, vmonto, vfecha);
        ELSE
            UPDATE sc_movs_corresp
               SET no_movs_cred = vcuantos,
                   monto_cred = vmonto
             WHERE fecha = vfecha
               AND sucursal = vsucursal;
        END IF;
        
        LET vsucursal = '';
        LET vcuantos = 0;
        LET vmonto = 0.00;
        LET vfecha = '';
        LET vexiste_suc = 0;
    END FOREACH;
    
    UPDATE STATISTICS MEDIUM FOR TABLE sc_movs_corresp;
    
    -- // INSERTA LAS CIUDADES DE LAS SUCURSALES
    FOREACH
        SELECT UNIQUE sucursal
          INTO vsucursal
          FROM sc_movs_corresp
          
        SELECT localidad_inegi
          INTO vlocalidad
          FROM bdirepaut:sp_r026_establecimiento
         WHERE clave = vsucursal;
           
        SELECT LIMIT 1 ciudad||' '||TRIM(nombre)
          INTO vciudad
          FROM bdinteg:si_ciudades
         WHERE localidad_inegi = vlocalidad;
          
        UPDATE sc_movs_corresp
           SET ciudad = vciudad
         WHERE sucursal = vsucursal;
         
        LET vsucursal = '';
        LET vlocalidad = '';
        LET vciudad = '';
    END FOREACH;
    
    UPDATE STATISTICS MEDIUM FOR TABLE sc_movs_corresp;
    
    -- // DESCARGA EL ARCHIVO DE INFORMACIÓN
    LET vaniomes = TO_CHAR(vfecha_fin, '%Y%m');
    
    LET vsql = '';
    LET vsql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/movscorrespxfechasuc_'||vaniomes||'.txt '||
               ' SELECT ciudad, sucursal, no_movs_capt, monto_capt, no_movs_cred, monto_cred, fecha[4,5]||fecha[1,2]||fecha[9,10]'||
               ' FROM sc_movs_corresp WHERE fecha BETWEEN '''||vfecha_ini||''' AND '''||vfecha_fin||''' ORDER BY fecha, sucursal" > /resplogifx/conciliachq/movtoscorresp.sql';
    SYSTEM vsql;
    
    LET vsql = '';
    LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/movtoscorresp.sql"; 
    SYSTEM vsql;
       
    LET vcodret3 = 'EL PROCESO SE REALIZO SATISFACTORIAMENTE';

    END;

    RETURN vcodret1, vcodret2, vcodret3;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_conciliaciondispersionnomina_his(pNombreArchivo CHAR(17))
RETURNING CHAR(5),CHAR(18);  
    
    DEFINE v_cCodRet         		CHAR(5);
    DEFINE v_cNumEmpleado    		CHAR(10);
    DEFINE v_cCuentaAbono    		CHAR(20);
    DEFINE v_cNumTarjeta     		CHAR(20);
    DEFINE v_mImporte        		MONEY(18,2);
    DEFINE v_cStatus         		CHAR(1);
    DEFINE v_mComDis         		MONEY(18,2);
    DEFINE v_mIvaDis         		MONEY(18,2);
    DEFINE v_cHoraAplicada   		CHAR(8);
    DEFINE v_cNomArchivo     		CHAR(18);
    DEFINE v_cdirectorio     		CHAR(100);
    DEFINE v_cvsql           		CHAR(600);
    DEFINE vSqlErr           		SMALLINT;
    DEFINE v_iSqlErr         		INTEGER;
    DEFINE cNumeroEmpresa    		CHAR(3);
    DEFINE cFolioDispersion  		CHAR(16);
    DEFINE dFechaAplicado    		Date ;
    DEFINE cHoraAplicado     		DateTime Hour to Second;
    DEFINE cImporteTotalAplicadoCh 	CHAR(19);
    DEFINE cComisionAplicadoCh 		CHAR(19);
    DEFINE cIvaAplicadoCh 			CHAR(19);
    DEFINE sTipoEmpresa   			SMALLINT;
    DEFINE cPunto 					CHAR(1);
    DEFINE cConcepto         		INTEGER;
    
    LET cConcepto  				= 0;
    LET sTipoEmpresa			= 0;
    LET cNumeroEmpresa  		= "";
    LET cFolioDispersion  		= "";
    LET dFechaAplicado  		= '';
    LET cHoraAplicado  			= current;
    LET cImporteTotalAplicadoCh = "";
    LET cComisionAplicadoCh 	= "";
    LET cIvaAplicadoCh 			= "";
    LET v_cCodRet 				= "000";
    LET v_cNumEmpleado 			= "";
    LET v_cCuentaAbono 			= "";
    LET v_cNumTarjeta  			= "";
    LET v_mImporte  			= 0;
    LET v_cStatus 				= "";
    LET v_mComDis 				= 0.00;
    LET v_mIvaDis  				= 0.00;
    LET v_cHoraAplicada 		= "";
    LET v_cNomArchivo  			= "";
    LET v_cdirectorio 			= "";
    LET v_cvsql 				= "";
    LET vSqlErr 				= 0;
    LET v_iSqlErr  				= 0;
    LET cPunto					= "";

    BEGIN
    
    ON EXCEPTION SET vSqlErr
        IF vSqlErr <> 0 THEN
            LET v_cCodRet  = vSqlErr;
            RETURN  v_cCodRet,v_cNomArchivo; --Se quitaron  los valores de retoorno v_mComDis, v_mIvaDis, v_cHoraAplicada ;
        END IF
    END EXCEPTION
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    --- SET DEBUG FILE TO "/tmp/sp_ConciliacionDispersionNomina.out";
    --- TRACE ON;

    IF EXISTS (SELECT dbsname, tabname FROM sysmaster:systabnames WHERE tabname = 'sc_tmpconciliacion_nomina') THEN
        DROP TABLE sc_tmpconciliacion_nomina;
    END IF;

    CREATE TABLE sc_tmpconciliacion_nomina
    (
        empleado      CHAR(10), 
        cuenta        CHAR(20), 
        tarjeta       CHAR(20), 
        importe       MONEY, 
        status        CHAR(1), 
        apell_paterno CHAR(26), 
        apell_materno CHAR(26), 
        nombre1       CHAR(26), 
        nombre2       CHAR(26)
    );

    /* Valida que el nombre de archivo  sea correcto */
    LET cPunto = substr(pNombreArchivo, 14, 1);

    /* Valida el parametro de entrada */
    IF Length(pNombreArchivo) <> 17 or cPunto <> '.' THEN  
        LET v_cCodRet = "110"; /* datos insuficientes */
        DROP TABLE sc_tmpconciliacion_nomina;
        RETURN v_cCodRet,v_cNomArchivo;
    END IF;

    /* Obtener los datos para la generacion del archivo */
    /* Se agrego el nombre del cliente */
    INSERT INTO sc_tmpconciliacion_nomina (empleado, cuenta, tarjeta, importe, status, apell_paterno, apell_materno, nombre1, nombre2)
    SELECT nommov.num_empleado, nommov.cuenta_abono, NVL(tar.num_tarjeta, ''), nommov.importe, nommov.status, nvl(cli.apell_paterno, ''), nvl(cli.apell_materno, ''), nvl(cli.nombre1,''), nvl(cli.nombre2,'')
      FROM bdicheq:sc_nominamovimientoshist nommov 
      LEFT outer JOIN bdicheq:sc_maechq chq  ON (chq.cuenta = nommov.cuenta_abono)
      LEFT outer JOIN bdinteg:si_cliente cli ON (cli.numcte = chq.num_cte)
      LEFT outer JOIN bdicheq:sc_tarjeta tar ON (tar.empresa = '001' AND tar.numcte = cli.numcte AND tar.cuenta = nommov.cuenta_abono AND tar.tipo_tarjeta = 'T' AND tar.status_tar = 'A')
     WHERE nombre_archivo = pNombreArchivo;

    /* Generar el nombre de archivo .dat */
    LET v_cNomArchivo = "C" || TRIM(pNombreArchivo);

    /* Generar Archivo Plano */
    LET v_cdirectorio = "/tmp/traspasobanco/archivosnomina/conciliacion/" || TRIM(v_cNomArchivo);
    LET v_cvsql = '';
    LET v_cvsql = 'echo "UNLOAD TO ' || TRIM(v_cdirectorio) ||
                  ' SELECT empleado, cuenta, tarjeta, importe, status, apell_paterno, apell_materno, nombre1, nombre2 FROM sc_tmpconciliacion_nomina;" > /tmp/querydisnom.sql';

    SYSTEM v_cvsql;
    LET v_cvsql = '';
    LET v_cvsql = "/ifxsif01/bin/dbaccess bdicheq /tmp/querydisnom.sql "; /* Produccion, se debe quitar lo comentariado cuando pase a produccion */
    --- LET v_cvsql = "dbaccess bdicheq /tmp/querydisnom.sql "; /* Desarrollo, se debe comentar esta linea al pasar a produccion */
    SYSTEM v_cvsql;
    
    /* Obtener los datos para guardar en la tabla  sc_nominaresultadosdispercionautomatica */
    SELECT {+INDEX(bdicheq:sc_nominaencabezadosumario idx_sc_nomencsum)}
           empresa, folio_dispersion, fecha_aplicado, importe_aplicado, comision, iva
      INTO cNumeroEmpresa, cFolioDispersion, dFechaAplicado, cImporteTotalAplicadoCh, cComisionAplicadoCh, cIvaAplicadoCh
      FROM bdicheq:sc_nominaencabezadosumario
     WHERE nombre_archivo = pNombreArchivo 
       AND status in ("2", "3");

    /* Obtiene el tipo de empresa, para de este establecer si pertenece o no al Grupo Coppel, (interna o externa) */
    SELECT tipo_empresa 
      INTO sTipoEmpresa 
      FROM sc_nominaempresas 
     WHERE codigo = cNumeroEmpresa;
    
    /* OBTENER EL CONCEPTO PARA VALIDARLO */
    SELECT {+INDEX(bdicheq:sc_nominamovimientos idx_nominamovimientos1)}
           LIMIT 1 concepto 
      INTO cConcepto 
      FROM bdicheq:sc_nominamovimientos 
      WHERE nombre_archivo = pNombreArchivo;
    
    /* Valida que el tipo de empresa partenece al Grupo Coppel, y guarda los datos del resultado de la dispersion */
    IF sTipoEmpresa < 3  AND cConcepto <> 5 THEN
        INSERT INTO bdicheq:sc_nominaresultadosdispercionautomatica 
        (Codigo_Retorno, Mensaje, Folio_Dispercion, Importe_Total_Aplicado, Comision_Aplicada, Iva_Aplicado, Nombre_Archivo_Conciliacion, hora_aplicado)
        Values(v_cCodRet,'DispersiÃ³n ejecutada correctamente', cFolioDispersion, cImporteTotalAplicadoCh, cComisionAplicadoCh, cIvaAplicadoCh, v_cNomArchivo, cHoraAplicado);
    END IF
    
    --- Se implementara hasta que se modiquen los reportes de nomina. 
    /* 
    --- Guarda historial de la  tabla encabezado sumario
    INSERT INTO sc_nominaencabezadosumariohist (empresa, fecha_gen, folio_archivo, nombre_archivo, sentido, cuenta_cargo, fecha_aplicacion, total_registros,
    importe_tot, status, fecha_insert, importe_aplicado, importe_no_aplicado, folio_acuserecibo, folio_dispersion, iva, comision, fecha_aplicado, hora_aplicado)
    SELECT empresa, fecha_gen, folio_archivo, nombre_archivo, sentido, cuenta_cargo, fecha_aplicacion, total_registros, importe_tot, status, fecha_insert,
    importe_aplicado, importe_no_aplicado, folio_acuserecibo, folio_dispersion, iva, comision, fecha_aplicado, hora_aplicado
    FROM bdicheq:sc_nominaencabezadosumario WHERE nombre_archivo = pNombreArchivo AND status > 1;

    --- Limpia la tabla base de encabezado sumario
    DELETE FROM bdicheq:sc_nominaencabezadosumario WHERE status > 1;

    --- Guarda historial de la tabla de movimientos
    INSERT INTO sc_nominamovimientoshist (nombre_archivo, num_empleado, apell_paterno, apell_materno, nombres, cuenta_abono, importe, concepto, status)
    SELECT nombre_archivo, num_empleado, apell_paterno, apell_materno, nombres, cuenta_abono, importe, concepto, status
    FROM bdicheq:sc_nominamovimientos WHERE nombre_archivo = pNombreArchivo AND status > 0;

    --- Limpia la tabla base de movimientos
    DELETE FROM bdicheq:sc_nominamovimientos WHERE nombre_archivo = pNombreArchivo AND status > 0;
    */
    
    DROP TABLE sc_tmpconciliacion_nomina;
    
    RETURN  v_cCodRet,v_cNomArchivo; /* Se quitaron  los valores de retoorno v_mComDis,   v_mIvaDis, v_cHoraAplicada ; */
    
    END
    
END PROCEDURE

DOCUMENT
