CREATE PROCEDURE "informix".borramovsduplicados(pempresa CHAR(3), pfecha DATE)
RETURNING CHAR(5), CHAR(5), INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador1       INTEGER;
    DEFINE vnum_serial      INTEGER;
    
    LET vcodret1        = '000';
    LET vcodret2        = '000';
    LET sql_err	        = 0;
    LET isam_err        = 0;
    LET vcontador1      = -1;
    LET vnum_serial     = 0;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/borramovsduplicados.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
        END IF;
    END EXCEPTION;
    
    -- SET DEBUG FILE TO "/resplogifx/conciliachq/borramovsduplicados.out";
    -- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    select {+index(sc_movhis_old2 idx_movhisnew6_old2)}
           num_serial, count(*) cuantos
      from sc_movhis_old2
     where fech_alt = pfecha
     group by 1
      into temp tmp_serial with no log;
    create index idxtmp_serial on tmp_serial(num_serial) using btree fillfactor 99;
    update statistics medium for table tmp_serial;
      
    select *
      from tmp_serial
     where cuantos > 1
      into temp tmp_movs_dupl with no log;
    create index idxtmp_movs on tmp_movs_dupl(num_serial) using btree fillfactor 99;
    update statistics medium for table tmp_movs_dupl;
    
    FOREACH cursor_borra WITH HOLD FOR
        SELECT {+index(sc_movhis_old2 idx_movhisnew6_old2)} num_serial
          INTO vnum_serial
          FROM sc_movhis_old2
         WHERE fech_alt = pfecha
           AND num_serial IN(SELECT num_serial FROM tmp_movs_dupl)
           
        IF vcontador1 = -1 THEN
            LET vcontador1 = 0;
            BEGIN WORK;
        END IF;
        
        DELETE FROM sc_movhis_old2
         WHERE CURRENT OF cursor_borra;
         
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;

    END;

    RETURN vcodret1, vcodret2, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".corrige_sdos_06082011(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER;
    
    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vsql             CHAR(200);
    DEFINE vcuenta          CHAR(20);
    DEFINE vsaldo           MONEY(18,2);    
    DEFINE vinteres         MONEY(18,2);     
    
    LET vcodret	     = '000';
    LET vcodret2     = '000';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET vcontador    = -1;
    LET ven_transacc = 0;
    
    LET vsql         = '';
    LET vcuenta      = '';
    LET vsaldo       = 0.00;
    LET vinteres     = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_sdos_06082011.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret, vcodret2, vcontador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_sdos_06082011.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum > 0 AND tabname = 'ctasxcorregir') THEN
        DROP TABLE "informix".ctasxcorregir;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxcorregir
      (
        cuenta  char(20) not null,
        saldo   money(18,2) not null,
        interes money(18,2) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctasxcorr ON "informix".ctasxcorregir(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/sdos_06082011.unl INSERT INTO ctasxcorregir" > /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    LET vsql = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxcorregir;
    
    FOREACH WITH HOLD
        SELECT cuenta, saldo, interes
          INTO vcuenta, vsaldo, vinteres
          FROM ctasxcorregir
        
        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
            LET ven_transacc = 1;
        END IF;
        
        UPDATE sc_sdodiarioc
           SET capvig6 = vsaldo,
               intprovnp6 = vinteres
         WHERE cuenta = vcuenta
           AND aniomes = '201108';
        
        LET vcontador = vcontador + 1;
        
        LET vcuenta = '';
        LET vsaldo  = 0.00;
        LET vinteres = 0.00;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    DROP TABLE "informix".ctasxcorregir;
    
    END;

    RETURN vcodret, vcodret2, vcontador;

END PROCEDURE;

CREATE PROCEDURE "informix".corrige_proac(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcodret_abono    CHAR(5);
    
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(14,2);    
    DEFINE vtransacc        CHAR(4);
    DEFINE vdescripcion     CHAR(40);
    DEFINE vsucursal        CHAR(4);  
    DEFINE vusuario         CHAR(8);
    DEFINE vmoneda          CHAR(2);
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcomienza     = -1;
    LET ven_transacc  = 0;
    LET vcodret_abono = '';
    
    LET vsql         = '';
    LET vstmt        = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vcuenta      = '';
    LET vmonto       = 0.00;
    LET vtransacc    = '';
    LET vdescripcion = '';
    LET vsucursal    = '';
    LET vusuario     = 'informix';
    LET vmoneda      = '01';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_proac.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_proac.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasproacxabonar') THEN
        DROP TABLE "informix".ctasproacxabonar;
    END IF;
    
    CREATE RAW TABLE "informix".ctasproacxabonar
      (
        cuenta      char(20)    not null,
        monto       money(18,2) not null,
        transacc    char(4)     not null,
        descripcion char(40)    not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctaproacxabon ON "informix".ctasproacxabonar(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/abonos_proac.unl DELIMITER ''","'' INSERT INTO ctasproacxabonar" > /resplogifx/conciliachq/abonos_proac.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/abonos_proac.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasproacxabonar;
    
    LET vhora = CURRENT HOUR TO FRACTION;
    LET vfolio = vusuario||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];
    
    FOREACH WITH HOLD
        SELECT cuenta, monto, transacc, descripcion
          INTO vcuenta, vmonto, vtransacc, vdescripcion
          FROM ctasproacxabonar
        
        IF (vcomienza = -1) THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        SELECT sucursal
          INTO vsucursal
          FROM sc_proac
         WHERE cuenta = vcuenta;
           
        CALL abono_ref( pempresa,       -- empresa
                        vsucursal,      -- sucursal
                        vusuario,       -- usuario
                        vtransacc,      -- transaccion
                        '0000',         -- transacc suc
                        vfolio,         -- folio
                        vcuenta,        -- cuenta
                        0,              -- cheque
                        vmonto,         -- monto
                        vmonto,         -- monto firme
                        0,              -- monto sbc
                        0,              -- monto rem
                        0,              -- dias ret
                        vmoneda,        -- divisa
                        vdescripcion,   -- referencia
                        ' ',            -- num tarjeta
                        vusuario )      -- autoriza
        RETURNING vcodret_abono;
        
        IF vcodret_abono = '000' THEN
            UPDATE sc_proac
               SET saldo = saldo + vmonto,
                   prem_proac = prem_proac + vmonto
             WHERE cuenta = vcuenta;
               
            LET vcontador2 = vcontador2 + 1;
            
            COMMIT WORK;
            BEGIN WORK;
        ELSE 
            ROLLBACK WORK;
            BEGIN WORK;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        
        LET vcuenta       = '';
        LET vmonto        = 0.00;
        LET vtransacc     = '';
        LET vdescripcion  = '';
        LET vsucursal     = '';
        LET vcodret_abono = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".consctesfircaja(pEmpresa char(3), pNumeroCuenta char(20), pNumeroCliente char(20))
	-- DATOS A REGRESAR --
	RETURNING
	char(5),    -- Codigo de retorno
	char(20),   -- # Cliente
	char(26),   -- Apellido paterno
	char(26),   -- Apellido materno
	char(26),   -- Nombre 1
	char(26),   -- Nombre 2
	char(13),   -- RFC
	char(16),   -- # Tarjeta
	date,    --	Expiracion
	char(4),    -- Producto tarjeta
	money(14,2), -- Limite de retiro maximo por mes
	char(1),    -- Status tarjeta
	char(8),    -- Tipo de cliente
	char(10),   --Fecha de Nacimiento
	char(4),    --Producto de la cuenta
	char(2);    --Parentesco

	-- VARIABLES --
	DEFINE vCodRet  char(5);
	DEFINE vTipCte  char(1);
	Define vSecuencia char(1);
	DEFINE vNumCte	char(20);
	DEFINE vApePat  char(26);
	DEFINE vApeMat  char(26);
	DEFINE vNombre1 char(26);
	DEFINE vNombre2 char(26);
	DEFINE vRFC     char(13);
	DEFINE vNumTarj char(16);
	DEFINE Vexpiracion date;
	DEFINE Vprodtarjeta char(4);
	DEFINE vLimTar  money(14,2);
	DEFINE vTipoCte char(8);
	DEFINE vStatTjt char(1);
	DEFINE vFechaNac char(10);
	DEFINE vProductoCuenta char(4);
	DEFINE vCantReg smallint;
	DEFINE vParentesco char(2);

--set debug file to "/respaldosbd/consctesfircaja.out";
--trace on;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO wait 3;


	-- INICIALIZACION DE VARIABLES --
	LET vCodRet  = "000";
	LET vCantReg = 0;
	LET vTipCte = "";
	LET vNumCte = "";
	LET vApePat = "";
	LET vApeMat = "";
	LET vNombre1 = "";
	LET vNombre2 = "";
	LET vRFC = "";
	LET vNumTarj = "";
	LET Vexpiracion = "";
	LET Vprodtarjeta = "";
	LET vLimTar = "";
	LET vTipoCte = "";
	LET vStatTjt = "";
	LET vFechaNac = "";
	LET vProductoCuenta = "";
	LET vParentesco = "";
	LET vSecuencia = "";



		-- CICLO PARA OBTENER A LOS FIRMANTES Y LAS TARJETAS DE DEBITO EN CASO DE QUE TENGAN --

	FOREACH
		SELECT DISTINCT
			sc_fir.secuencia,si_cte.numcte, si_cte.apell_paterno, si_cte.apell_materno, si_cte.nombre1, si_cte.nombre2, si_cte.rfc, 'Firmante' AS tipo_cliente,si_pf.fecha_nac, sc_mcq.producto, sc_fir.parentesco
		INTO
			vSecuencia, vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vTipoCte, vFechaNac, vProductoCuenta, vParentesco
		FROM
			bdicheq:"informix".sc_maechq sc_mcq,
			bdicheq:"informix".sc_firmantes AS sc_fir,
			bdinteg:"informix".si_cliente AS si_cte,
			bdinteg:"informix".si_ctepf AS si_pf
		WHERE
			--sc_fir.empresa =  pEmpresa AND sc_fir.cuenta =  pNumeroCuenta AND sc_fir.numcte != pNumeroCliente AND
			--sc_fir.numcte = si_cte.numcte AND si_cte.empresa = pEmpresa AND sc_fir.numcte = si_pf.numcte  AND
			--sc_mcq.empresa = pEmpresa AND sc_mcq.cuenta = pNumeroCuenta
			sc_fir.empresa =  pEmpresa AND sc_fir.cuenta =  pNumeroCuenta AND sc_fir.numcte = si_cte.numcte 
			AND si_cte.empresa = pEmpresa AND sc_fir.numcte = si_pf.numcte  AND
			sc_mcq.empresa = pEmpresa AND sc_mcq.cuenta = pNumeroCuenta
			Order By sc_fir.secuencia


		-- OBTENER LA TARJETA DEL FIRMANTE --

		SELECT DISTINCT
			sc_tjt.expiracion, sc_tjt.prodtarjeta, sc_tjt.num_tarjeta, sc_tjt.limite_aut, sc_tjt.status_tar
		INTO
			Vexpiracion, Vprodtarjeta, vNumTarj, vLimTar, vStatTjt
		FROM
			bdicheq:"informix".sc_tarjeta AS sc_tjt
		WHERE
			sc_tjt.empresa = pEmpresa AND
			sc_tjt.cuenta = pNumeroCuenta AND
			sc_tjt.numcte = vNumCte AND
			sc_tjt.status_tar = 'A' AND
			sc_tjt.tipo_tarjeta = 'A';


		IF vNumTarj IS NULL THEN
			LET vNumTarj = "Sin tarjeta";
			LET vLimTar = 0;
			LET vStatTjt = "";
		END IF

		LET vCantReg = vCantReg + 1;

		RETURN vCodRet, vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vNumTarj, Vexpiracion, Vprodtarjeta, vLimTar, vStatTjt, vTipoCte, vFechaNac, vProductoCuenta, vParentesco  WITH RESUME;
	END FOREACH;

	IF vCantReg = 0 THEN
		LET vCodRet  = "000";
		LET vNumCte  = "";
		LET vApePat  = "";
		LET vApeMat  = "";
		LET vNombre1 = "";
		LET vNombre2 = "";
		LET vRFC     = "";
		LET vNumTarj = "";
		LET Vexpiracion = "";
		LET Vprodtarjeta = "";
		LET vLimTar  = 0;
		LET vStatTjt = "";
		LET vTipoCte = "";
		LET vFechaNac = "";
		LET vParentesco  = "";

		RETURN vCodRet, vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vNumTarj, Vexpiracion, Vprodtarjeta, vLimTar, vStatTjt, vTipoCte, vFechaNac, vProductoCuenta, vParentesco;
	END IF
END PROCEDURE
DOCUMENT
'DESCRIPCION: Se modifica para que consulte todos los status de tarjetas',
'             incluyendo las tarjetas canceladas',
'EJECUTADO O LLAMADO POR: AsigAdic.exe',
'AUTOR : Martin Eduardo Miranda Miranda',
