CREATE PROCEDURE "informix".sp_reversa_opecorresp()
RETURNING CHAR(5), INTEGER, INTEGER;

    DEFINE sql_err             integer;
    DEFINE isam_err            integer;
    DEFINE cod_ret1            char(5);
    DEFINE cod_ret2            char(5);
    DEFINE vcodret             CHAR(5);
    
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vfolio_suc       CHAR(16);
    DEFINE vcuenta          CHAR(20);

    LET sql_err = 0;
    LET isam_err = 0;
    LET cod_ret1 = "000";
    LET cod_ret2 = "000";
    LET vcodret  = '';
    
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcomienza     = -1;
    LET ven_transacc  = 0;
    
    LET vsql         = '';
    LET vstmt        = '';
    LET vfolio_suc = '';
    LET vcuenta = '';

    -- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_reversa_opecorresp.out";
    -- TRACE ON;

    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err
        IF (sql_err <> 0) THEN
            -- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_reversa_opecorresp.err";
            -- TRACE ON;
            LET cod_ret1 = sql_err;
            LET cod_ret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN cod_ret1, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxreversar') THEN
        DROP TABLE "informix".ctasxreversar;
    END IF;
    
    -- // CREA TABLA DE FOLIOS A REVERSAR
    CREATE TABLE "informix".ctasxreversar
      (
        folio_suc char(16) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctaxrever ON "informix".ctasxreversar(folio_suc) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/reversos_opercorresp.unl INSERT INTO ctasxreversar" > /resplogifx/conciliachq/rever.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/rever.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxreversar;
    
    -- // CREA TABLA DE RESULTADOS
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'rever_oper_corresp') THEN
        DROP TABLE "informix".rever_oper_corresp;
    END IF;
    
    CREATE TABLE "informix".rever_oper_corresp
      (
        folio_suc char(16) not null,
        cod_ret   char(5) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_resulrever ON "informix".rever_oper_corresp(folio_suc) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE rever_oper_corresp;
    
    FOREACH WITH HOLD
        SELECT folio_suc
          INTO vfolio_suc
          FROM ctasxreversar
          
        IF (vcomienza = -1) THEN
            LET vcomienza = 0;
            BEGIN WORK;
        END IF;
        
        SELECT cuenta 
          INTO vcuenta
          FROM sc_movdia
         WHERE folio_suc = vfolio_suc;
         
        UPDATE sc_maechq
           SET status_cta = '1',
               motivo = '00'
         WHERE empresa = '001'
           AND cuenta = vcuenta;
          
        EXECUTE PROCEDURE bdicorresp:"informix".corresp_revdep('5005', 'informix', vfolio_suc)
        INTO vcodret;
        
        INSERT INTO rever_oper_corresp VALUES(vfolio_suc, vcodret);
        
        IF vcodret = '000' THEN
            LET vcontador2 = vcontador2 + 1;
        END IF;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vcontador1 = vcontador1 + 1;
        LET vfolio_suc = '';
        LET vcuenta = '';
        LET vcodret = '';
    END FOREACH;
    
    COMMIT WORK;
    
    RETURN cod_ret1, vcontador1, vcontador2;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_arreg_maehis_sbc( pEmpresa CHAR(3), pFechaIni DATE, pFechaFin DATE )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;

    DEFINE CodRet1	                CHAR(5);
    DEFINE CodRet2                  CHAR(5);
    DEFINE CodRet3                  CHAR(50);
    DEFINE sql_err                  INTEGER;
    DEFINE isam_err                 INTEGER;
    DEFINE desc_err                 CHAR(50);
    DEFINE vcomienza                SMALLINT;
    DEFINE ven_transacc             SMALLINT;
    DEFINE vcontador1               INTEGER;
    
    DEFINE vtotdepositos            DECIMAL(14,2);
    DEFINE vtotretiros              DECIMAL(14,2);
    DEFINE vfechafin                DATE;
    DEFINE vfechaini                DATE;
    DEFINE vaniomes                 CHAR(6);
    DEFINE vmonto_tot               DECIMAL(16,2);
    DEFINE vtransacc                CHAR(4);
    DEFINE vnaturaleza              CHAR(1);
    DEFINE vtipo_tran               CHAR(2);
    DEFINE vfechainimovhis          CHAR(10);
    DEFINE vfechainimovhisold       CHAR(10);
    DEFINE vtran_efec               CHAR(4);
    DEFINE vtotretirosefec          DECIMAL(18,2);
    DEFINE vtototroscargos          DECIMAL(18,2);
    DEFINE vtrandepotrobco          CHAR(4);
    DEFINE vtrandevotrobco          CHAR(4);
    DEFINE vgtrans_pag_int          CHAR(4);
    DEFINE vgtransisr               CHAR(4);
    DEFINE vmincta, vmaxcta         CHAR(20);
    DEFINE vcuenta                  CHAR(20);
    
    LET CodRet1      = '000';
    LET CodRet2      = '000';
    LET CodRet3      = 'PROCESO REALIZADO CORRECTAMENTE';
    LET sql_err      = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcomienza    = -1;
    LET ven_transacc = 0;
    LET vcontador1   = 0;
    
    LET vtotdepositos      = 0.00;
    LET vtotretiros        = 0.00;
    LET vfechafin          = '';
    LET vfechaini          = '';
    LET vaniomes           = '';
    LET vmonto_tot         = 0.00;
    LET vtransacc          = '';
    LET vnaturaleza        = '';
    LET vtipo_tran         = '';
    LET vfechainimovhis    = '';
    LET vfechainimovhisold = '';
    LET vtran_efec         = '';
    LET vtotretirosefec    = 0.00;
    LET vtototroscargos    = 0.00;
    LET vtrandepotrobco    = '';
    LET vtrandevotrobco    = '';
    LET vgtrans_pag_int    = '';
    LET vgtransisr         = '';
    LET vmincta            = '';
    LET vmaxcta            = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_arreg_maehis_sbc.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET CodRet1 = sql_err;
            LET CodRet2 = isam_err;
            LET CodRet3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN CodRet1, CodRet2, CodRet3, vcontador1;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/tmp/sp_arreg_maehis_sbc.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE PARAMETROS
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = "tranpagint";

    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = "tranisr";
       
    SELECT valor
      INTO vfechainimovhis
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'fechcon_movhis';
       
    SELECT valor
      INTO vfechainimovhisold
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'FechIniCon_movhis_ol';
       
    SELECT valor
      INTO vtrandepotrobco
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'trandepobco';
       
    SELECT valor
      INTO vtrandevotrobco
      FROM sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'trandevobco';
       
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vmincta, vmaxcta
      FROM sc_maehis;
       
    SELECT cuenta
      FROM sc_movhis_old 
     WHERE fech_alt BETWEEN '09/05/2011' AND '10/31/2011'
       AND fech_alt >= vfechainimovhisold
       AND fech_alt < vfechainimovhis
       AND transacc IN(vtrandepotrobco, vtrandevotrobco)
       AND cancelad <> 'S'
    UNION ALL 
    SELECT cuenta
      FROM sc_movhis
     WHERE fech_alt BETWEEN '09/05/2011' AND '10/31/2011'
       AND fech_alt >= vfechainimovhis
       AND transacc IN(vtrandepotrobco, vtrandevotrobco)
       AND cancelad <> 'S'
    INTO TEMP tmp_movs WITH NO LOG;
    CREATE INDEX idx_ctatmpmovs ON tmp_movs(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_movs;
     
    -- // OBTIENE CUENTAS A PROCESAR
    FOREACH WITH HOLD
        SELECT UNIQUE his.cuenta, his.aniomes, his.fechaini, his.fechafin
          INTO vcuenta, vaniomes, vfechaini, vfechafin
          FROM sc_maehis his,
               tmp_movs movs
         WHERE his.empresa = pEmpresa
           AND his.cuenta = movs.cuenta
           AND his.fechafin BETWEEN pFechaIni AND pFechaFin     

        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        -- // INICIALIZA VARIABLES DE SALDOS
        LET vtotdepositos   = 0;
        LET vtotretiros     = 0;
        LET vtotretirosefec = 0;
        LET vtototroscargos = 0;
        
        -- // OBTIENE CARGOS Y ABONOS DEL HISTORICO
        FOREACH           
            SELECT mv.monto_tot, mv.transacc, tr.naturaleza, tr.tipo_tran, NVL(efe.transaccion, '0000')
              INTO vmonto_tot, vtransacc, vnaturaleza, vtipo_tran, vtran_efec
              FROM sc_movhis mv
             INNER JOIN bdinteg:si_transacc tr ON (tr.empresa = mv.empresa AND tr.numero = mv.transacc AND tr.se_emite_edocta = 'S')
              LEFT OUTER JOIN sc_transacc_efectivo efe ON (efe.transaccion = mv.transacc)
             WHERE mv.empresa = pEmpresa
               AND mv.cuenta = vcuenta
               AND mv.fech_alt BETWEEN vfechaini AND vfechafin
               AND mv.fech_alt >= vfechainimovhis
               AND mv.cancelad <> 'S'
               AND mv.transacc = tr.numero
            UNION ALL
            SELECT mv.monto_tot, mv.transacc, tr.naturaleza, tr.tipo_tran, NVL(efe.transaccion, '0000')
              FROM sc_movhis_old mv
             INNER JOIN bdinteg:si_transacc tr ON (tr.empresa = mv.empresa AND tr.numero = mv.transacc AND tr.se_emite_edocta = 'S')
              LEFT OUTER JOIN sc_transacc_efectivo efe ON (efe.transaccion = mv.transacc)
             WHERE mv.empresa = pEmpresa
               AND mv.cuenta = vcuenta
               AND mv.fech_alt BETWEEN vfechaini AND vfechafin
               AND mv.fech_alt >= vfechainimovhisold
               AND mv.fech_alt < vfechainimovhis
               AND mv.cancelad <> 'S'
               AND mv.transacc = tr.numero
            
            -- // ABONOS
            IF vnaturaleza = 'A' THEN 
                IF (vtransacc <> vgtrans_pag_int AND vtransacc <> vtrandepotrobco) THEN -- TOTAL DEPOSITOS
                    LET vtotdepositos = vtotdepositos + vmonto_tot;
                END IF;
            -- // CARGOS
            ELIF vnaturaleza = 'C' THEN 
                IF (vtipo_tran IN('00','30') AND vtransacc <> vgtransisr AND vtransacc <> vtrandevotrobco) THEN -- TOTAL RETIROS
                    LET vtotretiros = vtotretiros + vmonto_tot;
                    LET vtototroscargos = vtototroscargos + vmonto_tot;
                END IF;
                
                IF vtran_efec = vtransacc THEN
                    LET vtotretirosefec = vtotretirosefec + vmonto_tot;
                END IF;
            END IF;
        END FOREACH;

        IF vtotdepositos IS NULL THEN -- DEPOSITOS
            LET vtotdepositos = 0;
        END IF;

        IF vtotretiros is null OR vtotretiros < 0 THEN -- RETIROS
            LET vtotretiros = 0;
        END IF;
        
        IF vtotretirosefec IS NULL THEN
            LET vtotretirosefec = 0;
        END IF;
        
        LET vtototroscargos = vtototroscargos - vtotretirosefec;
        
        IF vtototroscargos is null OR vtototroscargos < 0 THEN
            LET vtototroscargos = 0;
        END IF;

        UPDATE sc_maehis
           SET totdepositos = vtotdepositos,
               totretiros = vtotretiros,
               tototroscargos = vtototroscargos
         WHERE empresa = pEmpresa
           AND cuenta = vcuenta
           AND aniomes = vaniomes;
           
        LET vcontador1 = vcontador1 + 1; 
           
        COMMIT WORK;
        BEGIN WORK;
        
        LET vcuenta = ''; 
        LET vaniomes = ''; 
        LET vfechaini = ''; 
        LET vfechafin = '';
        LET vmonto_tot = 0.00; 
        LET vtransacc = ''; 
        LET vnaturaleza = ''; 
        LET vtipo_tran = ''; 
        LET vtran_efec = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;
            
    RETURN CodRet1, CodRet2, CodRet3, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".corrige_sdos_31102011(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER;
    
    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador        INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vsql             CHAR(200);
    DEFINE vcuenta          CHAR(20);
    DEFINE vsaldo           MONEY(18,2);    
    DEFINE vinteres         MONEY(18,2);     
    
    LET vcodret	     = '000';
    LET vcodret2     = '000';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET vcontador    = -1;
    LET ven_transacc = 0;
    
    LET vsql         = '';
    LET vcuenta      = '';
    LET vsaldo       = 0.00;
    LET vinteres     = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_sdos_31102011.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret, vcodret2, vcontador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/corrige_sdos_31102011.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum > 0 AND tabname = 'ctasxcorregir') THEN
        DROP TABLE "informix".ctasxcorregir;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxcorregir
      (
        cuenta  char(20) not null,
        interes money(18,2) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctasxcorr ON "informix".ctasxcorregir(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/ints_31102011.unl INSERT INTO ctasxcorregir" > /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    LET vsql = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasxcorreg.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxcorregir;
    
    FOREACH WITH HOLD
        SELECT cuenta, interes
          INTO vcuenta, vinteres
          FROM ctasxcorregir
        
        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
            LET ven_transacc = 1;
        END IF;
        
        UPDATE sc_sdodiarioc
           SET intprovnp31 = vinteres
         WHERE cuenta = vcuenta
           AND aniomes = '201110';
        
        LET vcontador = vcontador + 1;
        
        LET vcuenta = '';
        LET vsaldo  = 0.00;
        LET vinteres = 0.00;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    DROP TABLE "informix".ctasxcorregir;
    
    END;

    RETURN vcodret, vcodret2, vcontador;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_validararchivoenviado(pArchivo CHAR(50))
	RETURNING
		CHAR(6) 	AS CODRET;


		---DECLARACIONES
		DEFINE iSqlErr				INTEGER;
		DEFINE cCodRet         		CHAR(6);

		---INICIALIZACIONES
		LET iSqlErr            		= 0;
		LET cCodRet            		= '00000';

	BEGIN

		ON EXCEPTION SET iSqlErr
		   IF iSqlErr != 0 THEN
			  LET cCodRet = iSqlErr;
			  RETURN cCodRet;
		   END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		--SET DEBUG FILE TO '/tmp/sp_validararchivoenviado.out';
		--TRACE ON;	

		IF EXISTS (SELECT nombre_archivo FROM bdicheq:"informix".sc_nominaencabezadosumario WHERE nombre_archivo = pArchivo
		UNION SELECT nombre_archivo FROM bdicheq:"informix".sc_nominaencabezadosumariohist WHERE nombre_archivo = pArchivo) THEN
            LET cCodRet = '00001';
        END IF;
        RETURN cCodRet;
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que valida si ya se proseso archivos de dispercion en las tablas ',
'sc_nominaencabezadosumario y sc_nominaencabezadosumariohist ',
'AUTOR: Bernardo Carlos Báez Gozález ',
'FECHA: 20 de Octubre 2011',
'VERSION: 20111020.1152',
'BD: bdicheq',
'Paquete/Caso de Uso: PCU-bdicheq/CU-0161-ValidarArchivoEnviado-SPL',
'Se ejecuta desde la aplicacion: "validafondos" en el mensaje "validafondos00005.so"',
'mismo que se llama desde "DispersionNominaBanCoppel.exe"';

CREATE PROCEDURE "informix".sp_obtbines2(pBin char(6))
RETURNING CHAR(5),CHAR(3)


	------------------------------------------------------------------------------------------------------------------------
	--Elaboró:Francisco Rodríguez Ibarra.
	--Actividad:Se utiliza para obtener el banco  o generar los bines, debido a la migración de BD de postgres a informix
	--Solicito:Diana Castellanos
	--Fecha:21/10/2010
	------------------------------------------------------------------------------------------------------------------------
		------------------------------------------------------------------------------------------------------------------------
	--Elaboró:Francisco Rodríguez Ibarra.
	--Actividad:Se modificó para tomar la columna cve_banco en vez de la id_bco
	--Solicito:Diana Castellanos
	--Fecha:16/11/2010
	------------------------------------------------------------------------------------------------------------------------
	--DECLARACION DE VARIABLES
	DEFINE vCod_Ret CHAR(5);
	DEFINE sql_err INTEGER ;
	DEFINE vBanco CHAR(3);
	DEFINE vStipo CHAR(1);
	
	--INICIALIZAR VALORES A VARIABLES;
	LET vCod_Ret='00000';
	LET vBanco='';
	LET vStipo='';
	
	BEGIN
		ON EXCEPTION SET sql_err
		  IF sql_err <> 0 THEN
				let vCod_Ret = sql_err;
				RETURN vCod_Ret,vBanco;
		  END IF ;
		END EXCEPTION ;
		
		
			
		SELECT creditodebito,cve_banco INTO vStipo,vBanco FROM  bdicheq:sc_bines WHERE bin= TRIM(pBIN);
		IF(vStipo<>'')THEN
			IF(vStipo='d')THEN
				LET vCod_Ret='00000';			END IF;
			IF(vStipo='c')THEN
				LET vCod_Ret='00001';			END IF;
			IF(vBanco='137')THEN
				LET vCod_Ret='00001';			END IF;
		ELSE
				LET vCod_Ret='00002'; --No existe el bin
		END IF
		
		
		RETURN vCod_Ret,vBanco;
		
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cons_estatus_disp(pIdEmp char(3),pCteEmpresa char(9),pArchivo char(20) )
returning char(5),char(50);

	-- Autor: Francisco Rodríguez
	-- Objetivo: Obtiene el código de retorno de la dispersión
	-- Solicitó: Mauricio Leon
	-- Fecha: 01/11/2011

--DECLARACION DE VARIABLES
	DEFINE vCodRet CHAR(5);
	DEFINE sql_err INTEGER ;
	DEFINE vValor INTEGER;
	DEFINE cMensaje CHAR(50);

	--INICIALIZAR VALORES A VARIABLES;
	LET vCodRet='00000';
	LET vValor=0;
	LET cMensaje='';

	--SET debug FILE TO "/home/informix/ivonne/sp_cons_estatus_disp.out";
	--Trace ON;

	BEGIN
	 on exception set sql_err
        if vCodRet <> 0 then
            let vCodRet = sql_err;

			 return vCodRet,'';
        end if;
    	end exception;

	SET LOCK MODE TO WAIT ;
	SET ISOLATION DIRTY READ ;

	SELECT codret,mensaje INTO vCodRet,cMensaje FROM bdibpi:"informix".tmp_disp_err
	WHERE id_empresa=pIdEmp AND num_cte=pCteEmpresa AND nom_arch=pArchivo;

	DELETE FROM bdibpi:"informix".tmp_disp_err  WHERE id_empresa=pIdEmp AND num_cte=pCteEmpresa AND nom_arch=pArchivo;


	RETURN vCodRet,cMensaje;

END;
END PROCEDURE;

create procedure "informix".sp_dispersionprogramada_bpi(pidempresa char(3),pnumcte char(9),pnombrearchivo char(20))
returning char(5);

    DEFINE vsqlerr          INTEGER;
    DEFINE vcodret          CHAR(5);
	DEFINE cFolio 			CHAR(16);
	DEFINE cMensaje 		CHAR(50);

	LET vsqlerr = 0;
    LET vcodret = "000";
	LET cFolio = '';
	LET cMensaje = " ";

	--SET debug FILE TO "/home/informix/ivonne/sp_dispersionprogramada_bpi.out";
	--Trace ON;

    begin

    on exception set vsqlerr
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
			insert into bdibpi:"informix".tmp_disp_err(id_empresa ,num_cte ,nom_arch,codret,mensaje,f_registro)values(pidempresa,pnumcte,pnombrearchivo,vcodret,cMensaje,current);
            return vcodret;
        end if;
    end exception;

    call sp_cargadividearchivonomina_bpi(pnombrearchivo)
		returning vcodret, cFolio, cMensaje;

    IF 	vcodret <> "00000" THEN
		LET cMensaje = 'ERROR AL EJECUTAR LA APLICACION';
	ELSE
		LET cMensaje = 'LA APLICACION SE EJECUTO EXITOSAMENTE';
	END IF;

	insert into bdibpi:"informix".tmp_disp_err(id_empresa ,num_cte ,nom_arch,codret,mensaje,f_registro)values(pidempresa,pnumcte,pnombrearchivo,vcodret,cMensaje,current);

    return vcodret;

    END;

end procedure;

CREATE PROCEDURE "informix".sp_dispersiontraspasomovtos_bpi(cNombreArchivo CHAR(30))
RETURNING CHAR(5);

--Declaracion de variables
DEFINE cCodRet            	    	CHAR(5);
DEFINE iSqlError            	    INTEGER;
DEFINE iIsamErr            	    	INTEGER;
DEFINE iEmpleado           	    	INTEGER;
DEFINE iNumRegMov           	    INTEGER;
DEFINE iNumRegEnc           	    INTEGER;

LET cCodRet  = '00000';
LET iSqlError  = 0;
LET iIsamErr = 0;
LET iEmpleado = 0;
LET iNumRegMov = 0;
LET iNumRegEnc = 0;

--*********************************************
--SET DEBUG FILE TO '/home/informix/ivonne/sp_dispersiontraspasomovtos_bpi.out';
--TRACE ON;
--*********************************************

BEGIN
	ON EXCEPTION SET iSqlError, iIsamErr
		IF iSqlError != 0 THEN
				LET cCodRet = iSqlError;
				RETURN cCodRet;
		END IF;
    END EXCEPTION;

	INSERT INTO bdicheq:sc_nominamovimientoshist (nombre_archivo,num_empleado,apell_paterno,apell_materno,nombres,cuenta_abono,importe,concepto,status)
	SELECT nombre_archivo,num_empleado,apell_paterno,apell_materno,nombres,cuenta_abono,importe,concepto,status
	FROM bdicheq:sc_nominamovimientos_bpi
	WHERE nombre_archivo = cNombreArchivo;

	LET iNumRegMov = DBINFO("sqlca.sqlerrd2");

	INSERT INTO bdicheq:sc_nominaencabezadosumariohist (empresa,fecha_gen,folio_archivo,nombre_archivo,sentido,cuenta_cargo,fecha_aplicacion,
	total_registros,importe_tot,status,	fecha_insert,importe_aplicado,importe_no_aplicado,folio_acuserecibo,folio_dispersion,iva,comision,
	fecha_aplicado,hora_aplicado)
	SELECT empresa,fecha_gen,folio_archivo,nombre_archivo,sentido,cuenta_cargo,fecha_aplicacion,total_registros,importe_tot,status,
	fecha_insert,importe_aplicado,importe_no_aplicado,folio_acuserecibo,folio_dispersion,iva,comision,fecha_aplicado,hora_aplicado
	FROM bdicheq:sc_nominaencabezadosumario_bpi
	WHERE nombre_archivo = cNombreArchivo;
	
	LET iNumRegEnc = DBINFO("sqlca.sqlerrd2");

	IF iNumRegMov <= 0 OR iNumRegEnc <= 0 THEN
		LET cCodRet = '00001';
	ELSE
		DELETE FROM bdicheq:sc_nominamovimientos_bpi WHERE nombre_archivo = cNombreArchivo;
		DELETE FROM bdicheq:sc_nominaencabezadosumario_bpi WHERE nombre_archivo = cNombreArchivo;
	END IF;

 RETURN cCodRet;
END
END PROCEDURE



;

CREATE PROCEDURE "informix".sp_consultarctasxproductomoral(pNumcte CHAR(20), pProd CHAR(4))
	RETURNING
		CHAR(6) 	AS COD_RET,
		CHAR(20)   	AS CUENTA_MORAL;
					
		---DECLARACIONES
		DEFINE iSqlErr					INTEGER;    
		DEFINE iNRows					INTEGER;    
		DEFINE cCodRet         			CHAR(6);				
		DEFINE cCuentaMoral         	CHAR(20);							
			
		---INICIALIZACIONES
		LET iSqlErr						= 0;    
		LET iNRows						= 0;    
		LET cCodRet         			= '000000';				
		LET cCuentaMoral         		= '';				
					
	BEGIN
		
		ON EXCEPTION SET iSqlErr
		   IF iSqlErr != 0 THEN
			  LET cCodRet = iSqlErr;
			  RETURN cCodRet,TRIM(NVL(cCuentaMoral,''));
		   END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		--SET DEBUG FILE TO '/home/sysifx/SPsPAYAN/sp_consultarctasxproductomoral.out';
		--TRACE ON;
		
		IF TRIM(NVL(pNumcte,'')) = '' THEN
			LET cCodRet = '000001';			RETURN cCodRet, TRIM(NVL(cCuentaMoral,''));
		END IF;
		
		FOREACH
			--SE OBTIENE LAS CUENTAS CON PRODUCTOS PARA PERSONA MORAL.					
			SELECT a.cuenta
			INTO cCuentaMoral
			FROM bdicheq:"informix".sc_maechq a INNER JOIN bdicheq:"informix".sc_prodctemoral b ON (a.producto = b.producto)
			WHERE a.num_cte = pNumcte
			AND a.status_cta <> '2'
			AND a.producto = CASE WHEN pProd = "" THEN a.producto  ELSE pProd END
			
			--SE RETORNA INFORMACION.
			RETURN cCodRet, TRIM(NVL(cCuentaMoral,'')) WITH RESUME;
		END FOREACH
		
		--SE VALIDA QUE REGRESE INFORMACION EL PROCEDIMIENTO.
		LET iNRows = dbinfo("sqlca.sqlerrd2");				
		
		IF iNRows = 0 THEN
			LET cCodRet = "000002";			RETURN cCodRet, TRIM(NVL(cCuentaMoral,''));
		END IF;	
		
	END;
	
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que obtiene las cuentas de productos pertenecientes a personas morales', 
'AUTOR: Guadalupe Payan ',
'FECHA: Octubre 2011',
'VERSION: 20111003.1522',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_integra_suspenso_pba(pempresa CHAR(3),psistema CHAR(2),pfecha DATE)
    RETURNING CHAR(5);

    DEFINE GLOBAL vgcodigo_mn           CHAR(2)     DEFAULT ' ';
    DEFINE GLOBAL vg_sistema            CHAR(2)     DEFAULT ' ';
    DEFINE GLOBAL vgtransacc_t1         CHAR(4)     DEFAULT ' ';
    DEFINE GLOBAL vgtransacc_t2         CHAR(4)     DEFAULT ' ';
    DEFINE GLOBAL vgcta_iva             CHAR(20)    DEFAULT ' ';
    DEFINE GLOBAL vgcta_itr             CHAR(20)    DEFAULT ' ';
    DEFINE GLOBAL vgtransacc_corresp    CHAR(4)     DEFAULT ' ';
    
    DEFINE vcodret          CHAR(5);
    DEFINE vsqlerr          INTEGER;
	DEFINE vfecha_valida    DATE;

	DEFINE vidsc_suspenso   INTEGER; 
    DEFINE vsecuencia       INTEGER;
    DEFINE vsucursal 		CHAR(4);
    DEFINE vsuccta 			CHAR(4);
	DEFINE vcancelad 		CHAR(1);
    DEFINE vccmayor 		CHAR(10);
    DEFINE vccsub 			CHAR(10);
    DEFINE vccsubsub 		CHAR(10);
    DEFINE vccssubsub 		CHAR(10);
    DEFINE vccsssubsub 		CHAR(10);
    DEFINE vsector 			CHAR(10);
    DEFINE vauxiliar 		CHAR(9);
    DEFINE vproducto 		CHAR(4);
    DEFINE vtransacc 		CHAR(4);
	DEFINE vsectorca 		CHAR(2);
	
    DEFINE vtot_cargo 		MONEY(14,2);
    DEFINE vtot_abono 		MONEY(14,2);
	DEFINE vmonto_tot       MONEY(14,2);
    DEFINE vmoneda 			CHAR(2);
    DEFINE vdescripcion 	CHAR(30);
	
    DEFINE vc_ccmayor        CHAR(4);
    DEFINE vc_ccsub          CHAR(2);
    DEFINE vc_ccsubsub       CHAR(2);
    DEFINE vc_ccsssub        CHAR(2);
    DEFINE vc_ccssssub       CHAR(2);
    DEFINE vc_sector         CHAR(2);
    DEFINE va_ccmayor        CHAR(4);
    DEFINE va_ccsub          CHAR(2);
    DEFINE va_ccsubsub       CHAR(2);
    DEFINE va_ccsssub        CHAR(2);
    DEFINE va_ccssssub       CHAR(2);
    DEFINE va_sector         CHAR(2);
	
    DEFINE vpsucursal 		 CHAR(4);
    DEFINE vpsuccta 		 CHAR(4);
	
	DEFINE vpccmayor         CHAR(4);
    DEFINE vpccsub           CHAR(2);
    DEFINE vpccsubsub        CHAR(2);
    DEFINE vpccssubsub       CHAR(2);
    DEFINE vpccsssubsub      CHAR(2);
    DEFINE vpsector          CHAR(2);
	
	DEFINE vpauxiliar 		  CHAR(9);
	DEFINE vptot_cargo 		  MONEY(14,2);
    DEFINE vptot_abono 		  MONEY(14,2);
    DEFINE vpmoneda 		  CHAR(2);
    DEFINE vpdescripcion 	  CHAR(30);
	DEFINE vpciudad           CHAR(3);
	DEFINE vusuario 		  CHAR(8);
	DEFINE vfecha_hoy         DATE;
	DEFINE vpsecuencia        INTEGER;
	DEFINE vaplicapasecap     BOOLEAN;
	DEFINE vmca_aplic 	      CHAR(1);
	
	BEGIN 
	
	ON EXCEPTION SET vsqlerr
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            RETURN vcodret ;
        END IF;
    END EXCEPTION;

	--set debug file to "sp_integra_suspenso.out";
    --trace on;

    LET vcodret  = '000';
	LET vfecha_valida = NULL;

	LET vidsc_suspenso = 0;
	LET vproducto = '';
	LET vtransacc = '';
	LET vsectorca = '';
	LET vsecuencia = '';
	
	LET vc_ccmayor        = ' ';
    LET vc_ccsub          = ' ';
    LET vc_ccsubsub       = ' ';
    LET vc_ccsssub        = ' ';
    LET vc_ccssssub       = ' ';
    LET vc_sector         = ' ';
    LET va_ccmayor        = ' ';
    LET va_ccsub          = ' ';
    LET va_ccsubsub       = ' ';
    LET va_ccsssub        = ' ';
    LET va_ccssssub       = ' ';
    LET va_sector         = ' ';

	LET vusuario 		  = ' ';
	LET vpsucursal 	      = ' ';
	LET vpsuccta 	      = ' ';

	LET vpccmayor         = ' ';
	LET vpccsub           = ' ';
	LET vpccsubsub        = ' ';
	LET vpccssubsub       = ' ';
	LET vpccsssubsub      = ' ';
	LET vpsector          = ' ';
	LET vpauxiliar 	      = ' ';
	LET vptot_cargo 	  = 0;
	LET vptot_abono 	  = 0;
	LET vmonto_tot        = 0;
	LET vpmoneda 	      = ' ';
	LET vpdescripcion     = ' ';
	LET vpciudad          = ' ';
	LET vpsecuencia       = 0;
	
	LET vaplicapasecap    = 'f';
	LET vmca_aplic        = "0";
	
    SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	-- // Extrae parametros globales	
	CALL pasechq_globalvar (pempresa) RETURNING vcodret; 

	
	IF psistema='01' THEN

		IF EXISTS( SELECT COUNT(fecha_valida) FROM bdicheq:sc_suspenso WHERE fecha_captura_fin = pfecha ) THEN
			UPDATE bdicheq:sc_suspenso 
			   SET fecha_captura_fin = null
			 WHERE fecha_captura_fin = pfecha;
		END IF
		
		SELECT MIN(fecha_valida) INTO vfecha_valida FROM bdicheq:sc_suspenso WHERE fecha_captura_fin IS NULL;
		
		IF vfecha_valida IS NULL THEN
			
			RETURN vcodret;
			
		ELSE
		
			UPDATE bdicheq:sc_suspenso 
			   SET (usuario_sus, control_poliza_sus,fecha_captura_sus) = 
		           ((SELECT usuario,control_poliza,fecha_captura 
				       FROM bdicont:co_poliza 
					  WHERE empresa = pempresa
					    AND usuario='chqinfor'
						AND control_poliza > 0 
						AND fecha_captura = pfecha
						AND moneda IS NOT NULL))
			 WHERE fecha_valida = pfecha;
			 
		END IF
		
		TRUNCATE bdicheq:sc_contab;
        TRUNCATE bdicheq:aux_auditerr;
	
		FOREACH
			SELECT idsc_suspenso,secuencia,sucursal,succta,cancelad,ccmayor,ccsub,ccsubsub,ccssubsub,ccsssubsub,sector,auxiliar,producto,transacc,sectorca,tot_cargo,tot_abono,moneda,descripcion
			  INTO vidsc_suspenso,vsecuencia,vsucursal,vsuccta,vcancelad,vccmayor,vccsub,vccsubsub,vccssubsub,vccsssubsub,vsector,vauxiliar,vproducto,vtransacc,vsectorca,vtot_cargo,vtot_abono,vmoneda,vdescripcion
			  FROM bdicheq:sc_suspenso
			 WHERE fecha_valida = vfecha_valida
			 ORDER BY idsc_suspenso ASC

				SELECT c_ccmayor, c_ccsub, c_ccsubsub, c_ccsssub, c_ccssssub, c_sector,
					   a_ccmayor, a_ccsub, a_ccsubsub, a_ccsssub, a_ccssssub, a_sector
				  INTO vc_ccmayor, vc_ccsub, vc_ccsubsub, vc_ccsssub, vc_ccssssub, vc_sector,
					   va_ccmayor, va_ccsub, va_ccsubsub, va_ccsssub, va_ccssssub, va_sector
				  FROM bdinteg:si_prodtran
				 WHERE empresa = pempresa 
				   AND producto = vproducto 
				   AND sistema = psistema 
				   AND transaccion = vtransacc 
				   AND secuencia = vsecuencia;
				   
					IF (vc_ccmayor =' '  OR vc_ccmayor IS NULL) AND (va_ccmayor = ' ' OR va_ccmayor IS NULL) THEN
						CONTINUE FOREACH;
					END IF
					
					IF vtot_cargo <> 0 THEN -- cancelacion de poliza suspenso

						INSERT INTO bdicheq:sc_contab VALUES (pempresa, vsecuencia, vsucursal, vsuccta, vccmayor,vccsub,vccsubsub,
															  vccssubsub,vccsssubsub,vsector,vauxiliar,0,vtot_cargo,
															  vmoneda,vdescripcion) ; 
															  
															  
					ELSE

						INSERT INTO bdicheq:sc_contab VALUES (pempresa, vsecuencia, vsucursal, vsuccta, vccmayor,vccsub,vccsubsub,
															  vccssubsub,vccsssubsub,vsector,vauxiliar,vtot_abono,0,
														      vmoneda,vdescripcion) ; 
					END IF

					LET vaplicapasecap = 't';
					
					IF vtot_cargo <> 0 THEN
						LET vmonto_tot = vtot_cargo;

						CALL extrae_cont(pempresa,vsecuencia,vmonto_tot,vsucursal,vproducto,vmoneda,vtransacc,vsectorca,vcancelad,vsuccta,vdescripcion) 
						RETURNING vcodret;
						
						IF vcodret <> "000" THEN 
							RETURN vcodret;
						END IF
						
					END IF

		END FOREACH

		IF vaplicapasecap = 't' THEN
		
		    CALL auditor(pempresa) RETURNING vcodret;
		
			IF vcodret = "000" THEN 
		
				LET vusuario = "ctassuca";
			    CALL pasecont(pempresa,pfecha,vfecha_valida,vusuario) RETURNING vcodret;
				
				IF vcodret = "000" THEN 
				
					UPDATE bdicheq:sc_suspenso 
					   SET (usuario_fin, control_poliza_fin, fecha_captura_fin) = 
		                   ((SELECT usuario,control_poliza,fecha_captura 
							   FROM bdicont:co_poliza 
							  WHERE empresa = pempresa
					            AND usuario='ctassuca'
						        AND control_poliza > 0 
						        AND fecha_captura = pfecha
						        AND moneda IS NOT NULL))
			        WHERE fecha_valida = vfecha_valida;

				END IF
			
			END IF

			END IF
		
	END IF
	
    RETURN vcodret;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".elimina_movshistduplicados_1( pempresa CHAR(3), pFecha DATE )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vempieza         SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vSerialDuplicado INTEGER;
    DEFINE vmin_serial      INTEGER;
    DEFINE vmax_serial      INTEGER;
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO REALIZADO SATISFACTORIAMENTE';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vempieza     = -1;
    LET ven_transacc = 0; 
    
    LET vSerialDuplicado = 0;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/elimina_movshistduplicados_1.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vSerialDuplicado;
        END IF;
    END EXCEPTION;

ON EXCEPTION IN (-243)
        LET vcodret1 = sql_err;
        LET vcodret2 = isam_err;
        LET vcodret3 = desc_err;
        LET vSerialDuplicado = vSerialDuplicado;
END EXCEPTION WITH RESUME;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/elimina_movshistduplicados_1.out";
    --- TRACE ON;
    
    set optimization high;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 20;
    
    SELECT {+INDEX(bdicheq:"informix".sc_movhis_old idx_movhisnew6_old)} 
           num_serial, COUNT(*) cuantos
      FROM bdicheq:"informix".sc_movhis_old
     WHERE fech_alt = pFecha
     GROUP BY 1
      INTO TEMP tmp_seriales1 WITH NO LOG;
    CREATE INDEX idx_tmpser1 ON tmp_seriales1(cuantos) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_seriales1;
      
    SELECT num_serial  
      FROM tmp_seriales1 
     WHERE cuantos > 1
      AND num_serial >= 342335395
       AND num_serial < 343807243
      INTO TEMP tmp_duplicados1 WITH NO LOG;
    CREATE INDEX idx_tmpdupl ON tmp_duplicados1(num_serial) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_duplicados1;

    FOREACH WITH HOLD 
        SELECT num_serial
          INTO vSerialDuplicado
          FROM tmp_duplicados1
           
        IF vempieza = -1 THEN
            LET vempieza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        DELETE {+INDEX(bdicheq:"informix".sc_movhis_old idx_movhisnew6_old)} 
               bdicheq:"informix".sc_movhis_old
         WHERE fech_alt = pfecha
           AND num_serial = vSerialDuplicado;
        
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        COMMIT WORK;
        LET vcontador2 = 0;
        LET ven_transacc = 0;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vSerialDuplicado;

END PROCEDURE;

