    -- // TABLA PARA REPORTAR LAS CUENTAS POR INFORMAR
    CREATE TEMP TABLE repctasxinformar(
        empresa     char(30)    not null,
        num_cte     char(20)    not null,
        fecha_nac   char(10),    
        reg_fiscal  char(1),
        tpo_dep     char(4),
        tpo_cuenta  char(2),
        producto    char(40),
        bancaxint   char(1),
        nomina      char(1),
        deposito    char(1),
        cheques     char(1),
        ahorro      char(1),
        credito     char(1),
        bolsa       char(1),
        compensa    char(1),
        valores     char(1),
        dispersion  char(1),
        fondos      char(1),
        tesoreria   char(1),
        otros       char(1),
        fecha_alta  char(10),
        ipab        char(1),
        moneda      char(1),
        tasa        char(1) ) WITH NO LOG;
    CREATE INDEX idx_repctaxinf ON repctasxinformar(num_cte) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE repctasxinformar;
    
    -- // TABLA PARA REPORTAR LAS CUENTAS POR INFORMAR
    CREATE TEMP TABLE repsdosctasxinformar(
