                IF vSumaTasas > 0 THEN
                    LET vTasa1 = vTasaa / vSumaTasas;
                ELSE
                    LET vTasa1 = 0;
                END IF;
                
                LET vTasa2 = vTasa1 * vIndice;
                INSERT INTO tmp_tasas2 VALUES(vIndice, vTasa2);
                LET vIndice = vIndice + 1;
            END WHILE; 
            
