                      INTO vSdoInicial
                      FROM bdicheq:"informix".sc_sdodiarioc_2011 
                     WHERE cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
                       AND aniomes = vPeriodo::integer - 1;
                ELIF vMes = '12' THEN
                    SELECT SUM(NVL(capvig30, 0))
                      INTO vSdoInicial
                      FROM bdicheq:"informix".sc_sdodiarioc_2011 
                     WHERE cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
                       AND aniomes = vPeriodo::integer - 1;
                END IF;
            END IF;
            
            IF vSdoInicial is null THEN
                LET vSdoInicial = 0;
            END IF;
           
            -- // ABONOS 
            SELECT NVL(SUM(a.monto_tot), 0)
              INTO vDepositosOld3
              FROM bdicheq:"informix".sc_movhis_old3 a,
                   bdinteg:"informix".si_transacc b
             WHERE a.empresa = pEmpresa
               AND a.cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
               AND a.fech_alt >= vFechaConsMovhisOld3
               AND a.fech_alt < vFechaConsMovhisOld2
               AND YEAR(a.fech_alt) = vAnio
               AND MONTH(a.fech_alt) = vMes
               AND a.cancelad <> 'S'
               AND a.transacc = b.numero
               AND b.se_emite_edocta = 'S'
               AND b.naturaleza = 'A'
               AND b.numero <> '0250';
               
            IF vDepositosOld3 is null THEN
                LET vDepositosOld3 = 0;
            END IF;
                   
            SELECT NVL(SUM(a.monto_tot), 0)
              INTO vDepositosOld2
              FROM bdicheq:"informix".sc_movhis_old2 a,
                   bdinteg:"informix".si_transacc b
             WHERE a.empresa = pEmpresa
               AND a.cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
               AND a.fech_alt >= vFechaConsMovhisOld2
               AND a.fech_alt < vFechaConsMovhisOld
               AND YEAR(a.fech_alt) = vAnio
               AND MONTH(a.fech_alt) = vMes
               AND a.cancelad <> 'S'
               AND a.transacc = b.numero
               AND b.se_emite_edocta = 'S'
               AND b.naturaleza = 'A'
               AND b.numero <> '0250';
               
            IF vDepositosOld2 is null THEN
                LET vDepositosOld2 = 0;
            END IF;
               
            SELECT NVL(SUM(a.monto_tot), 0)
              INTO vDepositosOld
              FROM bdicheq:"informix".sc_movhis_old a,
                   bdinteg:"informix".si_transacc b
             WHERE a.empresa = pEmpresa
               AND a.cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
               AND a.fech_alt >= vFechaConsMovhisOld
               AND a.fech_alt < vFechaFin
               AND YEAR(a.fech_alt) = vAnio
               AND MONTH(a.fech_alt) = vMes
               AND a.cancelad <> 'S'
               AND a.transacc = b.numero
               AND b.se_emite_edocta = 'S'
               AND b.naturaleza = 'A'
               AND b.numero <> '0250';
               
            IF vDepositosOld is null THEN
                LET vDepositosOld = 0;
            END IF;
            
            LET vDepositos = vDepositosOld + vDepositosOld2 + vDepositosOld3;
               
            -- // CARGOS 
            SELECT NVL(SUM(a.monto_tot), 0)
              INTO vCargosOld3
              FROM bdicheq:"informix".sc_movhis_old3 a,
                   bdinteg:"informix".si_transacc b
             WHERE a.empresa = pEmpresa
               AND a.cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
               AND a.fech_alt >= vFechaConsMovhisOld3
               AND a.fech_alt < vFechaConsMovhisOld2
               AND YEAR(a.fech_alt) = vAnio
               AND MONTH(a.fech_alt) = vMes
               AND a.cancelad <> 'S'
               AND a.transacc = b.numero
               AND b.se_emite_edocta = 'S'
               AND b.naturaleza = 'C'
               AND b.numero <> '0232';
               
            IF vCargosOld3 is null THEN
                LET vCargosOld3 = 0;
            END IF;
               
            SELECT NVL(SUM(a.monto_tot), 0)
              INTO vCargosOld2
              FROM bdicheq:"informix".sc_movhis_old2 a,
                   bdinteg:"informix".si_transacc b
             WHERE a.empresa = pEmpresa
               AND a.cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
               AND a.fech_alt >= vFechaConsMovhisOld2
               AND a.fech_alt < vFechaConsMovhisOld
               AND YEAR(a.fech_alt) = vAnio
               AND MONTH(a.fech_alt) = vMes
               AND a.cancelad <> 'S'
               AND a.transacc = b.numero
               AND b.se_emite_edocta = 'S'
               AND b.naturaleza = 'C'
               AND b.numero <> '0232';
               
            IF vCargosOld2 is null THEN
                LET vCargosOld2 = 0;
            END IF;
               
            SELECT NVL(SUM(a.monto_tot), 0)
              INTO vCargosOld
              FROM bdicheq:"informix".sc_movhis_old a,
                   bdinteg:"informix".si_transacc b
             WHERE a.empresa = pEmpresa
               AND a.cuenta IN(SELECT cuenta FROM tmp_ctasxinf)
               AND a.fech_alt >= vFechaConsMovhisOld
               AND a.fech_alt < vFechaFin
               AND YEAR(a.fech_alt) = vAnio
               AND MONTH(a.fech_alt) = vMes
               AND a.cancelad <> 'S'
               AND a.transacc = b.numero
               AND b.se_emite_edocta = 'S'
               AND b.naturaleza = 'C'
               AND b.numero <> '0232';
               
            IF vCargosOld is null THEN
                LET vCargosOld = 0;
            END IF;
               
            LET vCargos = vCargosOld3 + vCargosOld2 + vCargosOld;
            LET vSdoFinal = ((vSdoInicial + vDepositos) - vCargos);
            
            CREATE TEMP TABLE tmp_tasas( numero integer not null, tasa decimal(6,2) not null ) WITH NO LOG;
            CREATE TEMP TABLE tmp_tasas2( numero integer not null, tasa   decimal(6,2) not null ) WITH NO LOG;
            
            LET vNumero = 0;
            
            FOREACH
                SELECT cuenta
                  INTO vCuenta
                  FROM tmp_ctasxinf
                  
                SELECT NVL(SUM(tasa_aplicada), 0)
                  INTO vTasaOld3
                  FROM bdicheq:"informix".sc_movhis_old3
                 WHERE empresa = pEmpresa
                   AND cuenta = vCuenta
                   AND fech_alt >= vFechaConsMovhisOld3
                   AND fech_alt < vFechaConsMovhisOld2
                   AND YEAR(fech_alt) = vAnio
                   AND MONTH(fech_alt) = vMes
                   AND cancelad <> 'S'
                   AND transacc = '3276';
                   
                SELECT NVL(SUM(tasa_aplicada), 0)
                  INTO vTasaOld2
                  FROM bdicheq:"informix".sc_movhis_old2
                 WHERE empresa = pEmpresa
                   AND cuenta = vCuenta
                   AND fech_alt >= vFechaConsMovhisOld2
                   AND fech_alt < vFechaConsMovhisOld
                   AND YEAR(fech_alt) = vAnio
                   AND MONTH(fech_alt) = vMes
                   AND cancelad <> 'S'
                   AND transacc = '3276';
                   
                SELECT NVL(SUM(tasa_aplicada), 0)
                  INTO vTasaOld
                  FROM bdicheq:"informix".sc_movhis_old
                 WHERE empresa = pEmpresa
                   AND cuenta = vCuenta
                   AND fech_alt >= vFechaConsMovhisOld
                   AND fech_alt < vFechaFin
                   AND YEAR(fech_alt) = vAnio
                   AND MONTH(fech_alt) = vMes
                   AND cancelad <> 'S'
                   AND transacc = '3276';
                   
                IF vTasaOld3 is null THEN
                    LET vTasaOld3 = 0;
                END IF;
                
                IF vTasaOld2 is null THEN
                    LET vTasaOld2 = 0;
                END IF;
                
                IF vTasaOld is null THEN
                    LET vTasaOld = 0;
                END IF;
                   
                LET vTasa = vTasaOld3 + vTasaOld2 + vTasaOld;
                LET vTasa = vTasa * 100;
                LET vNumero = vNumero + 1;
                
                INSERT INTO tmp_tasas VALUES(vNumero, vTasa);
            END FOREACH;
            
            CREATE INDEX idx_tmptasauno ON tmp_tasas(numero) USING BTREE;
            UPDATE STATISTICS MEDIUM FOR TABLE tmp_tasas;
            
            SELECT SUM(tasa)
              INTO vSumaTasas
              FROM tmp_tasas;
                  
            SELECT COUNT(*)
              INTO vCuantos
              FROM tmp_tasas;
              
            LET vIndice = 1;
            
            WHILE vIndice <= vCuantos 
                SELECT tasa
                  INTO vTasaa
                  FROM tmp_tasas
                 WHERE numero = vIndice;
                
                IF vSumaTasas > 0 THEN
                    LET vTasa1 = vTasaa / vSumaTasas;
                ELSE
                    LET vTasa1 = 0;
                END IF;
                
                LET vTasa2 = vTasa1 * vIndice;
                INSERT INTO tmp_tasas2 VALUES(vIndice, vTasa2);
                LET vIndice = vIndice + 1;
            END WHILE; 
            
            CREATE INDEX idx_tmptasados ON tmp_tasas2(numero) USING BTREE;
            UPDATE STATISTICS MEDIUM FOR TABLE tmp_tasas2;
            
            SELECT SUM(tasa)
              INTO vTasaInteres
              FROM tmp_tasas2;
            
            INSERT INTO repsdosctasxinformar(periodo, empresa, num_cte, sdo_minimo, abonos, cargos, sdo_inicial, sdo_final,  tasa)
            VALUES(vPeriodo, vEmpresa, vNumCte, 0.00, vDepositos, vCargos, vSdoInicial, vSdoFinal, vTasaInteres);
            
            DROP TABLE tmp_tasas;
            DROP TABLE tmp_tasas2;
        END FOREACH;
            
        -- // GUARDA DATOS EN TABLA PARA DESCARGARLOS
        INSERT INTO repctasxinformar VALUES
        (vEmpresa, vNumCte, vFechaNacim, vRegFiscal, vTipoDepositante, vTipoCta, vNomProducto, vBPI, vNomina, vDeposito, vCheques, vAhorro, vCredito, vContCasaBolsa, 
         vContCompensacion, vContCustodiaValores, vContDispNom, vContConcentracion, vContGestionTeso, vOtrosContratos, vFechaApertura, vAseguradoIPAB, vMoneda, vTipoTasaInt);
         
        DROP TABLE tmp_ctasxinf;
        LET vContador1 = vContador1 + 1;
    END FOREACH;
    
    END;
    
    RETURN vCodRet1, vCodRet2, vCodRet3, vContador1;
    
END PROCEDURE;

create procedure "informix".colateral(pempresa char(3),
                           pusuario    char(8),
                           pfuncion    char(1),
                           pcuenta     char(20),
                           pcta_col1   char(20),
                           pcta_col2   char(20),
                           pcta_col3   char(20),
                           pcta_col4   char(20),
                           pcta_col5   char(20))

   returning char(5);

   define cod_ret char(5);
   define madicionado, vadicionado, vmodificado char(5);
   define vstatus_cta char(1);
   define v_cal_int_chq char(1);
   define col char(20);
   define v_long_cta char(2);
   define longitud smallint;
   define vcuenta, mcuenta, mcta_col char(20);
   define msecuencia, num_sec, i , longiud smallint;
   define mfecha_alta, vfecha_alta, vfecha_mod, fecha date;
   define sql_err integer;
   define v_usuario char(8);
-- ****************************************************************************
-- Inicializa variables
-- ****************************************************************************
let cod_ret = "000";

begin
   on exception set sql_err
      if sql_err <> 0 then
         let cod_ret = sql_err;
         return cod_ret;
      end if;
   end exception;

-- ****************************************************************************
-- Valida el tipo de funcion a realizar A = alta, C = cambio
-- ****************************************************************************
if pfuncion = "A" or pfuncion = "C" then
else
   let cod_ret = "116";
   return cod_ret;
end if

-- ****************************************************************************
-- Valida la informacion de entrada
-- ****************************************************************************
if pusuario   = "" or
   pcuenta    = "" or
   pcta_col1   = "" then
   let cod_ret = "110";
   return cod_ret;
end if
select ejecutivo into v_usuario from bdinteg:si_ejecut
   where ejecutivo = pusuario;
if v_usuario <> pusuario then
   let cod_ret = "106";
   return cod_ret;
end if
if (pcta_col2 = "" and pcta_col3 <> "") or
   (pcta_col3 = "" and pcta_col4 <> "") or
   (pcta_col4 = "" and pcta_col5 <> "") then
   let cod_ret = "117";
   return cod_ret;
end if

-- ****************************************************************************
-- Validar de acuerdo a la funcion si debe o no existir en la tabla sc_colateral
-- ****************************************************************************
let col = "";
for i = 1 to 5
    if i = 1 then
       let col = pcta_col1;
    elif i = 2 then
       let col = pcta_col2;
    elif i = 3 then
       let col = pcta_col3;
    elif i = 4 then
       let col = pcta_col4;
    elif i = 5 then
       let col = pcta_col5;
    end if;
    if col = "0" or col is null or col = " " then
    else
       select cuenta, cta_col, adicionado, fecha_alta
              into mcuenta, mcta_col, madicionado, mfecha_alta
       from sc_colateral
       where empresa = pempresa and cuenta  = pcuenta and
             cta_col = col;
       if pfuncion = "A" then
          if mcuenta is null and mcta_col is null then
             select count(*) into msecuencia from sc_colateral
                where empresa = pempresa and cuenta = pcuenta;
             let num_sec = msecuencia;
             let num_sec = num_sec + i;
             if num_sec > 5 then
                let cod_ret = "119";
                return cod_ret;
             end if
          else
             let cod_ret = "108";
             return cod_ret;
          end if
       else
          if mcuenta = pcuenta and mcta_col = col then
             let msecuencia = 0;
          else
             let cod_ret = "109";
             return cod_ret;
          end if
       end if
    end if
end for;

-- ****************************************************************************
-- Validar que exista la cuenta eje en la tabla sc_maechq
-- ****************************************************************************
if pfuncion = "A" then
   select cuenta, status_cta
          into vcuenta, vstatus_cta
   from sc_maechq
   where empresa = pempresa and cuenta = pcuenta;
   if vcuenta = pcuenta then
   else
      let cod_ret = "100";
      return cod_ret;
   end if
   if vstatus_cta in("2","6","7") then
      let cod_ret = "200";
      return cod_ret;
   elif vstatus_cta = "3" then
      let cod_ret = "307";
      return cod_ret;
   end if
end if

-- ****************************************************************************
-- Validar que exista la cuenta colateral en la tabla sc_maechq
-- ****************************************************************************
let col = "";
for i = 1 to 5
    if i = 1 then
       let col = pcta_col1;
    elif i = 2 then
       let col = pcta_col2;
    elif i = 3 then
       let col = pcta_col3;
    elif i = 4 then
       let col = pcta_col4;
    elif i = 5 then
       let col = pcta_col5;
    end if;
    if col = "" or col = "0" or
       col is null then
    else
       let vcuenta = "";
       let vstatus_cta = "";
       select cuenta, status_cta
              into vcuenta, vstatus_cta
       from sc_maechq
       where empresa = pempresa and cuenta = col;
       if vcuenta = col then
       else
          let cod_ret = "107";
          return cod_ret;
       end if
       if vstatus_cta in("2","6","7") then
          let cod_ret = "200";
          return cod_ret;
       elif vstatus_cta = "3" then
          let cod_ret = "307";
          return cod_ret;
       end if
    end if
end for

 select fecha_hoy into fecha from sc_fechas where empresa = pempresa;

if pfuncion = "A" then
   let vadicionado = pusuario;
   let vfecha_alta = fecha;
   let vmodificado = "";
   let vfecha_mod  = "";
end if;
-- begin work;
if pfuncion = "C" then
   let vadicionado = madicionado;
   let vfecha_alta = mfecha_alta;
   let vmodificado = pusuario;
   let vfecha_mod  = fecha;
   delete from sc_colateral where empresa = pempresa and cuenta = pcuenta;
end if
let col = "";
for i = 1 to 5
    if i = 1 then
       let col = pcta_col1;
    elif i = 2 then
       let col = pcta_col2;
    elif i = 3 then
       let col = pcta_col3;
    elif i = 4 then
       let col = pcta_col4;
    elif i = 5 then
       let col = pcta_col5;
    end if;
    if col = "" or
       col is null then
    else
       if msecuencia is null then
          let msecuencia = 0;
       end if
       let msecuencia = msecuencia + 1;
       insert into sc_colateral
       values (pempresa,pcuenta, col, msecuencia, vadicionado, vfecha_alta,
               vmodificado, vfecha_mod);
    end if;
end for;
-- commit work;

-- ****************************************************************************
-- Graba la cuenta eje con cuentas colaterales en el Maestro de Cheques
-- ****************************************************************************
update sc_maechq
   set (colateral) = ("S")
   where empresa = pempresa and cuenta = pcuenta;
return cod_ret;
end
end procedure;

create procedure "informix".conbloqueo(pempresa char(3),
                                       pcuenta  char(20),
                                       pultreg  smallint)
returning char(5),char(2),money(14,2),char(8),date,char(5);

    define vcodret       char(5);
    define vsqlerr       integer;
    define vconreg       smallint;
    define vcodbloq      char(2);
    define vimporte      money(14,2);
    define vusuario      char(8);
    define vfechbloq     date;
    define vclave        char(5);
    define vstatus_cta   char(1);
    
    begin
    
    on exception set vsqlerr
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
            return vcodret,vcodbloq,vimporte,vusuario,vfechbloq,vclave;
        end if;
    end exception;

    let vcodret = "000";
    let vconreg = 0;
    let vcodbloq = " ";
    let vimporte = 0;
    let vusuario = " ";
    let vfechbloq = "";
    let vclave = " ";

    select status_cta 
      into vstatus_cta
      from sc_maechq
     where empresa = pempresa 
       and cuenta = pcuenta;
       
    if vstatus_cta is null then
        let vcodret = "100";
        return vcodret,vcodbloq,vimporte,vusuario,vfechbloq,vclave;
    end if;

    if vstatus_cta in('2','6','7') then
        let vcodret = "200";
        return vcodret,vcodbloq,vimporte,vusuario,vfechbloq,vclave;
    end if;

    foreach
        select motivo,importe,usuario,fecha,clave
          into vcodbloq,vimporte,vusuario,vfechbloq,vclave
          from sc_histbloq
         where empresa = pempresa 
           and cuenta = pcuenta 
           and tipo_mov = "B" and status_blo = "B"
        order by fecha
        
        let vconreg = vconreg + 1;
        
        if vconreg <= pultreg then
            continue foreach;
        end if
        
        return vcodret,vcodbloq,vimporte,vusuario,vfechbloq,vclave with resume;
    end foreach
    end
end procedure;

create procedure "informix".cons_cta(pempresa char(3),
                                     pcuenta char(20),
                                     pmoneda char(02))
returning char(5);

    define w_codret    char(5);
    define w_cuenta    char(20);
    define w_statuscta char(1);
    define w_moneda    char(2);
    define sql_err     integer;

    --- Inicializa Variables de Salida
    let w_codret    = "000";
    
    begin
    
    on exception set sql_err
        if sql_err <> 0 then
            let w_codret = sql_err;
            return w_codret;
        end if
    end exception;

    --- Valida que la Cuenta o la moneda no sea Blanco
    if pcuenta = " " or pcuenta is null or pmoneda = " " or pmoneda is null then
        let w_codret = "110";
        return w_codret;
    end if

    ---- Valida que Exista la Cuenta de Cheques
    select status_cta,divisa 
      into w_statuscta, w_moneda
      from sc_maechq mc, 
           sc_producto pr
     where mc.empresa = pempresa 
       and cuenta = pcuenta 
       and mc.empresa = pr.empresa 
       and mc.producto = pr.producto;
    
    if w_statuscta is null then
        let w_codret = "100";
        return w_codret;
    end if

    if w_statuscta in("2","6","7") then
        let w_codret = "200";
        return w_codret;
    end if

    if w_statuscta = "3" then
        let w_codret = "300";
        return w_codret;
    end if

    if w_moneda <> pmoneda then
        let w_codret = "905";
        return w_codret;
    end if

    return w_codret;
    
    end
    
end procedure;

CREATE PROCEDURE "informix".creciente_proy_cierre( pempresa  CHAR(3),
                                                   pcuenta   CHAR(20),
                                                   pproducto CHAR(4),
                                                   pmonto    MONEY(14,2),
                                                   pinstrucc CHAR(2) )
returning CHAR(5);

    -- ##################################################################################
    -- creciente_proy_cierre
    -- Version              1.0.0
    -- Objetivo:            Registra la proyeccion de una cuenta de cheques en el cierre
    -- Supuestos:           Ninguno
    -- Creado por:
    -- ModIFicado por:      Alejandro Rueda Sanchez
    -- Ultima Modificacion: Abril - 2008
    --                      Creación de SPL
    -- ##################################################################################

    -- // Definicion de variables
    DEFINE vcodret     CHAR(5);
    DEFINE vsucursal   CHAR(4);
    DEFINE vusuario    CHAR(8);
    DEFINE vtasatotal  DECIMAL(4,2);
    DEFINE vfecha_ini  DATE;
    DEFINE vfecha_fin  DATE;
    DEFINE vfecha_hoy  DATE;
    DEFINE vtasa       DECIMAL(4,2);
    DEFINE vmonto_int  MONEY(14,2);
    DEFINE vmonto_tot  MONEY(14,2);
    DEFINE i           SMALLINT;
    DEFINE vtipo_tasa  CHAR(1);
    DEFINE vmontoprom  DECIMAL(14,2);
    DEFINE vtisr	      DECIMAL(9,6);
    DEFINE sql_err     INTEGER;
    DEFINE vint_acum   DECIMAL(14,2);

    -- // Inicializacion de Variables
    LET vcodret    = "000";
    LET vsucursal  = "0000";
    LET vusuario   = "informix";

    LET vfecha_ini = "";
    LET vfecha_fin = "";
    LET vtasa      = 0;
    LET vmonto_int = 0;
    LET vmontoprom = 0;
    LET vmonto_tot = pmonto;
    LET vfecha_hoy = "";
    LET vtasa      = "";
    LET vtipo_tasa = "";
    LET vtisr      = 0;
    LET sql_err    = 0;
    
    BEGIN
        
    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET vcodret = sql_err;
            RETURN vcodret ;
        END IF;
    END EXCEPTION;
    
    --- set debug file to "creciente_proy_cierre.out";
    --- trace on;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 2;
    
    IF TRIM(pproducto) = "" or pmonto = 0 THEN
        LET vcodret = "110";
        RETURN vcodret;
    END IF

    LET i = 1;
    LET vint_acum = 0;

    FOREACH
        EXECUTE FUNCTION sp_proyeccionsc(pempresa, vsucursal, vusuario, pproducto, pmonto, pinstrucc)
        INTO vcodret,vfecha_ini,vfecha_fin, vtasa, vmonto_int, vtasatotal, vmonto_tot, vmontoprom, vtisr
        
        IF trim(vcodret) <> "000" THEN
            RETURN vcodret;
        END IF;
        
        SELECT tipo_tasa
          INTO vtipo_tasa
          FROM bdinteg:si_tasa_mes
         WHERE valor_tasa = vtasa
           AND mes = i;
            
        IF vtipo_tasa <> "P" THEN
            LET vint_acum = vint_acum + vmonto_int;
        ELSE
            LET vmonto_int = vmonto_int - vint_acum;
        END IF
        
        INSERT INTO sc_tasa_variable (empresa, cuenta, inicio_periodo, fin_periodo, tipo_tasa, valor_tasa, int_acum, isr, tasa_isr)
        VALUES (pempresa, pcuenta, vfecha_ini, vfecha_fin, vtipo_tasa, vtasa, vmonto_int, vmontoprom, vtisr);
        
        LET i = i +1;
    END FOREACH;

    UPDATE sc_maenoc
       SET fecha_mod = vfecha_fin
     WHERE empresa = pempresa
       AND cuenta = pcuenta;

    END;
    
    RETURN vcodret;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_asignar_direccion_envio(pEmpresa char(3), pCuenta char(20), pDirEnvio smallint)
        RETURNING char(5);

    -- Realizo   : Javier Humberto Calderon Zazueta
    -- Actividad : Asignar la direccion de envio
    -- Solicitó  : Mauricio Leon Ibarra
    -- Fecha     : 22/03/2010

   DEFINE vCodret   char(5);
   DEFINE sql_err integer;

	ON EXCEPTION SET sql_err
	   IF sql_err <> 0 THEN
		LET vCodret = sql_err;
		RETURN vCodret;
	   END IF;
	END EXCEPTION;

	LET vCodret = '000';
	
	BEGIN
		UPDATE sc_maechq SET direcc_envio = pDirEnvio WHERE empresa = pEmpresa AND cuenta = pCuenta;
		RETURN vCodret;
	END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_cons_ctascan(pempresa    char(10),
                                             psucursal  char(10),
                                             pfecha         date,
                                             pfecha1         date,
                                             pcontador   integer)

--RETURNING CHAR(5), CHAR(20), VARCHAR(104), MONEY(14,2);
--DSB 17/01/2012
--RETURNING CHAR(5), CHAR(20), CHAR(104), CHAR(16);
RETURNING CHAR(5), CHAR(20), CHAR(104), CHAR(16), DATE, DATE;

DEFINE vcodret             char(5);
DEFINE vcuenta            char(20);
DEFINE vnombre        varchar(104);
DEFINE vcliente           char(20);
DEFINE vmontoaper      money(14,2);
DEFINE vsqlerr            integer;
DEFINE scod_ret            char(5);
DEFINE vcontador           integer;
--DSB 17/01/2012
DEFINE vFecha_Aper         date;
DEFINE vFecha_Canc         date;


LET vcuenta     = "";
LET vnombre     = "";
LET vcliente    = "";
LET vmontoaper  = 0;
LET scod_ret    = "000";
--DSB 17/01/2012
LET vFecha_Aper = "";
LET vFecha_Canc = "";


    --SET debug file to "/tmp/sp.out";
    --TRACE on;
	
	SET LOCK MODE TO WAIT 3;	

    BEGIN
    ON EXCEPTION SET vsqlerr
       IF vsqlerr != 0 THEN
          LET scod_ret = vsqlerr;
		  --DSB 17/01/2012
          --RETURN vcodret, vcuenta, vnombre,vmontoaper;
		  RETURN vcodret, vcuenta, vnombre, vmontoaper, vFecha_Aper, vFecha_Canc;

       END IF;
    END EXCEPTION;

        
   LET vcodret = "000";
   LET vcontador = 0;

   FOREACH
           SELECT  {index (bdicheq:"informix".sc_mechq ix174_3)} mq.cuenta ,  trim(sc.nombre1) || " " || trim(sc.nombre2) || " " ||
                trim(sc.apell_paterno)|| " " || trim(sc.apell_materno)|| " " ||
                trim(razon_social) AS nombre, mq.sdo_actual,
				mc.fecha_alta, mq.fec_cancelac   --DSB 17/01/2012
           INTO vcuenta, vnombre, vmontoaper,
		        vFecha_Aper, vFecha_Canc  --DSB 17/01/2012
           FROM bdinteg:"informix".si_cliente sc, bdicheq:"informix".sc_maechq mq, 
		        bdicheq:"informix".sc_maenoc mc   --DSB 17/01/2012
                WHERE mq.empresa = sc.empresa AND
                      mq.num_cte = sc.numcte AND
                      mq.empresa  = trim(pempresa) AND
                      mq.producto  = '1900' AND
                      mq.sucursal  = trim(psucursal) AND
                      mq.status_cta  = 2  AND
                      --mq.fec_cancelac= pfecha
                      mq.fec_cancelac >= pfecha AND
                      mq.fec_cancelac <= pfecha1
				  AND mq.empresa = mc.empresa     --DSB 17/01/2012
				  AND mc.cuenta = mq.cuenta       --DSB 17/01/2012
              ORDER BY mq.cuenta
           LET vcontador = vcontador +1;

           IF vcontador <= pcontador THEN
              CONTINUE FOREACH;
           ELSE
		      --DSB 17/01/2012
              --RETURN vcodret, vcuenta, vnombre,vmontoaper with resume;
			  RETURN vcodret, vcuenta, vnombre, vmontoaper, vFecha_Aper, vFecha_Canc with resume;			  
           END IF 
	     
        END FOREACH;
END;
END PROCEDURE
DOCUMENT
'Se agregan parámetros de retorno: Fecha de Apertura y Fecha de Cancelación',
'AUTOR : Nancy Sevilla Camacho',
'FECHA : 17/01/2012';

CREATE PROCEDURE "informix".sp_dispersionnominavalidacionestatus_bpi( pCuenta CHAR(20),
                                                                  pNumeroEmpresa CHAR(3),
                                                                  pFechaGeneracion CHAR(10),
                                                                  pFolioArchivo INTEGER,
                                                                  pFechaActual CHAR(10),
                                                                  pHoraActual CHAR (8),
                                                                  pNombreArchivo CHAR(17),
                                                                  pNumeroEmpleado CHAR(10),
                                                                  pImporteEmpleado MONEY(18,2),
                                                                  pImporteNoAbonado MONEY(18,2),
                                                                  piTipoEmpresa		CHAR(1) )
RETURNING CHAR(3),CHAR(1),CHAR(1),MONEY(18,2),CHAR(4),CHAR(4);

    DEFINE vcodret          CHAR(3);
    DEFINE cEstatusCuenta   CHAR(1);
    DEFINE cSucursalAbono   CHAR(4);
    DEFINE cSucursalCargo   CHAR(4);
    DEFINE cMotivo          CHAR(2);
    DEFINE cConsulta        CHAR(1);
    DEFINE iExiste          INTEGER;
    DEFINE iAceptab         INTEGER;
    DEFINE iSqlerr          INTEGER;
    DEFINE iBandera         INTEGER;

    Begin

    ON EXCEPTION SET iSqlerr
        IF iSqlerr <> 0 THEN
            Let vcodret = iSqlerr;
            RETURN vcodret,cEstatusCuenta,cConsulta,NVL(pImporteNoAbonado,'0.00'),cSucursalCargo,cSucursalAbono;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    --Set Debug File To '/home/informix/ivonne/sp_dispersionnominavalidacionestatus.out';
    --Trace On;

    LET vcodret = "000";
    LET cEstatusCuenta	 = "";
    LET cSucursalAbono = "";
    LET cSucursalCargo	= "";
    LET cMotivo = "";
    LET cConsulta = "";
    LET iExiste = 0;
    LET iAceptab = 0;
    LET iBandera = 0;

    IF  pCuenta  <> "" AND pNumeroEmpresa <> "" AND pFechaGeneracion <> "" AND pFolioArchivo <> 0 AND pFechaActual <> "" AND pHoraActual <> "" THEN
        LET iBandera = 1;
        LET pImporteNoAbonado = '0.00';
    ELSE
        IF pCuenta  <> ""  AND pNombreArchivo <> "" AND pNumeroEmpleado <> "" AND NOT pImporteEmpleado IS NULL  AND NOT pImporteNoAbonado IS NULL AND piTipoEmpresa <> "" THEN
            LET iBandera = 2;
        END IF
    END IF;

    IF iBandera <> 1 AND iBandera <> 2 THEN
        LET vcodret = '805';
    END IF

    /* INICIO de Consulta para la cuenta eje */
    IF iBandera = 1 THEN
        Let cEstatusCuenta = '';
        Let cSucursalCargo = '';

        SELECT status_cta, sucursal,motivo
          INTO cEstatusCuenta, cSucursalCargo, cMotivo
          FROM bdicheq:sc_maechq
         WHERE empresa = '001'
           AND cuenta = pCuenta;

        /* La Cuenta esta Cancelada */
        IF cEstatusCuenta = '2' THEN
            Let vcodret = "815";

             /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
            UPDATE bdicheq:sc_nominaencabezadosumario_bpi
               SET status = '8',
                   fecha_aplicado = pFechaActual,
                   hora_aplicado = pHoraActual
             WHERE empresa = pNumeroEmpresa
               AND fecha_gen = pFechaGeneracion
               AND folio_archivo = pFolioArchivo;
        END IF

        IF cEstatusCuenta = '3' THEN   -- La Cuenta esta Bloqueada

            SELECT "1"
              INTO iExiste
              FROM sc_ctabloqueo
             WHERE cuenta = pCuenta;

            IF iExiste = "1" THEN

                SELECT opcion
                  INTO iAceptab
                  FROM sc_ctabloqueo
                  WHERE cuenta = pCuenta;

                IF iAceptab = 4 THEN
                    Let vcodret = "820";

                    /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
                    UPDATE bdicheq:sc_nominaencabezadosumario_bpi
                       SET status = '9',
                           fecha_aplicado = pFechaActual,
                           hora_aplicado = pHoraActual
                     WHERE empresa = pNumeroEmpresa
                       AND fecha_gen = pFechaGeneracion
                       AND folio_archivo = pFolioArchivo;
                END IF;

                IF iAceptab = 3 THEN
                    Let vcodret = "820";

                    /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
                    UPDATE bdicheq:sc_nominaencabezadosumario_bpi
                       SET status = '9',
                           fecha_aplicado = pFechaActual,
                           hora_aplicado = pHoraActual
                     WHERE empresa = pNumeroEmpresa
                       AND fecha_gen = pFechaGeneracion
                       AND folio_archivo = pFolioArchivo;
                END IF;
            ELSE
                /* Selecciono el campo cargo de sc_bloqueo, para saber si el tipo de bloqueo admite o no cargos */
                SELECT cargo
                  INTO cConsulta
                  FROM sc_bloqueo
                 WHERE codigo=cMotivo;

                IF cConsulta = 'N' THEN
                    Let vcodret = "820";

                    /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
                    UPDATE bdicheq:sc_nominaencabezadosumario_bpi
                       SET status = '9',
                           fecha_aplicado = pFechaActual,
                           hora_aplicado = pHoraActual
                     WHERE empresa = pNumeroEmpresa
                       AND fecha_gen = pFechaGeneracion
                       AND folio_archivo = pFolioArchivo;
                END IF
            END IF
        END IF
    END IF  /* FIN de Consulta para la cuenta eje */

    /* INICIO de Consulta para la cuenta Empleado */
    IF iBandera = 2 THEN
        Let cEstatusCuenta = '';
        Let cSucursalAbono = '';
        LET  cConsulta = "S";

        SELECT status_cta, sucursal,motivo
          INTO cEstatusCuenta, cSucursalAbono,cMotivo
          FROM bdicheq:sc_maechq
         WHERE empresa = '001'
           AND cuenta = pCuenta;

        IF cEstatusCuenta = '2' THEN
            LET  cConsulta = "N";

            /* Cuenta Cancelada */
            UPDATE bdicheq:sc_nominamovimientos_bpi
               SET status = cEstatusCuenta
             WHERE nombre_archivo = pNombreArchivo
               AND num_empleado = pNumeroEmpleado;

            IF piTipoEmpresa = 2 THEN
                Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
            END IF
        END IF

        IF cEstatusCuenta = '3' THEN
            SELECT "1"
              INTO iExiste
              FROM sc_ctabloqueo
             WHERE cuenta = pCuenta;

            IF iExiste = "1" THEN

                SELECT opcion
                  INTO iAceptab
                  FROM sc_ctabloqueo
                 WHERE cuenta = pCuenta;

                IF iAceptab = 4 THEN
                    LET cConsulta = "N";
                    Let vcodret = "820";

                    /* Cuenta Bloqueada */
                    UPDATE bdicheq:sc_nominamovimientos_bpi
                       SET status = cEstatusCuenta
                     WHERE nombre_archivo = pNombreArchivo
                       AND num_empleado = pNumeroEmpleado;

                    IF piTipoEmpresa = 2 THEN
                        Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
                    END IF
                END IF;

                IF iAceptab = 2 THEN
                    LET cConsulta = "N";
                    Let vcodret = "820";

                    /* Cuenta Bloqueada */
                    UPDATE bdicheq:sc_nominamovimientos_bpi
                       SET status = cEstatusCuenta
                     WHERE nombre_archivo = pNombreArchivo
                       AND num_empleado = pNumeroEmpleado;

                    IF piTipoEmpresa = 2 THEN
                        Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
                    END IF
                END IF;
            ELSE
                /* Selecciono el campo Abono de sc_bloqueo, para saber si el tipo de bloqueo admite o no Abonos */
                SELECT abono
                  INTO cConsulta
                  FROM sc_bloqueo
                 WHERE codigo = cMotivo;

                IF cConsulta = 'N' THEN
                    Let vcodret = "820";

                    /* Cuenta Bloqueada */
                    UPDATE bdicheq:sc_nominamovimientos_bpi
                       SET status = cEstatusCuenta
                     WHERE nombre_archivo = pNombreArchivo
                       AND num_empleado = pNumeroEmpleado;

                    IF piTipoEmpresa = 2 THEN
                        Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
                    END IF
                END IF
            END IF
        END IF
    END IF  /* FIN de Consulta para la cuenta Empleado */

    RETURN vcodret,cEstatusCuenta,cConsulta,pImporteNoAbonado,cSucursalCargo,cSucursalAbono;

    END

END Procedure

DOCUMENT
'DESCRIPCION: Genera las validaciones para el estatus de la cuenta a consultar para la dispersion de nomina"',
'AUTOR: Jesus Antonio Bastidas Lopez',
'FECHA: Abril de 2009',
'VERSION: 200904',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_generamovtosfecha(pCuenta CHAR(20),
                                                 pFecha_ini date, 
                                                 pFecha_fin date, 
                                                 pSucursal CHAR(4), 
                                                 pMonto MONEY(18,2), 
                                                 pEmpleado CHAR(8), 
                                                 pUsuario CHAR(8), 
                                                 pRegistro INTEGER
												 )

RETURNING CHAR(5),DATE, CHAR(50), CHAR(40), CHAR(16), 
          MONEY(18,2), MONEY(18,2), MONEY(18,2);

    DEFINE cCodRet          CHAR(5);
    DEFINE iSqlErr			INTEGER;
    DEFINE cTransacc		CHAR(50);
    DEFINE cTarjeta			CHAR(16);
    DEFINE cReferencia		CHAR(40);
    DEFINE dFecha_hoy       DATE;
    DEFINE dFecha_alt		DATE;
    DEFINE mSdo_antmov      MONEY(18,2);
    DEFINE cNatu			CHAR(1);
    DEFINE mCargo			MONEY(18,2);
    DEFINE mAbono			MONEY(18,2);
    DEFINE cConsmovhis		CHAR(10);	
    DEFINE cConsmovhisold   CHAR(10);
    DEFINE cConsmovhisold2  CHAR(10);
    DEFINE sCont			SMALLINT;
    DEFINE mMonto_mov		MONEY(18,2);
    DEFINE mSdo_antmovcal   MONEY(18,2);
    DEFINE mMonto_movcal	MONEY(18,2);
    DEFINE cNatu_ant        CHAR(1);
	DEFINE cTrans           CHAR(4) ;
	DEFINE cTrans2          CHAR(4) ;
--	DEFINE cCansela         CHAR(1); DSB 08/11/2011
	DEFINE iNumSerial       INTEGER;
--	DEFINE iContador        INTEGER;  

    LET cCodRet     = "00000";
	LET iSqlErr     = 0;
    LET cTransacc	= "";
    LET cTarjeta	= "";
    LET cReferencia	= "";
    LET dFecha_hoy  = DATE(1);
    LET dFecha_alt  = DATE(1);
    LET mSdo_antmov = 0;
    LET cNatu		= '';
    LET mCargo      = 0;
    LET mAbono 		= 0;
    LET cConsmovhis	= '';
    LET sCont		= 0;
    LET mMonto_mov	= 0;
    LET mSdo_antmovcal = 0;
    LET mMonto_movcal  = 0;
    LET cNatu_ant	= '';
    LET cConsmovhisold	= '';
    LET cConsmovhisold2 = '';
	LET cTrans =  '';
	LET cTrans2 =  '';
--	LET cCansela =  '';  DSB 08/11/2011
	LET iNumSerial =  0;
--	LET iContador  =  0;  
	
	SET LOCK MODE TO WAIT 3;
	
    BEGIN

    ON EXCEPTION SET iSqlErr
        IF cCodRet != 0 THEN
            LET cCodRet = iSqlErr;
            RETURN cCodRet, dFecha_alt, cTransacc, cReferencia,
                   cTarjeta, mCargo, mAbono, mSdo_antmov;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 2;

    --SET DEBUG FILE TO "/respaldosbd/cris/sp_generamovtosfecha.out";
    --TRACE ON;

    IF NOT EXISTS (SELECT cuenta 
                     FROM Bdicheq:"informix".sc_maechq 
                    WHERE empresa= '001' 
                      AND cuenta = pcuenta)THEN    
        LET cCodRet = "10000"; -- // No existe cuenta
        RETURN cCodRet,dFecha_alt,cTransacc,cReferencia,
               cTarjeta, mCargo, mAbono, mSdo_antmov;
    END IF;
    
    IF EXISTS( SELECT {+INDEX(sc_conmovtosfecha idx_conmovtosfecha)} usuario 
                 FROM bdicheq:"informix".sc_conmovtosfecha 
                WHERE usuario = pUsuario) THEN
        DELETE {+INDEX(sc_conmovtosfecha idx_conmovtosfecha)} sc_conmovtosfecha 
         WHERE usuario = pUsuario;
    END IF;
    
    SELECT {+INDEX(sc_fechas idx_fechas1)} fecha_hoy
      INTO dFecha_hoy
      FROM bdicheq:"informix".sc_fechas
     WHERE empresa = '001';

    IF pFecha_fin < dFecha_hoy AND pFecha_ini <= pFecha_fin THEN

        IF pMonto = "" OR pMonto IS NULL THEN
            LET pMonto = 0;
        END IF;

        SELECT valor
          INTO cConsmovhis
          FROM Bdicheq:"informix".sc_param
         WHERE empresa = '001'
           AND codparam = 'fechcon_movhis';
           
        SELECT valor
          INTO cConsmovhisold
          FROM bdicheq:"informix".sc_param
         WHERE empresa = '001'
           AND codparam = 'FechIniCon_movhis_ol';
           
        SELECT valor
          INTO cConsmovhisold2
          FROM bdicheq:"informix".sc_param
         WHERE empresa = '001'
           AND codparam = 'FechaIniMovhisOld2';

		   
        INSERT INTO bdicheq:"informix".sc_conmovtosfecha
        SELECT {+INDEX(sc_movhis idx_movhisnew4)}
               NVL(fech_alt, " "), 
               NVL(TRIM(transacc||' '||descripcion), " "),
               NVL(referencia, " "), 
               NVL(num_tarjeta, " "), 
               NVL(monto_tot, 0), 
               NVL(sdo_cuenta, 0), 
               NVL(naturaleza, " "),
               NVL(fech_hor, " "), 
               pUsuario,
			   NVL(m.cancelad, " "),
			   NVL(num_serial,0)
          FROM bdicheq:"informix".sc_movhis m,
               bdinteg:"informix".si_transacc t
         WHERE m.empresa = "001" 
           AND m.cuenta = pCuenta
           AND m.fech_alt BETWEEN pFecha_ini AND pFecha_fin
           AND m.fech_alt >= cConsmovhis
          --AND m.cancelad <> 'S'
           AND m.transacc = t.numero
           AND m.monto_tot = CASE WHEN pMonto = 0 THEN monto_tot ELSE pMonto END
           AND m.sucursal = CASE WHEN pSucursal = "" THEN sucursal ELSE pSucursal END
           AND m.usuario = CASE WHEN pEmpleado = "" THEN usuario ELSE pEmpleado END
           AND t.empresa = m.empresa
           AND t.numero = m.transacc
           AND t.se_emite_edocta = "S";
		   
        
        INSERT INTO bdicheq:"informix".sc_conmovtosfecha
        SELECT {+INDEX(sc_movhis_old movhis1)}
               NVL(fech_alt, " "), 
               NVL(TRIM(transacc||' '||descripcion), " "),
               NVL(referencia, " "), 
               NVL(num_tarjeta, " "), 
               NVL(monto_tot, 0), 
               NVL(sdo_cuenta, 0), 
               NVL(naturaleza, " "),
               NVL(fech_hor, " "), 
               pUsuario,
			   NVL(m.cancelad, " "),
			   NVL(num_serial,0)
          FROM bdicheq:"informix".sc_movhis_old m,
               bdinteg:"informix".si_transacc t
         WHERE m.empresa = "001" 
           AND m.cuenta = pCuenta
           AND m.fech_alt BETWEEN pFecha_ini AND pFecha_fin
           AND m.fech_alt >= cConsmovhisold
           AND m.fech_alt < cConsmovhis
           --AND m.cancelad <> 'S'
           AND m.transacc = t.numero
           AND m.monto_tot = CASE WHEN pMonto = 0 THEN monto_tot ELSE pMonto END
           AND m.sucursal = CASE WHEN pSucursal = "" THEN sucursal ELSE pSucursal END
           AND m.usuario = CASE WHEN pEmpleado = "" THEN usuario ELSE pEmpleado END
           AND t.empresa = m.empresa
           AND t.numero = m.transacc
           AND t.se_emite_edocta = "S";
           
        INSERT INTO bdicheq:"informix".sc_conmovtosfecha
        SELECT {+INDEX(sc_movhis_old2 movhis1_old2)}
               NVL(fech_alt, " "), 
               NVL(TRIM(transacc||' '||descripcion), " "),
               NVL(referencia, " "), 
               NVL(num_tarjeta, " "), 
               NVL(monto_tot, 0), 
               NVL(sdo_cuenta, 0), 
               NVL(naturaleza, " "),
               NVL(fech_hor, " "), 
               pUsuario,
			   NVL(m.cancelad, " "),
			   NVL(num_serial,0)
          FROM bdicheq:"informix".sc_movhis_old2 m,
               bdinteg:"informix".si_transacc t
         WHERE m.empresa = "001" 
           AND m.cuenta = pCuenta
           AND m.fech_alt BETWEEN pFecha_ini AND pFecha_fin
           AND m.fech_alt >= cConsmovhisold2
           AND m.fech_alt < cConsmovhisold
           --AND m.cancelad <> 'S'
           AND m.transacc = t.numero
           AND m.monto_tot = CASE WHEN pMonto = 0 THEN monto_tot ELSE pMonto END
           AND m.sucursal = CASE WHEN pSucursal = "" THEN sucursal ELSE pSucursal END
           AND m.usuario = CASE WHEN pEmpleado = "" THEN usuario ELSE pEmpleado END
           AND t.empresa = m.empresa
           AND t.numero = m.transacc
           AND t.se_emite_edocta = "S";
		   
           
        INSERT INTO bdicheq:"informix".sc_conmovtosfecha
        SELECT {+INDEX(sc_movhis_old3 movhis1_old3)}
               NVL(fech_alt, " "), 
               NVL(TRIM(transacc||' '||descripcion), " "),
               NVL(referencia, " "), 
               NVL(num_tarjeta, " "), 
               NVL(monto_tot, 0), 
               NVL(sdo_cuenta, 0), 
               NVL(naturaleza, " "),
               NVL(fech_hor, " "), 
               pUsuario,
			   NVL(m.cancelad, " "),
			   NVL(num_serial,0)
          FROM bdicheq:"informix".sc_movhis_old3 m,
               bdinteg:"informix".si_transacc t
         WHERE m.empresa = "001" 
           AND m.cuenta = pCuenta
           AND m.fech_alt BETWEEN pFecha_ini AND pFecha_fin
           AND m.fech_alt < cConsmovhisold2
           --AND m.cancelad <> 'S'
           AND m.transacc = t.numero
           AND m.monto_tot = CASE WHEN pMonto = 0 THEN monto_tot ELSE pMonto END
           AND m.sucursal = CASE WHEN pSucursal = "" THEN sucursal ELSE pSucursal END
           AND m.usuario = CASE WHEN pEmpleado = "" THEN usuario ELSE pEmpleado END
           AND t.empresa = m.empresa
           AND t.numero = m.transacc
           AND t.se_emite_edocta = "S";

        IF pSucursal <> '' OR pMonto <> 0 OR pEmpleado <> '' THEN -- // Valida que los filtros Sucursal, Empleado o monto se hallan utilizado.

            FOREACH  -- // se utilizaron filtros y regresa valores sin calcular saldos.
                SELECT {+INDEX(sc_conmovtosfecha idx_conmovtosfecha)}
                       SKIP pRegistro FIRST 20 
                       NVL(fech_alt, " "),
                       NVL(TRIM(transacc), " "), 
					   SUBSTR(transacc, 1,4),
                       NVL(TRIM(referencia), " "),
                       NVL(TRIM(num_tarjeta), " "), 
                       NVL(monto_mov, 0),
                       NVL(sdo_cuenta, 0), 
                       NVL(TRIM(naturaleza), " "),
					   NVL(num_serial,0)
                  INTO dFecha_alt, cTransacc, cTrans, cReferencia, cTarjeta, mMonto_mov, mSdo_antmov,cNatu, iNumSerial
                  FROM bdicheq:"informix".sc_conmovtosfecha
                 WHERE usuario = pUsuario
			  ORDER BY num_serial
				
				LET cTrans = cTrans;
                
				IF cNatu = 'C' THEN
                    LET mCargo = mMonto_mov;
                    LET mAbono = 0;
                ELSE
                    LET mAbono = mMonto_mov;
                    LET mCargo = 0;
                END IF;
				
		--		LET icontador = 1;  
				
				RETURN cCodRet,dFecha_alt,cTransacc,cReferencia,cTarjeta, mCargo, mAbono, mSdo_antmov WITH RESUME;
            END FOREACH;
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '30000';
				RETURN cCodRet,dFecha_alt,cTransacc,cReferencia,cTarjeta, mCargo, mAbono, mSdo_antmov;
			END IF;	

        ELSE

            FOREACH  -- // Se utilizo solo cuenta y rango de fechas como filtro, por lo tanto se reconstruyen saldos.
               
					SELECT {+INDEX(sc_conmovtosfecha idx_conmovtosfecha)}
						SKIP pRegistro FIRST 20
						NVL(fech_alt, " "),
						NVL(TRIM(transacc), " "),
						SUBSTR(transacc, 1,4),
						NVL(TRIM(referencia), " "),
						NVL(TRIM(num_tarjeta), " "), 
						NVL(monto_mov, 0),
						NVL(sdo_cuenta, 0), 
						NVL(TRIM(naturaleza), " "),
					    NVL(num_serial,0)
						   
					INTO dFecha_alt, cTransacc, cTrans, cReferencia, cTarjeta, mMonto_mov, mSdo_antmov,cNatu, iNumSerial
					FROM Bdicheq:"informix".sc_conmovtosfecha
					WHERE usuario = pUsuario
					AND cancelad <> "S"
					ORDER BY num_serial
				 
				IF sCont =  0 THEN
				
					FOREACH
						SELECT first 1 NVL(sdo_cuenta, 0) 
						INTO  mSdo_antmov
						FROM Bdicheq:"informix".sc_conmovtosfecha
						WHERE usuario = pUsuario
						AND cancelad = "S"
						AND fech_alt = dFecha_alt
						AND num_serial < iNumSerial
					END FOREACH;
					
							
					LET mSdo_antmovcal = mSdo_antmov;
                    LET mMonto_movcal = mMonto_mov;
                    LET cNatu_ant = cNatu;

                    IF cNatu = 'C' THEN
                        LET mCargo = mMonto_mov;
                        LET mAbono = 0.00;
                    ELSE
                        LET mAbono = mMonto_mov;
                        LET mCargo = 0.00;
                    END IF;

                    LET sCont = 1;

					RETURN cCodRet,dFecha_alt,cTransacc,cReferencia,cTarjeta, mCargo, mAbono, mSdo_antmov WITH RESUME;


					CONTINUE FOREACH;
				
				
				END IF;
					
				
				IF cTrans <> "0250" AND cTrans <> "0232"  THEN
					IF cTrans2 <> "0250" AND cTrans2 <> "0232"  THEN
						LET cTrans2 = cTrans;			
						IF cNatu_ant = 'C' THEN
								--Saldo anterior                --Saldo anterior                --Monto Movimiento
							LET mSdo_antmovcal = mSdo_antmovcal - mMonto_movcal;
						--	LET mMonto_movcal = mMonto_mov;  DSB-08/11/2011
						ELSE
							LET mSdo_antmovcal = mSdo_antmovcal + mMonto_movcal;
						--	LET mMonto_movcal = mMonto_mov;  DSB-08/11/2011
						END IF;
					ELSE
						LET cTrans2 = cTrans;
						-- DSB-08/11/2011
						/*IF cNatu_ant = 'C' THEN
							LET mSdo_antmovcal = mSdo_antmovcal;
						--	LET mMonto_movcal = mMonto_mov;
						ELSE
							LET mSdo_antmovcal = mSdo_antmovcal;
						--	LET mMonto_movcal = mMonto_mov;
						END IF;*/
						LET mSdo_antmovcal = mSdo_antmov;		
					END IF;
				ELSE
					
					IF cTrans2 <> "0250" AND cTrans2 <> "0232"  AND cTrans2 <> "" THEN
						LET cTrans2 = cTrans;
						IF cNatu_ant = 'C' THEN
							LET mSdo_antmovcal = mSdo_antmovcal - mMonto_movcal;
						--	LET mMonto_movcal = mMonto_mov;  DSB-08/11/2011
						ELSE
							LET mSdo_antmovcal = mSdo_antmovcal + mMonto_movcal;
						--	LET mMonto_movcal = mMonto_mov;  DSB-08/11/2011
						END IF;
					
					ELSE
						LET cTrans2 = cTrans;
						--DSB-08/11/2011
						/*IF cNatu_ant = 'C' THEN
							--LET mSdo_antmovcal = mSdo_antmovcal;
							LET mSdo_antmovcal = mSdo_antmov;						
						--	LET mMonto_movcal = mMonto_mov;
						ELSE
							--LET mSdo_antmovcal = mSdo_antmovcal;
							LET mSdo_antmovcal = mSdo_antmov;						
							--LET mMonto_movcal = mMonto_mov;
						END IF;*/
						LET mSdo_antmovcal = mSdo_antmov;						
					END IF;
				END IF;
				LET mMonto_movcal = mMonto_mov;
                IF cNatu = 'C' THEN
                    LET mCargo = mMonto_mov;
                    LET mAbono = 0.00;
                ELSE
                    LET mCargo = 0.00 ;
                    LET mAbono = mMonto_mov;	
                END IF;

			--	LET icontador = 1;  
								
                LET cNatu_ant = cNatu;	  
				RETURN cCodRet,dFecha_alt, cTransacc,cReferencia,cTarjeta, mCargo, mAbono, mSdo_antmovcal WITH RESUME;
				

			END FOREACH;
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '30000';
				RETURN cCodRet,dFecha_alt,cTransacc,cReferencia,cTarjeta, mCargo, mAbono, mSdo_antmov;
			END IF;	
			
        END IF;
		
	
    ELSE

        LET cCodRet = '20000';
        
        RETURN cCodRet,dFecha_alt,cTransacc,cReferencia,cTarjeta, mCargo, mAbono, mSdo_antmov;

    END IF;

    END;
    
END PROCEDURE

DOCUMENT
'AUTOR: Abigail Vasavilbazo Cañedo',
'DESCRIPCION: Procedimiento que obtiene los movimientos en un rango de fechas, con filtros por sucursal, monto',
