CREATE PROCEDURE "informix".sp_cancela_tarjetas_efecplus( pcEmpresa  CHAR(3) )
RETURNING CHAR(5)  AS vcCodret1,
          CHAR(5)  AS vcCodret2,
          CHAR(50) AS vcCodret3,
          INTEGER  AS viContador;
    
    DEFINE vcCodret1    CHAR(5);
    DEFINE vcCodret2    CHAR(5);
    DEFINE vcCodret3    CHAR(50);
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE viContador   INTEGER;
    DEFINE vComienza    SMALLINT;
    DEFINE viTransacc   SMALLINT;
    
    DEFINE vcCuenta     CHAR(20);
    DEFINE vcTarjeta    CHAR(16);
    DEFINE vdCapVigAcum DECIMAL(18,2);
    DEFINE vdDiasAcum   SMALLINT;
    DEFINE vdPromedio   DECIMAL(18,2);
    DEFINE vsql         CHAR(500);
    DEFINE vstmt        CHAR(250);
    
    LET vcCodret1 = '000';
    LET vcCodret2 = '000';
    LET vcCodret3 = 'PROCESO FINALIZADO CORRECTAMENTE';
    LET viSqlErr  = 0;
    LET viIsamErr = 0;
    LET vcDescErr = '';
    LET viContador = 0;
    LET vComienza  = 0;
    LET viTransacc = 0;
    
    LET vcCuenta     = '';
    LET vcTarjeta    = '';
    LET vdCapVigAcum = 0.00;
    LET vdDiasAcum   = 0;
    LET vdPromedio   = 0.00;
    LET vsql         = '';
    LET vstmt        = '';
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cancela_tarjetas_efecplus.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodret1 = viSqlErr;
            LET vcCodret2 = viIsamErr;
            LET vcCodret3 = vcDescErr;
            IF viTransacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcCodret1, vcCodret2, vcCodret3, viContador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cancela_tarjetas_efecplus.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasefecplus') THEN
        DROP TABLE ctasefecplus;
    END IF;
    
    CREATE TABLE ctasefecplus( cuenta char(20) not null )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX idx_ctaefp ON ctasefecplus(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/cuentasefecplus.unl DELIMITER ''","'' INSERT INTO ctasefecplus" > /resplogifx/conciliachq/ctasefp.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasefp.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasefecplus;
    
    FOREACH WITH HOLD
        SELECT cuenta 
          INTO vcCuenta
          FROM ctasefecplus
         WHERE cuenta is not null
         
        IF vComienza = -1 THEN
            LET vComienza = 0;
        END IF;
        
        BEGIN WORK;
        LET viTransacc = 1;
         
        FOREACH
            SELECT num_tarjeta
              INTO vcTarjeta
              FROM bdicheq:"informix".sc_tarjeta
             WHERE empresa = pcEmpresa
               AND cuenta = vcCuenta
               AND secuencia > 0
        
            UPDATE bdicheq:"informix".sc_tarjeta
               SET status_tar = 'C'
             WHERE empresa = pcEmpresa
               AND cuenta = vcCuenta
               AND num_tarjeta = vcTarjeta;
               
            UPDATE intercard:"informix".tarjeta
               SET codstatustarjeta = 'CAN'
             WHERE numtarjeta = vcTarjeta;
        END FOREACH;
        
        LET viContador = viContador + 1;
           
        COMMIT WORK;
        LET viTransacc = 0;
        
        LET vcCuenta  = '';
        LET vcTarjeta = '';
    END FOREACH;
    
    END;
    
    RETURN vcCodret1, vcCodret2, vcCodret3, viContador;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_capintafecha( pCuenta CHAR(20), pFecha DATE )
RETURNING  CHAR(10), DECIMAL(14,2), DECIMAL(14,2);

    DEFINE cCodret      CHAR(5);
    DEFINE cCodret2     CHAR(5);
    DEFINE cCodret3     CHAR(50);
    DEFINE cSQL_ERR     INTEGER;
    DEFINE cISAM_ERR    INTEGER;
    DEFINE cDESC_ERR    CHAR(50);
    DEFINE cAnioMes     CHAR(6);
    DEFINE vCapital     DECIMAL(14,2);
    DEFINE vInteres     DECIMAL(14,2);
    DEFINE vdia         CHAR(2);

    LET cCodret   = '000';
    LET cCodret2  = '000';
    LET cCodret3  = '000';
    LET cSQL_ERR  = 0;
    LET cISAM_ERR = 0;
    LET cDESC_ERR = '';
    LET cAnioMes  = '';
    LET vCapital  = 0.00;
    LET vInteres  = 0.00;
    LET vdia      = '';

    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_capintafecha.out';
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET cSQL_ERR, cISAM_ERR, cDESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_capintafecha.err';
        TRACE ON;
        LET cCodret = cSQL_ERR;
        LET cCodret2 = cISAM_ERR;
        LET cCodret3 = cDESC_ERR;
        RETURN cCodret, vCapital, vInteres;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;

    LET vdia = DAY(pFecha);
    LET vdia = TRIM(vdia);
    
    LET cAnioMes = SUBSTR(pFecha,7,4) || SUBSTR(pFecha,1,2);
    LET cAnioMes = cAnioMes;
    
    SELECT {+INDEX(sc_sdodiarioc isdodiario)} 
           DECODE( vdia, '1',  capvig1,  
                         '2',  capvig2,  
                         '3',  capvig3,  
                         '4',  capvig4,  
                         '5',  capvig5,   
                         '6',  capvig6,  
                         '7',  capvig7,
                         '8',  capvig8,  
                         '9',  capvig9, 
                        '10', capvig10, 
                        '11', capvig11, 
                        '12', capvig12, 
                        '13', capvig13, 
                        '14', capvig14, 
                        '15', capvig15, 
                        '16', capvig16, 
                        '17', capvig17, 
                        '18', capvig18, 
                        '19', capvig19, 
                        '20', capvig20, 
                        '21', capvig21, 
                        '22', capvig22, 
                        '23', capvig23,
                        '24', capvig24, 
                        '25', capvig25, 
                        '26', capvig26, 
                        '27', capvig27, 
                        '28', capvig28, 
                        '29', capvig29, 
                        '30', capvig30, 
                        '31', capvig31 ), 
           DECODE( vdia, '1',  intprovnp1,   
                         '2',  intprovnp2,   
                         '3',  intprovnp3,  
                         '4',  intprovnp4,   
                         '5',  intprovnp5, 
                         '6',  intprovnp6, 
                         '7',  intprovnp7, 
                         '8',  intprovnp8,
                         '9',  intprovnp9, 
                        '10', intprovnp10,
                        '11', intprovnp11, 
                        '12', intprovnp12, 
                        '13', intprovnp13, 
                        '14', intprovnp14, 
                        '15', intprovnp15,
                        '16', intprovnp16, 
                        '17', intprovnp17, 
                        '18', intprovnp18, 
                        '19', intprovnp19, 
                        '20', intprovnp20,
                        '21', intprovnp21, 
                        '22', intprovnp22, 
                        '23', intprovnp23, 
                        '24', intprovnp24, 
                        '25', intprovnp25,
                        '26', intprovnp26, 
                        '27', intprovnp27, 
                        '28', intprovnp28, 
                        '29', intprovnp29, 
                        '30', intprovnp30,
                        '31', intprovnp31 ) 
      INTO vCapital, vInteres
      FROM bdicheq:"informix".sc_sdodiarioc 
     WHERE cuenta = pCuenta
       AND aniomes = cAnioMes;
       
    IF vCapital = '' OR vCapital IS NULL THEN
        -- // CUENTA NO EXISTE EN FECHA
        LET cCodret = '100'; 
        LET vCapital = 0.00;
        LET vInteres = 0.00;
    END IF;

    RETURN cCodret, vCapital, vInteres;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultainfocteretieneisr_pag (pCnumCte CHAR(20),pCcuenta CHAR(20),pSanio SMALLINT,pStipo SMALLINT,pSregistros SMALLINT)

--DATOS A REGRESAR---
RETURNING
	CHAR(6),  --CodRet,
	CHAR(60), --Mensaje,
	CHAR(2),  --TipoPersona,
	CHAR(104),--Nombre,
	CHAR(20), --Cuenta,
	CHAR(13), --RFC,
	CHAR(20), --CURP,
	DECIMAL(16, 2), --InteresNomTotal,
	DECIMAL(16, 2), --InteresReal,
	DECIMAL(16, 2), --Perdida,
	DECIMAL(16, 2), --InteresNomExento,
	DECIMAL(16, 2), --RetenInteres,
	CHAR(60), --RazonSocialRetenedor,
	CHAR(13), --RFCRetenedor,
	CHAR(104),--NombreRepLegal,
	CHAR(13), --RepLegalISR,
	CHAR(20); --CURPRepLegal;

	-- DECLARACION DE VARIABLES
	DEFINE cCodRet				CHAR(6);
	DEFINE cTipPer				CHAR(2);
	DEFINE cNumCte				CHAR(20);
	DEFINE cCuenta				CHAR(20);
	DEFINE dIntNominalTot		DECIMAL(16, 2);
	DEFINE dInteresReal			DECIMAL(16, 2);
	DEFINE dPerdida				DECIMAL(16, 2);
	DEFINE dIntNomExento		DECIMAL(16, 2);
	DEFINE dRetenInteres		DECIMAL(16, 2);
	DEFINE cNombreCliente 		CHAR(104);	
	DEFINE cRazonSocialReten	CHAR(60);
	DEFINE cRfcAlterno	 		CHAR(13);
	DEFINE cRfc			 		CHAR(13);
	DEFINE cCurp				CHAR(20);
	DEFINE cRfcRetenedor		CHAR(13);
	DEFINE cNomRepLegalISR		CHAR(104);
	DEFINE cRfcRepLegalISR		CHAR(13);
	DEFINE cCurpRepLegalISR		CHAR(20);	
	DEFINE iNRows 				INTEGER;
	DEFINE iSqlErr 				INTEGER;
	DEFINE cMensaje 			CHAR(60);
	
	
	-- INICIALIZACION DE VARIABLES.
	LET cCodRet 			= '000000';
	LET cTipPer 			= '';
	LET cNumCte				= '';
	LET cCuenta				= '';
	LET dIntNominalTot		= 0.00;
	LET dInteresReal		= 0.00;
	LET dPerdida			= 0.00;
	LET dIntNomExento		= 0.00;
	LET dRetenInteres		= 0.00;
	LET iNRows 				= 0;
	LET cMensaje			= 'EJECUCIÓN REALIZADA EXITOSAMENTE';
	LET cNombreCliente		= '';
	LET cRfcAlterno			= '';
	LET cRfc				= '';
	LET cCurp				= '';
	LET cRfcRetenedor		= '';
	LET cNomRepLegalISR		= '';
	LET cRfcRepLegalISR		= '';
	LET cCurpRepLegalISR	= '';
	LET iSqlErr 			= 0;
	LET cRazonSocialReten	= '';
	
	SET ISOLATION DIRTY READ ;
	SET LOCK MODE TO WAIT 3;

	 -- SET DEBUG FILE TO "/home/sysifx/vlv/sp_consultainfocteretieneisr.out";
	 -- TRACE ON;

BEGIN

	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensaje = 'ERROR NO CONTROLADO, VERIFIQUE';
			RETURN TRIM(cCodRet), TRIM(cMensaje), TRIM(NVL(cTipPer, '')), TRIM(NVL(cNombreCliente, '')), TRIM(NVL(cCuenta, '')),
			       TRIM(NVL(cRfcAlterno, '')), TRIM(NVL(cCurp, '')), NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00),
				   NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00), NVL(dRetenInteres, 0.00), TRIM(NVL(cRazonSocialReten, '')),
				   TRIM(NVL(cRfcRetenedor, '')), TRIM(NVL(cNomRepLegalISR, '')), TRIM(NVL(cRfcRepLegalISR, '')),
				   TRIM(NVL(cCurpRepLegalISR, ''));
		END IF;
	END EXCEPTION;
    
    IF pStipo = 1 THEN
   
		--  SE VALIDAN LOS PARAMETROS DE ENTRADA
		IF NVL(pCnumCte, '') = '' OR NVL(pSanio, 0) = 0 THEN
			LET cCodRet = '000002';
			LET cMensaje = 'FALTAN PARAMETROS PARA LA EJECUCIÓN DEL MODO: CUENTAS';

			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       dIntNominalTot, dInteresReal, dPerdida, dIntNomExento, dRetenInteres, TRIM(cRazonSocialReten),
				   TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR), TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
		END IF
		
		--  SE CONSULTAN LAS CUENTAS RETENIDAS DEL CLIENTE EN UN AÑO ESPECIFICO
		FOREACH		    
			SELECT SKIP pSregistros TRIM(cuenta),interes_nominal_total, interes_real, perdida, interes_nominal_exento, reten_interes
			INTO cCuenta, dIntNominalTot, dInteresReal, dPerdida, dIntNomExento, dRetenInteres
			FROM bdicheq:'informix'.sc_retenisr
			WHERE num_cte = TRIM(pCnumCte)
			AND ejercicio = pSanio
			
			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       dIntNominalTot, dInteresReal, dPerdida, dIntNomExento, dRetenInteres, TRIM(cRazonSocialReten),
				   TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR), TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR) WITH RESUME;
			
		END FOREACH
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000005'; -- NO SE OBTUVO INFORMACION.
			LET cMensaje = 'CLIENTE NO TIENE CUENTAS RETENIDAS PARA EL AÑO RECIBIDO';

			RETURN cCodRet, TRIM(cMensaje), TRIM(NVL(cTipPer, '')), TRIM(NVL(cNombreCliente, '')), TRIM(NVL(cCuenta, '')),
				   TRIM(NVL(cRfcAlterno, '')), TRIM(NVL(cCurp, '')), NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00),
				   NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00), NVL(dRetenInteres, 0.00), TRIM(NVL(cRazonSocialReten, '')),
				   TRIM(NVL(cRfcRetenedor, '')), TRIM(NVL(cNomRepLegalISR, '')), TRIM(NVL(cRfcRepLegalISR, '')),
				   TRIM(NVL(cCurpRepLegalISR, ''));
		END IF;
		
	ELIF pStipo = 2 THEN
	
		--  SE VALIDAN LOS PARAMETROS DE ENTRADA
		IF NVL(pCnumCte, '') = '' OR NVL(pCcuenta, '') = '' OR NVL(pSanio, 0) = 0 THEN
			LET cCodRet = '000002';
			LET cMensaje = 'FALTAN PARAMETROS PARA LA EJECUCIÓN DEL MODO: REPORTE';
			
			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       dIntNominalTot, dInteresReal, dPerdida, dIntNomExento, dRetenInteres, TRIM(cRazonSocialReten),
				   TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR), TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
		END IF		
		
		SELECT TRIM(numcte), TRIM(tpo_persona), TRIM(nombre1)||' '||TRIM(nombre2)||' '||TRIM(apell_paterno)||' '||TRIM(apell_materno) || ' ' || TRIM(razon_social), TRIM(rfc), TRIM(rfc_alterno)
		INTO cNumCte, cTipPer, cNombreCliente, cRfc, cRfcAlterno
		FROM bdinteg:'informix'.si_cliente
		WHERE empresa = '001'
		AND numcte = pCnumCte;
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000004';
			LET cMensaje = 'CLIENTE NO EXISTE';
			
			RETURN cCodRet, TRIM(cMensaje), TRIM(NVL(cTipPer, '')), TRIM(NVL(cNombreCliente, '')), TRIM(NVL(cCuenta, '')),
				   TRIM(NVL(cRfcAlterno, '')), TRIM(NVL(cCurp, '')), NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00),
				   NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00), NVL(dRetenInteres, 0.00), TRIM(NVL(cRazonSocialReten, '')),
				   TRIM(NVL(cRfcRetenedor, '')), TRIM(NVL(cNomRepLegalISR, '')), TRIM(NVL(cRfcRepLegalISR, '')),
				   TRIM(NVL(cCurpRepLegalISR, ''));
		END IF
		
		IF NVL(cRfcAlterno, '') = '' THEN
			LET cRfcAlterno = cRfc;
		END IF
		
		IF cTipPer = '01' THEN
			
			SELECT NVL(curp, '') INTO cCurp
			FROM bdinteg:'informix'.si_ctepf
			WHERE numcte = cNumCte;
			
		END IF
		
	 -- PARA GENERAR EL REPORTE-CONSTANCIA.
		SELECT TRIM(cuenta), interes_nominal_total, interes_real, perdida, interes_nominal_exento, reten_interes
		INTO cCuenta, dIntNominalTot, dInteresReal, dPerdida, dIntNomExento, dRetenInteres
		FROM bdicheq:'informix'.sc_retenisr
		WHERE num_cte = pCnumCte
		AND cuenta = pCcuenta
		AND ejercicio = pSanio;
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000005'; -- NO SE OBTUVO INFORMACION.
			LET cMensaje = 'CLIENTE NO TIENE CUENTAS RETENIDAS PARA EL AÑO RECIBIDO';

			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(NVL(cCuenta, '')), TRIM(cRfcAlterno), TRIM(cCurp),
			       NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00), NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00),
				   NVL(dRetenInteres, 0.00), TRIM(cRazonSocialReten), TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR),
				   TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
		END IF
		
		-- CONSULTAMOS LA RAZON SOCIAL DEL RETENEDOR Y EL RFC DEL RETENEDOR.
		SELECT TRIM(razon_social), TRIM(rfc) INTO cRazonSocialReten, cRfcRetenedor
		FROM  bdinteg:'informix'.si_empresas
		WHERE empresa = '001';
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000003';
			LET cMensaje = 'NO EXISTE LA INFORMACION PARA LA EMPRESA RETENEDORA';

			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00), NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00),
				   NVL(dRetenInteres, 0.00), TRIM(NVL(cRazonSocialReten, '')), TRIM(NVL(cRfcRetenedor, '')), 
				   TRIM(NVL(cNomRepLegalISR, '')), TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
		END IF
		
		SELECT TRIM(valor) INTO cNomRepLegalISR 
		FROM bdinteg:'informix'.si_param 
		WHERE cod_param = '131';
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000003';
			LET cMensaje = 'NO EXISTE LA INFORMACION PARA EL REPRESENTANTE LEGAL';

			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00), NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00),
				   NVL(dRetenInteres, 0.00), TRIM(cRazonSocialReten), TRIM(cRfcRetenedor), TRIM(NVL(cNomRepLegalISR, '')),
				   TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
		END IF
		
		SELECT TRIM(valor) INTO cRfcRepLegalISR 
		FROM bdinteg:'informix'.si_param 
		WHERE cod_param = '132';
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000003';
			LET cMensaje = 'NO EXISTE LA INFORMACION PARA EL REPRESENTANTE LEGAL';

			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00), NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00),
				   NVL(dRetenInteres, 0.00), TRIM(cRazonSocialReten), TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR),
				   TRIM(NVL(cRfcRepLegalISR, '')), TRIM(cCurpRepLegalISR);
		END IF
		
		SELECT TRIM(valor) INTO cCurpRepLegalISR 
		FROM bdinteg:'informix'.si_param 
		WHERE cod_param = '133';
		
		LET iNRows = dbinfo("sqlca.sqlerrd2");
		
		IF iNRows = 0 THEN
			LET cCodRet = '000003';
			LET cMensaje = 'NO EXISTE LA INFORMACION PARA EL REPRESENTANTE LEGAL';

			RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			       NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00), NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00),
				   NVL(dRetenInteres, 0.00), TRIM(cRazonSocialReten), TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR),
				   TRIM(cRfcRepLegalISR), TRIM(NVL(cCurpRepLegalISR, ''));
		END IF
		
		RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			   NVL(dIntNominalTot, 0.00), NVL(dInteresReal, 0.00), NVL(dPerdida, 0.00), NVL(dIntNomExento, 0.00),
			   NVL(dRetenInteres, 0.00), TRIM(cRazonSocialReten), TRIM(cRfcRetenedor), TRIM(cNomRepLegalISR),
			   TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
	ELSE
	
		LET cCodRet = '000001';
		LET cMensaje = 'TIPO DE EJECUCIÓN DESCONOCIDA';
		
		RETURN cCodRet, TRIM(cMensaje), TRIM(cTipPer), TRIM(cNombreCliente), TRIM(cCuenta), TRIM(cRfcAlterno), TRIM(cCurp),
			   dIntNominalTot, dInteresReal, dPerdida, dIntNomExento, dRetenInteres, TRIM(cRazonSocialReten), TRIM(cRfcRetenedor),
			   TRIM(cNomRepLegalISR), TRIM(cRfcRepLegalISR), TRIM(cCurpRepLegalISR);
	END IF
END;
END PROCEDURE
DOCUMENT
'AUTOR: Josue Zepeda',
'FECHA: 30 de Marzo del 2012',
'DESCRIPCION: Procedimiento que consulta la informacion del cliente, ya sea cliente fisico o moral que cuente',
'con retención del ISR.',
'SOLICITO: Alejandro Sánchez',
'VERSION: 20120330.1135',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_obtenercuentascaptacion(p_sEmpresa CHAR(3), p_sNumCliente CHAR(20))
	RETURNING	CHAR(6) AS retorno, 
				CHAR(3) AS empresa, 
				CHAR(20) AS cuenta,
				CHAR(20) AS num_cte,
				CHAR(1) AS tipoCuenta;
	
	DEFINE iSqlErr							INTEGER;
	DEFINE v_sValRetorno					CHAR(6);
	DEFINE v_sEmpresa						CHAR(3);
	DEFINE v_sCuenta						CHAR(20);
	DEFINE v_sNumCliente					CHAR(20);
	DEFINE v_sTipoCuenta					CHAR(1);
	-----------------------------------------------------------------------------
	--Creado por Erick Zamora 05/Agosto/2009
	--	Obtiene las cuentas de Capatacion del cliente especifico
	--Caso de Uso asociado: PCU-bdicheq\CU-0042-ObtenerCuentasCaptación-SPL
	--SET DEBUG FILE TO "/tmp/sp_obtenerCuentasCaptacion.out";
	--TRACE ON;
	-----------------------------------------------------------------------------	
	
	LET v_sValRetorno = '000001';
	LET v_sTipoCuenta = 'D';
	
	BEGIN	
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr,'','','','';
			END IF;
		END EXCEPTION;
		
		--LOS PARAMETROS NO DEBEN SER NULOS
		IF NVL(p_sEmpresa,'')='' OR NVL(p_sNumCliente,'')='' THEN
			RETURN v_sValRetorno,'','','','';
		END IF;
		
		LET p_sNumCliente = LPAD(TRIM(p_sNumCliente),9,'0');
		
		--OBTIENE LAS CUENTAS DE CHEQUES
		FOREACH
			SELECT empresa, cuenta, num_cte
			INTO v_sEmpresa, v_sCuenta, v_sNumCliente
			FROM bdicheq:sc_maechq 			
			WHERE empresa = p_sEmpresa AND num_cte = p_sNumCliente
			
			LET v_sValRetorno = '000000';
			RETURN v_sValRetorno, v_sEmpresa, v_sCuenta, v_sNumCliente, v_sTipoCuenta WITH RESUME;
		END FOREACH;
		--OBTIENE LAS CUENTAS DE INVERSION
		FOREACH
			SELECT DISTINCT empresa, cuenta, num_cte
			INTO v_sEmpresa, v_sCuenta, v_sNumCliente
			FROM bdinvers:sv_maeinv 			
			WHERE empresa = p_sEmpresa AND num_cte = p_sNumCliente
			
			LET v_sValRetorno = '000000';
			RETURN v_sValRetorno, v_sEmpresa, v_sCuenta, v_sNumCliente, v_sTipoCuenta WITH RESUME;
		END FOREACH;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_saldoafecha( pCuenta Char(20), pFecha  Date )
RETURNING Char(10), Decimal(14,2);

    DEFINE cCodret      Char(5);
    DEFINE cCodret2     Char(5);
    DEFINE cCodret3     Char(50);
    DEFINE cSQL_ERR     Integer;
    DEFINE cISAM_ERR    Integer;
    DEFINE cDESC_ERR    Char(50);
    DEFINE cDia         Char(2);
    DEFINE cAnioMes     Char(6);
    DEFINE dSaldo       Decimal(14,2);

    LET cCodret   = '000';
    LET cCodret2  = '000';
    LET cCodret3  = '';
    LET cSQL_ERR  = 0;
    LET cISAM_ERR = 0;
    LET cDESC_ERR = '';
    LET cDia      = '';
    LET cAnioMes  = '';
    LET dSaldo    = 0;

    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_SaldoaFecha.out';
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET cSQL_ERR, cISAM_ERR, cDESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_SaldoaFecha.err';
        TRACE ON;
        LET cCodret  = cSQL_ERR;
        LET cCodret2 = cISAM_ERR;
        LET cCodret3 = cDESC_ERR;
        RETURN cCodret, dSaldo;
    END EXCEPTION;

    LET cDia = substr(pFecha,4,2);
    LET cAnioMes = substr(pFecha,7,4) || substr(pFecha,1,2);
    LET cDia = cDia;
    LET cAnioMes = cAnioMes;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    IF Lpad(cDia,2,'0') = '01' THEN
