    ELIF Lpad(cDia,2,'0') = '26' THEN
        SELECT capvig26 
          INTO dSaldo 
          FROM bdicheq:sc_sdodiarioc 
         WHERE cuenta = pCuenta 
           AND aniomes = cAnioMes;
    ELIF Lpad(cDia,2,'0') = '27' THEN
        SELECT capvig27 
          INTO dSaldo 
          FROM bdicheq:sc_sdodiarioc 
         WHERE cuenta = pCuenta 
           AND aniomes = cAnioMes;
    ELIF Lpad(cDia,2,'0') = '28' THEN
        SELECT capvig28 
          INTO dSaldo 
          FROM bdicheq:sc_sdodiarioc 
         WHERE cuenta = pCuenta 
