    ELIF Lpad(cDia,2,'0') = '31' THEN
        SELECT capvig31 
          INTO dSaldo 
          FROM bdicheq:sc_sdodiarioc 
         WHERE cuenta = pCuenta 
           AND aniomes = cAnioMes;
    ELSE
        -- // FECHA INVALIDA
        LET cCodret = '200'; 
    END IF;

    IF dSaldo = '' OR dSaldo IS NULL THEN
        -- // CUENTA NO EXISTE EN FECHA
        LET cCodret = '100'; 
    END IF;

    RETURN cCodret, dSaldo;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION: Programa para obtener el saldo a una fecha ',
'             determinada de una cuenta de cheques de captacion',
'EJECUTADO O LLAMADO POR: IPAB, etc',
'AUTOR : Armando Mercado',
'FECHA : 15/Octubre/2008',
'VERSION: 1.00.0000',
'BD    : BDICHEQ';

CREATE PROCEDURE "informix".sp_saldopromedioafecha(pCuenta Char(20), pFechaIni Date, pFechaFin Date, pDias integer)
RETURNING Char(10), Decimal(14,2);

    DEFINE cCodret          Char(5);
    DEFINE cCodret2         Char(5);
    DEFINE cCodret3         Char(50);
    DEFINE cSQL_ERR         Integer;   
    DEFINE cISAM_ERR        Integer;
    DEFINE cDESC_ERR        Char(50);
    DEFINE dFecha           Date;
    DEFINE dSaldoDia        Decimal(14,2);
    DEFINE dSaldoPromedio   Decimal(14,2);
     
    LET cCodret        = '000';
    LET cCodret2       = '000';
    LET cCodret3       = '';
    LET cSQL_ERR       = 0; 
    LET cISAM_ERR      = 0;
    LET cDESC_ERR      = '';
    LET dFecha         = pFechaIni;
    LET dSaldoDia      = 0;        
    LET dSaldoPromedio = 0;

    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_SaldoPromedioaFecha.out';
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET cSQL_ERR, cISAM_ERR, cDESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_SaldoPromedioaFecha.err';
        TRACE ON;
        LET cCodret = cSQL_ERR;
        LET cCodret2 = cISAM_ERR;
        LET cCodret3 = cDESC_ERR;
        RETURN cCodret, dSaldoPromedio;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    WHILE dFecha <= pFechaFin
        EXECUTE PROCEDURE bdicheq:"informix".sp_saldoafecha(pCuenta, dFecha) 
        INTO cCodret, dSaldoDia;

        LET dSaldoPromedio = dSaldoPromedio + dSaldoDia;
        LET dFecha = dFecha + 1;
    END WHILE;

    LET dSaldoPromedio = dSaldoPromedio / pDias;

    IF dSaldoPromedio = '' OR dSaldoPromedio IS NULL THEN 
        LET cCodret = '100'; --- CUENTA NO EXISTE EN FECHA
    END IF;

    RETURN cCodret, dSaldoPromedio;  

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION: Programa para obtener el saldo promedio a una', 
'             fecha determinada de una cuenta de cheques Captacion',
'EJECUTADO O LLAMADO POR: IPAB, etc',
'AUTOR : Armando Mercado',
'FECHA : Octubre/2008',
'VERSION: 1.00.0000',
'BD    : BDICHEQ';

CREATE PROCEDURE "informix".sp_consultamovtoscortetienda( pTipo SMALLINT, 
                                                          pTienda SMALLINT, 
                                                          pTipoDeposito CHAR(1), 
                                                          pFechaParcialCoppel DATE, 
                                                          pFechaDeposito DATE, 
                                                          pFolioDeposito CHAR(16), 
                                                          pMontoDeposito INTEGER )
RETURNING INTEGER, INTEGER;

    --- #############################################################################################
    --- ## Modifico: Miguel Olivas                                                                 ##
    --- ## Fecha: 18/nov/2008                                                                      ##
    --- ## se modifica para que no haga la consulta a la tabla historica sc_movhis.                ##
    --- ##                                                                                         ##
    --- ## Modifico: Daniel Zambada                                                                ##
    --- ## Fecha: 21/nov/2008                                                                      ##
    --- ## se modifica para que valide  el retorno cuando no exista el registro con regreso 1 o 3. ##
    --- ##                                                                                         ##
    --- ## Modifico: Daniel Zambada                                                                ##
    --- ## Fecha: 21/may/2009                                                                      ##
    --- ## se modifica para que valide  el monto en la movdia por rango inferior  y superior.      ##
    --- #############################################################################################
    
    DEFINE vCodRet    CHAR(5);
    DEFINE vSqlErr    INTEGER;
    DEFINE vSucursal  CHAR(4);
    DEFINE vCSucursal CHAR(4);
    DEFINE vDeposito MONEY(14,2);
    
    LET vCodRet = '000';
    LET vSqlErr = 0;
    LET vSucursal = '0000';
    LET vCSucursal = '0000';
    LET vDeposito = pMontoDeposito/100;
    
    BEGIN
    
    ON EXCEPTION SET vsqlerr
        IF vSqlErr <> 0 THEN
            LET vCodRet = vSqlErr;
            RETURN vCodRet,vSucursal;
        END IF;
    END EXCEPTION;
	--SET DEBUG FILE TO "/respaldosbd/cris/sp_consultamovtoscortetienda.out";
	--TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF pTipo = 1 THEN
    
        IF EXISTS (SELECT {+INDEX(bdicheq:"informix".sc_consultamovtoscortetienda ind_sc_consultamovtoscortetienda_01)} 
					fechadeposito,foliodeposito,montodeposito 
					FROM "informix".sc_consultamovtoscortetienda 
					WHERE fechadeposito = pFechaDeposito 
					AND foliodeposito = pFolioDeposito 
					AND montodeposito = vDeposito 
					AND estado = 1) THEN
                      
            INSERT INTO bdicheq:"informix".sc_consultamovtoscortetienda(fechadeposito,foliodeposito,montodeposito,tienda,tipodeposito,fechaparcialcoppel,estado,fechamov)
            VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 2, CURRENT);

            LET vCodRet = '2';
            LET vSucursal = '0';
            
        ELSE
            
		/* ###############################################
		IF EXISTS (SELECT fech_alt, folio_suc, monto_tot 
				FROM sc_movdia 
				WHERE fech_alt = pFechaDeposito 
				AND folio_suc = pFolioDeposito 
				AND monto_tot = vDeposito) THEN 
		############################################### */
            
		IF EXISTS ( SELECT {+INDEX(bdicheq:"informix".sc_movdia idx_movdia7a)} 
					fech_alt, folio_suc, monto_tot 
					FROM "informix".sc_movdia 
					WHERE cuenta = '16000000012' 
					AND folio_suc = pFolioDeposito
					AND fech_alt = pFechaDeposito 
					AND monto_tot = vDeposito ) THEN 

				/* ################################
					SELECT nvl(sucursal,'') 
					INTO vCSucursal 
					FROM sc_movdia 
					WHERE fech_alt = pFechaDeposito 
					AND folio_suc = pFolioDeposito 
					AND monto_tot = vDeposito; 
				################################ */
			
				SELECT {+INDEX(bdicheq:"informix".sc_movdia idx_movdia7a)} 
				NVL(sucursal,'') 
				INTO vCSucursal 
				FROM "informix".sc_movdia 
				WHERE cuenta = '16000000012' 
				AND folio_suc = pFolioDeposito
				AND fech_alt = pFechaDeposito 
				AND monto_tot = vDeposito;                 
              

                INSERT INTO bdicheq:"informix".sc_consultamovtoscortetienda(fechadeposito,foliodeposito,montodeposito,tienda,tipodeposito,fechaparcialcoppel,estado,fechamov)
                VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 1, CURRENT);

                LET vCodRet = '1';
                LET vSucursal = vCSucursal;
                
            ELSE

			-- // Se modifica para que no haga la consulta a la tabla historica sc_movhis.
			/* ############################################################################################################
			IF EXISTS (SELECT fech_alt, folio_suc, monto_tot 
				FROM sc_movhis 
				WHERE fech_alt = pFechaDeposito 
				AND folio_suc = pFolioDeposito 
				AND monto_tot = vDeposito) THEN

				SELECT nvl(sucursal,'') 
				INTO vCSucursal 
				FROM sc_movhis 
				WHERE fech_alt = pFechaDeposito 
				AND folio_suc = pFolioDeposito 
				AND monto_tot = vDeposito;        

				INSERT INTO sc_consultamovtoscortetienda(fechadeposito, foliodeposito, montodeposito, tienda, tipodeposito, fechaparcialcoppel, estado, fechamov)
				VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 1, CURRENT);

				LET vCodRet = '1';
				LET vSucursal = vCSucursal;
			ELSE
			############################################################################################################ */
                
                INSERT INTO bdicheq:"informix".sc_consultamovtoscortetienda(fechadeposito,foliodeposito,montodeposito,tienda,tipodeposito,fechaparcialcoppel,estado,fechamov)
                VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 3, CURRENT);
                
                /* ############################################################################
					IF pFechaDeposito::DATE < (select fecha_hoy::DATE from bdicheq:sc_fechas) THEN	     	
						LET vCodRet = '1';
					ELSE
						LET vCodRet = '3';
					END IF;
				############################################################################ */
                
                LET vCodRet = '3';
                LET vSucursal = '0';

               --- END IF; 
            END IF; 
        END IF;
    END IF;

    RETURN vCodRet, vSucursal;
    
    END;
    
END PROCEDURE

DOCUMENT
"Consulta Movimientos de Cortes de Tienda ",
"AUTOR: Saul Ivanhoe",
"FECHA: 26/Febrero/2008",
"BD   : bdicheq",
"VER  : 1.1",
"MODIFICACION: Se igualan consulta a la sc_movdia filtradas por fecha, monto,folio y monto para corregir incidencia en la confirmacicón de los retiros parciales.",
"MODIFICO: Cristian Valentina Aguilar",
"FECHA: 20/Abril/2012",
"BD   : bdicheq",
"VER  : 20120420.1756";

CREATE PROCEDURE "informix".borramovshistold1(pempresa CHAR(3), pcuenta CHAR(20), pfecha DATE)
RETURNING CHAR(5), CHAR(5), INTEGER;

    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vcontador1   INTEGER;
    DEFINE vnum_serial  INTEGER;
    
    LET vcodret1    = '000';
    LET vcodret2    = '000';
    LET vcodret3    = '';
    LET sql_err	    = 0;
    LET isam_err    = 0;
    LET desc_err    = '';
    LET vcontador1  = -1;
    LET vnum_serial = 0;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/borramovshistold1.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/borramovshistold1.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 10;
    
    FOREACH cursor_borra FOR
        SELECT {+INDEX(sc_movhis idx_movhisnew1)} num_serial
          INTO vnum_serial
          FROM sc_movhis
         WHERE empresa = pempresa
           AND cuenta = pcuenta
           AND fech_alt = pfecha
           
        IF vcontador1 = -1 THEN
            LET vcontador1 = 0;
        END IF;
        
        DELETE FROM sc_movhis 
         WHERE CURRENT OF cursor_borra;
         
        LET vcontador1 = vcontador1 + 1;
    END FOREACH;

    END;

    RETURN vcodret1, vcodret2, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtinfctasinactivas( pempresa char(3), pfechaini date, pfechafin date )
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;
     
    DEFINE vcodret1                 char(5);
    DEFINE vcodret2                 char(5);
    DEFINE vsqlerr                  integer;
    DEFINE isam_err                 integer;
    DEFINE vcontador1               integer;
    DEFINE vcontador2               integer;
    DEFINE vcontador3               integer;
    DEFINE ven_transacc             smallint;
    DEFINE vcomienza                smallint;

    DEFINE vfecha_hoy               date;
    DEFINE vfechconmovhis           char(10);
    DEFINE vfechconmovhisold        char(10);
    DEFINE vfechconmovhisold2       char(10);
    DEFINE vfechaconmovhisold3      char(10);
    DEFINE vfechaconmovhisold4      char(10);
    DEFINE vproducto                char(4);
    DEFINE vcuenta                  char(20);
    DEFINE vfecha_alta              date;
    DEFINE vsdo_actual              decimal(18,2);
    DEFINE vfecha_ultima_transacc   date;
    DEFINE vdias                    integer;

    LET vcodret1     = "000";               
    LET vcodret2     = '000';
    LET vsqlerr      = 0;                   
    LET isam_err     = 0;
    LET vcontador1   = 0;                   
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET ven_transacc = 0;                   
    LET vcomienza    = -1;  
       
    LET vfecha_hoy              = ''; 
    LET vfechconmovhis          = '';
    LET vfechconmovhisold       = '';
    LET vfechconmovhisold2      = '';
    LET vfechaconmovhisold3     = '';
    LET vfechaconmovhisold4     = '';
    LET vproducto               = '';
    LET vcuenta                 = '';    
    LET vfecha_alta             = '';
    LET vsdo_actual             = 0.00;    
    LET vfecha_ultima_transacc  = '';
    LET vdias                   = 0;

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_obtinfctasinactivas.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret1 = vsqlerr;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_obtinfctasinactivas.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;

    SELECT valor 
      INTO vfechconmovhis
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'fechcon_movhis';
       
    SELECT valor 
      INTO vfechconmovhisold
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechIniCon_movhis_ol';
       
    SELECT valor 
      INTO vfechconmovhisold2
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechaIniMovhisOld2';
       
    SELECT valor
      INTO vfechaconmovhisold3
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'vfechconmovhisold3';
       
    SELECT valor
      INTO vfechaconmovhisold4
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechaIniMovhisOld4';
       
    CREATE TEMP TABLE tmp_ctasinactivas
    ( 
        producto        CHAR(4), 
        cuenta          CHAR(20), 
        sdo_actual      MONEY(18,2), 
        fecha_ult_mov   DATE 
    ) WITH NO LOG;
    CREATE INDEX idx_ctasinactivas ON tmp_ctasinactivas(cuenta);
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_ctasinactivas;

    -- // CUENTAS DIFERENTES A INVERSION CRECIENTE
    FOREACH WITH HOLD
        SELECT noc.cuenta, noc.fecha_alta, chq.producto, chq.sdo_actual
          INTO vcuenta, vfecha_alta, vproducto, vsdo_actual
          FROM sc_maechq chq,
               sc_maenoc noc
         WHERE chq.producto <> '1100'
           AND chq.status_cta <> '2'
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
           AND noc.fecha_alta BETWEEN pfechaini AND pfechafin

        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        SELECT MAX(fech_alt)
          INTO vfecha_ultima_transacc
          FROM sc_movdia
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND cancelad <> 'S'
           AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
        
        IF vfecha_ultima_transacc is null THEN
        
            SELECT {+INDEX(sc_movhis idx_movhisnew4)}
                   MAX(fech_alt)
              INTO vfecha_ultima_transacc
              FROM sc_movhis
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt >= vfechconmovhis
               AND cancelad <> 'S'
               AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
               
            IF vfecha_ultima_transacc is null THEN
        
                SELECT {+INDEX(sc_movhis_old movhis1)}
                       MAX(fech_alt)
                  INTO vfecha_ultima_transacc
                  FROM sc_movhis_old
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND fech_alt >= vfechconmovhisold
                   AND fech_alt < vfechconmovhis
                   AND cancelad <> 'S'
                   AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                   
                IF vfecha_ultima_transacc is null THEN
                
                    SELECT {+INDEX(sc_movhis_old2 movhis1_old2)}
                           MAX(fech_alt)
                      INTO vfecha_ultima_transacc
                      FROM sc_movhis_old2
                     WHERE empresa = pempresa
                       AND cuenta = vcuenta
                       AND fech_alt >= vfechconmovhisold2
                       AND fech_alt < vfechconmovhisold
                       AND cancelad <> 'S'
                       AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
        
                    IF vfecha_ultima_transacc is null THEN
                    
                        SELECT {+INDEX(sc_movhis_old3 movhis1_old3)}
                               MAX(fech_alt)
                          INTO vfecha_ultima_transacc
                          FROM sc_movhis_old3
                         WHERE empresa = pempresa
                           AND cuenta = vcuenta
                           AND fech_alt >= vfechaconmovhisold3
                           AND fech_alt < vfechconmovhisold2
                           AND cancelad <> 'S'
                           AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                           
                        IF vfecha_ultima_transacc is null THEN
                        
                            SELECT {+INDEX(sc_movhis_old4 movhis1_old4)}
                                   MAX(fech_alt)
                              INTO vfecha_ultima_transacc
                              FROM sc_movhis_old4
                             WHERE empresa = pempresa
                               AND cuenta = vcuenta
                               AND fech_alt >= vfechaconmovhisold4
                               AND fech_alt < vfechaconmovhisold3
                               AND cancelad <> 'S'
                               AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                               
                               
                            IF vfecha_ultima_transacc is null THEN
                    
                                SELECT {+INDEX(sc_movhis_old5 movhis1_old5)}
                                       MAX(fech_alt)
                                  INTO vfecha_ultima_transacc
                                  FROM sc_movhis_old5
                                 WHERE empresa = pempresa
                                   AND cuenta = vcuenta
                                   AND fech_alt < vfechaconmovhisold4
                                   AND cancelad <> 'S'
                                   AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                            
                            END IF;
                               
                        END IF;
        
                    END IF;
                    
                END IF;
                
            END IF;
            
        END IF;
        
        IF vfecha_ultima_transacc is null THEN
            LET vfecha_ultima_transacc = vfecha_alta;
        END IF;
        
        LET vdias = vfecha_hoy - vfecha_ultima_transacc;
        
        IF vdias >= 1095 THEN
            INSERT INTO tmp_ctasinactivas ( producto, cuenta, sdo_actual, fecha_ult_mov )
            VALUES ( vproducto, vcuenta, vsdo_actual, vfecha_ultima_transacc );
            
            LET vcontador2 = vcontador2 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador3 = vcontador3 + 1;

        IF (vcontador3 >= 5000) THEN
            LET vcontador3 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vproducto               = '';
        LET vcuenta                 = '';
        LET vfecha_alta             = '';
        LET vsdo_actual             = 0.00;
        LET vfecha_ultima_transacc  = '';
        LET vdias                   = 0;
    END FOREACH;

    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;

    UPDATE STATISTICS MEDIUM FOR TABLE tmp_ctasinactivas(cuenta);
    
    LET vcomienza = -1;
    
    -- // INVERSIONES CRECIENTES
    FOREACH WITH HOLD
        SELECT chq.cuenta, chq.producto, chq.sdo_actual
          INTO vcuenta, vproducto, vsdo_actual
          FROM sc_maechq chq
         WHERE chq.producto = '1100'
           AND chq.status_cta <> '2'

        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        SELECT fech_alt
          INTO vfecha_alta
          FROM sc_movdia
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND cancelad <> 'S'
           AND transacc = '0202';
           
        IF vfecha_alta is null OR vfecha_alta = '' THEN
        
            SELECT {+INDEX(sc_movhis idx_movhisnew4)}
                   fech_alt
              INTO vfecha_alta
              FROM sc_movhis
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt >= vfechconmovhis
               AND cancelad <> 'S'
               AND transacc = '0202';
               
            IF vfecha_alta is null OR vfecha_alta = '' THEN
            
                SELECT {+INDEX(sc_movhis_old movhis1)}
                       fech_alt
                  INTO vfecha_alta
                  FROM sc_movhis_old
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND fech_alt >= vfechconmovhisold
                   AND fech_alt < vfechconmovhis
                   AND cancelad <> 'S'
                   AND transacc = '0202';
                   
                IF vfecha_alta is null OR vfecha_alta = '' THEN
                
                    SELECT {+INDEX(sc_movhis_old2 movhis1_old2)}
                           fech_alt
                      INTO vfecha_alta
                      FROM sc_movhis_old2
                     WHERE empresa = pempresa
                       AND cuenta = vcuenta
                       AND fech_alt >= vfechconmovhisold2
                       AND fech_alt < vfechconmovhisold
                       AND cancelad <> 'S'
                       AND transacc = '0202';
                       
                    IF vfecha_alta is null OR vfecha_alta = '' THEN
                    
                        SELECT {+INDEX(sc_movhis_old3 movhis1_old3)}
                               fech_alt
                          INTO vfecha_alta
                          FROM sc_movhis_old3
                         WHERE empresa = pempresa
                           AND cuenta = vcuenta
                           AND fech_alt >= vfechaconmovhisold3
                           AND fech_alt < vfechconmovhisold2
                           AND cancelad <> 'S'
                           AND transacc = '0202';
                           
                        IF vfecha_alta is null OR vfecha_alta = '' THEN
                        
                            SELECT {+INDEX(sc_movhis_old4 movhis1_old4)}
                                   fech_alt
                              INTO vfecha_alta
                              FROM sc_movhis_old4
                             WHERE empresa = pempresa
                               AND cuenta = vcuenta
                               AND fech_alt >= vfechaconmovhisold4
                               AND fech_alt < vfechaconmovhisold3
                               AND cancelad <> 'S'
                               AND transacc = '0202';
                               
                            IF vfecha_alta is null OR vfecha_alta = '' THEN
                            
                                SELECT {+INDEX(sc_movhis_old5 movhis1_old5)}
                                       fech_alt
                                  INTO vfecha_alta
                                  FROM sc_movhis_old5
                                 WHERE empresa = pempresa
                                   AND cuenta = vcuenta
                                   AND fech_alt < vfechaconmovhisold4
                                   AND cancelad <> 'S'
                                   AND transacc = '0202';
                                   
                            END IF;   
                            
                        END IF;
                        
                    END IF;
                    
                END IF;
                
            END IF;
            
        END IF;
        
        IF vfecha_alta >= pfechaini AND vfecha_alta <= pfechafin THEN
        
            SELECT MAX(fech_alt)
              INTO vfecha_ultima_transacc
              FROM sc_movdia
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND cancelad <> 'S'
               AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
            
            IF vfecha_ultima_transacc is null THEN
            
                SELECT {+INDEX(sc_movhis idx_movhisnew4)}
                       MAX(fech_alt)
                  INTO vfecha_ultima_transacc
                  FROM sc_movhis
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND fech_alt >= vfechconmovhis
                   AND cancelad <> 'S'
                   AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                   
                IF vfecha_ultima_transacc is null THEN
            
                    SELECT {+INDEX(sc_movhis_old movhis1)}
                           MAX(fech_alt)
                      INTO vfecha_ultima_transacc
                      FROM sc_movhis_old
                     WHERE empresa = pempresa
                       AND cuenta = vcuenta
                       AND fech_alt >= vfechconmovhisold
                       AND fech_alt < vfechconmovhis
                       AND cancelad <> 'S'
                       AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                       
                    IF vfecha_ultima_transacc is null THEN
                    
                        SELECT {+INDEX(sc_movhis_old2 movhis1_old2)}
                               MAX(fech_alt)
                          INTO vfecha_ultima_transacc
                          FROM sc_movhis_old2
                         WHERE empresa = pempresa
                           AND cuenta = vcuenta
                           AND fech_alt >= vfechconmovhisold2
                           AND fech_alt < vfechconmovhisold
                           AND cancelad <> 'S'
                           AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
            
                        IF vfecha_ultima_transacc is null THEN
                        
                            SELECT {+INDEX(sc_movhis_old3 movhis1_old3)}
                                   MAX(fech_alt)
                              INTO vfecha_ultima_transacc
                              FROM sc_movhis_old3
                             WHERE empresa = pempresa
                               AND cuenta = vcuenta
                               AND fech_alt >= vfechaconmovhisold3
                               AND fech_alt < vfechconmovhisold2
                               AND cancelad <> 'S'
                               AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                               
                            IF vfecha_ultima_transacc is null THEN
                            
                                SELECT {+INDEX(sc_movhis_old4 movhis1_old4)}
                                       MAX(fech_alt)
                                  INTO vfecha_ultima_transacc
                                  FROM sc_movhis_old4
                                 WHERE empresa = pempresa
                                   AND cuenta = vcuenta
                                   AND fech_alt >= vfechaconmovhisold4
                                   AND fech_alt < vfechaconmovhisold3
                                   AND cancelad <> 'S'
                                   AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                                   
                                IF vfecha_ultima_transacc is null THEN
                            
                                    SELECT {+INDEX(sc_movhis_old5 movhis1_old5)}
                                           MAX(fech_alt)
                                      INTO vfecha_ultima_transacc
                                      FROM sc_movhis_old5
                                     WHERE empresa = pempresa
                                       AND cuenta = vcuenta
                                       AND fech_alt < vfechaconmovhisold4
                                       AND cancelad <> 'S'
                                       AND transacc NOT IN('3381','3382','3276','3277','3353','3354','3383');
                                
                                END IF;
                            
                            END IF;
            
                        END IF;
                        
                    END IF;
                    
                END IF;
                
            END IF;
            
            IF vfecha_ultima_transacc is null THEN
                LET vfecha_ultima_transacc = vfecha_alta;
            END IF;
            
            LET vdias = vfecha_hoy - vfecha_ultima_transacc;
            
            IF vdias >= 1095 THEN
                INSERT INTO tmp_ctasinactivas ( producto, cuenta, sdo_actual, fecha_ult_mov )
                VALUES ( vproducto, vcuenta, vsdo_actual, vfecha_ultima_transacc );
                
                LET vcontador2 = vcontador2 + 1;
            END IF;
        
        ELSE
        
            CONTINUE FOREACH;
        
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador3 = vcontador3 + 1;

        IF (vcontador3 >= 5000) THEN
            LET vcontador3 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vproducto               = '';
        LET vcuenta                 = '';
        LET vfecha_alta             = '';
        LET vsdo_actual             = 0.00;
        LET vfecha_ultima_transacc  = '';
        LET vdias                   = 0;
    END FOREACH;
        
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;

    UPDATE STATISTICS MEDIUM FOR TABLE tmp_ctasinactivas(cuenta);

    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".elimina_movshistduplicados_cta( pempresa CHAR(3), pFecha DATE )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vempieza         SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vSerialDuplicado INTEGER;
    DEFINE vmin_serial      INTEGER;
    DEFINE vmax_serial      INTEGER;
	DEFINE vcuenta          CHAR(20);
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO REALIZADO SATISFACTORIAMENTE';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vempieza     = -1;
    LET ven_transacc = 0; 
    
    LET vSerialDuplicado = 0;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/elimina_movshistduplicados_cta.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/elimina_movshistduplicados_cta.out";
    --- TRACE ON;
    
    set optimization high;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH WITH HOLD 
        SELECT unique(cuenta)
          INTO vcuenta
          FROM sc_movhis_old
		 WHERE fech_alt = "04232012"
		   --AND cuenta <> "16000000012"
         GROUP BY cuenta
           
        IF vempieza = -1 THEN
            LET vempieza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        DELETE {+INDEX(bdicheq:"informix".sc_movhis_old idx_movhis)} 
               bdicheq:"informix".sc_movhis_old
         WHERE empresa = pempresa
		   AND cuenta = vcuenta
		   AND fech_alt = pfecha;
		       
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        COMMIT WORK;
        LET vcontador2 = 0;
        LET ven_transacc = 0;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".modifica_maehis(pempresa CHAR(3))
RETURNING CHAR(5);

    DEFINE CodRet	                CHAR(5);
    DEFINE sql_err                  INTEGER;
	DEFINE vcuenta                  CHAR (20);
    DEFINE vtotdepositos            DECIMAL(14,2);
    DEFINE vtotretiros              DECIMAL(14,2);
    DEFINE vtotcomcobrada           DECIMAL(14,2);
    DEFINE vtotcombonif             DECIMAL(14,2);
    DEFINE vtotivacobrado           DECIMAL(14,2);
    DEFINE vtotivabonif             DECIMAL(14,2);
    DEFINE vtotintpag               DECIMAL(14,2);
    DEFINE vtotisrcobrado           DECIMAL(14,2);
	DEFINE vfechafin                DATE;
    DEFINE vfechaini                DATE;
    DEFINE vaniomes                 CHAR(6);
	DEFINE vmonto_tot               DECIMAL(16,2);
    DEFINE vtransacc                CHAR(4);
    DEFINE vnaturaleza              CHAR(1);
    DEFINE vtipo_tran               CHAR(2);
    DEFINE vfechainimovhis          CHAR(10);
    DEFINE vfechainimovhisold       CHAR(10);
	DEFINE vtran_efec               CHAR(4);
    DEFINE vtotretirosefec          DECIMAL(18,2);
    DEFINE vtototroscargos          DECIMAL(18,2);
    DEFINE vtrandepotrobco          CHAR(4);
    DEFINE vtrandevotrobco          CHAR(4);
	DEFINE vgtrans_pag_int          CHAR(4);
	DEFINE vgtransisr               CHAR(4);
	DEFINE vcontador1               INTEGER;
    DEFINE vempieza                 SMALLINT;
	DEFINE ven_transacc             SMALLINT;

    ON EXCEPTION 
        SET sql_err
        LET CodRet = sql_err;
        RETURN CodRet;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/modifica_maehis.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;

    LET CodRet     = '000';
    LET vtran_efec = '';
 
     -- // INICIALIZA VARIABLES DE SALDOS
    LET vtotdepositos   = 0;
    LET vtotretiros     = 0;
    LET vtotintpag      = 0;
    LET vtotcomcobrada  = 0;
    LET vtotcombonif    = 0;
    LET vtotivacobrado  = 0;
    LET vtotivabonif    = 0;
    LET vtotisrcobrado  = 0;
    LET vtotretirosefec = 0;
    LET vtototroscargos = 0;
	LET vgtrans_pag_int = "3276";
	LET vgtransisr      = "3277";
	LET vcontador1   = 0;
    LET vempieza     = -1;
    LET ven_transacc = 0; 
        
    -- // OBTIENE FECHAS DE CONSULTAS EN HISTORICOS
    SELECT valor
      INTO vfechainimovhis
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'fechcon_movhis';
       
    SELECT valor
      INTO vfechainimovhisold
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechIniCon_movhis_ol';
       
    SELECT valor
      INTO vtrandepotrobco
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'trandepobco';
       
    SELECT valor
      INTO vtrandevotrobco
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'trandevobco';
    

	FOREACH WITH HOLD
	    SELECT modi.cuenta, modi.aniomes, maehis.fechaini, maehis.fechafin
		  INTO vcuenta, vaniomes, vfechaini, vfechafin
		  FROM cuentas_maehis modi, sc_maehis maehis
         WHERE modi.cuenta = maehis.cuenta
           AND modi.aniomes = maehis.aniomes		 
	
	    IF vempieza = -1 THEN
           LET vempieza = 0;
           LET ven_transacc = 1; 
           BEGIN WORK;
        END IF;
	
        -- // OBTIENE CARGOS Y ABONOS DEL HISTORICO
        FOREACH           
            SELECT mv.monto_tot, mv.transacc, tr.naturaleza, tr.tipo_tran, NVL(efe.transaccion, '0000')
              INTO vmonto_tot, vtransacc, vnaturaleza, vtipo_tran, vtran_efec
              FROM sc_movhis mv
              INNER JOIN bdinteg:si_transacc tr ON (tr.empresa = mv.empresa AND tr.numero = mv.transacc AND tr.se_emite_edocta = 'S')
              LEFT OUTER JOIN sc_transacc_efectivo efe ON (efe.transaccion = mv.transacc)
             WHERE mv.empresa = pEmpresa
               AND mv.cuenta = vCuenta
               AND mv.fech_alt BETWEEN vfechaini AND vfechafin
               AND mv.fech_alt >= vfechainimovhis
               AND mv.cancelad <> 'S'
               AND mv.transacc = tr.numero
            UNION ALL
            SELECT mv.monto_tot, mv.transacc, tr.naturaleza, tr.tipo_tran, NVL(efe.transaccion, '0000')
              FROM sc_movhis_old mv
              INNER JOIN bdinteg:si_transacc tr ON (tr.empresa = mv.empresa AND tr.numero = mv.transacc AND tr.se_emite_edocta = 'S')
              LEFT OUTER JOIN sc_transacc_efectivo efe ON (efe.transaccion = mv.transacc)
             WHERE mv.empresa = pempresa
               AND mv.cuenta = vCuenta
               AND mv.fech_alt BETWEEN vfechaini AND vfechafin
               AND mv.fech_alt >= vfechainimovhisold
               AND mv.fech_alt < vfechainimovhis
               AND mv.cancelad <> 'S'
               AND mv.transacc = tr.numero
           
            -- // ABONOS
            IF vnaturaleza = 'A' THEN 
               IF (vtransacc <> vgtrans_pag_int AND vtransacc <> vtrandepotrobco) THEN -- TOTAL DEPOSITOS
                  LET vtotdepositos = vtotdepositos + vmonto_tot;
               END IF;

               IF vtipo_tran in('01','05','09') THEN -- TOTAL COMISIONES BONIFICADAS
                  LET vtotcombonif = vtotcombonif + vmonto_tot;
               END IF;

               IF vtipo_tran in('02','04','06','08') THEN -- TOTAL IVA BONIFICADO
                  LET vtotivabonif = vtotivabonif + vmonto_tot;
               END IF;
            -- // CARGOS
            ELIF vnaturaleza = 'C' THEN 
               IF (vtipo_tran IN('00','30') AND vtransacc <> vgtransisr AND vtransacc <> vtrandevotrobco) THEN -- TOTAL RETIROS
                  LET vtotretiros = vtotretiros + vmonto_tot;
                  LET vtototroscargos = vtototroscargos + vmonto_tot;
               END IF;
            
               IF vtran_efec = vtransacc THEN
                  LET vtotretirosefec = vtotretirosefec + vmonto_tot;
               END IF;

               IF vtipo_tran in('01','31') THEN -- TOTAL COMISIONES COBRADAS
                  LET vtotcomcobrada = vtotcomcobrada + vmonto_tot;
               END IF;

               IF vtipo_tran in('02','32') THEN -- TOTAL IVA COBRADO
                  LET vtotivacobrado = vtotivacobrado + vmonto_tot;
               END IF;
            END IF;
         
            IF vtransacc = vgtrans_pag_int THEN -- TOTAL PAGO DE INTERESES
               LET vtotintpag = vtotintpag + vmonto_tot;
            END IF;

            IF vtransacc = vgtransisr THEN -- TOTAL ISR COBRADO
               LET vtotisrcobrado = vtotisrcobrado + vmonto_tot;
            END IF;
        END FOREACH;

        IF vtotdepositos IS NULL THEN -- DEPOSITOS
           LET vtotdepositos = 0;
        END IF;

        IF vtotretiros is null OR vtotretiros < 0 THEN -- RETIROS
           LET vtotretiros = 0;
        END IF;

        IF vtotcomcobrada IS NULL THEN -- COMISIONES COBRADAS
           LET vtotcomcobrada = 0;
        END IF;

        IF vtotcombonif IS NULL THEN -- COMISIONES BONIFICADAS
           LET vtotcombonif = 0;
        END IF;

        LET vtotcomcobrada = vtotcomcobrada - vtotcombonif;

        IF vtotivacobrado IS NULL THEN -- IVA COBRADO
           LET vtotivacobrado = 0;
        END IF;

        IF vtotivabonif IS NULL THEN -- IVA BONIFICADO
           LET vtotivabonif = 0;
        END IF;

        LET vtotivacobrado = vtotivacobrado - vtotivabonif;

        IF vtotintpag IS NULL THEN -- INTERESES
           LET vtotintpag = 0;
        END IF;

        IF vtotisrcobrado IS NULL THEN -- ISR
           LET vtotisrcobrado = 0;
        END IF;
    
        IF vtotretirosefec IS NULL THEN
           LET vtotretirosefec = 0;
        END IF;
    
        LET vtototroscargos = vtototroscargos - vtotretirosefec;
    
        IF vtototroscargos is null OR vtototroscargos < 0 THEN
           LET vtototroscargos = 0;
        END IF;

        -- // MODIFICA REGISTRO HISTORICO
        UPDATE sc_maehis SET totdepositos = vtotdepositos, 
		                     totretiros = vtotretiros,
                             totintpag = vtotintpag,
							 totcomcobrada = vtotcomcobrada,
                             totivacobrado = vtotivacobrado,
                             totisrcobrado = vtotisrcobrado, 
							 totretirosefec = vtotretirosefec,
							 tototroscargos = vtototroscargos
		 WHERE cuenta = vcuenta
           AND aniomes = vaniomes;
		
        LET vcontador1 = vcontador1 + 1;

        COMMIT WORK;
        BEGIN WORK;		
		   
		LET vtotdepositos   = 0;
        LET vtotretiros     = 0;
        LET vtotintpag      = 0;
        LET vtotcomcobrada  = 0;
        LET vtotcombonif    = 0;
        LET vtotivacobrado  = 0;
        LET vtotivabonif    = 0;
        LET vtotisrcobrado  = 0;
        LET vtotretirosefec = 0;
        LET vtototroscargos = 0;   
    
    END FOREACH;

    IF ven_transacc = 1 THEN
       COMMIT WORK;
       LET ven_transacc = 0;
    END IF;	

    RETURN CodRet;

END PROCEDURE

;

create procedure "informix".cons_cc(pempresa char(3), pcuenta char(20))
returning char(5),date,datetime hour to fraction(3),char(20),char(2),
          char(40),char(2),char(3),char(2),char(1),char(10),date,date,
          money(14,2),money(14,2),smallint,money(14,2),
          smallint,money(14,2),money(14,2),money(14,2),
          money(14,2),money(14,2),money(14,2),money(14,2),char(1),
          money(14,2),money(14,2),date,
          money(14,2),money(14,2),date,
          money(14,2),money(14,2),date;

    define cod_ret char(5);
    define vfecha_hoy date;
    define vhora datetime hour to fraction(3);
    define vcuenta,tcuenta,var_cta char(20);
    define vsistema char(2);
    define vnombre char(40);
    define vpersonalidad char(2);
    define vaplicacion char(3);
    define vmoneda char(2);
    define v_long_cta char(2);
    define ves_fisica,venvio char(1);
    define vstatus_cta char(10);
    define vfecha_apert,vfecha_ultmov date;
    define vint_pend,vcom_pend money(14,2);
    define vchq_dev1,vchq_dev2,longitud smallint;
    define vmto_dev1,vmto_dev2 money(14,2);
    define vsdo_prom1,vsdo_prom2,vsdo_prom3,vsdo_prom4,vsdo_prom5,
    vsdo_prom6 money(14,2);
    define vlinea_ccc_imp,vlinea_rem_imp,vlinea_sbc_imp money(14,2);
    define vlinea_ccc_monto,vlinea_rem_monto,vlinea_sbc_monto money(14,2);
    define vlinea_ccc_disp, vlinea_rem_disp, vlinea_sbc_disp  money(14,2);
    define vlinea_ccc_vig,  vlinea_rem_vig,  vlinea_sbc_vig date;
    define tstatus_cta,vtipo_linea char(1);
    define tnum_cte char(20);
    define tnombre1,tnombre2,tapell_paterno,tapell_materno char(15);
    define trazon_soc char(30);
    define tplaza char(3);
    define tsucursal char(4);
    define v_cal_int_chq char(1);
    define timp_int_ccc money(14,2);
    define timp_sbg_ccc,timp_chq_rem,timp_chq_sbc money(14,2);
    define timpor_dev,tacum_pos money(14,2);
    define tnum_dev,i,tdias_pos smallint;
    define tfecha,tfechar,var_fec datetime year to month;
    define sql_err integer;

    -- ****************************************************************************
    -- Inicializa variables
    -- ****************************************************************************
    let cod_ret          = "000";
    let vfecha_hoy       = "";
    let vhora            = "";
    let vcuenta          = "";
    let vsistema         = "00";
    let vnombre          = "";
    let vpersonalidad    = "";
    let vaplicacion      = "";
    let vmoneda          = "";
    let venvio           = "";
    let vstatus_cta      = "";
    let vfecha_apert     = "";
    let vfecha_ultmov    = "";
    let vint_pend        = 0;
    let vcom_pend        = 0;
    let vchq_dev1        = 0;
    let vmto_dev1        = 0;
    let vchq_dev2        = 0;
    let vmto_dev2        = 0;
    let vsdo_prom1       = 0;
    let vsdo_prom2       = 0;
    let vsdo_prom3       = 0;
    let vsdo_prom4       = 0;
    let vsdo_prom5       = 0;
    let vsdo_prom6       = 0;
    let vlinea_ccc_monto = 0;
    let vlinea_rem_monto = 0;
    let vlinea_sbc_monto = 0;
    let vlinea_ccc_disp  = 0;
    let vlinea_rem_disp  = 0;
    let vlinea_sbc_disp  = 0;
    let vlinea_ccc_vig   = "";
    let vlinea_rem_vig   = "";
    let vlinea_sbc_vig   = "";
    let vlinea_ccc_imp   = 0;
    let vlinea_rem_imp   = 0;
    let vlinea_sbc_imp   = 0;
    let var_cta          = "";
    let var_fec          = "";
    let vtipo_linea      = " ";

    begin
    
    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret,vfecha_hoy,vhora,vcuenta,vsistema,vnombre,vpersonalidad,
            vaplicacion,vmoneda,venvio,vstatus_cta,vfecha_apert,
            vfecha_ultmov,vint_pend,vcom_pend,vchq_dev1,vmto_dev1,vchq_dev2,
            vmto_dev2,vsdo_prom1,vsdo_prom2,vsdo_prom3,vsdo_prom4,
            vsdo_prom5,vsdo_prom6,vtipo_linea,vlinea_ccc_monto,
            vlinea_ccc_disp,vlinea_ccc_vig,vlinea_rem_monto,vlinea_rem_disp,
            vlinea_rem_vig,vlinea_sbc_monto,vlinea_sbc_disp,vlinea_sbc_vig;
        end if;
    end exception;

    select sistema 
      into vsistema 
      from bdinteg:si_sistema
     where siglas = "SC";

    -- ****************************************************************************
    -- Valida exista la Cuenta de Cheques y extrae informacion necesaria
    -- ****************************************************************************
    select mc.cuenta,mc.sucursal,mc.plaza,num_cte,producto,envio_direcc,
           status_cta,fecha_alta,imp_int_ccc + imp_int_sbg,com_pendiente,
           lim_sbg_ccc,imp_sbg_ccc + imp_chq_sbg,fech_venc_ccc,
           lim_chq_rem,imp_chq_rem,fech_venc_rem,
           lim_chq_sbc,imp_chq_sbc,fech_venc_sbc,fec_ult_mov,
           tipo_linea
      into vcuenta,tsucursal,tplaza,tnum_cte,vaplicacion,venvio,tstatus_cta,
           vfecha_apert,timp_int_ccc,vcom_pend,vlinea_ccc_monto,
           vlinea_ccc_imp,vlinea_ccc_vig,vlinea_rem_monto,vlinea_rem_imp,
           vlinea_rem_vig,vlinea_sbc_monto,vlinea_sbc_imp,vlinea_sbc_vig,
           vfecha_ultmov,vtipo_linea
      from sc_maechq mc,
           sc_maenoc mn
     where mc.empresa = pempresa 
       and mc.cuenta = pcuenta
       and mc.empresa = mn.empresa 
       and mn.cuenta = mc.cuenta;

    if vcuenta is null then
        let cod_ret = "100";
        return cod_ret,vfecha_hoy,vhora,vcuenta,vsistema,vnombre,vpersonalidad,
        vaplicacion,vmoneda,venvio,vstatus_cta,vfecha_apert,
        vfecha_ultmov,vint_pend,vcom_pend,vchq_dev1,vmto_dev1,vchq_dev2,
        vmto_dev2,vsdo_prom1,vsdo_prom2,vsdo_prom3,vsdo_prom4,
        vsdo_prom5,vsdo_prom6,vtipo_linea,vlinea_ccc_monto,
        vlinea_ccc_disp,vlinea_ccc_vig,vlinea_rem_monto,vlinea_rem_disp,
        vlinea_rem_vig,vlinea_sbc_monto,vlinea_sbc_disp,vlinea_sbc_vig;
    end if

    Select fecha_hoy 
      into vfecha_hoy 
      from sc_fechas 
     where empresa = pempresa;

    let vhora = current hour to fraction(3);

    -- ****************************************************************************
    -- Extrae el nombre del Cliente
    -- ****************************************************************************
    Select es_fisica,nombre1,nombre2,apell_paterno,apell_materno,razon_social
      into ves_fisica,tnombre1,tnombre2,tapell_paterno,tapell_materno,trazon_soc
      from bdinteg:si_cliente,
           bdinteg:si_tipper
     where bdinteg:si_cliente.numcte = tnum_cte 
       and bdinteg:si_cliente.tpo_persona = bdinteg:si_tipper.tpo_persona;
       
    if ves_fisica = "S" then
        let vnombre = trim(tapell_paterno)||" "||trim(tapell_materno)||" "||trim(tnombre1)||" "||trim(tnombre2);
    else
        let vnombre = trim(trazon_soc);
    end if

    -- ****************************************************************************
    -- Extrae el tipo de moneda y sistema de la aplicacion de la cuenta
    -- ****************************************************************************
    select divisa 
      into vmoneda
      from sc_producto
     where empresa = pempresa 
       and producto = vaplicacion;

    -- ****************************************************************************
    -- Define el status de la Cuenta
    -- ****************************************************************************
    if tstatus_cta = "1" then
        let vstatus_cta = "Activa";
    elif tstatus_cta = "2" then
        let vstatus_cta = "Cancelada";
    elif tstatus_cta = "3" then
        let vstatus_cta = "Bloqueada";
    elif tstatus_cta = "4" then
        let vstatus_cta = "Inactiva";
    elif tstatus_cta = "5" then
        let vstatus_cta = "Informada";
    elif tstatus_cta = "6" then
        let vstatus_cta = "Concentrada";
    elif tstatus_cta = "7" then
        let vstatus_cta = "Traspasada";
    elif tstatus_cta = "8" then
        let vstatus_cta = "DesConcentrada";
    end if

    -- ****************************************************************************
    -- Extrae los intereses pendientes
    -- ****************************************************************************
    let vint_pend = timp_int_ccc;

    -- ****************************************************************************
    -- Extrae los cheques devueltos y el saldo promedio
    -- ****************************************************************************
    let tfecha = vfecha_hoy;
    let i = 1;
    
    while i < 7
        let tfecha = tfecha - 1 units month;
        
        begin
        
        let tcuenta,tfechar,tacum_pos,tdias_pos,tnum_dev,timpor_dev = (select cuenta,fecha,acum_pos,dias_pos,num_dev,impor_dev
                                                                         from sc_salpro
                                                                        where empresa = pempresa 
                                                                          and cuenta = pcuenta 
                                                                          and fecha = tfecha);
                                                                          
        end
        
        if pcuenta = var_cta and tfechar = var_fec then
            let tnum_dev   = 0;
            let timpor_dev = 0;
            let tacum_pos  = 0;
        end if
        
        if i = 1 then
            let vchq_dev1  = tnum_dev;
            let vmto_dev1  = timpor_dev;
            
            if tacum_pos > 0 then
                let vsdo_prom1 = tacum_pos/tdias_pos;
            else
                let vsdo_prom1 = 0;
            end if
        elif i = 2 then
            let vchq_dev2  = tnum_dev;
            let vmto_dev2  = timpor_dev;
            
            if tacum_pos > 0 then
                let vsdo_prom2 = tacum_pos/tdias_pos;
            else
                let vsdo_prom2 = 0;
            end if
        elif i = 3 then
            if tacum_pos > 0 then
                let vsdo_prom3 = tacum_pos/tdias_pos;
            else
                let vsdo_prom3 = 0;
            end if
        elif i = 4 then
            if tacum_pos > 0 then
                let vsdo_prom4 = tacum_pos/tdias_pos;
            else
                let vsdo_prom4 = 0;
            end if
        elif i = 5 then
            if tacum_pos > 0 then
                let vsdo_prom5 = tacum_pos/tdias_pos;
            else
                let vsdo_prom5 = 0;
            end if
        elif i = 6 then
            if tacum_pos > 0 then
                let vsdo_prom6 = tacum_pos/tdias_pos;
            else
                let vsdo_prom6 = 0;
            end if
        end if
        
        let i = i + 1;
        let var_cta = tcuenta;
        let var_fec = tfechar;
    end while

    -- ****************************************************************************
    -- Extrae monto disponible de la linea 1305 / 1505
    -- ****************************************************************************
    let vlinea_ccc_disp = vlinea_ccc_monto - vlinea_ccc_imp;
    
    if vlinea_ccc_disp < 0 then
        let vlinea_ccc_monto = vlinea_ccc_imp;
        let vlinea_ccc_disp = 0;
    end if

    -- ****************************************************************************
    -- Extrae monto disponible de la linea de remesas
    -- ****************************************************************************
    let vlinea_rem_disp = vlinea_rem_monto - vlinea_rem_imp;
    
    if vlinea_rem_disp < 0 then
        let vlinea_rem_disp = 0;
    end if

    -- ****************************************************************************
    -- Extrae monto disponible de la linea de sbc
    -- ****************************************************************************
    let vlinea_sbc_disp = vlinea_sbc_monto - vlinea_sbc_imp;

    -- ****************************************************************************
    -- Verifica no enviar nulos como respuesta
    -- ****************************************************************************
    if vchq_dev1 is null then
        let vchq_dev1 = 0;
    end if
    
    if vmto_dev1 is null then
        let vmto_dev1 = 0;
    end if
    
    if vchq_dev2 is null then
        let vchq_dev2 = 0;
    end if
    
    if vmto_dev2 is null then
        let vmto_dev2 = 0;
    end if
    
    if vsdo_prom1 is null then
        let vsdo_prom1 = 0;
    end if
    
    if vsdo_prom2 is null then
        let vsdo_prom2 = 0;
    end if
    
    if vsdo_prom3 is null then
        let vsdo_prom3 = 0;
    end if
    
    if vsdo_prom4 is null then
        let vsdo_prom4 = 0;
    end if
    
    if vsdo_prom5 is null then
        let vsdo_prom5 = 0;
    end if
    
    if vsdo_prom6 is null then
        let vsdo_prom6 = 0;
    end if

    return cod_ret,vfecha_hoy,vhora,vcuenta,vsistema,vnombre,vpersonalidad,
           vaplicacion,vmoneda,venvio,vstatus_cta,vfecha_apert,
           vfecha_ultmov,vint_pend,vcom_pend,vchq_dev1,vmto_dev1,vchq_dev2,
           vmto_dev2,vsdo_prom1,vsdo_prom2,vsdo_prom3,vsdo_prom4,
           vsdo_prom5,vsdo_prom6,vtipo_linea,vlinea_ccc_monto,
           vlinea_ccc_disp,vlinea_ccc_vig,vlinea_rem_monto,vlinea_rem_disp,
           vlinea_rem_vig,vlinea_sbc_monto,vlinea_sbc_disp,vlinea_sbc_vig;

    end

end procedure;

CREATE PROCEDURE "informix".entre_chq(mempresa char(3),
                           msucursal CHAR(4),
                           musuario  CHAR(8),
                           mcuenta   CHAR(20),
                           mnum_ini  INTEGER,
                           mcan_cheq SMALLINT,
                           mtp_cheq  CHAR(2),
                           mnro_cheq SMALLINT)
RETURNING CHAR(5), CHAR(60);

--------------------------------------------------------------------------
--Definicion de Variables
--------------------------------------------------------------------------

DEFINE cod_ret       CHAR(5);
DEFINE v_nombrecte   CHAR(60);
DEFINE v_razon_soc   CHAR(35);
DEFINE estatus       CHAR(1);
DEFINE sucur         CHAR(4);
DEFINE v_producto    CHAR(4);
DEFINE fecha         DATE;
DEFINE v_cal_int_chq,
       v_sin_inv,
       v_con_doctos,
       v_mod_inv     CHAR(1);
DEFINE v_numcte      CHAR(20);
DEFINE v_usuario     CHAR(8);

DEFiNE v_reposicion,
       v_numchqs,
       longitud,
       v_long_cta,
       v_reorden     SMALLINT;

DEFINE v_nombre1,
       v_nombre2,
       v_appat,
       v_apmat       CHAR(12);

DEFINE v_proveedor,
       v_plaza       CHAR(3);

DEFINE v_stock,
       v_ultnva,
       v_row,
       v_row2,
       ultimo_chq,
       ultimo_chq2,
       ultimo_chqsc,
       a, b, c, d, e,
       i, num,
       sql_err,
       alta_ent,
       v_ult_ent,
       v_pagados,
       v_calculo,
       v_chq_prov,
       vinicial,
       alta_stock   INTEGER;

DEFINE cuen,
       cta         CHAR(20);

DEFINE v_moneda,
       v_monedaint,
       vtp_nchequera,
       vtp_chequera CHAR(2);

DEFINE r_sucursal         CHAR(4);
DEFINE r_cuenta           CHAR(20);
DEFINE r_inicial          INTEGER ;
DEFINE r_final            INTEGER;
DEFINE r_fecha_req        DATE  ;
DEFINE r_estado           CHAR(1);
DEFINE r_fecha_rec        DATE  ;
DEFINE r_fecha_ent        DATE  ;
DEFINE r_proveedor        CHAR(3);
DEFINE r_num_pedido       INTEGER;
DEFINE r_usuario          CHAR(8);
DEFINE r_tpo_persona      CHAR(3);
DEFINE v_tran_com         CHAR(4);
DEFINE v_divisa           CHAR(2);
DEFINE v_maxchq           SMALLINT;
--------------------------------------------------------------------------
--------------------------------------------------------------------------
--Asignacion de Variables
--------------------------------------------------------------------------
LET cod_ret = "000";
LET a = mnum_ini;
LET b = mcan_cheq;
LET ultimo_chq = 0;
LET ultimo_chq2 = 0;
LET v_nombrecte = "SIN NOMBRE";

--COMMIT WORK;
--BEGIN WORK;
BEGIN
   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
         LET cod_ret = sql_err;
         --ROLLBACK WORK;
         RETURN cod_ret, v_nombrecte;
      END IF;
   END EXCEPTION;

   -------------------------------------------------------------------------
   --Validacion de que la sucursal no venga en blancos
   -------------------------------------------------------------------------
   IF msucursal = ""  OR msucursal=" " THEN
      LET cod_ret = "110";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;

   SELECT ejecutivo INTO v_usuario FROM bdinteg:si_ejecut
    WHERE ejecutivo = musuario;
   IF v_usuario <> musuario or v_usuario IS NULL THEN
      LET cod_ret = "106";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;
   -------------------------------------------------------------------------
   --Validacion de que el usuario no venga en blancos
   -------------------------------------------------------------------------
   IF musuario = "" or musuario = " " THEN
      LET cod_ret = "110";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;


   -------------------------------------------------------------------------
   --Validacion de que la cantidad de cheques no venga en ceros
   -------------------------------------------------------------------------
   IF mcan_cheq = 0 THEN
      LET cod_ret = "110";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;

   -------------------------------------------------------------------------
   --Validacion de que el numero inicial de cheques no venga en ceros
   -------------------------------------------------------------------------
   IF mnum_ini = 0 THEN
      LET cod_ret = "110";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;

   -------------------------------------------------------------------------
   --Validacion de la cuenta
   -------------------------------------------------------------------------
   IF mcuenta = "" or mcuenta=" "  THEN
      LET cod_ret = "110";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;

   SELECT rowid, cuenta, status_cta, ult_chq
   INTO v_row, cta, estatus, ultimo_chq FROM sc_maechq
   WHERE empresa = mempresa and cuenta = mcuenta;

   IF cta is null THEN
      LET cta = "0";
   END IF;
   IF mcuenta != cta THEN
      LET cod_ret = "100";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;
   IF estatus IN("2","6","7","8") THEN
      LET cod_ret = "200";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;

   -------------------------------------------------------------------------
   --Validacion de la cantidad de cheques no sea mayor de 300
   -------------------------------------------------------------------------
   IF mcan_cheq > 300 THEN
      LET cod_ret = "555";
      --ROLLBACK WORK;
      RETURN cod_ret, v_nombrecte;
   END IF;

   -------------------------------------------------------------------------
   --Validacion del numero del cheque  no haya sido
   --contemplado en otra chequera. Incremeetar el ultimo cheque.
   -------------------------------------------------------------------------

   LET ultimo_chqsc =  ultimo_chq;
   LET ultimo_chq = (mnum_ini + mcan_cheq -1);
   LET ultimo_chq2 = (mnum_ini + mcan_cheq -1);

   -------------------------------------------------------------------------
   --Accesando la fecha del calendario
   -------------------------------------------------------------------------
   SELECT fecha_hoy INTO fecha FROM sc_fechas where empresa = mempresa;

   -- **********************************************************************
   --                Carga Parametros de Chequeras
   -- **********************************************************************
   SELECT chq_sin_inv, chq_con_doctos, mod_inv, proveedor_default, tran_comision
     INTO v_sin_inv, v_con_doctos, v_mod_inv, v_proveedor, v_tran_com
     FROM bdicntchq:sq_paramgen;

   IF v_sin_inv IS NULL OR v_sin_inv = "" THEN
      LET cod_ret = "558";
      RETURN cod_ret, v_nombrecte;
   END IF;
   IF v_con_doctos IS NULL OR v_con_doctos = "" THEN
      LET cod_ret = "558";
      RETURN cod_ret, v_nombrecte;
   END IF;
   IF v_mod_inv IS NULL OR v_mod_inv = "" THEN
      LET cod_ret = "558";
      RETURN cod_ret, v_nombrecte;
   END IF;
   IF v_proveedor IS NULL OR v_proveedor = "" THEN
      LET cod_ret = "558";
      RETURN cod_ret, v_nombrecte;
   END IF;
   -- Las siguientes lineas se comentaron: LAMQ l2/09/2000
   --IF v_tran_com IS NULL OR v_tran_com = "" THEN
   --   LET cod_ret = "558";
   --   RETURN cod_ret, v_nombrecte;
   --END IF;

   ---- Rutinas de control de chequeras ---
   SELECT rowid INTO v_row2 FROM bdicntchq:sq_stocknvas
   WHERE cuenta = mcuenta;

   IF v_row2 IS NOT NULL THEN
         -- *************************************************************
         --     Valida si se entrega la chequera con doctos pagados
         -- *************************************************************
      IF v_mod_inv <> "N" THEN
         IF v_con_doctos = "N" THEN
            SELECT COUNT(*) INTO v_pagados FROM sc_contch
             WHERE empresa = mempresa and cuenta = mcuenta
             AND (numero >= mnum_ini
             AND numero <= mnum_ini + mcan_cheq -1)
             AND estado = "P";
             IF v_pagados <> 0 THEN
                LET cod_ret = "501";
                RETURN cod_ret, v_nombrecte;
             END IF;
          END IF;

          ----------------------------------------------------------------
          -- Valida el Tipo de Chequera y el Nro. de Talonarios ( NUEVAS )
          ----------------------------------------------------------------
          -- Extrae Datos de Chequera Nueva
          SELECT rowid, ult_cheque, divisa
            INTO v_row2, v_ultnva, v_divisa
            FROM bdicntchq:sq_stocknvas
           WHERE cuenta=mcuenta;

          IF v_row2 IS NULL OR v_row2 = "" THEN
             LET cod_ret="560";
             RETURN cod_ret, v_nombrecte;
          END IF;

           SELECT chequera, no_cheques INTO vtp_chequera, v_numchqs
             FROM bdicntchq:sq_chequera
            WHERE divisa = v_divisa
              AND ctas_nvas="1";

          -- Verifica numero de Doctos sea igual al del talonario asignado

          IF MOD(v_numchqs,mcan_cheq)> 0 THEN
             LET cod_ret="561";
             RETURN cod_ret, v_nombrecte;
          END IF;

          IF (mcan_cheq <> v_numchqs) AND mtp_cheq = "00"  THEN
             LET cod_ret = "561";
             RETURN  cod_ret, v_nombrecte;
          END IF

          SELECT estado INTO r_estado FROM bdicntchq:sq_reqnvos
           WHERE cuenta = mcuenta
             AND inicial = mnum_ini;
          IF r_estado <> "E" THEN
            LET cod_ret = "562";
            RETURN  cod_ret, v_nombrecte;
          END IF

          SELECT MIN(inicial) INTO vinicial
             FROM bdicntchq:sq_reqnvos
             WHERE cuenta = mcuenta AND estado = "E";
          IF vinicial <> mnum_ini THEN
            LET cod_ret = "563";
            RETURN  cod_ret, v_nombrecte;
          END IF

          -- Incorporaci¢n del IF para que realice correctamente la
          -- Entrega de Chequeras de Cuentas Nuevas
          IF v_ultnva = "25" THEN
             LET v_ultnva = "1000025";
             UPDATE sc_maechq SET ult_chq = "1000000"
                where empresa = mempresa and cuenta = mcuenta;
          END IF

          IF v_ultnva < ultimo_chq THEN
             LET cod_ret="563";
             RETURN cod_ret, v_nombrecte;
          END IF

          SELECT plaza, producto, nombre1, nombre2, apell_paterno,
                 apell_materno, razon_social
            INTO v_plaza, v_producto, v_nombre1, v_nombre2,
                 v_appat, v_apmat, v_razon_soc
            FROM sc_maechq, bdinteg:si_cliente
           WHERE sc_maechq.num_cte = bdinteg:si_cliente.numcte
             AND sc_maechq.empresa = mempresa and cuenta=mcuenta;

          LET v_nombrecte = trim(trim(v_appat)||" "||trim(v_apmat)||" "||trim(v_nombre1)||" "||trim(v_nombre2)||" "||trim(v_razon_soc));

          IF mtp_cheq <> "00" THEN
                SELECT no_cheques, max_repos INTO v_numchqs, v_maxchq
                  FROM bdicntchq:sq_chequera
                 WHERE chequera = mtp_cheq
                   AND divisa = v_divisa;
          ELSE
                SELECT no_cheques, max_repos INTO v_numchqs, v_maxchq
                  FROM bdicntchq:sq_chequera
                 WHERE ctas_nvas = "1"
                   AND divisa = v_divisa;
          END IF

          IF mnro_cheq <> 0 THEN
                IF mnro_cheq > v_maxchq THEN
                        LET cod_ret = "1203";
                        RETURN cod_ret, v_nombrecte;
                END IF
          END IF

          FOR i = 1 TO mnro_cheq
                LET c=v_ultnva + 1;
                LET d=v_ultnva + v_numchqs;
          --    LET e=v_ultnva - mcan_cheq; --LAMQ 08/03/2000
                INSERT INTO bdicntchq:sq_reqctes
                 VALUES(msucursal, mcuenta, v_divisa, c, d, fecha, fecha,
                        fecha, "X", v_proveedor, 0, musuario);
                LET v_ultnva=d;
          END FOR
--  LET ultimo_chq=d;

          --LAMQ 08/03/2000
          --Se inserta la diferencia entre el ult_cheque (sq_stocknvas) y
          --el parametro mcan_cheq que viene en la variable e.
          --Ademas se cambia la variable d por la variable v_ultnva.
          INSERT INTO bdicntchq:sq_stockctes
             VALUES(msucursal, mcuenta,v_divisa, mtp_cheq,mnro_cheq,v_nombrecte,
                    mcan_cheq, 0, fecha, v_proveedor, 2, d);

          DELETE FROM bdicntchq:sq_stocknvas WHERE cuenta=mcuenta;

          UPDATE bdicntchq:sq_reqnvos SET estado = "L", fecha_ent = fecha,
                                          usuario = musuario
           WHERE cuenta = mcuenta
             AND inicial = mnum_ini;

          -- Pasa Detalle a Clientes
          FOREACH SELECT * INTO r_sucursal, r_cuenta, v_divisa, r_inicial,
                                r_final, r_fecha_req, r_estado, r_fecha_rec,
                                r_fecha_ent, r_proveedor, r_num_pedido,
                                r_usuario, r_tpo_persona
                    FROM bdicntchq:sq_reqnvos
                   WHERE cuenta = mcuenta

                   INSERT INTO bdicntchq:sq_reqctes
                      VALUES (r_sucursal, r_cuenta, v_divisa,r_inicial, r_final,
                              r_fecha_req, r_fecha_rec, r_fecha_ent,
                              r_estado, r_proveedor, r_num_pedido,r_usuario);

                   DELETE FROM bdicntchq:sq_reqnvos
                    WHERE cuenta = r_cuenta
                      AND inicial = r_inicial;

            END FOREACH

            SELECT valor INTO v_monedaint 
               FROM bdinteg:si_param
               where empresa = mempresa and cod_param = "codigo mn";
            IF r_tpo_persona = "005" THEN -- Persona Juridica (Moral)
                UPDATE bdicntchq:sq_paramnvas SET (inventario) =
                                                  (inventario - 1)
                WHERE sucursal = msucursal
                  AND divisa = v_divisa
                  AND tpo_persona = "M";
            ELSE -- Persona Fisica (Natural)
                UPDATE bdicntchq:sq_paramnvas SET (inventario) =
                                                  (inventario - 1)
                WHERE sucursal = msucursal
                  AND divisa = v_divisa
                  AND tpo_persona = "F";
            END IF;
       END IF;
    ELSE
       -----------------------------------------------------------------
       --       Actualiza Parametros de Tipo de Chequera ( REPOSICION )
       -----------------------------------------------------------------
       -- **************************************************************
       --      Valida si se entrega la chequera con ddctos pagados
       -- **************************************************************
       IF v_mod_inv <> "N" THEN
          IF v_con_doctos = "N" THEN
             SELECT COUNT(*) INTO v_pagados FROM sc_contch
             WHERE empresa = mempresa and  cuenta = mcuenta
             AND (numero >= mnum_ini
             AND numero <= mnum_ini + mcan_cheq -1)
             AND estado = "P";
             IF v_pagados <> 0 THEN
                LET cod_ret = "501";
                --ROLLBACK WORK;
                RETURN cod_ret, v_nombrecte;
             END IF;
          END IF;

          SELECT divisa, chequera, nro_chequeras
            INTO v_divisa, vtp_chequera,vtp_nchequera
            FROM bdicntchq:sq_stockctes
           WHERE cuenta=mcuenta;
          IF mtp_cheq <>  "00" THEN
             IF vtp_chequera <> mtp_cheq  THEN
                UPDATE bdicntchq:sq_stockctes SET chequera = mtp_cheq
                WHERE cuenta = mcuenta;
             END IF;
          ELSE
             IF vtp_chequera = "" OR vtp_chequera = "00" THEN
                SELECT chequera INTO vtp_chequera FROM bdicntchq:sq_chequera
                WHERE ctas_nvas="1"
                  AND divisa = v_divisa;
                UPDATE bdicntchq:sq_stockctes SET chequera = vtp_chequera
                WHERE cuenta = mcuenta;
             END IF;
          END IF;

          IF mnro_cheq <> 0  THEN
             IF vtp_nchequera <> mnro_cheq THEN
                UPDATE bdicntchq:sq_stockctes SET reorden = mnro_cheq
                WHERE cuenta = mcuenta;
             END IF;
          ELSE
             IF vtp_nchequera = 0 OR vtp_nchequera IS NULL THEN
                SELECT max_repos INTO vtp_chequera FROM bdicntchq:sq_chequera
                 WHERE ctas_nvas="1"
                   AND divisa = v_divisa;
                UPDATE bdicntchq:sq_stockctes SET nro_chequeras = vtp_chequera
                 WHERE cuenta = mcuenta;
             END IF;
        END IF;

        -- Extrae Datos de Chequera
        SELECT a.rowid,
               a.ultimo_ent,
               a.divisa,
               a.ultimo_stock,
               a.proveedor,
               a.reorden,
               a.nro_chequeras,
               b.no_cheques,
               a.chq_prov
        INTO v_row2, v_ult_ent, v_divisa, v_stock, v_proveedor, v_reorden,
             v_reposicion, v_numchqs, v_chq_prov
        FROM bdicntchq:sq_stockctes a, bdicntchq:sq_chequera b
       WHERE a.cuenta   = mcuenta
         AND a.chequera = b.chequera
         AND a.divisa   = b.divisa;

        IF v_stock is null THEN
           LET cod_ret="560";
           --ROLLBACK WORK;
           RETURN cod_ret, v_nombrecte;
        END IF;

        IF mcan_cheq > v_stock THEN
           IF v_sin_inv <> "S" THEN
              LET cod_ret="561";
              --ROLLBACK WORK;
              RETURN cod_ret, v_nombrecte;
           END IF;
        END IF;

        IF mod(mcan_cheq, v_numchqs)> 0 THEN
           LET cod_ret="1222";
           RETURN cod_ret, v_nombrecte;
        END IF;

        IF mcan_cheq <> v_numchqs THEN
            LET cod_ret = "1223";
            RETURN  cod_ret, v_nombrecte;
        END IF

        SELECT estado INTO r_estado FROM bdicntchq:sq_reqctes
         WHERE cuenta = mcuenta
           AND inicial = mnum_ini;
        IF r_estado <> "E" OR r_estado IS NULL THEN
            LET cod_ret = "561";
            RETURN  cod_ret, v_nombrecte;
        END IF

        SELECT MIN(inicial) INTO vinicial
           FROM bdicntchq:sq_reqctes
           WHERE cuenta = mcuenta AND estado = "E";
        IF vinicial <> mnum_ini THEN
           LET cod_ret = "563";
           RETURN  cod_ret, v_nombrecte;
        END IF

        -- Actualiza Inventario
        IF v_mod_inv = "S" THEN
           IF v_ult_ent >  ultimo_chq THEN
                LET cod_ret="564";
                RETURN cod_ret, v_nombrecte;
           ELSE
              LET v_stock = v_stock - mcan_cheq;
              UPDATE bdicntchq:sq_stockctes
              SET (ultimo_ent,ultimo_stock) = (ultimo_chq, v_stock)
              WHERE rowid=v_row2;

              UPDATE bdicntchq:sq_reqctes SET (estado, fecha_ent, usuario)=
                                              ("L", fecha, musuario)
               WHERE cuenta = mcuenta
                 AND inicial = mnum_ini;
           END IF;

           SELECT COUNT(*) INTO v_stock FROM bdicntchq:sq_reqctes
            WHERE cuenta = mcuenta
              AND estado  NOT IN ("L", "A");
           -- Genera Requerimiento
           LET v_stock = v_reorden - v_stock;
           IF v_stock > 0 THEN
              LET i = 0;
              FOR i = 1 TO v_stock
                 LET c = v_chq_prov + 1;
                 LET d = v_chq_prov + v_numchqs;
                 INSERT INTO bdicntchq:sq_reqctes
                    VALUES(msucursal, mcuenta, v_divisa, c, d, fecha, fecha,
                           fecha, "X", v_proveedor, 0, musuario);
                 LET v_chq_prov=v_chq_prov + v_numchqs;
              END FOR
              UPDATE bdicntchq:sq_stockctes SET chq_prov = d
               WHERE cuenta = mcuenta;
           END IF;
        END IF;
     END IF;
  END IF;

          SELECT plaza, producto, nombre1, nombre2, apell_paterno,
                 apell_materno, razon_social
            INTO v_plaza, v_producto, v_nombre1, v_nombre2,
                 v_appat, v_apmat, v_razon_soc
            FROM sc_maechq, bdinteg:si_cliente
           WHERE sc_maechq.num_cte = bdinteg:si_cliente.numcte
             AND sc_maechq.empresa = mempresa and cuenta=mcuenta;

          LET v_nombrecte = trim(trim(v_appat)||" "||trim(v_apmat)||" "||trim(v_nombre1)||" "||trim(v_nombre2)||" "||trim(v_razon_soc));

  --------------------------------------------------------------------------
  --Creando la tabla de control de cheques
  --------------------------------------------------------------------------
  WHILE b <> 0
     IF EXISTS( SELECT cuenta, numero FROM sc_contch
                WHERE empresa = mempresa and cuenta = mcuenta AND
                      numero = a ) THEN

        INSERT INTO bdicntchq:sq_duplicados VALUES(mcuenta,a,fecha);
     ELSE
        INSERT INTO sc_contch VALUES (mempresa,mcuenta,a," ",fecha,0);
     END IF;

     LET b = b - 1;
     LET a = a + 1;
  END WHILE;

  --------------------------------------------------------------------------
  --Actualizando el ultimo cheque del maestro
  --------------------------------------------------------------------------
  IF ultimo_chqsc < mcan_cheq or ultimo_chq2 >= mcan_cheq THEN
     update sc_maechq SET (ult_chq)= (ult_chq + mcan_cheq)
     WHERE rowid=v_row;
  END IF;

  LET cod_ret = "000";
--  COMMIT WORK;
  RETURN cod_ret, v_nombrecte;
END
END PROCEDURE;

create procedure "informix".envio_corres(pempresa char(3),
                                         i_cuenta  char(20),
                                         i_cliente char(20),
                                         cual smallint)
returning char(5);

    define v_long_cta            smallint;
    define w_cod_ret             char(5);
    define w_cuenta              char(20);
    define w_edo_cta             char(1);
    define existe                smallint;

    --     SET DEBUG FILE TO "/tmp/envio_corres.out";
    --     TRACE ON;


    --- Inicializa Variables de Salida
    let w_cod_ret   = "000";
    let existe = 0;
    let w_cuenta    = "";
    let w_edo_cta   = "";

    --- Valida que la Cuenta no sea Blanco
    if i_cuenta = " " then
    let w_cod_ret = "110";
    return w_cod_ret;
    end if

    --- Valida que Exista la Cuenta de Cheques y Extrae los Siguientes Campos
    select num_cte,  status_cta
      into w_cuenta, w_edo_cta
      from sc_maechq
     where empresa = pempresa 
       and cuenta = i_cuenta;
       
    if w_cuenta is null then
        let w_cod_ret = "100";
        return w_cod_ret;
    end if
    
    if w_edo_cta in("2","6","7","8") then
        let w_cod_ret = "200";
        return w_cod_ret;
    end if;
    
    if w_cuenta != i_cliente then
        let w_cod_ret = "122";
        return w_cod_ret;
    end if;
    
    if cual > 0 then
        select secuencia 
          into existe
          from bdinteg:si_direcciones
         where numcte = i_cliente
           and secuencia = cual;
        
        if existe is null or existe = 0 then
            let w_cod_ret = "130";
            return w_cod_ret;
        end if;
        
        update sc_maechq
           set direcc_envio = cual
         where empresa = pempresa 
           and cuenta = i_cuenta;
    end if;
    
    return w_cod_ret;
    
end procedure;

CREATE PROCEDURE "informix".sp_blqconsultarestraspaso
(
pNumArchivo INTEGER
)
RETURNING
	CHAR(6) 		AS cod_ret,
	CHAR(80) 		AS descripcion,
	CHAR(4)			AS cod_producto,
	CHAR(40)		AS nom_producto,
	CHAR(20)		AS num_cliente,
	CHAR(20)		AS num_tarjeta,
	CHAR(20)		AS num_cuenta,
	CHAR(104)		AS nom_cliente,
	DECIMAL(18,2)	AS sdo_cuenta,
	CHAR(10)		AS fec_ult_dep,
	CHAR(10)		AS fec_ult_ret,
	CHAR(1)			AS cod_status,
	CHAR(20)		AS status_cuenta,
	CHAR(16)		AS folio,
	CHAR(20)		AS resultado,
	CHAR(10)		AS fecha_trasp


	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);
    DEFINE cMensajeRet		CHAR(80);
	DEFINE cCodProducto		CHAR(4);
	DEFINE cNomProducto		CHAR(40);
	DEFINE cNumCliente		CHAR(20);
	DEFINE cNumTarjeta		CHAR(20);
	DEFINE cNumCuenta		CHAR(20);
	DEFINE cNomCliente		CHAR(104);
	DEFINE dSdoCuenta		DECIMAL(18,2);
	DEFINE cFecUltDep		CHAR(10);
	DEFINE cFecUltRet		CHAR(10);
	DEFINE cCodStatus		CHAR(1);
	DEFINE cStatusCuenta	CHAR(20);
	DEFINE cFolio			CHAR(16);
	DEFINE cResultado		CHAR(20);
	DEFINE cFecTrasp		CHAR(10);

	
	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
	LET cCodRet				= "000000";
	LET cMensajeRet			= "PROCESO EXITOSO";
	LET cCodProducto		= "";
	LET cNomProducto		= "";
	LET cNumCliente			= "";
	LET cNumTarjeta			= "";
	LET cNumCuenta			= "";
	LET cNomCliente			= "";
	LET dSdoCuenta			= 0.0;
	LET cFecUltDep			= "";
	LET cFecUltRet			= "";
	LET cCodStatus			= "";
	LET cStatusCuenta		= "";
	LET cFolio				= "";
	LET cResultado			= "";
	LET cFecTrasp			= "";

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN cCodRet,cMensajeRet,cCodProducto,cNomProducto,cNumCliente,cNumTarjeta,cNumCuenta,cNomCliente,dSdoCuenta,cFecUltDep,cFecUltRet,cCodStatus,cStatusCuenta,cFolio,cResultado,cFecTrasp;
       END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/respaldosbd/has/sp_blqconsultarestraspaso.out';
	--TRACE ON;
	
	-- VALIDA QUE NO VENGAN PARAMETROS VACIOS
	IF pNumArchivo IS NULL THEN 
		LET cCodRet = "000001";
		LET cMensajeRet = "FALTA EL NUMERO DEL ARCHIVO";
		RETURN cCodRet,cMensajeRet,cCodProducto,cNomProducto,cNumCliente,cNumTarjeta,cNumCuenta,cNomCliente,dSdoCuenta,cFecUltDep,cFecUltRet,cCodStatus,cStatusCuenta,cFolio,cResultado,cFecTrasp;
	ELSE
		-- BARRE LA CUENTAS CONCENTRADAS PARA EL ARCHIVO	
		FOREACH
			SELECT num_cte, tarjeta, cuenta, cliente, sdo_concentrado, LPAD(DAY(fech_ult_dep),2,"0") || "/" || LPAD(MONTH(fech_ult_dep),2,"0") || "/" || YEAR(fech_ult_dep), LPAD(DAY(fech_ult_ret),2,"0") || "/" || LPAD(MONTH(fech_ult_ret),2,"0") || "/" || YEAR(fech_ult_ret), folio, DECODE(resultado,1,"SATISFACTORIO",0,"SIN EXITO")
			INTO cNumCliente, cNumTarjeta, cNumCuenta, cNomCliente, dSdoCuenta, cFecUltDep, cFecUltRet, cFolio, cResultado
			FROM bdicheq:"informix".sc_cuentas_concentradas
			WHERE num_archivo = pNumArchivo

			LET cFecTrasp = LPAD(DAY(TODAY),2,"0") || "/" || LPAD(MONTH(TODAY),2,"0") || "/" || YEAR(TODAY);
			
			-- OBTIENE EL ESTATUS DE LA CUENTA
			SELECT mc.status_cta, UPPER(TRIM(me.descripcion)), mc.producto, pro.nombre
			INTO cCodStatus, cStatusCuenta, cCodProducto, cNomProducto
			FROM bdicheq:"informix".sc_maechq mc, bdicheq:"informix".sc_mae_estatus me, bdicheq:"informix".sc_producto pro
			WHERE mc.empresa = "001" 
			AND mc.cuenta = cNumCuenta
			AND mc.status_cta = me.cod_estatus
			AND mc.producto = pro.producto;
			
			RETURN cCodRet,TRIM(cMensajeRet),NVL(cCodProducto,""),TRIM(NVL(cNomProducto,"")),TRIM(NVL(cNumCliente,"")),TRIM(NVL(cNumTarjeta,"")),TRIM(NVL(cNumCuenta,"")),TRIM(NVL(cNomCliente,"")),NVL(dSdoCuenta,0.0),NVL(cFecUltDep,""),NVL(cFecUltRet,""),NVL(cCodStatus,""),TRIM(NVL(cStatusCuenta,"")),NVL(cFolio,""),TRIM(NVL(cResultado,"")),NVL(cFecTrasp,"") WITH RESUME;
		END FOREACH

		IF dbinfo('sqlca.sqlerrd2') = 0 THEN
			LET cCodRet = "000002";
			LET cMensajeRet = 'NO EXISTEN DATOS';
			RETURN cCodRet,cMensajeRet,cCodProducto,cNomProducto,cNumCliente,cNumTarjeta,cNumCuenta,cNomCliente,dSdoCuenta,cFecUltDep,cFecUltRet,cCodStatus,cStatusCuenta,cFolio,cResultado,cFecTrasp;
		END IF	
	END IF
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para la obtencion de datos de las cuentas concentradas para el reporte del mismo', 
'AUTOR: Mohamed Carreón ',
'FECHA: Marzo 2012',
'VERSION: 20120321.1623';

CREATE PROCEDURE "informix".sp_blqvalidacuentasconcentrar
(
pTipoEjec	SMALLINT, -- 1=POR TARJETA 2=POR CUENTA.
pTarjeta	CHAR(20),
pCuenta 	CHAR(20)
)
RETURNING
	CHAR(6)			AS cod_ret,
	CHAR(80) 		AS descripcion,
	CHAR(20)		AS cuenta,
	CHAR(20)		AS num_cliente,
	CHAR(104)		AS nom_cliente,
	CHAR(40)		AS producto,
	CHAR(20)		AS num_tarjeta,
	CHAR(20)		AS estatus,
	CHAR(10)		AS fecha_concent,
	DECIMAL(18,2)	AS impte_concent
	
	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);
    DEFINE cMensajeRet		CHAR(80);
	DEFINE cCuenta			CHAR(20);
	DEFINE cNumCliente		CHAR(20);
	DEFINE cNomCliente		CHAR(104);
	DEFINE cProducto		CHAR(40);
	DEFINE cNumTarjeta		CHAR(20);
	DEFINE cEstatus			CHAR(20);
	DEFINE cFechaConcent	CHAR(10);
	DEFINE dImpteConcent	DECIMAL(18,2);

	
	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
	LET cCodRet				= "000000";
	LET cMensajeRet			= "PROCESO EXITOSO";
	LET cCuenta				= "";
	LET cNumCliente			= "";
	LET cNomCliente			= "";
	LET cProducto			= "";
	LET cNumTarjeta			= "";
	LET cEstatus			= "";
	LET cFechaConcent		= "";
	LET dImpteConcent		= 0.0;
	


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN cCodRet,cMensajeRet,cCuenta,cNumCliente,cNomCliente,cProducto,cNumTarjeta,cEstatus,cFechaConcent,dImpteConcent;
       END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/respaldosbd/has/sp_blqvalidacuentasconcentrar.out';
	--TRACE ON;

	-- VALIDA QUE NO ESTEN VACIOS LOS PARAMETROS
	IF pTipoEjec IS NULL OR pTipoEjec NOT IN (1,2) OR (NVL(pTarjeta,"") = "" AND NVL(pCuenta,"") = "")  THEN
		LET cCodRet = "000001";
		LET cMensajeRet = "Faltan uno o mas parámetros";
		RETURN cCodRet,cMensajeRet,cCuenta,cNumCliente,cNomCliente,cProducto,cNumTarjeta,cEstatus,cFechaConcent,dImpteConcent;
	ELSE
		-- VALIDA SI ES CONSULTA POR TARJETA
		IF pTipoEjec = 1 THEN
			-- VALIDA QUE LA TARJETA EXISTE Y OBTIENE LA CUENTA
			SELECT cuenta
			INTO cCuenta
			FROM bdicheq:'informix'.sc_tarjeta 
			WHERE num_tarjeta = pTarjeta 
			AND status_tar = "A" 
			AND tipo_tarjeta = "T";
			
			IF NVL(cCuenta,"") = "" THEN
				LET cCodRet = "000002";
				LET cMensajeRet = "La Tarjeta No Existe";
				RETURN cCodRet,cMensajeRet,cCuenta,cNumCliente,cNomCliente,cProducto,cNumTarjeta,cEstatus,cFechaConcent,dImpteConcent;
			ELSE
				-- OBTIENE LOS DATOS Y VALIDA LA CUENTA DE CHEQUES ESTE CONCENTRADA
				SELECT cc.cuenta, cc.num_cte, TRIM(cc.cliente), TRIM(cc.producto), cc.tarjeta, cc.fecha_concentra, cc.sdo_concentrado
				INTO cCuenta,cNumCliente,cNomCliente,cProducto,cNumTarjeta,cFechaConcent,dImpteConcent
				FROM bdicheq:"informix".sc_cuentas_concentradas cc, bdicheq:"informix".sc_maechq mc
				WHERE cc.cuenta = mc.cuenta
				AND mc.status_cta = "6"
				AND cc.tarjeta = pTarjeta;
				
				IF NVL(cCuenta,"") = "" THEN
					LET cCodRet = "000003";
					LET cMensajeRet = "La Cuenta de la tarjeta no está concentrada";
				ELSE
					LET cEstatus = "concentrada";
				END IF
				
				RETURN cCodRet,cMensajeRet,NVL(cCuenta,""),NVL(cNumCliente,""),NVL(cNomCliente,""),NVL(cProducto,""),NVL(cNumTarjeta,""),NVL(cEstatus,""),NVL(cFechaConcent,""),NVL(dImpteConcent,0.0);
			END IF
		-- VALIDA SI ES CONUSLTA POR CUENTA
		ELIF pTipoEjec = 2 THEN
				-- OBTIENE LOS DATOS Y VALIDA LA CUENTA DE CHEQUES ESTE CONCENTRADA
				SELECT cc.cuenta, cc.num_cte, TRIM(cc.cliente), TRIM(cc.producto), cc.tarjeta, cc.fecha_concentra, cc.sdo_concentrado
				INTO cCuenta,cNumCliente,cNomCliente,cProducto,cNumTarjeta,cFechaConcent,dImpteConcent
				FROM bdicheq:"informix".sc_cuentas_concentradas cc, bdicheq:"informix".sc_maechq mc
				WHERE cc.cuenta = mc.cuenta
				AND mc.status_cta = "6"
				AND cc.cuenta = pCuenta;
				
				IF NVL(cCuenta,"") = "" THEN
					LET cCodRet = "000002";
					LET cMensajeRet = "La Cuenta no está concentrada";
				ELSE
					LET cEstatus = "concentrada";
				END IF
				
				RETURN cCodRet,cMensajeRet,NVL(cCuenta,""),NVL(cNumCliente,""),NVL(cNomCliente,""),NVL(cProducto,""),NVL(cNumTarjeta,""),NVL(cEstatus,""),NVL(cFechaConcent,""),NVL(dImpteConcent,0.0);
		END IF
	END IF

END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para realizar la validacion y la obtención de datos de una cuenta concentrada de cheques', 
'AUTOR: Mohamed Carreón ',
'FECHA: Marzo del 2012',
'VERSION: 20120321.1616';

CREATE PROCEDURE "informix".sp_dispersionnominavalidacionestatus( pCuenta CHAR(20),
                                                                  pNumeroEmpresa CHAR(3),
                                                                  pFechaGeneracion CHAR(10),
                                                                  pFolioArchivo INTEGER,
                                                                  pFechaActual CHAR(10),
                                                                  pHoraActual CHAR (8),
                                                                  pNombreArchivo CHAR(17),
                                                                  pNumeroEmpleado CHAR(10),
                                                                  pImporteEmpleado MONEY(18,2),
                                                                  pImporteNoAbonado MONEY(18,2),
                                                                  piTipoEmpresa		CHAR(1) )
RETURNING CHAR(3),CHAR(1),CHAR(1),MONEY(18,2),CHAR(4),CHAR(4);
    
    DEFINE vcodret          CHAR(3);
    DEFINE cEstatusCuenta   CHAR(1);
    DEFINE cSucursalAbono   CHAR(4);
    DEFINE cSucursalCargo   CHAR(4);
    DEFINE cMotivo          CHAR(2);
    DEFINE cConsulta        CHAR(1);
    DEFINE iExiste          INTEGER;
    DEFINE iAceptab         INTEGER;
    DEFINE iSqlerr          INTEGER;
    DEFINE iBandera         INTEGER;

    Begin
    
    ON EXCEPTION SET iSqlerr
        IF iSqlerr <> 0 THEN
            Let vcodret = iSqlerr; 
            RETURN vcodret,cEstatusCuenta,cConsulta,NVL(pImporteNoAbonado,'0.00'),cSucursalCargo,cSucursalAbono;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    --- Set Debug File To '/tmp/sp_dispersionnominavalidacionestatus.out';
    --- Trace On;
    
    LET vcodret = "000";
    LET cEstatusCuenta	 = "";
    LET cSucursalAbono = "";
    LET cSucursalCargo	= "";
    LET cMotivo = "";
    LET cConsulta = "";
    LET iExiste = 0;
    LET iAceptab = 0;
    LET iBandera = 0;

    IF  pCuenta  <> "" AND pNumeroEmpresa <> "" AND pFechaGeneracion <> "" AND pFolioArchivo <> 0 AND pFechaActual <> "" AND pHoraActual <> "" THEN
        LET iBandera = 1;
        LET pImporteNoAbonado = '0.00';
    ELSE
        IF pCuenta  <> ""  AND pNombreArchivo <> "" AND pNumeroEmpleado <> "" AND NOT pImporteEmpleado IS NULL  AND NOT pImporteNoAbonado IS NULL AND piTipoEmpresa <> "" THEN
            LET iBandera = 2;
        END IF
    END IF;

    IF iBandera <> 1 AND iBandera <> 2 THEN
        LET vcodret = '805';
    END IF

    /* INICIO de Consulta para la cuenta eje */
    IF iBandera = 1 THEN
        Let cEstatusCuenta = '';
        Let cSucursalCargo = '';
        
        SELECT status_cta, sucursal,motivo 
          INTO cEstatusCuenta, cSucursalCargo, cMotivo
          FROM bdicheq:sc_maechq 
         WHERE empresa = '001' 
           AND cuenta = pCuenta;
        
        /* La Cuenta esta Cancelada */
        IF cEstatusCuenta IN('2','6','7','8') THEN   
            Let vcodret = "815";
            
             /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
            UPDATE bdicheq:sc_nominaencabezadosumario  
               SET status = '8', 
                   fecha_aplicado = pFechaActual, 
                   hora_aplicado = pHoraActual
             WHERE empresa = pNumeroEmpresa 
               AND fecha_gen = pFechaGeneracion 
               AND folio_archivo = pFolioArchivo;
        END IF

        IF cEstatusCuenta = '3' THEN   -- La Cuenta esta Bloqueada

            SELECT "1" 
              INTO iExiste 
              FROM sc_ctabloqueo 
             WHERE cuenta = pCuenta;

            IF iExiste = "1" THEN

                SELECT opcion 
                  INTO iAceptab 
                  FROM sc_ctabloqueo 
                  WHERE cuenta = pCuenta;

                IF iAceptab = 4 THEN
                    Let vcodret = "820";
                    
                    /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
                    UPDATE bdicheq:sc_nominaencabezadosumario  
                       SET status = '9',
                           fecha_aplicado = pFechaActual,
                           hora_aplicado = pHoraActual
                     WHERE empresa = pNumeroEmpresa
                       AND fecha_gen = pFechaGeneracion
                       AND folio_archivo = pFolioArchivo;
                END IF;

                IF iAceptab = 3 THEN
                    Let vcodret = "820";
                    
                    /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
                    UPDATE bdicheq:sc_nominaencabezadosumario  
                       SET status = '9',
                           fecha_aplicado = pFechaActual,
                           hora_aplicado = pHoraActual
                     WHERE empresa = pNumeroEmpresa
                       AND fecha_gen = pFechaGeneracion
                       AND folio_archivo = pFolioArchivo;
                END IF;
            ELSE
                /* Selecciono el campo cargo de sc_bloqueo, para saber si el tipo de bloqueo admite o no cargos */
                SELECT cargo 
                  INTO cConsulta 
                  FROM sc_bloqueo 
                 WHERE codigo=cMotivo;

                IF cConsulta = 'N' THEN
                    Let vcodret = "820";
                    
                    /* Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo */
                    UPDATE bdicheq:sc_nominaencabezadosumario  
                       SET status = '9',
                           fecha_aplicado = pFechaActual,
                           hora_aplicado = pHoraActual
                     WHERE empresa = pNumeroEmpresa
                       AND fecha_gen = pFechaGeneracion
                       AND folio_archivo = pFolioArchivo;
                END IF
            END IF
        END IF
    END IF  /* FIN de Consulta para la cuenta eje */

    /* INICIO de Consulta para la cuenta Empleado */
    IF iBandera = 2 THEN
        Let cEstatusCuenta = '';
        Let cSucursalAbono = '';
        LET  cConsulta = "S";
        
        SELECT status_cta, sucursal,motivo 
          INTO cEstatusCuenta, cSucursalAbono,cMotivo 
          FROM bdicheq:sc_maechq
         WHERE empresa = '001' 
           AND cuenta = pCuenta;

        IF cEstatusCuenta IN('2','6','7','8') THEN
            LET  cConsulta = "N"; 
            
            /* Cuenta Cancelada */
            UPDATE bdicheq:sc_nominamovimientos
               SET status = cEstatusCuenta   
             WHERE nombre_archivo = pNombreArchivo 
               AND num_empleado = pNumeroEmpleado;

            IF piTipoEmpresa = 2 THEN
                Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
            END IF
        END IF
        
        IF cEstatusCuenta = '3' THEN
            SELECT "1" 
              INTO iExiste  
              FROM sc_ctabloqueo 
             WHERE cuenta = pCuenta;

            IF iExiste = "1" THEN

                SELECT opcion 
                  INTO iAceptab 
                  FROM sc_ctabloqueo 
                 WHERE cuenta = pCuenta;

                IF iAceptab = 4 THEN
                    LET cConsulta = "N";
                    Let vcodret = "820";
                    
                    /* Cuenta Bloqueada */
                    UPDATE bdicheq:sc_nominamovimientos 
                       SET status = cEstatusCuenta
                     WHERE nombre_archivo = pNombreArchivo 
                       AND num_empleado = pNumeroEmpleado;

                    IF piTipoEmpresa = 2 THEN
                        Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
                    END IF
                END IF;
                
                IF iAceptab = 2 THEN
                    LET cConsulta = "N";
                    Let vcodret = "820";
                    
                    /* Cuenta Bloqueada */
                    UPDATE bdicheq:sc_nominamovimientos 
                       SET status = cEstatusCuenta
                     WHERE nombre_archivo = pNombreArchivo 
                       AND num_empleado = pNumeroEmpleado;

                    IF piTipoEmpresa = 2 THEN
                        Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
                    END IF
                END IF;
            ELSE
                /* Selecciono el campo Abono de sc_bloqueo, para saber si el tipo de bloqueo admite o no Abonos */
                SELECT abono 
                  INTO cConsulta 
                  FROM sc_bloqueo 
                 WHERE codigo = cMotivo;

                IF cConsulta = 'N' THEN
                    Let vcodret = "820";

                    /* Cuenta Bloqueada */
                    UPDATE bdicheq:sc_nominamovimientos 
                       SET status = cEstatusCuenta
                     WHERE nombre_archivo = pNombreArchivo 
                       AND num_empleado = pNumeroEmpleado;

                    IF piTipoEmpresa = 2 THEN
                        Let pImporteNoAbonado = pImporteNoAbonado + pImporteEmpleado;
                    END IF
                END IF
            END IF
        END IF
    END IF  /* FIN de Consulta para la cuenta Empleado */
    
    RETURN vcodret,cEstatusCuenta,cConsulta,pImporteNoAbonado,cSucursalCargo,cSucursalAbono;
    
    END
    
END Procedure

DOCUMENT
'DESCRIPCION: Genera las validaciones para el estatus de la cuenta a consultar para la dispersion de nomina"',
'AUTOR: Jesus Antonio Bastidas Lopez',
'FECHA: Abril de 2009',
'VERSION: 200904',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_obtenercuentascheques(pempresa CHAR(3),pnum_cte CHAR(9),pProducto CHAR(4),pmoneda CHAR(2),pRegistro SMALLINT)
RETURNING CHAR(5),CHAR(20),money(14,2);
    
    --*******************************************
    --sp_obtenerCuentasCheques
    --Objetivo: obtener las cuentas efectiva cheques, de un cliente especifico
    --Autor: Francisco Rodriguez Ibarra
    --Fecha: 30 marzo 2010
    --*********************************************
    
    --Declaracion de variables
    DEFINE vSqlErr 		INTEGER;
    DEFINE cod_ret  	CHAR(5);
    DEFINE v_cuenta		CHAR(20);
    DEFINE vSdoCta      money(14,2);
    DEFINE vRegistros    INTEGER;
    DEFINE iCont		INTEGER;
    
    --Asignacion de Valores a Variables
    LET cod_ret='00000';
    LET vSqlErr = 0;
    LET v_cuenta ='';
    LET vSdoCta = 0;
    LET iCont=0;
    LET vRegistros=0;

    BEGIN

    ON EXCEPTION SET vSqlErr
        IF vSqlErr <> 0 THEN
            let cod_ret = vSqlErr;
            --ROLLBACK WORK;
            RETURN cod_ret, v_cuenta, vSdoCta;
        END IF;
    END EXCEPTION;

    IF ( pempresa = '' OR pempresa IS NULL OR pnum_cte = '' OR
         pnum_cte IS NULL OR pmoneda = '' OR pmoneda IS NULL OR
         pRegistro = '' OR pRegistro IS NULL) THEN
        LET cod_ret = 100; --Parametros no validos.
        RETURN cod_ret, v_cuenta, vSdoCta;
    END IF

    SET ISOLATION DIRTY READ;

    FOREACH
        SELECT SKIP pRegistro FIRST 10 cuenta,sdo_actual
          INTO v_cuenta ,vSdoCta
          FROM bdicheq:sc_maechq  
         WHERE empresa = TRIM(pempresa)
           AND producto = TRIM(pProducto) 
           AND num_cte = TRIM(pnum_cte)
           AND status_cta NOT IN('2','6','7','8')

        LET iCont = iCont + 1;
        RETURN cod_ret, v_cuenta, vSdoCta WITH RESUME;
    END FOREACH

    IF ( iCont = 0 AND pRegistro = 0 ) THEN
        LET cod_ret = 101; -- Cliente No tiene cuentas
        RETURN cod_ret, v_cuenta, vSdoCta;
    END IF

    END;
    
END PROCEDURE;

create procedure "informix".sp_traecuenta( pempresa char(3),
                                           pcliente  char(20),
                                           ptipo char(1) )
returning char(5),   -- vcodret
          char(20),  -- vcuenta
          char(15);  -- pcliente

    -- ********************************************************************
    -- Nombre:              sp_traecuenta
    -- Version              1.0.0
    -- Objetivo:            Consulta de Cuentas de cheque por Cliente
    -- SI es tipo = 1, consulta por el Cliente;  Si es tipo=2, Consulta por
    -- el Numero de Cuenta.
    -- Creado por:          Jaime Santiago
    -- Modificado por:      Alejandro Rueda
    -- Fecha:               Febrero 2010
    -- ********************************************************************

    -- // Definicion de variables
    DEFINE vcodret         char(5);
    DEFINE vsqlerr         integer;
    DEFINE vcuenta         char(20);
    DEFINE pcliente2       char(20); 
    
    LET vcodret      = "000";
    LET vsqlerr      = 0;

    -- SET DEBUG FILE TO "/tmp/sp_traecuenta.out";
    -- TRACE ON;
    
    BEGIN
    
    on exception set vsqlerr
        IF vsqlerr <> 0 then
            LET vcodret = vsqlerr;
            return vcodret,null,null;
        END IF;
    END exception;
    
    --//Si la opcion es 2, buscamos el Numero del Cliente.
    IF ptipo = 2 THEN
        LET pcliente2 = pcliente;
        LET pcliente = " ";  
        
        SELECT distinct num_cte
          INTO pcliente
          FROM bdicheq:sc_maechq
         WHERE num_cte = pcliente2;
         
        IF pcliente = "" OR pcliente IS NULL THEN
            LET vcodret  = "104"; --//No existe el nuemro de cliente
            return vcodret, "", pcliente ;
        END IF
        
    --//Si la opcion es 3, buscamos el Numero del Cliente x la cuenta.
    ELIF ptipo = 3 THEN
        LET pcliente2 = pcliente;
        LET pcliente = " ";  
        
        SELECT distinct num_cte
          INTO pcliente
          FROM bdicheq:sc_maechq
         WHERE cuenta = pcliente2;
    END IF 

    -- CONSULTA QUE DEVUELVE LAS CUENTAS DE CHEQUES DE EL CLIENTE SELECCIONADO.
    LET vcuenta = "";
    
    FOREACH
        SELECT cuenta
          INTO vcuenta
          FROM bdicheq:sc_maechq mae, 
               bdicheq:sc_producto prod 
         WHERE mae.num_cte = pcliente
           AND mae.producto = prod.producto
           AND mae.status_cta NOT IN('2','6','7','8')
           AND prod.val_chequeras = 'S'
         ORDER BY cuenta
         
        return vcodret, vcuenta, pcliente with resume;
    END FOREACH;

    IF vcuenta = "" OR vcuenta IS NULL THEN
        LET vcodret = "995"; --//cliente no tiene cuenta con chequeras
        return vcodret, "", pcliente;
    END IF;

    END
    
END procedure;

create procedure "informix".susp_chqs( i_empresa char(3),
                                       i_sucursal char(4),
                                       i_usuario char(8),
                                       i_cuenta char(20),
                                       i_nro_inicial integer,
                                       i_nro_final integer,
                                       i_causa char(1) )
returning char(5);

    define d_cod_ret         char(5);
    define v_row             integer;
    define d_inicial         int;
    define d_final           int;
    define d_cant_chqs       int;
    define d_fecha_hoy       date;
    define v_utiliza         char(1);
    define v_cal_int_chq     char(1);
    define d_cont_cta        char(20);
    define d_cont_nro        int;
    define d_status_cta      char(1);
    define d_sucursal        char(4);
    define d_producto        char(4);
    define d_suspen          char(1);
    define sql_err           integer;
    define longitud          smallint;
    define v_long_cta        smallint;
    define v_hora_alta      datetime hour to second;
    define v_nomusu         char(40);
    
    let d_cod_ret = "000";
    let sql_err   = 0;

    begin
    
    on exception set sql_err
        if sql_err <> 0 then
            let d_cod_ret = sql_err;
            return d_cod_ret;
        end if;
    end exception;

    --- Valida Sucursal
    if i_sucursal = " " then
        let d_cod_ret = "110";
        return d_cod_ret;
    end if;

    --- Valida Usuario
    if i_usuario = " " then
        let d_cod_ret = "110";
        return d_cod_ret;
    end if;

    select nombre 
      into v_nomusu 
      from bdinteg:si_ejecut
     where ejecutivo = i_usuario;
     
    if v_nomusu is null then
        let d_cod_ret = "106";
        return d_cod_ret;
    end if;
    
    let v_nomusu = i_usuario||" "||v_nomusu;

    ---  Numero Inicial Igual a Blanco
    if i_nro_inicial = " " or i_nro_inicial = 0 then
        let d_cod_ret = "110";
        return d_cod_ret;
    end if;

    ---- Numero final = Blanco
    if i_nro_final = " " then
        let d_cod_ret = "110";
        return d_cod_ret;
    end if;

    ---- Numero Inicial Mayor a Final
    if i_nro_inicial > i_nro_final then
        let d_cod_ret = "559";
        return d_cod_ret;
    end if;
    
    ---- Cantidad de Cheques Mayor a 300
    let d_cant_chqs = i_nro_final - i_nro_inicial + 1;
    
    if d_cant_chqs > 300 then
        let d_cod_ret = "555" ;
        return d_cod_ret;
    end if;
    
    ---- Valida que la Cuenta de Cheques no ser Blanco
    if i_cuenta = " " or i_cuenta is null then
        let d_cod_ret = "110";
        return d_cod_ret;
    end if;
    
    ---- Valida que Exista la Cuenta de Cheques
    select cuenta,status_cta
      into d_cont_cta,d_status_cta
      from sc_maechq
     where empresa = i_empresa 
       and cuenta = i_cuenta;
       
    if  d_cont_cta is null then
        let d_cont_cta = "0";
    end if;

    if d_cont_cta != i_cuenta then
        let d_cod_ret = "100";
        return d_cod_ret;
    end if;

    ---- Valida que la Cuenta no Este Cancelada
    if d_status_cta in("2","6","7","8") then
        let d_cod_ret = "200";
        return d_cod_ret;
    end if;

    select fecha_hoy 
      into d_fecha_hoy
      from sc_fechas 
     where empresa = i_empresa;

    let v_hora_alta = current hour to second;

    if i_nro_inicial = i_nro_final then
        select rowid,estado 
          into v_row,v_utiliza
          from sc_contch
         where empresa = i_empresa 
           and cuenta = i_cuenta
           and numero = i_nro_inicial;
        
        if v_row is null then
            select rowid,estado 
              into v_row,v_utiliza
              from sc_histch
             where empresa = i_empresa 
               and cuenta = i_cuenta
               and numero = i_nro_inicial;
            
            if v_row is null then
                insert into sc_histch
                values(i_empresa,i_cuenta,i_nro_inicial,"S",d_fecha_hoy,0);
                
                insert into sc_alertados 
                values(i_empresa,i_cuenta,i_nro_inicial,d_fecha_hoy,v_hora_alta,v_nomusu,i_causa);
                
                let d_cod_ret="000";
                return d_cod_ret;
            else
                if v_utiliza="P" or v_utiliza="X" then
                    let d_cod_ret="600";
                    return d_cod_ret;
                end if;
                
                if v_utiliza="S" then
                    let d_cod_ret="700";
                    return d_cod_ret;
                else
                    update sc_histch
                       set (estado,fecha_alta,importe) = ("S",d_fecha_hoy,0)
                     where rowid = v_row;
                    
                    insert into sc_alertados
                    values(i_empresa,i_cuenta,i_nro_inicial,d_fecha_hoy,v_hora_alta,v_nomusu,i_causa);
                    
                    let d_cod_ret="000";
                    return d_cod_ret;
                end if;
            end if;
        else
            if v_utiliza="P" or v_utiliza="X" then
                let d_cod_ret="600";
                return d_cod_ret;
            end if;
            
            if v_utiliza="S" then
                let d_cod_ret="700";
                return d_cod_ret;
            else
                update sc_contch
                   set (estado,fecha_alta,importe) = ("S",d_fecha_hoy,0)
                 where rowid=v_row;
                 
                insert into sc_alertados 
                values(i_empresa,i_cuenta,i_nro_inicial,d_fecha_hoy,v_hora_alta,v_nomusu,i_causa);
                
                let d_cod_ret="000";
                return d_cod_ret;
            end if;
        end if;
    else
        -- Busca en Control de Chequeras para Suspender Cheque
        let d_final = i_nro_final;
        let d_inicial = i_nro_inicial;
        
        for d_inicial = i_nro_inicial to d_final
            select cuenta,numero 
              into d_cont_cta,d_cont_nro
              from sc_contch
             where empresa = i_empresa 
               and cuenta = i_cuenta 
               and numero = d_inicial;
        
            if d_cont_cta is null then
                let d_cont_cta = "0";
            end if;
            
            if i_cuenta != d_cont_cta or d_inicial != d_cont_nro then
                select cuenta,numero 
                  into d_cont_cta,d_cont_nro
                  from sc_histch
                 where empresa = i_empresa 
                   and cuenta = i_cuenta
                   and numero = d_inicial;
                
                if d_cont_cta is null then
                    let d_cont_cta = "0";
                end if;
                
                if i_cuenta != d_cont_cta or d_inicial != d_cont_nro then
                    insert into sc_histch
                    values(i_empresa,i_cuenta,d_inicial,"S",d_fecha_hoy,0);
                    
                    insert into sc_alertados
                    values(i_empresa,i_cuenta,d_inicial,d_fecha_hoy,v_hora_alta,v_nomusu,i_causa);
                else
                    update sc_histch
                       set (estado,fecha_alta,importe)=("S",d_fecha_hoy,0)
                     where empresa = i_empresa 
                       and cuenta = i_cuenta
                       and numero = d_inicial;
                       
                    insert into sc_alertados
                    values(i_empresa,i_cuenta,d_inicial,d_fecha_hoy,v_hora_alta,v_nomusu,i_causa);
                end if;
            else
                update sc_contch
                   set (estado,fecha_alta,importe) = ("S",d_fecha_hoy,0)
                 where empresa = i_empresa 
                   and cuenta = i_cuenta 
                   and numero = d_inicial;
                   
                insert into sc_alertados
                values(i_empresa,i_cuenta,d_inicial,d_fecha_hoy,v_hora_alta,v_nomusu,i_causa);
            end if;
        end for;
    end if;
    
    return d_cod_ret;
    
    end
    
end procedure;

create procedure "informix".valida( pempresa char(3), pcuenta char(20) )
returning char(5), char(4), char(4);

    define vcodret char(5);
    define vstatus char(2);
    define vsucursal, vproducto char(4);
    define vcuenta char(20);
    
    let vcodret = "000";
    
    select cuenta, status_cta, sucursal, producto
      into vcuenta, vstatus, vsucursal, vproducto
      from sc_maechq
     where empresa = pempresa 
       and cuenta = pcuenta;
       
    if vcuenta is null or vcuenta = "0000000000" or vstatus in("2","6","7","8") or vstatus = "3" then
        let vcodret = "100";
        let vsucursal = " ";
        let vproducto = " ";
    end if;
    
    return vcodret, vsucursal, vproducto;
    
end procedure;

create procedure "informix".respaldo_pba(pempresa char(3), ptipo_resp char(1))

returning char(5);

    define vcodret     char(5);
    define vdirectorio char(50);
    define vdia        char(2);
    define vmes        char(2);
    define vano        char(4);
    define vtabla      char(20);
    define vtablaid    integer;
    define vcolnomb    char(20);
    define vsql2       char(1000);
    define vnomtabla   char(400);
    define vproceso    char(10);
    define vfecha_hoy  date;
    define vruta       char(400);
    define vsqlerr     integer;
    define vexiste     char(1);
    define vexiste3    char(1);
    define vexiste2    integer;
    define vexistefin  integer;
    define vsistema    char(2);
    define vgusuario   char(10);
    define vproceso2   char(20);
    define vsql        char(600);
    define vstmt       char(250);
    
    let vcodret    = "000";
    let vsistema   = "01";
    let vgusuario  = user;
    let vexiste2   = 0;
    let vexiste3   = '';
    let vexistefin = 0;
    let vproceso2  = "respaciechq";
    let vsql       = '';
    let vstmt      = '';
    
    set debug file to "respaldo.out";
    trace on;
    
    begin
    
    on exception set vsqlerr
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
            
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso2||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasrespacie.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
            SYSTEM vstmt;
            
            return vcodret;
        end if;
    end exception;

    select fecha_hoy 
      into vfecha_hoy
      from sc_fechas 
     where empresa = pempresa;

    if ptipo_resp = "A" or ptipo_resp = "a" then
        let vruta = "/cheques/a_cierre/";
        let vproceso = "respacie";
    else
        let vruta = "/cheques/d_cierre/";
        let vproceso = "respdcie";
    end if
    
    let vruta = trim(vruta)||"empresa"||pempresa||"/";

    select count(*)   
      into vexiste2
      from bdinteg:sx_contproc  
     where empresa = pempresa  
       and proceso = vproceso2
       and fecha   = vfecha_hoy
       and sistema = vsistema;

    if vexiste2 = 0 then
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso2||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horasrespacie.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
        SYSTEM vstmt;
    else
        select count(*)   
          into vexistefin
          from bdinteg:sx_contproc  
         where empresa     = pempresa  
           and proceso     = vproceso2
           and fecha       = vfecha_hoy
           and sistema     = vsistema
           and status_proc = "F"; 

        if vexistefin = 0 then
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso2||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasrespacie.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
            SYSTEM vstmt;
        else
            LET vcodret = '958';
            
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso2||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasrespacie.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
            SYSTEM vstmt;
        end if
    end if;  
    
    SELECT "1"
      INTO vexiste3
      FROM sc_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha = vfecha_hoy;

    IF vexiste3 = "1" THEN
        LET vcodret = "958";
        RETURN vcodret;
    END IF

    select valor 
      into vdirectorio
      from sc_param
     where empresa = pempresa 
       and codparam = "rutaresp";

    if vdirectorio is null or vdirectorio = " " then
        let vcodret = "960";
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vgusuario||''','||
                   'status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso2||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horasrespacie.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
        SYSTEM vstmt;
        
        return vcodret;
    else
        let vdirectorio = TRIM(vdirectorio);
    end if

    BEGIN
    
    ON EXCEPTION IN (-668) SET vsqlerr
        SET DEBUG FILE TO TRIM(vnomtabla) || " respalda.err";
        TRACE ON;
        
        LET vcodret = "000";
        LET vsql2 = vsql2;
    END EXCEPTION WITH RESUME;

    let vdia = day(vfecha_hoy);
    let vmes = month(vfecha_hoy);
    let vano = year(vfecha_hoy);

    if vdia <= 9 then
        let vdia = "0"||vdia;
    end if

    if vmes <= 9 then
        let vmes = "0"||vmes;
    end if

    let vruta = TRIM(vdirectorio)||TRIM(vruta)||vdia||vmes||vano;
    let vsql2 = "mkdir -p "||vruta;
    
    SYSTEM vsql2;
    
    END

    SET ISOLATION TO DIRTY READ;
    
    foreach
        select trim(nombre_tabla) 
          into vtabla
          from sc_tablas
          
        let vtabla = TRIM(vtabla);
        
        select tabid 
          into vtablaid
          from systables
         where tabname = vtabla;

        -- // Tabla no existe en la base de datos
        if vtablaid is null then
            let vcodret = "961";
            
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso2||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasrespacie.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
            SYSTEM vstmt;
            
            return vcodret;
        end if

        let vnomtabla = TRIM(vruta)||"/"||TRIM(vtabla)||"."||trim(vdia)||trim(vmes)||trim(vano);
        
        -- // Verifica si existe empresa en la tabla
        let vnomtabla = trim(vnomtabla);
        
        select 1 
          into vexiste
          from syscolumns
         where tabid = vtablaid 
           and colname = "empresa";
           
        if vexiste is null then
            let vsql2 = 'echo " SET '||
                       'ISOLATION  DIRTY READ; '||
                       'UNLOAD TO ' || vnomtabla ||' SELECT * FROM '||vtabla ||';' ||
                       '"' ||
                       ' > querychq.sql';
        else
            let vsql2 = 'echo " SET '||
                       'ISOLATION DIRTY READ; '||
                       'UNLOAD TO ' || vnomtabla ||
                       'SELECT * FROM '||vtabla|| ' where empresa = '||
                       pempresa || ';'||
                       '"' || ' > querychq.sql';
        end if
        
        let vsql2 = vsql2;
        SYSTEM vsql2;
        
        LET vsql2 = "/ifxsif01/bin/dbaccess bdicheq querychq.sql";
        SYSTEM vsql2;
    end foreach

    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc = '''||'F'||''','||
               'codret          = '''||vcodret||''','||
               'hora_fin        = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso2||''' '||
               'AND fecha     = '''||vfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horasrespacie.sql';
    SYSTEM vsql;
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasrespacie.sql';
    SYSTEM vstmt;
    
    update sc_contproc
       set fecha = vfecha_hoy
     where empresa = pempresa 
       and proceso = vproceso;

    return vcodret;
    
    end
    
end procedure;

CREATE PROCEDURE "informix".sp_actparamcierre_vb(pempresa CHAR(3))
RETURNING CHAR(5);
 
    --- ################################################################################
    --- ##  Nombre:              sp_actparamcierre_vb                                 ##
    --- ##  Version:             1.0.1                                                ##
    --- ##  Objetivo:            Programa inicial del cierre diario de captacion      ##
    --- ##  Creado por:                                                               ##
    --- ##  ModIFicado por:      JICS                                                 ##
    --- ##  Ultima Modificacion: Diciembre 2011                                       ##
    --- ################################################################################

    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE vsqlerr          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE error_info       CHAR(50);
    DEFINE vfecha_hoy       DATE;
    DEFINE vpromedio        INTEGER;
    DEFINE vbrinca          INTEGER;
    DEFINE vcuenta          CHAR(20);
    
    LET vcodret    = "";
    LET vcodret2   = "";
    LET vcodret3   = " ";
    LET vsqlerr    = 0;
    LET isam_err   = 0;
    LET error_info = '';
    LET vfecha_hoy = ' ';    
    LET vpromedio  = 0;
    LET vbrinca    = 0;
    LET vcuenta    = '';
    
    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actparamcierre_vb.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actparamcierre_vb.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    SELECT ROUND(COUNT(*)/2)
      INTO vpromedio
      FROM sc_maechq
     WHERE producto = '2000'
       AND status_cta NOT IN("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vfecha_hoy);
       
    LET vbrinca = vpromedio;
    
    FOREACH
        SELECT SKIP vbrinca FIRST 1 cuenta
          INTO vcuenta
          FROM sc_maechq
         WHERE producto = '2000'
           AND status_cta not in("2","6","7","8")
           AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vfecha_hoy)
         ORDER BY cuenta
     
        UPDATE sc_param
           SET valor = vcuenta
         WHERE empresa = pempresa
           AND codparam = 'CtaEjeCierreCheques';
           
        LET vcodret = "000";
    END FOREACH;

    RETURN vcodret;

    END;

END PROCEDURE;

create procedure "informix".protsdo(pempresa char(3),
                                    suc char(4),
                                    usuariox char(8),
                                    transaccion char(4),
                                    transacc_suc char(4),
                                    folsuc char(16),
                                    cta char(20),
                                    docto integer,
                                    pmonto_concilia money(14,2),
                                    divisa char(2),
                                    clave integer)

returning char(5),char(4);

    --##############################################################################
    --## Procedimiento       : protsdo
    --## Version             : 1.0.0
    --## Objetivo            : Conciliacion de movimientos intercar
    --## Supuestos           :
    --## Modificado por      : Alejandro Rueda Sanchez
    --## Fecha modificacion  : Agosto 2009 PISA
    --## Fecha modificacion  : 01/03/2010 JYDG
    --##############################################################################

    -- // Variables Globales conciliacion 
    DEFINE GLOBAL vg_estatus    VARCHAR(5)  DEFAULT " ";
    DEFINE GLOBAL vgrfc_comer   VARCHAR(20) DEFAULT " ";
    DEFINE GLOBAL vgreferencia  VARCHAR(40) DEFAULT " ";

    -- // Definicion de Variables
    define sql_err,isam_err int;
    define cod_ret char(5);
    define v_tiptran, v_tpcheque, v_moneda, motiv char(2);
    define ctar char(20);
    define v_valdoc,nat char(1);
    define valdoc char(1);
    define suc_cta char(4);
    define v_plaza char(3);
    define prod char(8);
    define horax char(12);
    define fechax date;
    define vfechacalendario date;
    define v_status,cargox char(1);
    define saldo,reten money(16,2);
    define monto_docret, v_montolib money(16,2);
    define v_long_cta,longitud smallint;
    define v_cal_int_chq char(1);
    define tranret char(4);
    define v_clave integer;
    define v_usuario char(8);
    define v_referencia char(40);
    define vnum_tarjeta char(16);
    define vmaxsec smallint;

    -- // Variables para conciliacion
    DEFINE vtamanio      SMALLINT;
    DEFINE vt_indicador  CHAR(1);
    DEFINE vt_newfolio   CHAR(16);
    DEFINE vt_folsucorig CHAR(16);

    DEFINE vstatus_cta CHAR(1);
    DEFINE vexiste CHAR(1);
    define vaceptab char(1);
    define vacepcargo char(1);

    LET sql_err = 0;
    LET isam_err = 0;
    LET v_tiptran = "";
    LET v_tpcheque= "";
    LET v_moneda ="";
    LET motiv = "";
    LET ctar = "";
    LET v_valdoc = "";
    LET nat = "";
    LET valdoc = "";
    LET suc_cta = "";
    LET v_plaza = "";
    LET prod = "";
    LET cod_ret = "000";
    LET horax = "";
    LET fechax = " ";
    LET vfechacalendario = "";
    LET v_status = "";
    LET cargox = "";
    LET saldo = 0;
    LET reten = 0;
    LET monto_docret= 0;
    LET v_montolib = 0;
    LET v_long_cta= 0;
    LET longitud = 0;
    LET v_cal_int_chq = "";
    LET tranret = "";
    LET v_clave = 0;
    LET v_usuario = "";
    LET v_referencia = "";
    LET vnum_tarjeta = "";
    LET vmaxsec = 0;

    LET vtamanio      = 0;
    LET vt_indicador  = "";
    LET vt_newfolio   ="";
    LET vt_folsucorig ="";

    let tranret = transaccion;

    begin

    on exception set sql_err
        if sql_err <> 0  then
            LET vg_estatus = vg_estatus::smallint + 5;
            let cod_ret = sql_err;
            return cod_ret,tranret;
        end if;
    end exception;

    --- SET DEBUG FILE TO "/home/informix/jydg/protsdo.out";
    --- TRACE ON;
    
    ---***********************************************************
    ---* Validacion de datos transmitidos a este Store Procedure *
    ---***********************************************************
    let saldo   = 0;
    let reten   = 0;
    let sql_err = 0;

    set isolation to dirty read;
    set lock mode to wait 3;

    if suc is null or usuariox is null or transaccion is null or
       cta is null or folsuc is null or docto is null or
       suc = "   " or usuariox = "   " or transaccion = "    " or
       cta = " " or folsuc = " " then
            let cod_ret = "110";
            let tranret = transaccion;
            return cod_ret,tranret;
    end if;

    select ejecutivo 
      into v_usuario 
      from bdinteg:si_ejecut
     where empresa = pempresa 
       and ejecutivo = usuariox;

    if v_usuario <> usuariox or v_usuario is null then
        let cod_ret = "106";
        let tranret = transaccion;
        return cod_ret,tranret;
    end if;

    if pmonto_concilia = 0 or pmonto_concilia is null then
        let cod_ret = "110";
        return cod_ret,tranret;
    end if;
    
    ---***************************************
    ---* Validacion del numero de Transaccion*
    ---***************************************
    select numero,naturaleza,valida_docto,tpcheque,tipo_tran
      into tranret,nat,v_valdoc,v_tpcheque,v_tiptran
      from bdinteg:si_transacc
     where empresa = pempresa 
       and numero = transaccion;
     
    if tranret is null then
        let tranret = "XXXX";
    end if;

    if transaccion != tranret then
        let cod_ret = "550";
        let tranret = transaccion;
        return cod_ret,tranret;
    end if;

    if nat != "C" then
        let cod_ret = "560";
        return cod_ret,tranret;
    end if;

    select {+INDEX(sc_fechas idx_fechas1)} fecha_hoy 
      into vfechacalendario 
      from sc_fechas 
     where empresa = pempresa;

    select fecha_proceso, status_cta
      into fechax, vstatus_cta
      from sc_maechq
     where empresa = pempresa
       and cuenta = cta;

    if ( fechax is null or vstatus_cta = '4' or vstatus_cta = '5' ) then
        let fechax = vfechacalendario;
    end if

    if ( fechax < vfechacalendario ) then
        let cod_ret = "549";
        return cod_ret,tranret;
    end if
    
    if ( vstatus_cta in('2','6','7','8') ) then
        let cod_ret = "200";
        return cod_ret,tranret;
    end if
    
    -- // Busca el folio en docret
    select monto, referencia 
      INTO monto_docret, v_referencia
      FROM sc_docret
     WHERE empresa = pempresa
       AND cuenta = cta
       AND folio_suc = folsuc
       AND cancelado = "P";

    LET vtamanio = length(folsuc);
    LET folsuc = trim(folsuc);
    LET vt_folsucorig = trim(folsuc);
    LET vt_indicador = substr(folsuc,(vtamanio -6),1);

    -- // No encontro el folio en docret
    IF monto_docret = 0 OR monto_docret IS NULL THEN
        -- // Cambio el indicador por 1
        IF vt_indicador = '2' AND folsuc[1,8] = "intercar" THEN 
            LET vt_newfolio = substr(folsuc,1,vtamanio -7);
            LET vt_newfolio = trim(vt_newfolio)||"1"||substr(folsuc,vtamanio -5,vtamanio);
            LET folsuc = trim(vt_newfolio);
            
            -- // Realiza la busqueda con el nuevo folio
            SELECT monto,referencia 
              into monto_docret, v_referencia
              FROM sc_docret
             WHERE empresa = pempresa
               AND cuenta = cta
               AND folio_suc = folsuc
               AND cancelado = "P";
            
            -- // Forzada no encontrada como 2 ni 1...
            IF monto_docret = 0 OR monto_docret IS NULL THEN 
                LET vg_estatus = "3";
                LET folsuc = vt_folsucorig;
            -- // Forzada encontrada como 1..
            ELSE 
                LET vg_estatus = "2";
            END IF
        -- // Normal no encontrada....
        ELSE 
            LET vg_estatus = "1";
        END IF  
    -- // Si encontro el folio en docret...
    ELSE 
        -- // Normal encontrada como Normal
        IF vt_indicador = '1' THEN   
            LET vg_estatus = "0";    
        -- // Mismo folio que transaccion en linea..
        ELIF vt_indicador = '2' THEN
            LET vg_estatus = "4";
        ELSE
            LET vg_estatus = "99";
        END IF
    END IF  

    LET saldo    = 0;
    LET v_status = " ";
    LET ctar     = " ";
    LET v_montolib = 0;

    IF monto_docret IS NULL THEN
        LET monto_docret = 0;
    END IF;

    foreach cargo_cursor for
        select cuenta,sucursal,plaza,producto,status_cta,sdo_actual,sdo_retenido,motivo
          into ctar,suc_cta,v_plaza,prod,v_status,saldo,reten,motiv
          from sc_maechq
         where empresa = pempresa 
           and cuenta = cta

        select divisa 
          into v_moneda
          from sc_producto
         where empresa = pempresa 
           and producto = prod;
           
        if v_moneda != divisa then
            let cod_ret = "951";
            let tranret = transaccion;
            return cod_ret,tranret;
        end if;

        -- ******************************************
        -- Inicio de validaciones MAECHQ y BLOQUEO
        -- ******************************************
        if ctar is null then
            let ctar = "X";
        end if;

        if ctar = cta then
            let cod_ret = "000";
        else
            let cod_ret = "100";
            return cod_ret,tranret;
        end if;

        if v_status in ("2","6","7") then
            let cod_ret = "200";
            return cod_ret,tranret;
        elif v_status = "3" then
            IF transaccion <> '0830' AND transaccion <> '0887' THEN
                SELECT "1" 
                  INTO vexiste
                  FROM sc_ctabloqueo 
                 WHERE cuenta = ctar;

                IF vexiste = "1" THEN      
                    SELECT opcion 
                      INTO vaceptab
                      FROM sc_ctabloqueo 
                     WHERE cuenta = ctar;

                    IF vaceptab = 4 THEN
                        LET cod_ret = "300";
                        RETURN cod_ret,tranret;
                    END IF;

                    IF vaceptab = 3 THEN
                        LET cod_ret = "300";
                        RETURN cod_ret,tranret;
                    END IF;
                ELSE
                    select cargo 
                      into cargox 
                      from sc_bloqueo
                     where codigo = motiv;

                    if cargox = "N" then
                        let cod_ret = "300";
                        return cod_ret,tranret;
                    end if;
                END IF;
            END IF;
        end if;

        select max(secuencia) 
          into vmaxsec
          from sc_tarjeta
         where empresa = pempresa 
           and cuenta = cta 
           and tipo_tarjeta = "T";
           
        select num_tarjeta 
          into vnum_tarjeta
          from sc_tarjeta
         where empresa = pempresa 
           and cuenta = cta 
           and secuencia = vmaxsec;

        -- // Libera proteccion de saldo
        begin
        
        if monto_docret > 0 then
            -- // Monto en linea menor que conciliacion
            IF monto_docret < pmonto_concilia then
                LET vg_estatus = vg_estatus::smallint + 10;
            -- // Monto linea igual que la conciliacion
            ELIF monto_docret = pmonto_concilia THEN 
                LET vg_estatus = vg_estatus::smallint + 0;
            -- // Monto linea mayor  que la conciliacion
            ELSE 
                LET vg_estatus = vg_estatus::smallint + 20;
            END IF
            
            LET v_montolib = pmonto_concilia;
            let horax = current hour to fraction(3);
        end if
        
        end;
        
        if cod_ret = "000" then
            -- // Actualizacion del Maestro (se cambiar para que se libere el monto retenido)
            UPDATE sc_maechq
               SET (sdo_retenido) = (sdo_retenido - monto_docret)
             WHERE empresa = pempresa 
               AND cuenta = cta;

            if v_tpcheque = "01" then
                -- // Libera documento, para efectuar el cargo
                update {+INDEX(sc_histch idx_histch1)} sc_histch
                   set estado = " ",
                       importe = 0
                 where empresa = pempresa 
                   and cuenta = cta 
                   and numero = docto;
            end if
            
            -- // Marca documento retenido
            update sc_docret
               set cancelado = "S",
                   monto = monto - v_montolib
             where empresa = pempresa
               and cuenta = cta
               and folio_suc = folsuc
               and cancelado = "P";
               
            LET v_referencia = vgrfc_comer || vgreferencia;
            
            -- // Registra movimiento de retiro
            call cargon_ref(pempresa, suc, usuariox, transaccion, transacc_suc, folsuc, cta, 
                            docto, pmonto_concilia, v_moneda, v_referencia, vnum_tarjeta, "")
            returning cod_ret, tranret;
        end if
            
        return cod_ret, tranret;
    
    end foreach;

    end

end procedure;

CREATE PROCEDURE "informix".sp_compcancelactasinactivas( pEmpresa char(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;
      
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vComienza        INTEGER;
    DEFINE vEnTransacc      SMALLINT;
    DEFINE vContador1       INTEGER;
    DEFINE vCuenta          CHAR(20);
    DEFINE vnum_tarjeta     CHAR(16);
    
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '000';
    LET vCodRet2     = '000';
    LET vCodRet3     = '';
    LET vComienza    = -1;
    LET vEnTransacc  = 0;
    LET vContador1   = 0;
    LET vCuenta      = ''; 
    LET vnum_tarjeta = '';
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_compcancelactasinactivas.err";
        TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vEnTransacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vCodRet2, vCodRet3, vContador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_compcancelactasinactivas.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH WITH HOLD
        SELECT cuenta
          INTO vcuenta
          FROM sc_ctasinactinforcanc
          
        IF vComienza = -1 THEN
            LET vComienza = 0;
        END IF;    
        
        BEGIN WORK;
        LET vEnTransacc = 1;
        
        UPDATE bdicheq:"informix".sc_maechq
           SET motivo = '13'
         WHERE empresa = pEmpresa
           AND cuenta = vCuenta;
           
        FOREACH
            SELECT num_tarjeta
              INTO vnum_tarjeta
              FROM bdicheq:"informix".sc_tarjeta
             WHERE empresa = pEmpresa
               AND cuenta = vCuenta
			   AND status_tar = 'A'
               AND secuencia > 0
               
            UPDATE bdicheq:"informix".sc_tarjeta
               SET status_tar = 'C'
             WHERE empresa = pEmpresa
               AND num_tarjeta = vnum_tarjeta;
               
            UPDATE intercard:"informix".tarjeta
               SET codstatustarjeta = 'CAN'
             WHERE numtarjeta = vnum_tarjeta;
        END FOREACH
        
        LET vContador1 = vContador1 + 1;
        
        COMMIT WORK;
        LET vEnTransacc = 0;
        
    END FOREACH;
    
    END;
    
    RETURN vCodRet1, vCodRet2, vCodRet3, vContador1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consprodcta(pEmpresa char(3), pNumTarj char(16))
    -- DATOS A REGRESAR --
    RETURNING	char(5),    -- Codigo de retorno
				char(11),   -- cuenta
				char(4);    -- Producto de la cuenta

    --Realizó: Walber Castro
	--Fecha: 09/05/2012
	--Solicitó: Mauricio León
	--Descripción: Se consulta la cuenta y el producto de una tarjeta en específico.
	
	-- VARIABLES --
	DEFINE sql_err          INTEGER;		
    DEFINE vCodRet  char(5);
	DEFINE vProductoCuenta char(4);
	DEFINE vcuenta char(20);
		
	-- INICIALIZACION DE VARIABLES --
    LET vCodRet  = "00000";
	LET vProductoCuenta = "";
	LET sql_err	        = 0;
	LET vcuenta = '';
		
	BEGIN

    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET vCodRet = sql_err;            
            RETURN vCodRet, vcuenta, vProductoCuenta;
        END IF;
    END EXCEPTION;
	
	SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	IF EXISTS(SELECT cuenta FROM bdicheq:"informix".sc_tarjeta WHERE empresa = pEmpresa AND num_tarjeta = pNumTarj AND tipo_tarjeta = 'T' AND status_tar = 'A') THEN
		SELECT cuenta 
		INTO vcuenta
		FROM bdicheq:"informix".sc_tarjeta 
		WHERE empresa = pEmpresa 
		AND num_tarjeta = pNumTarj
		AND tipo_tarjeta = 'T' 
		AND status_tar = 'A';
			
		IF NOT vcuenta IS NULL THEN			
			SELECT sc_mcq.producto
			INTO vProductoCuenta
			FROM bdicheq:"informix".sc_maechq AS sc_mcq
			WHERE sc_mcq.empresa = pEmpresa 
			AND sc_mcq.cuenta =  vcuenta;
		END IF;	
	ELSE
		LET vcodret = '00001';
	END IF;	
		
	RETURN vCodRet, vcuenta, vProductoCuenta;
	
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_mspei_detallemovtos(	pIndicador SMALLINT, pFechaHist CHAR(10),pRastreo CHAR(40),pTipTransac CHAR(4),
													pCtaClave CHAR(18),pNumTarj CHAR(16), pMonto MONEY(14,2), pNumPag SMALLINT)
	
	RETURNING 	
	CHAR(6)        AS COD_RET,
	CHAR(80)       AS DESCRIPCION,	
	CHAR(10)       AS FECHA_ALT,
	CHAR(40)       AS REFERENCIA,
	CHAR(50)       AS DESCRIP,
	CHAR(18)       AS CTA_CVE,
	CHAR(16)       AS NUM_TARJ,
	MONEY(14,2)    AS MONTO_TOT;
		
	---DECLARACION DE VARIABLES.
	DEFINE iSqlErr              INTEGER;
	DEFINE iIsamErr             INTEGER;
	DEFINE cErrorInfo           CHAR(80);
	DEFINE cCodRet              CHAR(6);
	DEFINE cMensajeRet          CHAR(80);	
	DEFINE dtFechaHoy           DATE;
	DEFINE cFechaAlt           CHAR(10);
	DEFINE cReferencia          CHAR(40);
	DEFINE cDescrip		        CHAR(50);
	DEFINE cCtaCve		        CHAR(18);
	DEFINE cNumTarj		        CHAR(16);
	DEFINE mMontoTot	        MONEY(14,2);
	DEFINE sSalto		        SMALLINT;
	DEFINE sLimit		        SMALLINT;	

	---INICIALIZACION DE VARIABLES.
	LET iSqlErr                 = 0;
	LET iIsamErr                = 0;
	LET cErrorInfo              = '';
	LET cCodRet                 = '000000';
	LET cMensajeRet             = 'PROCESO EXISTOSO';	
	LET dtFechaHoy              = '';
	LET cFechaAlt               = '';
	LET cReferencia             = '';
	LET cDescrip	            = '';
	LET cCtaCve		            = '';
	LET cNumTarj	            = '';
	LET mMontoTot	            = 0.00;
	LET sSalto		            = 0;
	LET sLimit		            = 0;	
    
	BEGIN
		
		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
			IF iSqlErr != 0 THEN
				LET cCodRet = iSqlErr;
				LET cMensajeRet = cErrorInfo;				
				RETURN TRIM(cCodRet), TRIM(cMensajeRet),NVL(cFechaAlt,''),TRIM(NVL(cReferencia,'')),TRIM(NVL(cDescrip,'')),TRIM(NVL(cCtaCve,'')),TRIM(NVL(cNumTarj,'')),NVL(mMontoTot,0.00);
			END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		--SET DEBUG FILE TO '/respaldosbd/Guadalupe/sp_mspei_detallemovtos.out';
		--TRACE ON;

		--SE VALIDAN PARAMETROS.		
		IF NVL(pIndicador,0) = 0 OR pIndicador NOT IN(1,2)THEN
			LET cCodRet = '000001';
			LET cMensajeRet = 'PARAMETRO INVALIDO';
			RETURN TRIM(cCodRet), TRIM(cMensajeRet),TRIM(cFechaAlt),TRIM(cReferencia),TRIM(cDescrip),TRIM(cCtaCve),TRIM(cNumTarj),mMontoTot;
		END IF;		
		 
		IF NVL(pNumPag,0) = 0 THEN 
			--SE INICIALIZAN VARIABLES PARA COSULTAR SIN PAGINACION.
			LET sLimit = 0;
			LET sSalto = 0;		
		ELSE 
			LET sLimit = 50;
			--OBTENER EL SALTO DE REGISTROS.
			LET sSalto = (pNumPag - 1) * sLimit;
		END IF;		
		
		IF pIndicador = 1 THEN 
			-- // OBTINENE LA FECHA DE HOY
			SELECT fecha_hoy
			INTO dtFechaHoy
			FROM bdicheq:"informix".sc_fechas
			WHERE empresa = '001';
			
			--CICLO PARA OBTENER LOS DETALLES DE MOVIMIENTOS DEL DIA.
			FOREACH					 							
				SELECT SKIP sSalto LIMIT sLimit LPAD(DAY(mvd.fech_alt),2,'0') || '/' || LPAD(MONTH(mvd.fech_alt),2,'0') || '/' || YEAR(mvd.fech_alt),
					 mvd.referencia,tran.descripcion, mae.cuenta_clabe,mvd.num_tarjeta,mvd.monto_tot
				INTO cFechaAlt,cReferencia,cDescrip,cCtaCve,cNumTarj,mMontoTot
				FROM bdicheq:"informix".sc_movdia mvd, bdicheq:"informix".sc_maechq mae,bdinteg:"informix".si_transacc tran
				WHERE mvd.empresa = mae.empresa 
					AND mvd.cuenta = mae.cuenta 					
					AND mae.empresa = mvd.empresa 					
					AND mae.cuenta = mvd.cuenta 
					AND mvd.transacc = tran.numero									
					AND tran.empresa = mvd.empresa 
					AND tran.numero = mvd.transacc					
					AND mvd.fech_alt = dtFechaHoy
					AND mvd.cancelad <> 'S' 							
					AND mvd.transacc IN ('0274','0273','0276','0277')										
					AND UPPER(mvd.referencia) LIKE  DECODE(TRIM(UPPER(pRastreo))||'%','',mvd.referencia,TRIM(UPPER(pRastreo))||'%')						
					AND NVL(mvd.transacc ,'')		= DECODE(TRIM(NVL(pTipTransac,'')),'',NVL(mvd.transacc,''),TRIM(NVL(pTipTransac,'')))
					AND NVL(mvd.num_tarjeta ,'')	= DECODE(TRIM(NVL(pNumTarj,'')),'',NVL(mvd.num_tarjeta,''),TRIM(NVL(pNumTarj,'')))
					AND NVL(mvd.monto_tot ,0)		= DECODE(NVL(pMonto,0) ,0,NVL(mvd.monto_tot ,0),NVL(pMonto,0))
					AND NVL(mae.cuenta_clabe,'')	= DECODE(TRIM(NVL(pCtaClave,'')),'',NVL(mae.cuenta_clabe,''),TRIM(NVL(pCtaClave,'')))					 										
					
					RETURN TRIM(cCodRet), TRIM(cMensajeRet),TRIM(NVL(cFechaAlt,'')),TRIM(NVL(cReferencia,'')),TRIM(NVL(cDescrip,'')),TRIM(NVL(cCtaCve,'')),TRIM(NVL(cNumTarj,'')),NVL(mMontoTot,0.00) WITH RESUME;
					
			END FOREACH
			
			IF dbinfo('sqlca.sqlerrd2') = 0 THEN
				LET cCodRet ='000002';
				LET cMensajeRet = 'NO EXISTEN DATOS PARA LA CONSULTA POR MOVIMIENTOS DEL DIA';				
				RETURN TRIM(cCodRet), TRIM(cMensajeRet),TRIM(NVL(cFechaAlt,'')),TRIM(NVL(cReferencia,'')),TRIM(NVL(cDescrip,'')),TRIM(NVL(cCtaCve,'')),TRIM(NVL(cNumTarj,'')),NVL(mMontoTot,0.00);
			END IF;
									
		ELSE --INDICADOR = 2.
			IF NVL(pFechaHist,'') = '' THEN
				LET cCodRet = '000003';
				LET cMensajeRet = 'PARAMETRO FECHA HISTORICA INVALIDA';
				RETURN TRIM(cCodRet), TRIM(cMensajeRet),TRIM(cFechaAlt),TRIM(cReferencia),TRIM(cDescrip),TRIM(cCtaCve),TRIM(cNumTarj),mMontoTot;
			END IF;
			
			--CICLO PARA OBTENER LOS DETALLES DE MOVIMIENTOS HISTORICOS.
			FOREACH					
				SELECT SKIP sSalto LIMIT sLimit LPAD(DAY(mvhi.fech_alt),2,'0') || '/' || LPAD(MONTH(mvhi.fech_alt),2,'0') || '/' || YEAR(mvhi.fech_alt),
				     mvhi.referencia,tran.descripcion, mae.cuenta_clabe,mvhi.num_tarjeta,mvhi.monto_tot
				INTO cFechaAlt,cReferencia,cDescrip,cCtaCve,cNumTarj,mMontoTot
				FROM bdicheq:"informix".sc_movhis mvhi, bdicheq:"informix".sc_maechq mae,bdinteg:"informix".si_transacc tran
				WHERE mvhi.empresa=mae.empresa 
					AND mvhi.cuenta=mae.cuenta 					
					AND mae.empresa = mvhi.empresa 					
					AND mae.cuenta = mvhi.cuenta  										
					AND mvhi.transacc=tran.numero									
					AND tran.empresa = mvhi.empresa 
					AND tran.numero = mvhi.transacc					
					AND mvhi.fech_alt = pFechaHist
					AND mvhi.cancelad <> 'S' 							
					AND mvhi.transacc IN ('0274','0273','0276','0277')
					AND UPPER(mvhi.referencia) LIKE  DECODE(TRIM(UPPER(pRastreo))||'%','',mvhi.referencia,TRIM(UPPER(pRastreo))||'%')
					AND NVL(mvhi.transacc 	,'')	= DECODE(TRIM(NVL(pTipTransac,'')),'',NVL(mvhi.transacc,''),TRIM(NVL(pTipTransac,'')))
					AND NVL(mvhi.num_tarjeta ,'')	= DECODE(TRIM(NVL(pNumTarj,'')),'',NVL(mvhi.num_tarjeta,''),TRIM(NVL(pNumTarj,'')))
					AND NVL(mvhi.monto_tot 	,0)	= DECODE(NVL(pMonto,0) ,0,NVL(mvhi.monto_tot,0) ,NVL(pMonto,0))
					AND NVL(mae.cuenta_clabe	,'') = DECODE(TRIM(NVL(pCtaClave,'')),'',NVL(mae.cuenta_clabe,''),TRIM(NVL(pCtaClave,'')))					
				
				UNION ALL 
				
				SELECT LPAD(DAY(mvhisold.fech_alt),2,'0') || '/' || LPAD(MONTH(mvhisold.fech_alt),2,'0') || '/' || YEAR(mvhisold.fech_alt),
				     mvhisold.referencia,tran.descripcion, mae.cuenta_clabe,mvhisold.num_tarjeta,mvhisold.monto_tot				
				FROM bdicheq:"informix".sc_movhis_old mvhisold, bdicheq:"informix".sc_maechq mae, bdinteg:"informix".si_transacc tran
				WHERE mvhisold.empresa=mae.empresa 
					AND mvhisold.cuenta=mae.cuenta 					
					AND mae.empresa = mvhisold.empresa 					
					AND mae.cuenta = mvhisold.cuenta  															
					AND mvhisold.transacc=tran.numero									
					AND tran.empresa = mvhisold.empresa 
					AND tran.numero = mvhisold.transacc					
					AND mvhisold.fech_alt = pFechaHist
					AND mvhisold.cancelad <> 'S' 							
					AND mvhisold.transacc IN ('0274','0273','0276','0277')
					AND UPPER(mvhisold.referencia) LIKE  DECODE(TRIM(UPPER(pRastreo))||'%','',mvhisold.referencia,TRIM(UPPER(pRastreo))||'%')
					AND NVL(mvhisold.transacc,'') 		= DECODE(TRIM(NVL(pTipTransac,'')),'',NVL(mvhisold.transacc,''),TRIM(NVL(pTipTransac,'')))
					AND NVL(mvhisold.num_tarjeta ,'')	= DECODE(TRIM(NVL(pNumTarj,'')),'',NVL(mvhisold.num_tarjeta,''),TRIM(NVL(pNumTarj,'')))
					AND NVL(mvhisold.monto_tot,0) 		= DECODE(NVL(pMonto,0) ,0,NVL(mvhisold.monto_tot ,0),NVL(pMonto,0))					
					AND NVL(mae.cuenta_clabe,'')		= DECODE(TRIM(NVL(pCtaClave,'')),'',NVL(mae.cuenta_clabe,''),TRIM(NVL(pCtaClave,'')))
																	
				RETURN TRIM(cCodRet), TRIM(cMensajeRet),TRIM(NVL(cFechaAlt,'')),TRIM(NVL(cReferencia,'')),TRIM(NVL(cDescrip,'')),TRIM(NVL(cCtaCve,'')),TRIM(NVL(cNumTarj,'')),NVL(mMontoTot,0.00) WITH RESUME;
					
			END FOREACH
						
			IF dbinfo('sqlca.sqlerrd2') = 0 THEN
				LET cCodRet ='000002';
				LET cMensajeRet = 'NO EXISTEN DATOS PARA LA CONSULTA DE MOVIMIENTOS HISTORICOS';				
				RETURN TRIM(cCodRet), TRIM(cMensajeRet),TRIM(NVL(cFechaAlt,'')),TRIM(NVL(cReferencia,'')),TRIM(NVL(cDescrip,'')),TRIM(NVL(cCtaCve,'')),TRIM(NVL(cNumTarj,'')),NVL(mMontoTot,0.00);
			END IF;	
			
		END IF;			    				   			
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que obtiene los conteos asi como la sumatoria de los movimientos diarios e historicos para el aplicativo de monitor', 
'			  de SPEI por medio del metodo de consulta de paginación de 50 filas',
'AUTOR: Guadalupe Payan',
'FECHA DE CREACION: 18 de Abril de 2012',
'VERSION: 20120418.1300',
'BD: bdicheq',
'Modifico: Jesus Manuel Aguilar Heredia',
'Se modifica para quitar el ligue con la tabla sc_tarjeta y que asi conincidan los totales de las consultas, y NVL en las consultas para posibles registros con datos en null',
'VERSION: 20120518.1300',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_mspei_consultatotales ()
RETURNING
	CHAR(6)				AS COD_RET,
	CHAR(60)			AS MENS_RET,
	INT8				AS NUM_OPER_LIQ,
	DECIMAL(14,2)		AS SUM_MONTO_LIQ,
	INT8				AS NUM_OPER_DEV,
	DECIMAL(14,2)		AS SUM_MONTO_DEV,
	INT8				AS NUM_OPER_LIQ2,
	DECIMAL(14,2)		AS SUM_MONTO_LIQ2,
	INT8				AS NUM_OPER_CANCELADA,
	DECIMAL(14,2)		AS SUM_MONTO_CANCELADA;
	
--DECLARACIONES
	DEFINE cCodRet		CHAR(6);
	DEFINE cMensajeRet	CHAR(80);
	DEFINE iNumLiq		INT8;
	DEFINE iNumDev		INT8;
	DEFINE dSumLiq		DECIMAL(14,2);
	DEFINE dSumDev		DECIMAL(14,2);
	DEFINE iNumLiq2		INT8;
	DEFINE iNumCanc		INT8;
	DEFINE dSumLiq2		DECIMAL(14,2);
	DEFINE dSumCanc		DECIMAL(14,2);
	DEFINE iSqlErr		INTEGER;
	DEFINE iIsamErr		INTEGER;
	DEFINE cErrorInfo	CHAR(80);
	DEFINE dtFechaHoy	DATE;

--INICIALIZACIONES

	LET cCodRet			= "000000";
	LET cMensajeRet		= "PROCESO EXITOSO";
	LET iNumLiq			= 0;
	LET iNumDev			= 0;
	LET dSumLiq			= 0.00;
	LET dSumDev			= 0.00;
	LET iNumLiq2		= 0;
	LET iNumCanc		= 0;
	LET dSumLiq2		= 0.00;
	LET dSumCanc		= 0.00;
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= "";
	LET dtFechaHoy		= DATE(1);

BEGIN

	ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN TRIM(cCodRet), TRIM(cMensajeRet), NVL(iNumLiq,0), NVL(dSumLiq,0.00), NVL(iNumDev,0), NVL(dSumDev,0.00), NVL(iNumLiq2,0), NVL(dSumLiq2,0.00), NVL(iNumCanc,0), NVL(dSumCanc,0.00);
		END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO "/home/sysifx/armandomorales/sp_mspei_consultatotales.out";
	--TRACE ON;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	--SE CONSULTA LA FECHA DEL DIA.
	SELECT fecha_hoy
	INTO dtFechaHoy
	FROM bdicheq:"informix".sc_fechas
	WHERE empresa = "001";
		
	--HACE UN CONTEO Y SUMATORIA DEL CAMPO TRANSACCION DE LA SC_MOVDIA
	SELECT COUNT(Liquidadas), SUM(Liquidadas), COUNT(Devoluciones), SUM(Devoluciones), COUNT(Liquidadas2),SUM(Liquidadas2),COUNT(Canceladas), SUM(Canceladas)
	INTO iNumLiq, dSumLiq, iNumDev, dSumDev, iNumLiq2, dSumLiq2, iNumCanc, dSumCanc
	FROM TABLE (MULTISET ( 
		SELECT CASE WHEN mvd.transacc="0273" THEN mvd.monto_tot  END AS Liquidadas,
			  CASE WHEN mvd.transacc="0274" THEN mvd.monto_tot END AS Liquidadas2,
			  CASE WHEN mvd.transacc="0276" THEN mvd.monto_tot END AS Canceladas,
			  CASE WHEN mvd.transacc="0277" THEN mvd.monto_tot END AS Devoluciones								  
		FROM bdicheq:"informix".sc_movdia mvd, bdicheq:"informix".sc_maechq mae,bdinteg:"informix".si_transacc tran	
		WHERE mvd.transacc IN ("0274","0273","0276","0277")
		AND mvd.fech_val = dtFechaHoy
		AND mvd.cancelad <> 'S'	
		AND mvd.cuenta	= mae.cuenta
		AND mvd.transacc = tran.numero
		));
		
		--SI NO ENCUENTRA NINGUN REGISTRO MANDA MENSAJE DE ERROR.
	IF iNumLiq = 0 AND iNumDev = 0 AND iNumLiq2 = 0 AND iNumCanc = 0 THEN
		LET cCodRet = "000001";
		LET cMensajeRet = "NO HAY REGISTROS DE MOVIMIENTOS SPEI";
	END IF;
		
	RETURN TRIM(cCodRet), TRIM(cMensajeRet), NVL(iNumLiq,0), NVL(dSumLiq,0.00), NVL(iNumDev,0), NVL(dSumDev,0.00), NVL(iNumLiq2,0), NVL(dSumLiq2,0.00), NVL(iNumCanc,0), NVL(dSumCanc,0.00);
	
END
END PROCEDURE
DOCUMENT
'AUTOR : Armando Morales Barraza',
'DESCRIPCION: Se crea procedimeinto para que obtenga la información de las transacciones de SPEI agrupada por el tipo de transacción',
'			 (1.- Ordenes Recibidas:estado, número de operaciones y sumatoria de monto', 
'			 2.- Ordenes Enviadas:estado, número de operaciones y sumatoria de monto) y se retorna esta informacion',
'FECHA      : 18/Abril/2012',
'VERSION    : 20120418';

CREATE PROCEDURE "informix".sp_valida_monto_tras(pcEmpresa CHAR(3), pcCuenta CHAR(20), pcTransuc CHAR(4), pmTotTrans MONEY)
	RETURNING CHAR(6) AS CodRetorno, CHAR(4) AS CodMensaje;

--Definicion de Variables
DEFINE iSqlErr						INTEGER;
DEFINE cCodRet						CHAR(6);
DEFINE cCodMsj						CHAR(4);
DEFINE mMontoTot					MONEY(14,2);
--DEFINE iMontoMax					INTEGER;	--DSB 01/06/2012
DEFINE mMontoMax					MONEY(14,2);
DEFINE dFechaHoy					DATE;

--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '000000';
LET cCodMsj = '0000';
LET mMontoTot = 0;
LET mMontoMax = 0;
LET dFechaHoy = '01-01-1900';

--SET DEBUG FILE TO '/respaldosbd/joseluis/sp_valida_monto_tras.out';
--TRACE ON;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cCodMsj;
		END IF;
	END EXCEPTION;
	
	IF pcEmpresa = "" OR pcCuenta = "" OR pcTransuc = "" OR pmTotTrans = 0 THEN
		LET cCodRet = '110';
	ELSE
		SET LOCK MODE TO WAIT 3;
		--//Obtiene fecha del sistema de cheques
		SELECT fecha_hoy
		INTO dFechaHoy
		FROM bdicheq:"informix".sc_fechas
		WHERE empresa = pcEmpresa;
		
		SET LOCK MODE TO WAIT 3;
		--//Obtiene el monto total de las transacciones echas en el dia
		SELECT NVL(SUM(monto_tot),0) INTO mMontoTot
		FROM bdicheq:"informix".sc_movdia
		WHERE cuenta = pcCuenta AND fech_alt = dFechaHoy AND transacc_suc = pcTransuc AND transacc='0289' AND cancelad != 'S';
		
		SET LOCK MODE TO WAIT 3;
		--//Obtiene el monto maximo
		IF EXISTS(SELECT valor FROM bdicheq:"informix".sc_param WHERE codparam = 'montomaxtraspefectas') THEN
			--SELECT NVL(CAST(valor AS INTEGER),0) INTO iMontoMax		--DSB 01/06/2012
			SELECT NVL(CAST(valor AS MONEY(14,2)),0) INTO mMontoMax
			FROM bdicheq:"informix".sc_param WHERE codparam = 'montomaxtraspefectas';
		END IF;
		
		--//Comparacion del monto total con el monto maximo permitido
		--IF (mMontoTot > iMontoMax) OR (pmTotTrans > iMontoMax) THEN		--DSB 01/06/2012
		IF (pmTotTrans > mMontoMax) OR ((mMontoTot + pmTotTrans) > mMontoMax) THEN
			LET cCodMsj = '267';
		END IF;		
	END IF;
	RETURN cCodRet,cCodMsj;
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Saca y compara el monto total de las transacciones echas en el dia, con el monto maximo permitido',
'AUTOR : Jose Luis Polanco B.',
'FECHA : 04/04/2012',
'VERSION: 1.0',
'BD: bdicheq',
'SISTEMA : Caja sucursal',
'FECHA : DSB 01/06/2012',
'DESCRIPCION: Se incluye la comparacion de la suma de operaciones y el monto de la transaccion en proceso, para que no sea mayor de lo permitido',
'Se cambia el tipo de dato del monto maximo permitido para hacer de buena forma la comparacion',
'AUTOR : Jose Luis Polanco B.';

CREATE PROCEDURE "informix".sp_actsdoctasconc( pEmpresa CHAR(3) ) 
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;
    
    DEFINE Sql_Err      INTEGER;
    DEFINE Isam_Err     INTEGER;
    DEFINE Desc_Err     CHAR(50);
    DEFINE vCodRet1     CHAR(5);
    DEFINE vCodRet2     CHAR(5);
    DEFINE vCodRet3     CHAR(50);
    DEFINE vcontador    INTEGER;
    DEFINE vcuenta      CHAR(20);
    DEFINE vfechaconc   DATE;
    DEFINE vsdo_actual  DECIMAL(16,2);
    
    LET Sql_Err	    = 0;
    LET Isam_Err    = 0;
    LET Desc_Err    = '';
    LET vCodRet1    = '000';
    LET vCodRet2    = '000';
    LET vCodRet3    = 'PROCESO FINALIZADO CORRECTAMENTE';  
    LET vcontador   = 0;
    LET vcuenta     = '';
    LET vfechaconc  = '';
    LET vsdo_actual = 0.00;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actsdoctasconc.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            RETURN vCodRet1, vCodRet2, vCodRet3, vcontador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actsdoctasconc.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    FOREACH WITH HOLD
        SELECT a.cuenta, a.fecha_concentra, b.sdo_actual
          INTO vcuenta, vfechaconc, vsdo_actual
          FROM sc_cuentas_concentradas a,
               sc_maechq b
         WHERE a.cuenta = b.cuenta
           AND a.fecha_concentra >= '08/03/2012'
           AND b.status_cta = '6'
           
        BEGIN WORK;
        
        UPDATE sc_maechq
           SET sdo_dia_ant = vsdo_actual
         WHERE empresa = pempresa
           AND cuenta = vcuenta;
       
        IF vfechaconc = '08/03/2012' THEN
            UPDATE sc_sdodiarioc
               SET capvig3 = vsdo_actual,
                   capvig4 = vsdo_actual,
                   capvig5 = vsdo_actual,
                   capvig6 = vsdo_actual
             WHERE cuenta = vcuenta
               AND aniomes = '201208';
        END IF;
        
        IF vfechaconc = '08/06/2012' THEN
            UPDATE sc_sdodiarioc
               SET capvig6 = vsdo_actual
             WHERE cuenta = vcuenta
               AND aniomes = '201208';
        END IF;
           
        LET vcontador = vcontador + 1;
        
        COMMIT WORK;
        
        LET vcuenta = '';
        LET vfechaconc = '';
        LET vsdo_actual = 0.00;
    END FOREACH;
    
    END;
    
    RETURN vCodRet1, vCodRet2, vCodRet3, vcontador;
    
END PROCEDURE;

create procedure "informix".sc_consdatosctacentral( pempresa char(3), pnumcta char(20) )
returning char(5), char(4), char(4), char(20), char(1), char(2), date, char(8), char(2), char(1), 
          char(2), char(2), char(2), char(2), char(2), char(2), char(2), char(18), integer, integer;

    -- // Definicion de Variables
    define chrcodret			char(5);
    define chrcodret2			char(5);
    define chrcodret3			char(50);
    define intcodret			integer;
    define intisamerr           integer;
    define chrdescerr		    char(50);
    
    define chrsucursal		    char(4);
    define chrproducto		    char(4);
    define chrnumcte			char(20);
    define chrenviodirecc		char(1);
    define chrnumcot			char(2);
    define dtefecultmov		    date;
    define chrejecutivo		    char(8);
    define chrdireccenvio		char(2);
    define chrregfirmas		    char(1);
    define chrprocedaperacta	char(2);
    define chrprocedmantcta		char(2);
    define chrmontomensual		char(2);
    define chrdepositoscant		char(2);
    define chrdepositosmonto	char(2);
    define chrretiroscant		char(2);
    define chrretirosmonto		char(2);
    define chrcuentaclabe		char(18);
    define intempresa			integer;
    define intnomina			integer;
    
    -- // Inicializa variables
    let chrcodret			= "000";
    let chrcodret2			= "";
    let chrcodret3			= "";
    let intcodret			= 0;
    let intisamerr			= 0;
    let chrdescerr			= 0;
    
    let chrsucursal			= "";
    let chrproducto			= "";
    let chrnumcte			= "";
    let chrenviodirecc		= "";
    let chrnumcot			= "";
    let dtefecultmov        = "";
    let chrejecutivo		= "";
    let chrdireccenvio		= "";
    let chrregfirmas		= "";
    let chrprocedaperacta	= "";
    let chrprocedmantcta	= "";
    let chrmontomensual		= "";
    let chrdepositoscant	= "";
    let chrdepositosmonto	= "";
    let chrretiroscant		= "";
    let chrretirosmonto		= "";
    let chrcuentaclabe		= "";
    let intempresa			= 0;
    let intnomina			= 0;

    --- debug flag
    --- set debug file to "/tmp/sc_consdatosctacentral.out";
    --- trace on;

    begin

    on exception set intcodret, intisamerr, chrdescerr
        set debug file to "/tmp/sc_consdatosctacentral.err";
        trace on;
        if intcodret <> 0 then
            let chrcodret  = intcodret;
            let chrcodret2 = intisamerr;
            let chrcodret3 = chrdescerr;
            return chrcodret, chrsucursal, chrproducto, chrnumcte, chrenviodirecc, chrnumcot, dtefecultmov, 
                   chrejecutivo, chrdireccenvio, chrregfirmas, chrprocedaperacta, chrprocedmantcta, chrmontomensual, 
                   chrdepositoscant, chrdepositosmonto, chrretiroscant, chrretirosmonto, chrcuentaclabe, intempresa, intnomina;
        end if;
    end exception;
    
    if ( pempresa is null or pempresa = '' ) or
       ( pnumcta is null or pnumcta = '' ) then
       let chrcodret  = '110';
       return chrcodret, chrsucursal, chrproducto, chrnumcte, chrenviodirecc, chrnumcot, dtefecultmov, 
                   chrejecutivo, chrdireccenvio, chrregfirmas, chrprocedaperacta, chrprocedmantcta, chrmontomensual, 
                   chrdepositoscant, chrdepositosmonto, chrretiroscant, chrretirosmonto, chrcuentaclabe, intempresa, intnomina;
    end if;

    set isolation to dirty read;
    set lock mode to wait 3;

    select nvl(chq.sucursal, "0000"), 
           nvl(chq.producto, "0000"), 
           nvl(chq.num_cte, " "), 
           nvl(noc.envio_direcc, " "),
           nvl(noc.num_cot, " "),
           nvl(chq.fec_ult_mov, "1900-01-01"),
           nvl(noc.ejecutivo, " "),
           nvl(chq.direcc_envio, 0),
           nvl(noc.reg_firmas, " "),
           nvl(chq.proced_aperturacta, " "),
           nvl(chq.proced_mantenercta, " "),
           nvl(chq.monto_mensual, " "),
           nvl(chq.depositos_cantidad, " "),
           nvl(chq.depositos_monto, " "),
           nvl(chq.retiros_cantidad, " "),
           nvl(chq.retiros_monto, " "),
           nvl(chq.cuenta_clabe, " ")
      into chrsucursal, chrproducto, chrnumcte, chrenviodirecc, chrnumcot, dtefecultmov,
           chrejecutivo, chrdireccenvio, chrregfirmas, chrprocedaperacta, chrprocedmantcta, chrmontomensual,
           chrdepositoscant, chrdepositosmonto, chrretiroscant, chrretirosmonto, chrcuentaclabe
      from bdicheq:sc_maechq chq, 
           bdicheq:sc_maenoc noc
     where chq.cuenta = noc.cuenta 
       and chq.empresa = noc.empresa 
       and chq.empresa = pempresa 
       and chq.cuenta = pnumcta;

    -- // Extrae los datos de Empresa y No. de Nomina para Consulta
    if chrnumcte != "" or chrnumcte != " " or chrnumcte is not null then
        select nvl(numeric1, 0),
               nvl(numeric2, 0)
          into intempresa, intnomina
          from bdinteg:si_ctepf 
         where empresa = pempresa 
           and numcte = chrnumcte; 
    else
        let intempresa = 0;
        let intnomina = 0;
    end if        

    return chrcodret, chrsucursal, chrproducto, chrnumcte, chrenviodirecc, chrnumcot, dtefecultmov, 
           chrejecutivo, chrdireccenvio, chrregfirmas, chrprocedaperacta, chrprocedmantcta, chrmontomensual, 
           chrdepositoscant, chrdepositosmonto, chrretiroscant, chrretirosmonto, chrcuentaclabe, intempresa, intnomina;

    end;

end procedure;

CREATE PROCEDURE "informix".consctesfirxnumcta(pEmpresa CHAR(3), pNumeroCuenta CHAR(20), pNumeroCliente CHAR(20))
	-- DATOS A REGRESAR --
	RETURNING
	CHAR(5),     -- Codigo de retorno
	CHAR(20),    -- # Cliente
	CHAR(26),    -- Apellido paterno
	CHAR(26),    -- Apellido materno
	CHAR(26),    -- Nombre 1
	CHAR(26),    -- Nombre 2
	CHAR(13),    -- RFC
	CHAR(16),    -- # Tarjeta
	DATE,    	 --	Expiracion
	CHAR(4),     -- Producto tarjeta
	MONEY(14,2), -- Limite de retiro maximo por mes
	CHAR(1),     -- Status tarjeta
	CHAR(8),     -- Tipo de cliente
	CHAR(10),    -- Fecha de Nacimiento
	CHAR(4),     -- Producto de la cuenta
	CHAR(2);     -- Parentesco

	-- VARIABLES --
	DEFINE vCodRet  	CHAR(5);
	DEFINE iSqlErr 		INTEGER;
	DEFINE vTipCte  	CHAR(1);
	DEFINE vNumCte		CHAR(20);
	DEFINE vApePat  	CHAR(26);
	DEFINE vApeMat  	CHAR(26);
	DEFINE vNombre1 	CHAR(26);
	DEFINE vNombre2 	CHAR(26);
	DEFINE vRFC     	CHAR(13);
	DEFINE vNumTarj 	CHAR(16);
	DEFINE Vexpiracion  DATE;
	DEFINE Vprodtarjeta CHAR(4);
	DEFINE vLimTar  	MONEY(14,2);
	DEFINE vTipoCte 	CHAR(8);
	DEFINE vStatTjt 	CHAR(1);
	DEFINE vFechaNac 	CHAR(10);
	DEFINE vProductoCuenta CHAR(4);
	DEFINE vCantReg 	SMALLINT;
	DEFINE vParentesco 	CHAR(2);

	-- INICIALIZACION DE VARIABLES --
	LET vCodRet  		= "000";
	LET iSqlErr   		= 0;
	LET vCantReg 		= 0;
	LET vTipCte 		= "";
	LET vNumCte 		= "";
	LET vApePat 		= "";
	LET vApeMat 		= "";
	LET vNombre1 		= "";
	LET vNombre2 		= "";
	LET vRFC 			= "";
	LET vNumTarj 		= "";
	LET Vexpiracion 	= "";
	LET Vprodtarjeta 	= "";
	LET vLimTar 		= "";
	LET vTipoCte 		= "";
	LET vStatTjt 		= "";
	LET vFechaNac 		= "";
	LET vProductoCuenta = "";
	LET vParentesco 	= "";

	--SET DEBUG FILE TO "/respaldosbd/Daniela/consctesfirxnumcta.out";
	--TRACE ON;
	
	BEGIN

		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET vCodRet = iSqlErr;
				RETURN vCodRet, vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vNumTarj, Vexpiracion, 
						Vprodtarjeta, vLimTar, vStatTjt, vTipoCte, vFechaNac, vProductoCuenta, vParentesco;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;


		-- CICLO PARA OBTENER A LOS FIRMANTES Y LAS TARJETAS DE DEBITO EN CASO DE QUE TENGAN --

		FOREACH
		
			SELECT DISTINCT
				si_cte.numcte, si_cte.apell_paterno, si_cte.apell_materno, si_cte.nombre1, si_cte.nombre2, si_cte.rfc, 
				'Firmante' AS tipo_cliente, si_pf.fecha_nac, sc_mcq.producto, sc_fir.parentesco
			INTO
				vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vTipoCte, vFechaNac, vProductoCuenta, vParentesco
			FROM
				bdicheq:"informix".sc_maechq sc_mcq,
				bdicheq:"informix".sc_firmantes AS sc_fir,
				bdinteg:"informix".si_cliente AS si_cte,
				bdinteg:"informix".si_ctepf AS si_pf
			WHERE sc_fir.empresa =  pEmpresa 
			  AND sc_fir.cuenta =  pNumeroCuenta 
			  AND sc_fir.numcte != pNumeroCliente 
			  AND sc_fir.numcte = si_cte.numcte 
			  AND si_cte.empresa = pEmpresa 
			  AND sc_fir.numcte = si_pf.numcte
			  AND sc_mcq.empresa = pEmpresa 
			  AND sc_mcq.cuenta = pNumeroCuenta


			-- OBTENER LA TARJETA DEL FIRMANTE --

			SELECT DISTINCT
				sc_tjt.expiracion, sc_tjt.prodtarjeta, sc_tjt.num_tarjeta, sc_tjt.limite_aut, sc_tjt.status_tar
			INTO
				Vexpiracion, Vprodtarjeta, vNumTarj, vLimTar, vStatTjt
			FROM
				bdicheq:"informix".sc_tarjeta AS sc_tjt
			WHERE sc_tjt.empresa = pEmpresa 
			  AND sc_tjt.cuenta = pNumeroCuenta
			  AND sc_tjt.numcte = vNumCte
			  AND sc_tjt.tipo_tarjeta = 'A'
			  AND sc_tjt.status_tar = 'A' --DSB 27/06/2012
			  AND sc_tjt.secuencia = (
					SELECT MAX(secuencia) 
					  FROM bdicheq:sc_tarjeta 
					 WHERE sc_tjt.empresa = empresa 
					   AND sc_tjt.cuenta = cuenta 
					   AND sc_tjt.numcte = numcte
					   AND sc_tjt.tipo_tarjeta = 'A');

			IF vNumTarj IS NULL THEN
				LET vNumTarj = "Sin tarjeta";
				LET vLimTar = 0;
				LET vStatTjt = "";
			END IF

			LET vCantReg = vCantReg + 1;

			RETURN vCodRet, vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vNumTarj, Vexpiracion, 
					Vprodtarjeta, vLimTar, vStatTjt, vTipoCte, vFechaNac, vProductoCuenta, vParentesco WITH RESUME;
		
		END FOREACH;

		IF vCantReg = 0 THEN
			LET vCodRet  	 = "000";
			LET vNumCte  	 = "";
			LET vApePat  	 = "";
			LET vApeMat  	 = "";
			LET vNombre1 	 = "";
			LET vNombre2 	 = "";
			LET vRFC     	 = "";
			LET vNumTarj 	 = "";
			LET Vexpiracion  = "";
			LET Vprodtarjeta = "";
			LET vLimTar  	 = 0;
			LET vStatTjt 	 = "";
			LET vTipoCte 	 = "";
			LET vFechaNac 	 = "";
			LET vParentesco	 = "";

			RETURN vCodRet, vNumCte, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vNumTarj, Vexpiracion, 
					Vprodtarjeta, vLimTar, vStatTjt, vTipoCte, vFechaNac, vProductoCuenta, vParentesco;
		
		END IF;
	
	END 
	
END PROCEDURE

DOCUMENT
'DESCRIPCION: Se modifica para que consulte todos los status de tarjetas',
'             incluyendo las tarjetas canceladas',
'EJECUTADO O LLAMADO POR: AsigAdic.exe',
'AUTOR : Martin Eduardo Miranda Miranda',
'FECHA : 14/Septiembre/2010',
'BD    : BDICHEQ',

'DESCRIPCION: Se agrega filtro para obtener datos de tajertas unicamente Activas',
'EJECUTADO O LLAMADO POR: AsigAdic.exe',
'AUTOR : Daniela Ramírez',
'FECHA : 27/Junio/2012',
'BD    : BDICHEQ';

CREATE PROCEDURE "informix".sp_consprodxctaedad(pEmpresa CHAR(3), pNumCuenta CHAR(20), pTipo CHAR(1))

	--DATOS A REGRESAR--
	RETURNING CHAR(5) AS CodigoRetorno, 
			  CHAR(4) AS Producto;
			  
	--DEFINICION DE VARIABLES--
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRet CHAR(5);
	DEFINE cProducto CHAR(4);
	
	--INICIALIZACION DE VARIABLES--
	LET iSqlErr   = 0;
	LET cCodRet   = '00000';
	LET cProducto = '0';

	--SET DEBUG FILE TO "/respaldosbd/Daniela/sp_consprodxctaedad.out";
	--TRACE ON;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cProducto;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;

		IF(pEmpresa is NULL) OR (pNumCuenta IS NULL) OR (pTipo IS NULL) THEN
			RETURN "00001", 'Err';
		END IF;
		
		--Se obtiene el producto al que pertenece la cuenta
		
		IF pTipo = "1" THEN --Productos de Débito
		
			IF LENGTH(pNumCuenta) = 11 THEN
				SELECT producto INTO cProducto FROM bdicheq:"informix".sc_maechq WHERE cuenta = pNumCuenta;
			ELSE
				SELECT b.producto INTO cProducto FROM bdicheq:"informix".sc_tarjeta a, bdicheq:"informix".sc_maechq b
				WHERE a.num_tarjeta = pNumCuenta AND a.cuenta = b.cuenta;
			END IF;
			
		ELIF pTipo = "2" THEN --Productos de Inversión
		
			SELECT cod_instrum INTO cProducto FROM bdinvers:"informix".sv_maeinv WHERE cuenta = pNumCuenta;
			
		ELIF pTipo = "3" THEN --Productos de Crédito Bancoppel
		
			SELECT b.num_producto INTO cProducto FROM bdicred:"informix".sd_tarjeta a, bdicred:"informix".sd_maecred b
			WHERE a.num_tarjeta = pNumCuenta AND a.num_credito = b.num_credito;
			
		ELIF pTipo = "4" THEN --Producto de Crédito Coppel
		
			LET cProducto = "6500";
			
		END IF;

		
		RETURN cCodRet, cProducto;

	END
	
END PROCEDURE

DOCUMENT
'Conocer el tipo de producto al que pertenece la cuenta del cliente',
'Autor : Daniela Ramírez',
'FECHA : 22/05/2012',
'BD:     bdicheq';

CREATE PROCEDURE "informix".sp_conciliachqcomp1_pba( pempresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;
        
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vcontador1   INTEGER;
    DEFINE vcontador2   INTEGER;
    DEFINE vcontador3   INTEGER;
    DEFINE vcomienza1   SMALLINT;
    DEFINE vcomienza2   SMALLINT;
    DEFINE ven_transacc SMALLINT;
    
    DEFINE vsql          CHAR(600);
    DEFINE vstmt         CHAR(250);
    DEFINE vfecha        CHAR(8);
    DEFINE vfecha_hoy    DATE;
    DEFINE vfecha_ant    DATE;
    DEFINE vpri_hab_mes  DATE;
    DEFINE vfecha_actual DATE;
    DEFINE vproceso      CHAR(16);
    DEFINE vsistema      CHAR(2);
    DEFINE vexiste       INTEGER;
    DEFINE vexistefin    INTEGER;
    DEFINE vusuario      CHAR(10);
    DEFINE vfechaproc    DATE;
    DEFINE vfechaprocsdo DATE;
    
    DEFINE vminaniomes  CHAR(6);
    DEFINE vmaxaniomes  CHAR(6);
    DEFINE vcuenta      CHAR(20);
    DEFINE vnum_cte     CHAR(20);
    DEFINE vsucursal    CHAR(4);
    DEFINE vejecutivo   CHAR(8);
    DEFINE vproducto    CHAR(4);
    DEFINE wproducto    CHAR(4);
    
    DEFINE vcapital_anterior    MONEY(18,2);
    DEFINE vcapital_calculado   MONEY(18,2);
    DEFINE vmovs_cargo_capital  MONEY(18,2);
    DEFINE vmovs_abono_capital  MONEY(18,2);
    DEFINE vcapital_actual      MONEY(18,2);
    DEFINE vdiferencia_capital  MONEY(18,2);

    DEFINE vinteres_anterior    MONEY(18,2);
    DEFINE vinteres_calculado   MONEY(18,2);
    DEFINE vmovs_cargo_interes  MONEY(18,2);
    DEFINE vmovs_abono_interes  MONEY(18,2);
    DEFINE vinteres_actual      MONEY(18,2);
    DEFINE vdiferencia_interes  MONEY(18,2);
    
    DEFINE vcuentaini           CHAR(20);
    DEFINE vcuentafin           CHAR(20);
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET vcomienza1   = -1;
    LET vcomienza2   = -1;
    LET ven_transacc = 0; 
    
    LET vsql          = '';
    LET vstmt         = '';
    LET vfecha        = '';
    LET vfecha_hoy    = ''; 
    LET vfecha_ant    = '';
    LET vpri_hab_mes  = '';
    LET vfecha_actual = '';
    LET vproceso      = 'conciliachqcomp1';
    LET vsistema      = '01';
    LET vexiste       = 0;
    LET vexistefin    = 0;
    LET vusuario      = user;
    LET vfechaproc    = '';
    LET vfechaprocsdo = '';
    
    LET vminaniomes  = '';
    LET vmaxaniomes  = '';
    LET vcuenta      = ''; 
    LET vproducto    = '';
    LET wproducto    = '';
    LET vnum_cte     = '';
    LET vsucursal    = '';
    LET vejecutivo   = '';
    
    LET vcapital_anterior   = 0.00;
    LET vcapital_calculado  = 0.00;
    LET vmovs_cargo_capital = 0.00;
    LET vmovs_abono_capital = 0.00;
    LET vcapital_actual     = 0.00;
    LET vdiferencia_capital = 0.00;
    
    LET vinteres_anterior   = 0.00;
    LET vinteres_calculado  = 0.00;
    LET vmovs_cargo_interes = 0.00;
    LET vmovs_abono_interes = 0.00;
    LET vinteres_actual     = 0.00;
    LET vdiferencia_interes = 0.00;
    
    LET vcuentaini = '';
    LET vcuentafin = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_conciliachqcomp1.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasconcilchq1.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq1.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-668)
        LET vcodret1 = '668';
        LET vcodret2 = '668';
        LET vcodret3 = 'PROBLEMAS EN LA DESCARGA DE ARCHIVOS VERIFIQUE';
    END EXCEPTION WITH RESUME;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_conciliachqcomp1.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy, fecha_ant, pri_hab_mes, fecha_hoy
      INTO vfecha_hoy, vfecha_ant, vpri_hab_mes, vfecha_actual
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    -- // VALIDA LA FECHA DE AYER
    LET vfecha_hoy = vfecha_hoy - 1 UNITS DAY;
    
    CALL sp_valfechabil(vfecha_hoy, '-') 
    RETURNING vcodret1, vfecha_hoy;
    
    -- // VALIDA LA FECHA DE ANTIER
    LET vfecha_ant = vfecha_ant - 1 UNITS DAY;
    
    CALL sp_valfechabil(vfecha_ant, '-') 
    RETURNING vcodret1, vfecha_ant;
    
    -- // VERIFICA SE HAYA EFECTUADO EL PASO DE MOVS A HISTORICO
    select fecha 
      into vfechaproc
      from sc_contproc
     where empresa = pempresa 
       and proceso = "pasomovshist"
       and fecha   = vfecha_hoy;

    if vfechaproc is null then
        let vcodret1 = "953";
        let vcodret2 = "953";
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE sistema = vsistema
           AND codigo_retorno = vcodret1;
        
        return vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
    end if;
    
    -- // VERIFICA SE HAYA ACTUALIZADO LA TABLA DE SALDOS DIARIOS (SEGUNDA PARTE)
    select fecha 
      into vfechaprocsdo
      from bdinteg:sx_contproc
     where empresa = pempresa 
       and proceso = "sdoschqdes"
       and fecha   = vfecha_actual
       and sistema = vsistema
       and status_proc = 'F';

    if vfechaprocsdo is null then
        let vcodret1 = "950";
        let vcodret2 = "950";
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE sistema = vsistema
           AND codigo_retorno = vcodret1;
        
        return vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
    end if;
    
    -- // Verifica se haya iniciado el proceso principal
    select {+INDEX (bdicheq:sc_contproc idx_contproc2)} fecha 
      into vfechaproc
      from sc_contproc
     where empresa = pempresa 
       and proceso = "inicio_conciliachq";
       
    if vfechaproc <> vfecha_hoy then
        let vcodret1 = "977";        
        return vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
    end if
     
    -- // GUARDA REGISTRO DE CONTROL EN TABLA DE INTEGRAL
    select count(*)
      into vexiste
      from bdinteg:sx_contproc
     where empresa = pempresa
       and proceso = vproceso
       and fecha   = vfecha_hoy
       and sistema = vsistema;

    if vexiste = 0 then
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horasconcilchq1.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq1.sql';
        SYSTEM vstmt;
    else
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa     = pempresa
           AND proceso     = vproceso
           AND fecha       = vfecha_hoy
           AND sistema     = vsistema
           AND status_proc = "F";
           
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasconcilchq1.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq1.sql';
            SYSTEM vstmt;
        ELSE
            LET vcodret1 = "958";
            LET vcodret2 = "958";
            
            SELECT descripcion
              INTO vcodret3
              FROM bdinteg:si_codret
             WHERE sistema = vsistema
               AND codigo_retorno = vcodret1;

            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
        END IF;
    end if;
    
    -- // OBTIENE EL RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentaini
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniConcilChqComp1'; 
       
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniConcilChqComp2'; 
    
    -- // TABLA TEMPORAL DE MOVIMIENTOS
    ---SELECT {+INDEX(sc_movhis idx_movhisnew6), +INDEX(bdinteg:si_transacc idx_si_transacc4), +INDEX(bdinteg:si_prodtran idx01_prodtran)} 
    SELECT {+INDEX(sc_movhis idx_movhisnew4), +INDEX(bdinteg:si_transacc idx_si_transacc4), +INDEX(bdinteg:si_prodtran idx01_prodtran)} 
           mov.cuenta, mov.transacc, mov.monto_tot,
           TRIM(prod.c_ccmayor)||TRIM(prod.c_ccsub)||TRIM(prod.c_ccsubsub)||TRIM(prod.c_ccsssub)||TRIM(prod.c_ccssssub) AS cta_cargo,
           TRIM(prod.a_ccmayor)||TRIM(prod.a_ccsub)||TRIM(prod.a_ccsubsub)||TRIM(prod.a_ccsssub)||TRIM(prod.a_ccssssub) AS cta_abono
      FROM sc_movhis mov,
           bdinteg:si_transacc tran,
           bdinteg:si_prodtran prod
     ---WHERE mov.fech_alt = vfecha_hoy
     WHERE mov.empresa = '001'
       AND mov.fech_alt = vfecha_hoy
       AND mov.cancelad != 'S'
       AND mov.cuenta BETWEEN vcuentaini and vcuentafin
       ---AND mov.cuenta >= vcuentaini
       ---AND mov.cuenta < vcuentafin
       AND mov.producto <> '1100'
       AND tran.empresa = mov.empresa
       AND tran.numero = mov.transacc
       AND tran.se_contabiliza = 'S'
       AND tran.sistema = '01'
       AND prod.transaccion = tran.numero
       AND prod.producto = mov.producto
       AND prod.sistema = tran.sistema
      INTO TEMP tmp_concilia WITH NO LOG;
      
    ---CREATE INDEX idx_concilia ON tmp_concilia(cuenta) ONLINE;
    CREATE INDEX idx_concilia2 ON tmp_concilia(cuenta, cta_cargo) ONLINE;
    CREATE INDEX idx_concilia3 ON tmp_concilia(cuenta, cta_abono) ONLINE;
    
    ---UPDATE STATISTICS HIGH FOR TABLE tmp_concilia(cuenta, cta_cargo, cta_abono);
    
    -- // FOREACH CUENTAS 
    FOREACH WITH HOLD
        SELECT {+INDEX(sc_maechq idx_sc_maechq), +INDEX(sc_maenoc idx_sc_maenoc2)} chq.cuenta, chq.producto, chq.num_cte, chq.sucursal, noc.ejecutivo
          INTO vcuenta, vproducto, vnum_cte, vsucursal, vejecutivo
          FROM sc_maechq chq,
               sc_maenoc noc
         ---WHERE chq.empresa = pempresa
         WHERE chq.cuenta BETWEEN vcuentaini and vcuentafin
           ---AND chq.cuenta >= vcuentaini
           ---AND chq.cuenta < vcuentafin
           AND chq.producto <> '1100'
           AND ( chq.status_cta <> '2' OR chq.fecha_proceso >= vfecha_hoy )
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
           AND noc.fecha_alta < vfecha_actual
           
        IF vcomienza1 = -1 THEN
            LET vcomienza1 = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;

        -- // OBTIENE SALDOS ANTERIORES
        EXECUTE PROCEDURE sp_capintafecha(vcuenta, vfecha_ant) 
        INTO vcodret1, vcapital_anterior, vinteres_anterior;
        
        IF vcodret1 = '100' THEN
            LET vcapital_anterior = 0.00;
            LET vinteres_anterior = 0.00;
            LET vcodret1 = '000';
        END IF;
        
        LET vcapital_calculado = vcapital_anterior;
        LET vinteres_calculado = vinteres_anterior;
        
        -- // RESTA CAPITAL 
        SELECT {+INDEX(tmp_concilia idx_concilia2)} 
               NVL(SUM(tmp.monto_tot),0.00)
          INTO vmovs_cargo_capital
          FROM tmp_concilia tmp
         WHERE tmp.cuenta = vcuenta
           AND tmp.cta_cargo IN( SELECT {+INDEX(sc_ctascontchq idx_ctascont)} 
                                        cta_contable 
                                   FROM sc_ctascontchq 
                                  WHERE tipo IN('CAPITAL', 'SOBREGIRO') );

        LET vcapital_calculado = vcapital_calculado - vmovs_cargo_capital;
        
        -- // SUMA CAPITAL 
        SELECT {+INDEX(tmp_concilia idx_concilia3)} 
               NVL(SUM(tmp.monto_tot),0.00)
          INTO vmovs_abono_capital
          FROM tmp_concilia tmp
         WHERE tmp.cuenta = vcuenta
           AND tmp.cta_abono IN( SELECT {+INDEX(sc_ctascontchq idx_ctascont)} 
                                        cta_contable 
                                   FROM sc_ctascontchq 
                                  WHERE tipo IN('CAPITAL', 'SOBREGIRO') );

        LET vcapital_calculado = vcapital_calculado + vmovs_abono_capital;
        
        -- // RESTA INTERES
        SELECT {+INDEX(tmp_concilia idx_concilia2)} 
               NVL(SUM(tmp.monto_tot),0.00)
          INTO vmovs_cargo_interes
          FROM tmp_concilia tmp
         WHERE tmp.cuenta = vcuenta
           AND tmp.cta_cargo IN( SELECT {+INDEX(sc_ctascontchq idx_ctascont)} 
                                        cta_contable 
                                   FROM sc_ctascontchq 
                                  WHERE tipo = 'INTERES' );

        LET vinteres_calculado = vinteres_calculado - vmovs_cargo_interes;
        
        -- // SUMA INTERES
        SELECT {+INDEX(tmp_concilia idx_concilia3)} 
               NVL(SUM(tmp.monto_tot),0.00)
          INTO vmovs_abono_interes
          FROM tmp_concilia tmp
         WHERE tmp.cuenta = vcuenta
           AND tmp.cta_abono IN( SELECT {+INDEX(sc_ctascontchq idx_ctascont)} 
                                        cta_contable 
                                   FROM sc_ctascontchq 
                                  WHERE tipo = 'INTERES' );

        LET vinteres_calculado = vinteres_calculado + vmovs_abono_interes;
        
        -- // OBTIENE SALDOS ACTUALES
        EXECUTE PROCEDURE sp_capintafecha(vcuenta, vfecha_hoy) 
        INTO vcodret1, vcapital_actual, vinteres_actual;
        
        IF vcodret1 = '100' THEN
            LET vcapital_actual = 0.00;
            LET vinteres_actual = 0.00;
            LET vcodret1 = '000';
        END IF;
        
        -- // OBTIENE DIFERENCIAS
        LET vdiferencia_capital = vcapital_actual - vcapital_calculado;
        LET vdiferencia_interes = vinteres_actual - vinteres_calculado;
        
        -- // LLENA TABLA DE TODAS LAS CUENTAS
        INSERT INTO conciliachq VALUES
        (vfecha_hoy, vcuenta, vproducto, vnum_cte, vsucursal, vejecutivo,
         vcapital_anterior, vmovs_cargo_capital, vmovs_abono_capital, vcapital_calculado, vcapital_actual, vdiferencia_capital, 
         vinteres_anterior, vmovs_cargo_interes, vmovs_abono_interes, vinteres_calculado, vinteres_actual, vdiferencia_interes);
        
        -- // LLENA TABLA DE DIFERENCIAS
        IF (vdiferencia_capital != 0.00 OR vdiferencia_interes != 0.00) THEN
            INSERT INTO conciliachq_dif VALUES
            (vfecha_hoy, vcuenta, vproducto, vnum_cte, vsucursal, vejecutivo,
             vcapital_anterior, vmovs_cargo_capital, vmovs_abono_capital, vcapital_calculado, vcapital_actual, vdiferencia_capital, 
             vinteres_anterior, vmovs_cargo_interes, vmovs_abono_interes, vinteres_calculado, vinteres_actual, vdiferencia_interes); 
             
            LET vcontador2 = vcontador2 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador3 = vcontador3 + 1;
        
        IF vcontador3 >= 5000 THEN
            LET vcontador3 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vcuenta      = ''; 
        LET vproducto    = '';
        LET vnum_cte     = '';
        LET vsucursal    = '';
        LET vejecutivo   = '';
        
        LET vcapital_anterior   = 0.00;
        LET vcapital_calculado  = 0.00;
        LET vmovs_cargo_capital = 0.00;
        LET vmovs_abono_capital = 0.00;
        LET vcapital_actual     = 0.00;
        LET vdiferencia_capital = 0.00;
        
        LET vinteres_anterior   = 0.00;
        LET vinteres_calculado  = 0.00;
        LET vmovs_cargo_interes = 0.00;
        LET vmovs_abono_interes = 0.00;
        LET vinteres_actual     = 0.00;
        LET vdiferencia_interes = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET ejecutivo = '''||vusuario||''','||
               'status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret1||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horasconcilchq1.sql';
    SYSTEM vsql;
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq1.sql';
    SYSTEM vstmt;
           
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".pasamovshistold1_pba( pempresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE info_err         CHAR(40);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfecha_hoy       DATE;
    DEFINE vfecha           DATE;
    DEFINE vdias            INTEGER;
    DEFINE vfecha2          CHAR(10);
    DEFINE vexiste          SMALLINT;
    DEFINE vexistefin       SMALLINT;
    DEFINE vcuenta          CHAR(20);
    DEFINE veliminados      INTEGER;
    DEFINE vproceso         CHAR(20);
    DEFINE vsistema         CHAR(2);
    DEFINE vusuario         CHAR(8);
    DEFINE vsql             CHAR(600);
    DEFINE vstmt            CHAR(250);
    DEFINE vborrado         CHAR(1);
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = '';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET info_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET ven_transacc = 0; 
    
    LET vfecha_hoy  = '';
    LET vfecha      = ''; 
    LET vdias       = 0;
    LET vfecha2     = '';
    LET vexiste     = 0;
    LET vexistefin  = 0;
    LET vcuenta     = ''; 
    LET veliminados = 0;
    LET vproceso    = 'PasaMovsHistOld1';  
    LET vsistema    = '01';
    LET vusuario    = 'informix';
    LET vsql        = '';
    LET vstmt       = '';
    LET vborrado    = '0';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, info_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistold1.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = info_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistold1.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 10;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    SELECT valor 
      INTO vfecha
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PasoMovhis_MovhisOld';
       
    -- // VALIDA CUANTOS DIAS TIENE EL HISTORICO DE MOVIMIENTOS
    LET vdias = vfecha_hoy - vfecha;
    
    IF vdias <= 31 THEN
        LET vcodret1 = '111';
        LET vcodret2 = '111';
        LET vcodret3 = 'EL HISTORICO NO TIENE MAS DE 31 DIAS';
        RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
    END IF;
     
    -- // Guarda inicio de proceso     
    SELECT COUNT(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'PasaMovsHistOld1'
       AND fecha   = vfecha
       AND sistema = '01';

    IF vexiste = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horaspasamovsold.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
        SYSTEM vstmt;
    ELSE
        SELECT COUNT(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = 'PasaMovsHistOld1'
           AND fecha   = vfecha
           AND sistema = '01'
           AND status_proc = 'F';
    
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
            SYSTEM vsql;            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
            SYSTEM vstmt;
        ELSE
            LET vcodret1 = '958';
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'F'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END IF;
    
    -- // NUMERO DE REGISTROS A TRASPASAR
    SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
           COUNT(*)
      INTO vcontador1
      FROM sc_movhis
     WHERE fech_alt = vfecha; 
       
    -- // TRASPASA MOVIMIENTOS 
    FOREACH WITH HOLD 
        SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
               UNIQUE cuenta
          INTO vcuenta
          FROM sc_movhis
         WHERE fech_alt = vfecha
           AND producto NOT IN('1200','1600','9900','9901')
           
        BEGIN WORK;
        LET ven_transacc = 1; 
        
        IF vfecha > '05/08/2012' THEN
            INSERT INTO sc_movhis_old
            ---SELECT {+INDEX(sc_movhis idx_movhisnew1)} 
            SELECT {+INDEX(sc_movhis idx_sc_movhis8)} 
                   mov.*
              FROM sc_movhis mov
             ---WHERE mov.empresa = pempresa
             WHERE mov.cuenta = vcuenta
               AND mov.fech_alt = vfecha;
        END IF;
           
        LET vborrado = '0';
           
        WHILE vborrado = '0'
            CALL borramovshistold1(pempresa, vcuenta, vfecha)
            RETURNING vcodret1, vcodret2, veliminados;
            
            IF vcodret1 = '000' THEN
                LET vborrado = '1';
            ELSE 
                LET vborrado = '0';
            END IF;
        END WHILE;
        
        LET vcontador3 = vcontador3 + veliminados;
        
        COMMIT WORK;
        LET ven_transacc = 0; 
    END FOREACH;
    
    -- // TRASPASA MOVIMIENTOS 
    FOREACH WITH HOLD 
        SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
               UNIQUE cuenta
          INTO vcuenta
          FROM sc_movhis
         WHERE fech_alt = vfecha
           
        BEGIN WORK;
        LET ven_transacc = 1; 
           
        IF vfecha > '05/08/2012' THEN
            INSERT INTO sc_movhis_old
            ---SELECT {+INDEX(sc_movhis idx_movhisnew1)} 
            SELECT {+INDEX(sc_movhis idx_sc_movhis8)}
                   mov.*
              FROM sc_movhis mov
             ---WHERE mov.empresa = pempresa
             ---  AND mov.cuenta = vcuenta
                WHERE mov.cuenta = vcuenta
               AND mov.fech_alt = vfecha;
        END IF;
           
        LET vborrado = '0';
           
        WHILE vborrado = '0'
            CALL borramovshistold1(pempresa, vcuenta, vfecha)
            RETURNING vcodret1, vcodret2, veliminados;
            
            IF vcodret1 = '000' THEN
                LET vborrado = '1';
            ELSE 
                LET vborrado = '0';
            END IF;
        END WHILE;
           
        LET vcontador3 = vcontador3 + veliminados;
        
        COMMIT WORK;
        LET ven_transacc = 0; 
    END FOREACH;
    
    -- // NUMERO DE REGISTROS TRASPASADOS
    SELECT {+INDEX(sc_movhis_old idx_movhisnew6_old)} 
           COUNT(*)
      INTO vcontador2
      FROM sc_movhis_old
     WHERE fech_alt = vfecha; 
     
    -- // ACTUALIZA PARAMETROS FINALES
    IF vcontador1 = vcontador2 THEN
        LET vfecha2 = to_char(vfecha + 1 UNITS DAY, '%m/%d/%Y');
    
        UPDATE sc_param
           SET valor = vfecha2
         WHERE empresa = pempresa
           AND codparam = 'fechcon_movhis';
           
        UPDATE sc_param
           SET valor = vfecha2
         WHERE empresa = pempresa
           AND codparam = 'PasoMovhis_MovhisOld';
           
        LET vcodret1 = '000';
        LET vcodret2 = '000';
        LET vcodret3 = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'F'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
        SYSTEM vstmt;
    ELSE
        LET vcodret1 = '999';
        LET vcodret2 = '999';
        LET vcodret3 = 'LOS MOVS TRASP NO COINCIDEN CON LOS MOVS ORIG';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
        SYSTEM vstmt;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;

END PROCEDURE;

CREATE PROCEDURE "informix".sc_cons_status_cta(pempresa CHAR(3),
                                                pnum_cta CHAR(20))
returning char(5), char(1), char(4);

					 
    -- Definición de variables
    define vCodRet          char(5);
    define vStatus          char(1);
	define vProducto		char(4);
    define sql_err          integer;
    
    --- Inicializa Variables de Salida
    let vCodRet   	= 	"000";
    let vStatus    	= 	"";
	let vProducto	=	"";
	
	-- ***************************************************************************        
    -- Objetivo:            Consulta el status y producto de una cuenta en especifico
    -- Creado por:			Walber Castro    
    -- Fecha: 				2012/07/04        
    -- ***************************************************************************

    BEGIN

    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            let vCodRet = sql_err;
            RETURN vCodRet, vStatus, vProducto;
        END IF ;
    END EXCEPTION ;

    -- SET DEBUG FILE TO "/tmp/sc_cons_status_cta.out";
    -- TRACE ON;

    IF pnum_cta = "" OR pnum_cta IS NULL OR pempresa = "" OR pempresa IS NULL THEN
        let vCodRet = "001";
        RETURN vCodRet, vStatus, vProducto;
    END IF ;

    SET ISOLATION DIRTY READ ;
	SET LOCK MODE TO WAIT 3;
    
    SELECT LIMIT 1 status_cta, producto
    INTO vStatus, vProducto
    FROM bdicheq:"informix".sc_maechq
	WHERE cuenta = pnum_cta AND empresa = pempresa;
    
    RETURN vCodRet, vStatus, vProducto;

    END
    
END PROCEDURE ;

create procedure "informix".cal_habil_ant_pba(
			pfecha date)
                       	RETURNING char(5),date;

   DEFINE v_codret 	char(5);
   DEFINE v_habil_ant 	date;
   DEFINE v_esferiado 	char(1);
   DEFINE v_bandera	char(1);
   DEFINE v_fecha	date;
   DEFINE sql_err,isam_err int;


-- ****************************************************************************
-- Inicializa variables
-- ****************************************************************************

   LET v_codret    = "000";
   LET v_habil_ant = " ";
   LET v_esferiado = "0";




-- ****************************************************************************
-- valida datos de entrada
-- ****************************************************************************

	IF  	pfecha is null THEN
		-- datos de entrada incompletos
		LET v_codret = 110;
		RETURN v_codret,v_habil_ant;
	END IF;


BEGIN

	on exception set sql_err,isam_err
	if sql_err <> 0 or isam_err <> 0 then
	 let v_codret = sql_err;
	 return v_codret,v_habil_ant;
	end if;
	end exception;

	LET v_fecha = pfecha;


	select "1"
	into v_esferiado
	from bdinteg:si_feriado
	where fecha=v_fecha;

	IF v_esferiado is null THEN
		LET v_esferiado = "0";
	END IF

	IF v_esferiado <>"1" and to_char(v_fecha,"%A") <> "Saturday" and to_char(v_fecha,"%A") <> "Sunday"  THEN
		LET v_fecha = v_fecha - 1;
	END IF


	IF v_esferiado = "1"   THEN
		LET v_fecha = v_fecha - 1;
	END IF

	IF to_char(v_fecha,"%A") = "Saturday"  THEN
		LET v_fecha = v_fecha - 1;
	END IF

	IF to_char(v_fecha,"%A") = "Sunday"  THEN
		LET v_fecha = v_fecha - 2;
	END IF




	-- barrer hasta obtener el sig. habil

	LET v_bandera = "0";
	WHILE v_bandera = "0"

		-- validar si es feriado la nueva fecha
		select "1"
		into v_esferiado
		from bdinteg:si_feriado
		where fecha=v_fecha;

		IF v_esferiado is null THEN
			LET v_esferiado = "0";
		END IF

		IF v_esferiado <> "1" and to_char(v_fecha,"%A") <> "Saturday" and to_char(v_fecha,"%A") <> "Sunday" THEN
			-- salir
			LET v_bandera = "1";
		ELSE

			LET v_fecha = v_fecha - 1;
		END IF

	END WHILE



	LET v_habil_ant = v_fecha;

END;

RETURN v_codret,v_habil_ant;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_liberaretinterpza_pba( pEmpresa CHAR(3) ) 
RETURNING CHAR(5); 
     
    DEFINE Sql_Err      INTEGER;
    DEFINE Isam_Err     INTEGER;
    DEFINE Desc_Err     CHAR(50);
    DEFINE vCodRet1     CHAR(5);
    DEFINE vCodRet2     CHAR(5);
    DEFINE vCodRet3     CHAR(50);
    DEFINE vContador1   INTEGER;
    DEFINE vContador2   INTEGER;
    DEFINE vAbierto     CHAR(1);
    DEFINE vFechaAnt    DATE;
    DEFINE vFechaHoy    DATE;
    DEFINE vNumCte      CHAR(20);
    DEFINE vCuenta      CHAR(20);
    DEFINE vMontoRet    MONEY(14,2);
    DEFINE vSdoRetenido MONEY(14,2);
    DEFINE vFecha       CHAR(8);
    DEFINE vstmt        CHAR(600);
    DEFINE vsql         CHAR(200);
    DEFINE vFechaIni    DATE;
    DEFINE vFechaFin    DATE;
    DEFINE vFecha1      CHAR(8);
    DEFINE vFecha2      CHAR(8);
    
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '';
    LET vCodRet2     = '';
    LET vCodRet3     = '';  
    LET vContador1   = 0;
    LET vContador2   = 0;
    LET vAbierto     = '0';
    LET vFechaAnt    = '';
    LET vFechaHoy    = '';
    LET vNumCte      = '';
    LET vCuenta      = '';
    LET vMontoRet    = 0.00;
    LET vSdoRetenido = 0.00;
    LET vFecha       = '';
    LET vstmt        = '';
    LET vsql         = '';
    LET vFechaIni    = '';
    LET vFechaFin    = '';
    LET vFecha1      = '';
    LET vFecha2      = '';
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_liberaretinterpza.err";
        TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vAbierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_liberaretinterpza.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // OBTIENE FECHAS DEL SISTEMA DE CHEQUES
    SELECT fecha_ant, fecha_hoy
      INTO vFechaAnt, vFechaHoy
      FROM sc_fechas
     WHERE empresa = pEmpresa;
    
    -- // REALIZA LIBERACION DE MONTOS RETENIDOS
    FOREACH WITH HOLD
        SELECT {+INDEX(sc_depinterpza idx_depintpza_fech)} dep.num_cte, dep.cuenta, dep.monto_ret, mae.sdo_retenido
          INTO vNumCte, vCuenta, vMontoRet, vSdoRetenido
          FROM sc_depinterpza dep,
               sc_maechq mae
         WHERE dep.fecha = vFechaAnt
           AND dep.monto_ret > 0
           AND dep.liberado = '0'
           AND mae.cuenta = dep.cuenta
           AND mae.num_cte = dep.num_cte
           
        BEGIN WORK;
        LET vAbierto = '1';
           
        IF vSdoRetenido >= vMontoRet THEN
            UPDATE sc_maechq
               SET sdo_retenido = sdo_retenido - vMontoRet
             WHERE cuenta = vCuenta;
             
            UPDATE sc_depinterpza
               SET liberado = '1'
             WHERE fecha = vFechaAnt
               AND num_cte = vNumCte
               AND cuenta = vCuenta;
               
            LET vcontador2 = vcontador2 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        LET vAbierto = '0';
        
        LET vNumCte = '';
        LET vCuenta = '';
        LET vMontoRet = 0;
        LET vSdoRetenido = 0;
    END FOREACH;
    
    -- // PASA REGISTROS A TABLA HISTORICA
    FOREACH WITH HOLD
        SELECT UNIQUE cuenta
          INTO vCuenta
          FROM sc_depinterpza
         WHERE fecha < vFechaHoy
         
        BEGIN WORK;
        LET vAbierto = '1';
         
        INSERT INTO sc_depinterpzahist
        SELECT {+INDEX(sc_depinterpza idx_sc_depinterpza3)} *
          FROM sc_depinterpza
         WHERE cuenta = vCuenta
           AND fecha < vFechaHoy;
         
        DELETE {+INDEX(sc_depinterpza idx_sc_depinterpza3)} FROM sc_depinterpza
         WHERE cuenta = vCuenta
           AND fecha < vFechaHoy;
         
        COMMIT WORK;
        LET vAbierto = '0';
    
        LET vCuenta = '';
    END FOREACH;
    
    -- // GENERA REPORTE SEMANAL 
    IF WEEKDAY (vFechaHoy) = 2 THEN
        LET vFechaIni = vFechaAnt - 7 UNITS DAY;
        LET vFechaFin = vFechaAnt - 1 UNITS DAY;
        
        LET vFecha1 = TO_CHAR(vFechaIni, '%d%m%Y');
        LET vFecha2 = TO_CHAR(vFechaFin, '%d%m%Y');
    
        LET vstmt = '';
        LET vstmt = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/MovsInterEstado_'||vFecha1||'_'||vFecha2||'.txt '||
                   'SELECT mae.num_cte, mov.cuenta, mov.monto_tot, mov.sucursal, mov.usuario, mov.fech_alt, mov.fech_hor, mae.sucursal, mov.sdo_cuenta + mov.monto_tot '||
                   'FROM bdicheq:sc_movhis mov, bdicheq:sc_maechq mae '||
                   'WHERE mov.fech_alt BETWEEN '''||vFechaIni||''' AND '''||vFechaFin||''' '||
                   'AND mov.transacc = ''0325'' '||
                   'AND mov.cancelad <> ''S'' '||
                   'AND mae.empresa = mov.empresa '||
                   'AND mae.cuenta = mov.cuenta; " > /resplogifx/conciliachq/movsinterpza.sql';
        SYSTEM vstmt;
        LET vstmt = '';
        
        LET vsql = '';
        LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/movsinterpza.sql"; 
        SYSTEM vsql;
        LET vsql = '';
    END IF; 
    
    LET vCodRet1 = '000';
    LET vCodRet2 = '000';
    LET vCodRet3 = 'PROCESO FINALIZADO';  
    
    END; 
    
    RETURN vCodRet1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cobrosbg_pba(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    
    DEFINE vfecha           DATE;
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    
    DEFINE vcuenta          CHAR(20);
    DEFINE vsucursal        CHAR(4);  
    DEFINE vproducto        CHAR(4);
    DEFINE vsuc_cta         CHAR(4);
    DEFINE vsdo_actual      MONEY(18,2);    
    DEFINE vsdo_retenido    MONEY(18,2);    
    DEFINE vsdo_cong        MONEY(18,2);    
    DEFINE vimp_chq_sbg     MONEY(18,2);    
    DEFINE vsdo_disp        MONEY(18,2);
    
    LET vcodret1	 = '000';
    LET vcodret2     = '000';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET vcomienza    = -1;
    LET ven_transacc = 0;
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    
    LET vfecha  = '';
    LET vhora   = '';
    LET vfolio  = '';
    
    LET vcuenta       = '';
    LET vsucursal     = '9250';
    LET vproducto     = '';
    LEt vsuc_cta      = '';
    LET vsdo_actual   = 0.00;
    LET vsdo_retenido = 0.00;
    LET vsdo_cong     = 0.00;
    LET vimp_chq_sbg  = 0.00;
    LET vsdo_disp     = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cobrosbg.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cobrosbg.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vfecha
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    LET vhora = CURRENT HOUR TO FRACTION;
    LET vfolio = 'informix'||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];
    
    FOREACH WITH HOLD
        SELECT {+INDEX(sc_maechq maecheques)} cuenta, producto, sucursal, sdo_actual, sdo_retenido, sdo_cong, imp_chq_sbg
          INTO vcuenta, vproducto, vsuc_cta, vsdo_actual, vsdo_retenido, vsdo_cong, vimp_chq_sbg
          FROM sc_maechq
         ---WHERE status_cta NOT IN('2','6','7','8')
          WHERE num_cte between '000001001' and '900000006'    
            AND ( ( status_cta != '2' ) OR 
                  ( status_cta != '6' ) OR 
                  ( status_cta != '7' ) OR 
                  ( status_cta != '8' ) )
           AND imp_chq_sbg > 0.00
        
        IF (vcomienza = -1) THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        
        LET vsdo_disp = vsdo_actual - (vsdo_retenido + vsdo_cong);
        
        IF vsdo_disp > 0.00 THEN
        
            IF vsdo_disp >= vimp_chq_sbg THEN
            
                INSERT INTO sc_movdia VALUES
                ( 0, vfolio, vsucursal, "informix", vfecha, vfecha, vhora, '3247', vsuc_cta, vproducto, pempresa, vcuenta, 
                  " ", 0, vimp_chq_sbg, 0, 0, 0, 0, " ", " ", vsdo_actual, '0000', "COBRO PENDIENTE DE SOBREGIRO", 0, " ", "informix" );
                  
                IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
                    IF ven_transacc = 1 THEN
                        ROLLBACK WORK;
                        BEGIN WORK;
                    ELSE
                        ROLLBACK WORK;
                    END IF;
                    CONTINUE FOREACH;
                END IF;
                
                UPDATE sc_maechq
                   SET sdo_actual  = sdo_actual - vimp_chq_sbg,
                       imp_chq_sbg = 0.00
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta;
                
            ELIF vsdo_disp < vimp_chq_sbg THEN
            
                INSERT INTO sc_movdia VALUES
                ( 0, vfolio, vsucursal, "informix", vfecha, vfecha, vhora, '3247', vsuc_cta, vproducto, pempresa, vcuenta, 
                  " ", 0, vsdo_disp, 0, 0, 0, 0, " ", " ", vsdo_actual, '0000', "COBRO PENDIENTE DE SOBREGIRO", 0, " ", "informix" );
                  
                IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
                    IF ven_transacc = 1 THEN
                        ROLLBACK WORK;
                        BEGIN WORK;
                    ELSE
                        ROLLBACK WORK;
                    END IF;
                    CONTINUE FOREACH;
                END IF;
                
                UPDATE sc_maechq
                   SET sdo_actual  = sdo_actual - vsdo_disp,
                       imp_chq_sbg = imp_chq_sbg - vsdo_disp
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta;
                
            END IF;
        
            LET vcontador2 = vcontador2 + 1;
            
        END IF;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vcuenta       = '';
        LET vproducto     = '';
        LEt vsuc_cta      = '';
        LET vsdo_actual   = 0.00;
        LET vsdo_retenido = 0.00;
        LET vsdo_cong     = 0.00;
        LET vimp_chq_sbg  = 0.00;
        LET vsdo_disp     = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_reportesbc_pba(vEmpresa char(3),vfechareporte char(10))

RETURNING CHAR(3)AS vcod_ret, CHAR(20)AS vcuenta, CHAR(4)AS vsucursal,
          DATE AS vfecha_alta,CHAR(4)AS vtransacc,CHAR(40)AS vreferencia,
          INTEGER AS vnum_chq,SMALLINT AS vdias_ori, MONEY(14,2) AS vmonto_ori, 
          CHAR(2)AS vsiglas,CHAR (40) AS vBanco, char (10) AS vfecharep;

--**********************************************************************
--*    sp_reporteSBC                                                   *
--*    Version              1.0.0                                      *
--*    Objetivo:            Obtener el reporte de la liberacion SBC    *
--*    Supuestos:           Ninguno                                    *
--*    Creado por:          Edith Rodríguez Arellano                   *
--*    ModIFicado por:                                                 *
--*    Ultima Modificacion: Enero - 2009                               *
--*                         Creación de SPL                            *
--*    Modificado por JYDG de dia.codigo_fun = '033' a '336'           *
--**********************************************************************

DEFINE vcod_ret CHAR(3);
DEFINE sql_err  integer;
DEFINE vcuenta  CHAR(20);
DEFINE vsucursal CHAR(4);  
DEFINE vfecha_alta DATE;
DEFINE vtransacc CHAR(4);
DEFINE vreferencia CHAR(40);
DEFINE vnum_chq INTEGER;
DEFINE vdias_ori SMALLINT;
DEFINE vmonto_ori MONEY(14,2);
DEFINE vsiglas CHAR(2);
DEFINE vtranlibsbc CHAR(4); 
DEFINE vtranlibctadev CHAR(4);
DEFINE vtranlibsbcTC CHAR(4);
DEFINE vBanco CHAR(40); 

DEFINE vfecharep char(10);

BEGIN
   on exception set sql_err
      if sql_err <> 0 then
         let vcod_ret = sql_err;
        return vcod_ret,null,null,
           null,null,null,
           null,null,null,
           null,null,null;
      end if;
   end exception;

  --SET DEBUG FILE TO "/tmp/sp_reporteSBC.out";
  --TRACE ON;  

LET vcod_ret ='000';
LET vtranlibsbc = "0000";
LET vtranlibctadev = "0000";
LET vtranlibsbcTC = "0000";
LET vfecharep=vfechareporte;
   select valor into vtranlibsbc
     from sc_param
    where empresa = vEmpresa and codparam = "tranlibsbc";

   select valor into vtranlibctadev
     from sc_param
    where empresa = vEmpresa and codparam = "tranlibctadev";

   select valor into vtranlibsbcTC
     from bdicred:sd_param
    where empresa = vEmpresa and cod_param = "83";


   FOREACH
   
   
      SELECT {+INDEX(sc_movdia idx_movdia7a), +INDEX(sc_docret idx_docret2)} ret.cuenta,ret.sucursal,ret.fecha_alta,
             ret.transacc,ret.referencia,ret.num_chq,
             ret.dias_ori,ret.monto_ori,ret.siglas, 
             ban.descripcion
        INTO vcuenta,vsucursal,vfecha_alta,
             vtransacc,vreferencia,vnum_chq,
             vdias_ori,vmonto_ori,vsiglas,
             vBanco  
        FROM sc_movdia dia, 
             sc_docret ret, 
             bdinteg:si_bancos ban
       WHERE dia.cuenta=ret.cuenta
         --AND dia.empresa=ret.empresa
         AND dia.monto_tot=ret.monto_ori
         AND dia.num_cheq=ret.num_chq
         AND dia.folio_suc=ret.folio_suc
         AND (dia.transacc = vtranlibsbc OR dia.transacc = vtranlibctadev OR dia.transacc = vtranlibsbcTC ) 
         AND ret.transacc = dia.transacc
         AND ret.cancelado='L'
         AND ret.siglas='SC'
         AND ban.banco= ret.referencia[1,3] 
   UNION
   
      SELECT ret.cuenta,ret.sucursal,ret.fecha_alta,
             ret.transacc,ret.referencia,ret.num_chq,
             ret.dias_ori,ret.monto_ori,ret.siglas,
             ban.descripcion
        FROM bdicred:sd_movdia dia, 
             sc_docret ret,
             bdicred:sd_tarjeta tar, 
             bdinteg:si_bancos ban 
       WHERE tar.num_tarjeta = ret.cuenta
         AND dia.num_credito = tar.num_credito       
         AND dia.empresa = ret.empresa
         AND dia.monto = ret.monto_ori     
         AND dia.folio_suc[1,14] = ret.folio_suc[1,14]
         AND dia.codigo_fun = '336'
         AND dia.codigo_ref = 1
         AND ret.cancelado = 'L'
         AND ret.siglas = 'SD'
         AND ban.banco = ret.referencia[1,3]  
   
   
   RETURN vcod_ret,vcuenta,vsucursal,
           vfecha_alta,vtransacc,vreferencia,
           vnum_chq,vdias_ori,vmonto_ori,
           vsiglas,vBanco,vfecharep WITH RESUME;
   END FOREACH;

END
END PROCEDURE;

create procedure "informix".gen_protsdo( pempresa       char(3),
                                         psucursal      char(4),
                                         pusuario       char(8),
                                         ptransacc      char(4),
                                         ptransacc_suc  char(4),
                                         pfolio_suc     char(16),
                                         pcuenta        char(20),
                                         pmonto         money(14,2),
                                         pdocto         integer,
                                         pdivisa        char(2),
                                         pnip           char(4),
                                         preferval      char(40),
                                         ptiporef	    char(1),  --- 0 No valida titularidad
                                                                  --- 1 Valida cta_cheques vs cuenta eje
                                                                  --- 2 Valida Titular
                                                                  --- 3 Valida Cotitular
                                                                  --- 4 No valida titularidad ni tipo persona y nip
                                         pnum_tarjeta   char(16),
                                         pusuautoriza   char(8) )
returning char(5), char(8), money(14,2);

    define cod_ret          char(5);
    define vfecha           date;
    define vfechacalendario date;
    define v_valdoc         char(1);
    define v_tipo_tran      char(2);
    define v_moneda         char(2);
    define v_tpcheque       char(2);
    define v_long_cta       char(2);
    define vcuenta          char(20);
    define v_plaza          char(3);
    define v_succta         char(4);
    define v_producto       char(4);
    define v_numreg         smallint;
    define v_dias           smallint;
    define longitud         smallint;
    define v_mesdia         char(4);
    define v_tranret        char(4);
    define v_cal_int_chq    char(1);
    define v_clave          char(8);
    define v_cvepro         char(8);
    define v_fisica         char(1);
    define v_tipper         char(1);
    define sql_err          integer;
    define v_monto_val_nip  money(16,2);
    define v_disponible     money(16,2);
    define v_nip            char(4);
    define v_numcte         char(20);
    define v_cotit          char(20);
    define v_cteexo         char(20);
    define v_band           char(1);
    define v_tasapl         char(8);
    define v_valortasa      money(14,2);
    define v_comision       money(14,2);
    define vstatus_cta      char(1);
    
    let cod_ret    = "000";
    let v_clave    = "    ";
    let v_comision = 0;
    
    begin
    
    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret, v_clave, v_comision;
        end if;
    end exception;
    
    -- Extrae la fecha del sistema de cheques
    select {+INDEX(sc_fechas idx_fechas1)} fecha_hoy 
      into vfechacalendario 
      from sc_fechas 
     where empresa = pempresa;

    select fecha_proceso, status_cta  
      into vfecha, vstatus_cta
      from sc_maechq
     where empresa = pempresa
       and cuenta = pcuenta;

    if ( vfecha is null or vstatus_cta = '4' or vstatus_cta = '5' ) then
        let vfecha = vfechacalendario;
    end if

    if ( vfecha < vfechacalendario ) then
        let cod_ret = "549";
        return  cod_ret, v_clave, v_comision;
    end if
    
    if ( vstatus_cta in('2','6','7','8') ) then
        let cod_ret = "200";
        return  cod_ret, v_clave, v_comision;
    end if
    
    -- Extrae la informacion de la Cuenta de Cheques
    select cuenta, num_cte, producto, plaza
      into vcuenta, v_numcte, v_producto, v_plaza
      from sc_maechq
     where empresa = pempresa 
       and cuenta = pcuenta;
       
    if vcuenta is null then
        let cod_ret = "100";
        return cod_ret, v_clave, v_comision;
    end if
    
    -- Valida el nip de acuerdo al monto por tipo de cliente
    if ptiporef <> "4" then
        select monto_val_nip 
          into v_monto_val_nip
          from bdinteg:si_cliente clie, 
               bdinteg:si_tipocte tpoclie
         where clie.tipo_cliente = tpoclie.tipo_cliente 
           and numcte = v_numcte;

        if pmonto >= v_monto_val_nip then
            select nip 
              into v_nip 
              from bdinteg:si_servcte
             where numcte = v_numcte;
            
            if v_nip is null then
                let v_nip = " ";
            end if;

            if v_nip <> pnip then
                let cod_ret = "614";
                return cod_ret, v_clave, v_comision;
            end if
        end if

        --- Valida personalidad del cliente
        select {+INDEX(bdinteg:si_tipper ix193_1)} es_fisica 
          into v_fisica
          from bdinteg:si_cliente clie, 
               bdinteg:si_tipper tpe
         where clie.numcte = v_numcte 
           and clie.tpo_persona = tpe.tpo_persona;

        if v_fisica <> "S" or v_fisica is null then
            let cod_ret = "122";
            return cod_ret, v_clave, v_comision;
        end if
    end if

    if ptiporef = "2" then
        --- Valida Titular
        if v_numcte <> preferval then
            let cod_ret = "211";
            return cod_ret, v_clave, v_comision;
        end if
    end if

    if ptiporef = "3" then
        --- Valida Titular y Cotitular
        let v_band = "0";
        
        if v_numcte <> preferval then
            foreach
                select {+INDEX(sc_cotitular idx_cotit2)} nombre 
                  into v_cotit 
                  from sc_cotitular
                 where empresa = pempresa 
                   and cuenta = pcuenta

                if v_cotit <> preferval then
                    continue foreach;
                else
                    let v_band = "1";
                    exit foreach;
                end if
            end foreach
            
            if v_band = "0" then
                let cod_ret="211";
                return cod_ret, v_clave, v_comision;
            end if
        end if
    end if

    select tipo_tran, dias_ret, tasa_aplicada, valida_docto
      into v_tipo_tran,v_dias, v_tasapl, v_valdoc
      from bdinteg:si_transacc
     where empresa = pempresa 
       and numero = ptransacc;

    if v_tipo_tran is null then
        let v_tipo_tran = 0;
    end if;

    if v_tipo_tran < "20" and v_tipo_tran > "29" then
        let cod_ret = "615";
        return cod_ret, v_clave, v_comision;
    end if

    if v_dias is null then
        let v_dias = 0;
    end if
    
    let v_producto = v_producto;

    select divisa 
      into v_moneda
      from sc_producto
     where empresa = pempresa 
       and producto=v_producto;
       
    if v_moneda is null then
        let cod_ret = "110";
        return cod_ret, v_clave, v_comision;
    end if;
    
    if v_valdoc = "S" then
        --- Valida que el Cheque no haya sido protegido previamente
        select count(*) 
          into v_numreg 
          from sc_docret
         where empresa = pempresa 
           and cuenta = pcuenta
           and num_chq = pdocto
           and cancelado = "P"
           and folio_suc = pfolio_suc;
        
        if v_numreg is null then
            let v_numreg = 0;
        end if
        
        if v_numreg > 0 then
            let cod_ret = "616";
            return cod_ret, v_clave, v_comision;
        end if
    end if

    call cargon_ref(pempresa,psucursal, pusuario, ptransacc, ptransacc_suc, pfolio_suc, pcuenta, pdocto, pmonto, v_moneda, preferval, pnum_tarjeta,pusuautoriza)
    returning cod_ret, v_tranret;

    --- let cod_ret = "100"; -- Esto regresaba originalmente el procedimiento cargon_ref, se cambio para que regresara "000

    if cod_ret = "000" then
        if v_valdoc = "S" and pdocto <> 0 then
            delete {+INDEX(sc_histch idx_histch1)} 
              from sc_histch
             where empresa = pempresa 
               and cuenta = pcuenta 
               and numero = pdocto;
               
            insert into sc_histch 
            values(pempresa,pcuenta,pdocto,"R",vfecha,pmonto);
            
            delete {+INDEX(sc_contch idx_contch2)} 
              from sc_contch
             where empresa = pempresa 
               and cuenta = pcuenta 
               and numero = pdocto;
        end if
        
        insert into sc_docret values
        ( pempresa, "SC", pcuenta, v_dias, pmonto, pfolio_suc, pusuario, vfecha, current hour to fraction, "P", preferval, psucursal, pdocto, v_dias, ptransacc, pmonto, '', '' );
        
        update sc_maechq
           set (sdo_actual, sdo_retenido, fec_ult_mov) =
               (sdo_actual + pmonto,sdo_retenido + pmonto, vfecha)
         where empresa = pempresa 
           and cuenta = pcuenta;
           
        if vstatus_cta = '5' then
            update sc_maechq
               set status_cta = '1',
                   fecha_proceso = vfechacalendario
             where empresa = pempresa 
               and cuenta = pcuenta;
        end if
    end if
    
    return cod_ret, v_clave, v_comision;
    
    end
    
end procedure;

create procedure "informix".dias_ret_pba(pempresa char(3), pdiaslib smallint)
RETURNING char(5);

    -- ******************************************************
    --                      dias_ret
    -- Version              1.0.0
    -- Obejtivo:            Liberacion documentos retenidos
    -- Creado por:
    -- ModIFicacion por:    Bancoppel
    -- Ultima ModIFicacion: 26 NOV 2009
    -- ******************************************************

    DEFINE vcuenta,vcta_cheques,vnum_cte                    char (20);
    DEFINE vreferencia,desc_err,vcodret3                    char(40);
    DEFINE vdias_ret                                        smallint;
    DEFINE sql_err,isam_err,vrowid                          integer;
    DEFINE vcodret,vcodret1,vcodret2                        char (5);
    DEFINE vplaza                                           char(3);
    DEFINE vsuccta,vsucursal                                char(4);
    DEFINE vusuario                                         char(8);
    DEFINE vfecha_alta,vfechoy                              date;
    DEFINE vfecha                                           date;
    DEFINE vcancelado                                       char(1);
    DEFINE vproducto,vtrandepsbc,vtranret,
           vtranlibsbc,vtranlibsbcTC,vtransuc,
           vtrancancta,vtrancanprov,vtrancapchq             char(4);
    DEFINE vsdo_actual,vmonto,vimpliberar,
           vimpmaxlib,vsdo_retenido,
           vcapital,vsdodisp,vmontoret,
           vtotcanc,vintprov                                money(14,2);
    DEFINE vfolsuc                                          char(16);
    DEFINE vdocto,vsolbcos                                  integer;
    DEFINE horax                                            datetime hour to fraction(3);
    DEFINE vcero                                            smallint;
    DEFINE vsecuencia,vdias_ori,vdifdias                    smallint;
    DEFINE vexiste, vabierto, vstatus                        char(1);
    DEFINE vmoneda,vsiglas,vsistema                         char(2);
    DEFINE vmensaje                                         char(80);
    DEFINE vnum_tarjeta                                     char(16);
    DEFINE vmaxsec                                          smallint;
    DEFINE vreferencia2                                     char(40);
    DEFINE vmonto1,vmonto2,vmonto3,
           vmonto4,vmonto5,vmonto6,
           vmonto7,vmonto8,vmonto9                          Money(14,2);
    DEFINE wSecuenciaPago                                   smallint;
    DEFINE vnum_credito                                     char(20);
    DEFINE vfechalta                                        date;
    DEFINE vcolateral                                       CHAR(1);
    DEFINE vstatus_cta                                      CHAR(1);
    DEFINE vmotivo                                          CHAR(2);
    DEFINE vtranlibctadev, vtranlibsbcA, vtranlibctadevA    CHAR(4);
    DEFINE vtranlibsbcTCA                                   CHAR(4);
    DEFINE vrowid1                                          int;
    DEFINE vrefnew                                          char(20);
    DEFINE vcvebconew                                       char(3);
    DEFINE vcomienza                                        INTEGER;
    DEFINE vexistechq                                       INTEGER;
    DEFINE vexistecta                                       CHAR(20);

    let pempresa = "001";
    let vabierto = "0";
    let vtransuc = "0000";
    let vdocto   = 0;
    let vcodret  = "000";
    let vcero    = 0;
    let vcuenta = "";
    let vcta_cheques = "";
    let vnum_cte = "";
    let vreferencia = "";
    let vdias_ret = 0;
    let vcodret1 = "";
    let vplaza  = "";
    let vsuccta = "";
    let vsucursal = "";
    let vusuario = "";
    let vfecha_alta = "";
    let vfechoy = "";
    let vfecha = "";
    let vcancelado = "";
    let vproducto = "";
    let vtrandepsbc = "";
    let vtranret = "";
    let vtranlibsbc = "";
    let vtranlibsbcTC = "";
    let vtranlibctadev = "";
    let vtransuc = "";
    let vtrancancta = "";
    let vtrancanprov = "";
    let vtrancapchq  = "";
    let vsdo_actual = 0;
    let vmonto = 0;
    let vimpliberar = 0;
    let vimpmaxlib = 0;
    let vsdo_retenido = 0;
    let vcapital = 0;
    let vsdodisp = 0;
    let vmontoret = 0;
    let vtotcanc = 0;
    let vintprov  = 0;
    let vfolsuc  = "";
    let vdocto = 0;
    let vsolbcos = 0;
    let horax  = "";
    let vsecuencia = 0;
    let vdias_ori = 0;
    let vdifdias = 0;
    let vexiste = "";
    let vabierto = "";
    let vstatus = "";
    let vmoneda = "";
    let vsiglas = "";
    let vsistema = "";
    let vmensaje = "";
    let vnum_tarjeta  = "";
    let vmaxsec = 0;
    let vreferencia2 = "";
    let wSecuenciaPago = 0;
    let vnum_credito = "";
    LET vcolateral   = "";
    LET vstatus_cta  = "";
    LET vmotivo      = "";
    let vtranlibsbcA = ""; 
    LET vtranlibctadevA = ""; 
    LET vtranlibsbcTCA= ""; 
    let vrowid = 0;
    let vrowid1 = 0;
    LET vrefnew = "";
    LET vcvebconew = "";
    LET vcomienza = -1;
    LET vexistechq = 0;
    LET vexistecta = '';

    --- set debug file to "/tmp/dias_ret.out";
    --- trace on;
    
    begin

    on exception set sql_err, isam_err, desc_err
        set debug file to "/tmp/dias_ret.err";
        trace on;
        if sql_err <> 0 then
            let vcodret = sql_err;
            let vcodret2 = isam_err;
            let vcodret3 = desc_err;
            if vabierto = "1" then
                rollback work;
            end if;
            return vcodret;
        end if;
    end exception;

    set isolation to dirty read;
    set lock mode to wait 16;

    select {+INDEX(sc_fechas idx_fechas1)} fecha_hoy 
      into vfecha 
      from sc_fechas 
     where empresa = pempresa;

    -- // Valida no se halla realizado liberacion
    select {+ INDEX(sc_contproc idx_contproc2)} rowid, "1"
      into vrowid1, vexiste
      from sc_contproc
     where empresa = pempresa 
       and proceso = "docret" 
       and fecha = vfecha; 
       
    if vexiste = "1" then
        let vcodret = "971";
        return vcodret;
    end if

    select ejecutivo 
      into vusuario
      from bdinteg:si_ejecut
     where ejecutivo = user;

    select valor 
      into vtranlibsbc
      from sc_param
     where empresa = pempresa 
       and codparam = "tranlibsbc";

    let vtranlibsbcA = vtranlibsbc; 

    select valor 
      into vtranlibctadev
      from sc_param
     where empresa = pempresa 
       and codparam = "tranlibctadev";

    LET vtranlibctadevA = vtranlibctadev; 

    select valor 
      into vtranlibsbcTC
      from bdicred:sd_param
     where empresa = pempresa 
       and cod_param = "83";

    LET vtranlibsbcTCA = vtranlibsbcTC; 

    if weekday(vfecha) = 0 or weekday(vfecha) = 6 then
        update {+INDEX(sc_contproc idx_contproc2)} sc_contproc
           set fecha = vfecha
         where empresa = pempresa 
           and proceso = "docret"; 
           
        let vcodret = "000";
        return vcodret;
    end if

    select {+INDEX(bdinteg:si_feriado idx_feriado)} "1" 
      into vexiste
      from bdinteg:si_feriado
     where fecha = vfecha 
       and empresa = pempresa;
       
    if vexiste = "1" then
        update {+INDEX(sc_contproc idx_contproc2)} sc_contproc
           set fecha = vfecha
         where empresa = pempresa 
           and proceso = "docret";  
        
        let vcodret = "000";
        return vcodret;
    end if

    FOREACH WITH HOLD
        select {+INDEX(sc_docret idx_docret3)}
               rowid,cuenta,dias_ret,monto,folio_suc,cancelado,referencia,sucursal,num_chq,dias_ori,transacc,siglas, fecha_alta, banco, numcuenta
          into vrowid,vcuenta,vdias_ret,vmonto,vfolsuc,vcancelado,vreferencia,vsucursal,vdocto,vdias_ori,vtrandepsbc,vsiglas, vfechalta, vcvebconew, vrefnew
          from sc_docret
         where siglas in ('SC', 'SD')
           and fecha_alta < vfecha
           and cancelado = "T" 
           and transacc in('0250', '6250')
         order by siglas, dias_ret
         
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET vabierto = "1";
        END IF;

        LET vtranlibsbc    = vtranlibsbcA; 
        LET vtranlibctadev = vtranlibctadevA; 
        LET vtranlibsbcTC  = vtranlibsbcTCA; 
        
        --- LET vrefnew = vreferencia[6,25]; -- Se agrega para extraer los 20 digitos y no hacerlo en la consulta
        --- LET vrefnew = vrefnew;
        
        --- LET vrefnew = SUBSTR(vrefnew,10,11);
        --- LET vrefnew = vrefnew;
        
        --- LET vcvebconew = vreferencia[1,3]; -- Se agrega para extraer los 3 digitos de clave banco y no en la consulta
        --- LET vcvebconew = vcvebconew;

        -- // Valida si los Cheques a Liberar Fueron Presentados
        SELECT {+INDEX(bditef:cce_cheques_det cheques_det2)} 
               COUNT(*) 
          INTO vexistechq
          FROM bditef:cce_cheques_det
         WHERE empresa = pempresa
           AND cvebanco = vcvebconew
           AND numcuenta = vrefnew
           AND numcheque = vdocto
           AND fechapresenta <= vfecha
           AND monto = vmonto
           AND fecha_alta <= vfecha
           AND presentado = "1";

        IF vexistechq = 0 THEN
            continue foreach;
        END IF;

        let vdias_ret = vdias_ret - pdiaslib;
        let vdifdias = vdias_ori - vdias_ret;
        
        if vdias_ret < 1 then
            let vimpliberar = vmonto;
            let vstatus = "L";
        else
            let vimpliberar = 0;
        end if
        
        if vimpliberar > 0 then
        
            if vsiglas = "SC" then -- // Captacion

                select mc.sucursal, mc.producto, sdo_actual, mc.colateral, mc.status_cta, mc.motivo
                  into vsuccta, vproducto, vsdo_actual, vcolateral, vstatus_cta, vmotivo
                  from sc_maechq mc,
                       sc_producto pr
                 where mc.empresa = pempresa 
                   and mc.cuenta = vcuenta
                   and pr.empresa = mc.empresa 
                   and pr.producto = mc.producto;
                   
                /* ###########################
                select max(secuencia) 
                  into vmaxsec
                  from sc_tarjeta
                 where empresa = pempresa 
                   and cuenta = vcuenta 
                   and tipo_tarjeta = "T";
                   
                select num_tarjeta 
                  into vnum_tarjeta
                  from sc_tarjeta
                 where empresa = pempresa 
                   and cuenta = vcuenta 
                   and secuencia = vmaxsec;
                ########################### */

                -- // Para el caso de doctos devueltos en cuentas especiales, cambia la transaccion 
                IF vcolateral = "S" AND vstatus_cta = "3" AND vmotivo = "99" THEN 
                    /* ##########################################################################
                    IF EXISTS (SELECT {+INDEX(bditef:cce_cheques_dev idx_chqdev)} cta_deposito 
                                 FROM bditef:cce_cheques_dev
                                WHERE numcheque = vdocto
                                  AND lpad(trim(numcuenta),20,"0") = vreferencia[6,25]
                                  AND monto = vmonto
                                  AND fechapresenta >= vfechalta
                                  AND empresa = pempresa
                                  AND cvebanco = vreferencia[1,3]) THEN
                                  
                                  
                        LET vtranlibsbc = vtranlibctadev;
                    END IF
                    ########################################################################## */
                    
                    SELECT {+INDEX(bditef:cce_cheques_dev idx_chqdev)}
                           cta_deposito
                      INTO vexistecta
                      FROM bditef:cce_cheques_dev
                     WHERE numcheque = vdocto
                       AND numcuenta = vrefnew
                       AND monto = vmonto
                       AND fechapresenta >= vfechalta
                       AND empresa = pempresa
                       AND cvebanco = vcvebconew;
                       
                    IF vexistecta is not null OR vexistecta <> '' THEN
                        LET vtranlibsbc = vtranlibctadev;
                    END IF
                END IF

                insert into sc_movdia values 
                ( 0, vfolsuc, vsucursal, vusuario, vfecha, vfecha, current hour to fraction(3), vtranlibsbc, vsuccta, vproducto, pempresa, 
                  vcuenta, " ", vdocto, vimpliberar, vimpliberar, vcero, vcero, vcero, " ", " ", vsdo_actual, vtransuc, vreferencia, vcero, '', '');
                        
                update sc_maechq
                   set imp_chq_sbc = imp_chq_sbc - vimpliberar,
                       sdo_actual = sdo_actual + vimpliberar
                 where empresa = pempresa 
                   and cuenta = vcuenta;

                call cobintcomsbg(pempresa, vcuenta, vfolsuc, vusuario, vsucursal)
                returning vcodret1;
                
                IF vcodret1 = "000" THEN
                    update sc_docret
                       set cancelado = vstatus,
                           dias_ret = dias_ret - pdiaslib,
                           monto = monto - vimpliberar
                    where rowid = vrowid;
                --A.S.H.
                ELSE
                    update sc_docret
                       set cancelado = "A",
                           dias_ret = dias_ret - pdiaslib,
                           monto = monto - vimpliberar
                    where rowid = vrowid;
                --A.S.H. 
                END IF

            elif vsiglas = "SD" then -- // Credito

                -- // Ejecuta SPL Libera SBC Principalsbc
                -- // Requiere Datos del Banco y No de Cheque
                Select descripcion[1,19] 
                  Into vreferencia2
                  from bdinteg:si_bancos
                 Where banco = vreferencia[1,3];
                 
                If vreferencia2 Is NUll Then
                    Let vreferencia2 = "PAGO TDC S.B.C "||lpad(vdocto,7,'0');
                Else
                    Let vreferencia = vreferencia2;
                    Let vreferencia2 = vreferencia[1,15]||" "||lpad(vdocto,7,'0');
                End If
                
                -- // Valida la Sec de Pago para agregar al Folio la Secuencia
                SELECT num_credito 
                  INTO vnum_credito
                  FROM bdicred:sd_tarjeta
                 WHERE num_tarjeta = vcuenta;

                SELECT MAX(secuencia)
                  INTO wSecuenciaPago
                  FROM bdicred:sd_secpago
                 WHERE empresa = pEmpresa
                   AND num_credito = vnum_credito;
                   
                let vfolsuc = vfolsuc;
                
                IF (wSecuenciaPago = 0 OR wSecuenciaPago IS NULL) THEN
                    LET wSecuenciaPago = 1;
                ELSE
                    LET wSecuenciaPago = wSecuenciaPago + 1;
                END IF;

                LET vfolsuc = vfolsuc[1,14]||lpad(wSecuenciaPago::varchar(2),2,"0");
                
                call bdicred:principalrefer(pEmpresa, vcuenta, "01", vcuenta, vusuario, vsucursal, vfolsuc, vtranlibsbcTC, 0, vmonto, vreferencia2) 
                returning vcodret1, vmonto1, vmonto2, vmonto3, vmonto4, vmonto5, vmonto6, vmonto7, vmonto8, vmonto9;

                If vcodret1 = "000" Then
                    update sc_docret
                       set cancelado = vstatus,
                           dias_ret = dias_ret - pdiaslib,
                           monto = monto - vimpliberar
                    where rowid = vrowid;
                End if

            else

                select {+INDEX(bdinvers:sv_instrum idx_instrum)}
                       mv.sucursal, mv.cod_instrum, capital, plaza, secuencia, sdo_retenido, sdo_mes_ant, num_cte, moneda, capital
                  into vsuccta, vproducto, vsdo_actual, vplaza, vsecuencia, vsdo_retenido, vintprov, vnum_cte, vmoneda, vcapital
                  from bdinvers:sv_maeinv mv,
                       bdinvers:sv_instrum pr
                 where mv.empresa = pempresa 
                   and mv.cuenta = vcuenta 
                   and pr.cod_instrum = mv.cod_instrum
                   and pr.empresa = mv.empresa
                   and status_cta <> "4";
                   
                insert into bdinvers:sv_movdia values 
                ( pempresa, 0, vfolsuc, vplaza, vsucursal, vusuario, vfecha, current hour to fraction(3), vtranlibsbc, vsuccta, 
                  vcuenta, vsecuencia, vproducto, vcero, vimpliberar, vimpliberar, vcero, vcero, " ", vsdo_actual, vtransuc );

                update bdinvers:sv_maeinv
                   set sdo_retenido = sdo_retenido - vimpliberar
                 where empresa = pempresa 
                   and cuenta = vcuenta 
                   and secuencia = vsecuencia;
                   
                if vsdo_retenido = vimpliberar then
                    select valor 
                      into vtrancancta
                      from bdinvers:sv_param
                     where codparam = "trancancta" 
                       and empresa = pempresa;
                       
                    select valor 
                      into vtrancanprov
                      from bdinvers:sv_param
                     where codparam = "trancanprov" 
                       and empresa = pempresa;
                       
                    select importe, cta_cheques, sistema
                      into vtotcanc, vcta_cheques, vsistema
                      from bdinvers:sv_maeinstrucc
                     where empresa = pempresa 
                       and cuenta = vcuenta 
                       and cap_int = "C" 
                       and aplicado = "N";
                       
                    if vtotcanc is null then
                        let vtotcanc = 0;
                    end if
                    
                    if vtotcanc > 0 then
                        let vreferencia = "CANCELACION DE CERTIFICADO " || vcuenta || " POR DEVOLUCION DE CHEQUE";
                                      
                        select valor 
                          into vtrancapchq
                          from bdinvers:sv_param
                         where codparam = "trancapchq" 
                           and empresa = pempresa;
                           
                        if vsistema = "01" then
                            call abono_ref(pempresa,vsucursal,vusuario,vtrancapchq,"0000",vfolsuc,vcta_cheques,0,vtotcanc,vtotcanc,0,0,0,vmoneda,vreferencia) 
                            returning vcodret;
                        end if
                        
                        if vcodret <> "000" or vsistema <> "01" then
                            call bdibanco:sbsp_graba_solchq(pempresa,vnum_cte,vusuario,vtotcanc,vcuenta) 
                            returning vcodret,vmensaje,vsolbcos;
                        end if
                        
                        insert into bdinvers:sv_movdia values 
                        ( pempresa, 0, vfolsuc, vplaza, vsucursal, vusuario, vfecha, current hour to fraction(3), vtrancancta, 
                          vsuccta, vcuenta, vsecuencia, vproducto, 0, vtotcanc, vtotcanc, 0, 0, " ", vcapital, "0000");
                    end if
                    
                    if vintprov > 0 then
                        insert into bdinvers:sv_movdia values 
                        ( pempresa, 0, vfolsuc, vplaza, vsucursal, vusuario, vfecha, current hour to fraction(3), vtrancanprov,
                          vsuccta, vcuenta, vsecuencia, vproducto, 0, vintprov, vintprov, 0, 0, " ", vcapital, "0000" );
                    end if
                    
                    -- // Actualiza el Maestro de Inversiones
                    update bdinvers:sv_maeinv
                       set status_cta   = "2",
                           fec_cancelac = vfecha,
                           modificado   = vusuario,
                           fecha_mod    = vfecha
                     where empresa = pempresa 
                       and cuenta = vcuenta 
                       and secuencia = vsecuencia;
                       
                    update sc_docret
                       set cancelado = vstatus,
                           dias_ret = dias_ret - pdiaslib,
                           monto = monto - vimpliberar
                     where rowid = vrowid;
                end if
            end if

        else

            UPDATE sc_docret
               SET dias_ret = dias_ret - pdiaslib
            WHERE rowid = vrowid;

        end if
        
        IF vabierto = 1 THEN
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
    end foreach
    
    update {+INDEX(sc_contproc idx_contproc2)} sc_contproc
       set fecha = vfecha
     where empresa = pempresa 
       and proceso = "docret"; 

    IF vabierto = 1 THEN
        COMMIT WORK;
    END IF;
       
    return vcodret;

    end;

end procedure;

CREATE PROCEDURE "informix".sp_consultaproductoscaptacion(cEmpresa CHAR(3))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se obtiene el catálogo de productos de captación
--Realizó: Nancy Sevilla Camacho
--Fecha: 30/03/2012                    
--------------------------------------------------------------------												
		
    --DATOS A REGRESAR---		
	RETURNING CHAR(5),	-- Código de retorno
			  CHAR(4),	-- Número de producto
			  CHAR(40);	-- Nombre del producto

	--DEFINICION DE VARIABLES--
	DEFINE cCodRet      CHAR(5);
	DEFINE iSqlErr      INTEGER;
    ---------------------------
	DEFINE cNumProducto CHAR(4);
	DEFINE cNomProducto CHAR(40);

	--INICIALIZACION DE VARIABLES--
	LET cCodRet = '00000';
	LET iSqlErr = 0;

	LET cNumProducto = '';
	LET cNomProducto = '';

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, 
			       cNumProducto, 
				   cNomProducto;
		END EXCEPTION;

		--SET DEBUG FILE TO "/home/sysifx/Nancy/sp_consultaproductoscaptacion.out";
		--TRACE ON;
		
		--Valida parámetros de entrada
		IF cEmpresa <> '' THEN			

			FOREACH
				SELECT producto, 
					   nombre
				  INTO cNumProducto, 
					   cNomProducto
				  FROM bdicheq:"informix".sc_producto
				 WHERE empresa = cEmpresa
				 and producto>'0000'
				 ORDER BY nombre

				RETURN cCodRet, 
					   cNumProducto, 
					   cNomProducto 
				  WITH RESUME;
			END FOREACH;
			
		ELSE
		
			--Parámetro de entrada vacío
			LET cCodRet = '00001';
			
			RETURN cCodRet, 
				   cNumProducto, 
				   cNomProducto 
			  WITH RESUME;			
			
		END IF;
		
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".elimina_movshistduplicados_cuenta( pempresa CHAR(3), pFecha DATE )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vempieza         SMALLINT;
    DEFINE ven_transacc     SMALLINT;
	DEFINE vcuenta          CHAR(20);
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO REALIZADO SATISFACTORIAMENTE';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vempieza     = -1;
    LET ven_transacc = 0; 
    LET vcuenta      = '';
    LET vsql         = '';
    LET vstmt        = '';
    
    BEGIN
        
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/elimina_movshistduplicados_cuenta.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/elimina_movshistduplicados_cuenta.out";
    --- TRACE ON;
    
    SET OPTIMIZATION HIGH;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxdepurar') THEN
        DROP TABLE ctasxdepurar;
    END IF;
    
    CREATE TABLE ctasxdepurar( cuenta char(20) not null )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX idx_ctaxdepu ON ctasxdepurar(cuenta) USING BTREE FILLFACTOR 99;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/ctas_depuracion.unl DELIMITER ''","'' INSERT INTO ctasxdepurar" > /resplogifx/conciliachq/ctasdep.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasdep.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxdepurar;
    
    FOREACH WITH HOLD 
        SELECT UNIQUE cuenta
          INTO vcuenta
          FROM ctasxdepurar
           
        IF vempieza = -1 THEN
            LET vempieza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        DELETE {+INDEX(sc_movhis_old idx_movhis)} 
               sc_movhis_old
         WHERE empresa = pempresa
		   AND cuenta = vcuenta
		   AND fech_alt = pfecha;
		       
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        COMMIT WORK;
        LET ven_transacc = 0;
    END IF;
       
    END;
    
    RETURN vcodret1, vcodret2, vcodret3, vcontador1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consprodcta(pEmpresa CHAR(3), pNumCuenta CHAR(20), pTipo CHAR(1))

	--DATOS A REGRESAR--
	RETURNING CHAR(5) AS CodigoRetorno, 
			  CHAR(4) AS Producto;
			  
	--DEFINICION DE VARIABLES--
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRet CHAR(5);
	DEFINE cProducto CHAR(4);
	
	--INICIALIZACION DE VARIABLES--
	LET iSqlErr   = 0;
	LET cCodRet   = '00000';
	LET cProducto = '0';

	--SET DEBUG FILE TO "/respaldosbd/Daniela/sp_consprodcta.out";
	--TRACE ON;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cProducto;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;

		IF(pEmpresa is NULL) OR (pNumCuenta IS NULL) OR (pTipo IS NULL) THEN
			RETURN "00001", 'Err';
		END IF;
		
		--Se obtiene el producto al que pertenece la cuenta
		
		IF pTipo = "1" THEN --Productos de Débito
		
			IF LENGTH(pNumCuenta) = 11 THEN
				SELECT producto INTO cProducto FROM bdicheq:"informix".sc_maechq WHERE cuenta = pNumCuenta;
			ELSE
				SELECT b.producto INTO cProducto FROM bdicheq:"informix".sc_tarjeta a, bdicheq:"informix".sc_maechq b
				WHERE a.num_tarjeta = pNumCuenta AND a.cuenta = b.cuenta;
			END IF;
			
		ELIF pTipo = "2" THEN --Productos de Inversión
		
			SELECT cod_instrum INTO cProducto FROM bdinvers:"informix".sv_maeinv WHERE cuenta = pNumCuenta;
			
		ELIF pTipo = "3" THEN --Productos de Crédito Bancoppel
		
			SELECT b.num_producto INTO cProducto FROM bdicred:"informix".sd_tarjeta a, bdicred:"informix".sd_maecred b
			WHERE a.num_tarjeta = pNumCuenta AND a.num_credito = b.num_credito;
			
		ELIF pTipo = "4" THEN --Producto de Crédito Coppel
		
			LET cProducto = "6500";
			
		END IF;

		
		RETURN cCodRet, cProducto;

	END
	
END PROCEDURE

DOCUMENT
'Conocer el tipo de producto al que pertenece la cuenta del cliente',
'Autor : Daniela Ramírez',
'FECHA : 22/05/2012',
'BD:     bdicheq';

CREATE PROCEDURE "informix".pasamovshistold1( pempresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE info_err         CHAR(40);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfecha_hoy       DATE;
    DEFINE vfecha           DATE;
    DEFINE vdias            INTEGER;
    DEFINE vfecha2          CHAR(10);
    DEFINE vexiste          SMALLINT;
    DEFINE vexiste_fecha    SMALLINT;
    DEFINE vstatus_proc     CHAR(1);
    DEFINE vcuenta          CHAR(20);
    DEFINE veliminados      INTEGER;
    DEFINE vproceso         CHAR(20);
    DEFINE vsistema         CHAR(2);
    DEFINE vusuario         CHAR(8);
    DEFINE vsql             CHAR(600);
    DEFINE vstmt            CHAR(250);
    DEFINE vborrado         CHAR(1);
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = '';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET info_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET ven_transacc = 0; 
    
    LET vfecha_hoy    = '';
    LET vfecha        = ''; 
    LET vdias         = 0;
    LET vfecha2       = '';
    LET vexiste       = 0;
    LET vexiste_fecha = 0;
    LET vstatus_proc  = '';
    LET vcuenta       = ''; 
    LET veliminados   = 0;
    LET vproceso      = 'PasaMovsHistOld1';  
    LET vsistema      = '01';
    LET vusuario      = 'informix';
    LET vsql          = '';
    LET vstmt         = '';
    LET vborrado      = '0';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, info_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistold1.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = info_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistold1.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    -- // OBTIENE LA FECHA DE LOS MOVIMIENTOS A TRASPASAR
    SELECT valor 
      INTO vfecha
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PasoMovhis_MovhisOld';
       
    -- // VALIDA CUANTOS DIAS TIENE EL HISTORICO DE MOVIMIENTOS
    LET vdias = vfecha_hoy - vfecha;
    
    IF vdias <= 32 THEN
        LET vcodret1 = '111'; -- // EL HISTORICO NO TIENE MAS DE 31 DIAS
        LET vcodret2 = '111';
        RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
    END IF;
     
    -- // Guarda inicio de proceso     
    SELECT COUNT(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'PasaMovsHistOld1'
       AND fecha   = vfecha
       AND sistema = '01';

    IF vexiste = 0 THEN    
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''', '||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horaspasamovsold.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
        SYSTEM vstmt;
    ELSE
        SELECT status_proc
          INTO vstatus_proc
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = 'PasaMovsHistOld1'
           AND fecha   = vfecha
           AND sistema = '01';
           
        IF vstatus_proc = 'I' THEN
            LET vcodret1 = '953';
            LET vcodret2 = '953';
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        ELIF vstatus_proc = 'F' THEN
            LET vcodret1 = '958';
            LET vcodret2 = '958';
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        ELSE
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
            SYSTEM vsql;            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
            SYSTEM vstmt;
        END IF;
    END IF;
    
    -- // OBTIENE NUMERO DE REGISTROS A TRASPASAR
    SELECT COUNT(*)
      INTO vexiste_fecha
      FROM sc_trasp_movhis_movhisold
     WHERE fecha = vfecha;
     
    IF vexiste_fecha = 0 THEN
        SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
               COUNT(*)
          INTO vcontador1
          FROM sc_movhis
         WHERE fech_alt = vfecha; 
         
        INSERT INTO sc_trasp_movhis_movhisold(fecha, no_regs)
        VALUES(vfecha, vcontador1);
    ELSE
        SELECT no_regs
          INTO vcontador1
          FROM sc_trasp_movhis_movhisold
         WHERE fecha = vfecha;
    END IF;
       
    -- // TRASPASA MOVIMIENTOS 
    FOREACH WITH HOLD 
        SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
               UNIQUE cuenta
          INTO vcuenta
          FROM sc_movhis
         WHERE fech_alt = vfecha
           AND producto NOT IN('1200','1600','9900','9901')
           
        BEGIN WORK;
        LET ven_transacc = 1; 
        
        INSERT INTO sc_movhis_old
        SELECT {+INDEX(sc_movhis idx_movhisnew1)} 
               mov.*
          FROM sc_movhis mov
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.fech_alt = vfecha;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            DELETE {+INDEX(sc_movhis idx_movhisnew1)} 
              FROM sc_movhis
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt = vfecha;
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                COMMIT WORK;
                LET ven_transacc = 0; 
            ELSE
                ROLLBACK WORK;
                LET ven_transacc = 0; 
            END IF;
        ELSE
            ROLLBACK WORK;
            LET ven_transacc = 0; 
        END IF;
    END FOREACH;
    
    -- // TRASPASA MOVIMIENTOS 
    FOREACH WITH HOLD 
        SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
               UNIQUE cuenta
          INTO vcuenta
          FROM sc_movhis
         WHERE fech_alt = vfecha
           
        BEGIN WORK;
        LET ven_transacc = 1; 
           
        INSERT INTO sc_movhis_old
        SELECT {+INDEX(sc_movhis idx_movhisnew1)} 
               mov.*
          FROM sc_movhis mov
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.fech_alt = vfecha;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            DELETE {+INDEX(sc_movhis idx_movhisnew1)}
              FROM sc_movhis
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt = vfecha;
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                COMMIT WORK;
                LET ven_transacc = 0; 
            ELSE
                ROLLBACK WORK;
                LET ven_transacc = 0; 
            END IF;
        ELSE
            ROLLBACK WORK;
            LET ven_transacc = 0; 
        END IF;
    END FOREACH;
    
    -- // NUMERO DE REGISTROS TRASPASADOS
    SELECT {+INDEX(sc_movhis_old idx_movhisnew6_old)} 
           COUNT(*)
      INTO vcontador2
      FROM sc_movhis_old
     WHERE fech_alt = vfecha; 
     
    SELECT {+INDEX(sc_movhis idx_movhisnew6)} 
           COUNT(*)
      INTO vcontador3
      FROM sc_movhis
     WHERE fech_alt = vfecha; 
         
    -- // ACTUALIZA PARAMETROS FINALES
    IF vcontador1 = vcontador2 THEN
        LET vfecha2 = to_char(vfecha + 1 UNITS DAY, '%m/%d/%Y');
    
        UPDATE sc_param
           SET valor = vfecha2
         WHERE empresa = pempresa
           AND codparam = 'fechcon_movhis';
           
        UPDATE sc_param
           SET valor = vfecha2
         WHERE empresa = pempresa
           AND codparam = 'PasoMovhis_MovhisOld';
           
        LET vcodret1 = '000'; -- // PROCESO CONCLUIDO SATISFACTORIAMENTE
        LET vcodret2 = '000';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'F'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
        SYSTEM vstmt;
    ELSE
        LET vcodret1 = '999'; -- // LOS MOVIMIENTOS TRASPASADOS NO COINCIDEN CON LOS MOVIMIENTOS A TRASAPASAR
        LET vcodret2 = '999';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold.sql';
        SYSTEM vstmt;
    END IF;
       
    END;
    
    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_motivocancel(pClaveCanc CHAR(2), pTipoConsulta SMALLINT)
RETURNING
CHAR(6) 	AS 	cCodRet,
CHAR(85)	AS  cMensajeRet,
CHAR(2)	As 	CLAVE,
CHAR(40)	AS	DESCRIPCION;

	--DECLARACIONES
    DEFINE cCodRet          CHAR(6);
    DEFINE iSqlErr          INTEGER;
    DEFINE iIsamErr         INTEGER;
    DEFINE sRegistros       SMALLINT; 
	DEFINE cErrorInfo		CHAR(80);
    DEFINE cMensajeRet      CHAR(85);
    
	DEFINE cClave	        CHAR(2);
    DEFINE cDesc 	        CHAR(40);


    --INICIALIZACIONES
	LET cCodRet				= '000000';
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET sRegistros			= 0;
	LET cErrorInfo			= '';
	LET cMensajeRet			= 'PROCESO EXITOSO';
	
	LET cClave				= '';
	LET cDesc				= '';


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN TRIM(cCodRet), TRIM(cMensajeRet), TRIM(NVL(cClave,'')), TRIM(NVL(cDesc,''));
		END IF;
    END EXCEPTION;

	--SET DEBUG FILE TO "/home/sysifx/armandomorales/sp_infoctecancel.out";
	--TRACE ON;
	
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;	
	
	IF pTipoConsulta = 1 THEN -- TIPO DE CONSULTA PARA OBTENER TODA LA INFORMACION DEL CATALOGO
		
		FOREACH
			SELECT clave, descripcion
			INTO cClave, cDesc
			FROM bdicheq:"informix".sc_motivocancel
			ORDER BY clave

			RETURN TRIM(cCodRet), TRIM(cMensajeRet), TRIM(NVL(cClave,'')), TRIM(NVL(cDesc,'')) WITH RESUME;
		END FOREACH
		
		LET sRegistros = dbinfo("sqlca.sqlerrd2"); -- VALIDA SI EXISTE INFORMACION EN EL CATALOGO
		IF (sRegistros = 0) THEN
			LET cCodRet= '000003';
			LET cMensajeRet= 'NO SE ENCONTRO INFORMACION PARA CONSULTAR, VERIFIQUE';
			
			RETURN TRIM(cCodRet), TRIM(cMensajeRet), TRIM(NVL(cClave,'')), TRIM(NVL(cDesc,''));
		END IF;
	
	ELIF pTipoConsulta = 2 THEN -- TIPO DE CONSULTA PARA OBTENER INFORMACION PARA UNA CLAVE DE CANCELACION EN ESPECIFICO
	
		IF NVL(pClaveCanc, '') = '' THEN			
			LET cCodRet = '000001';
			LET cMensajeRet = 'ERROR EN EL PARAMETRO, CLAVE DE CANCELACION OBLIGATORIA PARA ESTE TIPO DE CONSULTA';
			
			RETURN TRIM(cCodRet), TRIM(cMensajeRet), TRIM(NVL(cClave,'')), TRIM(NVL(cDesc,''));
		END IF;
		
		SELECT clave, descripcion
		INTO cClave, cDesc
		FROM bdicheq:"informix".sc_motivocancel
		WHERE clave = pClaveCanc;
		
		LET sRegistros = dbinfo("sqlca.sqlerrd2"); -- VALIDA SI EXISTE LA CLAVE DE CANCELACION RECIBIDA
		IF (sRegistros = 0) THEN
			LET cCodRet= '000003';
			LET cMensajeRet= 'NO SE ENCONTRO INFORMACION PARA CONSULTAR, VERIFIQUE';
		END IF;		

		RETURN TRIM(cCodRet), TRIM(cMensajeRet), TRIM(NVL(cClave,'')), TRIM(NVL(cDesc,''));
		
	ELSE -- TIPO DE CONSULTA INVALIDA
		LET cCodRet = '000002';
		LET cMensajeRet = 'ERROR EN EL PARAMETRO, TIPO DE CONSULTA NO VALIDA';
			
		RETURN TRIM(cCodRet), TRIM(cMensajeRet), TRIM(NVL(cClave,'')), TRIM(NVL(cDesc,''));
	END IF;
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Arroja un listado de los motivos de cancelación de cuenta', 
'AUTOR: Armando Morales',
'FECHA: Julio 2012',
'VERSION: 20120802.1003';

CREATE PROCEDURE "informix".sp_portabregistraejecucion(pProceso CHAR(50), pFechaEjec DATE, pCodRet CHAR(5), pMensaje CHAR(100), pConsecDiario INTEGER)
RETURNING CHAR   (5) AS CodigoRetorno,
		  CHAR (100) AS MensajeEjecucion;

	--DESCRIPCION DE LOS PARAMETROS DE ENTRADA
		
		/*  pProceso:      	Proceso ejecutado que se registra en bitacora
			pFechaEjec:    	Fecha de ejecucion del proceso
			pCodRet:		Codigo correspondiente a la ejecucion del proceso ejecutado
			pMensaje:		Mensaje que describe la ejecucion del proceso ejecutado
			pConsecDiario: 	Numero de transferencias al proceso de pagos programados
		*/			
	
	-- DECLARACION DE VARIABLES
		  
DEFINE iSqlErr INTEGER;				-- ERROR DE INFORMIX
DEFINE cCodRet CHAR(5);				-- CODIGO DEL ERROR

DEFINE cHoraEjec        CHAR  (8);	-- HORA DE LA EJECUCION DEL PROCESO DE PORTABILIDAD
DEFINE cMensajeBitacora CHAR(100);	-- MENSAJE DE LA EJECUCION DEL PROCESO DE PORTABILIDAD
DEFINE cMensajeEjec     CHAR(100);	-- MENSAJE DE LA EJECUCION DEL PROCESO DE REGISTRO EN BITACORA

	-- INICIALIZACION DE VARIABLES
		  
LET iSqlErr = 0;
LET cCodRet = '00000';

LET cHoraEjec        = CURRENT HOUR TO SECOND;
LET cMensajeBitacora = '';
LET cMensajeEjec     = 'SE REALIZO CORRECTAMENTE EL REGISTRO EN LA BITACORA';

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeEjec = TRIM('ERROR INESPERADO EN LA EJECUCION DEL PROCEDIMIENTO');
			RETURN cCodRet, cMensajeEjec;
		END IF;
	END EXCEPTION;
	
--	SET DEBUG FILE TO "/tmp/sp_PortabRegistraEjecucion.out";
--	TRACE ON;	
	
	-- se valida que los parametros traigan datos
	IF pProceso = '' OR pProceso IS NULL OR pFechaEjec = '' OR pFechaEjec IS NULL OR pCodRet = '' OR pCodRet IS NULL OR
	   pMensaje = '' OR pMensaje IS NULL OR pConsecDiario IS NULL THEN
		LET cCodRet = '00001';
		LET cMensajeEjec = TRIM('ERROR EN LOS PARAMETROS; TODOS LOS PARAMETROS SON OBLIGATORIOS. VERIFIQUE');
		RETURN cCodRet, cMensajeEjec;
	END IF;	
	
	-- se concatena el codigo y el mensaje de la ejecucion del proceso de portabilidad
	LET cMensajeBitacora = TRIM(pCodRet ||' - '|| pMensaje);
	
	-- se registra la ejecucion del proceso de portabilidad en la bitacora
	INSERT INTO bdicheq:sc_portabitacora (proceso, fecha_ejec, hora, mensaje, consec_diario)
	                              VALUES (pProceso, pFechaEjec, TRIM(cHoraEjec), cMensajeBitacora, pConsecDiario);
	
	RETURN cCodRet, TRIM(cMensajeEjec);
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Genera el registro en bitacora de la ejecucion del proceso de la transferencia del servicio de portabilidad',
'al proceso de pagos programados',
'AUTOR: Clemente Angulo Ballardo',
'FECHA: 09 de Junio de 2010',
'VERSION: 20100609.1630',
'BD: BDICHEQ';

create procedure "informix".consnombcta(pempresa char(3),
        ppaterno char(26),
        pmaterno char(26),
        pnombre1 char(26),
        pnombre2 char(26),
        prfc     char(13))

        returning char(5), char(20), char(20);

        DEFINE v_cod_ret char(5);
        DEFINE v_ciclo smallint;
        DEFINE v_numcte char(20);
        DEFINE v_cuenta char (20);


        LET v_cod_ret  = "000";
        LET v_ciclo    = 0;
        LET v_numcte   = "";
        LET v_cuenta   = "";


                foreach
                select
                                a.numcte, b.cuenta
                into
                                v_numcte, v_cuenta
                from
                                bdinteg:si_cliente a,
                                bdicheq:sc_maechq b
                where
                                a.empresa = pempresa and
                                a.apell_paterno matches ppaterno and
                                a.apell_materno matches pmaterno and
                                a.nombre1 matches pnombre1 and
                                a.nombre2 matches pnombre2 and
                                a.rfc = prfc and
                                a.numcte = b.num_cte and
                                b.status_cta = '1'
                order by
                                b.cuenta

                                if not v_cuenta is null then
                                        LET v_ciclo = v_ciclo + 1;

                                        return v_cod_ret, v_cuenta, v_numcte with resume;
                                end if

                end foreach;


        if  v_ciclo = 0 then
                return "141", "", "";
        end if

end procedure
;

CREATE PROCEDURE "informix".consnomtit(pEmpresa CHAR(3), pNumeroCuenta CHAR(20))

	--DATOS A REGRESAR---
	RETURNING
	CHAR(5),  -- Codigo de Retorno
	CHAR(20), -- Numero de cliente
	CHAR(26), -- Apellido Paterno
	CHAR(26), -- Apellido Materno
	CHAR(26), -- Nombre1
	CHAR(26), -- Nombre2
	CHAR(13), -- RFC
    CHAR(4);  -- Numero de Producto	

	--DEFINICION DE VARIABLES--
	DEFINE vCodRet		CHAR(5);
	DEFINE vNumCliente	CHAR(20);
	DEFINE vApePat		CHAR(26);
	DEFINE vApeMat		CHAR(26);
	DEFINE vNombre1		CHAR(26);
	DEFINE vNombre2		CHAR(26);
	DEFINE vRFC      	CHAR(13);
    DEFINE vValProd     CHAR(4);
    DEFINE vNumProd     CHAR(4);
	DEFINE vtpopersona  CHAR(2);
    DEFINE vrazonsocial CHAR(26);
    DEFINE vesfisica    CHAR(1);
	DEFINE vRFC_alterno	CHAR(13);
	DEFINE vStatusCta   CHAR(1);
	
	--INICIALIZACION DE VARIABLES--
	LET vCodRet   	  = "000";
	LET vNumCliente   = "";
	LET vApePat	  	  = "";
	LET vApeMat	      = "";
	LET vNombre1	  = "";
	LET vNombre2	  = "";
	LET vRFC   	      = "";
    LET vValProd      = "";
    LET vNumProd      = "";
	LET vtpopersona   = "";
	LET vrazonsocial  = "";
	LET vesfisica     = "";
	LET vRFC_alterno  = "";
    LET vStatusCta    = "";
    set isolation to dirty read;
    set lock mode to wait 3;
     

	SELECT
		bdi_sicte.numcte, bdi_sicte.apell_paterno, bdi_sicte.apell_materno, 
                bdi_sicte.nombre1, bdi_sicte.nombre2, bdi_sicte.rfc, bdi_sicte.rfc_alterno, bdi_sicte.razon_social, bdi_sicte.tpo_persona,
	        dbc_sdmachq.producto, dbc_sdmachq.status_cta	
	INTO
		vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vRFC_alterno, vrazonsocial, vtpopersona, vNumProd, vStatusCta

	FROM
		bdinteg:si_cliente bdi_sicte,
		bdicheq:sc_maechq dbc_sdmachq

	WHERE
		dbc_sdmachq.cuenta = pNumeroCuenta AND
		dbc_sdmachq.num_cte = bdi_sicte.numcte;
		--AND bdi_sicte.empresa = pEmpresa; AND bdi_sicte.tpo_persona = "01";

		IF vStatusCta = '2' THEN
		LET vCodRet = "200";
		RETURN vCodRet, "","","","","","","";
		END IF
		
    IF vApePat IS NULL AND vNombre1 IS NULL AND vrazonsocial IS NULL THEN
	   LET vCodRet = "100";
	END IF

    SELECT es_fisica 
      INTO vesfisica
      FROM bdinteg:si_tipper
     WHERE tpo_persona = vtpopersona;

    IF vesfisica = "N" THEN
       LET vApePat = TRIM(vrazonsocial);
    END IF	   

    SELECT valor
      INTO vValProd
      FROM bditarjeta:td_producto_emp
     WHERE codigo = vNumProd;

    IF vValProd IS NULL OR Trim(vValProd) = "" THEN
       LET vValProd = "501";
    END IF

	IF vRFC_alterno is not null and vRFC_alterno <> "" THEN
       LET vRFC = vRFC_alterno;
    END IF;	

    RETURN vCodRet, vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vValProd;

END PROCEDURE;

create procedure "informix".cargo_ref_cel_pba(pnum_tarjeta  char(16),
                                       psucursal    char(4),
                                       pusuario     char(8),
                                       ptransacc    char(4),
                                       ptransuc     char(4),
                                       pfolsuc      char(16),
                                       pcuenta      char(20),
                                       pcheque      integer,
                                       pmtocompra   money(14,2),
                                       pmontoefe    money(14,2),
                                       ptransefe    char(4),
                                       pfolioefe    char(16),
                                       pdivisa      char(2),
                                       preferencia  char(40),
                                       psucursalcom char(4),
                                       pusuariocom  char(8),
                                       ptrancencom  char(4),
                                       ptransuccom  char(4),
                                       pfolsuccom   char(16),
                                       pcuentacom   char(20),
                                       pchequecom   integer,
                                       pmontocom    money(14,2),
                                       pdivisacom   char(2),
                                       prefercom    char(40),
                                       pbanderacom  char(1),
                                       ptrancomefe  char(4),
                                       ptrascomefe  char(4),
                                       pfolcomefe   char(16),
                                       pchequeefe   integer,
                                       pmtocomefe   money(14,2),
                                       pdivcomefe   char(2),
                                       prefcomefe   char(40))

       returning char(5),char(4),date,money(14,2),money(14,2),
                 char(5),char(4),date,money(14,2),money(14,2);

define vsqlerr int;
define vcodret,vcodret1,vcodretcom char(5);
define vtranret1,vtranret,vtransacc char(4);
define vtiporef char(1);
define vfechoy date;
define vsdodisp money(14,2);
define vcompend money(14,2);
define vmontoret,vtotcom money(14,2);
define vempresa char(3);
define vejecargo char(1);
define vconreg smallint;
define vcuenta char(20);
define vtotiva money(14,2);
define vtasaiva decimal(9,3);
define vivacom money(14,2);
define vtotret money(14,2);
define vsuccta char(4);
define vtraniva char(4);
define vfecapli date;

define vmtoapli money(14,2);


-- set debug file to "/tmp/cargo_ref_cel.out";
-- trace on;

set lock mode to wait 2;
begin
   on exception set vsqlerr
      if vsqlerr <> 0  then
         let vcodret = vsqlerr;
          ROLLBACK WORK; 
         return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
                vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
      end if;
   end exception;

   --set isolation to cursor stability;

   BEGIN WORK;

   let vcodret = "000";
   let vtranret = " ";
   let vsdodisp = 0;
   let vmontoret = 0;
   let vcodretcom = "000";
   let vtotcom = 0;
   let psucursal = "9"||trim(psucursal);
   let psucursalcom = "9"||trim(psucursalcom);

   select empresa into vempresa
      from bdinteg:si_ejecut
      where ejecutivo = pusuario;

   select fecha_hoy into vfechoy
      from sc_fechas
      where empresa = vempresa;

   let vmontoret = pmtocompra+pmontoefe;
   let vtotcom = pmontocom + pmtocomefe;
   let vfecapli = vfechoy;
   select cuenta into vcuenta
      from sc_tarjeta
      where empresa = vempresa and
            num_tarjeta = pnum_tarjeta;
   if vcuenta is null then
      let vcodret = "100";
      ROLLBACK WORK; 
      return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
             vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
   end if
   select sucursal,sdo_actual-sdo_retenido-sdo_cong
      into vsuccta, vsdodisp
      from sc_maechq
      where empresa = vempresa and cuenta = vcuenta;
   select iva into vtasaiva
      from bdinteg:si_sucursales
      where empresa = vempresa and sucursal = vsuccta;
   if vtasaiva is null then
      let vtasaiva = 0;
   end if
   let vtotiva = vtotcom * vtasaiva;
   let vtotret = pmtocompra + pmontoefe + vtotcom + vtotiva;
   if vsdodisp < vtotret then
      let vcodret = "400";
      ROLLBACK WORK; 
      return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
             vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
   end if

   if pmtocompra > 0 then
      call cargo_ref_td(vempresa,psucursal,pusuario,ptransacc,ptransuc,
                   pfolsuc,vcuenta,pcheque,pmtocompra,pdivisa,preferencia,
                   pnum_tarjeta,"")
           returning vcodret,vtranret,vfecapli,vsdodisp,vmtoapli;
      if vcodret <> "000" then
         ROLLBACK WORK; 
   {      call reversiontd(vempresa,psucursal,pusuario,pfolsuc,"A",
                          vcuenta,ptransacc)
              returning vcodret1;}
         return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
                vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
      end if
   end if

   if pmontoefe > 0 then
      call cargo_ref_td(vempresa,psucursal,pusuario,ptransefe,ptransuc,
                      pfolioefe,vcuenta,pcheque,pmontoefe,pdivisa,preferencia,
                      pnum_tarjeta,"")
           returning vcodret,vtranret,vfecapli,vsdodisp,vmtoapli;
      if vcodret <> "000" then
         ROLLBACK WORK; 
         {
         call reversiontd(vempresa,psucursal,pusuario,pfolsuc,"A",
                          vcuenta,ptransacc)
              returning vcodret1;
         
         call reversiontd(vempresa,psucursal,pusuario,pfolioefe,"A",
                          vcuenta,ptransefe)
              returning vcodret1;}
         return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
                vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
      end if
   end if
   if pmontocom > 0 then
      call cargo_ref_td(vempresa,psucursal,pusuario,ptrancencom,ptransuccom,
                      pfolsuccom,vcuenta,pchequecom,pmontocom,pdivisacom,
                      prefercom,pnum_tarjeta,"")
           returning vcodret,vtranret,vfecapli,vsdodisp,vmtoapli;
      if vcodret <> "000" then
         ROLLBACK WORK; 
         {
         call reversiontd(vempresa,psucursal,pusuario,pfolsuc,"A",
                        vcuenta,ptransacc)
              returning vcodret1;
         
         call reversiontd(vempresa,psucursal,pusuario,pfolioefe,"A",
                        vcuenta,ptransefe)
              returning vcodret1;
         call reversiontd(vempresa,psucursal,pusuario,pfolsuccom,"A",
                        vcuenta,ptrancencom)
              returning vcodret1;}
         return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
                vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
      else
         select tran_relac into vtraniva
            from bdinteg:si_transacc
            where empresa = vempresa and numero = ptrancencom;
         let vivacom = pmontocom * vtasaiva;
         if vivacom > 0 then
            call cargo_ref_td(vempresa,psucursal,pusuario,vtraniva,"0000",
                     pfolsuccom,vcuenta,pchequecom,vivacom,pdivisacom,
                     prefercom,pnum_tarjeta,"")
                 returning vcodret,vtranret,vfecapli,vsdodisp,vmtoapli;
            if vcodret <> "000" then
               ROLLBACK WORK; 
               {
               call reversiontd(vempresa,psucursal,pusuario,pfolsuc,"A",
                                vcuenta,ptransacc)
                    returning vcodret1;
               
               call reversiontd(vempresa,psucursal,pusuario,pfolioefe,"A",
                                vcuenta,ptransefe)
                    returning vcodret1;
               call reversiontd(vempresa,psucursal,pusuario,pfolsuccom,"A",
                                vcuenta,ptrancencom)
                    returning vcodret1;}
               return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
                      vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
            end if
         end if
      end if
   end if
   if pmtocomefe > 0 then
      call cargo_ref_td(vempresa,psucursal,pusuario,ptrancomefe,
                      ptrancomefe,pfolcomefe,vcuenta,pchequeefe,
                      pmtocomefe,pdivcomefe,prefcomefe,pnum_tarjeta,"")
           returning vcodret,vtranret,vfecapli,vsdodisp,vmtoapli;
      if vcodret <> "000" then
         ROLLBACK WORK; 
         {
         call reversiontd(vempresa,psucursal,pusuario,pfolsuc,"A",
                          vcuenta,ptransacc)
              returning vcodret1;
         
         call reversiontd(vempresa,psucursal,pusuario,pfolioefe,"A",
                          vcuenta,ptransefe)
              returning vcodret1;
         call reversiontd(vempresa,psucursal,pusuario,pfolsuccom,"A",
                          vcuenta,ptrancencom)
              returning vcodret1;
         call reversiontd(vempresa,psucursal,pusuario,pfolcomefe,"A",
                          vcuenta,ptrancomefe)
              returning vcodret1;}
      else
         select tran_relac into vtraniva
            from bdinteg:si_transacc
            where empresa = vempresa and numero = ptrancencom;
         let vivacom = pmtocomefe * vtasaiva;
         if vivacom > 0 then
            call cargo_ref_td(vempresa,psucursal,pusuario,vtraniva,
                      "0000",pfolcomefe,vcuenta,pchequeefe,
                      vivacom,pdivcomefe,prefcomefe,pnum_tarjeta,"")
                 returning vcodret,vtranret,vfecapli,vsdodisp,vmtoapli;
            if vcodret <> "000" then
               ROLLBACK WORK; 
              { 
               call reversiontd(vempresa,psucursal,pusuario,pfolcomefe,"A",
                                vcuenta,ptransacc)
                    returning vcodret1;
               call reversiontd(vempresa,psucursal,pusuario,pfolioefe,"A",
                                vcuenta,ptransefe)
                    returning vcodret1;
               call reversiontd(vempresa,psucursal,pusuario,pfolsuccom,"A",
                                vcuenta,ptrancencom)
                    returning vcodret1;}
               return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
                      vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
            end if
         end if
      end if
   end if
   let vfechoy = vfecapli;
   select sdo_actual-sdo_retenido-sdo_cong into vsdodisp
      from sc_maechq
      where empresa = vempresa and cuenta = vcuenta;
   COMMIT WORK;
   return vcodret,vtranret,vfechoy,vsdodisp,vmontoret,
          vcodretcom,ptrancomefe,vfechoy,vsdodisp,vtotcom;
end
end procedure;

CREATE PROCEDURE "informix".cargo_ref_cel_pba
	  (	pTarjeta             CHAR(16),
		pSucursal            CHAR(4),
		pUsuario             CHAR(8),
		pNumTran             CHAR(4),
		pNumTranS            CHAR(4),
		pFolio               CHAR(16),
		pNumCredito          CHAR(20),
		pDocumento           INTEGER,
		pMonto               MONEY(16,2),
		pMonto2              MONEY(16,2),
		pCashTranCen         CHAR(4),
		pCashFolio           CHAR(15),
		pDivisa              CHAR(2),
		pReferencia          CHAR(40),
		pComSucursal         CHAR(4),
		pComUsuario          CHAR(8),
		pComNumTran          CHAR(4),
		pComNumTranS         CHAR(4),
		pComFolio            CHAR(16),
		pComNumCredito       CHAR(20),
		pComDocumento        INTEGER,
		pComMonto            MONEY(16,2),
		pComDivisa           CHAR(2),
		pComReferencia       CHAR(40),
		pComBandera          CHAR(1),
		pSurcharge           CHAR(1),  -- jom Se agrega para identificar el tipo de comision   (F=No aplica,V=Aplica)
		pComCashNumTran      CHAR(4),
		pComCashNumTranS     CHAR(4),
		pComCashFolio        CHAR(16),
		pComCashDocumento    INTEGER,
		pComCashMonto        MONEY(16,2),
		pComCashDivisa       CHAR(2),
		pComCashReferencia   CHAR(40))

   RETURNING CHAR(5),       -- Codigo de Retorno
             CHAR(4),       -- Transaccion
             DATE,          -- Fecha Aplicacion
             MONEY(16,2),   -- Saldo Disponible
             MONEY(16,2),   -- Importe Cargado
             CHAR(5),       -- Codigo de Retorno Comision
             CHAR(4),       -- Transaccion Comision
             DATE,          -- Fecha Aplicacion Comision
             MONEY(16,2),   -- Saldo Disponible Comision
             MONEY(16,2);   -- Importe Cargado ComisioN

   -- **************************************************************************
   -- *                      DEFINICION DE VARIABLES                           *
   -- **************************************************************************
   DEFINE cod_ret               CHAR(5);
   DEFINE cod_ret2              CHAR(5);
   DEFINE sql_err               SMALLINT;
   DEFINE isam_err              SMALLINT;
   DEFINE error_info            CHAR(40);
   DEFINE nrows                 SMALLINT;
   DEFINE Mensaje               CHAR(80);

   DEFINE NumProducto           CHAR(4);
   DEFINE StatusCred            CHAR(2);
   DEFINE Saldo                 MONEY(16,2);
   DEFINE SaldoCom              MONEY(16,2);
   DEFINE TipoCredito           CHAR(2);
   DEFINE MontoOtorgado         MONEY(16,2);
   DEFINE v_com1_dlls           MONEY(16,2);
   DEFINE v_com2_dlls           MONEY(16,2);
   DEFINE v_mtofavor_dlls       MONEY(16,2);
   DEFINE v_mto1_dlls           MONEY(16,2);
   DEFINE v_mto2_dlls           MONEY(16,2);
   DEFINE MtoTot                MONEY(16,2);
   DEFINE TotCargo              MONEY(16,2);
   DEFINE TotComision           MONEY(16,2);
   DEFINE CodigoRef             INTEGER;
   DEFINE CodigoFun             CHAR(3);
   DEFINE wEmpresa              CHAR(3);
   DEFINE wSucursal             CHAR(4);
   DEFINE wDivisa               CHAR(2);
   DEFINE FechaHoy              DATE;
   DEFINE pForzado              CHAR(1);
   DEFINE wBegin                CHAR(1);
   DEFINE vusuario              CHAR(8);
   DEFINE v_paso                SMALLINT;
   DEFINE v_mn                  CHAR(2);
   DEFINE v_dv                  CHAR(2);
   DEFINE v_valor               SMALLINT;
   DEFINE v_tipocambio          DECIMAL(14,6);
   DEFINE v_mensaje             VARCHAR(100);
   DEFINE TasaIva               DECIMAL(5,3);
   DEFINE Iva                   DECIMAL(14,2);
   DEFINE vMtoComDisp           DECIMAL(14,2);
   DEFINE vMtoComDisp_iva       DECIMAL(14,2);     -- RRG Se agrega para el proyecto de circular 22/2010 comisiones ATM 26/10/2010
   DEFINE v_faplica             CHAR(1);
   DEFINE v_factor              DECIMAL(9,6);
   DEFINE v_rangos              CHAR(1);
   DEFINE v_rmax                MONEY(14,2);
   DEFINE v_codparam            CHAR(4);
   DEFINE vSdoPos               DECIMAL(14,2);
   DEFINE vMtoPaso              DECIMAL(14,2);
-- Jom INI Bloqueo de cuentas
   DEFINE vBloqueo              INTEGER;
-- Jom FIN Bloqueo de cuentas
   DEFINE vMtoFavor             DECIMAL(16,2);
   DEFINE pNumTranFavor         CHAR(4);
-- Jom INI limites
   DEFINE vnum_cliente          char(20);
   DEFINE vcodret               char(05);
   DEFINE vmsje_limites         char(80); 
   DEFINE vid_autor             char(01);
   DEFINE vid_transacc          char(02);
   DEFINE vid_canal             char(02);
   DEFINE vuser_limit           char(08);
-- Jom FIN limites
   DEFINE vEscajero             char(01);
   DEFINE v_bloqprod            INTEGER;   
   DEFINE vValDocto             char(01);

   -- **************************************************************************
   -- *                      CONTROL DE ERRORES                                *
   -- **************************************************************************

   ON EXCEPTION SET sql_err, isam_err, error_info
      --SET DEBUG FILE TO "CargoLineaCredito.err";
   --   TRACE sql_err||" * "||isam_err||" * "||error_info;
      LET cod_ret = sql_err;
      LET Saldo = 0;
      LET FechaHoy = NULL;
      RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	     cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END EXCEPTION;

-- SET DEBUG FILE TO "/pisa/cargoref_cel.out";
-- TRACE ON;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

  -- **************************************************************************
  -- *                      ASIGNACION DE VARIABLES                           *
  -- **************************************************************************

   LET wBegin           = "N";
   LET vusuario         = USER;
   LET cod_ret          = "000";
   LET Saldo            = 0;
   LET SaldoCom         = 0;
   LET cod_ret2         = "000";
   LET SaldoCom         = 0;
   LET MontoOtorgado    = 0;
   LET FechaHoy         = NULL;
   LET v_paso           = 0;
   LET MtoTot	        = 0;
   LET v_valor          = 0;
   LET v_tipocambio     = 0;
   LET v_mensaje        = "??";
   LET v_com1_dlls      = 0;
   LET v_com2_dlls      = 0;
   LET v_mtofavor_dlls  = 0;
   LET v_mto1_dlls      = 0;
   LET v_mto2_dlls      = 0;
   LET vMtoComDisp      = 0;
   LET vMtoComDisp_iva  = 0;
   LET vMtoPaso         = 0;
-- Jom INI Bloqueo de cuentas
   LET vBloqueo	        = 0;
-- Jom FIN Bloqueo de cuentas
   LET vMtoFavor        = 0;
   LET pNumTranFavor = pNumTran;
-- Jom INI limites
   LET vnum_cliente     = '';
   LET vcodret          = '';
   LET vmsje_limites    = '';
   LET vid_autor        = '';
   LET vid_transacc     = '';
   LET vid_canal        = '';
   LET vuser_limit      = '';
-- Jom FIN limites
   LET v_bloqprod       = 0;
   LET vEscajero = '0';
   LET vValDocto = '';
     
   --se obtiene la transaccion a favor de acuerdo a la transaccion recibida   
	SELECT transacc_favor,cajero
	INTO pNumTranFavor,vEscajero
	FROM "informix".sd_conceptoscargoscredito
	WHERE transacc = pNumTran;
		
	IF dbinfo("sqlca.sqlerrd2") = 0 THEN--cuando no exista en la tabla se pone el valor por default
      LET pNumTranFavor = pNumTran;
      LET vEscajero = '0';
    END IF;

    IF LENGTH(TRIM(pSucursal)) = 3 then
       LET pSucursal = "9" || TRIM(pSucursal);
    END IF

   SELECT valor INTO v_mn FROM bdinteg:"informix".si_param WHERE cod_param = 15; -- codigo mn
   SELECT valor INTO v_dv FROM bdinteg:"informix".si_param WHERE cod_param = 17; -- divisa de cambio
-- ****************************************************************************
-- *                        PROGRAMA PRINCIPAL                                *
-- ****************************************************************************

   SELECT fecha_hoy
     INTO FechaHoy
     FROM "informix".sd_fechas;
    --WHERE empresa = wEmpresa;

   -- ************************
   -- Busca Datos del Credito*
   -- ************************
       SELECT a.empresa, a.sucursal, a.divisa, a.num_producto, a.status_cred,
              b.monto_otorgado - (b.sdo_cap_insoluto + sdo_retenido),
          c.cod_tipcred, d.iva, e.fecha_proceso,
          CASE WHEN sdo_capital < 0 THEN  sdo_capital * -1 ELSE 0 END,
          a.id_unidad_prod, numcte
         INTO wEmpresa, wSucursal, wDivisa, NumProducto, StatusCred,
              Saldo, TipoCredito, TasaIva, FechaHoy, vSdoPos,
              vBloqueo, vnum_cliente
         FROM "informix".sd_maecred a, "informix".sd_maesdos b, "informix".sd_definicion c, "informix".sd_maecredanexo e,
          bdinteg:"informix".si_sucursales d
        WHERE a.num_credito = pNumCredito
          AND a.empresa = "001"
          AND b.num_credito = a.num_credito
          AND a.empresa = b.empresa
          AND c.num_producto = a.num_producto
          AND e.num_credito = a.num_credito
          AND e.empresa = a.empresa
          AND d.empresa = a.empresa
          AND d.sucursal = pSucursal;

   LET nrows = dbinfo("sqlca.sqlerrd2");
   IF(nrows = 0) THEN
      LET Saldo = 0;
      IF pNumTranS = "9999" then
      	LET cod_ret = "100";
      ELSE
      	LET cod_ret = "008";
      END IF
      RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	     cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END IF;

   IF(TipoCredito <> "03") THEN -- Credito no es tarjeta
      LET cod_ret = "206";
      RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	     cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END IF;

-- ini -- Se agrega bloqueo de cuentas
-- Bloqueo de cuentas operaciones
-- id_unidad_prod = 2 = bloqueo pago
-- id_unidad_prod = 3 = bloqueo disposicion
-- id_unidad_prod = 4 = bloqueo pago y disposicion



--Jom ini Bloqueo de creditos
   IF (vBloqueo = 3 or vBloqueo = 4) THEN -- Bloqueado
      LET cod_ret = "207";
      RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	     cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END IF
  
-- Jom Fin Bloqueo de creditos

   IF SUBSTR(StatusCred,1,1) IN ("B", "F", "C")  THEN -- Cancelado o Bloqueado
      LET cod_ret = "207";
      RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	     cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END IF;

    select count(*) 
      into v_bloqprod
      from bdicred:"informix".sd_bloqueoprod 
     where num_producto=NumProducto 
       and transac_bloq in (pNumTran,pNumTranFavor,pComNumTran,pComNumTranS,pComCashNumTran,pComCashNumTranS);

   IF v_bloqprod > 0  THEN -- bloqueo por producto
      LET cod_ret = "199";
      RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	     cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END IF;

   -- ****************************
   -- Valida Datos del Plasticos *
   -- ****************************

   SELECT valida_docto
     INTO vValDocto
     FROM bdinteg:"informix".si_transacc
    WHERE empresa = wEmpresa
      AND sistema = "06"
      AND numero = pNumTran;

   IF ( nvl(vValDocto,'') <> 'T' ) then
       SELECT COUNT(*) INTO v_valor
         FROM "informix".sd_tarjeta
        WHERE empresa = wEmpresa
          AND num_tarjeta = pTarjeta
          AND status_tar = "A"
          AND expiracion >= FechaHoy;

       IF v_valor IS NULL OR v_valor = 0 THEN -- No hay Plasticos Asignados
          LET cod_ret = "208";
          RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
             cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
       END IF;
   END IF;

   -- ********************************************************
   -- Extrae Tipo de Cambio si se requiere para la operacion *
   -- ********************************************************
	IF pDivisa <> v_mn OR pComDivisa <> v_mn OR pComCashDivisa <> v_mn THEN
		SELECT precio_venta INTO v_tipocambio
	          FROM bdinteg:"informix".si_tpcambio
		 WHERE empresa = "001"
		   AND divisa = v_dv
		   AND clase_tpcambio = "O"
		   AND fecha_tpcambio = (SELECT MAX(fecha_tpcambio)
					   FROM bdinteg:"informix".si_tpcambio
					  WHERE empresa = "001"
					    AND divisa = v_dv);
	END IF

   -- *******************************************************
   -- Valoriza Movimientos en Moneda Diferente a 01 (Pesos) *
   -- *******************************************************

   IF pDivisa <> v_mn THEN
    LET v_mto1_dlls = pMonto;
	LET pMonto = v_mto1_dlls * v_tipocambio;
	LET v_mto2_dlls = pMonto2;
	LET pMonto2 = v_mto2_dlls * v_tipocambio;
   END IF

   IF pComMonto > 0 THEN
   	IF pComDivisa <> v_mn THEN
		LET v_com1_dlls = pComMonto;
		LET pComMonto = v_com1_dlls * v_tipocambio;
   	END IF
   END IF

   IF pComCashMonto > 0 THEN
   	IF pComCashDivisa <> v_mn THEN
		LET v_com2_dlls = pComCashMonto;
		LET pComCashMonto = v_com1_dlls * v_tipocambio;
   	END IF
   END IF

   -- *********************************************
   -- Extrae Comision por disposicion de efectivo *
   -- *********************************************
   IF  pNumTrans IN ("0800", "6900","0871","0872","0873") THEN
        SELECT valor INTO v_codparam
          FROM "informix".sd_param
         WHERE empresa = wEmpresa
           AND cod_param = "334";

        IF vSdoPos > 0 AND vSdoPos < pMonto THEN
            LET vMtoPaso = pMonto - vSdoPos;
        ELIF vSdoPos > 0 AND vSdoPos >= pMonto THEN
            LET vMtoPaso = 0;
        ELIF vSdoPos = 0 THEN
            LET vMtoPaso = pMonto;
        END IF

        IF vMtoPaso > 0 THEN
                SELECT form_aplica, monto, apli_factor, consi_rango, monto_max
                  INTO v_faplica, vMtoComDisp, v_factor, v_rangos, v_rmax
                  FROM "informix".sd_tpcomis
                 WHERE empresa = wEmpresa
                   AND cod_comis = v_codparam;

                IF v_faplica = 2 THEN
                        LET vMtoComDisp = vMtoPaso * (v_factor/100);
                END IF

                IF v_rangos = "1" THEN
                        IF vMtoComDisp < v_rmax THEN
                                LET vMtoComDisp = v_rmax;
                        END IF
                END IF
        END IF
   END IF

   -- *******************************************************
   -- Calcula Iva Global por Comision, solo para validacion *
   -- *******************************************************
		     -- RRG Se modifica para el proyecto de circular 22/2010 comisiones ATM	26/10/2010
   if (pSurcharge = 'V') then
      LET Iva = (pComCashMonto * TasaIva) ;     -- RRG Se modifica para el proyecto de circular 22/2010 comisiones ATM 26/10/2010
   else
      LET Iva = (pComMonto + pComCashMonto) * TasaIva;     -- RRG Se modifica para el proyecto de circular 22/2010 comisiones ATM 26/10/2010
   end if;
   LET vMtoComDisp_iva = vMtoComDisp * TasaIva;     -- RRG Se agrega para el proyecto de circular 22/2010 comisiones ATM 26/10/2010
   LET Iva = Iva +  vMtoComDisp_iva;                -- RRG Se agrega para el proyecto de circular 22/2010 comisiones ATM 26/10/2010

   -- ***************************************
   -- Valida Disponible vs Monto Movimiento *
   -- ***************************************
   IF Saldo < pMonto + pMonto2 + pComMonto +
	      pComCashMonto + vMtoComDisp + Iva THEN
     LET cod_ret = "005";
     RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
            cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;
   END IF

   -- *********************************************
   -- validacion de limites de operaciones        *
   -- *********************************************
--validacion de limites jom ini
    select usuario
      into vuser_limit
      from bdinteg:"informix".si_usuario_limites
     where usuario = pUsuario
       and empresa = wEmpresa;

       if ( vuser_limit is not null or vuser_limit <> '' ) then 
    -- // validación adicional para reconocimiento de canal 120612
        IF (vuser_limit = "intercar") then
            select id_transacc, id_canal
              into vid_transacc, vid_canal
              from bdinteg:"informix".si_transacc_limites
             where transacc = pNumTrans
               and sistema = '06'
               and empresa = wEmpresa;
         ELSE
          SELECT id_canal 
          into vid_canal
             from bdinteg:si_canales
          where cc_canal = psucursal;
         
            select id_transacc, id_canal
              into vid_transacc, vid_canal
              from bdinteg:"informix".si_transacc_limites
             where transacc = pNumTrans
               and sistema = '06'
               and empresa = wEmpresa
                and id_canal = vid_canal;
         END IF;         


            if (vid_transacc is not null or vid_transacc <> '') then
-- RQI 01 050 Ajuste envío de mensajes JOM INI
-- Se agrega el parametro de tarjeta
                execute procedure bdinteg:"informix".sp_limite_max(vnum_cliente, pNumCredito, vid_transacc, vid_canal, FechaHoy, pMonto,pTarjeta)
-- RQI 01 050 Ajuste envío de mensajes JOM FIN
                into vcodret, vmsje_limites, vid_autor;

                if (vcodret = '00035') then
                     LET cod_ret = "035";
                     RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                            cod_ret2, pComNumTran, FechaHoy, SaldoCom, pComMonto;

                end if;
            end if;
        end if;

--validacion de limites jom ini

   -- ***********************************
   -- Determina Total de la Transaccion *
   -- ***********************************
   LET MtoTot =pMonto + pMonto2 + pComMonto + pComCashMonto + vMtoComDisp + Iva;
   LET TotComision = pComMonto + pComCashMonto + vMtoComDisp + Iva;
   LET SaldoCom = Saldo - TotComision;

   -- *************************************************************************
   -- *         Afecta Movimiento(s) de Cargo y Comision Respectivamente      *
   -- *************************************************************************

   -- ******************************************************
   -- Afecta Movto(s) de Disposicion en Cajeros y/o Compra *
   -- ******************************************************
   LET vMtoFavor= pMonto - vMtoPaso;

   IF pDivisa <> v_mn THEN
    	LET v_mtofavor_dlls =  vMtoFavor / v_tipocambio;
    else
        LET v_mtofavor_dlls = 0;
    end if;

   IF vMtoFavor > 0 THEN
        EXECUTE PROCEDURE "informix".cargo_cred(wEmpresa, pNumCredito, pSucursal,
                         pUsuario, pNumTranFavor, vMtoFavor, pFolio,
                         pTarjeta, v_mtofavor_dlls, v_tipocambio,
                         FechaHoy, pReferencia,"","")
        INTO cod_ret;

        IF cod_ret <> "000" THEN
            LET TotComision = 0;
            LET Saldo = 0;
            RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                   cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;

        END IF;
   END IF;

   IF vMtoPaso > 0 THEN
        EXECUTE PROCEDURE "informix".cargo_cred(wEmpresa, pNumCredito, pSucursal,
                         pUsuario, pNumTrans, vMtoPaso, pFolio,
                         pTarjeta, v_mto1_dlls, v_tipocambio,
                         FechaHoy, pReferencia,"","")
        INTO cod_ret;

        IF cod_ret <> "000" THEN
            LET TotComision = 0;
            LET Saldo = 0;
            RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                   cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;
        END IF;
   END IF;

   -- ***********************************************************
   -- Afecta Movimiento(s) por Comision de Disposicion o COmpra *
   -- ***********************************************************
   IF pComMonto > 0 THEN

-- jon ini mod surcharge
        if (pSurcharge = 'V') then
            if (pComNumTrans = '0857') then     -- red
                LET pComNumTrans = '0890';
            elif (pComNumTrans = '0858') then -- convenio
                LET pComNumTrans = '0891';
            elif (pComNumTrans = '0859') then -- internacional
                LET pComNumTrans = '0892';
            end if;
        end if;
-- jon fin mod surcharge

        EXECUTE PROCEDURE "informix".cargo_cred(wEmpresa, pNumCredito, pSucursal,
                                     pUsuario,pComNumTrans,pComMonto, pComFolio,
                                     pTarjeta, v_com1_dlls, v_tipocambio,
                                     FechaHoy, pComReferencia,"","")
        INTO cod_ret;

        IF cod_ret <> "000" THEN
            LET cod_ret2 = cod_ret;
                    LET TotComision = 0;
                    LET Saldo = 0;
                    RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                           cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;

        END IF
   END IF

   -- ********************************************
   -- Afecta Movto(s) de Disposicion en Comercio *
   -- ********************************************
   IF pMonto2 > 0 THEN

        EXECUTE PROCEDURE "informix".cargo_cred(wEmpresa, pNumCredito, pSucursal,
                                     pUsuario, pCashTranCen, pMonto2,pCashFolio,
                                     pTarjeta, v_mto2_dlls, v_tipocambio,
                                     FechaHoy, pReferencia,"","")
        INTO cod_ret;

        IF cod_ret <> "000" THEN
                LET TotComision = 0;
                LET Saldo = 0;
                RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                       cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;

        END IF

   END IF

   -- **************************************************************
   -- Afecta Movimiento(s) por Comision de Disposicion en Comercio *
   -- **************************************************************
   IF pComCashMonto > 0 THEN

        EXECUTE PROCEDURE "informix".cargo_cred(wEmpresa, pNumCredito, pSucursal,
                                     pUsuario,pComCashNumTrans, pComCashMonto,
				     pComCashFolio, pTarjeta, v_com2_dlls,
				     v_tipocambio, FechaHoy,
				     pComCashReferencia,"","")
        INTO cod_ret;

        IF cod_ret <> "000" THEN
		LET cod_ret2 = cod_ret;
                LET TotComision = 0;
                LET Saldo = 0;
                RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                       cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;

        END IF
   END IF

   -- **************************************************************
   -- Afecta Movimiento(s) por Comision de Disposicion de Efectivo *
   -- **************************************************************
   IF vMtoComDisp > 0 THEN

        EXECUTE PROCEDURE "informix".cargo_cred(wEmpresa, pNumCredito, pSucursal,
                                     pUsuario,v_codparam, vMtoComDisp,
                                     pFolio, pTarjeta, v_com2_dlls,
                                     v_tipocambio, FechaHoy,
                                     pComCashReferencia,"","")
        INTO cod_ret;

        IF cod_ret <> "000" THEN
                LET TotComision = 0;
                LET Saldo = 0;
                RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
                       cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;

        END IF
   END IF

   LET Saldo = Saldo - MtoTot;

-- jom ini -- Se elimina el iva del total comision
   if (pSurcharge = 'V' or vEscajero = '1') then
      LET TotComision = vMtoComDisp + vMtoComDisp_iva;      -- RRG Se modifica para el proyecto de circular 22/2010 comisiones ATM 26/10/2010
   else 
      LET TotComision = TotComision - Iva;
   end if;
-- jom fin

   RETURN cod_ret, pNumTran, FechaHoy, Saldo, MtoTot,
	  cod_ret2, pComNumTran, FechaHoy, SaldoCom, TotComision;


END PROCEDURE
