CREATE PROCEDURE "informix".sp_con_sc_movhis(  pFecha DATE )
RETURNING CHAR(5),integer,integer,integer,decimal(18,2),integer,decimal(18,2);
--,CODIGO DE ERROR SQL
--,NUMERO DE CONTRATOS ATM CAPTACION PERSONAS FISICAS
--,NUMERO DE CONTRATMOS ATM CAPTACION PERSONAS MORALES
--,NUMERO DE OPERACIONES ATM CAPTACION PERSONAS FISICAS
--,NUMERO DE OPERACIONES ATM CAPTACION PERSONAS FISICAS MONTO
--,NUMERO OPERACIONES CAPTACION PERSONAS MORALES,NUMERO OPERACIONES CAPTACION PERSONAS MORALES MONTO

	--Variables Exception
	DEFINE vcodret          CHAR(5);
	DEFINE vsqlerr,visamerr INTEGER; 


	DEFINE v_imes1								INTEGER;	
	DEFINE v_imes2								INTEGER;	
	DEFINE v_imes3								INTEGER;	
	DEFINE v_ivano1								INTEGER;
	
	DEFINE v_CON_ATMCAPF                        INTEGER;
	DEFINE v_CON_ATMCAPM						INTEGER;
	DEFINE v_OPE_ATMCAPF						INTEGER;
	DEFINE v_MONTO_TOT1							DECIMAL(18,2);	
	DEFINE v_OPE_ATMCAPM						INTEGER;
	DEFINE v_MONTO_TOT2							DECIMAL(18,2);

	--SET ISOLATION TO DIRTY READ;
	--SET LOCK MODE TO WAIT 3;
	
	LET v_imes1    	   = 0;		
	LET v_imes2		   = 0;	
	LET v_imes3        = MONTH(pFecha);		
	LET vcodret        = "000";
	LET v_CON_ATMCAPF  =0;
	LET v_CON_ATMCAPM  =0;
	LET v_OPE_ATMCAPF  =0;
	LET v_MONTO_TOT1   =0;	
	LET v_OPE_ATMCAPM  =0;
	LET v_MONTO_TOT2   =0;		
	
	BEGIN
    ON EXCEPTION SET vsqlerr,visamerr
    IF vsqlerr != 0 THEN
      LET vcodret=vsqlerr;
      RETURN vcodret,v_CON_ATMCAPF,v_CON_ATMCAPM,v_OPE_ATMCAPF,v_MONTO_TOT1,v_OPE_ATMCAPM ,v_MONTO_TOT2;	
    END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/tmp/sp_con_sc_movhis.out";
	--TRACE ON;
	
	
	
	
		IF v_imes3 = 1 THEN 
		  LET v_ivano1 = YEAR(pFecha);	
		  LET v_ivano1 =  v_ivano1 -1; 
		  LET v_imes1 = 11;		
		  LET v_imes2 = 12;
		ELIF v_imes3 = 2 THEN
		  LET v_ivano1 = YEAR(pFecha);	
		  LET v_ivano1 =  v_ivano1 -1; 		                             
		 LET v_imes1 = 12;
         LET v_imes2 = 01;		  
		ELIF (v_imes3 != 1 AND v_imes3 != 2) THEN
	      LET v_ivano1 = YEAR(pFecha);	
		  LET v_imes1 = v_imes3 - 2;		
		  LET v_imes2 = v_imes3 -1 ;
		END IF;  
	
	
			--2.0 3.0 OBTIENE LOS CLIENTES TIPO MORALES Y SUS CUENTA EN CAPTACION
			SELECT NVL(cl.numcte,'') as numcte,NVL(cuenta,'') as cuenta,NVL(razon_social,0) as razon_social,NVL(rfc,0) as rfc
			  FROM bdinteg:si_cliente cl LEFT JOIN bdicheq:sc_maechq ma 
                ON ma.num_cte = cl.numcte                  
			 WHERE cl.empresa = '001'
			   AND tpo_persona = 2
			  INTO temp tmp_clienteCAPM
			  WITH NO LOG;	  
			
			--cliente fisicos.
			SELECT count(*) 
			  INTO v_CON_ATMCAPF	
			  FROM bdicheq:SC_maechq
			 WHERE  fec_ult_mov IS NOT NULL
			   AND cuenta IS NOT NULL
			   AND producto <> 1100
			   AND status_cta <> 2
			   AND status_cta <> 6
			   AND num_cte NOT IN (SELECT numcte FROM tmp_clienteCAPM WHERE cuenta <> '');	

			--clientes morales. 
		    SELECT count(*) 
			  INTO v_CON_ATMCAPM	
			  FROM bdicheq:SC_maechq
			 WHERE fec_ult_mov IS NOT NULL
			   AND cuenta IS NOT NULL
			   AND producto <> 1100
			   AND status_cta <> 2
			   AND status_cta <> 6			   
			   AND num_cte IN (SELECT numcte FROM tmp_clienteCAPM WHERE cuenta <> '');				 
			    
			SELECT  {bdicred:sc_movhis informix.idx_movhisnew3}
					cuenta,fech_alt,cancelad,transacc,usuario,folio_suc,monto_tot
			  FROM bdicheq:sc_movhis a
             WHERE  a.transacc IN ('0871','0873','0800','0893')	              		
			UNION 
			SELECT {bdicred:sc_movhis_old informix.idxmovhistranspba}
					cuenta,fech_alt,cancelad,transacc,usuario,folio_suc,monto_tot		 
			  FROM bdicheq:sc_movhis_old a
             WHERE  a.transacc IN ('0871','0873','0800','0893')	                     
			INTO TEMP tmp_sc_movhis_old
			WITH NO LOG;
			
		CREATE INDEX informix.idx01tmp_sc_movhis_old ON informix.tmp_sc_movhis_old(fech_alt,cuenta,cancelad,usuario,folio_suc);
	
	
		-- MOVMIENTOS ATM CAPTCION PERSONAS FISICAS
		SELECT count(*),SUM(monto_tot)
		  INTO v_OPE_ATMCAPF,v_MONTO_TOT1
		  FROM tmp_sc_movhis_old
		 WHERE fech_alt BETWEEN  MDY(v_imes1,'01',v_ivano1) AND  pFecha
		   AND cuenta NOT IN  (SELECT cuenta FROM tmp_clienteCAPM WHERE cuenta <> '')
		   AND cancelad <> 'S'
		   AND usuario in ('intercar','sysconau')   		
		   AND folio_suc like ('i%') ;   	
	
		-- MOVIMIENTOS ATM CAPTACION PERSONAS MORALES			 
  		SELECT count(*),SUM(monto_tot) 
		  INTO v_OPE_ATMCAPM,v_MONTO_TOT2
		  FROM tmp_sc_movhis_old
		 WHERE fech_alt    BETWEEN  MDY(v_imes1,'01',v_ivano1) AND  pFecha
		   AND cuenta      IN  (SELECT cuenta FROM tmp_clienteCAPM WHERE cuenta <> '')
		   AND cancelad    <> 'S'
		   AND usuario in ('intercar','sysconau')   		
		   AND folio_suc like ('i%') ;   

		RETURN vcodret,v_CON_ATMCAPF,v_CON_ATMCAPM,v_OPE_ATMCAPF,v_MONTO_TOT1,v_OPE_ATMCAPM ,v_MONTO_TOT2;	
		DROP TABLE tmp_clienteCAPM;
	END  
END PROCEDURE;

CREATE PROCEDURE "informix".sp_activacuentas( pEmpresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;

    DEFINE cCodRet1         CHAR(5);
    DEFINE cCodRet2         CHAR(5);
    DEFINE cCodRet3         CHAR(50);
    DEFINE iSqlErr          INTEGER;
    DEFINE iIsamErr         INTEGER;
    DEFINE cDescErr         CHAR(50);
    DEFINE iContador1       INTEGER;
    DEFINE iContador2       INTEGER;
    DEFINE cTransacAbierta  CHAR(1);
    DEFINE cSql             CHAR(500);
    DEFINE cStmt            CHAR(250);
    DEFINE dFechaHoy        DATE;
    DEFINE cCuenta          CHAR(20);
    
    LET cCodRet1        = '';
    LET cCodRet2        = '';
    LET cCodRet3        = '';
    LET iSqlErr	        = 0;
    LET iIsamErr        = 0;
    LET cDescErr        = '';
    LET iContador1      = 0;
    LET iContador2      = 0;
    LET cTransacAbierta = '0';
    LET cSql            = '';
    LET cStmt           = '';
    LET dFechaHoy       = '';
    LET cCuenta         = '';
    
    BEGIN

    ON EXCEPTION SET iSqlErr, iIsamErr, cDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_activacuentas.err";
        TRACE ON;
        IF iSqlErr <> 0 THEN
            LET cCodRet1 = iSqlErr;
            LET cCodRet2 = iIsamErr;
            LET cCodRet3 = cDescErr;
            IF cTransacAbierta = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN cCodRet1, cCodRet2, cCodRet3, iContador1, iContador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_activacuentas.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxactivar') THEN
        DROP TABLE "informix".ctasxactivar;
    END IF;
    
    CREATE TABLE "informix".ctasxactivar
        ( 
            cuenta CHAR(20) NOT NULL 
        )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctaxactiv ON "informix".ctasxactivar(cuenta) ONLINE;
      
    LET cSql = 'echo "LOAD FROM /resplogifx/conciliachq/cuentasxactivar.unl INSERT INTO ctasxactivar" > /resplogifx/conciliachq/ctasxact.sql';
    SYSTEM cSql;
    LET cSql = '';
    
    LET cStmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasxact.sql';
    SYSTEM cStmt;
    LET cStmt = '';
    
    UPDATE STATISTICS HIGH FOR TABLE ctasxactivar;
    
    SELECT fecha_hoy
      INTO dFechaHoy
      FROM sc_fechas
     WHERE empresa = pEmpresa;
    
    FOREACH WITH HOLD
        SELECT cuenta
          INTO cCuenta
          FROM ctasxactivar
        
        BEGIN WORK;
        LET cTransacAbierta = '1'; 
        LET iContador1 = iContador1 + 1;
        
        UPDATE sc_maechq
           SET status_cta = '1',
               fecha_proceso = dFechaHoy,
               num_cgos_mes = 0,
               imp_cgos_mes = 0.00,
               num_abonos_mes = 0,
               imp_abonos_mes = 0.00
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta;
           
        UPDATE sc_maenoc
           SET dia_sdo_pos = 0,
               acum_sdo_pos = 0.00,
               int_acum = 0.00,
               dias_acum_int = 0,
               acum_sdo_int = 0.00
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            COMMIT WORK;
            LET iContador2 = iContador2 + 1;
        ELSE 
            ROLLBACK WORK;
        END IF;
        
        LET cCuenta = '';
        LET cTransacAbierta = '0';
    END FOREACH;
    
    LET cCodRet1 = '000';
    LET cCodRet2 = '000';
    LET cCodRet3 = 'PROCESO FINALIZADO CORRECTAMENTE';
    
    END;

    RETURN cCodRet1, cCodRet2, cCodRet3, iContador1, iContador2;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_reportevencinvcrecconcta3anios( pSucursal CHAR(4), pRegistro INTEGER )
RETURNING CHAR(5)     AS RETORNO,			
          CHAR(60)    AS MENSAJE,		    
          CHAR(4)     AS SUCURSAL,	
          CHAR(8)     AS PROMOTOR,		          
          CHAR(9)     AS NUMEROCLIENTE,	
          CHAR(104)   AS NOMBRECLIENTE,
          CHAR(20)    AS CUENTA,	
          CHAR(20)    AS CUENTAEJE,
          DATE        AS FECHAAPERTURA,		
          DATE        AS FECHAVENCIMIENTO, 
          CHAR(15)    AS TELEFONO1,
          CHAR(15)    AS TELEFONO2,
          CHAR(15)    AS TELEFONO3,
          CHAR(5)     AS EXTENSION,
          CHAR(50)    AS CORREOELECT; 
    
    DEFINE vSqlError 			SMALLINT;
    DEFINE vIsamError 			SMALLINT;
    DEFINE vDescError 			CHAR(50);
    DEFINE cCodRet  			CHAR(5);
    DEFINE cCodRet2  			CHAR(5);
    DEFINE cCodRet3  			CHAR(50);
    DEFINE cMensaje 			CHAR (60);
    DEFINE dFechaHoy  			DATE;
    DEFINE cSucursal 			CHAR(4);
    DEFINE cPromotor 			CHAR(8);
    DEFINE cNumCte				CHAR(9);
    DEFINE cNombreCte           CHAR(104);
    DEFINE cCuenta 				CHAR(20);
    DEFINE cCuentaEje           CHAR(20);
    DEFINE dFecha_apertura 		DATE;
    DEFINE dFecha_vencimiento 	DATE;
    DEFINE cTelefono1           CHAR(15);
    DEFINE cTelefono2           CHAR(15);
    DEFINE cTelefono3           CHAR(15);
    DEFINE cExtension           CHAR(5);
    DEFINE cMail                CHAR(50);
    DEFINE vciclo				SMALLINT;
    
    LET vSqlError		   = 0;
    LET vIsamError		   = 0;
    LET vDescError		   = '';
    LET cCodRet			   = '00000';
    LET cCodRet2		   = '';
    LET cCodRet3		   = '';
    LET cMensaje 		   = 'EL PROCESO SE EJECUTO EXITOSAMENTE';
    LET dFechaHoy 		   = '01-01-1900';
    LET cSucursal		   = "";
    LET cPromotor		   = "";
    LET cNumCte			   = "";
    LET cNombreCte         = "";
    LET cCuenta			   = "";
    LET cCuentaEje         = "";
    LET dFecha_apertura	   = '01-01-1900';
    LET dFecha_vencimiento = '01-01-1900';
    LET cTelefono1         = "";
    LET cTelefono2         = "";
    LET cTelefono3         = "";
    LET cExtension         = "";
    LET cMail              = "";
    LET vciclo			   = 0;
    
    BEGIN
    
    ON EXCEPTION SET vSqlError, vIsamError, vDescError
        SET debug file to "/tmp/sp_reportevencinvcrecconcta3anios.err";
        trace on;
        IF vSqlError <> 0 THEN
            LET cCodRet = vSqlError;
            LET cCodRet2 = vIsamError;
            LET cCodRet3 = vDescError;
            LET cMensaje = 'Ocurrio un Error Durante La Ejecucion Del Procedimiento';
            RETURN cCodRet, cMensaje, cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, 
                   dFecha_vencimiento, cTelefono1, cTelefono2, cTelefono3, cExtension, cMail WITH RESUME;
        END IF;
    END EXCEPTION;
    
    --- SET debug file to "/tmp/sp_reportevencinvcrecconcta3anios.out";
    --- trace on;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF NOT EXISTS( SELECT sucursal FROM bdinteg:si_sucursales where sucursal= pSucursal ) THEN
        LET cCodRet = '00001';
        LET cMensaje = 'La Sucursal No Existe';
    ELSE
        -- // Obtener  fecha  de hoy
        SELECT fecha_hoy 
          INTO dFechaHoy 
          FROM bdicheq:sc_fechas;
        
        -- // Obtiene los datos de las sucursales, regresa sus valores y los ordena por sucursal
        FOREACH WITH HOLD
            SELECT sucursal, promotor, TRIM(numcte), TRIM(nombre_cte), TRIM(numcta), TRIM(cta_eje), NVL(fecha_apertura,' '), NVL(fecha_vencimiento,' '), 
                   TRIM(NVL(telefono1,' ')), TRIM(NVL(telefono2,' ')), TRIM(NVL(telefono3,' ')), TRIM(NVL(extension,' ')), TRIM(NVL(correo_elect,' '))
              INTO cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, dFecha_vencimiento,
                   cTelefono1, cTelefono2, cTelefono3, cExtension, cMail
              FROM bdicheq:sc_invcrecconcta3anios
             WHERE sucursal = pSucursal 
               AND fecha_vencimiento >= dFechaHoy 
             ORDER BY fecha_vencimiento ASC, promotor ASC, numcta ASC
        
            LET vCiclo = vCiclo + 1;
        
            -- // Paginacion
            IF vciclo <= pRegistro THEN
                CONTINUE FOREACH;
            END IF; 
        
            RETURN cCodRet, cMensaje, cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, 
                   dFecha_vencimiento, cTelefono1, cTelefono2, cTelefono3, cExtension, cMail WITH RESUME;
        END FOREACH;
    
        IF vciclo = 0 THEN
            LET cCodRet = '00002';
            LET cMensaje = 'No Se Encontraron Datos';
        END IF;
    END IF;
    
    IF cCodRet <> '00000' THEN
        RETURN cCodRet, cMensaje, cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, 
               dFecha_vencimiento, cTelefono1, cTelefono2, cTelefono3, cExtension, cMail WITH RESUME;
    END IF;
    
    END;
    
END PROCEDURE;

