CREATE PROCEDURE "informix".sp_reportevencpagares3anios( pSucursal CHAR(4), pRegistro INTEGER )
RETURNING CHAR(5)     AS RETORNO,			
          CHAR(60)    AS MENSAJE,		    
          CHAR(4)     AS SUCURSAL,	
          CHAR(8)     AS PROMOTOR,		          
          CHAR(9)     AS NUMEROCLIENTE,	
          CHAR(104)   AS NOMBRECLIENTE,
          CHAR(20)    AS CUENTA,
          CHAR(20)    AS CUENTAEJE,
          DATE        AS FECHAAPERTURA,		
          DATE        AS FECHAVENCIMIENTO, 
          CHAR(15)    AS TELEFONO1,
          CHAR(15)    AS TELEFONO2,
          CHAR(15)    AS TELEFONO3,
          CHAR(5)     AS EXTENSION,
          CHAR(50)    AS CORREOELECT;
    
    DEFINE vSqlError 			SMALLINT;
    DEFINE vIsamError 			SMALLINT;
    DEFINE vDescError 			CHAR(50);
    DEFINE cCodRet  			CHAR(5);
    DEFINE cCodRet2  			CHAR(5);
    DEFINE cCodRet3  			CHAR(50);
    DEFINE cMensaje 			CHAR (60);
    DEFINE dFechaHoy  			DATE;
    DEFINE cSucursal 			CHAR(4);
    DEFINE cPromotor 			CHAR(8);
    DEFINE cNumCte				CHAR(9);
    DEFINE cNombreCte           CHAR(104);
    DEFINE cCuenta 				CHAR(20);
    DEFINE cCuentaEje           CHAR(20);
    DEFINE dFecha_apertura 		DATE;
    DEFINE dFecha_vencimiento 	DATE;
    DEFINE cTelefono1           CHAR(15);
    DEFINE cTelefono2           CHAR(15);
    DEFINE cTelefono3           CHAR(15);
    DEFINE cExtension           CHAR(5);
    DEFINE cMail                CHAR(50);
    DEFINE vciclo				SMALLINT;
    
    LET vSqlError		   = 0;
    LET vIsamError		   = 0;
    LET vDescError		   = '';
    LET cCodRet			   = '00000';
    LET cCodRet2		   = '';
    LET cCodRet3		   = '';
    LET cMensaje 		   = 'EL PROCESO SE EJECUTO EXITOSAMENTE';
    LET dFechaHoy 		   = '01-01-1900';
    LET cSucursal		   = "";
    LET cPromotor		   = "";
    LET cNumCte			   = "";
    LET cNombreCte         = "";
    LET cCuenta			   = "";
    LET cCuentaEje         = "";
    LET dFecha_apertura	   = '01-01-1900';
    LET dFecha_vencimiento = '01-01-1900';
    LET cTelefono1         = "";
    LET cTelefono2         = "";
    LET cTelefono3         = "";
    LET cExtension         = "";
    LET cMail              = "";
    LET vciclo			   = 0;
    
    BEGIN
    
    ON EXCEPTION SET vSqlError, vIsamError, vDescError
        SET debug file to "/tmp/sp_reportevencpagares3anios.err";
        trace on;
        IF vSqlError <> 0 THEN
            LET cCodRet = vSqlError;
            LET cCodRet2 = vIsamError;
            LET cCodRet3 = vDescError;
            LET cMensaje = 'Ocurrio un Error Durante La Ejecucion Del Procedimiento';
            RETURN cCodRet, cMensaje, cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, 
                   dFecha_vencimiento, cTelefono1, cTelefono2, cTelefono3, cExtension, cMail WITH RESUME;
        END IF;
    END EXCEPTION;
    
    --- SET debug file to "/tmp/sp_reportevencpagares3anios.out";
    --- trace on;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF NOT EXISTS( SELECT sucursal FROM bdinteg:si_sucursales where sucursal= pSucursal ) THEN
        LET cCodRet = '00001';
        LET cMensaje = 'La Sucursal No Existe';
    ELSE
        -- // Obtener  fecha  de hoy
        SELECT fecha_hoy 
          INTO dFechaHoy 
          FROM bdicheq:sc_fechas;
        
        -- // Obtiene los datos de las sucursales, regresa sus valores y los ordena por sucursal
        FOREACH WITH HOLD
            SELECT sucursal, promotor, TRIM(numcte), TRIM(nombre_cte), TRIM(numcta), TRIM(cta_eje), NVL(fecha_apertura,' '), NVL(fecha_vencimiento,' '), 
                   TRIM(NVL(telefono1,' ')), TRIM(NVL(telefono2,' ')), TRIM(NVL(telefono3,' ')), TRIM(NVL(extension,' ')), TRIM(NVL(correo_elect,' '))
              INTO cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, dFecha_vencimiento,
                   cTelefono1, cTelefono2, cTelefono3, cExtension, cMail
              FROM bdicheq:sc_pagares3anios
             WHERE sucursal = pSucursal 
               AND fecha_vencimiento >= dFechaHoy 
             ORDER BY fecha_vencimiento ASC, promotor ASC, numcta ASC
            
            LET vCiclo = vCiclo + 1;
            
            -- // Paginacion
            IF vciclo <= pRegistro THEN
                CONTINUE FOREACH;
            END IF; 
            
            RETURN cCodRet, cMensaje, cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, 
                   dFecha_vencimiento, cTelefono1, cTelefono2, cTelefono3, cExtension, cMail WITH RESUME;
        END FOREACH;
    
        IF vciclo = 0 THEN
            LET cCodRet = '00002';
            LET cMensaje = 'No Se Encontraron Datos';
        END IF;
    END IF;
    
    IF cCodRet <> '00000' THEN
        RETURN cCodRet, cMensaje, cSucursal, cPromotor, cNumCte, cNombreCte, cCuenta, cCuentaEje, dFecha_apertura, 
               dFecha_vencimiento, cTelefono1, cTelefono2, cTelefono3, cExtension, cMail WITH RESUME;
    END IF;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtienenomctesufijo
(
pNumCte CHAR(20)
)
RETURNING
	CHAR(6) 		AS cod_ret,
	CHAR(80) 		AS descripcion,
	CHAR(168) 		AS nomcte_sufijo;

	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);
    DEFINE cMensajeRet		CHAR(80);
	DEFINE cNomCteSufijo	CHAR(168);
	DEFINE cNombrecte		CHAR(107);
	DEFINE cSufijo			CHAR(60);
	


	
	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
	LET cCodRet				= "000000";
	LET cMensajeRet			= "PROCESO EXITOSO";
	LET cNomCteSufijo			= "";
	LET cNombrecte		= "";
	LET  cSufijo			= "";

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN cCodRet,cMensajeRet,cNomCteSufijo;
       END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/respaldosbd/has/sp_obtienenomctesufijo.out';
	--TRACE ON;
	
	select descripcion 
	into cSufijo
	from bdinteg:si_ctepm t1,  bdinteg:si_sufijos t2 
	where t1.numcte = pNumCte
	and t1.sufijo = t2.codigo;
	
	LET cSufijo = NVL(cSufijo,"");
	
	select limit 1 nombrecliente
	into cNombrecte
	from bdicheq: vedocta
	where numerocliente = pNumCte;
	
	LET cNombrecte = NVL(cNombrecte,"");
	
	LET cNomCteSufijo = TRIM(cNombrecte) || " " || TRIM(cSufijo);
	
	RETURN cCodRet,cMensajeRet,cNomCteSufijo;
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener le nombre dle cliente y la descripcion del sufijo perteneciente a su clave', 
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Noviembre 2012',
'VERSION: 20121126.1523';

CREATE PROCEDURE "informix".reptarjetacredpago(psucursal char(4),
                                               pfecini char(10),
                                               pfecfin char(10))
RETURNING CHAR(5),char(20), char(20), char(20), money, char(4), date, char(30), char(40);

DEFINE vsqlerr        int;
DEFINE vcodret        CHAR(5);
DEFINE vnum_tarjeta   CHAR(20);
DEFINE vnumcte        CHAR(20);
DEFINE vstatus        CHAR(1);
DEFINE vdescripcion   CHAR(20);
DEFINE vsucursal      CHAR(4);
DEFINE vmonto         MONEY;
DEFINE vfecha         date;
DEFINE vnomempresa    CHAR(30);
DEFINE vnomsuc        CHAR(40);


begin
   --SET DEBUG FILE TO "/tmp/reptarjetacredpago.out";
   --TRACE ON;

   on exception set vsqlerr
      if vsqlerr <> 0  then
         let vcodret = vsqlerr;
        RETURN vcodret,'', '', '', 0, '',null,'','';
      end if;
   end exception;

-- Inicializa variables
   LET vcodret        = "000";
   LET vnum_tarjeta   = "";
   LET vnumcte        = "";
   LET vstatus        = "";
   LET vmonto         = 0;
   LET vsucursal      = '0000';
   LET vdescripcion   = '';
   LET vfecha         = current;

       FOREACH 
          SELECT tar.num_tarjeta, 
                 tar.numcte,
                 doc.cancelado,
                 doc.monto,
                 doc.sucursal,
                 doc.fecha_alta,
                 emp.razon_social,
                 suc.nombre
            INTO vnum_tarjeta,
                 vnumcte ,
                 vstatus ,
                 vmonto ,
                 vsucursal,
                 vfecha ,
                 vnomempresa,
                 vnomsuc
            FROM sc_docret doc, bdicred:sd_tarjeta tar, bdinteg:si_empresas emp,
                 bdinteg:si_sucursales suc
           WHERE doc.siglas = 'SD'
             AND doc.empresa = tar.empresa
             AND doc.cuenta = tar.num_tarjeta
             AND doc.sucursal = DECODE(length(psucursal),4,psucursal,doc.sucursal) 
             AND fecha_alta >= pfecini
             AND fecha_alta <= pfecfin
             AND doc.empresa = emp.empresa
             AND doc.sucursal = suc.sucursal
			UNION
          SELECT tar.num_tarjeta, 
                 tar.numcte,
                 doc.cancelado,
                 doc.monto,
                 doc.sucursal,
                 doc.fecha_alta,
                 emp.razon_social,
                 suc.nombre
            FROM sc_docret_sbc doc, bdicred:sd_tarjeta tar, bdinteg:si_empresas emp,
                 bdinteg:si_sucursales suc
           WHERE doc.siglas = 'SD'
             AND doc.empresa = tar.empresa
             AND doc.cuenta = tar.num_tarjeta
             AND doc.sucursal = DECODE(length(psucursal),4,psucursal,doc.sucursal) 
             AND fecha_alta >= pfecini
             AND fecha_alta <= pfecfin
             AND doc.empresa = emp.empresa
             AND doc.sucursal = suc.sucursal
			 UNION
          SELECT tar.num_tarjeta, 
                 tar.numcte,
                 doc.cancelado,
                 doc.monto,
                 doc.sucursal,
                 doc.fecha_alta,
                 emp.razon_social,
                 suc.nombre
            FROM sc_docret_pos doc, bdicred:sd_tarjeta tar, bdinteg:si_empresas emp,
                 bdinteg:si_sucursales suc
           WHERE doc.siglas = 'SD'
             AND doc.empresa = tar.empresa
             AND doc.cuenta = tar.num_tarjeta
             AND doc.sucursal = DECODE(length(psucursal),4,psucursal,doc.sucursal) 
             AND fecha_alta >= pfecini
             AND fecha_alta <= pfecfin
             AND doc.empresa = emp.empresa
             AND doc.sucursal = suc.sucursal
			 

           IF vstatus = 'S' THEN
              LET vdescripcion = 'CANCELADO'; 
           ELIF vstatus = 'D' THEN
              LET vdescripcion = 'DEVUELTO'; 
           ELIF vstatus = 'T' THEN
              LET vdescripcion = 'TRANSITO'; 
           ELIF vstatus = 'L' THEN
              LET vdescripcion = 'LIBERADO'; 
           ELSE
              LET vdescripcion = 'OTRO'; 
           END IF;
            
           RETURN vcodret,vnum_tarjeta, vnumcte, vdescripcion, vmonto, vsucursal, vfecha, vnomempresa, vnomsuc WITH RESUME;
       END FOREACH;

END
END procedure;

CREATE PROCEDURE "informix".sp_cce_consultarchequesmovs
(
pEmpresa    CHAR(3),
pFecha      CHAR(10)
)
RETURNING
	CHAR(6) 		AS cod_ret,
	CHAR(3) 		AS banco,
	CHAR(40) 		AS desc_banco,
	CHAR(40) 		AS referencia,
	INTEGER 		AS num_cheque,
	DECIMAL(14,2) 	AS monto_orig,
	DATE 			AS fecha_alta,
	DATETIME HOUR TO FRACTION(3) AS hora,
	CHAR(44) 		AS sucursal,
	SMALLINT 		AS dias_ret,
	CHAR(16) 		AS folio_suc,
	CHAR(4) 		AS transcc,
	CHAR(4) 		AS cve_suc

	
	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);
	
	DEFINE cBanco			CHAR(3);
	DEFINE cDescBanco		CHAR(40);
	DEFINE cReferencia		CHAR(40);
	DEFINE iNumcheque		INTEGER;
	DEFINE dMontoOrig		DECIMAL(14,2);
	DEFINE cFechaAlta		DATE;
	DEFINE cHora			DATETIME HOUR TO FRACTION(3);	
	DEFINE cSucursal		CHAR(44);
	DEFINE sDiasRet			SMALLINT;
	DEFINE cFolioSuc		CHAR(16);
	DEFINE cTransacc		CHAR(4);
	DEFINE cCveSucursal		CHAR(4);


	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
	
	LET cBanco				= "";
	LET cDescBanco			= "";
	LET cReferencia			= "";
	LET iNumcheque			= 0;
	LET dMontoOrig			= 0.0;
	LET cFechaAlta			= DATE(1);
	LET cHora				= CURRENT HOUR TO FRACTION(3);
	LET cSucursal			= "";
	LET sDiasRet			= 0;
	LET cFolioSuc			= "";
	LET cTransacc			= "";
	LET cCveSucursal		= "";



BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cBanco, cDescBanco, cReferencia, iNumcheque, dMontoOrig, cFechaAlta, cHora,
				cSucursal, sDiasRet, cFolioSuc, cTransacc, cCveSucursal;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
--	SET DEBUG FILE TO '/respaldosbd/has/sp_cce_consultarchequesmovs.out';
--	TRACE ON;


	IF NVL(pEmpresa,"") = "" OR NVL(pFecha,"") = "" THEN
        -- FALTA EMPRESA O FECHA
        LET cCodRet = "000001";
        RETURN cCodRet, cBanco, cDescBanco, cReferencia, iNumcheque, dMontoOrig, cFechaAlta, cHora,
			cSucursal, sDiasRet, cFolioSuc, cTransacc, cCveSucursal;
	ELSE
        FOREACH WITH HOLD
			SELECT UNIQUE ba.banco, ba.descripcion, doc.referencia, doc.num_chq, doc.monto_ori, doc.fecha_alta, doc.fech_hor,
			suc.sucursal || " " || suc.nombre, doc.dias_ret, doc.folio_suc, doc.transacc, suc.sucursal
			INTO cBanco, cDescBanco, cReferencia, iNumcheque, dMontoOrig, cFechaAlta, cHora,
			cSucursal, sDiasRet, cFolioSuc, cTransacc, cCveSucursal
			FROM bdicheq:sc_docret_sbc doc, bdinteg:si_bancos ba, bdinteg:si_sucursales suc 
			WHERE doc.empresa = pEmpresa
			AND doc.banco = ba.banco 
			AND doc.sucursal = suc.sucursal 
			AND doc.transacc IN (SELECT transacc FROM bditef:cce_mapeo_cecoban) 
			AND doc.cancelado = "T"
			AND doc.fecha_alta = pFecha
			ORDER BY doc.fecha_alta, doc.fech_hor

			RETURN cCodRet, cBanco, cDescBanco, cReferencia, iNumcheque, dMontoOrig, cFechaAlta, cHora,
				cSucursal, sDiasRet, cFolioSuc, cTransacc, cCveSucursal WITH RESUME;
        END FOREACH 	
    
	END IF
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso que consulta los datos de los cheques del catalogo de documentos de cheques',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Octubre 2012',
'VERSION: 20121026.1305';

CREATE PROCEDURE "informix".sp_borrar_sc_docret
( 
)
RETURNING 
	CHAR(5), 
	CHAR(5), 
	CHAR(50), 
	INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vempieza         SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vCuenta CHAR(20);
    DEFINE vmin_serial      INTEGER;
    DEFINE vmax_serial      INTEGER;
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO REALIZADO SATISFACTORIAMENTE';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vempieza     = -1;
    LET ven_transacc = 0; 
    
    LET vCuenta = "";
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_borrar_sc_docret.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_borrar_sc_docret.out";
    --- TRACE ON;
    
    set optimization high;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH cursor_borra WITH HOLD FOR
		SELECT UNIQUE cuenta
		INTO vCuenta
		FROM sc_docret
		WHERE siglas IN ('SC','SD')
		AND transacc IN ('0250','6250')
           
        IF vempieza = -1 THEN
            LET vempieza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        DELETE FROM sc_docret 
        WHERE cuenta = vCuenta
		AND siglas IN ('SC','SD')
		AND transacc IN ('0250','6250');
         
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;
        
        IF vcontador2 >= 5000 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        COMMIT WORK;
        LET vcontador2 = 0;
        LET ven_transacc = 0;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_reportesbc(vEmpresa char(3),vfechareporte char(10))
RETURNING CHAR(3)AS vcod_ret, CHAR(20)AS vcuenta, CHAR(4)AS vsucursal, DATE AS vfecha_alta,CHAR(4)AS vtransacc,CHAR(40)AS vreferencia, INTEGER AS vnum_chq,
SMALLINT AS vdias_ori, MONEY(14,2) AS vmonto_ori,           CHAR(2)AS vsiglas,CHAR (40) AS vBanco, char (10) AS vfecharep;
--**********************************************************************
--*    sp_reporteSBC                                                   *
--*    Version              1.0.0                                      *
--*    Objetivo:            Obtener el reporte de la liberacion SBC    *
--*    Supuestos:           Ninguno                                    *
--*    Creado por:          Edith Rodríguez Arellano                   *
--*    ModIFicado por:                                                 *
--*    Ultima Modificacion: Enero - 2009                               *
--*                         Creación de SPL                            *
--*    Modificado por JYDG de dia.codigo_fun = '033' a '336'           *
--**********************************************************************
DEFINE vcod_ret CHAR(3);
DEFINE sql_err  integer;
DEFINE vcuenta  CHAR(20);
DEFINE vsucursal CHAR(4);  
DEFINE vfecha_alta DATE;
DEFINE vtransacc CHAR(4);
DEFINE vreferencia CHAR(40);
DEFINE vnum_chq INTEGER;
DEFINE vdias_ori SMALLINT;
DEFINE vmonto_ori MONEY(14,2);
DEFINE vsiglas CHAR(2);
DEFINE vtranlibsbc CHAR(4); 
DEFINE vtranlibctadev CHAR(4);
DEFINE vtranlibsbcTC CHAR(4);
DEFINE vBanco CHAR(40); 
DEFINE vfecharep char(10);
BEGIN   
on exception set sql_err      
if sql_err <> 0 then         
let vcod_ret = sql_err;        
return vcod_ret,null,null,null,null,null,null,null,null,null,null,null;
end if;   
end exception;  
--SET DEBUG FILE TO "/tmp/sp_reporteSBC.out";  
--TRACE ON;  
LET vcod_ret ='000';
LET vtranlibsbc = "0000";
LET vtranlibctadev = "0000";
LET vtranlibsbcTC = "0000";
LET vfecharep=vfechareporte;   
select valor 
into vtranlibsbc     
from sc_param    
where empresa = vEmpresa 
and codparam = "tranlibsbc";   
select valor 
into vtranlibctadev     
from sc_param    
where empresa = vEmpresa 
and codparam = "tranlibctadev";   
select valor 
into vtranlibsbcTC     
from bdicred:sd_param    
where empresa = vEmpresa 
and cod_param = "83";   
FOREACH            
SELECT ret.cuenta,ret.sucursal,ret.fecha_alta,ret.transacc,ret.referencia,ret.num_chq,ret.dias_ori,ret.monto_ori,ret.siglas,ban.descripcion        
INTO vcuenta,vsucursal,vfecha_alta,vtransacc,vreferencia,vnum_chq,vdias_ori,vmonto_ori,vsiglas,vBanco          
FROM sc_movdia dia, sc_docret_sbc ret, bdinteg:si_bancos ban       
WHERE dia.cuenta=ret.cuenta         
AND dia.empresa=ret.empresa         
AND dia.monto_tot=ret.monto_ori         
AND dia.num_cheq=ret.num_chq         
AND dia.folio_suc=ret.folio_suc         
AND (dia.transacc = vtranlibsbc 
OR dia.transacc = vtranlibctadev OR dia.transacc = vtranlibsbcTC )          
AND ret.cancelado='L'         
AND ret.siglas='SC'         
AND ban.banco= ret.referencia[1,3]    
UNION      
SELECT ret.cuenta,ret.sucursal,ret.fecha_alta, ret.transacc,ret.referencia,ret.num_chq, ret.dias_ori,ret.monto_ori,ret.siglas, ban.descripcion        
FROM bdicred:sd_movdia dia, sc_docret_sbc ret, bdicred:sd_tarjeta tar, bdinteg:si_bancos ban        
WHERE tar.num_tarjeta = ret.cuenta         
AND dia.num_credito = tar.num_credito                
AND dia.empresa = ret.empresa         
AND dia.monto = ret.monto_ori              
AND dia.folio_suc[1,14] = ret.folio_suc[1,14]         
AND dia.codigo_fun = '336'         
AND dia.codigo_ref = 1         
AND ret.cancelado = 'L'         
AND ret.siglas = 'SD'         
AND ban.banco = ret.referencia[1,3]           
RETURN vcod_ret,vcuenta,vsucursal, vfecha_alta,vtransacc,vreferencia, vnum_chq,vdias_ori,vmonto_ori, vsiglas,vBanco,vfecharep WITH RESUME;   
END FOREACH;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consula_cta_activa(pCuenta CHAR(20))
   returning char(5);

    -- Creado por: Mauricio Leon
    -- Actividad:  Consulta la existencia y el estatus activo de una cuenta
    -- Solicito:   Ismael Hernandez
    -- Fecha:      23/09/2011

    -- Define variables
    DEFINE cod_ret char(5);
    DEFINE sql_err integer ;
    DEFINE vCont smallint;

    -- Inicializa variables
    LET cod_ret  = "000";
    LET vCont = 0;

    BEGIN

        ON EXCEPTION SET sql_err
            IF sql_err <> 0 THEN
                let cod_ret = sql_err;
                RETURN cod_ret;
            END IF ;
        END EXCEPTION ;

		SET LOCK MODE TO WAIT 3;
		SET ISOLATION DIRTY READ ;

        SELECT count(*) INTO vCont FROM bdicheq:"informix".sc_maechq WHERE cuenta = pCuenta AND status_cta <> 2;

        IF vCont = 0 THEN
            LET cod_ret = '001';
        END IF ;

		RETURN cod_ret;

    END
END PROCEDURE
;

CREATE PROCEDURE "informix".sp_actparampasecheqhis(pempresa CHAR(3), pfecha DATE)
RETURNING CHAR(5);
    
    --- ################################################################################
    --- ##  Nombre:              sp_actparampasecheqhis                                  ##
    --- ##  Version:             1.0.1                                                ##
    --- ##  Objetivo:            Programa del pase contable de captacion              ##
    --- ##  Creado por:                                                               ##
    --- ##  ModIFicado por:      JICS                                                 ##
    --- ##  Ultima Modificacion: Diciembre 2011                                       ##
    --- ################################################################################

    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE vsqlerr          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE error_info       CHAR(50);
    DEFINE vpromedio        INTEGER;
    DEFINE vcont            SMALLINT;
    DEFINE vbrinca          INTEGER;
    DEFINE vserial          INTEGER;
    DEFINE vparam_serial    CHAR(60);
    
    LET vcodret       = "000";
    LET vcodret2      = "000";
    LET vcodret3      = " ";
    LET vsqlerr       = 0;
    LET isam_err      = 0;
    LET error_info    = '';
    LET vpromedio     = 0;
    LET vcont         = 0;
    LET vbrinca       = 0;
    LET vserial       = 0;
    LET vparam_serial = '';
    
    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actparampasecheqhis.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actparampasecheqhis.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT ROUND(COUNT(*)/6)
      INTO vpromedio
      FROM sc_movhis
     WHERE fech_alt = pfecha;
       
    LET vcont = 1;  
    
    WHILE vcont <= 5         
        IF vcont = 1 THEN
            LET vbrinca = vpromedio;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 num_serial
                  INTO vserial
                  FROM sc_movhis
                 WHERE fech_alt = pfecha
                 ORDER BY num_serial
                
                LET vparam_serial = vserial;
                
                UPDATE sc_param
                   SET valor = vparam_serial
                 WHERE empresa = pempresa
                   AND codparam = 'SerialIniPaseChqCom1';
            END FOREACH;
        ELIF vcont = 2 THEN
            LET vbrinca = vpromedio * 2;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 num_serial
                  INTO vserial
                  FROM sc_movhis
                 WHERE fech_alt = pfecha
                 ORDER BY num_serial
                 
                LET vparam_serial = vserial;
                 
                UPDATE sc_param
                   SET valor = vparam_serial
                 WHERE empresa = pempresa
                   AND codparam = 'SerialIniPaseChqCom2';
            END FOREACH;
        ELIF vcont = 3 THEN
            LET vbrinca = vpromedio * 3;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 num_serial
                  INTO vserial
                  FROM sc_movhis
                 WHERE fech_alt = pfecha
                 ORDER BY num_serial
                 
                LET vparam_serial = vserial;
                 
                UPDATE sc_param
                   SET valor = vparam_serial
                 WHERE empresa = pempresa
                   AND codparam = 'SerialIniPaseChqCom3';
            END FOREACH;
        ELIF vcont = 4 THEN
            LET vbrinca = vpromedio * 4;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 num_serial
                  INTO vserial
                  FROM sc_movhis
                 WHERE fech_alt = pfecha
                 ORDER BY num_serial
                 
                LET vparam_serial = vserial;
                 
                UPDATE sc_param
                   SET valor = vparam_serial
                 WHERE empresa = pempresa
                   AND codparam = 'SerialIniPaseChqCom4';
            END FOREACH;
        ELIF vcont = 5 THEN
            LET vbrinca = vpromedio * 5;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 num_serial
                  INTO vserial
                  FROM sc_movhis
                 WHERE fech_alt = pfecha
                 ORDER BY num_serial
                 
                LET vparam_serial = vserial;
                 
                UPDATE sc_param
                   SET valor = vparam_serial
                 WHERE empresa = pempresa
                   AND codparam = 'SerialIniPaseChqCom5';
            END FOREACH;
        END IF;
        LET vcont = vcont + 1;  
        LET vserial = 0;
        LET vparam_serial = '';
    END WHILE;    

    RETURN vcodret;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtinfretirosctas( pempresa char(3), pfechaini DATE, pfechafin DATE )
RETURNING CHAR(5), CHAR(5), INTEGER;
     
    DEFINE vcodret1             char(5);
    DEFINE vcodret2             char(5);
    DEFINE vsqlerr              integer;
    DEFINE isam_err             integer;
    DEFINE vcontador1           integer;
    DEFINE vcontador2           integer;
    DEFINE ven_transacc         smallint;
    DEFINE vcomienza            smallint;
    
    DEFINE vperiodo             char(6);
    DEFINE vfecha_hoy           date;
    DEFINE vfechconmovhis       char(10);
    DEFINE vfechconmovhisold    char(10);
    DEFINE vcuenta              char(20);
    DEFINE vproducto            char(4);
    DEFINE vexiste              integer;
    DEFINE vregs                integer;
    DEFINE vmonto               decimal(18,2);
    DEFINE vatm                 smallint;
    DEFINE vpos                 smallint;
    DEFINE vspei                smallint;
    DEFINE vventana             smallint;
    DEFINE vno_tarj_tit         smallint;
    DEFINE vno_tarj_adic        smallint;
    
    LET vcodret1     = "000";               
    LET vcodret2     = '000';
    LET vsqlerr      = 0;                   
    LET isam_err     = 0;
    LET vcontador1   = 0;                   
    LET vcontador2   = 0;
    LET ven_transacc = 0;                   
    LET vcomienza    = -1;  
       
    LET vperiodo       = '';
    LET vfecha_hoy     = ''; 
    LET vfechconmovhis = '';
    LET vfechconmovhisold = '';
    LET vcuenta        = '';  
    LET vproducto      = '';
    LET vexiste        = 0;  
    LET vregs          = 0;
    LET vmonto         = 0.00;
    LET vatm           = 0;
    LET vpos           = 0;
    LET vspei          = 0;
    LET vventana       = 0; 
    LET vno_tarj_tit   = 0;
    LET vno_tarj_adic  = 0;
    
    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_obtinfretirosctas.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret1 = vsqlerr;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1;
