                SELECT COUNT(*)
                  INTO vno_tarj_tit
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'T'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'T'
                                        AND status_tar = 'A');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_adic
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'A'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'A'
                                        AND status_tar = 'A');

                UPDATE tmp_retiros_atmposspei
                   SET no_cuentas = no_cuentas + 1,
                       no_tarj_tit = no_tarj_tit + vno_tarj_tit,
                       no_tarj_adic = no_tarj_adic + vno_tarj_adic,
                       no_operaciones = no_operaciones + vregs,
                       importe = importe + vmonto
                 WHERE periodo = vperiodo
                   AND producto = vproducto; 
            END IF;
            
            IF vatm = 1 AND vpos = 1 AND vspei = 0 AND vventana = 1 THEN
                SELECT COUNT(*), SUM(monto_tot)
                  INTO vregs, vmonto
                  FROM tmp_movhis 
                 WHERE cuenta = vcuenta
                   AND transacc IN('0800','0871','0872','0873','0830','0887','0223');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_tit
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'T'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'T'
                                        AND status_tar = 'A');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_adic
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'A'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'A'
                                        AND status_tar = 'A');

                UPDATE tmp_retiros_atmposvent
                   SET no_cuentas = no_cuentas + 1,
                       no_tarj_tit = no_tarj_tit + vno_tarj_tit,
                       no_tarj_adic = no_tarj_adic + vno_tarj_adic,
                       no_operaciones = no_operaciones + vregs,
                       importe = importe + vmonto
                 WHERE periodo = vperiodo
                   AND producto = vproducto; 
            END IF;
            
            IF vatm = 0 AND vpos = 1 AND vspei = 1 AND vventana = 1 THEN
                SELECT COUNT(*), SUM(monto_tot)
                  INTO vregs, vmonto
                  FROM tmp_movhis 
                 WHERE cuenta = vcuenta
                   AND transacc IN('0830','0887','0274','0223');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_tit
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'T'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'T'
                                        AND status_tar = 'A');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_adic
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'A'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'A'
                                        AND status_tar = 'A');

                UPDATE tmp_retiros_posspeivent
                   SET no_cuentas = no_cuentas + 1,
                       no_tarj_tit = no_tarj_tit + vno_tarj_tit,
                       no_tarj_adic = no_tarj_adic + vno_tarj_adic,
                       no_operaciones = no_operaciones + vregs,
                       importe = importe + vmonto
                 WHERE periodo = vperiodo
                   AND producto = vproducto; 
            END IF;
            
            IF vatm = 1 AND vpos = 1 AND vspei = 1 AND vventana = 1 THEN
                SELECT COUNT(*), SUM(monto_tot)
                  INTO vregs, vmonto
                  FROM tmp_movhis 
                 WHERE cuenta = vcuenta
                   AND transacc IN('0800','0871','0872','0873','0830','0887','0274','0223');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_tit
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'T'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'T'
                                        AND status_tar = 'A');
                   
                SELECT COUNT(*)
                  INTO vno_tarj_adic
                  FROM sc_tarjeta
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta
                   AND tipo_tarjeta = 'A'
                   AND status_tar = 'A'
                   AND secuencia = ( SELECT MAX(secuencia)
                                       FROM sc_tarjeta 
                                      WHERE empresa = pempresa
                                        AND cuenta = vcuenta
                                        AND tipo_tarjeta = 'A'
                                        AND status_tar = 'A');

                UPDATE tmp_retiros_atmposspeivent
                   SET no_cuentas = no_cuentas + 1,
                       no_tarj_tit = no_tarj_tit + vno_tarj_tit,
                       no_tarj_adic = no_tarj_adic + vno_tarj_adic,
                       no_operaciones = no_operaciones + vregs,
                       importe = importe + vmonto
                 WHERE periodo = vperiodo
                   AND producto = vproducto; 
            END IF;
            
        END IF;        
                
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;

        IF (vcontador2 >= 7500) THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vcuenta   = '';
        LET vproducto = '';
        LET vexiste   = '';
        LET vregs     = 0;
        LET vmonto    = 0.00;
        LET vatm      = 0;
        LET vpos      = 0;
        LET vspei     = 0;
        LET vventana  = 0; 
        LET vno_tarj_tit   = 0;
        LET vno_tarj_adic  = 0;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atm;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_pos;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_spei;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_ventanilla;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atmpos;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atmspei;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atmvent;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_posspei;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_posvent;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_speivent;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atmposspei;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atmposvent;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_posspeivent;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_retiros_atmposspeivent;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_sin_retiros;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_grababitacoratras(pEmpresa CHAR(3),
                                   pCtaOrig     CHAR(20),
								   pCtaDest     CHAR(20),
								   pSucursal    CHAR(5),
								   pMonto       MONEY,
								   pEjecutivo   CHAR(20))

	RETURNING CHAR(3);

	DEFINE vCodRet CHAR(3);
	DEFINE vSqlErr, vIsamErr INTEGER;

	LET vCodRet = "000";

	BEGIN
		ON EXCEPTION SET vSqlErr, vIsamErr
			IF vSqlErr != 0 THEN
				LET vCodRet = vSqlErr;
				RETURN vCodRet;
			END IF;
		END EXCEPTION;

		INSERT INTO sc_bitacoratraspaso
			(empresa, cta_origen, cta_destino, sucursal, monto, ejecutivo, fecha)
		VALUES
			(pEmpresa, pCtaOrig, pCtaDest, pSucursal, pMonto, pEjecutivo, Current);
		RETURN vCodRet;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".pasamovshist_pba(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfecha_hoy       DATE;
    DEFINE vfecha_ant       DATE;
    DEFINE vexiste          SMALLINT;
    DEFINE vexistefin       SMALLINT;
    DEFINE vfechaproc       DATE;
    DEFINE vmin_cta         CHAR(20);
    DEFINE vmax_cta         CHAR(20);
    DEFINE vcuenta          CHAR(20);
    DEFINE vaniomes         CHAR(6);
    DEFINE vsql             char(600);
    DEFINE vstmt            char(250);
    DEFINE vexistefinproc   CHAR(1);
    DEFINE vproceso         CHAR(12);
    DEFINE vsistema         CHAR(2);
    DEFINE vusuario         CHAR(10);
    DEFINE vexiste_fecha    SMALLINT;
    
    LET vcodret1        = '000';
    LET vcodret2        = '000';
    LET sql_err	        = 0;
    LET isam_err        = 0;
    LET vcontador1      = 0;
    LET vcontador2      = 0;
    LET vcontador3      = 0;
    LET ven_transacc    = 0; 
    
    LET vfecha_hoy      = ''; 
    LET vfecha_ant      = '';
    LET vexiste         = 0;
    LET vexistefin      = 0;
    LET vfechaproc      = '';
    LET vmin_cta        = '';
    LET vmax_cta        = '';
    LET vcuenta         = ''; 
    LET vaniomes        = '';
    LET vsql            = '';
    LET vstmt           = '';
    LET vexistefinproc  = '';
    LET vproceso        = 'PasaMovsHist';
    LET vsistema        = '01';
    LET vusuario        = user;
    LET vexiste_fecha   = 0;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshist.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovs.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovs.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshist.out";
    --- TRACE ON;
    
    SET OPTIMIZATION HIGH;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy, fecha_ant
      INTO vfecha_hoy, vfecha_ant
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    -- // VALIDA HAYA FINALIZADO CIERRE DE CAPTACION
    SELECT fecha
      INTO vfechaproc
      FROM sc_contproc
     WHERE empresa = pempresa
       AND proceso = 'cierre'
       AND fecha = vfecha_ant;
    
    IF vfechaproc is null THEN
        LET vcodret1 = "962";
        LET vcodret2 = "962";
        RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
    END IF
     
    -- // Guarda inicio de proceso     
    SELECT COUNT(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vfecha_hoy
       AND sistema = vsistema;

    IF vexiste = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horaspasamovs.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovs.sql';
        SYSTEM vstmt;
    ELSE
        SELECT COUNT(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";
           
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovs.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovs.sql';
            SYSTEM vstmt;
        ELSE
            SELECT "1"
              INTO vexistefinproc
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = "pasomovshist"
               AND fecha = vfecha_ant;
               
            IF vexistefinproc = "1" THEN
                LET vcodret1 = "958";
                RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
            END IF
        END IF;
    END IF;
    
   /*  -- // LLENA TABLA PARA PROCESO EXTERIOR
    TRUNCATE TABLE sc_movdia_apert;

    INSERT INTO sc_movdia_apert
    SELECT *
      FROM sc_movdia
     WHERE empresa = pempresa
       AND cuenta <> '16000000012'
       AND fech_alt = vfecha_ant
       AND cancelad <> 'S'
       AND transacc in ('0202','0223'); */
       
    -- // OBTIENE NUMERO DE REGISTROS A TRASPASAR
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vmin_cta, vmax_cta
      FROM sc_movdia;
      
    SELECT COUNT(*)
      INTO vexiste_fecha
      FROM sc_trasp_movdia_movhis
     WHERE fecha = vfecha_ant;
     
    IF vexiste_fecha = 0 THEN
        SELECT COUNT(*)
          INTO vcontador1
          FROM sc_movdia
         WHERE empresa = pempresa
           AND cuenta BETWEEN vmin_cta AND vmax_cta
           AND fech_alt = vfecha_ant; 
         
        INSERT INTO sc_trasp_movdia_movhis(fecha, no_regs)
        VALUES(vfecha_ant, vcontador1);
    ELSE
        SELECT no_regs
          INTO vcontador1
          FROM sc_trasp_movdia_movhis
         WHERE fecha = vfecha_ant;
    END IF;
    
    LET vaniomes = YEAR(vfecha_ant)||LPAD(MONTH(vfecha_ant),2,0);
    
    FOREACH WITH HOLD 
        SELECT UNIQUE cuenta
          INTO vcuenta
          FROM sc_movdia
         WHERE empresa = pempresa
           AND cuenta BETWEEN vmin_cta AND vmax_cta
           AND fech_alt = vfecha_ant
           AND producto NOT IN('1200','1600','9900','9901')
           
        BEGIN WORK;
        LET ven_transacc = 1; 
        
        INSERT INTO sc_movhis
        SELECT vaniomes, mov.*
          FROM sc_movdia mov
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.fech_alt = vfecha_ant;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            DELETE FROM sc_movdia
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt = vfecha_ant;
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                COMMIT WORK;
                LET ven_transacc = 0; 
            ELSE
                ROLLBACK WORK;
                LET ven_transacc = 0; 
            END IF;
        ELSE
            ROLLBACK WORK;
            LET ven_transacc = 0; 
        END IF;
    END FOREACH;
    
    FOREACH WITH HOLD 
        SELECT UNIQUE cuenta
          INTO vcuenta
          FROM sc_movdia
         WHERE empresa = pempresa
           AND cuenta BETWEEN vmin_cta AND vmax_cta
           AND fech_alt = vfecha_ant
           
        BEGIN WORK;
        LET ven_transacc = 1; 
           
        INSERT INTO sc_movhis
        SELECT vaniomes, mov.*
          FROM sc_movdia mov
         WHERE mov.empresa = pempresa
           AND mov.cuenta = vcuenta
           AND mov.fech_alt = vfecha_ant;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            DELETE FROM sc_movdia
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt = vfecha_ant;
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                COMMIT WORK;
                LET ven_transacc = 0; 
            ELSE
                ROLLBACK WORK;
                LET ven_transacc = 0; 
            END IF;
        ELSE
            ROLLBACK WORK;
            LET ven_transacc = 0; 
        END IF;
    END FOREACH;
    
    SELECT {+INDEX(sc_movhis idx_movhisnew6)}
           COUNT(*)
      INTO vcontador2
      FROM sc_movhis
     WHERE fech_alt = vfecha_ant;
     
    SELECT COUNT(*)
      INTO vcontador3
      FROM sc_movdia
     WHERE empresa = pempresa
       AND cuenta BETWEEN vmin_cta AND vmax_cta
       AND fech_alt = vfecha_ant; 
       
    IF vcontador1 = vcontador2 THEN
        LET vcodret1 = '000'; -- // PROCESO CONCLUIDO SATISFACTORIAMENTE
        LET vcodret2 = '000';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vusuario||''','||
                   'status_proc   = '''||'F'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovs.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovs.sql';
        SYSTEM vstmt;
           
        UPDATE sc_contproc
           SET fecha   = vfecha_ant
         WHERE empresa = pempresa
           AND proceso = 'pasomovshist';
    ELSE
        LET vcodret1 = '999'; -- // LOS MOVIMIENTOS TRASPASADOS NO COINCIDEN CON LOS MOVIMIENTOS A TRASAPASAR
        LET vcodret2 = '999';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovs.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovs.sql';
        SYSTEM vstmt;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_geninfoctaefecnos(cSucursal char(4),pRegistro smallint)
RETURNING  char(5), char(11), char(9), char(70), char (10), char (5), char(13), char(13), char(60), money(16,2);
    
    DEFINE cCodret 	char(5);
    DEFINE cCuenta	char (11);
    DEFINE cNumcte	char (9);
    DEFINE cCliente	char (70);
    DEFINE dFecha_nac	char (10);
    DEFINE cEdad	char (5);
    DEFINE cTelefono1	char (13);
    DEFINE cTelefono2	char (13);
    DEFINE cEmail	char (60);
    DEFINE mSdo_actual	money;
    DEFINE iSQL_ERR 	integer;
    DEFINE iBandera 	integer;
    DEFINE cDescripcion	char (35);
    DEFINE iCiclo 	integer;
    DEFINE iAnnos INTEGER;
    DEFINE iMeses INTEGER;
    DEFINE iMes_Actual INTEGER;
    DEFINE iMes_Nac INTEGER;
    DEFINE iDia_Actual INTEGER;
    DEFINE iDia_Nac INTEGER;
    
    LET cCuenta = "";
    LET cNumcte = "";
    LET cCliente = "";
    LET cEdad = 0.0;
    LET cTelefono1 = "";
    LET cTelefono2 = "";
    LET cEmail = "";
    LET mSdo_actual = 0;
    LET iSQL_ERR = 100 ;
    LET cCodret  = "000";
    LET dFecha_nac = "";
    LET iBandera = 1;
    LET iCiclo = 0;
    LET iAnnos = 0;
    LET iMeses = 0;
    
    -- SET DEBUG FILE TO '/tmp/sp_geninfoctaefecnos.out';
    -- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET iSQL_ERR
        LET cCodret = iSQL_ERR;
        RETURN cCodret,cCuenta, cNumcte, cCliente, dFecha_nac, cEdad, cTelefono1, cTelefono2, cEmail, mSdo_actual;
    END EXCEPTION;
    
    FOREACH
        SELECT mae.cuenta, sicte.numcte, 
               TRIM (sicte.apell_paterno) ||' '||TRIM (sicte.apell_materno) ||' '|| TRIM (sicte.nombre1) ||' '||TRIM (sicte.nombre2) as cliente,
               ctepf.fecha_nac, YEAR(fech.fecha_hoy) - YEAR(ctepf.fecha_nac), MONTH(fech.fecha_hoy) - MONTH(ctepf.fecha_nac),
               MONTH(fech.fecha_hoy), MONTH(ctepf.fecha_nac), DAY(fech.fecha_hoy), DAY(ctepf.fecha_nac),
               tel1.telefono, tel2.telefono, core.correo_elec, mae.sdo_actual
          INTO cCuenta, cNumcte , cCliente, dFecha_nac, iAnnos, iMeses, iMes_Actual, iMes_Nac, iDia_Actual, iDia_Nac, cTelefono1, cTelefono2, cEmail, mSdo_actual
          FROM bdicheq:sc_maechq mae
         INNER JOIN bdinteg:si_cliente sicte ON (sicte.numcte = mae.num_cte)
         INNER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = sicte.numcte)
         INNER JOIN bdicheq:sc_fechas fech ON (fech.fecha_hoy > ctepf.fecha_nac AND fech.empresa = mae.empresa)
          left outer join bdinteg:si_telefonos_actual tel1 on (tel1.numcte = mae.num_cte and tel1.tipo_tel = 1)
          left outer join bdinteg:si_telefonos_actual tel2 on (tel2.numcte = mae.num_cte and tel2.tipo_tel = 2)
          left outer join bdinteg:si_correos core on (core.numcte = mae.num_cte and core.tipo_correo = 1 and core.status_correo ='A')
         WHERE mae.producto = '1500'
           AND mae.sucursal = cSucursal
           AND mae.status_cta = '1'
           AND ((YEAR(fech.fecha_hoy) + (MONTH(fech.fecha_hoy)/12) + (DAY(fech.fecha_hoy)/30/12))) -
               ((YEAR(ctepf.fecha_nac) + (MONTH(ctepf.fecha_nac)/12) + (DAY(ctepf.fecha_nac)/30/12))) >= 17.9166666666666666666663
         --- ORDER BY mae.num_cte
    
        LET iBandera = cCodret;
        LET iCiclo = iCiclo + 1;
    
        IF iMeses < 0 THEN
            LET iAnnos =  iAnnos - 1;
            IF iMes_Nac  >  iMes_Actual THEN
                IF iDia_Nac = iDia_Actual OR iDia_Nac < iDia_Actual THEN
                    LET iMeses = iMeses + 12;
                ELSE
                    IF iDia_Nac > iDia_Actual THEN
                    LET iMeses = (iMeses +12) -1;
                    END IF;
                END IF;
            END IF;
    
            LET cEdad = cast(iAnnos AS CHAR(2))||'.'||CAST(iMeses AS CHAR(2));
        ELSE
            IF iMes_Actual  =  iMes_Nac THEN
                IF iDia_Nac = iDia_Actual OR iDia_Nac < iDia_Actual THEN
                    LET iAnnos = iAnnos;
                ELSE
                    LET iAnnos = iAnnos - 1;
                    LET iMeses = 11;
                END IF;
            ELSE
                IF iMes_Actual  >  iMes_Nac THEN
                    IF iDia_Nac = iDia_Actual OR iDia_Actual > iDia_Nac THEN
                        LET iMeses = iMeses;
                    ELSE
                        IF iDia_Nac > iDia_Actual THEN
                            LET iMeses = iMeses - 1;
                        END IF;
                    END IF;
                ELSE
                    IF iDia_Nac > iDia_Actual THEN
                        LET iMeses = iMeses;
                        LET iMeses = iMeses - 1;
                    END IF;
                    LET iAnnos = iAnnos - 1;
                END IF;
            END IF;
            --- LET iMeses = iMeses;
            LET cEdad = cast(iAnnos AS CHAR(2))||'.'||CAST(iMeses AS CHAR(2));
        END IF;
    
        IF iCiclo <= pRegistro THEN
            CONTINUE FOREACH;  -- PAGINACION
        END IF;
    
        RETURN cCodret, cCuenta, cNumcte, cCliente, dFecha_nac, cEdad, cTelefono1, cTelefono2, cEmail, mSdo_actual with resume;
    
    END FOREACH;
    
    IF iBandera <> 000 THEN
    	LET cCodret = '99999' ;
        LET cCliente = 'No se encontraron registros';
        RETURN cCodret,cCuenta, cNumcte ,cCliente, dFecha_nac, cEdad, cTelefono1, cTelefono2, cEmail, mSdo_actual;
    END IF
    
    END;
    
END PROCEDURE
    
DOCUMENT
'AUTOR :Jesus Antonio Bastidas Lopez',
'DESCRIPCION: Se creo el sp para el llenado del reporte de control de cuentas efectivas niños.',
'Captacion',
'FECHA : Noviembre de 2008',
'VERSION: 200811',
'MODIFICACION: Se agrego en la consulta para que regresara los Años y Mese de la Edad del Cliente',
'              de las cuentas efectivas niños.',
'AUTOR : Héctor Manuel Bojórquez Ruelas',
'FECHA Modificación: 01 de JULIO de 2009',
'BD    : BDICHEQ';

CREATE PROCEDURE "informix".sp_movs_mayores_diezmil(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER;

    DEFINE vsql CHAR(300);
    DEFINE vfecha CHAR(8);
    DEFINE vtel1, vtel2, vtel3 CHAR(13);
    DEFINE vtransacc, vsucursal, vsuc_cta CHAR(4);
    DEFINE vcodret1, vcodret2, vext CHAR(5);
    DEFINE vmincta, vmaxcta, vcuenta, vnum_cte, vexiste char(20); 
    DEFINE vmonto DECIMAL(18,2);
    DEFINE ven_transacc SMALLINT;
    DEFINE vfecha_hoy, vfecha_ant, vfech_alt DATE;
    DEFINE sql_err, isam_err, vcontador1, vnum_serial , vregistro INTEGER;
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET vcontador1   = -1;
    LET ven_transacc = 0; 
    
    LET vexiste    = '';
    LET vfecha_hoy = '';
    LET vfecha_ant = '';
    LET vmincta    = '';
    LET vmaxcta    = '';
    LET vfecha     = '';
    LET vsql       = '';
    
    LET vregistro = 0;
    LET vnum_serial = '';
    LET vcuenta = ''; 
    LET vsuc_cta = '';
    LET vtransacc = ''; 
    LET vmonto = 0.00; 
    LET vsucursal = ''; 
    LET vfech_alt = ''; 
    LET vnum_cte = '';
    LET vtel1 = '';
    LET vtel2 = '';
    LET vtel3 = '';
    LET vext = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_movs_mayores_diezmil.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_movs_mayores_diezmil.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    
    SELECT fecha_hoy, fecha_ant
      INTO vfecha_hoy, vfecha_ant
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    SELECT proceso
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE proceso = 'PasaMovsHist'
       AND fecha = vfecha_hoy
       AND sistema = '01'
       AND status_proc = 'F';
       
    IF vexiste is null OR vexiste = '' THEN 
        LET vcodret1 = '953';
        RETURN vcodret1, vcodret2, vcontador1;
    END IF;
     
    IF WEEKDAY(vfecha_ant) = 1 THEN
        TRUNCATE TABLE sc_movs_mayor_diezmil;
    END IF;
    
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vmincta, vmaxcta
      FROM sc_movhis;
      
    SELECT {+INDEX(sc_movhis idx_movhisnew4)}
           num_serial
      FROM sc_movhis
     WHERE empresa = pempresa
       AND cuenta = '16000000012'
       AND fech_alt = vfecha_ant
       AND cancelad <> 'S'
       AND transacc = '0202'
    UNION ALL 
    SELECT {+INDEX(sc_movhis idx_movhisnew4)}
           num_serial
      FROM sc_movhis
     WHERE empresa = pempresa
       AND cuenta = '16000000039'
       AND fech_alt = vfecha_ant
       AND cancelad <> 'S'
       AND transacc = '1133'
      INTO TEMP tmp_movscoppel WITH NO LOG;
    CREATE INDEX idx_tmpmovscoppel ON tmp_movscoppel(num_serial) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_movscoppel;
      
    SELECT {+INDEX(sc_movhis idx_movhisnew4)}
           mov.num_serial, mov.cuenta, mov.transacc, mov.monto_tot, mov.sucursal, mov.fech_alt, tran.descripcion
      FROM sc_movhis mov,
           bdinteg:si_transacc tran
     WHERE mov.empresa = pempresa
       AND mov.cuenta BETWEEN vmincta AND vmaxcta
       AND mov.fech_alt = vfecha_ant
       AND mov.cancelad <> 'S'
       AND mov.transacc = tran.numero
       AND mov.monto_tot > 10000.00
       AND mov.num_serial NOT IN(SELECT num_serial FROM tmp_movscoppel)
       AND tran.empresa = mov.empresa
       AND tran.numero = mov.transacc
       AND tran.naturaleza IN('A', 'C')       
      INTO TEMP tmp_movtos WITH NO LOG;
    CREATE INDEX idx_tmpmovtos ON tmp_movtos(cuenta) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_movtos;
    
    SELECT cuenta, num_cte, sucursal as suc_cta
      FROM sc_maechq
     WHERE empresa = pempresa
       AND cuenta IN(SELECT cuenta FROM tmp_movtos)
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idx_tmpctes ON tmp_clientes(num_cte) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_clientes;  
    
    /* ###########################################################################################
    SELECT numcte, secuencia, telefono1, telefono2, telefono3, extension
      FROM bdinteg:si_direcciones_actual
     WHERE numcte IN(SELECT num_cte FROM tmp_clientes)
      INTO TEMP tmp_si_direcciones_actual WITH NO LOG;
    CREATE INDEX idx_tmpsidirecc ON tmp_si_direcciones_actual(numcte) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_si_direcciones_actual;  
    ########################################################################################### */
    
    UPDATE STATISTICS MEDIUM FOR TABLE sc_movs_mayor_diezmil;
      
    FOREACH WITH HOLD
        SELECT num_serial, cuenta, transacc, monto_tot, sucursal, fech_alt
          INTO vnum_serial, vcuenta, vtransacc, vmonto, vsucursal, vfech_alt
          FROM tmp_movtos 
          
        IF vcontador1 = -1 THEN
            LET vcontador1 = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
         
        SELECT num_cte, suc_cta 
          INTO vnum_cte, vsuc_cta
          FROM tmp_clientes
         WHERE cuenta = vcuenta;
           
        SELECT LIMIT 1 NVL(tel1.telefono, ' '), NVL(tel2.telefono, ' '), NVL(tel3.telefono, ' '), NVL(tel3.extension, ' ')
          INTO vtel1, vtel2, vtel3, vext
          FROM bdicheq:sc_maechq mae
          INNER JOIN bdinteg:si_cliente sicte ON ( sicte.numcte = mae.num_cte )
          left outer join bdinteg:si_telefonos_actual tel1 on ( tel1.numcte = mae.num_cte and tel1.tipo_tel = 1 )
          left outer join bdinteg:si_telefonos_actual tel2 on ( tel2.numcte = mae.num_cte and tel2.tipo_tel = 2 )
          left outer join bdinteg:si_telefonos_actual tel3 on ( tel3.numcte = mae.num_cte and tel3.tipo_tel = 3 )
         WHERE mae.num_cte = vnum_cte;
           
        SELECT NVL(MAX(registro), 0) + 1
          INTO vregistro
          FROM sc_movs_mayor_diezmil;
    
        INSERT INTO sc_movs_mayor_diezmil VALUES
        (vregistro, vsucursal, vnum_cte, vcuenta, vsuc_cta, vfech_alt, vtransacc, vmonto, vtel1, vtel2, vtel3, vext);
        
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vregistro = 0;
        LET vnum_serial = '';
        LET vcuenta = ''; 
        LET vtransacc = ''; 
        LET vmonto = 0.00; 
        LET vsucursal = ''; 
        LET vfech_alt = ''; 
        LET vnum_cte = '';
        LET vsuc_cta = '';
        LET vtel1 = '';
        LET vtel2 = '';
        LET vtel3 = '';
        LET vext = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        COMMIT WORK;
        LET ven_transacc = 0;
    END IF;
    
    IF WEEKDAY(vfecha_ant) = 0 THEN
        UPDATE STATISTICS MEDIUM FOR TABLE sc_movs_mayor_diezmil;
        
        LET vfecha = TO_CHAR(vfecha_hoy, '%d%m%Y');
        
        LET vsql = '';
        LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/movtos_mayores_diezmil_'||vfecha||'.txt'||
                   ' SELECT sucursal,numcte,cuenta,suc_cta,fecha_transacc,transaccion,monto_transacc,telefono1,telefono2,telefono3,extension'||
                   ' FROM sc_movs_mayor_diezmil ORDER BY sucursal,numcte,cuenta;" > /resplogifx/conciliachq/movs.sql';
        SYSTEM vsql;
        LET vsql = '';
        --- LET vsql = "dbaccess bdicheq /resplogifx/conciliachq/movs.sql"; 
        LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/movs.sql"; 
        SYSTEM vsql;
        LET vsql = '';
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_reportepagareinversionxvencer ()
RETURNING CHAR(5), CHAR (60); -- CodigoRetorno,Mensaje
    
    -- Declaracion de Variables
    DEFINE vSqlError    SMALLINT;
    DEFINE cCodRet      CHAR (5);
    DEFINE dFechaHoy    DATE;
    DEFINE cDiasXVencer CHAR (5);
    DEFINE cMensaje     CHAR (60);
    DEFINE cMinCta      CHAR(20);
    DEFINE cMaxCta      CHAR(20);
    DEFINE cMin_Cta     CHAR(20);
    DEFINE cMax_Cta     CHAR(20);
    
    -- Inicializacion de Variables
    LET vSqlError = 0;
    LET cCodRet = '00000';
    LET dFechaHoy = '';
    LET cDiasXVencer = '';
    LET cMensaje ='EL PROCESO SE EJECUTO EXITOSAMENTE';
    LET cMinCta = '';
    LET cMaxCta = '';
    LET cMin_Cta = '';
    LET cMax_Cta = '';
    
    BEGIN
    
    ON EXCEPTION SET vSqlError
        IF vSqlError <> 0 THEN
            LET cCodRet = vSqlError;
            RETURN cCodRet, 'Ocurrio un Error Durante La Ejecucion Del Procedimiento';
        END IF;
    END EXCEPTION;
    
    -- LIMPIAR LA TABLA
    IF EXISTS(SELECT tabname FROM bdicheq:systables WHERE tabname = 'sc_vencinvpag') THEN
        --- // Limpia tabla para generar informacion diaria
        --- DELETE FROM bdicheq:sc_vencinvpag;
        DROP TABLE sc_vencinvpag;
    END IF;
    
    CREATE TABLE sc_vencinvpag 
        (   numcta CHAR(20) NOT NULL , 
            sucursal CHAR(4) NOT NULL, 
            fecha_vencimiento DATE NOT NULL, 
            promotor CHAR(8) NOT NULL,
            numcte CHAR(9) NOT NULL , 
            suc_cte CHAR(4) NOT NULL,
            nombre1 CHAR(30) NOT NULL, 
            nombre2 CHAR(30), 
            apell_paterno CHAR(30) NOT NULL, 
            apell_materno CHAR(30), 
            monto MONEY(15,2), 
            fecha_apertura DATE, 
            telefono CHAR(15),
            inst_vento_capital CHAR(2),
            inst_vento_interes CHAR(2),
            PRIMARY KEY (numcta) CONSTRAINT pk_numcta 
        )
    EXTENT SIZE 2048 NEXT SIZE 1024 LOCK MODE ROW;
    CREATE INDEX sc_vencinvpag ON sc_vencinvpag (sucursal, fecha_vencimiento, promotor, numcta) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE sc_vencinvpag;
    
    SET ISOLATION TO DIRTY READ;
    
    -- crea un archivo temporal en el servidor
    --- SET debug file to "/tmp/Antonio/sp_ReportePagareInversionXvencer.out";
    --- trace on;
    
    -- Obtener Parametros
    SELECT fecha_hoy 
      INTO dFechaHoy 
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';
    
    SELECT TRIM (valor) 
      INTO cDiasXVencer 
      FROM bdicheq:sc_param 
     WHERE empresa = "001"
       AND codparam = 'DIASANTESVENC';	
    
    SELECT MIN(cuenta), MAX(cuenta)
      INTO cMinCta, cMaxCta
      FROM sc_maechq;
    
    SELECT MIN(cuenta), MAX(cuenta)
      INTO cMin_Cta, cMax_Cta
      FROM bdinvers:sv_maeinv;
    
    -- Proceso para la Inversion Creciente
    INSERT INTO sc_vencinvpag ( numcta, sucursal, fecha_vencimiento, promotor, numcte, suc_cte, nombre1, nombre2, 
                                apell_paterno, apell_materno, monto, fecha_apertura, telefono, inst_vento_capital, inst_vento_interes )
    SELECT mae.cuenta, mae.sucursal, noc.fecha_mod, noc.ejecutivo, mae.num_cte, cte.sucursal, TRIM(cte.nombre1), TRIM(NVL(cte.nombre2,'')),
           TRIM(cte.apell_paterno), TRIM(NVL(cte.apell_materno,'')), mae.sdo_actual, noc.fecha_alta, tel.telefono, '01', '01'
      FROM bdicheq:sc_maechq mae
     INNER JOIN bdicheq:sc_maenoc noc ON (noc.empresa = mae.empresa AND noc.cuenta = mae.cuenta)
     INNER JOIN bdinteg:si_cliente cte ON (cte.empresa = mae.empresa AND cte.numcte = mae.num_cte)
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel ON (tel.numcte = cte.numcte AND tel.tipo_tel = '1')
     WHERE mae.empresa = '001'
       AND mae.cuenta BETWEEN cMinCta AND cMaxCta
       AND mae.status_cta = '1'
       AND mae.producto = '1100'
       AND noc.fecha_mod BETWEEN dFechaHoy AND (dFechaHoy + cDiasXVencer::INTEGER);
    
    -- Proceso para el pagare
    INSERT INTO sc_vencinvpag ( numcta, sucursal, fecha_vencimiento, promotor, numcte, suc_cte, nombre1, nombre2,
                                apell_paterno, apell_materno, monto, fecha_apertura, telefono, inst_vento_capital, inst_vento_interes )
    SELECT inv.cuenta, inv.sucursal, inv.fecha_venc, inv.promotor, inv.num_cte, cte.sucursal, 
           TRIM(cte.nombre1), TRIM(NVL(cte.nombre2,'')), TRIM(cte.apell_paterno), TRIM(NVL(cte.apell_materno,'')), 
           inv.capital, inv.fecha_alta, tel.telefono, 
           ( SELECT inst_vento FROM bdinvers:sv_maeinstrucc WHERE cuenta = inv.cuenta AND cap_int = 'C' ),
           ( SELECT inst_vento FROM bdinvers:sv_maeinstrucc WHERE cuenta = inv.cuenta AND cap_int = 'I' )
       --- LPAD( TRIM( CAST( SUM( NVL(inst.inst_ventocapital, 0) ) AS CHAR(2) ) ),2,'0'),
       --- LPAD( TRIM( CAST( SUM( NVL(inst.inst_ventointeres, 0) ) AS CHAR(2) ) ),2,'0')
      FROM bdinvers:sv_maeinv inv
     INNER JOIN bdinteg:si_cliente cte ON (cte.numcte = inv.num_cte)
    --- INNER JOIN bdinvers:sv_maeinstrucc inst ON (inst.empresa = inv.empresa AND inst.cuenta = inv.cuenta)
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel ON (tel.numcte = cte.numcte AND tel.tipo_tel = '1')
    ---  TABLE ( MULTISET ( SELECT empresa, cuenta,
    ---                            CASE WHEN cap_int = 'I' THEN CAST(inst_vento AS INTEGER) END AS inst_ventointeres,
    ---                            CASE WHEN cap_int = 'C' THEN CAST(inst_vento AS INTEGER) END AS inst_ventocapital
    ---                       FROM bdinvers:sv_maeinstrucc ) ) inst
     WHERE inv.empresa = '001'
       AND inv.cuenta BETWEEN cMin_Cta AND cMax_Cta
       AND inv.status_cta = '1'
       AND inv.fecha_venc BETWEEN dFechaHoy AND (dFechaHoy + cDiasXVencer::INTEGER); 
   --- AND inst.empresa = inv.empresa
   --- AND inst.cuenta = inv.cuenta
 --- GROUP BY inv.Cuenta, inv.sucursal, inv.fecha_venc, inv.promotor, inv.num_cte, cte.sucursal, cte.nombre1, cte.nombre2,
 ---          cte.apell_paterno, cte.apell_materno, inv.capital, inv.fecha_alta, tel.telefono;
    
    RETURN cCodRet, cMensaje;
    
    END
    
END PROCEDURE
    
DOCUMENT
'Autor: Edith Maribel Armenta Sánchez',
'Descripción: Crea un sp para consultar los vencimientos de los proximos 7 dias de la sucursal que ejecuta el proceso.',
