CREATE PROCEDURE "informix".sp_generarptcancel
(
pEmpresa	CHAR(3),
pEjecutivo	CHAR(8),
pGerente	CHAR(8),
pCliente	CHAR(20),
pCuenta 	CHAR(20) 
)
RETURNING
	CHAR(5) 		AS cod_ret,
	CHAR(80) 		AS descripcion,
	CHAR(10)		AS fecha,
	CHAR(45)		AS sucursal,
	CHAR(107)		AS nombre_cte,
	CHAR(20)		AS num_cte,
	CHAR(1)			AS tipo_cta,
	CHAR(20)		AS num_cta,
	CHAR(30)		AS num_identif,
	CHAR(40)		AS motivo_cancel,
	CHAR(22)		AS folio_cancel,
	CHAR(107)		AS nombre_firma_cte,
	CHAR(8)			AS codigo_firma_prom,
	CHAR(45)		AS nombre_firma_prom,
	CHAR(8)			AS codigo_firma_gte,
	CHAR(40)		AS nombre_firma_gte;
	

	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(5);
    DEFINE cMensajeRet		CHAR(80);
	DEFINE cFecha			CHAR(10);
	DEFINE cSucursal		CHAR(45);
	DEFINE cNombreCte		CHAR(107);
	DEFINE cTipoCta			CHAR(1);
	DEFINE cNumCta			CHAR(20);
	DEFINE cNumIdentif		CHAR(30);
	DEFINE cMotivoCancel	CHAR(40);
	DEFINE cFolioCancel		CHAR(22);
	DEFINE cNombreFirmaCte	CHAR(107);
	DEFINE cCodigoFirmaProm	CHAR(8);
	DEFINE cNombreFirmaProm	CHAR(45);
	DEFINE cCodigoFirmaGte	CHAR(8);
	DEFINE cNombreFirmaGte	CHAR(40);
	DEFINE vtipopersona	    CHAR(2);
	
	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
	LET cCodRet				= "00000";
	LET cMensajeRet			= "PROCESO EXITOSO";
	LET cFecha				= "";
	LET cSucursal			= "";
	LET cNombreCte			= "";
	LET cTipoCta			= "";
	LET cNumCta				= "";
	LET cNumIdentif			= "";
	LET cMotivoCancel		= "";
	LET cFolioCancel		= "";
	LET cNombreFirmaCte		= "";
	LET cCodigoFirmaProm	= "";
	LET cNombreFirmaProm	= "";
	LET cCodigoFirmaGte		= "";
	LET cNombreFirmaGte		= "";
	LET vtipopersona		= "";


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN cCodRet, cMensajeRet, cFecha, cSucursal, cNombreCte, pCliente, cTipoCta, cNumCta, cNumIdentif, cMotivoCancel, cFolioCancel, cNombreFirmaCte, cCodigoFirmaProm, cNombreFirmaProm, cCodigoFirmaGte, cNombreFirmaGte;
       END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	/*SET DEBUG FILE TO "/resplogifx/conciliachq/sp_generarptcancel.out";
	TRACE ON;*/

	-- VALIDA QUE LOS PARAMETROS NO VENGAN VACIOS
    IF NVL(pEmpresa,'') = '' OR NVL(pEjecutivo,'') = '' OR NVL(pCliente,'') = '' OR NVL(pCuenta,'') = '' THEN
		LET cCodRet = '00007';
				
		SELECT descripcion
		INTO cMensajeRet
		FROM bdinteg:"informix".si_codret
		WHERE codigo_retorno = '007'
		AND sistema = '20';
	ELSE		
		-- VALIDA QUE SE ENCUENTRE EN EL CATALOGO DE CTAS CANCELADAS E OBTIENE LA DESCRIPCION DEL MOTIVO Y EL FOLIO
		SELECT t1.descripcion, t2.folio_cancelacion
		INTO cMotivoCancel, cFolioCancel
		FROM bdicheq: "informix".sc_motivocancel t1, bdicheq: "informix".sc_ctacancelada t2
		WHERE t1.clave = t2.motivo
		AND t2.cuenta = pCuenta;
	
		IF NVL(cFolioCancel,"") = "" THEN
			LET cCodRet = '00080';
			
			SELECT descripcion
			INTO cMensajeRet
			FROM bdinteg:"informix".si_codret
			WHERE codigo_retorno = '80';
		ELSE
			-- OBTIENE LA FECHA DE HOY DEL SISTEMA
			SELECT LPAD(DAY(fecha_hoy),2,"0") || "/" || LPAD(MONTH(fecha_hoy),2,"0")|| "/" || YEAR(fecha_hoy)
			INTO cFecha
			FROM bdicheq: "informix".sc_fechas;
			
			-- OBTIENE LA CLAVE Y EL NOMBRE DE LA SUCURSAL, Y EL NOMBRE DEL GERENTE
			SELECT t1.sucursal || " " || t2.nombre, t1.nombre, t2.gerente
			INTO cSucursal, cNombreFirmaProm, cNombreFirmaGte
			FROM bdinteg: "informix".si_ejecut t1, bdinteg: "informix".si_sucursales t2
			WHERE t1.ejecutivo = pEjecutivo
			AND t1.sucursal = t2.sucursal;
			
			-- OBTIENE EL NOMBRE DEL CLIENTE
			SELECT TRIM(nombre1) || " " || TRIM(nombre2) || " " || TRIM(apell_paterno) || " " || TRIM(apell_materno), tpo_persona
			INTO cNombreCte, vtipopersona
			FROM bdinteg: "informix".si_cliente WHERE empresa = pEmpresa AND numcte = pCliente;
			
			IF vtipopersona = '02' THEN
			SELECT TRIM (pm.nombre_corto) || " " || TRIM (su.descripcion)
				INTO  cNombreCte
				FROM bdinteg:"informix".si_ctepm pm,
				bdinteg:"informix".si_sufijos su
				WHERE pm.numcte = pCliente
				AND su.codigo =pm.sufijo;
								
			END IF

			LET cNombreFirmaCte = cNombreCte;
			
			--  OBTIENE EL TIPO DE PRODUCTO
			SELECT "1"
			INTO cTipoCta
			FROM bdicheq: "informix".sc_maechq t1,  bdicheq: "informix".sc_producto t2
			WHERE t1.cuenta = pCuenta
			AND t1.producto = t2.producto;
			
			LET cTipoCta = NVL(cTipoCta,"0");
			
			LET cNumCta = pCuenta;
			
			-- OBTIENE LA IDENTIFICACION
			SELECT numidentifi
			INTO cNumIdentif
			FROM bdinteg: "informix".si_ctepf 
			WHERE empresa = pEmpresa AND numcte = pCliente;
			
			LET cCodigoFirmaProm = pEjecutivo;
			
			-- VALIDA SI VIENE VACIO SU ORIGEN ES DE CENTRAL
			IF NVL(pGerente,"") = "" THEN
				LET cCodigoFirmaGte = "";
			-- VALIDA SI TRAE DATO SU ORIGEN ES DE SUCURSAL
			ELSE
				LET cCodigoFirmaGte = pGerente;
				LET cNombreFirmaGte = "";
			END IF
			
		END IF
	END IF	
	
	RETURN cCodRet, cMensajeRet, NVL(cFecha,""), NVL(cSucursal,""), NVL(cNombreCte,""), NVL(pCliente,""), NVL(cTipoCta,""), NVL(cNumCta,""), NVL(cNumIdentif,""), NVL(cMotivoCancel,""), NVL(cFolioCancel,""), NVL(cNombreFirmaCte,""), NVL(cCodigoFirmaProm,""),  NVL(cNombreFirmaProm,""), NVL(cCodigoFirmaGte,""), NVL(cNombreFirmaGte,"");

	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener la informacion de la cuenta cancelada de captacion', 
'AUTOR: Mohamed Carreón ',
'FECHA: Agosto 2012',
'VERSION: 20120801.1139';

CREATE PROCEDURE "informix".sp_cargosideesp(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcodret_cargo    CHAR(5);
    
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vaniomes         CHAR(6);
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(14,2);    
    DEFINE vtransacc        CHAR(4);
    DEFINE vdescripcion     CHAR(40);
    DEFINE vsucursal        CHAR(4);  
    DEFINE vusuario         CHAR(8);
    DEFINE vmoneda          CHAR(2);
    DEFINE vtranret         CHAR(4);
    DEFINE vfechoy          DATE;
    DEFINE vsdodisp         DECIMAL(18,2);
    DEFINE vmontoret        DECIMAL(18,2);
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcomienza     = -1;
    LET ven_transacc  = 0;
    LET vcodret_cargo = '';
    
    LET vsql         = '';
    LET vstmt        = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vaniomes     = '';
    LET vcuenta      = '';
    LET vmonto       = 0.00;
    LET vtransacc    = '';
    LET vdescripcion = '';
    LET vsucursal    = '';
    LET vusuario     = 'informix';
    LET vmoneda      = '01';
    LET vtranret     = '';
    LET vfechoy      = '';
    LET vsdodisp     = 0.00;
    LET vmontoret    = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cargosideesp.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cargosideesp.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxcargaride') THEN
        DROP TABLE "informix".ctasxcargaride;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxcargaride
      (
        aniomes     char(4)     not null,
        cuenta      char(20)    not null,
        sucursal    char(4)     not null,
        monto       money(18,2) not null,
        transacc    char(4)     not null,
        descripcion char(40)    not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctasxcargaride ON "informix".ctasxcargaride(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/cargos_esp_ide.unl DELIMITER ''","'' INSERT INTO ctasxcargaride" > /resplogifx/conciliachq/cargoside.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/cargoside.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxcargaride;
    
    LET vhora = CURRENT HOUR TO FRACTION;
    LET vfolio = vusuario||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];
    
    FOREACH WITH HOLD
        SELECT aniomes, cuenta, sucursal, monto, transacc, descripcion
          INTO vaniomes, vcuenta, vsucursal, vmonto, vtransacc, vdescripcion
          FROM ctasxcargaride
         ORDER BY aniomes, cuenta
        
        IF (vcomienza = -1) THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        CALL cargo_ref( pempresa,       -- empresa
                        vsucursal,      -- sucursal
                        vusuario,       -- usuario
                        vtransacc,      -- transaccion
                        '0000',         -- transacc suc
                        vfolio,         -- folio
                        vcuenta,        -- cuenta
                        0,              -- cheque
                        vmonto,         -- monto
                        vmoneda,        -- divisa
                        vdescripcion,   -- referencia
                        ' ',            -- num tarjeta
                        vusuario )      -- autoriza
        RETURNING vcodret_cargo, vtranret, vfechoy, vsdodisp, vmontoret;
        
        IF vcodret_cargo = '000' THEN
            LET vcontador2 = vcontador2 + 1;
            COMMIT WORK;
            BEGIN WORK;
        ELSE 
            ROLLBACK WORK;
            BEGIN WORK;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        
        LET vaniomes      = '';
        LET vcuenta       = '';
        LET vsucursal     = '';
        LET vmonto        = 0.00;
        LET vtransacc     = '';
        LET vdescripcion  = '';
        LET vcodret_cargo = '';
        LET vtranret      = '';
        LET vfechoy       = '';
        LET vsdodisp      = 0.00;
        LET vmontoret     = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_desbloqmovsret( pempresa CHAR(3), pfechaini DATE, pfechafin DATE )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER, INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE nComit           SMALLINT;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE vsql             CHAR(300);
    DEFINE vstmt            CHAR(100);    
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(16,2);
    DEFINE vfolio           CHAR(20);
    DEFINE vsdo_retenido    MONEY(16,2);
    
    LET vcodret1      = "000";
    LET vcodret2      = "000";
    LET vcodret3      = "PROCESO CONCLUIDO";
    LET sql_err       = 0;
    LET isam_err      = 0;
    LET desc_err      = 0;
    LET nComit        = 0;
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcontador3    = 0;
    LET vsql          = '';
    LET vstmt         = '';
    LET vcuenta       = ''; 
    LET vmonto        = 0.00;
    LET vfolio        = '';
    LET vsdo_retenido = 0.00;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_desbloqmovsret.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF nComit = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_desbloqmovsret.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'movsxdesbloq') THEN
        DROP TABLE "informix".movsxdesbloq;
    END IF;
    
    CREATE RAW TABLE "informix".movsxdesbloq
      (
        cuenta char(20)    not null,
        monto  money(16,2) not null,
        folio  char(16)    not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_movxdesb ON "informix".movsxdesbloq(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/movs_desb_27012013.unl DELIMITER ''","'' INSERT INTO movsxdesbloq" > /resplogifx/conciliachq/movsxdesb.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/movsxdesb.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE movsxdesbloq;
    
    FOREACH WITH HOLD
        SELECT cuenta, monto, folio
          INTO vcuenta, vmonto, vfolio
          FROM movsxdesbloq
                  
        BEGIN WORK;
        LET nComit = 1;
        
        SELECT sdo_retenido
          INTO vsdo_retenido
          FROM sc_maechq
         WHERE empresa = pempresa
           AND cuenta = vcuenta;
           
        IF vmonto <= vsdo_retenido THEN
            UPDATE sc_maechq
               SET sdo_retenido = sdo_retenido - vmonto
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                LET vcontador1 = vcontador1 + 1;
            END IF;
        END IF;
        
        UPDATE sc_docret
           SET cancelado = 'S',
               monto = 0.00
         WHERE fecha_alta BETWEEN pfechaini AND pfechafin
           AND cuenta = vcuenta
           AND monto_ori = vmonto
           AND folio_suc = vfolio;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            LET vcontador2 = vcontador2 + 1;
        END IF;
           
        UPDATE sc_movhis
           SET cancelad = 'S'
         WHERE fech_alt BETWEEN pfechaini AND pfechafin
           AND cuenta = vcuenta
           AND monto_tot = vmonto
           AND folio_suc = vfolio;
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            LET vcontador3 = vcontador3 + 1;
        END IF;
        
        COMMIT WORK;
        LET nComit = 0;
        
        LET vcuenta       = ''; 
        LET vmonto        = 0.00;
        LET vfolio        = '';
        LET vsdo_retenido = 0.00;
    END FOREACH
    
    END;
    
    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2, vcontador3;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cancelatarjeta_chequera()
							
				returning CHAR(5)  AS Cod_Retorno;
										
DEFINE iexiste 			INT;
DEFINE cCodRet 		CHAR(5);
DEFINE iSql_err 		INT;	
DEFINE cNumtarj		CHAR(20);	
DEFINE cNumcte		CHAR(20);			

--inicializando variables
LET  iexiste 			 = 0;
LET cCodRet 	   = "00000";
LET iSql_err 			= 0 ;	
LET cNumtarj			='';
LET cNumcte				='';


BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	--SET DEBUG FILE TO "/informix/VH/chequeras/sp_cancelatarjeta_chequeras.out";
	--TRACE ON;

	FOREACH
		 SELECT num_tarjeta,numcte INTO cNumtarj,cNumcte FROM sc_tarjeta
		 WHERE empresa = '001'
		 AND cuenta IN (SELECT cuenta FROM sc_maechq WHERE empresa='001' AND producto='1900'AND status_cta=2)
		 AND status_tar='A'

		 UPDATE intercard:tarjeta SET codstatustarjeta='CAN',fechaultmodif=CURRENT,usuarioultmodif='informix'
		 WHERE numcliente=cNumcte AND numtarjeta=cNumtarj AND codstatustarjeta='ACT';

		 INSERT INTO intercard:bitacoracancelaciontarjetas (tarjeta,codigoproductotarjeta,fecha,resultado,descripcion,usuario)
		 VALUES (cNumtarj,'501',CURRENT,0,'CANCELACION DE TARJETA','CIERRECH');

		 UPDATE sc_tarjeta SET status_tar='C' WHERE empresa = '001' AND num_tarjeta = cNumtarj and status_tar='A';

	END FOREACH;	
	
	RETURN cCodRet;

END

END PROCEDURE
;

CREATE PROCEDURE "informix".sp_cce_consultar_chequespresentados
(
pEmpresa    CHAR(3),
pFecha      CHAR(8),
pNomArchivo CHAR(22)
)
RETURNING
	CHAR(6) 		AS cod_ret,
	CHAR(3) 		AS banco,
	CHAR(40) 		AS nom_banco,
	CHAR(40) 		AS referencia,
	INTEGER 		AS num_cheque,
	DECIMAL(14,2) 	AS monto_orig,
	CHAR(20) 		AS cuenta,
	CHAR(44) 		AS sucursal,
	CHAR(4) 		AS transacc
	
	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);

	
	DEFINE cBanco			CHAR(3);
	DEFINE cNomBanco		CHAR(40);
	DEFINE cReferencia		CHAR(40);
	DEFINE iNumCheque		INTEGER;
	DEFINE dMontoOrig		DECIMAL(14,2);
	DEFINE cCuenta			CHAR(20);
	DEFINE cSucursal		CHAR(44);
	DEFINE cTransacc		CHAR(4);



	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo			= "";
	LET cCodRet             = "000000";
	
	LET cBanco				= "";
	LET cNomBanco			= "";
	LET cReferencia			= "";
	LET iNumCheque			= 0;
	LET dMontoOrig			= 0.0;
	LET cCuenta				= "";
	LET cSucursal			= "";
	LET cTransacc			= "";


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc WITH RESUME;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
--	SET DEBUG FILE TO '/respaldosbd/has/sp_cce_consultar_chequespresentados.out';
--	TRACE ON;



	IF NVL(pEmpresa,"") = "" OR NVL(pFecha,"") = "" OR NVL(pNomArchivo,"") = "" THEN
        -- FALTAN UNO O MAS PARAMETROS
        LET cCodRet = "000001";
		RETURN cCodRet, cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc WITH RESUME;
	ELSE
        FOREACH WITH HOLD
			SELECT ba.banco, ba.descripcion, doc.referencia, doc.num_chq, doc.monto_ori, doc.cuenta, suc.sucursal || " " || suc.nombre,doc.transacc  
			INTO cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc
			FROM bdicheq:sc_docret_sbc doc, 
                 bdinteg:si_bancos ba, 
                 bdinteg:si_sucursales suc, 
                 bditef:cce_detalle cce
			WHERE doc.empresa = pEmpresa
			AND doc.banco = ba.banco  
			AND doc.sucursal = suc.sucursal  
			AND doc.transacc IN (SELECT transacc FROM bditef:cce_mapeo_cecoban)  
			AND doc.cancelado = "T"
			AND doc.banco = cce.bco_receptor
			AND doc.numcuenta::INT8 = cce.num_cuenta::INT8
			AND doc.num_chq = cce.num_cheque::INTEGER
            AND doc.cuenta = cce.cuenta_dep
			AND cce.fecha_transfer = pFecha  
			AND cce.cod_operacion = "40"
			AND cce.nombrearchivo= pNomArchivo
		
            RETURN cCodRet, cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc WITH RESUME;
        END FOREACH 	
    
	END IF
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso que consulta los cheques presentados a la cámara de compensación eletrónica',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Octubre 2012',
'VERSION: 20121026.1305';

CREATE PROCEDURE "informix".sp_cce_eliminar_cheques
(
pEmpresa	CHAR(3),
pCtaDep		CHAR(20),
pCveBanco	CHAR(3),
pNumCheque	INTEGER,
pMonto		DECIMAL(14,2)
)
		  

RETURNING
	CHAR(6) 		AS cod_ret
	

	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);

	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
	LET cCodRet				= "000000";
	

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/respaldosbd/has/sp_cce_eliminar_cheques.out';
	--TRACE ON;
	
	IF NVL(pEmpresa,"") = "" OR NVL(pCtaDep,"") = "" OR NVL(pCveBanco,"") = "" OR NVL(pNumCheque,0) = 0 OR NVL(pMonto,0.0) = 0.0 THEN
        -- FALTAN LA EMPRESA O LA FECHA
        LET cCodRet = "000001";
	ELSE
		-- ACTUALIZA LA TABLA DE CHEQUES SBC A CANCELADO
		UPDATE bdicheq:"informix".sc_docret_sbc
		SET cancelado = "S"
		WHERE cuenta = pCtaDep
		AND banco = pCveBanco
		AND num_chq = pNumCheque
		AND monto_ori = pMonto;
			  
		-- ACTUALIZA EL IMPORTE DE CHEQUES SBC DEL MAESTRO DE CHEQUES 
		UPDATE bdicheq:"informix".sc_maechq
		SET imp_chq_sbc = imp_chq_sbc - pMonto
		WHERE empresa = pEmpresa 
		AND cuenta = pCtaDep;

	END IF
	
	RETURN cCodRet;
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener los datos de los cheques del código 40', 
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Octubre 2012',
'VERSION: 20121026.1305';

CREATE PROCEDURE "informix".sp_arch_cartera_pyr_pba()
RETURNING CHAR(6);
--Creado por: maria elizabeth anzures ibarguen
--21-03-2012
--Proceso para la generación de archivo cartera reestructura y prestamo personal saldos e intereses

--Declaracion de variables
DEFINE sql_err				INTEGER;
DEFINE isam_err				INTEGER;
DEFINE error_info			CHAR(80);
DEFINE cMensaje				CHAR(80);
DEFINE cCod_ret				CHAR(6);
DEFINE cErrorInfo           CHAR(80);
DEFINE cSQL                 CHAR(2204);
DEFINE cCod_RetIB           CHAR(6);
define pfechacorte 			date;
define Vpri_dia_mes			date;
define Vult_dia_mes			date;
define vproceso				char(4);
--variables
DEFINE Vnumcreditortc       char(20);
DEFINE Vnumcreditotdc       char(20);
DEFINE Vnumcuentartc      	char(20);
DEFINE Vnumtarjetatdc       char(20);
DEFINE Vnumcte        		char(20);
DEFINE Vnumsucursal     	char(4);
DEFINE Vnumciudad			char(4);
DEFINE Vfechareestructura 	date;
DEFINE Vsaldoactual      	decimal(18,2);
DEFINE Vinteres       		decimal(18,2);
DEFINE Vsaldovencido     	decimal(18,2);
DEFINE Vinteresvencido   	decimal(18,2);
DEFINE vinteres_moratorio	decimal(18,2);
DEFINE Vabonobase			decimal(18,2);
DEFINE Vabonosvencidos		smallint;
DEFINE Vestadocredito		char(2);
DEFINE Vplazortc			smallint;
DEFINE Vtasainteres			decimal(18,2);
DEFINE Vfechalimitedepago	date;
DEFINE Vfechaultmov			date;
DEFINE Vtipoultimomov		char(2);
DEFINE Vfechacorte			date;
define cNombreArchivo		char(70);
define cNombreArchivo2		char(70);
define sPaso				integer;
define cempresa				char(3);
define Vprod				char(4);
define vmontor1				decimal(18,2);
define vmontor2				decimal(18,2);

-- SET DEBUG FILE TO "pagosydisposicionescrd.out";
-- TRACE ON; 

--Inicialización de variables
LET sql_err                 = 0;
LET isam_err                = 0;
LET error_info              = "";
LET cCod_Ret                = "000000";
LET cMensaje                = 'PROCESO EXITOSO';
LET cSQL                    = "";
LET cCod_RetIB              = "000000";
let vproceso				='2069';
--variables
LET	Vnumcreditortc			= '';
LET Vnumcreditotdc			= '';
LET Vnumcuentartc			= '';
LET	Vnumtarjetatdc			= '';
LET	Vnumcte           	    = '';
LET	Vnumsucursal			= 0;
LET	Vnumciudad	            = '';
LET Vfechareestructura		= DATE(1);
LET Vsaldoactual			= 0;
LET Vinteres                = 0;
LET Vsaldovencido           = 0;
LET Vinteresvencido         = 0;
LET Vabonobase              = 0;
LET Vabonosvencidos         = 0;
LET vinteres_moratorio		= 0;
LET Vestadocredito          = 0;
LET Vplazortc      			= 0;
LET Vtasainteres   		    = 0;
LET Vfechalimitedepago      = DATE(1);
LET	Vfechaultmov            = DATE(1);
LET Vtipoultimomov          = '';
LET Vfechacorte             = DATE(1);
let cempresa 				= '001';
let Vprod					='';
let vmontor1				= 0;
let vmontor2				= 0;

--LET cNombreArchivo1= 'DirectorioCtesBancoppel' || LPAD(TRIM(DAY(CURRENT::DATE)::CHAR(2)),2,'0') || LPAD(TRIM(MONTH(CURRENT::DATE)::CHAR(2)),2,'0') ||YEAR(CURRENT::DATE) || '.txt';
--LET cNombreArchivo2= 'CifrasControlCarterasPPyRTC' || LPAD(TRIM(DAY(CURRENT::DATE)::CHAR(2)),2,'0') || LPAD(TRIM(MONTH(CURRENT::DATE)::CHAR(2)),2,'0') ||YEAR(CURRENT::DATE) || '.txt';
--LET cNombreArchivo ='cartera_reestructura_prestamo' || LPAD(TRIM(DAY(CURRENT::DATE)::CHAR(2)),2,'0') || LPAD(TRIM(MONTH(CURRENT::DATE)::CHAR(2)),2,'0') ||YEAR(CURRENT::DATE) || '.txt';
        

BEGIN

    ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '02');
        RETURN cCod_ret;
	END EXCEPTION;

	--Directiva para lectura de tablas bloqueadas.
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

    CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '01');
	
	select fecha_hoy, fecha_hoy - 1 units day --fecha_ant, pri_dia_mes 
	into pfechacorte,Vult_dia_mes -- ,Vpri_dia_mes 
	from bdicred:sd_fechas where empresa = '001';
--let pfechacorte = '01-18-2012';
	SELECT COUNT(tabid) INTO sPaso FROM systables WHERE tabname= 'sd_pagosydisposicionescrd_cartera';
            IF NVL(sPaso,0) > 0 THEN
                DROP TABLE sd_pagosydisposicionescrd_cartera;
            END IF;


    create table sd_pagosydisposicionescrd_cartera
    (
	num_producto	char(4),
    numcreditortc	char(20),
    numcreditotdc	char(20),
    numcuentartc	char(20),
	numtarjetatdc   char(20),
	numcte          char(20),
	numsucursal     char(4),
	numciudad		char(4),
    fechareestructura   date,
    saldoactual     decimal(18,2),
    interes       	decimal(18,2),
    saldovencido    decimal(18,2),
    interesvencido  decimal(18,2),
	interes_moratorio	decimal(18,2),
    abonobase           decimal(18,2),
    abonosvencidos      smallint,
    estadocredito       char(2),
    plazortc    		smallint,
    tasainteres    		decimal(18,2),
    fechalimitedepago 	date,
	fechaultmov 		date,
    tipoultimomov		char(2),
    fechacorte          date);
	
	
	if (day(pfechacorte) in(3,18)) then
		let Vprod = '6011'; 	end if;
	if (day(pfechacorte) = 21 ) then
		let Vprod = '6300'; 	end if;
	let Vfechacorte = pfechacorte - 1 units day;
	
	LET cNombreArchivo2= 'CifrasControlCarterasPPyRTC' ||to_char(Vfechacorte,'%d%m%Y')||'.txt';
	LET cNombreArchivo ='cartera_reestructura_prestamo'||to_char(Vfechacorte,'%d%m%Y')||'.txt';
  
	FOREACH
	
	select  nvl(a.num_producto,0),nvl(a.num_credito,0),nvl(a.credito_externo,0),nvl(cta.num_cta,0),nvl(tar.num_tarjeta,0), nvl(a.numcte,0),nvl(a.sucursal,0),nvl(s.ciudad,0),a.fecha_apertura,
			nvl(b.sdo_capital,0) + nvl(b.monto_vencido,0) + nvl(b.mto_venc_trasp,0) + nvl(b.cap_tras_no_venci,0)
			,nvl(b.mto_fin_ven_trasp,0),nvl(a.status_cred,''),nvl(a.plazo,0),nvl(a.tasa_interes,0) ,nvl(c.prox_fecha_pago,'01/01/1900')
			,c.fecha_ult_pago--,today--,(b.sdo_exig_int + b.mto_venc_tra_int)
	INTO 	Vprod,Vnumcreditortc, Vnumcreditotdc, Vnumcuentartc,Vnumtarjetatdc ,Vnumcte,	Vnumsucursal,Vnumciudad, Vfechareestructura ,     
			Vsaldoactual,Vabonosvencidos ,Vestadocredito ,Vplazortc,Vtasainteres,Vfechalimitedepago,
			Vfechaultmov--,   Vfechacorte -- ,Vinteresvencido
	FROM bdicred:sd_maecredcrd a
		left join bdicred:sd_maesdoscrd b on (a.empresa = b.empresa and a.num_credito = b.num_credito)
		left join bdicred:sd_ctascarg cta on(a.num_credito = cta.num_credito and cta.naturaleza = 'A')
		left join bdicred:sd_tarjeta tar on (a.empresa = tar.empresa and a.credito_externo = tar.num_credito and tar.tipo_tarjeta ='T' and tar.secuencia = (select max(tar2.secuencia)
			 			from bdicred:sd_tarjeta tar2
			 			where tar2.empresa = '001' 
						and tar2.num_credito = a.credito_externo
						and tar2.tipo_tarjeta ='T' ))
		left join bdinteg:si_sucursales s on (a.empresa = s.empresa and a.sucursal = s.sucursal)
		left join bdicred:sd_maecredanexocrd c on(a.empresa = c.empresa and a.num_credito = c.num_credito)
	where a.empresa ='001'
		and a.num_producto = Vprod
	
	-------------------------BUSCAR ULTIMO MOVIMIENTO DEL CLIENTE-------------------------
	IF (Vprod = '6300') THEN
		if exists(select num_credito 
			from bdicred:sd_movhiscrd 
			where empresa = '001'
			and num_credito = Vnumcreditortc
			and codigo_ref = 1 and codigo_fun   in ('020','021','022','023','024','025','027','028')
			and fecha_mov = Vfechaultmov --(select max(fecha_mov)from bdicred:sd_movhiscrd )
			AND num_producto = '6300' )then 
	
			LET Vtipoultimomov = 'P';
		elif
		exists(select num_credito 
			from bdicred:sd_movhiscrd 
			where empresa = '001'
			and num_credito = Vnumcreditortc
			and codigo_ref = 3 and codigo_fun  = '001'
			and fecha_mov = (select max(fecha_mov)from bdicred:sd_movhiscrd where codigo_ref = 3 and codigo_fun  = '001' and num_credito = Vnumcreditortc)
			AND num_producto = '6300') then
	
			LET Vtipoultimomov = 'A';
			LET Vfechaultmov = Vfechareestructura;
		elif
		exists(select num_credito 
			from bdicred:sd_movhiscrd 
			where empresa = '001'
			and num_credito = Vnumcreditortc
			and codigo_ref = 66 and codigo_fun  ='002'
			and fecha_mov = (select max(fecha_mov)from bdicred:sd_movhiscrd where codigo_ref = 66 and codigo_fun  ='002' and num_credito = Vnumcreditortc)
			AND num_producto = '6300') then
			
			select LIMIT 1 fecha_mov into  Vfechaultmov
			from bdicred:sd_movhiscrd 
			where empresa = '001'	and num_credito = Vnumcreditortc	and codigo_ref = 66 and codigo_fun  ='002'
			and fecha_mov = (select max(fecha_mov)from bdicred:sd_movhiscrd where codigo_ref = 66 and codigo_fun  ='002' and num_credito = Vnumcreditortc)
			AND num_producto = '6300';
	
			LET Vtipoultimomov = 'D';
			LET Vfechaultmov = Vfechaultmov;
		end if;
	end if;			
	IF (Vprod = '6011') THEN
	
	--obtienes el interes vencido cargado a la reestruc   --intereses moratorios
		select limit 1 nvl(monto,0) into vmontor1
		FROM bdicred:sd_movhis 
		where empresa = '001' and num_credito = Vnumcreditortc 
		and codigo_fun = '338' and codigo_ref = 21 and reversado = 'N'
		and fecha_mov = (select max(fecha_mov) from bdicred:sd_movhis  where num_credito = Vnumcreditortc and codigo_fun = '338' and codigo_ref = 21 and reversado = 'N');
	
		select limit 1 nvl(monto,0) into vmontor2
		FROM bdicred:sd_movhis 
		where empresa = '001' and num_credito = Vnumcreditortc 
		and codigo_fun = '338' and codigo_ref = 22 and reversado = 'N'
		and fecha_mov = (select max(fecha_mov) from bdicred:sd_movhis  where num_credito = Vnumcreditortc and codigo_fun = '338' and codigo_ref = 22 and reversado = 'N'); 
		
		let Vinteres = vmontor1 + vmontor2;
		if   Vinteres is null then let Vinteres = 0; end if;
		
		if exists(select num_credito 
			from bdicred:sd_movhiscrd 
			where empresa = '001'
			and num_credito = Vnumcreditortc
			and codigo_fun in ('225','222')	and codigo_ref = 1
			and fecha_mov = Vfechaultmov --(select max(fecha_mov)from bdicred:sd_movhiscrd )
			AND num_producto = '6011') then
	
			LET Vtipoultimomov = 'P';
		elif
		exists(select num_credito 
			from bdicred:sd_movhiscrd 
			where empresa = '001'
			and num_credito = Vnumcreditortc
			and codigo_ref in(1,2) and codigo_fun  in ('001','002')
			and fecha_mov = (select max(fecha_mov)from bdicred:sd_movhiscrd where codigo_ref in(1,2) and codigo_fun  in ('001','002') and num_credito = Vnumcreditortc)
			AND num_producto = '6011') then
	
			LET Vtipoultimomov = 'A';
			LET Vfechaultmov = Vfechareestructura;
		elif
		exists(select num_credito 
			from bdicred:sd_movhiscrd 
			where empresa = '001'
			and num_credito = Vnumcreditortc
			and codigo_ref = 4 and codigo_fun  ='001'
			and fecha_mov = (select max(fecha_mov)from bdicred:sd_movhiscrd where codigo_ref = 4 and codigo_fun  ='001' and num_credito = Vnumcreditortc) 
			AND num_producto = '6011') then
			
			select LIMIT 1 fecha_mov INTO Vfechaultmov
			from bdicred:sd_movhiscrd 
			where empresa = '001'	and num_credito = Vnumcreditortc	and codigo_ref = 4 and codigo_fun  ='001'
			and fecha_mov = (select max(fecha_mov)from bdicred:sd_movhiscrd where codigo_ref = 4 and codigo_fun  ='001' and num_credito = Vnumcreditortc) 
			AND num_producto = '6011';
			
			LET Vtipoultimomov = 'L';
			LET Vfechaultmov = Vfechaultmov;
		end if;
	end if;
	
	select NVL(monto_vencido,0) + NVL(mto_venc_trasp,0) + NVL(cap_tras_no_venci,0) 
		into Vsaldovencido
	from sd_maesdoscrd 
	where empresa = '001'
		and num_credito = Vnumcreditortc;
	
	select nvl(capital_mto_cuota,0)
	into Vabonobase
	from bdicred:sd_amortiza_creditocrd 
	where num_credito = Vnumcreditortc
		and fecha_cuota = (select max(fecha_cuota) from bdicred:sd_amortiza_creditocrd where num_credito = Vnumcreditortc);
	
	if (Vabonobase = '') then 
		LET Vabonobase = 0; 
	end if;
	
	SELECT nvl(SUM(NVL(interes_debe,0) - NVL(interes_pagado,0)),0),
		       nvl(SUM(NVL(mora_provi_ordi,0) + NVL(mora_provi_cope,0) + NVL(mora_sdo_ordi,0) - NVL(mora_sdo_ordi_pag,0) + NVL(mora_sdo_cope,0) - NVL(mora_sdo_cope_pag,0)),0)
	INTO Vinteresvencido,
		  vinteres_moratorio
	FROM "informix".sd_amortiza_creditocrd
	WHERE empresa     = '001'
		AND num_credito = Vnumcreditortc
		AND capital_status IN ('2','7')
		AND fecha_cuota = (select max(fecha_cuota) from bdicred:sd_amortiza_creditocrd where num_credito = Vnumcreditortc);
	
	INSERT INTO sd_pagosydisposicionescrd_cartera  VALUES
	(Vprod,Vnumcreditortc, Vnumcreditotdc, Vnumcuentartc,	Vnumtarjetatdc ,Vnumcte ,Vnumsucursal,Vnumciudad, 
	Vfechareestructura ,Vsaldoactual  ,Vinteres   ,Vsaldovencido ,Vinteresvencido,vinteres_moratorio,
	Vabonobase ,Vabonosvencidos ,Vestadocredito , Vplazortc ,Vtasainteres , 	
	Vfechalimitedepago, Vfechaultmov ,Vtipoultimomov, Vfechacorte );
	
		LET	Vnumcreditortc			= '';LET Vnumcreditotdc			= '';LET Vnumcuentartc			= '';
	LET	Vnumtarjetatdc			= '';LET	Vnumcte           	    = '';LET	Vnumsucursal			= 0;
	LET	Vnumciudad	            = '';LET Vfechareestructura		= DATE(1);LET Vsaldoactual			= 0;LET Vinteres                = 0;
	LET Vsaldovencido           = 0;LET Vinteresvencido         = 0;LET Vabonobase              = 0;LET Vabonosvencidos         = 0;
	LET vinteres_moratorio		= 0;LET Vestadocredito          = 0;LET Vplazortc      			= 0;LET Vtasainteres   		    = 0;
	LET Vfechalimitedepago      = DATE(1);LET	Vfechaultmov            = DATE(1);LET Vtipoultimomov          = '';
	let vmontor1				= 0;let vmontor2				= 0;
				
	END FOREACH

	if (day(pfechacorte) in(3,18,21)) then --CREAR  ARCHIVO
	
		 
             LET cSql = '';
             LET cSql = 'echo "UNLOAD TO ' || '''/resplogifx/archivoscartera/Pagos1.unl''' || ' DELIMITER ' || '''|'''  ||
                ' select * from sd_pagosydisposicionescrd_cartera;'||
                ' " > /resplogifx/archivoscartera/Pagosydisposiciones2crd.sql';

              SYSTEM cSql;

              LET cSql = '';
              LET cSql = 'dbaccess bdicred /resplogifx/archivoscartera/Pagosydisposiciones2crd.sql';
              SYSTEM cSql;

              LET cSql = '';
              LET cSql = "sed 's/|$//g' /resplogifx/archivoscartera/Pagos1.unl > /resplogifx/archivoscartera/" || trim(cNombreArchivo);
              SYSTEM cSql;

              let cSql = '';
              LET cSql = "rm /resplogifx/archivoscartera/Pagos1.unl /resplogifx/archivoscartera/Pagosydisposiciones2crd.sql";
              SYSTEM cSql;
	
	
		 -- para Generar el archvio de Cifras.
             LET cSql = '';
             LET cSql = 'echo "UNLOAD TO ' || '''/resplogifx/archivoscartera/DirectorioCifrasControlRegistros.unl''' || ' DELIMITER ' || '''|'''  ||
                ' SELECT count(*)::integer, sum(saldoactual), sum(saldovencido), fechacorte  FROM bdicred:sd_pagosydisposicionescrd_cartera group by fechacorte ' ||
                ' " > /resplogifx/archivoscartera/DirectorioCifrasControlQuerys.sql';

              SYSTEM cSql;

              LET cSql = '';
              LET cSql = 'dbaccess bdicred /resplogifx/archivoscartera/DirectorioCifrasControlQuerys.sql';
              SYSTEM cSql;

              LET cSql = '';
              LET cSql = "sed 's/|$//g' /resplogifx/archivoscartera/DirectorioCifrasControlRegistros.unl > /resplogifx/archivoscartera/" || trim(cNombreArchivo2);
              SYSTEM cSql;

              let cSql = '';
              LET cSql = "rm /resplogifx/archivoscartera/DirectorioCifrasControlRegistros.unl /resplogifx/archivoscartera/DirectorioCifrasControlQuerys.sql";
              SYSTEM cSql;

	end if;

	
	CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '03');

	RETURN cCod_ret;

	
END;
END PROCEDURE;

CREATE PROCEDURE "informix".cierrechqinvcrec_pba(pempresa CHAR(3))
RETURNING CHAR(5);
     
    DEFINE GLOBAL vgusuario             CHAR(8)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_hoy           DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgprox_fecha          DATE        DEFAULT " ";
    DEFINE GLOBAL vgtrans_pag_int       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtransisr            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranprov            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrevprov         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranabotrasp        CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrecrece         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgProdCreciente       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgstatus_cta          CHAR(1)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_mod           DATE        DEFAULT " ";
    DEFINE GLOBAL vgfecha_alta          DATE        DEFAULT " ";
    DEFINE GLOBAL vginstrucc            CHAR(2)     DEFAULT " ";
    DEFINE GLOBAL vgcuentadep           CHAR(20)    DEFAULT " ";

    DEFINE vcodret                      CHAR(5);
    DEFINE vcodret2                     CHAR(5);
    DEFINE vcodret3                     CHAR(40);
    DEFINE vsqlerr                      INTEGER;
    DEFINE isam_err                     INTEGER;
    DEFINE error_info                   CHAR(40);
    DEFINE vfechahora                   CHAR(40);
    DEFINE vsql                         CHAR(600);
    DEFINE vstmt                        CHAR(250);
    DEFINE vsistema                     CHAR(2);
    DEFINE vproceso                     CHAR(20);
    DEFINE vstatuscierreinv             CHAR(1);
    DEFINE vstatuscobroreestruc         CHAR(1);
    DEFINE vProdChequeras               CHAR(4);
    DEFINE vexiste                      CHAR(1);
    DEFINE vexiste2                     INTEGER;
    DEFINE vexistefin                   INTEGER;
    DEFINE vdias                        INTEGER;
    DEFINE vregproc                     INTEGER;
    DEFINE vporcentajerror              INTEGER;
    DEFINE vfcuenta                     CHAR(20);
    DEFINE FechaProc                    DATE;
    DEFINE vProducto                    CHAR(4);
    DEFINE vSdoActual                   DECIMAL(14,2);
    DEFINE vSucursal                    CHAR(4);
    DEFINE vcontvalcie                  INTEGER;
    DEFINE vregistros                   INTEGER;
    DEFINE vcuenta                      CHAR(20);
    DEFINE vProdChequerasPM             CHAR(4);
    DEFINE vdia                         CHAR(2);
    DEFINE vfecha_pago                  DATE;
    DEFINE vnumdias                     SMALLINT;
    DEFINE vexiste_cta                  SMALLINT;
    DEFINE vhora            		    DATETIME HOUR TO FRACTION;
    DEFINE vfolio_suc       		    CHAR(16);
    DEFINE vint_acum                    MONEY(14,2);
    DEFINE vfecultdep                   DATE;
    DEFINE vdiasinact                   INTEGER;
    DEFINE vabierto                     CHAR(1);
    DEFINE vaniomes                     CHAR(6);
    DEFINE vexiste_proy                 SMALLINT;
    DEFINE vtotsuc                      INTEGER;
    DEFINE vcontproc                    INTEGER;
    DEFINE vtfechaxxx                   DATE;
    DEFINE vnum_cte                     CHAR(20);
    DEFINE vfecha_alta                  DATE;
    DEFINE vhoraw           		    CHAR(15);
    DEFINE vfecha_mod                   DATE;
    DEFINE vcuentafin                   CHAR(20);

    LET vgusuario       = USER;
    LET vgfecha_hoy     = ' ';
    LET vgpri_dia_mes   = ' ';
    LET vgpri_hab_mes   = ' ';
    LET vgult_dia_mes   = ' ';
    LET vgult_hab_mes   = ' ';
    LET vgprox_fecha    = ' ';
    LET vgtrans_pag_int = ' ';
    LET vgtransisr      = ' ';
    LET vgtranprov      = ' ';
    LET vgtranrevprov   = ' ';
    LET vgtranabotrasp  = ' ';
    LET vgtranrecrece   = ' ';
    LET vgProdCreciente = ' ';
    LET vgstatus_cta    = ' ';
    LET vgfecha_mod     = ' ';
    LET vgfecha_alta    = ' ';

    LET vcodret              = "000";
    LET vcodret2             = "000";
    LET vcodret3             = "000";
    LET vsqlerr              = 0;
    LET isam_err             = 0;
    LET error_info           = '';
    LET vfechahora           = " ";
    LET vsql                 = '';
    LET vstmt                = '';
    LET vsistema             = "01";
    LET vproceso             = "cierrechqinvcrec";
    LET vstatuscierreinv     = '';
    LET vstatuscobroreestruc = '';
    LET vProdChequeras       = '';
    LET vexiste              = '';
    LET vexiste2             = 0;
    LET vexistefin           = 0;
    LEt vdias                = 0;
    LET vregproc             = 0;
    LET vporcentajerror      = 0;
    LET vfcuenta             = '';
    LET FechaProc            = '';
    LET vProducto            = '';
    LET vSdoActual           = 0.00;
    LET vSucursal            = '';
    LET vcontvalcie          = 0;
    LET vregistros           = 0;
    LET vcuenta              = '';
    LET vProdChequerasPM     = '';
    LET vdia                 = '';
    LET vfecha_pago          = '';
    LET vnumdias             = 0;
    LET vexiste_cta          = 0;
    LET vhora                = '';
    LET vfolio_suc           = '';
    LET vint_acum            = 0.00;
    LET vfecultdep           = '';
    LET vdiasinact           = 0;
    LET vabierto             = '0';
    LET vaniomes             = '';
    LET vexiste_proy         = 0;
    LET vtotsuc              = 0;
    LET vcontproc            = 0;
    LET vtfechaxxx           = '';
    LET vnum_cte             = '';
    LET vfecha_alta          = '';
    LET vhoraw               = '';
    LET vfecha_mod           = '';
    LET vcuentafin           = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcrec.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            LET vfechahora = CURRENT;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
            SYSTEM vstmt;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcrec.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    ---SET PDQPRIORITY 10;
    
    -- // ##################################### //
    -- // #  FECHAS DEL SISTEMA DE CAPTACION  # //
    -- // ##################################### //
    SELECT fecha_hoy, pri_dia_mes, pri_hab_mes, ult_dia_mes, ult_hab_mes, prox_fecha
      INTO vgfecha_hoy, vgpri_dia_mes, vgpri_hab_mes, vgult_dia_mes, vgult_hab_mes, vgprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- // ###################################### //
    -- // #  TRANSACCION DE PAGO DE INTERESES  # //
    -- // ###################################### //
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";

    -- // ################################# //
    -- // #  TRANSACCION DE COBRO DE ISR  # //
    -- // ################################# //
    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";

    -- // ########################################### //
    -- // #  TRANSACCION DE PROVISION DE INTERESES  # //
    -- // ########################################### //
    SELECT valor
      INTO vgtranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";

    -- // ############################################## //
    -- // #  TRANSACCION DE DESPROVISION DE INTERESES  * //
    -- // ############################################## //
    SELECT valor
      INTO vgtranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";

    -- // ######################################## //
    -- // #  TRANSACCION DE ABONO PARA TRASPASO  # //
    -- // ######################################## //
    SELECT valor
      INTO vgtranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";

    -- // ############################################# //
    -- // #  TRANSACCION DE REINVERSION DE INVS CREC  # //
    -- // ############################################# //
    SELECT valor
      INTO vgtranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";

    -- // ################################## //
    -- // #  Producto Inversion Creciente  # //
    -- // ################################## //
    SELECT valor
      INTO vgProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";

    -- // ########################### //
    -- // #  Producto de Chequeras  # //
    -- // ########################### //
    SELECT valor
      INTO vProdChequeras
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
       
    -- // ####################################### //
    -- // #  Producto de Chequeras Empresarial  # //
    -- // ####################################### //
    SELECT valor
      INTO vProdChequerasPM
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqpm";   
    
    -- // ############################################################## //
    -- // #  VALIDA QUE NO SE HAYA REALIZADO EL CIERRE DEL DIA ACTUAL  # //
    -- // ############################################################## //
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgfecha_hoy
       AND sistema = vsistema;

    IF vexiste2 = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vgfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horacierrecrec.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
            SYSTEM vsql; 
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
            SYSTEM vstmt;
        ELSE
            SELECT 1
              INTO vexiste
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = 'cierreinvcrec'
               AND fecha = vgfecha_hoy;

            IF vexiste = "1" THEN
                LET vcodret = "966";
                RETURN vcodret;
            END IF            
        END IF
    END IF;
    
    -- // ################################################## //
    -- // #  VALIDA HAYA FINALIZADO CIERRE DE INVERSIONES  # // 
    -- // ################################################## //
    SELECT status_proc
      INTO vstatuscierreinv
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'CierreInv'
       AND fecha   = vgfecha_hoy
       AND sistema = '03';
        
    IF vstatuscierreinv is null OR vstatuscierreinv <> 'F' THEN
        LET vcodret = "959";
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vgusuario||''','||
                   'status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vgfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
        SYSTEM vstmt;
        RETURN vcodret;
    END IF
    
    -- // ################################################## //
    -- // #  VALIDA HAYA FINALIZADO COBRO DE REESTRUCTURA  # //
    -- // ################################################## //
    SELECT status_proc
      INTO vstatuscobroreestruc
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'CobroAutRe'
       AND fecha   = vgfecha_hoy
       AND sistema = '06';
    
    IF vstatuscobroreestruc is null OR vstatuscobroreestruc <> 'F' THEN
        LET vcodret = "954";
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vgusuario||''','||
                   'status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vgfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
        SYSTEM vstmt;
        RETURN vcodret;
    END IF

    -- // ############################################################### //
    -- // #  VALIDA SE HAYA REALIZADO EL RESPALDO DE TABLAS DE CHEQUES  # //
    -- // ############################################################### //
    SELECT 1
      INTO vexiste
      FROM sc_contproc
     WHERE empresa = pempresa
       AND proceso = "respacie"
       AND fecha = vgfecha_hoy;

    IF vexiste is null THEN
        LET vcodret = "965";
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vgusuario||''','||
                   'status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vgfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
        SYSTEM vstmt;
        RETURN vcodret;
    END IF
    
    -- // ########################################################### //
    -- // # VALIDA SE HAYA EFECTUADO EL PASE CONTABLE EN SUCURSALES # //
    -- // ########################################################### //
    SELECT count(*) 
      INTO vtotsuc
      FROM bdinteg:si_sucursales su
     WHERE empresa = pempresa
       AND tpo_sucursal = "01"
       AND not exists (SELECT fecha 
                         FROM bdinteg:si_feriadsuc fs
                        WHERE fs.empresa = pempresa
                          AND fecha = vgfecha_hoy
                          AND su.sucursal = fs.sucursal);
    
    SELECT count(*)
      INTO vcontproc
      FROM bdisuc:ss_contproc
     WHERE fecha = vgfecha_hoy
       AND proceso = "pase";

    -- // ######################################################## //
    -- // # REVERSA DESGLOSE DE MOVIMIENTOS CUANDO NO HAY MOVDIA # //
    -- // ######################################################## //
    FOREACH
        SELECT {+INDEX(sc_docret idx_sc_docret4)} cuenta, folio_suc
          INTO vcuenta, vfolio_suc
          FROM sc_docret
         WHERE siglas = "SC"
           AND fecha_alta = vgfecha_hoy
           AND cancelado <> "S"
         GROUP BY 1,2

        LET vexiste2 = 0;

        SELECT count(*)
          INTO vexiste2
          FROM sc_movdia
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND folio_suc = vfolio_suc
           AND cancelad <> "S";

        IF vexiste2 is null OR vexiste2 = 0 THEN
            -- // Verifica que se haya procesado esta cuenta
            SELECT fecha_proceso
              INTO vtfechaxxx
              FROM sc_maechq
             WHERE empresa = pempresa
               AND cuenta = vcuenta;

            IF vtfechaxxx = vgfecha_hoy THEN
                UPDATE sc_docret
                   SET cancelado = "S"
                 WHERE cuenta = vcuenta
                   AND folio_suc = vfolio_suc
                   AND fecha_alta = vgfecha_hoy;
            END IF
        END IF
        
        LET vcuenta    = '';
        LET vfolio_suc = '';
        LET vtfechaxxx = '';
    END FOREACH;
    
    -- // ######################################################### //
    -- // #  GUARDA HISTORIAL DE VALCIERRE E INICIALIZA LA TABLA  # //
    -- // ######################################################### //
    SELECT count(*)
      INTO vcontvalcie
      FROM sc_valcierre
     WHERE empresa = pempresa
       AND cuenta <> '';

    IF vcontvalcie <> 0 THEN
        INSERT INTO sc_valcierre_his
        SELECT a.*, b.fecha_ant
          FROM sc_valcierre a,
               sc_fechas b
         WHERE a.empresa = pempresa
           AND a.cuenta <> ''
           AND b.empresa = a.empresa;

        DELETE FROM sc_valcierre
         WHERE empresa = pempresa
           AND cuenta <> '';
    END IF

    -- // ####################################### //
    -- // #  OBTIENE NUMERO DE DIAS A PROCESAR  # //
    -- // ####################################### //
    IF vgfecha_hoy = vgult_hab_mes THEN
        LET vdias = vgult_dia_mes - vgfecha_hoy + 1;

        IF vgprox_fecha > vgult_dia_mes THEN
            LET vdias = vdias + ((vgprox_fecha-1) - vgult_dia_mes);
        END IF
    ELSE
        LET vdias = vgprox_fecha - vgfecha_hoy;
    END IF

    -- // ############################################ //
    -- // #  OBTIENE NUMERO DE REGISTROS A PROCESAR  # //
    -- // ############################################ //
    SELECT COUNT(*)
      INTO vregproc
      FROM sc_maechq
     WHERE producto = vgProdCreciente
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy);

    -- // ########################################################### //
    -- // #  Obtiene parametro de porcentajes de error por proceso  # //
    -- // ########################################################### //
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
       
    -- // ######################################### //
    -- // #  OBTIENE RANGO DE CUENTAS A PROCESAR  # //
    -- // ######################################### //
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp1'; 
       
    -- // ####################################### //
    -- // # ACTUALIZA BANDERA PARA COMPLEMENTOS # //
    -- // ####################################### //
    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = 'inicio_cierreinvcrec';
       
    /* ##################################################################################################################
    -- // #################################################################################### //
    -- // #  FOREACH INVERSIONES CRECIENTES QUE VENCEN Y TIENEN MAS DE 2 AÑOS DE ANTIGUEDAD  # //
    -- // #################################################################################### //
    FOREACH WITH HOLD 
        SELECT mae.cuenta, mae.num_cte, mae.fecultdep, noc.fecha_alta, noc.fecha_mod
          INTO vfcuenta, vnum_cte, vfecultdep, vfecha_alta, vgfecha_mod
          FROM sc_maechq mae,
               sc_maenoc noc
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta NOT IN("2","6","7","8")
           AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vgfecha_hoy )
           AND mae.cuenta < vcuentafin
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        BEGIN WORK;
        LET vabierto = '1';
        
        IF vfecultdep is null OR vfecultdep = '' THEN
            LET vfecultdep = vfecha_alta;
        END IF;
        
        LET vdiasinact = vgfecha_hoy - vfecultdep;
        
        IF vdiasinact >= 1060 THEN  
            LET vfecha_mod = vgfecha_mod;
            LET vfecha_mod = vfecha_mod - 1 UNITS DAY;
                    
            EXECUTE PROCEDURE "informix".sp_valfechabil(vfecha_mod, '-') 
            INTO vcodret, vfecha_mod;
            
            IF (vfecha_mod = vgfecha_hoy) THEN            
                -- // Obtiene instrucciones de la inversión creciente
                SELECT LIMIT 1 cuentadep
                  INTO vgcuentadep
                  FROM sc_maeinstrucc
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta
                   AND capint = "R";   
                
                SELECT COUNT(*)
                  INTO vexiste_cta
                  FROM sc_maechq
                 WHERE cuenta = vgcuentadep
                   AND status_cta IN('1','4','5')
                   AND ( fecha_proceso is null OR fecha_proceso = "" OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy );
                
                IF vexiste_cta = 0 THEN
                    SELECT LIMIT 1 cuenta
                      INTO vgcuentadep
                      FROM sc_maechq
                     WHERE status_cta IN('1','4','5')
                       AND ( fecha_proceso is null OR fecha_proceso = "" OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy )
                       AND producto <> vgProdCreciente
                       AND num_cte = vnum_cte;
                END IF;
                
                IF vgcuentadep is not null OR vgcuentadep <> '' THEN
                    UPDATE sc_maeinstrucc
                       SET instrucc = '02',
                           cuentadep = vgcuentadep
                     WHERE empresa = pempresa
                       AND cuenta = vfcuenta; 
                END IF;
            END IF;
        END IF;
        
        COMMIT WORK;
        LET vabierto = '0';
        
        LET vfcuenta    = '';
        LET vnum_cte    = '';
        LET vfecultdep  = '';
        LET vfecha_alta = '';
        LET vgfecha_mod = '';
        LET vdiasinact  = 0;
        LET vfecha_mod  = '';
        LET vgcuentadep = '';
        LET vexiste_cta = 0;
    END FOREACH;  
    ################################################################################################################## */
    
    -- // ################################################################### //
    -- // #  FOREACH INVERSIONES CRECIENTES CON INSTRUCCIONES DE TRASPASOS  # //
    -- // ################################################################### //
    FOREACH WITH HOLD 
        SELECT mae.cuenta, mae.fecha_proceso, mae.producto, mae.sdo_actual, mae.status_cta, mae.sucursal, noc.fecha_alta
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal, vfecha_alta
          FROM sc_maechq mae,
               sc_maenoc noc,
               sc_maeinstrucc ins
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta NOT IN("2","6","7","8")
           AND mae.fecha_proceso = vgfecha_hoy
           AND mae.cuenta < vcuentafin
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           AND ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.instrucc IN('02','03','04')
           AND ins.capint = "R"
           
        LET vdia = DAY(vfecha_alta);
        
        CALL calcula_fechapago(vgfecha_hoy, 0, vdia)
        RETURNING vcodret, vfecha_pago, vnumdias;
        
        IF vdia = 1 THEN
            CALL monthadd(vfecha_pago, 1) 
            RETURNING vfecha_pago;
        ELIF vdia = 2 AND vgfecha_hoy = '12'||'31'||YEAR(vgfecha_hoy) THEN
            CALL monthadd(vfecha_pago, 1)
            RETURNING vfecha_pago;
        ELSE
            LET vfecha_pago = vgfecha_hoy + vnumdias;
        END IF;

        IF NOT(vdia > DAY(vgult_dia_mes) OR vdia < 1) THEN
            LET vfecha_pago = vfecha_pago - 1;
        END IF
        
        IF ( ( vfecha_pago >= vgfecha_hoy AND vfecha_pago < vgprox_fecha ) AND ( vfecha_alta <> vgfecha_hoy ) ) THEN
            -- // Obtiene instrucciones de la inversión creciente
            SELECT instrucc, cuentadep
              INTO vginstrucc, vgcuentadep
              FROM sc_maeinstrucc
             WHERE empresa = pempresa
               AND cuenta = vfcuenta
               AND capint = "R";     
            
            -- // Verifica Fecha de Vencimiento para cuentas crecientes
            SELECT nvl(fecha_mod, vgfecha_hoy), nvl(fecha_alta, vgfecha_hoy)
              INTO vgfecha_mod, vgfecha_alta
              FROM sc_maenoc
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            -- // Actualiza la fecha como ya procesado si vencio su plazo
            IF vgfecha_mod < vgfecha_hoy THEN
                UPDATE sc_maechq
                   SET fecha_proceso = vgprox_fecha
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                CONTINUE FOREACH;
            END IF

            CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
            RETURNING vcodret;

            IF vcodret <> "000" THEN
                -- // Conteo de Errores generados por el cierre
                SELECT COUNT(*)
                  INTO vcontvalcie
                  FROM sc_valcierre
                 WHERE empresa = pempresa
                   AND cuenta <> '';

                LET vregistros = ROUND(vregproc * vporcentajerror / 100);

                IF vcontvalcie <= vregistros THEN
                    CONTINUE FOREACH;
                ELSE
                    LET vcodret = "997";

                    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                               'SET ejecutivo = '''||vgusuario||''','||
                               'status_proc   = '''||'C'||''','||
                               'codret        = '''||vcodret||''','||
                               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                               'WHERE empresa = '''||pempresa||''' '||
                               'AND proceso   = '''||vproceso||''' '||
                               'AND fecha     = '''||vgfecha_hoy||''' '||
                               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
                    SYSTEM vsql;
                    
                    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
                    SYSTEM vstmt;

                    RETURN vcodret;
                END IF;
            END IF;
        END IF;
        
        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
        LET vfecha_alta  = '';
        LET vdia         = '';
        LET vfecha_pago  = '';
        LET vnumdias     = 0;
    END FOREACH;  
    
    
    -- // ######################################################################### //
    -- // #  FOREACH PRINCIPAL DEL CIERRE DE CAPTACION DE INVERSIONES CRECIENTES  # //
    -- // ######################################################################### //
    FOREACH principal WITH HOLD FOR
        SELECT cuenta, fecha_proceso, producto, sdo_actual, status_cta, sucursal
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal
          FROM sc_maechq
         WHERE producto = vgProdCreciente
           AND status_cta not in( "2", "6", "7", "8" )
           AND ( fecha_proceso is null OR fecha_proceso = "" OR fecha_proceso = vgfecha_hoy )
           AND cuenta < vcuentafin
           
        -- // Obtiene instrucciones de la inversión creciente
        SELECT instrucc, cuentadep
          INTO vginstrucc, vgcuentadep
          FROM sc_maeinstrucc
         WHERE empresa = pempresa
           AND cuenta = vfcuenta
           AND capint = "R";

        IF FechaProc IS NULL THEN
            IF vSdoActual = 0 THEN
                UPDATE sc_maechq
                   SET status_cta = "2",
                       fecha_proceso = vgfecha_hoy
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                LET vcodret = "000";

                CONTINUE FOREACH;
            ELSE
                CALL creciente_proy_cierre(pempresa, vfcuenta, vProducto, vSdoActual, vginstrucc)
                RETURNING vcodret;

                IF vcodret <> "000" THEN
                    CONTINUE FOREACH;
                END IF
            END IF
        END IF

        -- // Verifica Fecha de Vencimiento para cuentas crecientes
        SELECT nvl(fecha_mod, vgfecha_hoy), nvl(fecha_alta, vgfecha_hoy)
          INTO vgfecha_mod, vgfecha_alta
          FROM sc_maenoc
         WHERE empresa = pempresa
           AND cuenta = vfcuenta;

        -- // Actualiza la fecha como ya procesado si vencio su plazo
        IF vgfecha_mod < vgfecha_hoy THEN
            UPDATE sc_maechq
               SET fecha_proceso = vgprox_fecha
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            CONTINUE FOREACH;
        END IF
        
        CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT COUNT(*)
              INTO vcontvalcie
              FROM sc_valcierre
             WHERE empresa = pempresa
               AND cuenta <> '';

            LET vregistros = ROUND(vregproc * vporcentajerror / 100);

            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                           'SET ejecutivo = '''||vgusuario||''','||
                           'status_proc   = '''||'C'||''','||
                           'codret        = '''||vcodret||''','||
                           'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                           'WHERE empresa = '''||pempresa||''' '||
                           'AND proceso   = '''||vproceso||''' '||
                           'AND fecha     = '''||vgfecha_hoy||''' '||
                           'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
                SYSTEM vsql;
                LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
                SYSTEM vstmt;
                RETURN vcodret;
            END IF;
        END IF;

        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
    END FOREACH;
    
    
    -- // ####################################################### //
    -- // #  Actualiza Cuentas Crecientes Canceladas en el Dia  # //
    -- // ####################################################### //
    FOREACH
        SELECT a.cuenta, b.fecha_alta
          INTO vfcuenta, FechaProc
          FROM sc_maechq a,
               sc_maenoc b
         WHERE a.empresa = pempresa
           AND a.status_cta = "2"
           AND a.producto = vgProdCreciente
           AND (a.fecha_proceso = vgfecha_hoy OR a.fecha_proceso IS NULL)
           ---AND b.empresa = a.empresa
           AND b.cuenta = a.cuenta

        IF FechaProc IS NULL THEN
           UPDATE sc_maechq
              SET fecha_proceso = vgfecha_hoy
            WHERE empresa = pempresa
              AND cuenta = vfcuenta;
	    END IF;

        LET vfcuenta   = '';
        LET FechaProc  = '';
    END FOREACH;
    
    
    -- // ########################################################### //
    -- // #  Desprovisiona Cuentas Crecientes Canceladas en el Dia  # //
    -- // ########################################################### //   
    LET vhora = current hour to fraction;
    LET vhoraw = vhora;
    LET vfolio_suc = 'informix'||vhoraw[1,2]||vhoraw[4,5]||vhoraw[7,8]||vhoraw[10,11];
    LET vaniomes = YEAR(vgfecha_hoy)||LPAD(MONTH(vgfecha_hoy),2,'0');
    
    FOREACH
        SELECT {+INDEX(sc_maenoc noc1)} a.cuenta, a.sucursal, a.producto, a.status_cta, b.int_acum
          INTO vcuenta, vSucursal, vProducto, vgstatus_cta, vint_acum
          FROM sc_maechq a,
               sc_maenoc b
         WHERE a.empresa = pempresa
           AND a.status_cta = '2'
           AND a.producto = vgProdCreciente
           AND a.fecha_proceso = vgfecha_hoy
           ---AND b.empresa = a.empresa
           AND b.cuenta = a.cuenta
           
        IF vint_acum > 0 THEN
            INSERT INTO sc_movdia VALUES
            ( 0, vfolio_suc, vSucursal, 'informix', vgfecha_hoy, vgfecha_hoy, vhora, vgtranrevprov, vSucursal, vProducto, 
              pempresa, vcuenta, '', 0, vint_acum, vint_acum, 0, 0, 0, '', vgstatus_cta, 0, '0000', ' ', 0, ' ', '' );
        END IF;
        
        SELECT COUNT(*)
          INTO vexiste_proy
          FROM sc_tasa_variable
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND tipo_tasa IN('M','P');
           
        IF vexiste_proy > 0 THEN
            INSERT INTO sc_tasa_var_hist 
            SELECT vaniomes, var.*
              FROM sc_tasa_variable var
             WHERE var.empresa = pempresa
               AND var.cuenta = vcuenta
               AND var.tipo_tasa IN('M','P');
               
            DELETE FROM sc_tasa_variable
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND tipo_tasa IN('M','P');
        END IF;
	    
        LET vcuenta      = '';
        LET vSucursal    = '';
        LET vProducto    = '';
        LET vgstatus_cta = '';
        LET vint_acum    = 0.00;
        LET vexiste_proy = 0;
    END FOREACH;
    
    
    -- // ############################ //
    -- // #  Registra fin de cierre  # //
    -- // ############################ //
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vgfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec.sql';
    SYSTEM vsql;

    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec.sql';
    SYSTEM vstmt;

    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreinvcrec";

    SET LOCK MODE TO NOT WAIT;

    RETURN vcodret;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION:   Cierre Diario del Producto de Inversion Creciente de Captacion ',
'EJECUTADO POR: Control-M',
'AUTOR:         JICS',
'FECHA:         20/Febrero/2013',
'VERSION:       1.00.0000',
'Base de Datos: bdicheq';

CREATE PROCEDURE "informix".actchequessbc( pempresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;
    
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
	DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE vabierto     CHAR(1);
    DEFINE vcomienza    SMALLINT;
    DEFINE vcontador1   INTEGER;
    DEFINE vcontador2   INTEGER;
	DEFINE vcontador3   INTEGER;
    DEFINE vmonto       MONEY(14,2);
    DEFINE vreferencia  CHAR(40);
    DEFINE vdocto       INTEGER;
    DEFINE vcuenta      CHAR(20);
    DEFINE vfecha_alta  DATE;
    DEFINE vcvebconew   CHAR(3);
    DEFINE vrefnew      CHAR(20);
    DEFINE vcvebanco    CHAR(3);
    DEFINE vnumcuenta   CHAR(20);
    DEFINE vdctabco     DECIMAL(20,0);
    DEFINE vcctabco     CHAR(20);
    
    LET sql_err	   = 0;
    LET isam_err   = 0;
    LET desc_err   = '';
	LET vcodret1   = '';
    LET vcodret2   = '';
    LET vcodret3   = '';
    LET vabierto   = '0';
    LET vcomienza  = -1;
    LET vcontador1 = 0;
    LET vcontador2 = 0;
	LET vcontador3 = 0;
    LET vmonto       = 0.00;
    LET vreferencia  = '';
    LET vdocto       = 0;
    LET vcuenta      = '';
    LET vfecha_alta  = '';
    LET vcvebconew   = '';
    LET vrefnew      = '';
    LET vcvebanco    = '';
    LET vnumcuenta   = '';
    LET vdctabco = 0;
    LET vcctabco = '';
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/actchequessbc.err";
        TRACE ON;
        IF sql_err <> 0 THEN
			LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/actchequessbc.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE EL NUMERO TOTAL DE REGISTROS A DEPURAR
    SELECT COUNT(empresa)
      INTO vcontador1
      FROM sc_docret_sbc 
     WHERE siglas IN('SC','SD')  
       AND transacc IN('0250','6250')
       AND cancelado <> "T"
       AND NVL(banco,"") = ""
       AND NVL(numcuenta,"") = "";
    
    -- // DEPURA REGISTROS DE LA sc_docret_sbc
    FOREACH WITH HOLD 
        SELECT monto_ori, referencia, num_chq, cuenta, fecha_alta
          INTO vmonto, vreferencia, vdocto, vcuenta, vfecha_alta
          FROM sc_docret_sbc 
         WHERE siglas IN('SC','SD')  
           AND transacc IN('0250','6250')
           AND cancelado <> "T"
		   AND NVL(banco,"") = ""
           AND NVL(numcuenta,"") = ""
           
		IF vcontador3 = 0 THEN
			BEGIN WORK;
			LET vabierto = '1'; 
		END IF
        
        LET vcvebconew = vreferencia[1,3]; 
        LET vcvebconew = vcvebconew;
        
        LET vrefnew = vreferencia[6,25]; 
        LET vdctabco = vrefnew::decimal(20,0);
        let vcctabco = vdctabco;
        let vcctabco = trim(vcctabco);
        
        /*
        SELECT cvebanco, numcuenta
          INTO vcvebanco, vnumcuenta
          FROM bditef:cce_cheques_det
         WHERE fecha_alta = '10/11/2012'
           AND cvebanco = vcvebconew
           AND lpad(trim(numcuenta),20,"0") = vrefnew
           AND numcheque = vdocto
           AND monto = vmonto;
        */
           
        UPDATE sc_docret_sbc
           SET banco = vcvebconew,
               numcuenta = vcctabco
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND fecha_alta = vfecha_alta
           AND referencia = vreferencia
           AND num_chq = vdocto
           AND monto_ori = vmonto;
        
        LET vcontador2 = vcontador2 + 1;

		LET vcontador3 = vcontador3 + 1;
        
		IF vcontador3 = 5000 THEN
			LET vabierto = '0';
			LET vcontador3 = 0;
			COMMIT WORK;
		END IF
        
        LET vmonto       = 0.00;
        LET vreferencia  = '';
        LET vdocto       = 0;
        LET vcuenta      = '';
        LET vfecha_alta  = '';
        LET vcvebconew   = '';
        LET vrefnew      = '';
        LET vcvebanco    = '';
        LET vnumcuenta   = '';
        LET vdctabco = 0;
        LET vcctabco = '';
    END FOREACH;
    
	IF vabierto = '1' THEN
		COMMIT WORK;
	END IF
	
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
    
    END;
    
    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ctes_captacion_pba()
RETURNING CHAR(5);
    
    DEFINE vcodret          CHAR(5);
    DEFINE vsqlerr          INTEGER;  
    DEFINE vsql             CHAR(600);
	DEFINE vfecha      		DATE; 
	DEFINE vdia         	CHAR(2);
	DEFINE vmesanio         CHAR(6);
	DEFINE vaniomes        CHAR(6);
	DEFINE Pempresa         CHAR(3);

	DEFINE vnumcte 		CHAR(20);
	DEFINE vcuenta 		CHAR(20);
	DEFINE vcuenta1 	CHAR(20);
	DEFINE vsucursal	CHAR(4);
	DEFINE vproducto	CHAR(4);
	DEFINE vprimermov	DATE;
	DEFINE vultimomov	DATE;
	DEFINE vplazo		smallint;
	DEFINE valtacta 	DATE;
	DEFINE vfechaaniv 	DATE;
	DEFINE valtacte 	DATE;
	DEFINE vsdodisp		money;
	DEFINE vsdoprom		money;
	DEFINE vciudad		CHAR(15);
	DEFINE vsexo		CHAR(1);
	DEFINE vedocivil	CHAR(2);
	DEFINE vocupacion 	CHAR(30);
	DEFINE vtasa	 	DECIMAL (11,6);
	DEFINE vstatus 		CHAR(1);
	DEFINE vsdoactual   money;
	
	DEFINE ven_transacc     CHAR(1);
    DEFINE vcontador        INTEGER;
	DEFINE vcomienza        SMALLINT;
	
	
    LET vcodret     = "00000";
    LET vsqlerr     = 0;
    LET vsql        = "";
	LET vfecha		= DATE(1);
    LET vdia  		= "";
	LET vmesanio    = "";
	LET vaniomes    = "";
    LET pempresa    = '001';
	
	LET vnumcte		= "";
	LET vcuenta 	= "";
	LET vcuenta1 	= "";
	LET vsucursal 	= "";
	LET vproducto 	= "";
	LET vprimermov	= DATE(1);
	LET vultimomov	= DATE(1);
	LET	vciudad		= "";
	LET	vocupacion 	= "";
	LET vedocivil	= "";	
	LET	vsexo		= "";
	LET vplazo		= 0;
	LET	valtacte	= DATE(1);
	LET	vfechaaniv	= DATE(1);
	LET	valtacta	= DATE(1);
	LET vsdoprom	= '0.00';
	LET vsdodisp	= '0.00'; 
	LET vtasa 		= 0;
	LET vstatus		= "";
	LET vsdoactual 	= '0.00'; 
		
    LET ven_transacc = '0';
    LET vcontador    = 0;
    LET vcomienza    = -1;
	
	
	
	SET DEBUG FILE TO "sp_ctes_captac_cut_pba.out";
	TRACE ON; 
	

    BEGIN

    ON EXCEPTION SET vsqlerr
       IF vsqlerr <> 0 THEN
	      LET vcodret = vsqlerr;
          RETURN vcodret;
          IF ven_transacc = '1' THEN
             ROLLBACK WORK;
          END IF;
       END IF;
    END EXCEPTION;
	
	   
	SET ISOLATION TO DIRTY READ;
	
	IF EXISTS (SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum BETWEEN (SELECT MIN(partnum) FROM sysmaster:systabnames) AND
                                      (SELECT MAX(partnum) FROM sysmaster:systabnames)
                  AND tabname = 'extriecap') THEN
		DROP TABLE bdicheq:"informix".extriecap;
	
	END IF	
	
	
		
CREATE TABLE bdicheq:"informix".extriecap ( 
	numcte         char(20),
	cuenta       	char(20),
	sucursal        char(4),
	plazo  		   	smallint,
	producto    	char(4),
	tasa			decimal(11,6),
	ocupacion		char(30),
	edo_civil		char(2),
	sexo			char(1),
	ciudad			char(15),
	sdoprom			money,
	sdodisp    		money,
	fechaaniv     	date,
	fechaltacte    	date,
	primermov     	date,
	ultimomov     	date,
	fech_alt     	date
	);
	
	CREATE INDEX informix.idx_extriecap
    ON informix.extriecap(numcte,cuenta);
	
	
	select to_char(pri_dia_mes - 1 units day,'%m/%d/%Y')
	into vfecha
	from bdicheq:sc_fechas
	where  empresa = pempresa;
	
	
	FOREACH WITH HOLD
		-- NUMERO DE CLIENTE, CUENTA, SUCURSAL, PRODUCTO, PRIMER MOVIMIENTO Y ULTIMO MOVIMIENTO STATUS Y SDO ACTUAL SE USAN PARA VALIDACIONES
		select  {+INDEX(bdicheq:sc_maechq ix174_1)}
		num_cte,cuenta,sucursal,producto,fecultdep,fecultret, status_cta, sdo_actual 
		into vnumcte,vcuenta,vsucursal,vproducto,vprimermov,vultimomov,vstatus, vsdoactual
		from bdicheq:sc_maechq
		where empresa = "001"
		
		
        IF vcomienza = -1 THEN
            BEGIN WORK;
            LET vcomienza = 0;
            LET ven_transacc = '1';
        END IF;
			
			--toma la fecha de alta de cliente
			select fecha_alta
			into valtacte
			from bdinteg:si_cliente 
			where numcte = vnumcte;
			
			--Solo aplica para Pagaré
			LET vplazo		= 0;
			
			--se toma ocupacion, estado civil y sexo del cliente
			select  b.descripcion,a.estado_civil,a.sexo
			into vocupacion, vedocivil, vsexo
			from bdinteg:si_ctepf a, bdinteg:si_profesion b
			where a.numcte = vnumcte
			and a.profesion= b.profesion;
			
			-- SALDO PROMEDIO, FECHA DE ALTA DE CUENTA Y FECHA DE ANIVERSARIO PARA INVERSION CRECIENTE
			select sdo_prom_mesant,fecha_alta,fecha_mod   
			into vsdoprom, valtacta, vfechaaniv
			from bdicheq:sc_maenoc 
			where cuenta = vcuenta;
			
			-- NO ES INVERSION CRECIENTE
			IF vproducto <> '1100' THEN
			--CALL bdicred:'informix'.monthadd(valtacta,1) RETURNING vfechaaniv; 
			LET	vfechaaniv	= DATE(1);
			END IF
			
				
			--NOMBRE DE CIUDAD
			select e.nombreciudad 
			into vciudad
			from bdinteg:si_direcciones_actual d, bdinteg:si_catciudades e 
			where  d.numcte = vnumcte
			and    d.tipo_dir = "1"
			and    e.numerociudad = d.numerociudad;
			
			
			-- TASA BRUTA
			LET vaniomes = SUBSTR(vfecha,7,4) || SUBSTR(vfecha,1,2);
			LET vaniomes = vaniomes;
						
			select tasabruta, cuenta
			into vtasa, vcuenta1
			from bdicheq:sc_maehis 
			where cuenta = vcuenta
			and aniomes = vaniomes;
			
			IF vcuenta1 is null THEN
			
			CONTINUE FOREACH;
			
			END IF
			
			
			
			IF vstatus IN ('4','5','6') AND vsdoactual <= '200' THEN
			
			LET vtasa = 0;
			
			END IF
			
			LET vcuenta1 = "";
			-- SALDO DISPONIBLE
			LET vdia = SUBSTR(vfecha,4,2);
			LET vdia = vdia;
			
			IF LPAD(vdia,2,'0') = '31' THEN
						
			SELECT capvig31 ,cuenta
			INTO vsdodisp, vcuenta1
			FROM bdicheq:sc_sdodiarioc
			where cuenta = vcuenta 
			and aniomes = vaniomes;
								
			ELIF LPAD(vdia,2,'0') = '30' THEN
						
			SELECT capvig30 ,cuenta
			INTO vsdodisp,vcuenta1
			FROM bdicheq:sc_sdodiarioc
			where cuenta = vcuenta 
			and aniomes = vaniomes;
			
			ELIF LPAD(vdia,2,'0') = '29' THEN
			
			SELECT capvig29 ,cuenta
			INTO vsdodisp,vcuenta1
			FROM bdicheq:sc_sdodiarioc
			where cuenta = vcuenta 
			and aniomes = vaniomes;
			
			ELIF LPAD(vdia,2,'0') = '28' THEN
			
			SELECT capvig28 ,cuenta
			INTO vsdodisp,vcuenta1
			FROM bdicheq:sc_sdodiarioc
			where cuenta = vcuenta 
			and aniomes = vaniomes;
			
			END IF
			
			IF vcuenta1 is null THEN
			
			CONTINUE FOREACH;
			
			END IF
			
		
		
		insert into bdicheq:"informix".extriecap values (vnumcte, vcuenta, vsucursal, nvl (vplazo,0), vproducto, nvl(vtasa, 0), nvl (vocupacion, ""), nvl (vedocivil, ""),
		nvl (vsexo, ""), nvl (vciudad, ""), nvl (vsdoprom,"0.00"), nvl (vsdodisp,"0.00"), nvl (vfechaaniv, date(1)), nvl (valtacte, date(1)), nvl (vprimermov,date(1)),
		nvl (vultimomov,date(1)), nvl (valtacta,date(1)) );	
		
		
        LET vcontador = vcontador + 1;
        
        IF vcontador >= 7500 THEN
            COMMIT WORK;
            BEGIN WORK;
            LET vcontador = 0;
        END IF;
			
	END FOREACH
    
    IF ven_transacc = '1' THEN
        COMMIT WORK;
        LET ven_transacc = '0';
    END IF;

		
	-- foreach para pagares
	
	FOREACH WITH HOLD
	
	-- se toma numero de cliente, cuenta, sucursal, plazo, tasa, saldo promedio y fecha de alta
	select num_cte, cuenta, sucursal, plazo, tasa, capital, fecha_alta  
	into vnumcte, vcuenta, vsucursal, vplazo, vtasa, vsdoprom, valtacta
	from bdinvers:sv_maeinv 
	where empresa = pempresa
		
		IF vcomienza = -1 THEN
            BEGIN WORK;
            LET vcomienza = 0;
            LET ven_transacc = '1';
        END IF;
		
	-- se asigna el producto para el pagare
	let vproducto = "3000" ;
	
	--se toma ocupacion, estado civil y sexo del cliente
	select  b.descripcion,a.estado_civil,a.sexo
	into vocupacion, vedocivil, vsexo
	from bdinteg:si_ctepf a, bdinteg:si_profesion b
	where a.numcte = vnumcte
	and a.profesion= b.profesion;
	
	
	--NOMBRE DE CIUDAD
			select e.nombreciudad 
			into vciudad
			from bdinteg:si_direcciones_actual d, bdinteg:si_catciudades e 
			where  d.numcte = vnumcte
			and    d.tipo_dir = "1"
			and    e.numerociudad = d.numerociudad;
			
	--EL SALDO DISPONIBLE Y FECHA DE ANIVERSARIO NO APLICAN PARA PAGARE
	LET vsdodisp	= '0.00'; 
	LET	vfechaaniv	= DATE(1);
	
	--toma la fecha de alta de cliente
			select fecha_alta
			into valtacte
			from bdinteg:si_cliente 
			where numcte = vnumcte;
	-- FECHA DEL PRIMER Y ULTIMO MOVIMIENTO NO APLICA PARA PAGARE
	LET vprimermov	= DATE(1);
	LET vultimomov	= DATE(1);
			
		insert into bdicheq:"informix".extriecap values (vnumcte, vcuenta, vsucursal, nvl (vplazo,0), vproducto, nvl(vtasa, 0), nvl (vocupacion, ""), nvl (vedocivil, ""),
		nvl (vsexo, ""), nvl (vciudad, ""), nvl (vsdoprom,"0.00"), nvl (vsdodisp,"0.00"), nvl (vfechaaniv, date(1)), nvl (valtacte, date(1)), nvl (vprimermov,date(1)),
		nvl (vultimomov,date(1)), nvl (valtacta,date(1)) );
		
	     LET vcontador = vcontador + 1;
        
        IF vcontador >= 7500 THEN
            COMMIT WORK;
            BEGIN WORK;
            LET vcontador = 0;
        END IF;
			
	END FOREACH
    
    IF ven_transacc = '1' THEN
        COMMIT WORK;
        LET ven_transacc = '0';
    END IF;

	LET vdia = SUBSTR(vfecha,4,2);
	LET vdia = vdia;   
	LET vmesanio =  SUBSTR(vfecha,1,2) || SUBSTR(vfecha,7,4);
	LET vmesanio = vmesanio;

    
    LET vsql = "";

	LET vsql =  ' echo "SET ISOLATION TO DIRTY READ; unload to /resplogifx/conciliachq/extriecap_'||vdia||''||vmesanio||'.unl'||
                ' select * from bdicheq:"informix".extriecap '||
                ';" > /resplogifx/conciliachq/qry_ctescapt.sql';
    SYSTEM vsql;
    
    LET vsql = "";
    LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/qry_ctescapt.sql";  --produccion
    --LET vsql = "dbaccess bdicheq /resplogifx/conciliachq/qry_ctescapt.sql"; -- desarrollo
    SYSTEM vsql;
    LET vsql = "";

	Drop table bdicheq:"informix".extriecap;
	  
    END;
    
    RETURN vcodret;
	
END PROCEDURE;

CREATE PROCEDURE "informix".reversion_pba(pempresa  char(3),
                                      psucursal char(4),
                                      pusuario  char(8),
                                      pfolio    char(16),
                                      ptiporev  char(1))
RETURNING char(5);
    
    DEFINE sql_err              integer;
    DEFINE isam_err             integer;
    DEFINE cod_ret              char(5);
    DEFINE cCodret2             char(5);
    DEFINE contador             smallint;
    DEFINE wcompend             money(14,2);
    DEFINE wtiptran             char(2);
    DEFINE wnum_serial          integer;
    DEFINE wtransacc            char(4);
    DEFINE wcuenta              char(20);
    DEFINE wmonto_tot           money(14,2);
    DEFINE wmonto_tot1          money(14,2);
    DEFINE montoaux             money(14,2);
    DEFINE wfirme               money(14,2);
    DEFINE wen_sbc              money(14,2);
    DEFINE wremesas             money(14,2);
    DEFINE wdias_ret            smallint;
    DEFINE wnum_cheq            integer;
    DEFINE wimp_sbg_ccc         money(14,2);
    DEFINE wimp_chq_sbg         money(14,2);
    DEFINE wimp_int_ccc         money(14,2);
    DEFINE wimp_int_sbg         money(14,2);
    DEFINE wchq_exp_mes         smallint;
    DEFINE wnaturaleza          char(1);
    DEFINE wvalida_docto        char(1);
    DEFINE wtipo                char(1);
    DEFINE wsaldo_cuenta        money(14,2);
    DEFINE wsdo_actual          money(14,2);
    DEFINE wsdo_retenido        money(14,2);
    DEFINE wsdo_sbc             money(14,2);
    DEFINE wsdo_cong            money(14,2);
    DEFINE wmontoaux            money(14,2);
    DEFINE wlim_chq_sbc         money(14,2);
    DEFINE wimp_chq_sbc         money(14,2);
    DEFINE wlim_chq_rem         money(14,2);
    DEFINE wimp_chq_rem         money(14,2);
    DEFINE wreferencia          char(40);
    DEFINE wstatus_envio        char(1);
    DEFINE wrowid               integer;
    DEFINE wfechoy              date;
    DEFINE pfolio1              char(16);
    DEFINE wtpcheque            char(2);
    DEFINE wfechahora           datetime hour to fraction(3);
    DEFINE vtranusoccc          char(4);
    DEFINE vtrancancta          char(4);
    DEFINE vtranintccc          char(4);
    DEFINE vtranusosbg          char(4);
    DEFINE vtranintsbg          char(4);
    DEFINE wcomision            char(4);
    DEFINE wsuc_cuen            char(4);
    DEFINE wproducto            char(4);
    define vnum_tarjeta         char(16);
    define vmaxsec              smallint;
    DEFINE vProdCrec            CHAR(4);
    DEFINE vstatus_cta          CHAR(1);
    DEFINE vtransaccion 	    integer;
    DEFINE vtrancorrespchq      CHAR(4);
    DEFINE wusuario             CHAR(8);
    DEFINE vuser_limit          CHAR(8);
    DEFINE vtran_limit          CHAR(4);
    DEFINE vid_transacc         CHAR(2);
    DEFINE vid_canal            CHAR(2);
    DEFINE wnum_cte             CHAR(20);
    DEFINE vmsje_limites        CHAR(80);
    DEFINE vid_autor            CHAR(1);
    DEFINE cTransaccAbonoEnvio  char(4);
    DEFINE cTransaccAbonoEnvioC char(4);
    DEFINE vtranpagosbg         CHAR(4);
	DEFINE vclave_rastreo       CHAR(30);
    --- // 2012.01.23 // INICIO
	DEFINE cont_exist       	INTEGER;
    --- // 2012.01.23 // FIN
    DEFINE wsuc_tran            CHAR(4);
    DEFINE vestado_oper         CHAR(2);
    DEFINE vestado_cta          CHAR(2);
    DEFINE vtpo_per_valida      CHAR(1);
	
    LET sql_err = 0;
    LET cod_ret = "000";
    LET cCodret2 = "00000";
    LET vtransaccion = 0;
    LET vtrancorrespchq = '';
    --- // 2012.01.23 // INICIO
	LET cont_exist = 0;
    --- // 2012.01.23 // FIN
    LET vtpo_per_valida = '';
    LET vnum_tarjeta = ' ';

    --- SET DEBUG FILE TO "/home/informix/ivonne/reversion.out";
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        IF (sql_err <> 0) THEN
            SET DEBUG FILE TO "reversionch.err";
            TRACE sql_err || " * " || isam_err;
            LET cod_ret = sql_err;
            if vtransaccion = 1 then
                ROLLBACK WORK;
                BEGIN WORK;
            else
                ROLLBACK WORK;
            end if
            RETURN cod_ret;
        END IF;
    END EXCEPTION;

    on exception in (-535)
        let vtransaccion = 1;
    end exception with resume;

    if vtransaccion = 1 then
        COMMIT WORK;
        BEGIN WORK;
    else
        BEGIN WORK;
    end if;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;

    LET pempresa = pempresa;
    LET psucursal = psucursal;
    LET pusuario = pusuario;
    LET pfolio =  pfolio;
    LET ptiporev = ptiporev;
    
    SELECT {+INDEX(sc_fechas idx_fechas1)}
           fecha_hoy
      INTO wfechoy
      FROM sc_fechas
     WHERE empresa = pempresa;

    SELECT TRIM(valor)
      INTO vProdCrec
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam ="PRODCREC";

    SELECT {+INDEX(sc_movdia idx_movdia2a),
            +INDEX(bdinteg:si_transacc idx_transacc2)}
           COUNT(*)
      INTO contador
      FROM sc_movdia m,
           bdinteg:si_transacc t
     WHERE m.empresa = pempresa
       AND m.folio_suc = pfolio
       AND m.cancelad <> "S"
       AND t.numero = m.transacc
       AND t.empresa = m.empresa
       AND t.reversable = "S";

    IF (contador = 0) THEN
        SELECT COUNT(*)
          INTO contador
          FROM sc_docret_sbc
         WHERE empresa = pempresa
           AND folio_suc = pfolio
           AND fecha_alta = wfechoy;

        IF (contador = 0) THEN
            --- ##################################################   2012.01.23 - INICIO   ##################################################
			--- IF EXISTS ( SELECT referencia1 
            ---               FROM bdisac:sac_movimientos 
            ---              WHERE folio_suc = pfolio 
            ---                AND id_sucursal = psucursal 
            ---                AND status_cancelado <> 'S' ) THEN
            ---     CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
            ---     RETURNING cCodret2;
            --- END IF;
            
            LET cont_exist = 0;
            
			SELECT {+INDEX(bdisuc:ss_operaciones idx_ss_operaciones2)} COUNT (folio_oper) 
              INTO cont_exist
              FROM bdisuc:ss_operaciones
             WHERE folio_sucursal = pfolio
               AND sucursal = psucursal
               AND reversado <> '1';

            
            IF cont_exist > 0 THEN
               CALL bdisuc:reversion(pempresa,psucursal,pusuario, pfolio,ptiporev) 
               RETURNING cCodret2;
            END IF;			
			
            LET cont_exist = 0;
            SELECT COUNT (referencia1) 
              INTO cont_exist
              FROM bdisac:sac_movimientos
             WHERE folio_suc = pfolio
               AND id_sucursal = psucursal
               AND status_cancelado <> 'S';
            
            IF cont_exist > 0 THEN
               CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
               RETURNING cCodret2;
            ELSE
                -----------------------------------------------
            END IF;
            --- ##################################################   2012.01.23 - FIN   ##################################################

			-- // Se modifica la busqueda para ser mas eficiente
			SELECT {+index (bditef:tef_operaciones  idx_tef_operaciones1)} clave_rastreo
              into vclave_rastreo
              FROM bditef:"informix".tef_operaciones
             WHERE folio_suc = pfolio
               AND clave_rastreo <> ""
               AND fecha_trans = wfechoy 
               AND cve_status = 'PE'
               AND sucursal = psucursal;
					
            if (vclave_rastreo is not null or vclave_rastreo <> '') then
                UPDATE {+index (bditef:tef_operaciones  idx_tef_operaciones1)} 
                       bditef:"informix".tef_operaciones 
                   SET cve_status = '04' 
                 WHERE folio_suc = pfolio  
                   AND clave_rastreo <> "" 
                   AND fecha_trans = wfechoy 
                   AND cve_status = 'PE'
                   AND sucursal = psucursal;
            else
                --------------------------
            end if;
            
            RETURN cod_ret;
        ELSE
            UPDATE sc_docret_sbc
               SET cancelado = "S"
             WHERE empresa = pempresa
               AND folio_suc = pfolio
               AND fecha_alta = wfechoy;
            
            --- ##################################################   2012.01.23 - INICIO   ##################################################
            --- IF EXISTS ( SELECT referencia1 
            ---               FROM bdisac:sac_movimientos 
            ---              WHERE folio_suc = pfolio 
            ---                AND id_sucursal = psucursal 
            ---                AND status_cancelado <> 'S') THEN
            ---     CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
            ---     RETURNING cCodret2;
            --- END IF;
            
            LET cont_exist = 0;
            
            SELECT COUNT (referencia1) 
              into cont_exist
              FROM bdisac:sac_movimientos
             WHERE folio_suc = pfolio
               AND id_sucursal = psucursal
               AND status_cancelado <> 'S';
               
            IF cont_exist > 0 THEN
                CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
                RETURNING cCodret2;
            ELSE
                -----------------------
            END IF;
            --- ##################################################   2012.01.23 - FIN   ##################################################
        
			-- // Se modifica la busqueda para ser mas eficiente
			SELECT {+index (bditef:tef_operaciones  idx_tef_operaciones1)} clave_rastreo
              into vclave_rastreo
              FROM bditef:"informix".tef_operaciones
             WHERE folio_suc = pfolio
               AND clave_rastreo <> ""
               AND fecha_trans = wfechoy 
               AND cve_status = 'PE'
               AND sucursal = psucursal;
						
            if (vclave_rastreo is not null or vclave_rastreo <> '') then
                UPDATE {+index (bditef:tef_operaciones  idx_tef_operaciones1)} 
                       bditef:"informix".tef_operaciones 
                   SET cve_status = '04' 
                 WHERE folio_suc = pfolio  
                   AND clave_rastreo <> "" 
                   AND fecha_trans = wfechoy 
                   AND cve_status = 'PE'
                   AND sucursal = psucursal;
            else
                ------------------------------
            end if;

            RETURN cod_ret;
        END IF
    END IF

    SELECT valor
      INTO vtrancancta
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trancancta";

    SELECT valor
      INTO vtranusoccc
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranusoccc";

    SELECT valor
      INTO vtranintccc
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranintccc";

    SELECT valor
      INTO vtranusosbg
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranusosbg";

    SELECT valor
      INTO vtranintsbg
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranintsbg";
       
    SELECT TRIM(valor) 
      INTO vtrancorrespchq
      FROM bdicheq:sc_param
     WHERE empresa = pempresa
       AND codparam = "trancorrespchq";
       
    SELECT valor
      INTO vtranpagosbg
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagosbg";
    
	-- // Valida si es un envio de Orden de Pago y su estatus no esta activo no deja reversar
	--- ##################################################   2012.01.23 - INICIO   ##################################################
	--- IF EXISTS ( SELECT referencia1 
    ---               FROM bdisac:sac_movimientos 
    ---              WHERE folio_suc = pfolio 
    ---                AND id_sucursal = psucursal 
    ---                AND status_cancelado <> 'S') THEN
	LET cont_exist = 0;
    
	SELECT COUNT (referencia1) 
      into cont_exist
      FROM bdisac:sac_movimientos
     WHERE folio_suc = pfolio
       AND id_sucursal = psucursal
       AND status_cancelado <> 'S';
    
	IF cont_exist > 0 THEN
	--- ##################################################   2012.01.23 - FIN   ##################################################
    
        -- // Obtengo transacciones de Anono a cuenta prest,  significa que es envio
        SELECT valor 
          INTO cTransaccAbonoEnvio  --- Abono en efectivo por Orden de Pago a Cuenta Prest
          FROM Bdisac:sac_param
         WHERE empresa = '001'
           AND cod_param = '5070011';
           
        SELECT valor 
          INTO cTransaccAbonoEnvioC   --- Abono en Cargo a cuenta por Orden de Pago         
          FROM Bdisac:sac_param
         WHERE empresa = '001'
           AND cod_param = '5070012';
           
        -- // Verifica si es un Envio de Orden de Pago
        SELECT {+INDEX(sc_movdia idx_movdia2a), 
               +INDEX(bdinteg:si_transacc idx_transacc2)} 
               Count(m.transacc)
          INTO contador
          FROM sc_movdia m, 
               bdinteg:si_transacc t
         WHERE m.empresa = pempresa 
           AND m.folio_suc = pfolio 
           AND m.cancelad <> "S"
           AND t.numero = m.transacc
           AND t.empresa = m.empresa
           AND t.reversable = "S"
           AND (t.numero = cTransaccAbonoEnvio OR t.numero = cTransaccAbonoEnvioC);
		
        If contador >= 1 THEN --- Si es un envio			
            -- // Verifica si el estatus del envio es diferente de activo
            --- ##################################################   2012.01.23 - INICIO   ##################################################
            --- IF EXISTS (SELECT referencia1 
            ---              FROM bdisac:sac_movimientos mov 
            ---        INNER JOIN bdisac:sac_enviosdineroya env ON (Trim(mov.referencia1) = env.no_control)
            ---             WHERE mov.folio_suc = pfolio 
            ---               AND mov.id_sucursal = psucursal 
            ---               AND mov.status_cancelado <> 'S' 
            ---               AND env.estatus <> '01') THEN
            ---               AND env.estatus not in ('00', '01')) THEN
            ---     -- // El envio no puede ser reversado, estatus diferente de 01-activo	
            ---     LET cod_ret = '170';
            ---     RETURN cod_ret;
            
            LET cont_exist = 0;
            
            SELECT COUNT (referencia1) 
              into cont_exist
              FROM bdisac:sac_movimientos mov
             INNER JOIN bdisac:sac_enviosdineroya env ON (Trim(mov.referencia1) = env.no_control)
             WHERE mov.folio_suc = pfolio
               AND mov.id_sucursal = psucursal
               AND mov.status_cancelado <> 'S'
               AND env.estatus not in ('00', '01');
               
            IF cont_exist > 0 THEN
                -- // El envio no puede ser reversado, estatus diferente de 01-activo	
                LET cod_ret = '170';
                RETURN cod_ret;
            ELSE
                --------------------------------------
            END IF;
            --- ##################################################   2012.01.23 - FIN   ##################################################
            
            -- // Se modifica la busqueda para ser mas eficiente
            SELECT {+index (bditef:tef_operaciones  idx_tef_operaciones1)} clave_rastreo
              into vclave_rastreo
              FROM bditef:"informix".tef_operaciones
             WHERE folio_suc = pfolio
               AND clave_rastreo <> ""
               AND fecha_trans = wfechoy 
               AND cve_status = 'PE'
               AND sucursal = psucursal;
                            
            if (vclave_rastreo is not null or vclave_rastreo <> '') then						
                UPDATE {+index (bditef:tef_operaciones  idx_tef_operaciones1)} 
                       bditef:"informix".tef_operaciones 
                   SET cve_status = '04' 
                 WHERE folio_suc = pfolio  
                   AND clave_rastreo <> "" 
                   AND fecha_trans = wfechoy 
                   AND cve_status = 'PE'
                   AND sucursal = psucursal;
            else
                -----------------------------
            end if;	
        END IF;
	END IF;
    
    FOREACH
        SELECT {+INDEX(sc_movdia idx_movdia2a),
                +INDEX(bdinteg:si_transacc idx_transacc2)}
               md.num_serial, md.transacc, md.cuenta, md.monto_tot, md.firme, md.en_sbc, md.remesas,
               md.dias_ret, md.num_cheq, tr.naturaleza, tr.valida_docto, tr.tipo_tran,
               md.referencia, md.suc_cuen, md.producto, tr.tpcheque, md.usuario, md.sucursal  -- Gpo PISA 270110
          INTO wnum_serial, wtransacc, wcuenta, wmonto_tot, wfirme, wen_sbc,
               wremesas, wdias_ret, wnum_cheq, wnaturaleza, wvalida_docto,
               wtiptran, wreferencia, wsuc_cuen, wproducto, wTpCheque, wusuario, wsuc_tran
          FROM sc_movdia md,
               bdinteg:si_transacc tr
         WHERE md.empresa = pempresa
           AND md.folio_suc = pfolio
           AND md.cancelad <> "S"
           AND tr.numero = md.transacc
           AND tr.empresa = md.empresa
           AND tr.reversable = "S"
         ORDER BY tr.naturaleza 
         
        SELECT tpper_valida
          INTO vtpo_per_valida
          FROM sc_producto
         WHERE producto = wproducto;

        /* #############################
        SELECT MAX(secuencia)
          INTO vmaxsec
          FROM sc_tarjeta
         WHERE empresa = pempresa
           AND cuenta = wcuenta
           AND tipo_tarjeta = "T";

        SELECT num_tarjeta
          INTO vnum_tarjeta
          FROM sc_tarjeta
         WHERE empresa = pempresa
           AND cuenta = wcuenta
           AND secuencia = vmaxsec;
        ############################# */

        LET wimp_sbg_ccc = 0;
        LET wimp_chq_sbg = 0;
        LET wimp_int_ccc = 0;
        LET wimp_int_sbg = 0;
        LET wchq_exp_mes = 0;
        LET wcompend = 0;

        IF wvalida_docto = "S" AND wTpCheque = "01" THEN --- Gpo PISA270110
            LET wchq_exp_mes  = 1;
        END IF

        IF wtransacc = vtranusoccc THEN
            LET wimp_sbg_ccc = wmonto_tot;
        ELIF wtransacc = vtranusosbg THEN
            LET wimp_chq_sbg = wmonto_tot;
        ELIF wtransacc = vtranpagosbg THEN
            LET wimp_chq_sbg = wmonto_tot;
        ELIF wtransacc = vtranintccc THEN
            LET wimp_int_ccc = wmonto_tot;
        ELIF wtransacc = vtranintsbg THEN
            LET wimp_int_sbg = wmonto_tot;
        ELIF wtiptran = "05" THEN
            LET wcompend = wmonto_tot;
            let wcomision = trim(wreferencia);
        END IF;

        SELECT sdo_actual, status_cta, num_cte
          INTO wsdo_actual, vstatus_cta, wnum_cte
          FROM sc_maechq
         WHERE empresa = pempresa
           AND cuenta = wcuenta;

        IF wnaturaleza = "C" THEN
            --- ##################################################   JOM INICIO   ##################################################
            UPDATE {+INDEX(sc_movdia idx_movdia_fechaserial)} sc_movdia
               SET cancelad = "S"
             WHERE fech_alt = TODAY
               and cancelad <> "S"
               AND num_serial = wnum_serial;

            IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
                IF vtransaccion = 1 THEN
                    ROLLBACK WORK;
                    BEGIN WORK;
                ELSE
                    ROLLBACK WORK;
                END IF;
                EXIT FOREACH;
            END IF;

            INSERT INTO sc_movdia VALUES 
            ( 0, pfolio, psucursal, pusuario, wfechoy, wfechoy, current hour to fraction(3), wtransacc, wsuc_cuen, wproducto, 
              pempresa, wcuenta, " ", wnum_cheq, wmonto_tot * -1, 0, 0, 0, 0, "S", " ", wsdo_actual, "0000", "REV", 0, vnum_tarjeta, "" );
            --- ##################################################   JOM FIN   ##################################################

            UPDATE sc_maechq SET
                   sdo_actual = sdo_actual + wmonto_tot,
                   imp_cgos_mes = imp_cgos_mes - wmonto_tot,
                   num_cgos_mes = num_cgos_mes - 1,
                   chq_exp_mes = chq_exp_mes - wchq_exp_mes,
                   imp_sbg_ccc = imp_sbg_ccc + wimp_sbg_ccc,
                   imp_int_ccc = imp_int_ccc + wimp_int_ccc,
                   imp_chq_sbg = imp_chq_sbg + wimp_chq_sbg,
                   imp_int_sbg = imp_int_sbg + wimp_int_sbg,
                   com_pendiente = com_pendiente + wcompend
             WHERE empresa = pempresa
               AND cuenta = wcuenta;

            --- if wtransacc = vtrancancta then

            IF vstatus_cta = "2" THEN
                UPDATE sc_maechq
                   SET status_cta = "1",
                       fec_cancelac = "",
                       motivo = " "
                 WHERE empresa = pempresa
                   AND cuenta = wcuenta;
            END IF

            IF wtiptran = "05" THEN
                UPDATE sc_detcomis
                   SET pago_com = pago_com - wmonto_tot,
                       estado_com = "P"
                 WHERE empresa = pempresa
                   AND cuenta = wcuenta
                   AND comision = wcomision
                   AND fecult_pago = wfechoy;
            END IF;

            --- Gpo PISA 270110
            IF wvalida_docto = "S" AND wTpCheque = "01" THEN
                UPDATE {+INDEX(sc_contch idx_contch1)} sc_contch
                   SET estado = "A",
                       importe = 0
                 WHERE empresa = pempresa
                   AND cuenta = wcuenta
                   AND numero = wnum_cheq;

                UPDATE sc_contch_hist
                   SET status = "V"
                 WHERE empresa = pempresa
                   AND cuenta = wcuenta
                   AND numchq = wnum_cheq
                   AND folio_suc = pfolio;

            END IF;
            
			--// Si es un movimiento de servicio reversa el servicio tambien
			--- IF EXISTS ( SELECT referencia1
            ---               FROM bdisac:sac_movimientos
            ---              WHERE folio_suc = pfolio
            ---                AND id_sucursal = psucursal
            ---                AND status_cancelado <> 'S') THEN
            ---     CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
            ---     RETURNING cCodret2;
            --- END IF;
            
			--- ##################################################   2012.01.23 - Inicio   ##################################################
			LET cont_exist = 0;
            
			SELECT COUNT (referencia1) 
              into cont_exist
			  FROM bdisac:sac_movimientos
			 WHERE folio_suc = pfolio
			   AND id_sucursal = psucursal
			   AND status_cancelado <> 'S';
               
			IF cont_exist > 0 THEN
				CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
                RETURNING cCodret2;
			ELSE
                ---------------------------------
			END IF;
			--- ##################################################   2012.01.23 - FIN   ##################################################
			
            SELECT {+index (bditef:tef_operaciones  idx_tef_operaciones1)} clave_rastreo
              into vclave_rastreo
              FROM bditef:"informix".tef_operaciones
             WHERE folio_suc = pfolio
               AND clave_rastreo <> ""
               AND fecha_trans = wfechoy 
               AND cve_status = 'PE'
               AND sucursal = psucursal;
               
            if (vclave_rastreo is not null or vclave_rastreo <> '') then						
			    UPDATE {+index (bditef:tef_operaciones  idx_tef_operaciones1)} 
                       bditef:"informix".tef_operaciones 
                   SET cve_status = '04' 
                 WHERE folio_suc = pfolio  
                   AND clave_rastreo <> "" 
                   AND fecha_trans = wfechoy 
                   AND cve_status = 'PE'
                   AND sucursal = psucursal;
            else
                ---------------------------------
			end if;
        ELSE
            IF (wnaturaleza = "A") THEN
                LET wsaldo_cuenta       = 0;
                LET wsdo_actual         = 0;
                LET wsdo_retenido       = 0;
                LET wsdo_sbc            = 0;
                LET wsdo_cong           = 0;

                SELECT sdo_actual - (sdo_retenido + sdo_cong + imp_sbg_ccc), sdo_actual, sdo_retenido, sdo_cong, imp_chq_sbc
                  INTO wsaldo_cuenta, wsdo_actual, wsdo_retenido, wsdo_cong, wsdo_sbc
                  FROM sc_maechq
                 WHERE empresa = pempresa
                   AND cuenta = wcuenta;
                   
                IF wtransacc = '0325' THEN
                    LET wsaldo_cuenta = wsaldo_cuenta + wmonto_tot;
                END IF;

                IF wsaldo_cuenta < wfirme THEN
                    LET cod_ret = "413";
                    RETURN cod_ret;
                END IF;

                --- ##################################################   JOM INICIO   ##################################################
                UPDATE {+INDEX(sc_movdia idx_movdia_fechaserial)} sc_movdia
                   SET cancelad = "S"
                 WHERE fech_alt = TODAY
                   and cancelad <> "S"
                   AND num_serial = wnum_serial;

                IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
                    IF vtransaccion = 1 THEN
                        ROLLBACK WORK;
                        BEGIN WORK;
                    ELSE
                        ROLLBACK WORK;
                    END IF;
                    EXIT FOREACH;
                END IF;

                INSERT INTO sc_movdia VALUES 
                ( 0, pfolio, psucursal, pusuario, wfechoy, wfechoy, current hour to fraction(3), wtransacc, wsuc_cuen, wproducto,
                  pempresa, wcuenta, " ", wnum_cheq, wmonto_tot * -1, 0, 0, 0, 0, "S", " ", wsdo_actual, "0000", "REV", 0, vnum_tarjeta, "" );
                --- ##################################################   JOM FIN   ##################################################
                
                IF wen_sbc > 0 THEN
                    LET wmonto_tot = 0;

                    UPDATE sc_docret_sbc
                       SET cancelado = "S"
                     WHERE empresa = pempresa
                       AND cuenta = wcuenta
                       AND folio_suc = pfolio
                       AND fecha_alta = wfechoy;
                END IF;

                UPDATE sc_maechq
                   SET sdo_actual     = sdo_actual - wmonto_tot,
                       imp_chq_sbc    = imp_chq_sbc - wen_sbc,
                       imp_sbg_ccc    = imp_sbg_ccc - wimp_sbg_ccc,
                       imp_chq_sbg    = imp_chq_sbg - wimp_chq_sbg,
                       num_abonos_mes = num_abonos_mes - 1,
                       imp_abonos_mes = imp_abonos_mes - wmonto_tot - wen_sbc
                 WHERE empresa = pempresa
                   AND cuenta = wcuenta;
                   
                IF wtransacc = vtrancorrespchq THEN
                    UPDATE {+index (bdicheq:"informix".sc_acumdiacorresp idx_acumdiario)}sc_acumdiacorresp
                       SET monto_acum = monto_acum - wmonto_tot
                     WHERE cuenta = wcuenta;
                     
                    UPDATE {+index (bdicheq:"informix".sc_param_corresp idx_paramcorresp)}sc_param_corresp
                       SET valor = valor - wmonto_tot
                     WHERE codparam = '003'
                       AND empresa = pempresa;
                END IF;
                
                IF wtransacc = '0325' THEN
                    UPDATE sc_maechq
                       SET sdo_retenido = sdo_retenido - wmonto_tot
                     WHERE empresa = pempresa
                       AND cuenta = wcuenta;
                       
                    UPDATE sc_depinterpza
                       SET monto_ret = monto_ret - wmonto_tot,
                           monto_acum = monto_acum - wmonto_tot
                     WHERE fecha = wfechoy
                       AND num_cte = wnum_cte
                       AND cuenta = wcuenta;
                END IF;
                
                IF wtransacc = '0202' AND vtpo_per_valida IN('1','3') THEN
                    SELECT estado
                      INTO vestado_oper
                      FROM bdinteg:"informix".si_sucursales
                     WHERE sucursal = wsuc_tran;
                     
                    SELECT estado
                      INTO vestado_cta
                      FROM bdinteg:"informix".si_sucursales
                     WHERE sucursal = wsuc_cuen;
                     
                    IF vestado_oper <> vestado_cta THEN
                        UPDATE sc_depinterpza
                           SET monto_acum = monto_acum - wmonto_tot
                         WHERE fecha = wfechoy
                           AND num_cte = wnum_cte
                           AND cuenta = wcuenta;
                    END IF;
                END IF;
                
                IF vProdCrec = wproducto THEN
                    UPDATE sc_maechq
                       SET marca_ret = "0",
                           status_cta = "2",
                           fec_cancelac = wfechoy
                     WHERE empresa = pempresa
                       AND cuenta = wcuenta;
                END IF;
                
				--- ##################################################   2012.01.23 - INICIO   ##################################################
                --- IF EXISTS ( SELECT referencia1
                ---               FROM bdisac:sac_movimientos
                ---              WHERE folio_suc = pfolio
                ---                AND id_sucursal = psucursal
                ---                AND status_cancelado <> 'S') THEN
                ---     CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
                ---     RETURNING cCodret2;
                --- END IF;
                
				LET cont_exist = 0;
                
				SELECT COUNT (referencia1) 
                  into cont_exist
				  FROM bdisac:sac_movimientos
				 WHERE folio_suc = pfolio
				   AND id_sucursal = psucursal
				   AND status_cancelado <> 'S';
                   
				IF cont_exist > 0 THEN
					CALL bdisac:sp_ReversionSac(pempresa,psucursal,pusuario, pfolio) 
                    RETURNING cCodret2;
                ELSE
                    -----------------------------------
				END IF;
				--- ##################################################   2012.01.23 - FIN   ##################################################
                
				SELECT {+index (bditef:tef_operaciones  idx_tef_operaciones1)} 
                       clave_rastreo
                  into vclave_rastreo
                  FROM bditef:"informix".tef_operaciones
                 WHERE folio_suc = pfolio
                   AND clave_rastreo <> ""
                   AND fecha_trans = wfechoy 
                   AND cve_status = 'PE'
                   AND sucursal = psucursal;
						
                if (vclave_rastreo is not null or vclave_rastreo <> '') then						
				    UPDATE {+index (bditef:tef_operaciones  idx_tef_operaciones1)} bditef:"informix".tef_operaciones 
                       SET cve_status = '04' 
					 WHERE folio_suc = pfolio  
					   AND clave_rastreo <> "" 
					   AND fecha_trans = wfechoy 
                       AND cve_status = 'PE'
					   AND sucursal = psucursal;
				else
                    ---------------------------------
				end if;
            END IF;
        END IF;
        
        -- // Validación de limites 
        select {+index (bdinteg:"informix".si_usuario_limites idx_usualim)} usuario
          into vuser_limit
          from bdinteg:si_usuario_limites
         where usuario = wusuario
           and empresa = pempresa;
        
        if (vuser_limit is not null or vuser_limit <> '') then 
            IF (vuser_limit = "intercar") then
                select transacc, id_transacc, id_canal
                  into vtran_limit, vid_transacc, vid_canal
                  from bdinteg:si_transacc_limites
                 where transacc = wtransacc
                   and empresa = pempresa
                   and sistema = '01';
            ELSE
                SELECT id_canal 
                  into vid_canal
                  from bdinteg:si_canales
                 where cc_canal = psucursal;

                select transacc, id_transacc
                  into vtran_limit, vid_transacc
                  from bdinteg:si_transacc_limites
                 where transacc = wtransacc
                   and empresa = pempresa
                   and sistema = '01'
                   and id_canal = vid_canal;
            END IF;
           
            if (vtran_limit is not null or vtran_limit <> '') then
                execute procedure bdinteg:sp_reversa_acum_x(wfechoy, wnum_cte, wcuenta, vid_transacc, vid_canal, wmonto_tot)
                into cod_ret, vmsje_limites, vid_autor;
                
                let cod_ret = '000';
            end if;
        end if;

    END FOREACH;

    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;

    END;

    RETURN cod_ret;

END PROCEDURE

DOCUMENT
'DESCRIPCION: Se incluye el llamado al procedimiento de reversion sac para reversar las transacciones de Ordenes de pago', 
'MODIFICO: Antonio Bastidas',
