    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- // LIMPIAR LA TABLA
    IF EXISTS(SELECT tabname FROM bdicheq:systables WHERE tabname = 'sc_pagares3anios') THEN
        DROP TABLE sc_pagares3anios;
    END IF;

    CREATE TABLE sc_pagares3anios 
        ( 
            sucursal            CHAR(4)     NOT NULL, 
            promotor            CHAR(8)     NOT NULL,
            numcte              CHAR(9)     NOT NULL , 
            nombre_cte          CHAR(108),
            numcta              CHAR(20)    NOT NULL , 
            cta_eje             CHAR(20),
            fecha_apertura      DATE, 
            fecha_vencimiento   DATE, 
            telefono1           CHAR(15),
            telefono2           CHAR(15),
            telefono3           CHAR(15),
            extension           CHAR(5),
            correo_elect        CHAR(50)
        )
    EXTENT SIZE 2048 NEXT SIZE 1024 LOCK MODE ROW;
    CREATE INDEX idx_pagare3anios_suc ON sc_pagares3anios (sucursal) ONLINE;
    CREATE INDEX idx_pagare3anios_ven ON sc_pagares3anios (fecha_vencimiento) ONLINE;
    CREATE INDEX idx_pagare3anios_cta ON sc_pagares3anios (numcta) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE sc_pagares3anios;
    
    -- // Obtener Parametros
    SELECT fecha_hoy, prox_fecha  
      INTO dFechaHoy, dProxFecha 
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';
     
    -- // OBTIENE PARAMETRO DE DIAS
    SELECT TRIM (valor) 
      INTO cDiasxVencer 
      FROM bdicheq:sc_param 
     WHERE empresa = "001"
       AND codparam = 'DiasRptsCtaIna3anios';	

    SELECT *
      FROM bdinvers:sv_maeinv
     WHERE empresa = '001'
       AND status_cta = '1'
      INTO TEMP tmp_invs WITH NO LOG;
    CREATE INDEX idx_pagare_tmp ON tmp_invs(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_invs;
       
    -- // Proceso para el pagare
    INSERT INTO sc_pagares3anios
    SELECT inv.sucursal, inv.promotor, inv.num_cte,
           TRIM(cte.nombre1)||' '||TRIM(NVL(cte.nombre2,''))||' '||TRIM(cte.apell_paterno)||' '||TRIM(NVL(cte.apell_materno,'')), 
           inv.cuenta, inv.cta_cheques, inv.fecha_alta, tmp.fecha_venc, tel1.telefono, tel2.telefono, tel3.telefono, tel3.extension, cor.correo_elec
      FROM bdinvers:sv_maeinv inv
     INNER JOIN tmp_invs tmp ON ( tmp.cuenta = inv.cuenta AND tmp.fecha_venc BETWEEN dProxFecha AND ( dProxFecha + cDiasxVencer::INTEGER ) )
     INNER JOIN bdinteg:si_cliente cte ON (cte.numcte = inv.num_cte) 
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = cte.numcte AND tel1.tipo_tel = 1)
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = cte.numcte AND tel2.tipo_tel = 2)
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = cte.numcte AND tel3.tipo_tel = 3)
      LEFT OUTER JOIN bdinteg:si_correos cor ON (cor.numcte = cte.numcte AND cor.tipo_correo = 1 AND cor.status_correo = 'A')
     WHERE inv.empresa = '001'
       AND inv.secuencia = 1
       AND dFechaHoy - inv.fecha_alta >= 1060;
       
    UPDATE STATISTICS MEDIUM FOR TABLE sc_pagares3anios;
    
    -- // GENERA EL ARCHIVO PARA OPERACIONES
    LET vfecha = TO_CHAR(dFechaHoy, '%d%m%Y');
    
    LET vsql = '';
    LET vsql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/Pagares3anios_'||vfecha||'.txt '||
               'SELECT * FROM sc_pagares3anios;" > /resplogifx/conciliachq/pagare3anios.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '';
    LET vstmt = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/pagare3anios.sql"; 
    SYSTEM vstmt;
    LET vstmt = '';
       
    RETURN cCodRet, cMensaje;
    
    END;
    
END PROCEDURE;

create procedure "informix".gen_protsdo_pos( pempresa       char(3),
                                         psucursal      char(4),
                                         pusuario       char(8),
                                         ptransacc      char(4),
                                         ptransacc_suc  char(4),
                                         pfolio_suc     char(16),
                                         pcuenta        char(20),
                                         pmonto         money(14,2),
                                         pdocto         integer,
                                         pdivisa        char(2),
                                         pnip           char(4),
                                         preferval      char(40),
                                         ptiporef	    char(1),  --- 0 No valida titularidad
                                                                  --- 1 Valida cta_cheques vs cuenta eje
                                                                  --- 2 Valida Titular
                                                                  --- 3 Valida Cotitular
                                                                  --- 4 No valida titularidad ni tipo persona y nip
                                         pnum_tarjeta   char(16),
                                         pusuautoriza   char(8),
										 preferencia23 CHAR(23))
returning char(5), char(8), money(14,2);

    define cod_ret          char(5);
    define vfecha           date;
    define vfechacalendario date;
    define v_valdoc         char(1);
    define v_tipo_tran      char(2);
    define v_moneda         char(2);
    define v_tpcheque       char(2);
    define v_long_cta       char(2);
    define vcuenta          char(20);
    define v_plaza          char(3);
    define v_succta         char(4);
    define v_producto       char(4);
    define v_numreg         smallint;
    define v_dias           smallint;
    define longitud         smallint;
    define v_mesdia         char(4);
    define v_tranret        char(4);
    define v_cal_int_chq    char(1);
    define v_clave          char(8);
    define v_cvepro         char(8);
    define v_fisica         char(1);
    define v_tipper         char(1);
    define sql_err          integer;
    define v_monto_val_nip  money(16,2);
    define v_disponible     money(16,2);
    define v_nip            char(4);
    define v_numcte         char(20);
    define v_cotit          char(20);
    define v_cteexo         char(20);
    define v_band           char(1);
    define v_tasapl         char(8);
    define v_valortasa      money(14,2);
    define v_comision       money(14,2);
    define vstatus_cta      char(1);
    
    let cod_ret    = "000";
    let v_clave    = "    ";
    let v_comision = 0;
    
    begin
    
    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret, v_clave, v_comision;
        end if;
    end exception;
    
    -- Extrae la fecha del sistema de cheques
    select {+INDEX(sc_fechas idx_fechas1)} fecha_hoy 
      into vfechacalendario 
      from sc_fechas 
     where empresa = pempresa;

    select fecha_proceso, status_cta  
      into vfecha, vstatus_cta
      from sc_maechq
     where empresa = pempresa
       and cuenta = pcuenta;

    if ( vfecha is null or vstatus_cta = '4' or vstatus_cta = '5' ) then
        let vfecha = vfechacalendario;
    end if

    if ( vfecha < vfechacalendario ) then
        let cod_ret = "549";
        return  cod_ret, v_clave, v_comision;
    end if
    
    if ( vstatus_cta in('2','6','7','8') ) then
        let cod_ret = "200";
        return  cod_ret, v_clave, v_comision;
    end if
    
    -- Extrae la informacion de la Cuenta de Cheques
    select cuenta, num_cte, producto, plaza
      into vcuenta, v_numcte, v_producto, v_plaza
      from sc_maechq
     where empresa = pempresa 
       and cuenta = pcuenta;
       
    if vcuenta is null then
        let cod_ret = "100";
        return cod_ret, v_clave, v_comision;
    end if
    
    -- Valida el nip de acuerdo al monto por tipo de cliente
    if ptiporef <> "4" then
        select monto_val_nip 
          into v_monto_val_nip
          from bdinteg:si_cliente clie, 
               bdinteg:si_tipocte tpoclie
         where clie.tipo_cliente = tpoclie.tipo_cliente 
           and numcte = v_numcte;

        if pmonto >= v_monto_val_nip then
            select nip 
              into v_nip 
              from bdinteg:si_servcte
             where numcte = v_numcte;
            
            if v_nip is null then
                let v_nip = " ";
            end if;

            if v_nip <> pnip then
                let cod_ret = "614";
                return cod_ret, v_clave, v_comision;
            end if
        end if

        --- Valida personalidad del cliente
        select {+INDEX(bdinteg:si_tipper ix193_1)} es_fisica 
          into v_fisica
          from bdinteg:si_cliente clie, 
               bdinteg:si_tipper tpe
         where clie.numcte = v_numcte 
           and clie.tpo_persona = tpe.tpo_persona;

        if v_fisica <> "S" or v_fisica is null then
            let cod_ret = "122";
            return cod_ret, v_clave, v_comision;
        end if
    end if

    if ptiporef = "2" then
        --- Valida Titular
        if v_numcte <> preferval then
            let cod_ret = "211";
            return cod_ret, v_clave, v_comision;
        end if
    end if

    if ptiporef = "3" then
        --- Valida Titular y Cotitular
        let v_band = "0";
        
        if v_numcte <> preferval then
            foreach
                select {+INDEX(sc_cotitular idx_cotit2)} nombre 
                  into v_cotit 
                  from sc_cotitular
                 where empresa = pempresa 
                   and cuenta = pcuenta

                if v_cotit <> preferval then
                    continue foreach;
                else
                    let v_band = "1";
                    exit foreach;
                end if
            end foreach
            
            if v_band = "0" then
                let cod_ret="211";
                return cod_ret, v_clave, v_comision;
            end if
        end if
    end if

    select tipo_tran, dias_ret, tasa_aplicada, valida_docto
      into v_tipo_tran,v_dias, v_tasapl, v_valdoc
      from bdinteg:si_transacc
     where empresa = pempresa 
       and numero = ptransacc;

    if v_tipo_tran is null then
        let v_tipo_tran = 0;
    end if;

    if v_tipo_tran < "20" and v_tipo_tran > "29" then
        let cod_ret = "615";
        return cod_ret, v_clave, v_comision;
    end if

    if v_dias is null then
        let v_dias = 0;
    end if
    
    let v_producto = v_producto;

    select divisa 
      into v_moneda
      from sc_producto
     where empresa = pempresa 
       and producto=v_producto;
       
    if v_moneda is null then
        let cod_ret = "110";
        return cod_ret, v_clave, v_comision;
    end if;
    
    if v_valdoc = "S" then
        --- Valida que el Cheque no haya sido protegido previamente
        select count(*) 
          into v_numreg 
          from sc_docret
         where empresa = pempresa 
           and cuenta = pcuenta
           and num_chq = pdocto
           and cancelado = "P"
           and folio_suc = pfolio_suc;
        
        if v_numreg is null then
            let v_numreg = 0;
        end if
        
        if v_numreg > 0 then
            let cod_ret = "616";
            return cod_ret, v_clave, v_comision;
        end if
    end if

    call cargon_ref_pos(pempresa,psucursal, pusuario, ptransacc, ptransacc_suc, pfolio_suc, pcuenta, pdocto, pmonto, v_moneda, preferval, pnum_tarjeta,pusuautoriza, preferencia23)
    returning cod_ret, v_tranret;

    --- let cod_ret = "100"; -- Esto regresaba originalmente el procedimiento cargon_ref, se cambio para que regresara "000

    if cod_ret = "000" then
        if v_valdoc = "S" and pdocto <> 0 then
            delete {+INDEX(sc_histch idx_histch1)} 
              from sc_histch
             where empresa = pempresa 
               and cuenta = pcuenta 
               and numero = pdocto;
               
            insert into sc_histch 
            values(pempresa,pcuenta,pdocto,"R",vfecha,pmonto);
            
            delete {+INDEX(sc_contch idx_contch2)} 
              from sc_contch
             where empresa = pempresa 
               and cuenta = pcuenta 
               and numero = pdocto;
        end if
        
        insert into sc_docret values
        ( pempresa, "SC", pcuenta, v_dias, pmonto, pfolio_suc, pusuario, vfecha, current hour to fraction, "P", preferval, psucursal, pdocto, v_dias, ptransacc, pmonto, '', '' );
        
        update sc_maechq
           set (sdo_actual, sdo_retenido, fec_ult_mov) =
               (sdo_actual + pmonto,sdo_retenido + pmonto, vfecha)
         where empresa = pempresa 
           and cuenta = pcuenta;
           
        if vstatus_cta = '5' then
            update sc_maechq
               set status_cta = '1',
                   fecha_proceso = vfechacalendario
             where empresa = pempresa 
               and cuenta = pcuenta;
        end if
    end if
    
    return cod_ret, v_clave, v_comision;
    
    end
    
end procedure;

create procedure "informix".conciliadebito(pempresa char(3),
                                           pnum_tarjeta char(16),
                                           psucursal char(4),
                                           pusuario char(8),
                                           ptipomov char(1),
                                           ptransacc char(4),
                                           pfoliosuc char(16),
                                           pmonto_tot money(14,2),
                                           pdivisa char(2),
                                           preferencia char(40),
                                           pfolioori char(16),
                                           pvRfcComer char (20),
                                           pvRef23 char(23))
    
returning char(5),char(1);

    -- // Variables Globales Conciliacion intercar
    DEFINE GLOBAL vg_estatus    VARCHAR(5)  DEFAULT " ";
    DEFINE GLOBAL vgrfc_comer   VARCHAR(20) DEFAULT " ";
    DEFINE GLOBAL vgreferencia  VARCHAR(40) DEFAULT " ";

    define vcodret char(5);
    define vsqlerr integer;
    define vbandera char(1);
    define vcuenta char(20);
    define vtranret char(4);
    define vfecapli date;
    define vsdodisp money(14,2);
    define vmtoapli money(14,2);
    define vTranResp CHAR(4);
    define vTipoTran char(2);
    define vt_status_cta char(1);
    
    --- set debug file to "/informixuc7/perifericos/conciliadebito.out";
    --- trace on;

    begin
    
    on exception set vsqlerr
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
            return vcodret, vbandera;
        end if
    end exception;

    let vcodret = "000";
    let vbandera = "E";
    let vsqlerr = 0;
    let vcuenta = "";
    let vtranret = "";
    let vfecapli = "";
    let vsdodisp = 0;
    let vmtoapli = 0;
    let vTranResp = "";
    let vTipoTran = "";
    LET vt_status_cta = "";

    -- // Busca la cuenta en base al No. tarjet
    select tar.cuenta, mae.status_cta 
      into vcuenta, vt_status_cta
      from sc_tarjeta tar, 
           sc_maechq mae
     WHERE tar.empresa = pempresa 
       AND num_tarjeta = pnum_tarjeta
       AND tar.empresa = mae.empresa
       AND tar.cuenta = mae.cuenta;

    if vcuenta is null OR vcuenta = "" then
        let vcodret = "111";
        let vbandera = "E";
        return vcodret, vbandera;
    end if

    LET vTranResp = ptransacc;

    -- // busca el tipo_tran en si_transaccc (20)
    SELECT NVL(tranlibprot, "0000"), tipo_tran
      INTO ptransacc, vTipoTran
      FROM bdinteg:si_transacc
     WHERE empresa = pempresa
       AND numero = ptransacc
       AND sistema = "01";

    -- // Si es de Cargo
    if ptipomov = "C" then
        if vTipoTran  in ("00", "01", "02") and vg_estatus <> "3" then
            let vbandera = "C";
            return vcodret, vbandera;
        end if;

        IF ptransacc = "0000" OR ptransacc = " " THEN
            LET ptransacc = vTranResp;
        END IF

        -- // Realiza un desbloqueo parcial si es necesario, para realizar el cargo correspondiente
        IF vt_status_cta = "3" THEN 
            UPDATE sc_maechq 
               SET status_cta = "1"
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF

        -- // Realiza el cargo de la transaccion en cheques...
        LET preferencia = vgrfc_comer || preferencia;
		
        call cargo_ref_pos(pempresa, psucursal, pusuario, ptransacc, ptransacc, pfoliosuc, 
                       vcuenta, 0, pmonto_tot, pdivisa, preferencia, pnum_tarjeta,"", pvRef23)
        returning vcodret, vtranret, vfecapli, vsdodisp, vmtoapli;

        -- // Devuelve el bloqueo original
        IF vt_status_cta = "3" THEN 
            UPDATE sc_maechq 
               SET status_cta = "3"
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF

        if vcodret <> "000" and vcodret <> "400" then
            let vbandera = "E";
            return vcodret, vbandera;
        elif vcodret = "400" then
            let vbandera = "0";
            return vcodret, vbandera;
        else
            let vbandera = "C";
            return vcodret, vbandera;
        end if
    end if
    
    -- // Si es de Abono
    if ptipomov = "A" then
        --LET ptransacc = "0813";
		LET ptransacc = vTranResp;
        LET preferencia = vgrfc_comer || preferencia;
        
        call abono_ref_pos(pempresa, psucursal, pusuario, ptransacc, ptransacc, pfoliosuc, vcuenta, 0, 
                       pmonto_tot, pmonto_tot, 0, 0, 0, pdivisa, preferencia, pnum_tarjeta, "", pvRef23)
        returning vcodret;
        
        if vcodret <> "000" then
            let vbandera = "E";
            return vcodret, vbandera;
        else
            let vbandera = "C";
            return vcodret, vbandera;
        end if
    end if

    -- // si es de reversion
    if ptipomov = "R" then
        call reversiontd(pempresa, psucursal, pusuario, pfolioori, "A", vcuenta, ptransacc)
        returning vcodret;
        
        if vcodret <> "000" then
            let vbandera = "E";
            return vcodret, vbandera;
        else
            let vbandera = "C";
            return vcodret, vbandera;
        end if
    end if
    
    return vcodret, vbandera;
    
    end
    
end procedure;

CREATE PROCEDURE "informix".abona_ctas(pempresa CHAR(3))

  RETURNING CHAR(5), INTEGER;

    -- // DECLARACION DE VARIABLES

    DEFINE vcodret     		CHAR(5);
    DEFINE sql_err     		INTEGER;
    DEFINE vprimera	 	INTEGER;
    DEFINE vcontador		INTEGER;
    DEFINE vcuantos  		INTEGER;

    DEFINE vfecha_hoy		DATE;
    DEFINE vhora		CHAR(15);
    DEFINE vfolio		CHAR(20);
    DEFINE vnum_serial		CHAR(16);
    DEFINE vcuenta              CHAR(20);
    DEFINE vmonto		MONEY(14,2);
    DEFINE vnum_tarjeta		CHAR(40);
    DEFINE vsucursal		CHAR(4);
    DEFINE vproducto		CHAR(4);
    DEFINE vstatus		CHAR(1);
    DEFINE vsdo_actual		MONEY(14,2);
    DEFINE vsdo_cuenta		MONEY(14,2);
    DEFINE vimp_sobregiro	MONEY(14,2);
    DEFINE vmonto_sobregiro	MONEY(14,2);

    -- // INICIALIZACION DE VARIABLES

    LET vcodret	= "000";
    LET sql_err	= 0;
    LET vprimera = 0;
    LET vcontador =-1;
    LET vcuantos = 0;

    BEGIN

    ON EXCEPTION
	SET sql_err
	IF sql_err <> 0 THEN
	    LET vcodret = sql_err;
            RETURN vcodret, vcuantos;
	END IF;
    END EXCEPTION;

    -- SET DEBUG FILE TO "./abona_ctas.out";
    -- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- ********************* FOREACH PRINCIPAL ***********************

    FOREACH WITH HOLD
        SELECT num_serial, cuenta, monto_tot, num_tarjeta
	  INTO vnum_serial, vcuenta, vmonto, vnum_tarjeta
          FROM sc_movhis
	 WHERE transacc = "0219"
           AND fech_alt = "06082009"
           AND referencia = "Cancelacion al movto. del 04/Jun/2009"

        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
        END IF;

	LET vhora = current hour to fraction;
        LET vfolio = "informix" || vhora[1,2] || vhora[4,5] ||
			           vhora[7,8] || vhora[10,11];

	SELECT sucursal, producto, status_cta, sdo_actual, imp_chq_sbg
	  INTO vsucursal, vproducto, vstatus, vsdo_actual, vimp_sobregiro
	  FROM sc_maechq
	 WHERE empresa = pempresa
 	   AND cuenta = vcuenta;

	LET vsdo_cuenta = vmonto;

	IF vimp_sobregiro > 0 THEN
	    IF vmonto >= vimp_sobregiro THEN
		LET vmonto_sobregiro = vimp_sobregiro;
		LET vsdo_cuenta = vmonto - vimp_sobregiro;
		LET vimp_sobregiro = 0;
	    ELSE
	        LET vsdo_cuenta = 0;
		LET vmonto_sobregiro = vmonto;
		LET vimp_sobregiro = vimp_sobregiro - vmonto;
	    END IF;

	    INSERT INTO sc_movdia
            VALUES (0, vfolio, vsucursal, "informix","06092009","06092009",
                    vhora, "3247", vsucursal, vproducto, pempresa, vcuenta, 
		    "", 0, vmonto_sobregiro, vmonto_sobregiro, 0,0,0, "", 
		    vstatus, vsdo_actual, "0000", 
		    "Cancelacion de sobregiro del 04/Jun/2009",
		    0.000000, vnum_tarjeta, " ","");
	END IF;		

	UPDATE sc_maechq
	   SET sdo_actual = sdo_actual + vsdo_cuenta,
	       imp_chq_sbg = vimp_sobregiro
	 WHERE empresa = pempresa
	   AND cuenta = vcuenta;

        LET vcontador = vcontador + 1;

        IF (vcontador >= 1500) THEN
            LET vcuantos = vcuantos + vcontador;
	    LET vcontador = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;

    END FOREACH;

    -- ************************* FOREACH PRINCIPAL *************************

    LET vcuantos = vcuantos + vcontador;

    IF (vcontador > 0) THEN
        COMMIT WORK;
    END IF;

    END;

    RETURN vcodret, vcuantos;

END PROCEDURE;

CREATE PROCEDURE "informix".ajusteprovision()

RETURNING CHAR(5);


DEFINE sql_err      SMALLINT;
DEFINE isam_err     SMALLINT;
DEFINE error_info   CHAR(40);
DEFINE cod_ret      CHAR(5);
DEFINE vFecha       DATE;
DEFINE vCuenta      CHAR(20);
DEFINE vInteres     DECIMAL(14,2);
DEFINE vProvision   DECIMAL(14,2);
DEFINE vAlta        DATE;
DEFINE vgusuario    CHAR(8);
DEFINE vgsucursal   CHAR(4);
DEFINE vgproducto   CHAR(4);
DEFINE vgstatus_cta CHAR(1);
DEFINE vgsdo_actual DECIMAL(14,2);
DEFINE vBegin       CHAR(1);
DEFINE vhora        DATETIME HOUR TO FRACTION;
DEFINE vhoraw       CHAR(15);
DEFINE vfolio_suc   CHAR(16);
-- **************************************************************************
-- *                      CONTROL DE ERRORES                                *
-- **************************************************************************

   ON EXCEPTION SET sql_err, isam_err, error_info
      LET cod_ret = sql_err;
      IF vBegin = "S" THEN
         ROLLBACK WORK;
      END IF
      RETURN cod_ret;
   END EXCEPTION;

--    set debug file to "ajusteprovision.out";
--    trace on;
-- **************************************************************************
-- *                      ASIGNACION DE VARIABLES                           *
-- **************************************************************************

LET cod_ret    = "000";
LET vBegin     = "N";
LET vgusuario  = "informix";
SELECT fecha_hoy INTO vFecha FROM sc_fechas;

-- **************************************************************************
-- *                      PROGRAMA PRINCIPAL                                *
-- **************************************************************************

FOREACH WITH HOLD     
       SELECT a.cuenta, ROUND((ROUND((acum_pos / dias_pos),2) * .04) /360,2),
              b.fecha_alta, c.sucursal, c.producto, status_cta, sdo_actual
	 INTO vCuenta, vInteres, vAlta, vgsucursal, vgproducto, vgstatus_cta,
	      vgsdo_actual
         FROM bdicheq:sc_Salpro a, sc_maenoc b, sc_maechq c
        WHERE a.fecha = TO_DATE("2008-03","%Y-%m")
          AND b.empresa = "001"
          AND b.cuenta = a.cuenta
          AND c.empresa = b.empresa
          AND c.cuenta = b.cuenta
          AND c.status_cta ="1"
          AND ROUND((ROUND((acum_pos / dias_pos),2) * .04) /360,2) > 0
--and a.cuenta ="1410070476"

	BEGIN WORK;
	LET vBegin ="S";

        LET vhora = current hour to fraction;
        LET vhoraw = vhora;
        LET vhoraw = vhoraw[1,2]||vhoraw[4,5]||vhoraw[7,8]||vhoraw[10,11];
        LET vfolio_suc = vgusuario||vhoraw[1,8];


	IF DAY(vFecha) <= DAY(vAlta) THEN
		LET vInteres = vInteres * (DAY(vFecha) - 1);
		UPDATE sc_maenoc
		   SET acum_sdo_int = acum_sdo_int + vInteres
		 WHERE empresa ="001"
		   AND cuenta = vCuenta;

	ELSE

	   LET vProvision = vInteres * DAY(vAlta);
	   INSERT INTO sc_movdia
           VALUES (0,vfolio_suc,vgsucursal,vgusuario,vFecha,
                  vFecha,vhora,"3381",vgsucursal,vgproducto,"001",
                  vCuenta, "",0,vProvision,vProvision,0,0,0,"",
		  vgstatus_cta, vgsdo_actual,"0000"," ",4,"","","");

            INSERT INTO sc_movdia
               VALUES (0,vfolio_suc,vgsucursal,vgusuario,vFecha,
                       vFecha,vhora,"3276",vgsucursal,vgproducto,
                       "001",vCuenta, "",0,vProvision,vProvision,0,0,0,"","1",
                       vgsdo_actual,"0000"," ",4,"","","");

            UPDATE sc_maechq
               SET (fec_ult_mov,num_abonos_mes,imp_abonos_mes,sdo_actual,
                    ultpagoint) =
                   (vFecha,num_abonos_mes + 1,
		    imp_abonos_mes + (vProvision),
                    sdo_actual + (vProvision), vFecha)
               WHERE empresa = "001" AND cuenta = vCuenta;


	    LET vInteres = vInteres * ((DAY(vFecha)- DAY(vAlta)) - 1);
            UPDATE sc_maenoc
               SET acum_sdo_int = acum_sdo_int + vInteres
             WHERE empresa ="001"
               AND cuenta = vCuenta;

	END IF

	COMMIT WORK;
	LET vBegin = "N";



END FOREACH

RETURN cod_ret;

END PROCEDURE
;

create procedure "informix".aplidividen(pempresa char(3),
                                        pejercicio datetime year to month)
       returning char(5);

define vrowid, vsqlerr integer;
define vsucursal char(4);
define vcuenta char(20);
define vcuenta_aho char(20);
define vnumcte char(20);
define vmonto money(14,2);
define vdivisa char(2);
define vstatus char(1);
define vnaturaleza char(1);
define vtipo_aplica char(1);
define vusuario char(8);
define vfolio_suc char(16);
define vcodret char(5);
define vtransacc char(4);
define vreferencia char(40);
define vfecha_hoy date;
define vmensaje char(80);
define vsolbcos char(20);
define vproducto char(4);
define vsdo_cuenta money(14,2);
define vtotreg integer;

begin
   on exception set vsqlerr
      if vsqlerr <> 0 then
         let vcodret = vsqlerr;
         return vcodret;
      end if
   end exception;


   let vusuario = USER;
   let vcodret = "000";

   select fecha_hoy into vfecha_hoy
      from sc_fechas
      where empresa = pempresa;

   select tipo_aplica into vtipo_aplica
      from sc_contpagdiv
      where empresa = pempresa and ejercicio = pejercicio;

   if vtipo_aplica = "A" then
      select valor into vtransacc
         from sc_param
         where empresa = pempresa and codparam = "tranpagdivabo";

      if vtransacc is null or vtransacc = " " then
         let vcodret = "550";
         return vcodret;
      end if

      select naturaleza into vnaturaleza
         from bdinteg:si_transacc
         where empresa = pempresa and numero = vtransacc;

      if vnaturaleza is null then
         let vcodret = "550";
         return vcodret;
      end if

      if vnaturaleza <> "A" then
         let vcodret = "552";
         return vcodret;
      end if
   else
      select valor into vtransacc
         from sc_param
         where empresa = pempresa and codparam = "tranpagdivcap";

      if vtransacc is null or vtransacc = " " then
         let vcodret = "550";
         return vcodret;
      end if

      select naturaleza into vnaturaleza
         from bdinteg:si_transacc
         where empresa = pempresa and numero = vtransacc;

      if vnaturaleza is null or vnaturaleza <> "R" then
         let vcodret = "550";
         return vcodret;
      end if
   end if

   select count(*) into vtotreg
      from sc_movpagdiv
      where empresa = pempresa and ejercicio = pejercicio and
            procesado != "S" and fecha_apli <= vfecha_hoy;
   if vtotreg is null or vtotreg <= 0 then
      let vcodret = "910";
      return vcodret;
   end if

   foreach with hold
      select a.rowid,sucursal,a.cuenta,monto,num_cte,producto,sdo_actual
         into vrowid,vsucursal,vcuenta,vmonto,vnumcte,vproducto,vsdo_cuenta
         from sc_movpagdiv a, sc_maechq b
         where a.empresa = pempresa and ejercicio = pejercicio and
               procesado != "S" and fecha_apli <= vfecha_hoy and
               a.empresa = b.empresa and a.cuenta = b.cuenta
      let vcodret = "000";
      let vstatus = " ";
      let vcuenta_aho = vcuenta[1,9]||"300";
      let vdivisa = "";
      select divisa,status_cta into vdivisa,vstatus
         from sc_maechq a, sc_producto b
         where a.empresa = pempresa and cuenta = vcuenta_aho and
               a.empresa = b.empresa and a.producto = b.producto;
      let vfolio_suc = current hour to fraction(3);
      let vfolio_suc = vusuario||vfolio_suc[1,2]||vfolio_suc[4,5]||
                       vfolio_suc[7,8]||vfolio_suc[9,10];
      let vreferencia = "Pago de dividendos del ejercicio "||pejercicio;
      if vtipo_aplica = "A" then
         if vdivisa is null then
            call bdibanco:sbsp_graba_solchq(pempresa,vnumcte,vusuario,
                 vmonto,vcuenta) returning vcodret,vmensaje,vsolbcos;
            if vcodret = "00000" then
               let vcodret = "000";
            end if
         else
            if vstatus = "3" then
               update sc_maechq
                  set status_cta = "1"
                  where empresa = pempresa and cuenta = vcuenta_aho;
            end if
            foreach
               execute procedure abono_ref(pempresa,vsucursal,vusuario,
                    vtransacc,"0000",vfolio_suc,vcuenta_aho,0,vmonto,
                    vmonto,0,0,0,vdivisa,vreferencia) into vcodret
            end foreach
            if vstatus = "3" then
               update sc_maechq
                  set status_cta = "3"
                  where empresa = pempresa and cuenta = vcuenta_aho;
            end if
         end if
      else
         insert into sc_movdia
            values(0,vfolio_suc,vsucursal,vusuario,vfecha_hoy,vfecha_hoy,
                   current hour to fraction(3),vtransacc,vsucursal,
                   vproducto,pempresa,vcuenta," ",0,vmonto,vmonto,0,0,0,
                   " "," ",vsdo_cuenta,"000",vreferencia,0,"","","");
      end if
      if vcodret = "000" then
         update sc_movpagdiv
            set(procesado,codigo_retorno,fecha_proceso) =
               ("S",vcodret,vfecha_hoy)
            where rowid=vrowid;
      else
         update sc_movpagdiv
            set(procesado,codigo_retorno,fecha_proceso) =
               ("N",vcodret,vfecha_hoy)
            where rowid=vrowid;
      end if
   end foreach
   let vcodret = "000";
   return vcodret;
end
end procedure;

CREATE PROCEDURE "informix".calc_interes(pempresa CHAR(3))

  RETURNING CHAR(5), INTEGER;

    -- // DECLARACION DE VARIABLES

    DEFINE vcodret     		CHAR(5);
    DEFINE sql_err     		INTEGER;
    DEFINE vprimera	 	INTEGER;
    DEFINE vcontador		INTEGER;
    DEFINE vcuantos  		INTEGER;

    DEFINE vcuenta              CHAR(20);
    DEFINE vacum_sdo_pos	MONEY(14,2);
    DEFINE vdia_sdo_pos		INTEGER;
    DEFINE vsdo_promedio	MONEY(14,2);
    DEFINE vcalc_int		MONEY(14,2);
    DEFINE vhora		CHAR(15);
    DEFINE vfolio		CHAR(20);
    DEFINE vsucursal		CHAR(4);
    DEFINE vproducto		CHAR(4);
    DEFINE vstatus_cta		CHAR(1);
    DEFINE vsdo_actual		MONEY(14,2);
    DEFINE vtotintpag		MONEY(14,2);
    DEFINE vpremio		MONEY(14,2);
    DEFINE vtasa		DECIMAL(9,6);
    DEFINE vmaxsec 		SMALLINT;
    DEFINE vtarjeta		CHAR(16);
    DEFINE vintereses		MONEY(14,2);

    -- // INICIALIZACION DE VARIABLES

    LET vcodret	  = "000";
    LET sql_err	  = 0;
    LET vprimera  = 0;
    LET vcontador = -1;
    LET vcuantos  = 0;

    BEGIN

    ON EXCEPTION
	SET sql_err
	IF sql_err <> 0 THEN
	    LET vcodret = sql_err;
            RETURN vcodret, vcuantos;
	END IF;
    END EXCEPTION;

    -- SET DEBUG FILE TO "./calc_interes.out";
    -- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- ********************* FOREACH PRINCIPAL ***********************

    FOREACH WITH HOLD
        SELECT {+INDEX(sc_maenoc ix137_1)} noc.cuenta, 
	       chq.sucursal, chq.producto, chq.status_cta, chq.sdo_actual,
	       his.acum_sdo_pos, his.dia_sdo_pos, his.tasabruta, his.totintpag
	  INTO vcuenta, 
	       vsucursal, vproducto, vstatus_cta, vsdo_actual,
	       vacum_sdo_pos, vdia_sdo_pos, vtasa, vtotintpag
          FROM sc_maenoc noc,
	       sc_maechq chq,
	       sc_maehis his
         WHERE noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
	   AND noc.empresa = his.empresa
	   AND noc.cuenta = his.cuenta
	   AND chq.empresa = his.empresa
	   AND chq.cuenta = his.cuenta
           AND noc.empresa = pempresa
	   AND DAY(noc.fecha_alta) = "02"
	   AND noc.fecha_alta = "07022009"
	   AND his.fechafin = "07012009"
	   AND chq.status_cta IN("1","3")
	   AND (noc.fecha_mod = "" OR noc.fecha_mod is null)
           AND chq.producto = "1100"

        LET vhora = current hour to fraction;
        LET vfolio = "informix"||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];

        LET vsdo_promedio = 0.00;
        LET vcalc_int     = 0.00;

        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
        END IF;

        LET vsdo_promedio = vacum_sdo_pos / vdia_sdo_pos;

	IF (vproducto = "2000" OR vproducto = "1400" OR 
            vproducto = "1500" OR vproducto = "1700") THEN

    	    IF (vsdo_promedio <= 200.00) THEN

	        LET vtasa = 0.00;
	        LET vcalc_int = ((vacum_sdo_pos / vdia_sdo_pos) * vtasa) * vdia_sdo_pos / 360;

	    ELIF (vsdo_promedio >= 200.01 AND vsdo_promedio <= 1000.00) THEN

	        LET vtasa = 0.02;
	        LET vcalc_int = ((vacum_sdo_pos / vdia_sdo_pos) * vtasa) * vdia_sdo_pos / 360;

	    ELIF (vsdo_promedio >= 1000.01) THEN

	        LET vtasa = 0.04;
	        LET vcalc_int = ((vacum_sdo_pos / vdia_sdo_pos) * vtasa) * vdia_sdo_pos / 360;

	    END IF;

        ELIF (vproducto = "1100" OR vproducto = "1200" OR
              vproducto = "1300" OR vproducto = "1600" OR
              vproducto = "1800") THEN

	    IF (vtasa IS NULL OR vtasa = "") THEN

		IF (vproducto = "1100") THEN
		    SELECT valor_tasa 
		      INTO vtasa
		      FROM sc_tasa_variable
		     WHERE empresa = pempresa
		       AND cuenta = vcuenta
		       AND vfecha_ant BETWEEN inicio_periodo AND fin_periodo
		       AND tipo_tasa = "M";
		ELIF (vproducto = "1200") THEN
		    LET vtasa = 0.0472;
		ELIF (vproducto = "1300") THEN
		    LET vtasa = 0.085;
		ELIF (vproducto = "1600") THEN
		    LET vtasa = 0.000;
		ELIF (vproducto = "1800") THEN
		    LET vtasa = 0.075;
		END IF

	    END IF

	    LET vcalc_int = ((vacum_sdo_pos / vdia_sdo_pos) * vtasa) * vdia_sdo_pos / 360;

        END IF;

	IF (vcalc_int < vtotintpag AND vproducto = "1100") THEN

	    SELECT MAX(secuencia)
              INTO vmaxsec
              FROM sc_tarjeta
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND tipo_tarjeta = "T";

            SELECT num_tarjeta
              INTO vtarjeta
              FROM sc_tarjeta
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND secuencia = vmaxsec;

	    SELECT int_acum
	      INTO vpremio
	      FROM sc_tasa_var_hist
	     WHERE empresa = "001"
	       AND cuenta = vcuenta
	       AND tipo_tasa = "P";

	    LET vtotintpag = vtotintpag - vpremio;
            LET vintereses = vcalc_int - vtotintpag;

	    INSERT INTO sc_movdia
            VALUES (0, vfolio, vsucursal, "informix", "07022009",
                    "07022009", vhora, "3276", vsucursal,
                    vproducto, pempresa, vcuenta, "", 0, vintereses,
                    vintereses, 0, 0, 0, "", vstatus_cta,
                    vsdo_actual, "0000", " ", vtasa,vtarjeta,"","");

	    UPDATE sc_maechq
	       SET sdo_actual = sdo_actual + vintereses
	     WHERE empresa = pempresa
	       AND cuenta = vcuenta;

	    UPDATE sc_maehis
	       SET totintpag = vpremio + vcalc_int
	     WHERE empresa = pempresa
	       AND cuenta = vcuenta
               AND fechafin = "07012009";

        ELIF (vcalc_int > vtotintpag) THEN

	    SELECT MAX(secuencia)
              INTO vmaxsec
              FROM sc_tarjeta
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND tipo_tarjeta = "T";

            SELECT num_tarjeta
              INTO vtarjeta
              FROM sc_tarjeta
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND secuencia = vmaxsec;

            LET vintereses = vcalc_int - vtotintpag;

	    INSERT INTO sc_movdia
            VALUES (0, vfolio, vsucursal, "informix", "07022009",
                    "07022009", vhora, "3276", vsucursal,
                    vproducto, pempresa, vcuenta, "", 0, vintereses,
                    vintereses, 0, 0, 0, "", vstatus_cta,
                    vsdo_actual, "0000", " ", vtasa,vtarjeta,"","");

	    UPDATE sc_maechq
	       SET sdo_actual = sdo_actual + vintereses
	     WHERE empresa = pempresa
	       AND cuenta = vcuenta;

	    UPDATE sc_maehis
	       SET totintpag = vcalc_int
	     WHERE empresa = pempresa
	       AND cuenta = vcuenta
               AND fechafin = "07012009";

	END IF

        LET vcontador = vcontador + 1;

        IF (vcontador >= 50000) THEN
            LET vcuantos = vcuantos + vcontador;
	    LET vcontador = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;

    END FOREACH;

    -- ************************* FOREACH PRINCIPAL *************************

    LET vcuantos = vcuantos + vcontador;

    IF (vcontador > 0) THEN
        COMMIT WORK;
    END IF;

    END;

    RETURN vcodret, vcuantos;

END PROCEDURE;

CREATE PROCEDURE "informix".mod_ctaefecplus(pempresa CHAR(3))

  RETURNING CHAR(5);

    -- // DECLARACION DE VARIABLES

    DEFINE vcodret     		CHAR(5);
    DEFINE sql_err     		INTEGER;
    DEFINE vprimera	 	INTEGER;
    DEFINE vcontador		INTEGER;
    DEFINE vcuantos  		INTEGER;

    DEFINE vfecha_hoy		DATE;
    DEFINE vhora		CHAR(15);
    DEFINE vfolio		CHAR(20);
    DEFINE vcuenta              CHAR(20);
    DEFINE vsucursal		CHAR(4);
    DEFINE vproducto		CHAR(4);
    DEFINE vstatus_cta		CHAR(1);
    DEFINE vsdo_actual		MONEY(14,2);
    DEFINE vmaxsec 		SMALLINT;
    DEFINE vtarjeta		CHAR(16);
    DEFINE vacum_sdo_pos	MONEY(14,2);
    DEFINE vacum_sdo_int	MONEY(14,2);
    DEFINE vcalc_int		MONEY(14,2);
    DEFINE vdesprov		MONEY(14,2);
    
    -- // INICIALIZACION DE VARIABLES

    LET vcodret	= "000";
    LET sql_err	= 0;
    LET vprimera = 0;
    LET vcontador =-1;
    LET vcuantos = 0;

    LET vacum_sdo_pos = 0.00;
    LET vacum_sdo_int = 0.00;
        
    BEGIN

    ON EXCEPTION
	SET sql_err
	IF sql_err <> 0 THEN
	    LET vcodret = sql_err;
            RETURN vcodret;
	END IF;
    END EXCEPTION;

    -- SET DEBUG FILE TO "./mod_ctaefecplus.out";
    -- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- ********************* FOREACH PRINCIPAL ***********************

    FOREACH WITH HOLD
        SELECT noc.cuenta, noc.acum_sdo_pos, noc.acum_sdo_int, 
	       chq.sucursal, chq.producto, chq.status_cta, chq.sdo_actual
	  INTO vcuenta, vacum_sdo_pos, vacum_sdo_int,
	       vsucursal, vproducto, vstatus_cta, vsdo_actual
          FROM sc_maenoc noc,
	       sc_maechq chq
         WHERE noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
	   AND chq.status_cta = "1"
	   AND chq.producto IN ("1800")
	   AND noc.acum_sdo_int > 0.00
	   AND noc.fecha_alta <> vfecha_hoy
         AND day(noc.fecha_alta) <> "01"
	   
        IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
        END IF;

	LET vhora = current hour to fraction;
        LET vfolio = "informix" || vhora[1,2] ||
		     vhora[4,5] || vhora[7,8] || vhora[10,11];

        SELECT MAX(secuencia)
          INTO vmaxsec
          FROM sc_tarjeta
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND tipo_tarjeta = "T";

        SELECT num_tarjeta
          INTO vtarjeta
          FROM sc_tarjeta
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND secuencia = vmaxsec;


        LET vcalc_int = 0.00;
        LET vdesprov  = 0.00;

	LET vcalc_int = ((vacum_sdo_pos * 0.075) / 360);

	IF (vacum_sdo_int > vcalc_int) THEN
	
	    LET vdesprov = vacum_sdo_int - vcalc_int;

	    INSERT INTO sc_movdia
            VALUES (0, vfolio, vsucursal, "informix", "07012009",
                    "07012009", vhora, "3382", vsucursal,
                    vproducto, pempresa, vcuenta, "", 0, vdesprov,
                    vdesprov, 0, 0, 0, "", vstatus_cta,
                    vsdo_actual, "0000", " ", 7.500000, vtarjeta,"","");

	END IF;

        UPDATE sc_maenoc
	   SET acum_sdo_int = vcalc_int
	 WHERE empresa = pempresa
	   AND cuenta = vcuenta;

        LET vcontador = vcontador + 1;

        IF (vcontador >= 10000) THEN
            LET vcuantos = vcuantos + vcontador;
	    LET vcontador = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;

    END FOREACH;

    -- ************************* FOREACH PRINCIPAL *************************

    LET vcuantos = vcuantos + vcontador;

    IF (vcontador > 0) THEN
        COMMIT WORK;
    END IF;

    END;

    RETURN vcodret;

END PROCEDURE;

CREATE PROCEDURE "informix".mod_movsatm(pempresa CHAR(3))

  RETURNING CHAR(5), INTEGER;

    -- // DECLARACION DE VARIABLES

    DEFINE vcodret     		CHAR(5);
    DEFINE sql_err     		INTEGER;
    DEFINE vprimera	 	INTEGER;
    DEFINE vcontador		INTEGER;
    DEFINE vcuantos  		INTEGER;

    DEFINE vcuenta		CHAR(20);
    DEFINE vstatus_cta		CHAR(1);
    DEFINE vsdo_actual		MONEY(14,2);
    DEFINE vfolio_suc		CHAR(16);
    DEFINE vsucursal		CHAR(4);
    DEFINE vusuario		CHAR(8);
    DEFINE vtransacc		CHAR(4);
    DEFINE vsuc_cuenta		CHAR(4);
    DEFINE vproducto		CHAR(4);
    DEFINE vmonto_tot		MONEY(14,2);
    DEFINE vtransacc_suc	CHAR(4);
    DEFINE vreferencia		CHAR(40);
    DEFINE vnum_tarjeta		CHAR(16);
    DEFINE vhora		CHAR(15);
    DEFINE vfolio		CHAR(20);
    DEFINE vmonto_transacc	MONEY(14,2);

    -- // INICIALIZACION DE VARIABLES

    LET vcodret	  = "000";
    LET sql_err	  = 0;
    LET vprimera  = 0;
    LET vcontador = -1;
    LET vcuantos  = 0;

    BEGIN

    ON EXCEPTION
	SET sql_err
	IF sql_err <> 0 THEN
	    LET vcodret = sql_err;
            RETURN vcodret, vcuantos;
	END IF;
    END EXCEPTION;

    -- SET DEBUG FILE TO "./mod_movsatm.out";
    -- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    SELECT {+ INDEX(intercard:movimiento idx_movimientonew1a)} *
      FROM intercard:movimiento
     WHERE substr(numtarjeta,1,4) = "4008"
       AND movconciliado = "F"
       AND fechahorainauth >= "2009-07-02 00:00:01"
       AND fechahorainauth <= "2009-07-02 21:00:00"
       AND codigoiso = "00"
       AND codtran = "01"
       AND movreversado = "F"
    INTO TEMP tmp_movimiento WITH NO LOG;
    CREATE INDEX idx_movto ON tmp_movimiento(numtarjeta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_movimiento;

    -- ********************* FOREACH PRINCIPAL ***********************

    FOREACH WITH HOLD
        SELECT his.folio_suc, his.sucursal, his.usuario, his.transacc, 
	       his.suc_cuen, his.producto, his.cuenta, his.monto_tot, 
               his.transacc_suc, his.referencia, his.num_tarjeta
	  INTO vfolio_suc, vsucursal, vusuario, vtransacc, 
	       vsuc_cuenta, vproducto, vcuenta, vmonto_tot, 
	       vtransacc_suc, vreferencia, vnum_tarjeta
	  FROM tmp_movimiento mov,
	       bdicheq:sc_movhis his
	 WHERE mov.numtarjeta = his.num_tarjeta
	   AND SUBSTR(mov.secuencia,2,6) = SUBSTR(his.folio_suc,10,6)
	   AND his.empresa = pempresa
	   AND his.cuenta IS NOT NULL
	   AND his.fech_alt = "07022009"
	   AND his.cancelad <> "S"
	   
 	IF (vcontador = -1) THEN
            BEGIN WORK;
            LET vcontador = 0;
        END IF;

	SELECT status_cta, sdo_actual
	  INTO vstatus_cta, vsdo_actual
	  FROM bdicheq:sc_maechq
	 WHERE empresa = pempresa
	   AND cuenta = vcuenta;
	     
	    LET vhora = current hour to fraction;
            LET vfolio = "informix" || vhora[1,2] || 
                                       vhora[4,5] ||
				       vhora[7,8] ||
				       vhora[10,11];

	    LET vmonto_transacc = vmonto_tot * -1;

	    INSERT INTO sc_movdia
            VALUES (0, vfolio, vsucursal, "informix", "07032009",
                    "07032009", vhora, vtransacc, vsuc_cuenta,
                    vproducto, pempresa, vcuenta, "", 0, vmonto_transacc,
                    vmonto_transacc, 0, 0, 0, "", vstatus_cta,
                    vsdo_actual, "0000", " ", 0.000000, vnum_tarjeta,"","");

	    UPDATE bdicheq:sc_maechq
	       SET sdo_actual = sdo_actual + vmonto_tot
	     WHERE empresa = pempresa
	       AND cuenta = vcuenta;	

        LET vcontador = vcontador + 1;

        IF (vcontador >= 50000) THEN
            LET vcuantos = vcuantos + vcontador;
	    LET vcontador = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;

    END FOREACH;

    -- ************************* FOREACH PRINCIPAL *************************

    LET vcuantos = vcuantos + vcontador;

    IF (vcontador > 0) THEN
        COMMIT WORK;
    END IF;

    END;

    RETURN vcodret, vcuantos;

END PROCEDURE;

CREATE PROCEDURE "informix".pase_cam(pempresa char(3))
   RETURNING CHAR(5);

   DEFINE cod_ret          CHAR(5);
   DEFINE v_statuschq,
          vcancelachq,
          vmca             CHAR(1);
   DEFINE vtipo_docto,
          v_moneda,
          v_tipo           CHAR(2);
   DEFINE vsuc_usuario,
          vsuc_cta,
          vproducto,
          vsucursal        CHAR(4);
   define vcodigo_bco,
          v_plaza,
          vcodigo_causa    CHAR(3);
   DEFINE vcausa_dev       CHAR(5);
   DEFINE vtransacc,
          tran,
          vnum_remesa      CHAR(4);
   DEFINE vusuario         CHAR(8);
   DEFINE vcuenta,
          vcuenta_aux      CHAR(20);
   DEFINE v_no_cheque      CHAR(10);
   DEFINE v_stts           CHAR(28);
   DEFINE vimporte,
          v_comision,
          v_iva,
          v_total_com      MONEY(14,2);
   DEFINE vsecuencia       INTEGER;
   DEFINE vnum_cheq        CHAR(10);   -- NCB 6/Ene/97
   DEFINE vnum_serial,
          sql_err,
          vfolio,
          v_rowid          INTEGER;
   DEFINE vfecha date;
   DEFINE v_fech_hor,
          vw_fech_hor       DATETIME YEAR TO SECOND;
   DEFINE vt_moneda_docto   CHAR(2);
   DEFINE vt_mto_divisa     money(14,2);
   DEFINE v_fecha           DATETIME YEAR TO DAY;
   DEFINE v_fecha_hora      CHAR(19);
   DEFINE vcodigo_mn        CHAR(2);
   DEFINE vmoneda           CHAR(2);
   DEFINE vsistrans         CHAR(2);
   DEFINE vsischeq          CHAR(2);
   DEFINE FOLIO1,FOLIO2     INTEGER;
   DEFINE FOLIOX            CHAR(16);
   DEFINE FOLIOC            CHAR(5);
   DEFINE hora              DATETIME HOUR TO FRACTION;
   DEFINE vplaza            CHAR(3);
   define vnum_tarjeta      char(16);
   define vmaxsec           smallint;

   -- Inicializa variables
   LET cod_ret       = "000";
   LET vcausa_dev    = " ";
   LET vtransacc     = "000";
   LET vfolio        = 0;
   LET vsecuencia    = 0;
   LET v_fech_hor    = " ";
   LET v_tipo        = " ";

  
   BEGIN
      ON EXCEPTION SET sql_err
         IF sql_err <> 0 THEN
            LET cod_ret = sql_err;
            RETURN cod_ret;
         END IF
      END EXCEPTION;

   SELECT codigo_mn INTO vcodigo_mn
      FROM bdinteg:si_param where empresa = pempresa;
   SELECT fecha_hoy INTO vfecha FROM sc_fechas where empresa = pempresa;

   LET v_fecha      = vfecha;
   LET v_fecha_hora = v_fecha || " " || current hour to second;
   LET v_fech_hor   = v_fecha_hora;
   SELECT sistema INTO vsistrans FROM bdinteg:si_sistema
      WHERE siglas = "ST";

   SELECT sistema INTO vsischeq FROM bdinteg:si_sistema
      WHERE siglas = "SC";

-- Lee el movimiento del detalle de camara por cada banco
FOREACH devoluc WITH HOLD FOR
   SELECT sucursal,usuario,codigo_bco,num_remesa,secuencia,numero_cta,
          numero_cheque,importe,tipo_docto,causa_dev,mca_aplic,rowid,
          moneda
          INTO vsucursal,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,
          vcuenta,vnum_cheq,vimporte,vtipo_docto,vcausa_dev,vmca,v_rowid,
          vmoneda
   FROM sc_detcam
   WHERE empresa = pempresa and mca_aplic = "0"
   ORDER BY numero_cta,importe

   SELECT plaza INTO vplaza FROM bdinteg:si_sucursales
      WHERE empresa = pempresa and sucursal = vsucursal;

   LET cod_ret   = "000";
   LET vfolio    = vfolio+1;
   LET vsuc_cta  = " ";
   LET vproducto = " ";
   LET FOLIOX = vsucursal||vusuario||vfolio;

   -- VerIFica sea valida la secuencia del movimiento
   IF vsecuencia IS NULL THEN
      LET cod_ret = "099";
      UPDATE sc_detcam
         SET (mca_aplic) = ("1")
         WHERE rowid = v_rowid;
   END IF

   -- VerIFica el movimiento no haya sido aplicado anteriormente
   IF vmca = "1" THEN
      LET cod_ret = "909";
      CONTINUE FOREACH;
   END IF

   -- VerIFica el tipo del documento
   IF vtipo_docto = "01" THEN                 -- Cheque Propio      (CP)
      LET v_tipo = "CP";
      LET vtransacc = "0231";
      select estado into v_statuschq
         from sc_contch
         where empresa = pempresa and cuenta = vcuenta and numero = vnum_cheq;
      if v_statuschq is null then
         select estado into v_statuschq
            from sc_histch
            where empresa = pempresa and cuenta = vcuenta and
                  numero = vnum_cheq;
         if v_statuschq = "C" then
            LET v_tipo = "CC";
            LET vtipo_docto = "03";
            LET vtransacc = "0000";
         end if
      else
         if v_statuschq = "C" then
            LET v_tipo = "CC";
            LET vtipo_docto = "03";
            LET vtransacc = "0000";
         end if

      end if
   ELSE
     IF vtipo_docto = "03" THEN               -- Cheque CertIFicado (CC)
        LET v_tipo = "CC";
        LET vtransacc = "0000";
     ELSE
       IF vtipo_docto = "04" THEN               -- Giro Bancario      (GB)
          LET v_tipo = "GB";
          LET vtransacc = "0000";
       ELSE
         IF vtipo_docto = "05" THEN               -- Cheque de Caja     (CJ)
            LET v_tipo = "CJ";
            LET vtransacc = "0000";
         ELSE
            LET v_tipo = '  ';
            LET vtransacc = '0000';
         END IF;
       END IF;
     END IF;
   END IF;

   IF v_tipo = "CP" THEN                         -- Cheque Propio
      SELECT sucursal INTO vsuc_usuario
         FROM bdinteg:si_ejecut
         WHERE ejecutivo = vusuario;
      SELECT sucursal,producto,cuenta,plaza
         INTO vsuc_cta,vproducto,vcuenta_aux,v_plaza
         FROM sc_maechq
         WHERE empresa = pempresa and cuenta = vcuenta;
      IF vproducto IS NULL THEN
         LET vcausa_dev = "02";
         LET cod_ret = "100";
      END IF
      SELECT divisa INTO v_moneda
         FROM sc_producto
         WHERE empresa = pempresa and producto = vproducto;

      -- Valida que exista la cuenta en Maestro de Cheques
      IF vcuenta_aux IS NULL THEN
         LET vcausa_dev = "02";
         LET cod_ret = "100";
      END IF;
      select max(secuencia) into vmaxsec
         from sc_tarjeta
         where empresa = pempresa and cuenta = pcuenta and
               tipo_tarjeta = "T";

      select num_tarjeta into vnum_tarjeta
          from sc_tarjeta
          where empresa = pempresa and cuenta = pcuenta and
                secuencia = vmaxsec;

      -- Valida si el documento fue rechazado por el area operativa de camara
      IF vcausa_dev IS NOT NULL  AND vcausa_dev <> " "
         and vcausa_dev <> "000" AND vcausa_dev <> "00"  AND
         vcausa_dev <> "0"  THEN
         INSERT INTO sc_devcam
            VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,
                   vcuenta,vsucursal,vproducto,vnum_cheq,vimporte,vcausa_dev,
                   vmoneda,"A");
         LET hora = current hour to fraction;
         INSERT INTO sc_movdia
         VALUES(0,FOLIOX,vsucursal,vusuario,vfecha,vfecha,hora,"3313",
                vsuc_cta,vproducto,pempresa,vcuenta," ",vnum_cheq,vimporte,
                vimporte,0,0,0," "," ",0," ",vnum_tarjeta,"","","","");
         UPDATE sc_detcam
            SET mca_aplic = "1"
            WHERE rowid = v_rowid;
         UPDATE sc_histcamara
            SET motivo_dev = vcausa_dev
            WHERE empresa = pempresa and nro_cuenta = vcuenta AND
                  nro_cheque = vnum_cheq AND
                  propias = "1";
      ELSE
         IF cod_ret = "000" and vtransacc = "0231" THEN
            call cargon_ref(pempresa,vsucursal,vusuario,vtransacc,
                    "0000", FOLIOX,vcuenta,vnum_cheq,vimporte,v_moneda,
                    "",vnum_tarjeta,"")
                 returning cod_ret,tran;
         END IF;
         IF cod_ret != "000" THEN
            LET  vcodigo_causa  = NULL;
            SELECT codigo INTO vcodigo_causa
               FROM bdinteg:si_coddevcam
               WHERE cod_ret_rel     = cod_ret
                     and sistema_rel = vsischeq;
            IF vcodigo_causa IS NOT NULL OR vcodigo_causa != "" then
               LET vcausa_dev = vcodigo_causa;
            END IF;
            INSERT INTO sc_devcam
               VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,
                      vcuenta,vsucursal,vproducto,vnum_cheq,vimporte,
                      vcausa_dev,vmoneda,"A");
            LET hora = current hour to fraction;
            INSERT INTO sc_movdia
               VALUES(0,FOLIOX,vsucursal,vusuario,vfecha,vfecha,hora,
                      "3313",vsuc_cta,vproducto,pempresa,vcuenta," ",
                      vnum_cheq,vimporte,vimporte,0,0,0," "," ",0," ",
                      vnum_tarjeta,"","","","");
            UPDATE sc_histcamara
               SET motivo_dev = vcausa_dev
               WHERE empresa = pempresa and nro_cuenta = vcuenta AND
                     nro_cheque = vnum_cheq AND
                     propias = "1";
         END IF;
      END IF;
   END IF                                        -- Cheque Propio

   IF v_tipo = "CC" THEN                         -- Cheque CertIFicado
      SELECT moneda INTO vt_moneda_docto FROM bditrans:st_maetrans
         WHERE empresa = pempresa and tipo_docto = "03" and
               num_docto = vnum_cheq and
               num_cargo_cta = vcuenta;
      IF vt_moneda_docto != vcodigo_mn THEN
         LET vt_mto_divisa = vimporte;
      ELSE
         LET vt_mto_divisa = 0;
      END IF
      IF vcausa_dev is not null and vcausa_dev <> " " and vcausa_dev <> "00"
         and vcausa_dev <> "000" and vcausa_dev <> "0" THEN
         INSERT INTO sc_devcam
            VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,vcuenta,
                   vsucursal," ",vnum_cheq,vimporte,vcausa_dev,vmoneda,"A");
         call bditrans:stmovdia(pempresa,vplaza,vsucursal,
             vusuario,v_fech_hor,"7",vt_moneda_docto,"03",vnum_cheq,
             FOLIOX,vcuenta) returning cod_ret;
         call bditrans:stmovdia(pempresa,vplaza,vsucursal,
             vusuario,v_fech_hor,"8",vt_moneda_docto,"03",vnum_cheq,
             FOLIOX,vcuenta) returning cod_ret;
         UPDATE sc_histcamara
            SET motivo_dev = vcausa_dev
            WHERE empresa = pempresa and nro_cuenta = vcuenta AND
                  nro_cheque = vnum_cheq AND
                  propias = "1";
      ELSE
         call bditrans:cert_pag2(pempresa,"CMRA",vsucursal,
                 vusuario, v_fech_hor,vfolio, vcuenta,vnum_cheq,vimporte,
                 vt_mto_divisa,vt_moneda_docto," ",0,vimporte) returning cod_ret;
         IF cod_ret != "000" THEN
            SELECT codigo INTO vcausa_dev
               FROM bdinteg:si_coddevcam
               WHERE cod_ret_rel = cod_ret and sistema_rel = vsistrans;
            IF vcausa_dev IS NULL THEN
               LET vcausa_dev = cod_ret;
            END IF;
            INSERT INTO sc_devcam
               VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,
                      vcuenta,vsucursal," ",vnum_cheq,vimporte,vcausa_dev,
                      vmoneda,"A");
            call bditrans:stmovdia(pempresa,vplaza,vsucursal,
               vusuario,v_fech_hor,"7",vt_moneda_docto,"03",vnum_cheq,
               FOLIOX,vcuenta) returning cod_ret;
            call bditrans:stmovdia(pempresa,vplaza,vsucursal,
               vusuario,v_fech_hor,"8",vt_moneda_docto,"03",vnum_cheq,
               FOLIOX,vcuenta) returning cod_ret;
            UPDATE sc_histcamara
               SET motivo_dev = vcausa_dev
               WHERE empresa = pempresa and nro_cuenta = vcuenta AND
                     nro_cheque = vnum_cheq AND
                     propias = "1";
            SELECT cancela INTO vcancelachq
               FROM sc_devolu
               WHERE codigo = vcausa_dev;
            IF vcancelachq = "S" THEN
               call bditrans:cert_pag2(pempresa,"CANC",
                  vsucursal,vusuario,v_fech_hor,vfolio,vcuenta,vnum_cheq,
                  vimporte,vt_mto_divisa,vt_moneda_docto," ",0,vimporte)
                  returning cod_ret;
            END IF
         END IF
      END IF
   END IF                                        -- Cheque CertIFicado

   IF v_tipo = "GB" THEN                         -- Giro Bancario
      SELECT moneda INTO vt_moneda_docto FROM bditrans:st_maetrans
         WHERE empresa = pempresa and tipo_docto = "04" and
               num_docto = vnum_cheq;
      IF vt_moneda_docto != vcodigo_mn THEN
         LET vt_mto_divisa = vimporte;
      ELSE
         LET vt_mto_divisa = 0;
      END IF
      IF vcausa_dev is not null and vcausa_dev <> " " and
         vcausa_dev <> "00"  and vcausa_dev <> "000"  and vcausa_dev <> "0" THEN
         INSERT INTO sc_devcam
            VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,vcuenta,
                   vsucursal," ",vnum_cheq,vimporte,vcausa_dev,vmoneda,"A");
         call bditrans:stmovdia(pempresa,vplaza,vsucursal,
            vusuario,v_fech_hor,"7",vt_moneda_docto,"04",vnum_cheq,
            FOLIOX,"") returning cod_ret;
         call bditrans:stmovdia(pempresa,vplaza,vsucursal,
            vusuario,v_fech_hor,"8",vt_moneda_docto,"04",vnum_cheq,
            FOLIOX,"") returning cod_ret;
      ELSE
         call bditrans:girbanc(pempresa,"CMRA",vtipo_docto,
            vusuario, v_fech_hor,"0",vsucursal," ",vnum_cheq,
            vt_moneda_docto,vt_mto_divisa,vimporte,
            0,0,0," ",0," ",0,0," "," "," "," "," "," "," "," ")
            returning cod_ret,v_no_cheque,v_comision,v_iva,v_total_com,
                     v_stts,vw_fech_hor;
         IF cod_ret != "000" THEN
            SELECT codigo INTO vcausa_dev
               FROM bdinteg:si_coddevcam
               WHERE cod_ret_rel = cod_ret and sistema_rel = vsistrans;
            IF vcausa_dev IS NULL THEN
               LET vcausa_dev = cod_ret;
            END IF;
            INSERT INTO sc_devcam
            VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,vcuenta,
                   vsucursal," ",vnum_cheq,vimporte,vcausa_dev,vmoneda,"A");
            call bditrans:stmovdia(pempresa,vplaza,vsucursal,
               vusuario,v_fech_hor,"7",vt_moneda_docto,"04",vnum_cheq,
               FOLIOX,"") returning cod_ret;
            call bditrans:stmovdia(pempresa,vplaza,vsucursal,
               vusuario,v_fech_hor,"8",vt_moneda_docto,"04",vnum_cheq,
               FOLIOX,"") returning cod_ret;
         END IF
      END IF
   END IF                                        -- Giro Bancario

   IF v_tipo = "CJ" THEN                         -- Cheque de Caja
      SELECT moneda INTO vt_moneda_docto FROM bditrans:st_maetrans
         WHERE empresa = pempresa and tipo_docto = "05" and
               num_docto = vnum_cheq;
      IF vt_moneda_docto != vcodigo_mn THEN
         LET vt_mto_divisa = vimporte;
      ELSE
         LET vt_mto_divisa = 0;
      END IF
      IF vcausa_dev is not null and vcausa_dev <> " " and vcausa_dev <> "00"
         and vcausa_dev <> "000" and vcausa_dev <> "0" THEN
         INSERT INTO sc_devcam
            VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,vcuenta,
                   vsucursal," ",vnum_cheq,vimporte,vcausa_dev,vmoneda,"A");
         call bditrans:stmovdia(pempresa,vplaza,vsucursal,vusuario,
               v_fech_hor, "7",vt_moneda_docto,"05",vnum_cheq,FOLIOX,"")
               returning cod_ret;
         call bditrans:stmovdia(pempresa,vplaza,vsucursal,vusuario,
               v_fech_hor, "8",vt_moneda_docto,"05",vnum_cheq,FOLIOX,"")
               returning cod_ret;
         UPDATE sc_histcamara
            SET motivo_dev = vcausa_dev
            WHERE empresa = pempresa and nro_cuenta = vcuenta AND
                  nro_cheque = vnum_cheq AND
                  propias = "1";
      ELSE
         call bditrans:chqcaj(pempresa,"CMRA",vtipo_docto,vusuario,
              v_fech_hor,
              "0","0",vsucursal," ",vnum_cheq,vt_moneda_docto,vt_mto_divisa,
              vimporte,0,0,0," ",0," ",0,0," "," "," "," ")
              returning v_comision,v_iva,v_total_com,v_stts,vw_fech_hor,
                   cod_ret,v_no_cheque;
         IF cod_ret != "000" THEN
            SELECT codigo INTO vcausa_dev
               FROM bdinteg:si_coddevcam
               WHERE cod_ret_rel = cod_ret and sistema_rel = vsistrans;
            IF vcausa_dev IS NULL THEN
               LET vcausa_dev = cod_ret;
            END IF;
            INSERT INTO sc_devcam
               VALUES(pempresa,vusuario,vcodigo_bco,vnum_remesa,vsecuencia,
                   vcuenta,
                   vsucursal," ",vnum_cheq,vimporte,vcausa_dev,vmoneda,"A");
            call bditrans:stmovdia(pempresa,vplaza,vsucursal,vusuario,
                v_fech_hor, "7",vt_moneda_docto,"05",vnum_cheq,FOLIOX,"")
                returning cod_ret;
            call bditrans:stmovdia(pempresa,vplaza,vsucursal,vusuario,
                v_fech_hor,"8",vt_moneda_docto,"05",vnum_cheq,FOLIOX,"")
                returning cod_ret;
            UPDATE sc_histcamara
              SET motivo_dev = vcausa_dev
              WHERE empresa = pempresa and nro_cuenta = vcuenta AND
                    nro_cheque = vnum_cheq AND
                    propias = "1";

            SELECT cancela INTO vcancelachq
               FROM sc_devolu
               WHERE codigo = vcausa_dev;
            IF vcancelachq = "S" THEN
               call bditrans:chqcaj(pempresa,"CANC",vtipo_docto,
                     vusuario,v_fech_hor,"0","0",vsucursal," ",vnum_cheq,
                     vt_moneda_docto,vt_mto_divisa,
                     vimporte,0,0,0," ",0," ",0,0," "," "," "," ")
                     returning v_comision,v_iva,v_total_com,v_stts,vw_fech_hor,
                          cod_ret,v_no_cheque;
            END IF
         END IF
      END IF
   END IF                                        -- Cheque de Caja
   -- Actualiza marca de movimiento aplicado en el detalle de camara
   UPDATE sc_detcam
      SET mca_aplic = "1",
          tipo_docto = vtipo_docto,
          causa_dev =  vcausa_dev
      WHERE rowid = v_rowid;

   INSERT INTO sc_valpase
      VALUES(pempresa,v_tipo,vcuenta,cod_ret);
   LET cod_ret   = "000";
END FOREACH

RETURN cod_ret;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_pagointinvcrec(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vfecha_hoy       DATE;
    DEFINE vcuenta          CHAR(20);
    DEFINE vcuentadep       CHAR(20);
    DEFINE vsucursal        CHAR(4);
    DEFINE vproducto        CHAR(4);
    DEFINE vstatus_cta      CHAR(1);
    DEFINE vsdo_actual      MONEY(14,2);
    DEFINE vhora            DATETIME HOUR TO FRACTION;
    DEFINE vhoraw           CHAR(15);
    DEFINE vfolio_suc       CHAR(16);
    DEFINE vinteres         MONEY(14,2);
    DEFINE visr             MONEY(14,2);
    DEFINE vvalor_tasa      DECIMAL(9,6);
    DEFINE vtipo_tasa       CHAR(1);
    DEFINE vprovisionado    MONEY(14,2);
    DEFINE vprovision       MONEY(14,2);
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET vcodret3      = 'PROCESO FINALIZADO';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET desc_err      = '';
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcontador3    = 0;
    LET ven_transacc  = 0;
    LET vsql          = '';
    LET vstmt         = '';
    LET vfecha_hoy    = '';
    LET vcuenta       = '';
    LET vcuentadep    = '';
    LET vsucursal     = '';
    LET vproducto     = '';
    LET vstatus_cta   = '';
    LET vsdo_actual   = 0.00;
    LET vhora         = '';
    LET vhoraw        = '';
    LET vfolio_suc    = '';
    LET vinteres      = 0.00;
    LET visr          = 0.00;
    LET vvalor_tasa   = 0.00;
    LET vtipo_tasa    = '';
    LET vprovisionado = 0.00;
    LET vprovision    = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_pagointinvcrec.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_pagointinvcrec.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'invsxmodif') THEN
        DROP TABLE "informix".invsxmodif;
    END IF;
    
    CREATE RAW TABLE "informix".invsxmodif
      (
        cuenta char(20) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_invcrecxmod ON "informix".invsxmodif(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/invcrecxact.unl INSERT INTO invsxmodif" > /resplogifx/conciliachq/invcrec.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/invcrec.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS HIGH FOR TABLE invsxmodif;
    
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM "informix".sc_fechas
     WHERE empresa = pempresa;
    
    FOREACH WITH HOLD
        SELECT a.cuenta, b.sucursal, b.producto, b.status_cta, b.sdo_actual, c.int_acum, c.isr, c.valor_tasa, c.tipo_tasa
          INTO vcuenta, vsucursal, vproducto, vstatus_cta, vsdo_actual, vinteres, visr, vvalor_tasa, vtipo_tasa
          FROM invsxmodif a,
               sc_maechq b,
               sc_tasa_var_hist c
         WHERE a.cuenta = b.cuenta
           AND a.cuenta <> '11008532097'
           AND c.empresa = b.empresa
           AND c.cuenta = b.cuenta
           AND c.tipo_tasa IN('M','P')
           AND c.fin_periodo = '02/28/2013'
         ORDER BY a.cuenta, c.tipo_tasa
        
        BEGIN WORK;
        LET ven_transacc = 1;
        
        IF vtipo_tasa = 'M' THEN
            SELECT monto_tot
              INTO vprovisionado
              FROM sc_movhis
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND fech_alt = '01/31/2013'
               AND cancelad <> 'S'
               ANd transacc = '3381';
               
            IF vprovisionado is null THEN
                LET vprovisionado = 0.00;
            END IF;
            
            LET vprovision = vinteres - vprovisionado;
        ELSE
            LET vprovision = vinteres;
        END IF;
        
        IF vstatus_cta = '2' THEN
            SELECT cuentadep
              INTO vcuentadep
              FROM sc_maeinstrucc
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
               
            SELECT sucursal, producto, status_cta, sdo_actual
              INTO vsucursal, vproducto, vstatus_cta, vsdo_actual
              FROM sc_maechq
             WHERE empresa = pempresa
               AND cuenta = vcuentadep;
               
            LET vcuenta = vcuentadep;
        END IF;
        
        LET vhora = current hour to fraction;
        LET vhoraw = vhora;
        LET vhoraw = vhoraw[1,2]||vhoraw[4,5]||vhoraw[7,8]||vhoraw[10,11];
        LET vfolio_suc = 'informix'||vhoraw[1,8];
        
        IF vinteres > 0 THEN
            INSERT INTO sc_movdia VALUES
            ( 0, vfolio_suc, vsucursal, 'informix', vfecha_hoy, vfecha_hoy, vhora, '3381', vsucursal, vproducto, pempresa, 
              vcuenta, '', 0, vprovision, vprovision, 0, 0, 0, '', vstatus_cta, vsdo_actual, "0000", " ", vvalor_tasa, '', '', '');
              
            INSERT INTO sc_movdia VALUES
            ( 0, vfolio_suc, vsucursal, 'informix', vfecha_hoy, vfecha_hoy, vhora, '3276', vsucursal, vproducto, pempresa, 
            vcuenta, '', 0, vinteres, vinteres, 0, 0, 0, '', vstatus_cta, vsdo_actual, "0000", " ", vvalor_tasa, '', '' ,'');
            
            IF visr > 0 THEN
                INSERT INTO sc_movdia VALUES
                ( 0, vfolio_suc, vsucursal, 'informix', vfecha_hoy, vfecha_hoy, vhora, '3277', vsucursal, vproducto, pempresa, 
                  vcuenta, '', 0, visr, visr, 0, 0, 0, '', vstatus_cta, vsdo_actual, "0000", " ", 0.0, '', '' ,'');
            END IF;
            
            UPDATE sc_maechq
               SET num_abonos_mes = num_abonos_mes + 1, 
                   imp_abonos_mes = imp_abonos_mes + vinteres, 
                   sdo_actual = sdo_actual + (vinteres - visr), 
                   ultpagoint = vfecha_hoy, 
                   chq_exp_mes = 0 
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF;
        
        COMMIT WORK;
        LET ven_transacc = 0;
        
        LET vcontador1 = vcontador1 + 1;
        
        LET vcuenta       = '';
        LET vcuentadep    = '';
        LET vsucursal     = '';
        LET vproducto     = '';
        LET vstatus_cta   = '';
        LET vsdo_actual   = 0.00;
        LET vhora         = '';
        LET vhoraw        = '';
        LET vfolio_suc    = '';
        LET vinteres      = 0.00;
        LET visr          = 0.00;
        LET vvalor_tasa   = 0.00;
        LET vtipo_tasa    = '';
        LET vprovisionado = 0.00;
        LET vprovision    = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1;

END PROCEDURE;

create procedure "informix".vencimiento_cap(pempresa char(3))
       returning char(5);
   define global vgfecha_hoy   date         default " ";
   define global vgprox_fecha  date         default " ";
   define global vgusuario char(8)          default " ";
   define global vgpri_hab_mes date         default " ";
   define global vgult_hab_mes date         default " ";
   define global vgtranabotrasp char(4)     default " ";

   define vcodret char(5);
   define vsqlerr integer;
   define vtrancarcap char(4);
   define vsdo_disp,vsdo_cong,vsdo_retenido money(14,2);
   define vexiste char(1);
   define vultpagocap date;
   define vfolio_suc char(16);
   define vhora datetime hour to fraction;
   define vhoraw char(15);
   define vfecpagocap datetime month to day;
   define vcuenta,vnum_cte,vcuentadep char(20);
   define vsucursal char(4);
   define vstatus_cta char(1);
   define vpaga_capital char(1);
   define vsistema,vinstrucc,vtp_moneda char(2);
   define vtranretcap,vproducto char(4);
   define vsdo_actual money(14,2);
   define vfecha_pago date;
   define vmensaje char(60);
   define vsolbcos integer;
   define vnum_tarjeta char(16);
   define vmaxsec smallint;


   let vcodret = "000";

begin
   on exception set vsqlerr
      if vsqlerr <> 0 then
         let vcodret = vsqlerr;
         return vcodret;
      end if;
   end exception;

   foreach
      select mc.cuenta,mc.num_cte,mc.sucursal,status_cta,pr.paga_capital,
             divisa,mc.producto,sdo_actual,sdo_cong,sdo_retenido,
             mc.ultpagocap,fecpagocap
         into vcuenta,vnum_cte,vsucursal,vstatus_cta,vpaga_capital,
             vtp_moneda,vproducto,vsdo_actual,vsdo_cong,vsdo_retenido,
             vultpagocap,vfecpagocap
         from sc_maechq mc,sc_maenoc mn,sc_producto pr
         where mc.empresa = pempresa and status_cta = "1"
               and mc.empresa = mn.empresa and mc.cuenta = mn.cuenta
               and pr.empresa = mc.empresa and pr.producto = mc.producto

      if vpaga_capital is null then
         let vpaga_capital = "N";
      end if

      if vfecpagocap = "" or vfecpagocap is null then
         let vfecha_pago = "";
      else
         let vfecha_pago = mdy(month(vfecpagocap),day(vfecpagocap),
                               year(vgfecha_hoy));
         if vfecha_pago <= vultpagocap then
            let vfecha_pago = vfecha_pago + 1 units year;
         end if
      end if

      if vpaga_capital = "S" and vsdo_retenido = 0 and
         vfecha_pago >= vgfecha_hoy and vfecha_pago < vgprox_fecha then
         if vsdo_actual > 0 then
            select instrucc,sistema,cuentadep
               into vinstrucc,vsistema,vcuentadep
               from sc_maeinstrucc
               where empresa = pempresa and cuenta = vcuenta and
                     capint = "C";
            if vinstrucc is null then
               let vinstrucc = "03";
               insert into sc_maeinstrucc
                  values(pempresa,vcuenta,"C","03","12","","N");
            end if
            if vinstrucc <> "01" then
               let vhora = current hour to fraction;
               let vhoraw = vhora;
               let vhoraw = vhoraw[1,2] || vhoraw[4,5] || vhoraw[7,8] ||
                            vhoraw[10,11];
               let vfolio_suc = vgusuario || vhoraw[1,8];
               select trans_cap into vtrancarcap
                  from sc_instrucc
                  where empresa = pempresa and instrucc = vinstrucc;
               if vsistema = "01" and vcuentadep <> "" then
                  select max(secuencia) into vmaxsec
                     from sc_tarjeta
                     where empresa = pempresa and cuenta = vcuentadep and
                           tipo_tarjeta = "T";
                  select num_tarjeta into vnum_tarjeta
                     from sc_tarjeta
                     where empresa = pempresa and cuenta = vcuentadep and
                           secuencia = vmaxsec;
                  insert into sc_movdia
                     values (0,vfolio_suc,vsucursal,vgusuario,vgfecha_hoy,
                     vgfecha_hoy,vhora,vgtranabotrasp,vsucursal,vproducto,
                     pempresa,vcuentadep, "",0,vsdo_actual,vsdo_actual,0,
                     0,0,"","1",vsdo_actual,"0000"," ",0,vnum_tarjeta,"","");
               else
                  call bdibanco:sbsp_graba_solchq(pempresa,vnum_cte,vgusuario,
                                                  vsdo_actual,vcuenta)
                       returning vcodret,vmensaje,vsolbcos;
                  if vcodret = "00000" then
                     let vcodret = "000";
                  end if
               end if
               update sc_maeinstrucc
                  set aplicado = "S"
                  where empresa = pempresa and cuenta = vcuenta and
                        capint = "C";
               insert into sc_movdia
                  values (0,vfolio_suc,vsucursal,vgusuario,vgfecha_hoy,
                     vgfecha_hoy,vhora,vtrancarcap,vsucursal,vproducto,
                     pempresa,vcuenta, "",0,vsdo_actual,vsdo_actual,0,0,
                     0,"","1",vsdo_actual,"0000"," ",0,vnum_tarjeta,"","");
               update sc_maechq
                  set (num_cgos_mes,imp_cgos_mes,sdo_actual) =
                      (num_cgos_mes + 1,imp_cgos_mes + vsdo_actual,
                       sdo_actual - vsdo_actual)
                  where empresa = pempresa and cuenta = vcuenta;
            end if
         end if
      end if
   end foreach
   return vcodret;
end
end procedure;

CREATE PROCEDURE "informix".sp_rptainvcrecconcta3anios()
RETURNING CHAR(5), CHAR (60); --- CodigoRetorno, Mensaje

    -- // Declaracion de Variables
    DEFINE vSqlError    SMALLINT;
    DEFINE vIsamError   SMALLINT;
    DEFINE vDescError   CHAR (50);
    DEFINE cCodRet      CHAR (5);
    DEFINE cCodRet2     CHAR (5);
    DEFINE cCodRet3     CHAR (50);
    DEFINE dFechaHoy    DATE;
    DEFINE dProxFecha   DATE;
    DEFINE cDiasxVencer CHAR (5);
    DEFINE cMensaje     CHAR (60);
    DEFINE vsql         CHAR(600);
    DEFINE vstmt        CHAR(250);
    DEFINE vfecha       CHAR(8);
    
    -- // Inicializacion de Variables
    LET vSqlError    = 0;
    LET vIsamError   = 0;
    LET vDescError   = '';
    LET cCodRet      = '00000';
    LET cCodRet2     = '';
    LET cCodRet3     = '';
    LET dFechaHoy    = '';
    LET dProxFecha   = '';
    LET cDiasxVencer = '';
    LET cMensaje     = 'EL PROCESO SE EJECUTO EXITOSAMENTE';
    LET vsql         = '';
    LET vstmt        = '';
    LET vfecha       = '';

    BEGIN

    ON EXCEPTION SET vSqlError, vIsamError, vDescError
        SET DEBUG FILE TO "/tmp/sp_rptainvcrecconcta3anios.err";
        TRACE ON;
        IF vSqlError <> 0 THEN
            LET cCodRet = vSqlError;
            LET cCodRet2 = vIsamError;
            LET cCodRet3 = vDescError;
            RETURN cCodRet, 'Ocurrio un Error Durante La Ejecucion Del Procedimiento';
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/tmp/sp_rptainvcrecconcta3anios.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- // LIMPIAR LA TABLA
    IF EXISTS(SELECT tabname FROM bdicheq:systables WHERE tabname = 'sc_invcrecconcta3anios') THEN
        DROP TABLE sc_invcrecconcta3anios;
    END IF;

    CREATE TABLE sc_invcrecconcta3anios 
        ( 
            sucursal            CHAR(4)     NOT NULL, 
            promotor            CHAR(8)     NOT NULL,
            numcte              CHAR(9)     NOT NULL , 
            nombre_cte          CHAR(108),
            numcta              CHAR(20)    NOT NULL , 
            cta_eje             CHAR(20),
            fecha_apertura      DATE, 
            fecha_vencimiento   DATE, 
            telefono1           CHAR(15),
            telefono2           CHAR(15),
            telefono3           CHAR(15),
            extension           CHAR(5),
            correo_elect        CHAR(50)
        )
    EXTENT SIZE 2048 NEXT SIZE 1024 LOCK MODE ROW;
    CREATE INDEX idx_invcrec3anios_cta_suc ON sc_invcrecconcta3anios (sucursal) ONLINE;
    CREATE INDEX idx_invcrec3anios_cta_ven ON sc_invcrecconcta3anios (fecha_vencimiento) ONLINE;
    CREATE INDEX idx_invcrec3anios_cta_cta ON sc_invcrecconcta3anios (numcta) ONLINE;
    UPDATE STATISTICS MEDIUM FOR TABLE sc_invcrecconcta3anios;
    
    -- // Obtener Parametros
    SELECT fecha_hoy, prox_fecha  
      INTO dFechaHoy, dProxFecha 
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';
     
    -- // OBTIENE PARAMETRO DE DIAS
    SELECT TRIM (valor) 
      INTO cDiasxVencer 
      FROM bdicheq:sc_param 
     WHERE empresa = "001"
       AND codparam = 'DiasRptsCtaIna3anios';	

    -- // Proceso para la Inversion Creciente
    INSERT INTO sc_invcrecconcta3anios
    SELECT mae.sucursal, noc.ejecutivo, mae.num_cte, 
           TRIM(cte.nombre1)||' '||TRIM(NVL(cte.nombre2,''))||' '||TRIM(cte.apell_paterno)||' '||TRIM(NVL(cte.apell_materno,'')), 
           mae.cuenta, ins.cuentadep, mae.fecultdep, noc.fecha_mod, tel1.telefono, tel2.telefono, tel3.telefono, tel3.extension, cor.correo_elec
      FROM bdicheq:sc_maechq mae 
     INNER JOIN bdicheq:sc_maenoc noc ON (noc.empresa = mae.empresa AND noc.cuenta = mae.cuenta)
     INNER JOIN bdicheq:sc_maeinstrucc ins ON (ins.empresa = mae.empresa AND ins.cuenta = mae.cuenta)
     INNER JOIN bdinteg:si_cliente cte ON (cte.numcte = mae.num_cte) 
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = cte.numcte AND tel1.tipo_tel = 1)
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = cte.numcte AND tel2.tipo_tel = 2)
      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = cte.numcte AND tel3.tipo_tel = 3)
      LEFT OUTER JOIN bdinteg:si_correos cor ON (cor.numcte = cte.numcte AND cor.tipo_correo = 1 AND cor.status_correo = 'A')
     WHERE mae.producto = '1100'
       AND mae.status_cta <> '2'
       AND dFechaHoy - mae.fecultdep >= 1060
       AND noc.fecha_mod BETWEEN dProxFecha AND ( dProxFecha + cDiasxVencer::INTEGER )
       AND LENGTH(ins.cuentadep) = 11 
       AND ins.capint = 'R';
       
    UPDATE STATISTICS MEDIUM FOR TABLE sc_invcrecconcta3anios;
    
    -- // GENERA EL ARCHIVO PARA OPERACIONES
    LET vfecha = TO_CHAR(dFechaHoy, '%d%m%Y');
    
    LET vsql = '';
    LET vsql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/InvCrec3anios_'||vfecha||'.txt '||
               'SELECT * FROM sc_invcrecconcta3anios;" > /resplogifx/conciliachq/invcrec3anios2.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '';
    LET vstmt = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/invcrec3anios2.sql"; 
    SYSTEM vstmt;
    LET vstmt = '';
    
    RETURN cCodRet, cMensaje;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_rep_contraloria_pba()
RETURNING CHAR(5);
    
    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE vsqlerr          INTEGER;  
    DEFINE visamerr         INTEGER;  
    DEFINE vdescerr         CHAR(50);  
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     CHAR(1);
    DEFINE vcontador        INTEGER;	
    DEFINE vfecha_ini       DATE; 
    DEFINE vfecha_fin       DATE; 
    DEFINE vfecha_hoy	    DATE; 
    DEFINE vfecha_ant       DATE;
    DEFINE fecha_movhis     DATE;
    DEFINE fecha_movhisold  DATE;
    DEFINE vfechades        CHAR(8);
    DEFINE vempresa         CHAR(3);
    DEFINE vnum_serial      INTEGER;
    DEFINE ccuenta       	CHAR(20);
    DEFINE cfecha    		DATE;
    DEFINE ctransacc     	CHAR(4);
    DEFINE cmonto    		MONEY(18,2);
    DEFINE vdescripcion		CHAR(50);
    DEFINE vnumcte			CHAR(20);
    DEFINE vsucursal		CHAR(4);
    DEFINE vpaterno			CHAR(26);
    DEFINE vmaterno			CHAR(26);
    DEFINE vnombre1			CHAR(26);
    DEFINE vnombre2			CHAR(26);
    DEFINE vrazon			CHAR(60);
    DEFINE vnombrecalle		CHAR(30);
    DEFINE vnumext			CHAR(10);
    DEFINE vnumint			CHAR(10);
    DEFINE vnombrezona		CHAR(32);
    DEFINE vcpostal			CHAR(5);
    DEFINE vnomciudad		CHAR(30);
    DEFINE viniestado		CHAR(4);
    DEFINE vtelefono1		CHAR(13);
    DEFINE vtelefono2 		CHAR(13);
    DEFINE vtelefono3		char(13);
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(200);

    LET vcodret         = "000";
    LET vcodret2        = "";
    LET vcodret3        = "";
    LET vsqlerr         = 0;
    LET visamerr        = 0;
    LET vdescerr        = '';
    LET vcomienza       = -1;
    LET ven_transacc    = '0';
    LET vcontador       = 0;
    LET vfecha_ini      = '';
    LET vfecha_fin      = '';
    LET vfecha_hoy 	    = '';
    LET vfecha_ant      = '';
    LET fecha_movhis    = '';
    LET fecha_movhisold = '';
    LET vfechades       = '';
    LET vempresa        = '001';
    LET vnum_serial     = 0;
    LET ccuenta         = "";
    LET cfecha    	    = '';
    LET ctransacc       = "";
    LET cmonto   	    = 0.00;
    LET vdescripcion    = "";
    LET vnumcte		    = "";
    LET vsucursal	    = "";
    LET vpaterno	    = "";
    LET vmaterno	    = "";
    LET vnombre1	    = "";
    LET vnombre2	    = "";
    LET vrazon		    = "";
    LET vnombrecalle    = "";
    LET vnumext		    = "";
    LET vnumint		    = "";
    LET vnombrezona	    = "";
    LET vcpostal	    = "";
    LET vnomciudad	    = "";
    LET viniestado	    = "";
    LET vtelefono1	    = "";
    LET vtelefono2 	    = "";
    LET vtelefono3	    = "";
    LET vsql            = "";
    LET vstmt           = "";
	
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_rep_contraloria.out";
    --- TRACE ON; 
    
    BEGIN
    
    ON EXCEPTION SET vsqlerr, visamerr, vdescerr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_rep_contraloria.err";
        TRACE ON; 
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = visamerr;
            LET vcodret3 = vdescerr;
            IF ven_transacc = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;
    
	SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy, fecha_ant
	  INTO vfecha_hoy, vfecha_ant
	  FROM sc_fechas
	 WHERE empresa = vempresa;
    
    IF WEEKDAY(vfecha_hoy) = 2 THEN
        IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'tmp_rep_cont' ) THEN
            DROP TABLE tmp_rep_cont;
        END IF	
            
        CREATE TABLE tmp_rep_cont 
          ( 
            cuenta       	char(20),
            fech_alt     	date,
            sucursal        char(4),
            transacc     	char(4),
            descripcion    	char(50),
            monto_tot    	money,
            num_cte         char(20),
            apell_paterno  	char(26),
            apell_materno  	char(26),
            nombre1        	char(26),
            nombre2        	char(26),
            razon_social   	char(60),
            nombrecalle    	char(30),
            numeroextcalle 	char(10),
            numerointcalle 	char(10),
            nombrezona      char(32),
            cod_postal     	char(5),
            nombreciudad    char(30),
            inicialestado   char(4),
            telefono1   	char(13),
            telefono2   	char(13),
            telefono3   	char(13)
          )
        EXTENT SIZE 150000 NEXT SIZE 15000 LOCK MODE ROW;
    END IF;
	
	FOREACH WITH HOLD
        SELECT {+INDEX(sc_movhis idx_movhisnew4)}
               mov1.num_serial, mov1.cuenta, mov1.sucursal, mov1.fech_alt, mov1.transacc, mov1.monto_tot, trx1.descripcion, mae.num_cte
          INTO vnum_serial, ccuenta, vsucursal, cfecha, ctransacc, cmonto, vdescripcion, vnumcte
          FROM sc_movhis mov1,
               bdinteg:si_transacc trx1,
               sc_maechq mae
         WHERE mov1.empresa = vempresa
           AND mov1.cuenta <> '16000000012'
           AND mov1.fech_alt = vfecha_ant
           AND mov1.cancelad <> "S"
           AND mov1.transacc IN("0202", "0204", "0250", "0282", "0310", "0325", "0223") 
           AND trx1.numero = mov1.transacc
           AND mae.cuenta = mov1.cuenta
           AND mae.producto = mov1.producto
        
		IF vcomienza = -1 THEN
            BEGIN WORK;
            LET vcomienza = 0;
            LET ven_transacc = '1';
        END IF;
        
        INSERT INTO tmp_rep_cont( cuenta, fech_alt, sucursal, transacc, descripcion, monto_tot, num_cte )
        VALUES( ccuenta, cfecha, vsucursal, ctransacc, vdescripcion, cmonto, vnumcte );
        
        LET vcontador = vcontador + 1;
        
        IF vcontador >= 10000 THEN
            COMMIT WORK;
            BEGIN WORK;
            LET vcontador = 0;
        END IF;
	END FOREACH
    
    IF ven_transacc = '1' THEN
        COMMIT WORK;
        LET ven_transacc = '0';
    END IF;
    
    IF WEEKDAY(vfecha_hoy) = 2 THEN
        CREATE INDEX idx_tmp_rep_cont_1 ON tmp_rep_cont(num_cte) USING BTREE;
        CREATE INDEX idx_tmp_rep_cont_2 ON tmp_rep_cont(fech_alt) USING BTREE;
		CREATE INDEX idx_tmp_rep_cont_3 ON tmp_rep_cont(num_cte, fech_alt) USING BTREE;
    END IF;
    
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_rep_cont;
    
    LET vcontador = 0;
    LET vcomienza = -1;
    LET ven_transacc = '0';
    
    FOREACH WITH HOLD
        SELECT {+INDEX(tmp_rep_cont idx_tmp_rep_cont_2)}
               UNIQUE num_cte
          INTO vnumcte
          FROM tmp_rep_cont
         WHERE fech_alt = vfecha_ant
          
        IF vcomienza = -1 THEN
            BEGIN WORK;
            LET vcomienza = 0;
            LET ven_transacc = '1';
        END IF;
          
        SELECT cte.apell_paterno, cte.apell_materno, cte.nombre1, cte.nombre2, cte.razon_social, calle.nombrecalle, dir.numeroextcalle, dir.numerointcalle, 
               zona.nombrezona, dir.cod_postal, ciudad.nombreciudad, ciudad.inicialestado, tel1.telefono, tel2.telefono, tel3.telefono
          INTO vpaterno, vmaterno, vnombre1, vnombre2, vrazon, vnombrecalle, vnumext, vnumint, 
               vnombrezona, vcpostal, vnomciudad, viniestado, vtelefono1, vtelefono2, vtelefono3
          FROM bdinteg:si_cliente cte
         INNER JOIN bdinteg:si_direcciones_actual dir ON (dir.numcte = cte.numcte AND dir.tipo_dir = '1')
          LEFT OUTER JOIN bdinteg:si_catcalles calle ON (calle.numerocalle = dir.numerocalle)
          LEFT OUTER JOIN bdinteg:si_catciudades ciudad ON (ciudad.numerociudad = dir.numerociudad)
          LEFT OUTER JOIN bdinteg:si_catzonas zona ON (zona.numerociudad = dir.numerociudad AND zona.numerocolonia = dir.numerocolonia) 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1 AND tel1.status_tel = 'A')
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2 AND tel2.status_tel = 'A')
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3 AND tel3.status_tel = 'A')
         WHERE cte.numcte = vnumcte;
           
        UPDATE {+INDEX(tmp_rep_cont idx_tmp_rep_cont_1)} tmp_rep_cont
           SET ( apell_paterno, apell_materno, nombre1, nombre2, razon_social, nombrecalle, numeroextcalle, numerointcalle, 
                 nombrezona, cod_postal, nombreciudad, inicialestado, telefono1, telefono2, telefono3 ) =
               ( vpaterno, vmaterno, vnombre1, vnombre2, vrazon, vnombrecalle, vnumext, vnumint, 
                 vnombrezona, vcpostal, vnomciudad, viniestado, vtelefono1, vtelefono2, vtelefono3 )
         WHERE num_cte = vnumcte
		   AND fech_alt = vfecha_ant;
        
        LET vcontador = vcontador + 1;
        
        IF vcontador >= 10000 THEN
            COMMIT WORK;
            BEGIN WORK;
            LET vcontador = 0;
        END IF;
    END FOREACH;
    
    IF ven_transacc = '1' THEN
        COMMIT WORK;
        LET ven_transacc = '0';
    END IF;
    
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_rep_cont;
    
    IF WEEKDAY(vfecha_hoy) = 1 THEN
        LET vfechades = SUBSTR(vfecha_ant,7,4) || SUBSTR(vfecha_ant,1,2) || SUBSTR(vfecha_ant,4,2);
        LET vfechades = vfechades;
        
        LET vsql =  'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/dep_contral_'||vfechades||'.unl '||
                    'SELECT * FROM tmp_rep_cont;" > /resplogifx/conciliachq/query_contraloria.sql';
        SYSTEM vsql;
        
        LET vstmt = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/query_contraloria.sql"; 
        SYSTEM vstmt;
    END IF;

	END;
    
    RETURN vcodret;
	
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultamovimientoscen_pba(cTipo CHAR(1), siRegistros SMALLINT, cSucursal CHAR(4))

    RETURNING
    CHAR(5),            -- Codigo de Retorno
    CHAR(8),            -- Codigo Usuario
    CHAR(8),            -- Secuencia
    CHAR(4),            -- Transaccion Sucursal
    MONEY(14,2),        -- Monto
    CHAR(1),            -- Cancelado o Reversado
    CHAR(2)             -- Sistema

    --  DEFINICION DE VARIABLES --
    DEFINE iSqlErr INTEGER;
    DEFINE cCodRet CHAR(5);
    DEFINE cCodUsuario CHAR(8);
    DEFINE cSecuencia CHAR(8);
    DEFINE cTransaccSuc CHAR(4);
    DEFINE mMonto MONEY(14,2);
    DEFINE siCiclo SMALLINT;
    DEFINE cCanRev CHAR(1);
    DEFINE cSistema CHAR(2);
    DEFINE iSecuencia INTEGER;
    DEFINE cfolio_suc CHAR(16);
    DEFINE v_fecha_hoy DATE;

    -- INICIALIZACION DE VARIABLES --
    LET iSqlErr = 0;
    LET cCodRet = '000';
    LET cCodUsuario = '';
    LET cSecuencia = '';
    LET cTransaccSuc = '';
    LET mMonto = '';
    LET siCiclo = 0;
    LET cCanRev = '';
    LET cSistema = '';
    LET iSecuencia = 0;
    LET cfolio_suc = '';
    LET v_fecha_hoy = DATE(1);

    SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

    --SET DEBUG FILE TO "/home/sysifx/sp_consultamovimientoscen.out";
    --TRACE ON;

    BEGIN
        ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET cCodRet = iSqlErr;
                RETURN cCodRet, cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev, cSistema;
            END IF;
        END EXCEPTION;
		
        -- Debito
        SELECT fecha_hoy INTO v_fecha_hoy FROM bdicheq:"informix".sc_fechas;

        IF cTipo = "1" OR cTipo = "4" THEN
            FOREACH
                SELECT {+ INDEX (sc_movdia idx_sucempbdicheq)} SUBSTR(folio_suc, 1, 8), 
				SUBSTR(folio_suc, 9, 16), transacc_suc, monto_tot, cancelad
                INTO cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev
                FROM bdicheq:"informix".sc_movdia
                WHERE sucursal = cSucursal AND empresa = '001' AND fech_alt = v_fecha_hoy

                LET cSistema = "SC";
                LET siCiclo = siCiclo + 1;
                IF siCiclo <= siRegistros THEN
                    CONTINUE FOREACH;
                END IF;

                RETURN cCodRet, cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev, cSistema WITH RESUME;
            END FOREACH;
        END IF;

        -- Inversion
        SELECT fecha_hoy INTO v_fecha_hoy FROM bdinvers:"informix".sv_fechas;

        IF cTipo = "2" OR cTipo = "4" THEN
            FOREACH
                SELECT {+ INDEX (sv_movdia idx_sucempbdinvers)} SUBSTR(folio_suc, 1, 8), 
				SUBSTR(folio_suc, 9, 16), transacc_suc, monto_tot, cancelad
                INTO cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev
                FROM bdinvers:"informix".sv_movdia 
				WHERE empresa = '001' AND sucursal = cSucursal AND fech_alt = v_fecha_hoy

                LET cSistema = "SV";
                LET siCiclo = siCiclo + 1;
                IF siCiclo <= siRegistros THEN
                    CONTINUE FOREACH;
                END IF;

                RETURN cCodRet, cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev, cSistema WITH RESUME;
            END FOREACH;
        END IF;

		-- Se anexa acceso a la tabla de fechas
        SELECT fecha_hoy INTO v_fecha_hoy FROM bdicred:"informix".sd_fechas;

        -- Credito
        IF cTipo = "3" OR cTipo = "4" THEN
            FOREACH
                -- DSB 25/05/2009
                SELECT folio_suc, MIN(secuencia) INTO cfolio_suc, iSecuencia
                FROM bdicred:"informix".sd_movdia
                WHERE ((codigo_fun IN ("033", "333") AND codigo_ref = 1) OR (codigo_fun = "336" AND codigo_ref = 20) OR (codigo_fun = "002" AND codigo_ref IN (50,60)))
                AND sucursal = cSucursal AND fecha_mov = v_fecha_hoy
                GROUP BY folio_suc
				UNION ALL	-- DSB 16/06/2011
				SELECT folio_suc, MIN(secuencia)
                FROM bdicred:"informix".sd_movdiacrd
                WHERE (codigo_fun IN ("020", "221", "223", "225", "027", "028") AND codigo_ref = 1) --se agrega el codigo_fun 225 ,027 y 028
				AND sucursal = cSucursal AND fecha_mov = v_fecha_hoy
                GROUP BY folio_suc

				FOREACH
	                SELECT SUBSTR(folio_suc, 1, 8), SUBSTR(folio_suc, 9, 16), transacc_suc, monto, reversado
	                INTO cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev
	                FROM bdicred:"informix".sd_movdia
	                WHERE empresa = '001' AND secuencia = iSecuencia AND fecha_mov = v_fecha_hoy AND hora_mov >= DATE(0)
	                AND sucursal = cSucursal AND num_credito > '' AND folio_suc = cfolio_suc
					UNION ALL	-- DSB 16/06/2011
					SELECT SUBSTR(folio_suc, 1, 8), SUBSTR(folio_suc, 9, 16), transacc_suc, monto, reversado
	                FROM bdicred:"informix".sd_movdiacrd
	                WHERE empresa = '001' AND secuencia = iSecuencia AND fecha_mov = v_fecha_hoy AND hora_mov >= DATE(0)
					AND sucursal = cSucursal AND num_credito > '' AND folio_suc = cfolio_suc

	                LET cSistema = "SD";
	                LET siCiclo = siCiclo + 1;
	                IF siCiclo <= siRegistros THEN
	                    CONTINUE FOREACH;
	                END IF;

					RETURN cCodRet, cCodUsuario, cSecuencia, cTransaccSuc, mMonto, cCanRev, cSistema WITH RESUME;
				END FOREACH;
            END FOREACH;
        END IF;
    END;
END PROCEDURE
DOCUMENT
"Consulta Movimientos en Central",
"AUTOR: Iris Arias Zazueta",
"FECHA: 19/03/2009",
"MODIFICACION: 25/05/2009 - Se consulta para obtener la minima secuencia de cada registro",
"REALIZO: Iris Arias Zazueta",
"MODIFICACION: 16/06/2011 - Se consulta los movimientos de prestamos a plazo",
"REALIZO: Iris Arias Zazueta",
"BD: bdicheq";

CREATE PROCEDURE "informix".pasamovshistoldcomp1_pba(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER, INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vfecha_hoy       DATE;
    DEFINE vfecha_ant       DATE;
    DEFINE vexiste          SMALLINT;
    DEFINE vexistefin       SMALLINT;
    DEFINE vfechaproc       SMALLINT;
    DEFINE vsql             char(600);
    DEFINE vstmt            char(250);
    DEFINE vexistefinproc   CHAR(1);
    DEFINE vproceso         CHAR(20);
    DEFINE vsistema         CHAR(2);
    DEFINE vusuario         CHAR(10);
    DEFINE vexiste_fecha    SMALLINT;
    
    DEFINE vcodretparam     CHAR(5);
    DEFINE vserial_inicial  INTEGER;
    DEFINE vserial_final    INTEGER;
    DEFINE vcomienza        INTEGER;
    DEFINE vcont_commit     INTEGER;
    DEFINE vnum_serial      INTEGER;
    
    LET vcodret1        = '000';
    LET vcodret2        = '000';
    LET sql_err	        = 0;
    LET isam_err        = 0;
    LET vcontador1      = 0;
    LET vcontador2      = 0;
    LET vcontador3      = 0;
    LET ven_transacc    = 0; 
    
    LET vfecha_hoy      = ''; 
    LET vfecha_ant      = '';
    LET vexiste         = 0;
    LET vexistefin      = 0;
    LET vfechaproc      = 0;
    LET vsql            = '';
    LET vstmt           = '';
    LET vexistefinproc  = '';
    LET vproceso        = 'PasaMovsHistOldComp1';
    LET vsistema        = '01';
    LET vusuario        = user;
    LET vexiste_fecha   = 0;
    
    LET vcodretparam    = '';    
    LET vserial_inicial = 0;
    LET vserial_final   = 0;
    LET vcomienza       = -1;
    LET vcont_commit    = 0;
    LET vnum_serial     = 0;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistoldcomp1.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold1.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold1.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistoldcomp1.out";
    --- TRACE ON;
    
    SET OPTIMIZATION HIGH;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    SELECT valor
      INTO vfecha_ant
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PasoMovhis_MovhisOld';
        
    -- // VALIDA HAYA INICIADO EL PROCESO PRINCIPAL
    WHILE vfechaproc = 0
        SET ISOLATION TO DIRTY READ;
    
        SELECT COUNT(*)
          INTO vfechaproc
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'ini_pasomovshistold'
           AND fecha = vfecha_ant;
    END WHILE;
    
    -- // Guarda inicio de proceso     
    SELECT COUNT(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vfecha_hoy
       AND sistema = vsistema;

    IF vexiste = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horaspasamovsold1.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold1.sql';
        SYSTEM vstmt;
    ELSE
        SELECT COUNT(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";
           
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold1.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold1.sql';
            SYSTEM vstmt;
        ELSE
            SELECT "1"
              INTO vexistefinproc
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = "pasomovshistoldcomp1"
               AND fecha = vfecha_ant;
               
            IF vexistefinproc = "1" THEN
                LET vcodret1 = "958";
                RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
            END IF
        END IF;
    END IF;
    
    -- // OBTIENE VALORES PARA RANGO DE SERIALES A PROCESAR
    SELECT valor::integer
      INTO vserial_inicial
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'SerIniPasoMovHisOld1';
       
    SELECT valor::integer
      INTO vserial_final
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'SerIniPasoMovHisOld2';
       
    -- // OBTIENE EL NUMERO DE REGISTROS A TRASPASAR
    SELECT {+INDEX(sc_movhis idx_movhis_serial)}
           COUNT(*)
      INTO vcontador1
      FROM sc_movhis
     WHERE fech_alt = vfecha_ant
       AND num_serial >= vserial_inicial
       AND num_serial < vserial_final;
    
    FOREACH WITH HOLD 
        SELECT {+INDEX(sc_movhis idx_movhis_serial)}
               num_serial
          INTO vnum_serial
          FROM sc_movhis
         WHERE fech_alt = vfecha_ant
           AND num_serial >= vserial_inicial
           AND num_serial < vserial_final
           
        /*
        IF vcomienza = -1 THEN
            BEGIN WORK;
            LET vcomienza = 0;
            LET ven_transacc = 1;
        END IF;
        */
        
        BEGIN WORK;
        LET ven_transacc = 1;
        
        INSERT INTO sc_movhis_old
        SELECT {+INDEX(sc_movhis idx_movhis_serial)}
               mov.*
          FROM sc_movhis mov
         WHERE mov.fech_alt = vfecha_ant
           AND mov.num_serial = vnum_serial;
         
        DELETE {+INDEX(sc_movhis idx_movhis_serial)}
          FROM sc_movhis
         WHERE fech_alt = vfecha_ant
           AND num_serial = vnum_serial;
         
        LET vcont_commit = vcont_commit + 1;
        
        COMMIT WORK;
        LET ven_transacc = 0;
        
        /*
        IF vcont_commit >= 5000 THEN
            COMMIT WORK;
            BEGIN WORK;
            LET vcont_commit = 0;
        END IF;
        */
    END FOREACH;
    
    /*
    IF ven_transacc = 1 THEN
        COMMIT WORK;
        LET ven_transacc = 0;
    END IF;
    */
    
    SELECT {+INDEX(sc_movhis_old idx_movhis_serial_old)}
           COUNT(*)
      INTO vcontador2
      FROM sc_movhis_old
     WHERE fech_alt = vfecha_ant
       AND num_serial >= vserial_inicial
       AND num_serial < vserial_final;
     
    SELECT {+INDEX(sc_movhis idx_movhis_serial)}
           COUNT(*)
      INTO vcontador3
      FROM sc_movhis
     WHERE fech_alt = vfecha_ant
       AND num_serial >= vserial_inicial
       AND num_serial < vserial_final;
       
    IF vcontador1 = vcontador2 THEN
        LET vcodret1 = '000'; -- // PROCESO CONCLUIDO SATISFACTORIAMENTE
        LET vcodret2 = '000';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vusuario||''','||
                   'status_proc   = '''||'F'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold1.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold1.sql';
        SYSTEM vstmt;
           
        UPDATE sc_contproc
           SET fecha   = vfecha_ant
         WHERE empresa = pempresa
           AND proceso = 'pasomovshistoldcomp1';
    ELSE
        LET vcodret1 = '999'; -- // LOS MOVIMIENTOS TRASPASADOS NO COINCIDEN CON LOS MOVIMIENTOS A TRASAPASAR
        LET vcodret2 = '999';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold1.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold1.sql';
        SYSTEM vstmt;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;

END PROCEDURE;

create procedure "informix".bloqueo_cta_pba( pempresa     char(3),
                                         pcuenta      char(20),
                                         pmonto       money(14,2),                          
                                         pcodbloq     char(2),
                                         popbloq      integer,
                                         pfechabloq   char(10),
                                         pusuario     char(8),
                                         pclave       char(5),
										 pAreaSolic   CHAR(2),
										 pCodArea     CHAR(1),
										 pTipoBloq    CHAR(2),
										 pCodTipoBloq CHAR(1) )
returning char(5), char(5);

    define cod_ret                  char(3);
    define cta_w,x_cta              char (20);
    define suc_w                    char (4);
    define usu_w                    char (5);
    define prod_w                   char (4);
    define banca_w                  char (3);
    define v_long_cta               char (2);
    define mov, status_w            char (1);
    define status2_w                char (1);
    define sdoc_w                   money (14,2);
    define sdod_w                   money (14,2);
    define sdoa_w                   money (14,2);
    define fecha_w                  date;
    define hora_w                   char(15);
    define edo_cta_w                char (1);
    define v_cal_int_chq            char (1);
    define v_folio                  char (16);
    define folio2                   char(8);
    define longitud                 smallint;
    define v_transacc, v_clave      char(4);
    define v_mesdia                 char(4);
    define vmonto_cong              money(14,2);
    define vsdoxdesbloq,vimporte    money(14,2);
    define vrowid                   integer;
    define vfecha                   date;
    define vmaxsec                  smallint;
    define vnum_tarjeta             char(16);

    let cod_ret = "000";
    let v_clave = "0000";
    
    -- // Verifica recepcion completa de datos
    if pfechabloq = "" or pcuenta = "" or pmonto = "" or popbloq ="" or pcodbloq = "" or pusuario = "" then
        let cod_ret = 110;
        return cod_ret, v_clave;
    end if;
    
    let x_cta = pcuenta;
    
    select cuenta, sucursal, producto, status_cta, sdo_cong, sdo_actual, sdo_actual - sdo_cong - sdo_retenido
      into cta_w, suc_w, prod_w, status_w, sdoc_w, sdoa_w, sdod_w
      from sc_maechq
     where empresa = pempresa 
       and cuenta = pcuenta;

    --- SET DEBUG FILE TO "/dbexportb/vlv/bloqueo_cta.out";
    --- TRACE ON
	   
    -- // Verifica el Saldo a Congelar de la Cuenta
    if pmonto > sdoa_w - sdoc_w and pcodbloq <> "00" then
        let cod_ret = "162";
        return cod_ret, v_clave;
    end if

    -- // Verifica el Saldo a desbloquear de la Cuenta
    if  pmonto > sdoc_w and pcodbloq = "00" then
        let cod_ret = "163";
        return cod_ret, v_clave;
    end if

    -- // Verifica existencia de la Cuenta
    if cta_w is null then
    
        let cod_ret = 100;
        return cod_ret, v_clave;
        
    elif status_w = "1" then -- // Verifica si la cuenta esta activa y no esta bloqueada
    
        if pcodbloq = "00" then
            let cod_ret = "302";
            return cod_ret, v_clave;
        end if
    
    elif status_w in ("2","6","7") then -- // Verifica que la cuenta no este cancelada
    
        let cod_ret = 200;
        return cod_ret, v_clave;
    
    elif status_w = "3" then -- // Verifica que la cuenta no haya sido bloqueada previamente
    
        if pcodbloq != "00" then
        
            if pmonto >  sdoa_w - sdoc_w then
                let cod_ret = 303;
                return cod_ret, v_clave;
            end if
            
        end if
        
    end if

    select fecha_hoy 
      into fecha_w 
      from sc_fechas 
     where empresa = pempresa;

    let hora_w = current hour to fraction;

    -- // Asigna un folio
    let folio2  = hora_w[1,2] || hora_w[4,5] || hora_w[7,8] || hora_w[10,11];
    let v_folio = trim(pusuario)||folio2;

    -- // Asigna el Status con el que quedara la Cuenta, de acuerdo al cod. recibido
    if pcodbloq = "00" then
        let status2_w = "1";
        let mov = "D";
        let vmonto_cong = pmonto * -1;
        let v_transacc = "3354";
        
        if pmonto = sdoc_w then
            let status2_w = "1";
        else
            let status2_w = "3";
        end if
    else
        let status2_w = "3";
        let mov = "B";
        let vmonto_cong = pmonto;
        let v_transacc = "3353";
    end if

    let v_mesdia = month(fecha_w) || day(fecha_w);
    let hora_w = hora_w[4,5] || hora_w[7,8];
    
    if pcodbloq = "00" then
        let v_clave = pclave;
    else
        let v_clave = v_mesdia + hora_w;
    end if

    select max(secuencia) 
      into vmaxsec
      from sc_tarjeta
     where empresa = pempresa 
       and cuenta = pcuenta 
       and tipo_tarjeta = "T";

    select num_tarjeta 
      into vnum_tarjeta
      from sc_tarjeta
     where empresa = pempresa 
       and cuenta = pcuenta 
       and secuencia = vmaxsec;

    insert into sc_histbloq 
    (empresa, cuenta, tipo_mov, motivo, opcion, importe, usuario, fecha, hora, clave, 
     status_blo, folio_suc, referencia, cve_area, cod_area, cve_tipobloq, cod_tipobloq)
    values 
    (pempresa, pcuenta, mov, pcodbloq, popbloq, pmonto, pusuario, fecha_w, current hour to fraction, v_clave, 
     mov, v_folio, "", pAreaSolic, pCodArea, pTipoBloq, pCodTipoBloq);
    
    insert into sc_movdia values
    (0, v_folio, suc_w, pusuario, fecha_w, fecha_w, current hour to fraction, v_transacc, suc_w, prod_w, 
     pempresa, pcuenta, " ", 0, pmonto, 0, 0, 0, 0, " ", " ", sdod_w, "0000", " ", 0, vnum_tarjeta, " ", "");

	---- // INSERT NUEVOS // ----
	-- // Guarda un historial de los bloqueos 
	IF pcodbloq != "00" THEN
    
        INSERT INTO sc_ctabloqueo
        (cuenta, clave, opcion, cve_area, cod_area, cve_tipobloq, cod_tipobloq)  
        VALUES 
        (pcuenta, pcodbloq, popbloq, pAreaSolic, pCodArea, pTipoBloq, pCodTipoBloq);

        INSERT INTO sc_ctabloqueohist
        (cuenta, clave, opcion)
        VALUES 
        (pcuenta, pcodbloq, popbloq);
        
	 ELSE  
        
        DELETE FROM bdicheq:sc_ctabloqueo 
         WHERE cuenta = pcuenta;
         
	END IF
	---- // INSERT NUEVOS // ----
    
    update sc_maechq
       set fec_cancelac = fecha_w,
           status_cta = status2_w,
           motivo = pcodbloq,
           sdo_cong = sdo_cong + vmonto_cong,
           fecha_proceso = fecha_w
     where empresa = pempresa 
       and cuenta = pcuenta;
       
    if pcodbloq = "00" then
        if pclave <>  "" and pclave <> " " then
            update sc_histbloq
               set status_blo = mov
             where empresa = pempresa 
               and cuenta = pcuenta
               and clave = pclave 
               and tipo_mov = "B";
        else
            let vsdoxdesbloq = pmonto;
            
            foreach
                select rowid,importe,fecha
                  into vrowid, vimporte,vfecha
                  from sc_histbloq
                 where empresa = pempresa 
                   and cuenta = pcuenta 
                   and tipo_mov = "B" 
                   and status_blo = "B"
                 order by fecha
                 
                if vimporte > vsdoxdesbloq then
                    let vimporte = vimporte - vsdoxdesbloq;
                else
                    let vimporte = vimporte;
                end if
                
                update sc_histbloq
                   set status_blo = mov,
                       importe = vimporte
                 where rowid = vrowid;
                 
                let vsdoxdesbloq = vsdoxdesbloq - vimporte;
                
                if vsdoxdesbloq = 0 then
                    exit foreach;
                end if
            end foreach
        end if
    end if
    
    let cod_ret = "000";
    
    return cod_ret, v_clave;
    
end procedure

DOCUMENT
'DESCRIPCION: Realiza el Bloqueo de cuentas si no estan bloqueadas',
'AUTOR: Valentín López',
'FECHA: Septiembre 2010',
'VERSION: 20100929.0101';

create procedure "informix".conciliadebito_pba(pempresa char(3),
                                           pnum_tarjeta char(16),
                                           psucursal char(4),
                                           pusuario char(8),
                                           ptipomov char(1),
                                           ptransacc char(4),
                                           pfoliosuc char(16),
                                           pmonto_tot money(14,2),
                                           pdivisa char(2),
                                           preferencia char(40),
                                           pfolioori char(16),
                                           pvRfcComer char (20),
                                           pvRef23 char(23))
    
returning char(5),char(1);

    -- // Variables Globales Conciliacion intercar
    DEFINE GLOBAL vg_estatus    VARCHAR(5)  DEFAULT " ";
    DEFINE GLOBAL vgrfc_comer   VARCHAR(20) DEFAULT " ";
    DEFINE GLOBAL vgreferencia  VARCHAR(40) DEFAULT " ";

    define vcodret char(5);
    define vsqlerr integer;
    define vbandera char(1);
    define vcuenta char(20);
    define vtranret char(4);
    define vfecapli date;
    define vsdodisp money(14,2);
    define vmtoapli money(14,2);
    define vTranResp CHAR(4);
    define vTipoTran char(2);
    define vt_status_cta char(1);
    
    --- set debug file to "/informixuc7/perifericos/conciliadebito.out";
    --- trace on;

    begin
    
    on exception set vsqlerr
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
            return vcodret, vbandera;
        end if
    end exception;

    let vcodret = "000";
    let vbandera = "E";
    let vsqlerr = 0;
    let vcuenta = "";
    let vtranret = "";
    let vfecapli = "";
    let vsdodisp = 0;
    let vmtoapli = 0;
    let vTranResp = "";
    let vTipoTran = "";
    LET vt_status_cta = "";

    -- // Busca la cuenta en base al No. tarjet
    select tar.cuenta, mae.status_cta 
      into vcuenta, vt_status_cta
      from sc_tarjeta tar, 
           sc_maechq mae
     WHERE tar.empresa = pempresa 
       AND num_tarjeta = pnum_tarjeta
       AND tar.empresa = mae.empresa
       AND tar.cuenta = mae.cuenta;

    if vcuenta is null OR vcuenta = "" then
        let vcodret = "111";
        let vbandera = "E";
        return vcodret, vbandera;
    end if

    LET vTranResp = ptransacc;

    -- // busca el tipo_tran en si_transaccc (20)
    SELECT NVL(tranlibprot, "0000"), tipo_tran
      INTO ptransacc, vTipoTran
      FROM bdinteg:si_transacc
     WHERE empresa = pempresa
       AND numero = ptransacc
       AND sistema = "01";

    -- // Si es de Cargo
    if ptipomov = "C" then
        if vTipoTran  in ("00", "01", "02") and vg_estatus <> "3" then
            let vbandera = "C";
            return vcodret, vbandera;
        end if;

        IF ptransacc = "0000" OR ptransacc = " " THEN
            LET ptransacc = vTranResp;
        END IF

        -- // Realiza un desbloqueo parcial si es necesario, para realizar el cargo correspondiente
        IF vt_status_cta = "3" THEN 
            UPDATE sc_maechq 
               SET status_cta = "1"
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF

        -- // Realiza el cargo de la transaccion en cheques...
        LET preferencia = vgrfc_comer || preferencia;
		
        call cargo_ref_pos(pempresa, psucursal, pusuario, ptransacc, ptransacc, pfoliosuc, 
                       vcuenta, 0, pmonto_tot, pdivisa, preferencia, pnum_tarjeta,"", pvRef23)
        returning vcodret, vtranret, vfecapli, vsdodisp, vmtoapli;

        -- // Devuelve el bloqueo original
        IF vt_status_cta = "3" THEN 
            UPDATE sc_maechq 
               SET status_cta = "3"
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF

        if vcodret <> "000" and vcodret <> "400" then
            let vbandera = "E";
            return vcodret, vbandera;
        elif vcodret = "400" then
            let vbandera = "0";
            return vcodret, vbandera;
        else
            let vbandera = "C";
            return vcodret, vbandera;
        end if
    end if
    
    -- // Si es de Abono
    if ptipomov = "A" then
        --LET ptransacc = "0813";
		LET ptransacc = vTranResp;
        LET preferencia = vgrfc_comer || preferencia;
        
        call abono_ref_pos(pempresa, psucursal, pusuario, ptransacc, ptransacc, pfoliosuc, vcuenta, 0, 
                       pmonto_tot, pmonto_tot, 0, 0, 0, pdivisa, preferencia, pnum_tarjeta, "", pvRef23)
        returning vcodret;
        
        if vcodret <> "000" then
            let vbandera = "E";
            return vcodret, vbandera;
        else
            let vbandera = "C";
            return vcodret, vbandera;
        end if
    end if

    -- // si es de reversion
    if ptipomov = "R" then
        call reversiontd(pempresa, psucursal, pusuario, pfolioori, "A", vcuenta, ptransacc)
        returning vcodret;
        
        if vcodret <> "000" then
            let vbandera = "E";
            return vcodret, vbandera;
        else
            let vbandera = "C";
            return vcodret, vbandera;
        end if
    end if
    
    return vcodret, vbandera;
    
    end
    
end procedure;

CREATE PROCEDURE "informix".sp_apediacap(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador        INTEGER;
    DEFINE ven_transacc     SMALLINT; 
    DEFINE vfecha_ant       CHAR(10);
    DEFINE vcuenta          CHAR(20);
    DEFINE vsucursal        CHAR(4);  
    DEFINE vplaza           CHAR(3);
    DEFINE vproducto        CHAR(4);  
    DEFINE vnum_cte         CHAR(20);  
    DEFINE vnombre_cte      CHAR(120);
    DEFINE vsdo_dia_ant     MONEY(18,2);
    DEFINE vnombre_suc      CHAR(40);
    DEFINE vnombre_prod     CHAR(40);
    DEFINE vdivisa          CHAR(2);    
    DEFINE vejecutivo       CHAR(8);
    DEFINE vnombre_plaza    CHAR(40);
    DEFINE vregional        CHAR(3);
    DEFINE vfecha           CHAR(10);   
    DEFINE vdesc_divisa     CHAR(30);
    DEFINE vnombre_region   CHAR(40);
    DEFINE vsql             CHAR(400);
    DEFINE vstmt            CHAR(200);
    DEFINE vfechades        CHAR(8);
    DEFINE vdia             CHAR(2);
    DEFINE vmes             CHAR(2);
    DEFINE vanio            CHAR(4);
    DEFINE vfecultdep       DATE;
    DEFINE vtipo_alta       CHAR(8);
    
    LET vcodret1         = '000';
    LET vcodret2         = '000';
    LET vcodret3         = '';
    LET sql_err	         = 0;
    LET isam_err         = 0;
    LET desc_err         = '';
    LET vcontador        = 0;
    LET ven_transacc     = 0;
    LET vcuenta          = '';
    LET vsucursal        = '';
    LET vplaza           = '';
    LET vproducto        = '';
    LET vnum_cte         = '';
    LET vnombre_cte      = '';
    LET vsdo_dia_ant     = 0.00;
    LET vnombre_suc      = '';
    LET vnombre_prod     = '';
    LET vdivisa          = '';
    LET vejecutivo       = '';
    LET vnombre_plaza    = '';
    LET vregional        = '';
    LET vfecha           = ''; 
    LET vdesc_divisa     = '';
    LET vnombre_region   = '';
    LET vsql             = '';
    LET vstmt            = '';
    LET vfecha_ant       = '';
    LET vfechades        = '';
    LET vdia             = '';
    LET vmes             = '';
    LET vanio            = '';
    LET vfecultdep       = '';
    LET vtipo_alta       = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_apediacap.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_apediacap.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'aperdiariascapt') THEN
        DROP TABLE bdicheq:"informix".aperdiariascapt;
    END IF;
    
    CREATE TABLE bdicheq:"informix".aperdiariascapt
      (
        cuenta                  CHAR(20),
        sucursal                CHAR(4),   
        plaza                   CHAR(3),
        producto                CHAR(4),  
        num_cte                 CHAR(20),
        nombre_cte              CHAR(104),
        sdo_dia_ant             MONEY(18,2),
        nombre_suc              CHAR(40),
        nombre_prod             CHAR(40),
        divisa                  CHAR(2),
        ejecutivo               CHAR(8),
        nombre_plaza            CHAR(40),
        regional                CHAR(3),
        fecha                   CHAR(10),
        desc_divisa             CHAR(30),
        nombre_region           CHAR(40),
        tipo_alta               CHAR(8)
      )
    EXTENT SIZE 3200 NEXT SIZE 320 LOCK MODE ROW;
    
    SELECT fecha_ant
      INTO vfecha_ant
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    FOREACH WITH HOLD
        SELECT TRIM(noc.cuenta), TRIM(noc.ejecutivo), TRIM(chq.sucursal), TRIM(chq.plaza), TRIM(chq.producto), 
               TRIM(chq.num_cte), chq.sdo_dia_ant, TRIM(prod.nombre), TRIM(prod.divisa), chq.fecultdep
          INTO vcuenta, vejecutivo, vsucursal, vplaza, vproducto, vnum_cte, vsdo_dia_ant, vnombre_prod, vdivisa, vfecultdep
          FROM sc_maenoc noc,
               sc_maechq chq,
               sc_producto prod
         WHERE noc.empresa = pempresa
           AND noc.cuenta = chq.cuenta
           AND noc.fecha_alta = vfecha_ant
           AND chq.empresa = noc.empresa
           AND chq.cuenta = noc.cuenta
           AND prod.empresa = chq.empresa
           AND prod.producto = chq.producto
		   AND chq.status_cta <> '2'
           
        BEGIN WORK;
        LET ven_transacc = 1;
        
        SELECT TRIM(nombre1)||" "||TRIM(nombre2)||" "||TRIM(apell_paterno)||" "||TRIM(apell_materno)
          INTO vnombre_cte
          FROM bdinteg:si_cliente
         WHERE numcte = vnum_cte;
         
        SELECT TRIM(nombre)
          INTO vnombre_suc
          FROM bdinteg:si_sucursales
         WHERE sucursal = vsucursal
           AND empresa = pempresa;
           
        SELECT TRIM(nombre), TRIM(regional)
          INTO vnombre_plaza, vregional
          FROM bdinteg:si_plazas
         WHERE plaza = vplaza
           AND empresa = pempresa;
           
        SELECT TRIM(nombre)
          INTO vnombre_region
          FROM bdinteg:si_regional
         WHERE regional = vregional
           AND empresa = pempresa;
        
        SELECT TRIM(descripcion)
          INTO vdesc_divisa
          FROM bdinteg:si_divisas
         WHERE empresa = pempresa
           AND divisa = vdivisa;
           
        IF vproducto = '1100' THEN
            IF vfecultdep < vfecha_ant THEN
                LET vtipo_alta = 'RENOVADA';
            ELSE
                LET vtipo_alta = 'ALTA';
            END IF;
        ELSE
            LET vtipo_alta = 'ALTA';
        END IF;
        
        INSERT INTO aperdiariascapt VALUES 
        ( vcuenta, vsucursal, vplaza, vproducto, vnum_cte, vnombre_cte, vsdo_dia_ant, vnombre_suc, vnombre_prod, 
          vdivisa, vejecutivo, vnombre_plaza, vregional, vfecha_ant, vdesc_divisa, vnombre_region, vtipo_alta );
        
        LET vcontador = vcontador + 1;
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    CREATE INDEX "informix".idx_apediacap ON bdicheq:"informix".aperdiariascapt(cuenta) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE aperdiariascapt;
    
    LET vfecha_ant = vfecha_ant;
    LET vdia  = SUBSTR(vfecha_ant, 4, 2);
    LET vmes  = SUBSTR(vfecha_ant, 1, 2);
    LET vanio = SUBSTR(vfecha_ant, 7, 4);
    LET vdia  = TRIM(vdia);
    LET vmes  = TRIM(vmes);
    LET vanio = TRIM(vanio);
    LET vfechades = vmes||vdia||vanio;
    
    
    LET vsql = 'echo "set isolation to dirty read; unload to /resplogifx/conciliachq/apediacap_'||vfechades||'.txt '||
               ' select * from aperdiariascapt order by divisa, sucursal, producto, cuenta;" > /resplogifx/conciliachq/apediacap.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/apediacap.sql"; 
    SYSTEM vstmt;
    LET vstmt = '';
    
    EXECUTE PROCEDURE "informix".sp_candiacap(pempresa)
    INTO vcodret2;
    
    END;
    
    RETURN vcodret1, vcodret2, vcontador;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_candiacap(pempresa CHAR(3))
RETURNING CHAR(5);

    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vcontador    INTEGER;
    DEFINE ven_transacc SMALLINT;
    DEFINE vfecha_ant   CHAR(10);
    DEFINE vsucursal    CHAR(4);  
    DEFINE vcuenta      CHAR(20);
    DEFINE vstatus_cta  CHAR(1);
    DEFINE vnum_cte     CHAR(20);  
    DEFINE vproducto    CHAR(4);  
    DEFINE vfecha_canc  DATE;
    DEFINE vsdo_dia_ant MONEY(18,2);
    DEFINE vsql         CHAR(400);
    DEFINE vstmt        CHAR(200);
    DEFINE vdia         CHAR(2);
    DEFINE vmes         CHAR(2);
    DEFINE vanio        CHAR(4);
    DEFINE vfechades    CHAR(8);
    
    LET vcodret1     = '000';
    LET vcodret2     = '';
    LET vcodret3     = '';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador    = -1;
    LET ven_transacc = 0;
    LET vfecha_ant   = '';
    LET vsucursal    = '';
    LET vcuenta      = '';
    LET vstatus_cta  = '';
    LET vnum_cte     = '';
    LET vproducto    = '';
    LET vfecha_canc  = '';
    LET vsdo_dia_ant = 0.00;
    LET vsql         = '';
    LET vstmt        = '';
    LET vdia         = '';
    LET vmes         = '';
    LET vanio        = '';
    LET vfechades    = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_candiacap.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_candiacap.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'canceldiariascapt') THEN
        DROP TABLE bdicheq:"informix".canceldiariascapt;
    END IF;
    
    CREATE TABLE bdicheq:"informix".canceldiariascapt
      (
        sucursal                CHAR(4), 
        cuenta                  CHAR(20),
        status_cta              CHAR(1),
        num_cte                 CHAR(20),
        producto                CHAR(4),  
        fecha_canc              DATE,
        sdo_dia_ant             MONEY(18,2),                   
        fecha                   CHAR(10)
      )
    EXTENT SIZE 320 NEXT SIZE 320 LOCK MODE ROW;
    
    SELECT fecha_ant
      INTO vfecha_ant
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    FOREACH WITH HOLD
        SELECT mae.sucursal, mae.cuenta, mae.status_cta, mae.num_cte, mae.producto, mae.fec_cancelac, mae.sdo_dia_ant 
          INTO vsucursal, vcuenta, vstatus_cta, vnum_cte, vproducto, vfecha_canc, vsdo_dia_ant 
          FROM sc_maechq mae,
               sc_maenoc noc      
         WHERE mae.empresa = noc.empresa
           AND mae.cuenta = noc.cuenta
           AND mae.producto <> '1100'
           AND mae.status_cta = '2'
           AND mae.fec_cancelac = vfecha_ant
           AND noc.fecha_alta < vfecha_ant
           
        BEGIN WORK;
        LET ven_transacc = 1;
        
        INSERT INTO canceldiariascapt(sucursal, cuenta, status_cta, num_cte, producto, fecha_canc, sdo_dia_ant, fecha)
        VALUES(vsucursal, vcuenta, vstatus_cta, vnum_cte, vproducto, vfecha_canc, vsdo_dia_ant, vfecha_ant);
        
        LET vcontador = vcontador + 1;
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    FOREACH WITH HOLD
        SELECT mae.sucursal, mae.cuenta, mae.status_cta, mae.num_cte, mae.producto, mae.fec_cancelac, mae.sdo_dia_ant
          INTO vsucursal, vcuenta, vstatus_cta, vnum_cte, vproducto, vfecha_canc, vsdo_dia_ant 
          FROM sc_maechq mae,
               sc_maenoc noc      
         WHERE mae.empresa = noc.empresa
           AND mae.cuenta = noc.cuenta
           AND mae.producto = '1100'
           AND mae.status_cta = '2'
           AND mae.fec_cancelac = vfecha_ant 
           AND noc.fecha_alta <> mae.fecultret
           
        BEGIN WORK;
        LET ven_transacc = 1;
        
        INSERT INTO canceldiariascapt(sucursal, cuenta, status_cta, num_cte, producto, fecha_canc, sdo_dia_ant, fecha)
        VALUES(vsucursal, vcuenta, vstatus_cta, vnum_cte, vproducto, vfecha_canc, vsdo_dia_ant, vfecha_ant);
        
        LET vcontador = vcontador + 1;
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    FOREACH WITH HOLD
        SELECT mae.sucursal, mae.cuenta, mae.status_cta, mae.num_cte, mae.producto, mae.fec_cancelac, mae.sdo_dia_ant
          INTO vsucursal, vcuenta, vstatus_cta, vnum_cte, vproducto, vfecha_canc, vsdo_dia_ant 
          FROM sc_maechq mae,
               sc_maenoc noc      
         WHERE mae.empresa = noc.empresa
           AND mae.cuenta = noc.cuenta
           AND mae.producto = '1100'
           AND mae.status_cta = '2'
           AND mae.fec_cancelac = vfecha_ant 
           AND noc.fecha_alta = mae.fecultret
           AND mae.fecultdep < noc.fecha_alta
           
        BEGIN WORK;
        LET ven_transacc = 1;
        
        INSERT INTO canceldiariascapt(sucursal, cuenta, status_cta, num_cte, producto, fecha_canc, sdo_dia_ant, fecha)
        VALUES(vsucursal, vcuenta, vstatus_cta, vnum_cte, vproducto, vfecha_canc, vsdo_dia_ant, vfecha_ant);
        
        LET vcontador = vcontador + 1;
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    CREATE INDEX "informix".idx_candiacap ON bdicheq:"informix".canceldiariascapt(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE canceldiariascapt;
    
    LET vfecha_ant = vfecha_ant;
    LET vdia  = SUBSTR(vfecha_ant, 4, 2);
    LET vmes  = SUBSTR(vfecha_ant, 1, 2);
    LET vanio = SUBSTR(vfecha_ant, 7, 4);
    LET vdia  = TRIM(vdia);
    LET vmes  = TRIM(vmes);
    LET vanio = TRIM(vanio);
    LET vfechades = vmes||vdia||vanio;
    
    LET vsql = 'echo "unload to /resplogifx/conciliachq/candiacap_'||vfechades||'.txt '||
               'select * from canceldiariascapt;" > /resplogifx/conciliachq/candiacap.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/candiacap.sql"; 
    SYSTEM vstmt;
    LET vstmt = '';
    
    END;
    
    RETURN vcodret1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizakelloggs(pEmpresa CHAR(3), pNumFolio CHAR(7), pEntregado CHAR(1), pNumCuenta CHAR(11),
												pSucursal CHAR(4), pUsuario CHAR(8), pMontoPremio DECIMAL(16,8))

RETURNING CHAR(5) AS CodRet,CHAR(5) As CodRet2;

--Definicion de Variables
DEFINE cEntregado	CHAR(1);
DEFINE cCodRet		CHAR(5);
DEFINE cCodRet2		CHAR(5);
DEFINE iSqlErr 		INTEGER;

--Inicializacion de Variables
LET cCodRet    = '00000';
LET cCodRet2   = '00000';
LET cEntregado = '';

--SET DEBUG FILE TO '/tmp/sp_actualizakelloggs.out';
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
		RETURN cCodRet, cCodRet2;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO dirty READ;

	IF (pEmpresa IS NULL OR pEmpresa = '') OR (pNumFolio IS NULL OR pNumFolio = '')
		OR (pSucursal IS NULL OR pSucursal = '') OR (pUsuario IS NULL OR pUsuario = '') OR
		(pEntregado IS NULL OR pEntregado = '')  OR (pMontoPremio IS NULL OR pMontoPremio = '') THEN
		LET cCodRet2 = '00001';
	ELSE
		SELECT entregado INTO cEntregado
		FROM "informix".sc_promocion_kelloggs 
		WHERE folio = pNumFolio AND empresa = pEmpresa;

		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet2 = '00002';
		ELSE
			IF cEntregado = '1' THEN
				LET cCodRet2 = '00003';
			ELSE
				UPDATE "informix".sc_promocion_kelloggs
				SET entregado = pEntregado, cuenta_abono = pNumCuenta, folio = pNumFolio,
				sucursal = pSucursal, usuario_entrega = pUsuario, monto_premio = pMontoPremio, fecha_entrega = CURRENT	
				WHERE folio = pNumFolio AND empresa = pEmpresa;
			END IF;
		END IF;
	END IF;

	RETURN cCodRet, cCodRet2;
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Se crea SP que actualice el folio ingresado cuando sea ganador en la tabla sc_promocion_kelloggs ',
'AUTOR : Oscar Valenzuela',
'FECHA : 9/07/2013',
'VERSION: 20130808.1209',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_bitacorakelloggs(pEmpresa CHAR(3), pNumFolio CHAR(7), pSucursal CHAR(4), pUsuario CHAR(8))
RETURNING CHAR(5) AS CodRet,CHAR(5) As CodRet2;

