    LET cVar        = "";
    LET vabierto    = "0";
    LET vcomienza   = -1;
    LET vexiste_ctabloq = '';
    LET vexiste_invcrec = 0;
    LET vexiste_pagare = 0;
    LET vdFechaHoy  = '';
    LET mSdoSBC = 0;
    LET mSdoRet = 0;
    LET mSdoCong = 0;
    LET mSdoSBG = 0;
    LET mComPend = 0;
    
    --- SET DEBUG FILE TO '/tmp/sp_valmayoedadctaefecnos.out';
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET iSQL_ERR
