        RETURN cCodret;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vdFechaHoy
      FROM sc_fechas
     WHERE empresa = '001';
    
    FOREACH WITH HOLD
        SELECT mae.empresa, mae.cuenta, sicte.numcte, 
               TRIM(sicte.apell_paterno)||' '||TRIM(sicte.apell_materno)||' '||TRIM(sicte.nombre1)||' '||TRIM(sicte.nombre2) AS cliente,
               ctepf.fecha_nac, 
               SUBSTR( ( YEAR(fecha.fecha_hoy) + MONTH(fecha.fecha_hoy)/12 + DAY(fecha.fecha_hoy)/30/12 ) - 
                       ( YEAR(ctepf.fecha_nac) + MONTH(ctepf.fecha_nac)/12 + DAY(ctepf.fecha_nac)/30/12 ), 0, 4 ) AS edad,
               tel1.telefono, tel2.telefono, core.correo_elec, mae.sdo_actual, fecha.fecha_hoy,
               mae.imp_chq_sbc, mae.sdo_retenido, mae.sdo_cong, mae.imp_chq_sbg, mae.com_pendiente
          INTO cEmpresa, cCuenta, cNumcte, cCliente, dFecha_nac, cEdad, cTelefono1, cTelefono2, cEmail, mSdo_actual, cFecha,
               mSdoSBC, mSdoRet, mSdoCong, mSdoSBG, mComPend
          FROM bdicheq:sc_maechq mae
         INNER JOIN bdinteg:si_cliente sicte ON sicte.numcte = mae.num_cte
         INNER JOIN bdinteg:si_ctepf ctepf ON ctepf.numcte = mae.num_cte
         INNER JOIN bdicheq:sc_fechas fecha ON (fecha.fecha_hoy > ctepf.fecha_nac AND fecha.empresa = mae.empresa)
	      left outer join bdinteg:si_telefonos_actual tel1 on (tel1.numcte = mae.num_cte and tel1.tipo_tel = 1)
	      left outer join bdinteg:si_telefonos_actual tel2 on (tel2.numcte = mae.num_cte and tel2.tipo_tel = 2)
	      left outer join bdinteg:si_correos core on (core.numcte = mae.num_cte and core.tipo_correo = 1 and core.status_correo ='A')
         WHERE mae.producto = '1500'
           AND mae.status_cta IN('1','4')
           AND ( ( YEAR(fecha.fecha_hoy) + MONTH(fecha.fecha_hoy)/12 + DAY(fecha.fecha_hoy)/30/12 ) - 
                 ( YEAR(ctepf.fecha_nac) + MONTH(ctepf.fecha_nac)/12 + DAY(ctepf.fecha_nac)/30/12 ) >= 18.5 )
         
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET vabierto = "1";
        END IF;
        
        SELECT COUNT(*)
          INTO vexiste_invcrec
          FROM bdicheq:sc_maeinstrucc ins,
               bdicheq:sc_maechq mae
         WHERE ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.cuentadep = cCuenta
           AND mae.status_cta <> '2';
           
        SELECT COUNT(*)
          INTO vexiste_pagare
          FROM bdinvers:sv_maeinv
         WHERE status_cta = '1'
           AND cta_cheques = cCuenta;
           
        IF vexiste_invcrec = 0 AND vexiste_pagare = 0 THEN
            IF ( mSdo_actual = 0 AND mSdoSBC = 0 AND mSdoSBG = 0 AND mComPend = 0 ) THEN
                UPDATE bdicheq:sc_maechq 
                   SET status_cta = '2', 
                       motivo = "00",
                       fec_cancelac = vdFechaHoy
                 WHERE empresa = '001'
                   AND cuenta = cCuenta;
            
                INSERT INTO bdicheq:sc_movctaefecnos 
                (cuenta, status, fecha_ins) 
                VALUES 
                (cCuenta, '2', cFecha);
            ELSE
                CALL bloqueo_cta(cEmpresa, cCuenta, 0, '02', '2', cFecha, 'informix', '', '', '','','') 
                RETURNING cCodret, cVar;
                
                SELECT UNIQUE cuenta
                  INTO vexiste_ctabloq
                  FROM bdicheq:sc_ctabloqueo
                 WHERE cuenta = cCuenta;
                 
                IF vexiste_ctabloq is null OR vexiste_ctabloq = '' THEN            
                    INSERT INTO bdicheq:sc_ctabloqueo 
                    (cuenta, clave, opcion, cve_area,cod_area, cve_tipobloq, cod_tipobloq ) 
                    VALUES 
                    (cCuenta, '02', '2', '', '', '', '' );
                    
                    INSERT INTO bdicheq:sc_ctabloqueohist 
                    (cuenta, clave, opcion) 
                    VALUES 
                    (cCuenta, '02', '2');
                END IF
                
                INSERT INTO bdicheq:sc_movctaefecnos 
                (cuenta, status, fecha_ins) 
                VALUES 
                (cCuenta, '3', cFecha);
            END IF
        END IF;
    
        LET iBandera = cCodret;
            
        IF vabierto = 1 THEN
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF vabierto = 1 THEN
        COMMIT WORK;
    END IF;
        
    IF iBandera <> 000 THEN
        LET cCodret = '000';
        LET cCliente = 'No se encontraron registros';
        RETURN cCodret;
    ELSE
        RETURN cCodret;
    END IF
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_modifinvcrec(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER, INTEGER;

    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vcontador1   INTEGER;
    DEFINE vcontador2   INTEGER;
    DEFINE vcontador3   INTEGER;
    DEFINE ven_transacc SMALLINT;
    DEFINE vsql         CHAR(500);
    DEFINE vstmt        CHAR(250);
    DEFINE vcuenta      CHAR(20);
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO FINALIZADO';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET ven_transacc = 0;
    LET vsql         = '';
    LET vstmt        = '';
    LET vcuenta      = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_modifinvcrec.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_modifinvcrec.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxmodif') THEN
        DROP TABLE "informix".ctasxmodif;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxmodif
      (
        cuenta char(20) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctaxmodif ON "informix".ctasxmodif(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/invcrecxmodif.unl INSERT INTO ctasxmodif" > /resplogifx/conciliachq/invcrec.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/invcrec.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS HIGH FOR TABLE ctasxmodif;
    
    FOREACH WITH HOLD
        SELECT a.cuenta
          INTO vcuenta
          FROM ctasxmodif a,
               "informix".sc_maechq b
         WHERE a.cuenta = b.cuenta
           AND b.status_cta <> '2'
        
        BEGIN WORK;
        LET ven_transacc = 1;
        
        UPDATE "informix".sc_tasa_variable
           SET fin_periodo = '09/06/2013'
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND tipo_tasa IN('M','P')
           AND fin_periodo = '09/05/2013';
           
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            UPDATE "informix".sc_maenoc
               SET fecha_alta = '09/06/2012',
                   fecha_mod = '09/06/2013'
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                UPDATE "informix".sc_maechq
                   SET fecha_proceso = '09/05/2013'
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta;
                        
                COMMIT WORK;
                LET ven_transacc = 0;
                LET vcontador2 = vcontador2 + 1;
            ELSE
                ROLLBACK WORK;
                LET ven_transacc = 0;
                LET vcontador3 = vcontador3 + 1;
            END IF;
        ELSE
            ROLLBACK WORK;
            LET ven_transacc = 0;
            LET vcontador3 = vcontador3 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcuenta = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;
    
    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
    
END PROCEDURE;

CREATE PROCEDURE "informix".cierrechqinvcreccomp1(pempresa CHAR(3))
RETURNING CHAR(5);
     
    DEFINE GLOBAL vgusuario             CHAR(8)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_hoy           DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgprox_fecha          DATE        DEFAULT " ";
    DEFINE GLOBAL vgtrans_pag_int       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtransisr            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranprov            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrevprov         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranabotrasp        CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrecrece         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgProdCreciente       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgstatus_cta          CHAR(1)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_mod           DATE        DEFAULT " ";
    DEFINE GLOBAL vgfecha_alta          DATE        DEFAULT " ";
    DEFINE GLOBAL vginstrucc            CHAR(2)     DEFAULT " ";
    DEFINE GLOBAL vgcuentadep           CHAR(20)    DEFAULT " ";

    DEFINE vcodret                      CHAR(5);
    DEFINE vcodret2                     CHAR(5);
    DEFINE vcodret3                     CHAR(40);
    DEFINE vsqlerr                      INTEGER;
    DEFINE isam_err                     INTEGER;
    DEFINE error_info                   CHAR(40);
    DEFINE vfechahora                   CHAR(40);
    DEFINE vsql                         CHAR(600);
    DEFINE vstmt                        CHAR(250);
    DEFINE vsistema                     CHAR(2);
    DEFINE vproceso                     CHAR(20);
    DEFINE vstatuscierreinv             CHAR(1);
    DEFINE vstatuscobroreestruc         CHAR(1);
    DEFINE vProdChequeras               CHAR(4);
    DEFINE vexiste                      CHAR(1);
    DEFINE vexiste2                     INTEGER;
    DEFINE vexistefin                   INTEGER;
    DEFINE vdias                        INTEGER;
    DEFINE vregproc                     INTEGER;
    DEFINE vporcentajerror              INTEGER;
    DEFINE vfcuenta                     CHAR(20);
    DEFINE FechaProc                    DATE;
    DEFINE vProducto                    CHAR(4);
    DEFINE vSdoActual                   DECIMAL(14,2);
    DEFINE vSucursal                    CHAR(4);
    DEFINE vcontvalcie                  INTEGER;
    DEFINE vregistros                   INTEGER;
    DEFINE vcuenta                      CHAR(20);
    DEFINE vProdChequerasPM             CHAR(4);
    DEFINE vdia                         CHAR(2);
    DEFINE vfecha_pago                  DATE;
    DEFINE vnumdias                     SMALLINT;
    DEFINE vexiste_cta                  SMALLINT;
    DEFINE vhora            		    DATETIME HOUR TO FRACTION;
    DEFINE vfolio_suc       		    CHAR(16);
    DEFINE vint_acum                    MONEY(14,2);
    DEFINE vfecultdep                   DATE;
    DEFINE vdiasinact                   INTEGER;
    DEFINE vabierto                     CHAR(1);
    DEFINE vaniomes                     CHAR(6);
    DEFINE vexiste_proy                 SMALLINT;
    DEFINE vtotsuc                      INTEGER;
    DEFINE vcontproc                    INTEGER;
    DEFINE vtfechaxxx                   DATE;
    DEFINE vnum_cte                     CHAR(20);
    DEFINE vfecha_alta                  DATE;
    DEFINE vhoraw           		    CHAR(15);
    DEFINE vfecha_mod                   DATE;
    DEFINE vcuentaini                   CHAR(20);
    DEFINE vcuentafin                   CHAR(20);
    DEFINE vinicio_cierre               SMALLINT;
    DEFINE vProdPROAC                   CHAR(4);

    LET vgusuario       = USER;
    LET vgfecha_hoy     = ' ';
    LET vgpri_dia_mes   = ' ';
    LET vgpri_hab_mes   = ' ';
    LET vgult_dia_mes   = ' ';
    LET vgult_hab_mes   = ' ';
    LET vgprox_fecha    = ' ';
    LET vgtrans_pag_int = ' ';
    LET vgtransisr      = ' ';
    LET vgtranprov      = ' ';
    LET vgtranrevprov   = ' ';
    LET vgtranabotrasp  = ' ';
    LET vgtranrecrece   = ' ';
    LET vgProdCreciente = ' ';
    LET vgstatus_cta    = ' ';
    LET vgfecha_mod     = ' ';
    LET vgfecha_alta    = ' ';

    LET vcodret              = "000";
    LET vcodret2             = "000";
    LET vcodret3             = "000";
    LET vsqlerr              = 0;
    LET isam_err             = 0;
    LET error_info           = '';
    LET vfechahora           = " ";
    LET vsql                 = '';
    LET vstmt                = '';
    LET vsistema             = "01";
    LET vproceso             = "cierrechqinvcrecomp1";
    LET vstatuscierreinv     = '';
    LET vstatuscobroreestruc = '';
    LET vProdChequeras       = '';
    LET vexiste              = '';
    LET vexiste2             = 0;
    LET vexistefin           = 0;
    LEt vdias                = 0;
    LET vregproc             = 0;
    LET vporcentajerror      = 0;
    LET vfcuenta             = '';
    LET FechaProc            = '';
    LET vProducto            = '';
    LET vSdoActual           = 0.00;
    LET vSucursal            = '';
    LET vcontvalcie          = 0;
    LET vregistros           = 0;
    LET vcuenta              = '';
    LET vProdChequerasPM     = '';
    LET vdia                 = '';
    LET vfecha_pago          = '';
    LET vnumdias             = 0;
    LET vexiste_cta          = 0;
    LET vhora                = '';
    LET vfolio_suc           = '';
    LET vint_acum            = 0.00;
    LET vfecultdep           = '';
    LET vdiasinact           = 0;
    LET vabierto             = '0';
    LET vaniomes             = '';
    LET vexiste_proy         = 0;
    LET vtotsuc              = 0;
    LET vcontproc            = 0;
    LET vtfechaxxx           = '';
    LET vnum_cte             = '';
    LET vfecha_alta          = '';
    LET vhoraw               = '';
    LET vfecha_mod           = '';
    LET vcuentaini           = '';
    LET vcuentafin           = '';
    LET vinicio_cierre       = 0;
    LET vProdPROAC           = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp1.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            LET vfechahora = CURRENT;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec1.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec1.sql';
            SYSTEM vstmt;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp1.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    --- SET PDQPRIORITY 10;
    
    -- // ##################################### //
    -- // #  FECHAS DEL SISTEMA DE CAPTACION  # //
    -- // ##################################### //
    SELECT fecha_hoy, pri_dia_mes, pri_hab_mes, ult_dia_mes, ult_hab_mes, prox_fecha
      INTO vgfecha_hoy, vgpri_dia_mes, vgpri_hab_mes, vgult_dia_mes, vgult_hab_mes, vgprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- // ###################################### //
    -- // #  TRANSACCION DE PAGO DE INTERESES  # //
    -- // ###################################### //
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";

    -- // ################################# //
    -- // #  TRANSACCION DE COBRO DE ISR  # //
    -- // ################################# //
    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";

    -- // ########################################### //
    -- // #  TRANSACCION DE PROVISION DE INTERESES  # //
    -- // ########################################### //
    SELECT valor
      INTO vgtranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";

    -- // ############################################## //
    -- // #  TRANSACCION DE DESPROVISION DE INTERESES  * //
    -- // ############################################## //
    SELECT valor
      INTO vgtranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";

    -- // ######################################## //
    -- // #  TRANSACCION DE ABONO PARA TRASPASO  # //
    -- // ######################################## //
    SELECT valor
      INTO vgtranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";

    -- // ############################################# //
    -- // #  TRANSACCION DE REINVERSION DE INVS CREC  # //
    -- // ############################################# //
    SELECT valor
      INTO vgtranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";

    -- // ################################## //
    -- // #  Producto Inversion Creciente  # //
    -- // ################################## //
    SELECT valor
      INTO vgProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";

    -- // ########################### //
    -- // #  Producto de Chequeras  # //
    -- // ########################### //
    SELECT valor
      INTO vProdChequeras
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
       
    -- // ####################################### //
    -- // #  Producto de Chequeras Empresarial  # //
    -- // ####################################### //
    SELECT valor
      INTO vProdChequerasPM
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqpm";   
       
    -- // ######################################## //
    -- // #  Producto Programa Ahorre su Cambio  # //
    -- // ######################################## //
    SELECT valor
      INTO vProdPROAC
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PROACPRODUCTO";   
    
    -- // ############################################################## //
    -- // #  VALIDA QUE NO SE HAYA REALIZADO EL CIERRE DEL DIA ACTUAL  # //
    -- // ############################################################## //
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgfecha_hoy
       AND sistema = vsistema;

    IF vexiste2 = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vgfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horacierrecrec1.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec1.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec1.sql';
            SYSTEM vsql; 
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec1.sql';
            SYSTEM vstmt;
        ELSE
            SELECT 1
              INTO vexiste
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = 'cierreinvcreccomp1'
               AND fecha = vgfecha_hoy;

            IF vexiste = "1" THEN
                LET vcodret = "966";
                RETURN vcodret;
            END IF            
        END IF
    END IF;
    
    -- // #################################################################### //
    -- // # VALIDA QUE EL CIERRE PRINCIPAL HAYA COMENZADO A PROCESAR CUENTAS # //
    -- // #################################################################### //
    WHILE vinicio_cierre = 0 
        SET ISOLATION TO DIRTY READ;
        
        SELECT COUNT(*)
          INTO vinicio_cierre
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'inicio_cierreinvcrec'
           AND fecha = vgfecha_hoy;
    END WHILE;

    -- // ####################################### //
    -- // #  OBTIENE NUMERO DE DIAS A PROCESAR  # //
    -- // ####################################### //
    IF vgfecha_hoy = vgult_hab_mes THEN
        LET vdias = vgult_dia_mes - vgfecha_hoy + 1;

        IF vgprox_fecha > vgult_dia_mes THEN
            LET vdias = vdias + ((vgprox_fecha-1) - vgult_dia_mes);
        END IF
    ELSE
        LET vdias = vgprox_fecha - vgfecha_hoy;
    END IF

    -- // ############################################ //
    -- // #  OBTIENE NUMERO DE REGISTROS A PROCESAR  # //
    -- // ############################################ //
    SELECT COUNT(*)
      INTO vregproc
      FROM sc_maechq
     WHERE producto = vgProdCreciente
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy);

    -- // ########################################################### //
    -- // #  Obtiene parametro de porcentajes de error por proceso  # //
    -- // ########################################################### //
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
       
    -- // OBTIENE RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentaini
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp1'; 
       
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp2'; 
       
       
    -- // ######################################################################### //
    -- // #  FOREACH PRINCIPAL DEL CIERRE DE CAPTACION DE INVERSIONES CRECIENTES  # //
    -- // ######################################################################### //
    FOREACH principal WITH HOLD FOR
        SELECT mae.cuenta, mae.fecha_proceso, mae.producto, mae.sdo_actual, mae.status_cta, mae.sucursal,
               ins.instrucc, ins.cuentadep, nvl(noc.fecha_mod, vgfecha_hoy), nvl(noc.fecha_alta, vgfecha_hoy)
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal,
               vginstrucc, vgcuentadep, vgfecha_mod, vgfecha_alta
          FROM sc_maechq mae,
               sc_maeinstrucc ins,
               sc_maenoc noc
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta <> '2'
           AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vgfecha_hoy )
           AND mae.cuenta >= vcuentaini
           AND mae.cuenta < vcuentafin
           AND ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.capint = 'R'
           AND ins.instrucc = '01'
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        IF FechaProc IS NULL THEN
            IF vSdoActual = 0 THEN
                UPDATE sc_maechq
                   SET status_cta = "2",
                       fecha_proceso = vgfecha_hoy
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                LET vcodret = "000";

                CONTINUE FOREACH;
            ELSE
                CALL creciente_proy_cierre(pempresa, vfcuenta, vProducto, vSdoActual, vginstrucc)
                RETURNING vcodret;

                IF vcodret <> "000" THEN
                    CONTINUE FOREACH;
                END IF
            END IF
        END IF

        -- // Actualiza la fecha como ya procesado si vencio su plazo
        IF vgfecha_mod < vgfecha_hoy THEN
            UPDATE sc_maechq
               SET fecha_proceso = vgprox_fecha
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            CONTINUE FOREACH;
        END IF
        
        CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT COUNT(*)
              INTO vcontvalcie
              FROM sc_valcierre
             WHERE empresa = pempresa
               AND cuenta <> '';

            LET vregistros = ROUND(vregproc * vporcentajerror / 100);

            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                           'SET ejecutivo = '''||vgusuario||''','||
                           'status_proc   = '''||'C'||''','||
                           'codret        = '''||vcodret||''','||
                           'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                           'WHERE empresa = '''||pempresa||''' '||
                           'AND proceso   = '''||vproceso||''' '||
                           'AND fecha     = '''||vgfecha_hoy||''' '||
                           'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec1.sql';
                SYSTEM vsql;
                LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec1.sql';
                SYSTEM vstmt;
                RETURN vcodret;
            END IF;
        END IF;

        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
    END FOREACH;    
    
    
    -- // ############################ //
    -- // #  Registra fin de cierre  # //
    -- // ############################ //
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vgfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec1.sql';
    SYSTEM vsql;

    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec1.sql';
    SYSTEM vstmt;

    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreinvcreccomp1";

    SET LOCK MODE TO NOT WAIT;

    RETURN vcodret;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION:   Complemento 1 Cierre Diario del Producto de Inversion Creciente de Captacion ',
'EJECUTADO POR: Control-M',
'AUTOR:         JICS',
'FECHA:         20/Febrero/2013',
'VERSION:       1.00.0000',
'Base de Datos: bdicheq';

CREATE PROCEDURE "informix".cierrechqinvcreccomp2(pempresa CHAR(3))
RETURNING CHAR(5);
     
    DEFINE GLOBAL vgusuario             CHAR(8)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_hoy           DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgprox_fecha          DATE        DEFAULT " ";
    DEFINE GLOBAL vgtrans_pag_int       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtransisr            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranprov            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrevprov         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranabotrasp        CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrecrece         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgProdCreciente       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgstatus_cta          CHAR(1)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_mod           DATE        DEFAULT " ";
    DEFINE GLOBAL vgfecha_alta          DATE        DEFAULT " ";
    DEFINE GLOBAL vginstrucc            CHAR(2)     DEFAULT " ";
    DEFINE GLOBAL vgcuentadep           CHAR(20)    DEFAULT " ";

    DEFINE vcodret                      CHAR(5);
    DEFINE vcodret2                     CHAR(5);
    DEFINE vcodret3                     CHAR(40);
    DEFINE vsqlerr                      INTEGER;
    DEFINE isam_err                     INTEGER;
    DEFINE error_info                   CHAR(40);
    DEFINE vfechahora                   CHAR(40);
    DEFINE vsql                         CHAR(600);
    DEFINE vstmt                        CHAR(250);
    DEFINE vsistema                     CHAR(2);
    DEFINE vproceso                     CHAR(20);
    DEFINE vstatuscierreinv             CHAR(1);
    DEFINE vstatuscobroreestruc         CHAR(1);
    DEFINE vProdChequeras               CHAR(4);
    DEFINE vexiste                      CHAR(1);
    DEFINE vexiste2                     INTEGER;
    DEFINE vexistefin                   INTEGER;
    DEFINE vdias                        INTEGER;
    DEFINE vregproc                     INTEGER;
    DEFINE vporcentajerror              INTEGER;
    DEFINE vfcuenta                     CHAR(20);
    DEFINE FechaProc                    DATE;
    DEFINE vProducto                    CHAR(4);
    DEFINE vSdoActual                   DECIMAL(14,2);
    DEFINE vSucursal                    CHAR(4);
    DEFINE vcontvalcie                  INTEGER;
    DEFINE vregistros                   INTEGER;
    DEFINE vcuenta                      CHAR(20);
    DEFINE vProdChequerasPM             CHAR(4);
    DEFINE vdia                         CHAR(2);
    DEFINE vfecha_pago                  DATE;
    DEFINE vnumdias                     SMALLINT;
    DEFINE vexiste_cta                  SMALLINT;
    DEFINE vhora            		    DATETIME HOUR TO FRACTION;
    DEFINE vfolio_suc       		    CHAR(16);
    DEFINE vint_acum                    MONEY(14,2);
    DEFINE vfecultdep                   DATE;
    DEFINE vdiasinact                   INTEGER;
    DEFINE vabierto                     CHAR(1);
    DEFINE vaniomes                     CHAR(6);
    DEFINE vexiste_proy                 SMALLINT;
    DEFINE vtotsuc                      INTEGER;
    DEFINE vcontproc                    INTEGER;
    DEFINE vtfechaxxx                   DATE;
    DEFINE vnum_cte                     CHAR(20);
    DEFINE vfecha_alta                  DATE;
    DEFINE vhoraw           		    CHAR(15);
    DEFINE vfecha_mod                   DATE;
    DEFINE vcuentaini                   CHAR(20);
    DEFINE vcuentafin                   CHAR(20);
    DEFINE vinicio_cierre               SMALLINT;
    DEFINE vProdPROAC                   CHAR(4);

    LET vgusuario       = USER;
    LET vgfecha_hoy     = ' ';
    LET vgpri_dia_mes   = ' ';
    LET vgpri_hab_mes   = ' ';
    LET vgult_dia_mes   = ' ';
    LET vgult_hab_mes   = ' ';
    LET vgprox_fecha    = ' ';
    LET vgtrans_pag_int = ' ';
    LET vgtransisr      = ' ';
    LET vgtranprov      = ' ';
    LET vgtranrevprov   = ' ';
    LET vgtranabotrasp  = ' ';
    LET vgtranrecrece   = ' ';
    LET vgProdCreciente = ' ';
    LET vgstatus_cta    = ' ';
    LET vgfecha_mod     = ' ';
    LET vgfecha_alta    = ' ';

    LET vcodret              = "000";
    LET vcodret2             = "000";
    LET vcodret3             = "000";
    LET vsqlerr              = 0;
    LET isam_err             = 0;
    LET error_info           = '';
    LET vfechahora           = " ";
    LET vsql                 = '';
    LET vstmt                = '';
    LET vsistema             = "01";
    LET vproceso             = "cierrechqinvcrecomp2";
    LET vstatuscierreinv     = '';
    LET vstatuscobroreestruc = '';
    LET vProdChequeras       = '';
    LET vexiste              = '';
    LET vexiste2             = 0;
    LET vexistefin           = 0;
    LEt vdias                = 0;
    LET vregproc             = 0;
    LET vporcentajerror      = 0;
    LET vfcuenta             = '';
    LET FechaProc            = '';
    LET vProducto            = '';
    LET vSdoActual           = 0.00;
    LET vSucursal            = '';
    LET vcontvalcie          = 0;
    LET vregistros           = 0;
    LET vcuenta              = '';
    LET vProdChequerasPM     = '';
    LET vdia                 = '';
    LET vfecha_pago          = '';
    LET vnumdias             = 0;
    LET vexiste_cta          = 0;
    LET vhora                = '';
    LET vfolio_suc           = '';
    LET vint_acum            = 0.00;
    LET vfecultdep           = '';
    LET vdiasinact           = 0;
    LET vabierto             = '0';
    LET vaniomes             = '';
    LET vexiste_proy         = 0;
    LET vtotsuc              = 0;
    LET vcontproc            = 0;
    LET vtfechaxxx           = '';
    LET vnum_cte             = '';
    LET vfecha_alta          = '';
    LET vhoraw               = '';
    LET vfecha_mod           = '';
    LET vcuentaini           = '';
    LET vcuentafin           = '';
    LET vinicio_cierre       = 0;
    LET vProdPROAC           = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp2.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            LET vfechahora = CURRENT;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec2.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec2.sql';
            SYSTEM vstmt;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp2.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    --- SET PDQPRIORITY 10;
    
    -- // ##################################### //
    -- // #  FECHAS DEL SISTEMA DE CAPTACION  # //
    -- // ##################################### //
    SELECT fecha_hoy, pri_dia_mes, pri_hab_mes, ult_dia_mes, ult_hab_mes, prox_fecha
      INTO vgfecha_hoy, vgpri_dia_mes, vgpri_hab_mes, vgult_dia_mes, vgult_hab_mes, vgprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- // ###################################### //
    -- // #  TRANSACCION DE PAGO DE INTERESES  # //
    -- // ###################################### //
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";

    -- // ################################# //
    -- // #  TRANSACCION DE COBRO DE ISR  # //
    -- // ################################# //
    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";

    -- // ########################################### //
    -- // #  TRANSACCION DE PROVISION DE INTERESES  # //
    -- // ########################################### //
    SELECT valor
      INTO vgtranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";

    -- // ############################################## //
    -- // #  TRANSACCION DE DESPROVISION DE INTERESES  * //
    -- // ############################################## //
    SELECT valor
      INTO vgtranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";

    -- // ######################################## //
    -- // #  TRANSACCION DE ABONO PARA TRASPASO  # //
    -- // ######################################## //
    SELECT valor
      INTO vgtranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";

    -- // ############################################# //
    -- // #  TRANSACCION DE REINVERSION DE INVS CREC  # //
    -- // ############################################# //
    SELECT valor
      INTO vgtranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";

    -- // ################################## //
    -- // #  Producto Inversion Creciente  # //
    -- // ################################## //
    SELECT valor
      INTO vgProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";

    -- // ########################### //
    -- // #  Producto de Chequeras  # //
    -- // ########################### //
    SELECT valor
      INTO vProdChequeras
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
       
    -- // ####################################### //
    -- // #  Producto de Chequeras Empresarial  # //
    -- // ####################################### //
    SELECT valor
      INTO vProdChequerasPM
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqpm";   
       
    -- // ######################################## //
    -- // #  Producto Programa Ahorre su Cambio  # //
    -- // ######################################## //
    SELECT valor
      INTO vProdPROAC
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PROACPRODUCTO";   
    
    -- // ############################################################## //
    -- // #  VALIDA QUE NO SE HAYA REALIZADO EL CIERRE DEL DIA ACTUAL  # //
    -- // ############################################################## //
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgfecha_hoy
       AND sistema = vsistema;

    IF vexiste2 = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vgfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horacierrecrec2.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec2.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec2.sql';
            SYSTEM vsql; 
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec2.sql';
            SYSTEM vstmt;
        ELSE
            SELECT 1
              INTO vexiste
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = 'cierreinvcreccomp2'
               AND fecha = vgfecha_hoy;

            IF vexiste = "1" THEN
                LET vcodret = "966";
                RETURN vcodret;
            END IF            
        END IF
    END IF;
    
    -- // #################################################################### //
    -- // # VALIDA QUE EL CIERRE PRINCIPAL HAYA COMENZADO A PROCESAR CUENTAS # //
    -- // #################################################################### //
    WHILE vinicio_cierre = 0 
        SET ISOLATION TO DIRTY READ;
        
        SELECT COUNT(*)
          INTO vinicio_cierre
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'inicio_cierreinvcrec'
           AND fecha = vgfecha_hoy;
    END WHILE;

    -- // ####################################### //
    -- // #  OBTIENE NUMERO DE DIAS A PROCESAR  # //
    -- // ####################################### //
    IF vgfecha_hoy = vgult_hab_mes THEN
        LET vdias = vgult_dia_mes - vgfecha_hoy + 1;

        IF vgprox_fecha > vgult_dia_mes THEN
            LET vdias = vdias + ((vgprox_fecha-1) - vgult_dia_mes);
        END IF
    ELSE
        LET vdias = vgprox_fecha - vgfecha_hoy;
    END IF

    -- // ############################################ //
    -- // #  OBTIENE NUMERO DE REGISTROS A PROCESAR  # //
    -- // ############################################ //
    SELECT COUNT(*)
      INTO vregproc
      FROM sc_maechq
     WHERE producto = vgProdCreciente
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy);

    -- // ########################################################### //
    -- // #  Obtiene parametro de porcentajes de error por proceso  # //
    -- // ########################################################### //
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
       
    -- // OBTIENE RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentaini
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp2'; 
       
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp3'; 
       
       
    -- // ######################################################################### //
    -- // #  FOREACH PRINCIPAL DEL CIERRE DE CAPTACION DE INVERSIONES CRECIENTES  # //
    -- // ######################################################################### //
    FOREACH principal WITH HOLD FOR
        SELECT mae.cuenta, mae.fecha_proceso, mae.producto, mae.sdo_actual, mae.status_cta, mae.sucursal,
               ins.instrucc, ins.cuentadep, nvl(noc.fecha_mod, vgfecha_hoy), nvl(noc.fecha_alta, vgfecha_hoy)
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal,
               vginstrucc, vgcuentadep, vgfecha_mod, vgfecha_alta
          FROM sc_maechq mae,
               sc_maeinstrucc ins,
               sc_maenoc noc
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta <> '2'
           AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vgfecha_hoy )
           AND mae.cuenta >= vcuentaini
           AND mae.cuenta < vcuentafin
           AND ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.capint = 'R'
           AND ins.instrucc = '01'
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        IF FechaProc IS NULL THEN
            IF vSdoActual = 0 THEN
                UPDATE sc_maechq
                   SET status_cta = "2",
                       fecha_proceso = vgfecha_hoy
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                LET vcodret = "000";

                CONTINUE FOREACH;
            ELSE
                CALL creciente_proy_cierre(pempresa, vfcuenta, vProducto, vSdoActual, vginstrucc)
                RETURNING vcodret;

                IF vcodret <> "000" THEN
                    CONTINUE FOREACH;
                END IF
            END IF
        END IF

        -- // Actualiza la fecha como ya procesado si vencio su plazo
        IF vgfecha_mod < vgfecha_hoy THEN
            UPDATE sc_maechq
               SET fecha_proceso = vgprox_fecha
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            CONTINUE FOREACH;
        END IF
        
        CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT COUNT(*)
              INTO vcontvalcie
              FROM sc_valcierre
             WHERE empresa = pempresa
               AND cuenta <> '';

            LET vregistros = ROUND(vregproc * vporcentajerror / 100);

            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                           'SET ejecutivo = '''||vgusuario||''','||
                           'status_proc   = '''||'C'||''','||
                           'codret        = '''||vcodret||''','||
                           'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                           'WHERE empresa = '''||pempresa||''' '||
                           'AND proceso   = '''||vproceso||''' '||
                           'AND fecha     = '''||vgfecha_hoy||''' '||
                           'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec2.sql';
                SYSTEM vsql;
                LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec2.sql';
                SYSTEM vstmt;
                RETURN vcodret;
            END IF;
        END IF;

        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
    END FOREACH;    
    
    
    -- // ############################ //
    -- // #  Registra fin de cierre  # //
    -- // ############################ //
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vgfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec2.sql';
    SYSTEM vsql;

    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec2.sql';
    SYSTEM vstmt;

    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreinvcreccomp2";

    SET LOCK MODE TO NOT WAIT;

    RETURN vcodret;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION:   Complemento 2 Cierre Diario del Producto de Inversion Creciente de Captacion ',
'EJECUTADO POR: Control-M',
'AUTOR:         JICS',
'FECHA:         20/Febrero/2013',
'VERSION:       1.00.0000',
'Base de Datos: bdicheq';

CREATE PROCEDURE "informix".cierrechqinvcreccomp3(pempresa CHAR(3)) 
RETURNING CHAR(5);
     
    DEFINE GLOBAL vgusuario             CHAR(8)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_hoy           DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgprox_fecha          DATE        DEFAULT " ";
    DEFINE GLOBAL vgtrans_pag_int       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtransisr            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranprov            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrevprov         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranabotrasp        CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrecrece         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgProdCreciente       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgstatus_cta          CHAR(1)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_mod           DATE        DEFAULT " ";
    DEFINE GLOBAL vgfecha_alta          DATE        DEFAULT " ";
    DEFINE GLOBAL vginstrucc            CHAR(2)     DEFAULT " ";
    DEFINE GLOBAL vgcuentadep           CHAR(20)    DEFAULT " ";

    DEFINE vcodret                      CHAR(5);
    DEFINE vcodret2                     CHAR(5);
    DEFINE vcodret3                     CHAR(40);
    DEFINE vsqlerr                      INTEGER;
    DEFINE isam_err                     INTEGER;
    DEFINE error_info                   CHAR(40);
    DEFINE vfechahora                   CHAR(40);
    DEFINE vsql                         CHAR(600);
    DEFINE vstmt                        CHAR(250);
    DEFINE vsistema                     CHAR(2);
    DEFINE vproceso                     CHAR(20);
    DEFINE vstatuscierreinv             CHAR(1);
    DEFINE vstatuscobroreestruc         CHAR(1);
    DEFINE vProdChequeras               CHAR(4);
    DEFINE vexiste                      CHAR(1);
    DEFINE vexiste2                     INTEGER;
    DEFINE vexistefin                   INTEGER;
    DEFINE vdias                        INTEGER;
    DEFINE vregproc                     INTEGER;
    DEFINE vporcentajerror              INTEGER;
    DEFINE vfcuenta                     CHAR(20);
    DEFINE FechaProc                    DATE;
    DEFINE vProducto                    CHAR(4);
    DEFINE vSdoActual                   DECIMAL(14,2);
    DEFINE vSucursal                    CHAR(4);
    DEFINE vcontvalcie                  INTEGER;
    DEFINE vregistros                   INTEGER;
    DEFINE vcuenta                      CHAR(20);
    DEFINE vProdChequerasPM             CHAR(4);
    DEFINE vdia                         CHAR(2);
    DEFINE vfecha_pago                  DATE;
    DEFINE vnumdias                     SMALLINT;
    DEFINE vexiste_cta                  SMALLINT;
    DEFINE vhora            		    DATETIME HOUR TO FRACTION;
    DEFINE vfolio_suc       		    CHAR(16);
    DEFINE vint_acum                    MONEY(14,2);
    DEFINE vfecultdep                   DATE;
    DEFINE vdiasinact                   INTEGER;
    DEFINE vabierto                     CHAR(1);
    DEFINE vaniomes                     CHAR(6);
    DEFINE vexiste_proy                 SMALLINT;
    DEFINE vtotsuc                      INTEGER;
    DEFINE vcontproc                    INTEGER;
    DEFINE vtfechaxxx                   DATE;
    DEFINE vnum_cte                     CHAR(20);
    DEFINE vfecha_alta                  DATE;
    DEFINE vhoraw           		    CHAR(15);
    DEFINE vfecha_mod                   DATE;
    DEFINE vcuentaini                   CHAR(20);
    DEFINE vcuentafin                   CHAR(20);
    DEFINE vinicio_cierre               SMALLINT;
    DEFINE vProdPROAC                   CHAR(4);

    LET vgusuario       = USER;
    LET vgfecha_hoy     = ' ';
    LET vgpri_dia_mes   = ' ';
    LET vgpri_hab_mes   = ' ';
    LET vgult_dia_mes   = ' ';
    LET vgult_hab_mes   = ' ';
    LET vgprox_fecha    = ' ';
    LET vgtrans_pag_int = ' ';
    LET vgtransisr      = ' ';
    LET vgtranprov      = ' ';
    LET vgtranrevprov   = ' ';
    LET vgtranabotrasp  = ' ';
    LET vgtranrecrece   = ' ';
    LET vgProdCreciente = ' ';
    LET vgstatus_cta    = ' ';
    LET vgfecha_mod     = ' ';
    LET vgfecha_alta    = ' ';

    LET vcodret              = "000";
    LET vcodret2             = "000";
    LET vcodret3             = "000";
    LET vsqlerr              = 0;
    LET isam_err             = 0;
    LET error_info           = '';
    LET vfechahora           = " ";
    LET vsql                 = '';
    LET vstmt                = '';
    LET vsistema             = "01";
    LET vproceso             = "cierrechqinvcrecomp3";
    LET vstatuscierreinv     = '';
    LET vstatuscobroreestruc = '';
    LET vProdChequeras       = '';
    LET vexiste              = '';
    LET vexiste2             = 0;
    LET vexistefin           = 0;
    LEt vdias                = 0;
    LET vregproc             = 0;
    LET vporcentajerror      = 0;
    LET vfcuenta             = '';
    LET FechaProc            = '';
    LET vProducto            = '';
    LET vSdoActual           = 0.00;
    LET vSucursal            = '';
    LET vcontvalcie          = 0;
    LET vregistros           = 0;
    LET vcuenta              = '';
    LET vProdChequerasPM     = '';
    LET vdia                 = '';
    LET vfecha_pago          = '';
    LET vnumdias             = 0;
    LET vexiste_cta          = 0;
    LET vhora                = '';
    LET vfolio_suc           = '';
    LET vint_acum            = 0.00;
    LET vfecultdep           = '';
    LET vdiasinact           = 0;
    LET vabierto             = '0';
    LET vaniomes             = '';
    LET vexiste_proy         = 0;
    LET vtotsuc              = 0;
    LET vcontproc            = 0;
    LET vtfechaxxx           = '';
    LET vnum_cte             = '';
    LET vfecha_alta          = '';
    LET vhoraw               = '';
    LET vfecha_mod           = '';
    LET vcuentaini           = '';
    LET vcuentafin           = '';
    LET vinicio_cierre       = 0;
    LET vProdPROAC           = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp3.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            LET vfechahora = CURRENT;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec3.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec3.sql';
            SYSTEM vstmt;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp3.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    --- SET PDQPRIORITY 10;
    
    -- // ##################################### //
    -- // #  FECHAS DEL SISTEMA DE CAPTACION  # //
    -- // ##################################### //
    SELECT fecha_hoy, pri_dia_mes, pri_hab_mes, ult_dia_mes, ult_hab_mes, prox_fecha
      INTO vgfecha_hoy, vgpri_dia_mes, vgpri_hab_mes, vgult_dia_mes, vgult_hab_mes, vgprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- // ###################################### //
    -- // #  TRANSACCION DE PAGO DE INTERESES  # //
    -- // ###################################### //
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";

    -- // ################################# //
    -- // #  TRANSACCION DE COBRO DE ISR  # //
    -- // ################################# //
    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";

    -- // ########################################### //
    -- // #  TRANSACCION DE PROVISION DE INTERESES  # //
    -- // ########################################### //
    SELECT valor
      INTO vgtranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";

    -- // ############################################## //
    -- // #  TRANSACCION DE DESPROVISION DE INTERESES  * //
    -- // ############################################## //
    SELECT valor
      INTO vgtranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";

    -- // ######################################## //
    -- // #  TRANSACCION DE ABONO PARA TRASPASO  # //
    -- // ######################################## //
    SELECT valor
      INTO vgtranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";

    -- // ############################################# //
    -- // #  TRANSACCION DE REINVERSION DE INVS CREC  # //
    -- // ############################################# //
    SELECT valor
      INTO vgtranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";

    -- // ################################## //
    -- // #  Producto Inversion Creciente  # //
    -- // ################################## //
    SELECT valor
      INTO vgProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";

    -- // ########################### //
    -- // #  Producto de Chequeras  # //
    -- // ########################### //
    SELECT valor
      INTO vProdChequeras
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
       
    -- // ####################################### //
    -- // #  Producto de Chequeras Empresarial  # //
    -- // ####################################### //
    SELECT valor
      INTO vProdChequerasPM
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqpm";   
       
    -- // ######################################## //
    -- // #  Producto Programa Ahorre su Cambio  # //
    -- // ######################################## //
    SELECT valor
      INTO vProdPROAC
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PROACPRODUCTO";   
    
    -- // ############################################################## //
    -- // #  VALIDA QUE NO SE HAYA REALIZADO EL CIERRE DEL DIA ACTUAL  # //
    -- // ############################################################## //
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgfecha_hoy
       AND sistema = vsistema;

    IF vexiste2 = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vgfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horacierrecrec3.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec3.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec3.sql';
            SYSTEM vsql; 
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec3.sql';
            SYSTEM vstmt;
        ELSE
            SELECT 1
              INTO vexiste
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = 'cierreinvcreccomp3'
               AND fecha = vgfecha_hoy;

            IF vexiste = "1" THEN
                LET vcodret = "966";
                RETURN vcodret;
            END IF            
        END IF
    END IF;
    
    -- // #################################################################### //
    -- // # VALIDA QUE EL CIERRE PRINCIPAL HAYA COMENZADO A PROCESAR CUENTAS # //
    -- // #################################################################### //
    WHILE vinicio_cierre = 0 
        SET ISOLATION TO DIRTY READ;
        
        SELECT COUNT(*)
          INTO vinicio_cierre
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'inicio_cierreinvcrec'
           AND fecha = vgfecha_hoy;
    END WHILE;

    -- // ####################################### //
    -- // #  OBTIENE NUMERO DE DIAS A PROCESAR  # //
    -- // ####################################### //
    IF vgfecha_hoy = vgult_hab_mes THEN
        LET vdias = vgult_dia_mes - vgfecha_hoy + 1;

        IF vgprox_fecha > vgult_dia_mes THEN
            LET vdias = vdias + ((vgprox_fecha-1) - vgult_dia_mes);
        END IF
    ELSE
        LET vdias = vgprox_fecha - vgfecha_hoy;
    END IF

    -- // ############################################ //
    -- // #  OBTIENE NUMERO DE REGISTROS A PROCESAR  # //
    -- // ############################################ //
    SELECT COUNT(*)
      INTO vregproc
      FROM sc_maechq
     WHERE producto = vgProdCreciente
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy);

    -- // ########################################################### //
    -- // #  Obtiene parametro de porcentajes de error por proceso  # //
    -- // ########################################################### //
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
       
    -- // OBTIENE RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentaini
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp3'; 
       
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp4'; 
       
       
    -- // ######################################################################### //
    -- // #  FOREACH PRINCIPAL DEL CIERRE DE CAPTACION DE INVERSIONES CRECIENTES  # //
    -- // ######################################################################### //
    FOREACH principal WITH HOLD FOR
        SELECT mae.cuenta, mae.fecha_proceso, mae.producto, mae.sdo_actual, mae.status_cta, mae.sucursal,
               ins.instrucc, ins.cuentadep, nvl(noc.fecha_mod, vgfecha_hoy), nvl(noc.fecha_alta, vgfecha_hoy)
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal,
               vginstrucc, vgcuentadep, vgfecha_mod, vgfecha_alta
          FROM sc_maechq mae,
               sc_maeinstrucc ins,
               sc_maenoc noc
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta <> '2'
           AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vgfecha_hoy )
           AND mae.cuenta >= vcuentaini
           AND mae.cuenta < vcuentafin
           AND ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.capint = 'R'
           AND ins.instrucc = '01'
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        IF FechaProc IS NULL THEN
            IF vSdoActual = 0 THEN
                UPDATE sc_maechq
                   SET status_cta = "2",
                       fecha_proceso = vgfecha_hoy
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                LET vcodret = "000";

                CONTINUE FOREACH;
            ELSE
                CALL creciente_proy_cierre(pempresa, vfcuenta, vProducto, vSdoActual, vginstrucc)
                RETURNING vcodret;

                IF vcodret <> "000" THEN
                    CONTINUE FOREACH;
                END IF
            END IF
        END IF

        -- // Actualiza la fecha como ya procesado si vencio su plazo
        IF vgfecha_mod < vgfecha_hoy THEN
            UPDATE sc_maechq
               SET fecha_proceso = vgprox_fecha
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            CONTINUE FOREACH;
        END IF
        
        CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT COUNT(*)
              INTO vcontvalcie
              FROM sc_valcierre
             WHERE empresa = pempresa
               AND cuenta <> '';

            LET vregistros = ROUND(vregproc * vporcentajerror / 100);

            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                           'SET ejecutivo = '''||vgusuario||''','||
                           'status_proc   = '''||'C'||''','||
                           'codret        = '''||vcodret||''','||
                           'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                           'WHERE empresa = '''||pempresa||''' '||
                           'AND proceso   = '''||vproceso||''' '||
                           'AND fecha     = '''||vgfecha_hoy||''' '||
                           'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec3.sql';
                SYSTEM vsql;
                LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec3.sql';
                SYSTEM vstmt;
                RETURN vcodret;
            END IF;
        END IF;

        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
    END FOREACH;    
    
    
    -- // ############################ //
    -- // #  Registra fin de cierre  # //
    -- // ############################ //
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vgfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec3.sql';
    SYSTEM vsql;

    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec3.sql';
    SYSTEM vstmt;

    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreinvcreccomp3";

    SET LOCK MODE TO NOT WAIT;

    RETURN vcodret;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION:   Complemento 1 Cierre Diario del Producto de Inversion Creciente de Captacion ',
'EJECUTADO POR: Control-M',
'AUTOR:         JICS',
'FECHA:         20/Febrero/2013',
'VERSION:       1.00.0000',
'Base de Datos: bdicheq';

CREATE PROCEDURE "informix".cierrechqinvcreccomp4(pempresa CHAR(3)) 
RETURNING CHAR(5);
     
    DEFINE GLOBAL vgusuario             CHAR(8)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_hoy           DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgprox_fecha          DATE        DEFAULT " ";
    DEFINE GLOBAL vgtrans_pag_int       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtransisr            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranprov            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrevprov         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranabotrasp        CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrecrece         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgProdCreciente       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgstatus_cta          CHAR(1)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_mod           DATE        DEFAULT " ";
    DEFINE GLOBAL vgfecha_alta          DATE        DEFAULT " ";
    DEFINE GLOBAL vginstrucc            CHAR(2)     DEFAULT " ";
    DEFINE GLOBAL vgcuentadep           CHAR(20)    DEFAULT " ";

    DEFINE vcodret                      CHAR(5);
    DEFINE vcodret2                     CHAR(5);
    DEFINE vcodret3                     CHAR(40);
    DEFINE vsqlerr                      INTEGER;
    DEFINE isam_err                     INTEGER;
    DEFINE error_info                   CHAR(40);
    DEFINE vfechahora                   CHAR(40);
    DEFINE vsql                         CHAR(600);
    DEFINE vstmt                        CHAR(250);
    DEFINE vsistema                     CHAR(2);
    DEFINE vproceso                     CHAR(20);
    DEFINE vstatuscierreinv             CHAR(1);
    DEFINE vstatuscobroreestruc         CHAR(1);
    DEFINE vProdChequeras               CHAR(4);
    DEFINE vexiste                      CHAR(1);
    DEFINE vexiste2                     INTEGER;
    DEFINE vexistefin                   INTEGER;
    DEFINE vdias                        INTEGER;
    DEFINE vregproc                     INTEGER;
    DEFINE vporcentajerror              INTEGER;
    DEFINE vfcuenta                     CHAR(20);
    DEFINE FechaProc                    DATE;
    DEFINE vProducto                    CHAR(4);
    DEFINE vSdoActual                   DECIMAL(14,2);
    DEFINE vSucursal                    CHAR(4);
    DEFINE vcontvalcie                  INTEGER;
    DEFINE vregistros                   INTEGER;
    DEFINE vcuenta                      CHAR(20);
    DEFINE vProdChequerasPM             CHAR(4);
    DEFINE vdia                         CHAR(2);
    DEFINE vfecha_pago                  DATE;
    DEFINE vnumdias                     SMALLINT;
    DEFINE vexiste_cta                  SMALLINT;
    DEFINE vhora            		    DATETIME HOUR TO FRACTION;
    DEFINE vfolio_suc       		    CHAR(16);
    DEFINE vint_acum                    MONEY(14,2);
    DEFINE vfecultdep                   DATE;
    DEFINE vdiasinact                   INTEGER;
    DEFINE vabierto                     CHAR(1);
    DEFINE vaniomes                     CHAR(6);
    DEFINE vexiste_proy                 SMALLINT;
    DEFINE vtotsuc                      INTEGER;
    DEFINE vcontproc                    INTEGER;
    DEFINE vtfechaxxx                   DATE;
    DEFINE vnum_cte                     CHAR(20);
    DEFINE vfecha_alta                  DATE;
    DEFINE vhoraw           		    CHAR(15);
    DEFINE vfecha_mod                   DATE;
    DEFINE vcuentaini                   CHAR(20);
    DEFINE vcuentafin                   CHAR(20);
    DEFINE vinicio_cierre               SMALLINT;
    DEFINE vProdPROAC                   CHAR(4);

    LET vgusuario       = USER;
    LET vgfecha_hoy     = ' ';
    LET vgpri_dia_mes   = ' ';
    LET vgpri_hab_mes   = ' ';
    LET vgult_dia_mes   = ' ';
    LET vgult_hab_mes   = ' ';
    LET vgprox_fecha    = ' ';
    LET vgtrans_pag_int = ' ';
    LET vgtransisr      = ' ';
    LET vgtranprov      = ' ';
    LET vgtranrevprov   = ' ';
    LET vgtranabotrasp  = ' ';
    LET vgtranrecrece   = ' ';
    LET vgProdCreciente = ' ';
    LET vgstatus_cta    = ' ';
    LET vgfecha_mod     = ' ';
    LET vgfecha_alta    = ' ';

    LET vcodret              = "000";
    LET vcodret2             = "000";
    LET vcodret3             = "000";
    LET vsqlerr              = 0;
    LET isam_err             = 0;
    LET error_info           = '';
    LET vfechahora           = " ";
    LET vsql                 = '';
    LET vstmt                = '';
    LET vsistema             = "01";
    LET vproceso             = "cierrechqinvcrecomp4";
    LET vstatuscierreinv     = '';
    LET vstatuscobroreestruc = '';
    LET vProdChequeras       = '';
    LET vexiste              = '';
    LET vexiste2             = 0;
    LET vexistefin           = 0;
    LEt vdias                = 0;
    LET vregproc             = 0;
    LET vporcentajerror      = 0;
    LET vfcuenta             = '';
    LET FechaProc            = '';
    LET vProducto            = '';
    LET vSdoActual           = 0.00;
    LET vSucursal            = '';
    LET vcontvalcie          = 0;
    LET vregistros           = 0;
    LET vcuenta              = '';
    LET vProdChequerasPM     = '';
    LET vdia                 = '';
    LET vfecha_pago          = '';
    LET vnumdias             = 0;
    LET vexiste_cta          = 0;
    LET vhora                = '';
    LET vfolio_suc           = '';
    LET vint_acum            = 0.00;
    LET vfecultdep           = '';
    LET vdiasinact           = 0;
    LET vabierto             = '0';
    LET vaniomes             = '';
    LET vexiste_proy         = 0;
    LET vtotsuc              = 0;
    LET vcontproc            = 0;
    LET vtfechaxxx           = '';
    LET vnum_cte             = '';
    LET vfecha_alta          = '';
    LET vhoraw               = '';
    LET vfecha_mod           = '';
    LET vcuentaini           = '';
    LET vcuentafin           = '';
    LET vinicio_cierre       = 0;
    LET vProdPROAC           = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp4.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            LET vfechahora = CURRENT;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec4.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec4.sql';
            SYSTEM vstmt;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp4.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    --- SET PDQPRIORITY 10;
    
    -- // ##################################### //
    -- // #  FECHAS DEL SISTEMA DE CAPTACION  # //
    -- // ##################################### //
    SELECT fecha_hoy, pri_dia_mes, pri_hab_mes, ult_dia_mes, ult_hab_mes, prox_fecha
      INTO vgfecha_hoy, vgpri_dia_mes, vgpri_hab_mes, vgult_dia_mes, vgult_hab_mes, vgprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- // ###################################### //
    -- // #  TRANSACCION DE PAGO DE INTERESES  # //
    -- // ###################################### //
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";

    -- // ################################# //
    -- // #  TRANSACCION DE COBRO DE ISR  # //
    -- // ################################# //
    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";

    -- // ########################################### //
    -- // #  TRANSACCION DE PROVISION DE INTERESES  # //
    -- // ########################################### //
    SELECT valor
      INTO vgtranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";

    -- // ############################################## //
    -- // #  TRANSACCION DE DESPROVISION DE INTERESES  * //
    -- // ############################################## //
    SELECT valor
      INTO vgtranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";

    -- // ######################################## //
    -- // #  TRANSACCION DE ABONO PARA TRASPASO  # //
    -- // ######################################## //
    SELECT valor
      INTO vgtranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";

    -- // ############################################# //
    -- // #  TRANSACCION DE REINVERSION DE INVS CREC  # //
    -- // ############################################# //
    SELECT valor
      INTO vgtranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";

    -- // ################################## //
    -- // #  Producto Inversion Creciente  # //
    -- // ################################## //
    SELECT valor
      INTO vgProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";

    -- // ########################### //
    -- // #  Producto de Chequeras  # //
    -- // ########################### //
    SELECT valor
      INTO vProdChequeras
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
       
    -- // ####################################### //
    -- // #  Producto de Chequeras Empresarial  # //
    -- // ####################################### //
    SELECT valor
      INTO vProdChequerasPM
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqpm";   
       
    -- // ######################################## //
    -- // #  Producto Programa Ahorre su Cambio  # //
    -- // ######################################## //
    SELECT valor
      INTO vProdPROAC
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PROACPRODUCTO";   
    
    -- // ############################################################## //
    -- // #  VALIDA QUE NO SE HAYA REALIZADO EL CIERRE DEL DIA ACTUAL  # //
    -- // ############################################################## //
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgfecha_hoy
       AND sistema = vsistema;

    IF vexiste2 = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vgfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horacierrecrec4.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec4.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec4.sql';
            SYSTEM vsql; 
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec4.sql';
            SYSTEM vstmt;
        ELSE
            SELECT 1
              INTO vexiste
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = 'cierreinvcreccomp4'
               AND fecha = vgfecha_hoy;

            IF vexiste = "1" THEN
                LET vcodret = "966";
                RETURN vcodret;
            END IF            
        END IF
    END IF;
    
    -- // #################################################################### //
    -- // # VALIDA QUE EL CIERRE PRINCIPAL HAYA COMENZADO A PROCESAR CUENTAS # //
    -- // #################################################################### //
    WHILE vinicio_cierre = 0 
        SET ISOLATION TO DIRTY READ;
        
        SELECT COUNT(*)
          INTO vinicio_cierre
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'inicio_cierreinvcrec'
           AND fecha = vgfecha_hoy;
    END WHILE;

    -- // ####################################### //
    -- // #  OBTIENE NUMERO DE DIAS A PROCESAR  # //
    -- // ####################################### //
    IF vgfecha_hoy = vgult_hab_mes THEN
        LET vdias = vgult_dia_mes - vgfecha_hoy + 1;

        IF vgprox_fecha > vgult_dia_mes THEN
            LET vdias = vdias + ((vgprox_fecha-1) - vgult_dia_mes);
        END IF
    ELSE
        LET vdias = vgprox_fecha - vgfecha_hoy;
    END IF

    -- // ############################################ //
    -- // #  OBTIENE NUMERO DE REGISTROS A PROCESAR  # //
    -- // ############################################ //
    SELECT COUNT(*)
      INTO vregproc
      FROM sc_maechq
     WHERE producto = vgProdCreciente
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy);

    -- // ########################################################### //
    -- // #  Obtiene parametro de porcentajes de error por proceso  # //
    -- // ########################################################### //
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
       
    -- // OBTIENE RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentaini
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp4'; 
       
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp5'; 
       
       
    -- // ######################################################################### //
    -- // #  FOREACH PRINCIPAL DEL CIERRE DE CAPTACION DE INVERSIONES CRECIENTES  # //
    -- // ######################################################################### //
    FOREACH principal WITH HOLD FOR
        SELECT mae.cuenta, mae.fecha_proceso, mae.producto, mae.sdo_actual, mae.status_cta, mae.sucursal,
               ins.instrucc, ins.cuentadep, nvl(noc.fecha_mod, vgfecha_hoy), nvl(noc.fecha_alta, vgfecha_hoy)
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal,
               vginstrucc, vgcuentadep, vgfecha_mod, vgfecha_alta
          FROM sc_maechq mae,
               sc_maeinstrucc ins,
               sc_maenoc noc
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta <> '2'
           AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vgfecha_hoy )
           AND mae.cuenta >= vcuentaini
           AND mae.cuenta < vcuentafin
           AND ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.capint = 'R'
           AND ins.instrucc = '01'
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        IF FechaProc IS NULL THEN
            IF vSdoActual = 0 THEN
                UPDATE sc_maechq
                   SET status_cta = "2",
                       fecha_proceso = vgfecha_hoy
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                LET vcodret = "000";

                CONTINUE FOREACH;
            ELSE
                CALL creciente_proy_cierre(pempresa, vfcuenta, vProducto, vSdoActual, vginstrucc)
                RETURNING vcodret;

                IF vcodret <> "000" THEN
                    CONTINUE FOREACH;
                END IF
            END IF
        END IF

        -- // Actualiza la fecha como ya procesado si vencio su plazo
        IF vgfecha_mod < vgfecha_hoy THEN
            UPDATE sc_maechq
               SET fecha_proceso = vgprox_fecha
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            CONTINUE FOREACH;
        END IF
        
        CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT COUNT(*)
              INTO vcontvalcie
              FROM sc_valcierre
             WHERE empresa = pempresa
               AND cuenta <> '';

            LET vregistros = ROUND(vregproc * vporcentajerror / 100);

            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                           'SET ejecutivo = '''||vgusuario||''','||
                           'status_proc   = '''||'C'||''','||
                           'codret        = '''||vcodret||''','||
                           'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                           'WHERE empresa = '''||pempresa||''' '||
                           'AND proceso   = '''||vproceso||''' '||
                           'AND fecha     = '''||vgfecha_hoy||''' '||
                           'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec4.sql';
                SYSTEM vsql;
                LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec4.sql';
                SYSTEM vstmt;
                RETURN vcodret;
            END IF;
        END IF;

        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
    END FOREACH;    
    
    
    -- // ############################ //
    -- // #  Registra fin de cierre  # //
    -- // ############################ //
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vgfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec4.sql';
    SYSTEM vsql;

    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec4.sql';
    SYSTEM vstmt;

    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreinvcreccomp4";

    SET LOCK MODE TO NOT WAIT;

    RETURN vcodret;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION:   Complemento 1 Cierre Diario del Producto de Inversion Creciente de Captacion ',
'EJECUTADO POR: Control-M',
'AUTOR:         JICS',
'FECHA:         20/Febrero/2013',
'VERSION:       1.00.0000',
'Base de Datos: bdicheq';

CREATE PROCEDURE "informix".cierrechqinvcreccomp5(pempresa CHAR(3)) 
RETURNING CHAR(5);
     
    DEFINE GLOBAL vgusuario             CHAR(8)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_hoy           DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgpri_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_dia_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgult_hab_mes         DATE        DEFAULT " ";
    DEFINE GLOBAL vgprox_fecha          DATE        DEFAULT " ";
    DEFINE GLOBAL vgtrans_pag_int       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtransisr            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranprov            CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrevprov         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranabotrasp        CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgtranrecrece         CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgProdCreciente       CHAR(4)     DEFAULT " ";
    DEFINE GLOBAL vgstatus_cta          CHAR(1)     DEFAULT " ";
    DEFINE GLOBAL vgfecha_mod           DATE        DEFAULT " ";
    DEFINE GLOBAL vgfecha_alta          DATE        DEFAULT " ";
    DEFINE GLOBAL vginstrucc            CHAR(2)     DEFAULT " ";
    DEFINE GLOBAL vgcuentadep           CHAR(20)    DEFAULT " ";

    DEFINE vcodret                      CHAR(5);
    DEFINE vcodret2                     CHAR(5);
    DEFINE vcodret3                     CHAR(40);
    DEFINE vsqlerr                      INTEGER;
    DEFINE isam_err                     INTEGER;
    DEFINE error_info                   CHAR(40);
    DEFINE vfechahora                   CHAR(40);
    DEFINE vsql                         CHAR(600);
    DEFINE vstmt                        CHAR(250);
    DEFINE vsistema                     CHAR(2);
    DEFINE vproceso                     CHAR(20);
    DEFINE vstatuscierreinv             CHAR(1);
    DEFINE vstatuscobroreestruc         CHAR(1);
    DEFINE vProdChequeras               CHAR(4);
    DEFINE vexiste                      CHAR(1);
    DEFINE vexiste2                     INTEGER;
    DEFINE vexistefin                   INTEGER;
    DEFINE vdias                        INTEGER;
    DEFINE vregproc                     INTEGER;
    DEFINE vporcentajerror              INTEGER;
    DEFINE vfcuenta                     CHAR(20);
    DEFINE FechaProc                    DATE;
    DEFINE vProducto                    CHAR(4);
    DEFINE vSdoActual                   DECIMAL(14,2);
    DEFINE vSucursal                    CHAR(4);
    DEFINE vcontvalcie                  INTEGER;
    DEFINE vregistros                   INTEGER;
    DEFINE vcuenta                      CHAR(20);
    DEFINE vProdChequerasPM             CHAR(4);
    DEFINE vdia                         CHAR(2);
    DEFINE vfecha_pago                  DATE;
    DEFINE vnumdias                     SMALLINT;
    DEFINE vexiste_cta                  SMALLINT;
    DEFINE vhora            		    DATETIME HOUR TO FRACTION;
    DEFINE vfolio_suc       		    CHAR(16);
    DEFINE vint_acum                    MONEY(14,2);
    DEFINE vfecultdep                   DATE;
    DEFINE vdiasinact                   INTEGER;
    DEFINE vabierto                     CHAR(1);
    DEFINE vaniomes                     CHAR(6);
    DEFINE vexiste_proy                 SMALLINT;
    DEFINE vtotsuc                      INTEGER;
    DEFINE vcontproc                    INTEGER;
    DEFINE vtfechaxxx                   DATE;
    DEFINE vnum_cte                     CHAR(20);
    DEFINE vfecha_alta                  DATE;
    DEFINE vhoraw           		    CHAR(15);
    DEFINE vfecha_mod                   DATE;
    DEFINE vcuentaini                   CHAR(20);
    DEFINE vinicio_cierre               SMALLINT;
    DEFINE vProdPROAC                   CHAR(4);

    LET vgusuario       = USER;
    LET vgfecha_hoy     = ' ';
    LET vgpri_dia_mes   = ' ';
    LET vgpri_hab_mes   = ' ';
    LET vgult_dia_mes   = ' ';
    LET vgult_hab_mes   = ' ';
    LET vgprox_fecha    = ' ';
    LET vgtrans_pag_int = ' ';
    LET vgtransisr      = ' ';
    LET vgtranprov      = ' ';
    LET vgtranrevprov   = ' ';
    LET vgtranabotrasp  = ' ';
    LET vgtranrecrece   = ' ';
    LET vgProdCreciente = ' ';
    LET vgstatus_cta    = ' ';
    LET vgfecha_mod     = ' ';
    LET vgfecha_alta    = ' ';

    LET vcodret              = "000";
    LET vcodret2             = "000";
    LET vcodret3             = "000";
    LET vsqlerr              = 0;
    LET isam_err             = 0;
    LET error_info           = '';
    LET vfechahora           = " ";
    LET vsql                 = '';
    LET vstmt                = '';
    LET vsistema             = "01";
    LET vproceso             = "cierrechqinvcrecomp5";
    LET vstatuscierreinv     = '';
    LET vstatuscobroreestruc = '';
    LET vProdChequeras       = '';
    LET vexiste              = '';
    LET vexiste2             = 0;
    LET vexistefin           = 0;
    LEt vdias                = 0;
    LET vregproc             = 0;
    LET vporcentajerror      = 0;
    LET vfcuenta             = '';
    LET FechaProc            = '';
    LET vProducto            = '';
    LET vSdoActual           = 0.00;
    LET vSucursal            = '';
    LET vcontvalcie          = 0;
    LET vregistros           = 0;
    LET vcuenta              = '';
    LET vProdChequerasPM     = '';
    LET vdia                 = '';
    LET vfecha_pago          = '';
    LET vnumdias             = 0;
    LET vexiste_cta          = 0;
    LET vhora                = '';
    LET vfolio_suc           = '';
    LET vint_acum            = 0.00;
    LET vfecultdep           = '';
    LET vdiasinact           = 0;
    LET vabierto             = '0';
    LET vaniomes             = '';
    LET vexiste_proy         = 0;
    LET vtotsuc              = 0;
    LET vcontproc            = 0;
    LET vtfechaxxx           = '';
    LET vnum_cte             = '';
    LET vfecha_alta          = '';
    LET vhoraw               = '';
    LET vfecha_mod           = '';
    LET vcuentaini           = '';
    LET vinicio_cierre       = 0;
    LET vProdPROAC           = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp5.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            LET vfechahora = CURRENT;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec5.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec5.sql';
            SYSTEM vstmt;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcreccomp5.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    --- SET PDQPRIORITY 10;
    
    -- // ##################################### //
    -- // #  FECHAS DEL SISTEMA DE CAPTACION  # //
    -- // ##################################### //
    SELECT fecha_hoy, pri_dia_mes, pri_hab_mes, ult_dia_mes, ult_hab_mes, prox_fecha
      INTO vgfecha_hoy, vgpri_dia_mes, vgpri_hab_mes, vgult_dia_mes, vgult_hab_mes, vgprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    -- // ###################################### //
    -- // #  TRANSACCION DE PAGO DE INTERESES  # //
    -- // ###################################### //
    SELECT valor
      INTO vgtrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";

    -- // ################################# //
    -- // #  TRANSACCION DE COBRO DE ISR  # //
    -- // ################################# //
    SELECT valor
      INTO vgtransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";

    -- // ########################################### //
    -- // #  TRANSACCION DE PROVISION DE INTERESES  # //
    -- // ########################################### //
    SELECT valor
      INTO vgtranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";

    -- // ############################################## //
    -- // #  TRANSACCION DE DESPROVISION DE INTERESES  * //
    -- // ############################################## //
    SELECT valor
      INTO vgtranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";

    -- // ######################################## //
    -- // #  TRANSACCION DE ABONO PARA TRASPASO  # //
    -- // ######################################## //
    SELECT valor
      INTO vgtranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";

    -- // ############################################# //
    -- // #  TRANSACCION DE REINVERSION DE INVS CREC  # //
    -- // ############################################# //
    SELECT valor
      INTO vgtranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";

    -- // ################################## //
    -- // #  Producto Inversion Creciente  # //
    -- // ################################## //
    SELECT valor
      INTO vgProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";

    -- // ########################### //
    -- // #  Producto de Chequeras  # //
    -- // ########################### //
    SELECT valor
      INTO vProdChequeras
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
       
    -- // ####################################### //
    -- // #  Producto de Chequeras Empresarial  # //
    -- // ####################################### //
    SELECT valor
      INTO vProdChequerasPM
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqpm"; 
    
    -- // ######################################## //
    -- // #  Producto Programa Ahorre su Cambio  # //
    -- // ######################################## //
    SELECT valor
      INTO vProdPROAC
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PROACPRODUCTO";   
    
    -- // ############################################################## //
    -- // #  VALIDA QUE NO SE HAYA REALIZADO EL CIERRE DEL DIA ACTUAL  # //
    -- // ############################################################## //
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgfecha_hoy
       AND sistema = vsistema;

    IF vexiste2 = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vgfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vgusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horacierrecrec5.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec5.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vgusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vgfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec5.sql';
            SYSTEM vsql; 
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec5.sql';
            SYSTEM vstmt;
        ELSE
            SELECT 1
              INTO vexiste
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = 'cierreinvcreccomp5'
               AND fecha = vgfecha_hoy;

            IF vexiste = "1" THEN
                LET vcodret = "966";
                RETURN vcodret;
            END IF            
        END IF
    END IF;
    
    -- // #################################################################### //
    -- // # VALIDA QUE EL CIERRE PRINCIPAL HAYA COMENZADO A PROCESAR CUENTAS # //
    -- // #################################################################### //
    WHILE vinicio_cierre = 0 
        SET ISOLATION TO DIRTY READ;
        
        SELECT COUNT(*)
          INTO vinicio_cierre
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'inicio_cierreinvcrec'
           AND fecha = vgfecha_hoy;
    END WHILE;

    -- // ####################################### //
    -- // #  OBTIENE NUMERO DE DIAS A PROCESAR  # //
    -- // ####################################### //
    IF vgfecha_hoy = vgult_hab_mes THEN
        LET vdias = vgult_dia_mes - vgfecha_hoy + 1;

        IF vgprox_fecha > vgult_dia_mes THEN
            LET vdias = vdias + ((vgprox_fecha-1) - vgult_dia_mes);
        END IF
    ELSE
        LET vdias = vgprox_fecha - vgfecha_hoy;
    END IF

    -- // ############################################ //
    -- // #  OBTIENE NUMERO DE REGISTROS A PROCESAR  # //
    -- // ############################################ //
    SELECT COUNT(*)
      INTO vregproc
      FROM sc_maechq
     WHERE producto = vgProdCreciente
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgfecha_hoy);

    -- // ########################################################### //
    -- // #  Obtiene parametro de porcentajes de error por proceso  # //
    -- // ########################################################### //
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
       
    -- // OBTIENE RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentaini
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniCieInvCreComp5'; 
       
       
    -- // ######################################################################### //
    -- // #  FOREACH PRINCIPAL DEL CIERRE DE CAPTACION DE INVERSIONES CRECIENTES  # //
    -- // ######################################################################### //
    FOREACH principal WITH HOLD FOR
        SELECT mae.cuenta, mae.fecha_proceso, mae.producto, mae.sdo_actual, mae.status_cta, mae.sucursal,
               ins.instrucc, ins.cuentadep, nvl(noc.fecha_mod, vgfecha_hoy), nvl(noc.fecha_alta, vgfecha_hoy)
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vgstatus_cta, vSucursal,
               vginstrucc, vgcuentadep, vgfecha_mod, vgfecha_alta
          FROM sc_maechq mae,
               sc_maeinstrucc ins,
               sc_maenoc noc
         WHERE mae.producto = vgProdCreciente
           AND mae.status_cta <> '2'
           AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vgfecha_hoy )
           AND mae.cuenta >= vcuentaini
           AND ins.empresa = mae.empresa
           AND ins.cuenta = mae.cuenta
           AND ins.capint = 'R'
           AND ins.instrucc = '01'
           AND noc.empresa = mae.empresa
           AND noc.cuenta = mae.cuenta
           
        IF FechaProc IS NULL THEN
            IF vSdoActual = 0 THEN
                UPDATE sc_maechq
                   SET status_cta = "2",
                       fecha_proceso = vgfecha_hoy
                 WHERE empresa = pempresa
                   AND cuenta = vfcuenta;

                LET vcodret = "000";

                CONTINUE FOREACH;
            ELSE
                CALL creciente_proy_cierre(pempresa, vfcuenta, vProducto, vSdoActual, vginstrucc)
                RETURNING vcodret;

                IF vcodret <> "000" THEN
                    CONTINUE FOREACH;
                END IF
            END IF
        END IF

        -- // Actualiza la fecha como ya procesado si vencio su plazo
        IF vgfecha_mod < vgfecha_hoy THEN
            UPDATE sc_maechq
               SET fecha_proceso = vgprox_fecha
             WHERE empresa = pempresa
               AND cuenta = vfcuenta;

            CONTINUE FOREACH;
        END IF
        
        CALL cierrechq_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT COUNT(*)
              INTO vcontvalcie
              FROM sc_valcierre
             WHERE empresa = pempresa
               AND cuenta <> '';

            LET vregistros = ROUND(vregproc * vporcentajerror / 100);

            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                           'SET ejecutivo = '''||vgusuario||''','||
                           'status_proc   = '''||'C'||''','||
                           'codret        = '''||vcodret||''','||
                           'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                           'WHERE empresa = '''||pempresa||''' '||
                           'AND proceso   = '''||vproceso||''' '||
                           'AND fecha     = '''||vgfecha_hoy||''' '||
                           'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec5.sql';
                SYSTEM vsql;
                LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec5.sql';
                SYSTEM vstmt;
                RETURN vcodret;
            END IF;
        END IF;

        LET vfcuenta     = '';
        LET FechaProc    = '';
        LET vProducto    = '';
        LET vSdoActual   = 0.00;
        LET vgstatus_cta = ' ';
        LET vSucursal    = '';
        LET vgfecha_mod  = ' ';
        LET vgfecha_alta = ' ';
        LET vcontvalcie  = 0;
        LET vregistros   = 0;
        LET vginstrucc   = '';
        LET vgcuentadep  = '';
    END FOREACH;  
    
    
    -- // ############################ //
    -- // #  Registra fin de cierre  # //
    -- // ############################ //
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vgfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horacierrecrec5.sql';
    SYSTEM vsql;

    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horacierrecrec5.sql';
    SYSTEM vstmt;

    UPDATE sc_contproc
       SET fecha = vgfecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreinvcreccomp5";

    SET LOCK MODE TO NOT WAIT;

    RETURN vcodret;

    END;

END PROCEDURE

DOCUMENT
'DESCRIPCION:   Complemento 2 Cierre Diario del Producto de Inversion Creciente de Captacion ',
'EJECUTADO POR: Control-M',
'AUTOR:         JICS',
'FECHA:         20/Febrero/2013',
'VERSION:       1.00.0000',
'Base de Datos: bdicheq';

CREATE PROCEDURE "informix".cancelatarjeta_pba(pEmpresa CHAR(3),
                  pCuenta CHAR(20), pNumTarjeta CHAR(20),
                  pNumCte CHAR(20))

	RETURNING
	CHAR(5),MONEY(14,2); -- Codigo de retorno

	DEFINE vCodRet	  CHAR(5);
	DEFINE vActualizo INTEGER;
	DEFINE vSqlErr	  INTEGER;
        DEFINE vmonto_aut MONEY(14,2);

	LET vcodret    = "000";
	LET vActualizo = 0;
	LET vSqlErr    = 0;
        LET vmonto_aut = 0;

	BEGIN
		ON EXCEPTION SET vSqlErr
			IF vSqlErr <> 0 THEN
				LET vCodRet = vSqlErr;
				RETURN vCodRet,vmonto_aut;
			END IF;
		END EXCEPTION;


		-- ACTUALIZAR EL ESTADO DE LA TARJETA
		UPDATE
			bdicheq:sc_tarjeta
		SET
			status_tar = 'C'
		WHERE
			empresa = pEmpresa AND
			cuenta = pCuenta AND
			numcte = pNumCte AND
			num_tarjeta = pNumTarjeta;

		-- Regresa el Monto Autorizado de la Tarjeta
                SELECT limite_aut INTO vmonto_aut
                FROM   sc_tarjeta
		WHERE  empresa = pEmpresa AND
		       cuenta = pCuenta AND
		       numcte = pNumCte AND
		       num_tarjeta = pNumTarjeta;

                -- VERIFICAR SI SE CAMBIO EL ESTADO DE LA TARJETA
		SELECT
			1
		INTO
			vActualizo
		FROM
			bdicheq:sc_tarjeta
		WHERE
			empresa = pEmpresa AND
			cuenta = pCuenta AND
			numcte = pNumCte AND
			num_tarjeta = pNumTarjeta AND
			status_tar = 'C';


		IF vActualizo <> 1 THEN
			LET vCodRet = "254";
		END IF

		RETURN vCodRet,vmonto_aut;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_archivo_pagos_kelloggs(pEmpresa CHAR(3))
RETURNING CHAR(5);	

DEFINE cCodret            CHAR(5);
DEFINE cRutaArchivo	      CHAR(60);
DEFINE cNombreArchivo     CHAR(60);
DEFINE cDia				  CHAR(2);
DEFINE cMes				  CHAR(2);
DEFINE cAnio              CHAR(4);
DEFINE cFecha    		  CHAR(10);
DEFINE cFechaAnt		  CHAR(10);
DEFINE cFechaIni		  CHAR(60);
DEFINE cFechaFin		  CHAR(60);
DEFINE cEmpresa			  CHAR(3);
DEFINE cFolio			  CHAR(7);
DEFINE cCuenta 			  CHAR(11);
DEFINE cSucursal		  CHAR(4);
DEFINE cfechaEntrega      CHAR(19);
DEFINE cFechaApertura	  CHAR(10);
DEFINE cNombre1           CHAR(26);
DEFINE cNombre2           CHAR(26);
DEFINE cApellido1         CHAR(26);
DEFINE cApellido2         CHAR(26);
DEFINE cNombreSuc		  CHAR(40);	
DEFINE cNombreCompleto    CHAR(104);
DEFINE vsql 			  CHAR(1000);
DEFINE dFecha             DATE;
DEFINE dFechaIni          DATE;
DEFINE dFechaFin          DATE;
DEFINE dFechaAnt          DATE;
DEFINE iSql_err           INTEGER;

LET cCodret               = '00000';	
LET cRutaArchivo	      = '';
LET cNombreArchivo	      = '';
LET cDia	              = '';
LET cMes	              = '';
LET cAnio	              = '';
LET cFecha 				  = '';
LET cFechaAnt	          = '';
LET cFechaIni	          = '';
LET cFechaFin	          = '';
LET cEmpresa	          = '';
LET cFolio	              = '';
LET cCuenta 	          = '';
LET cSucursal	          = '';
LET cfechaEntrega	      = '';
LET cFechaApertura	      = '';
LET cNombre1	          = '';
LET cNombre2	          = '';
LET cApellido1	          = '';
LET cApellido2	          = '';	      
LET cNombreSuc	          = '';
LET cNombreCompleto	      = '';
LET vsql           	      = '';		      
LET iSql_err		      = 0;
LET dFecha                = DATE(1);
LET dFechaFin             = DATE(1);
LET dFechaIni             = DATE(1);
LET dFechaAnt             = DATE(1);

--SET DEBUG FILE TO '/tmp/sp_archivo_pagos_kelloggs.out';
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSql_err
		LET cCodret = CAST(iSql_err AS CHAR);    
		RETURN cCodret;
	END EXCEPTION;	

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	IF TRIM(NVL(pEmpresa,'')) <> '' THEN
		SELECT fecha_hoy INTO cFecha FROM "informix".sc_fechas WHERE empresa = pEmpresa;

		LET cDia = LPAD(DAY(cFecha),2,'0');
		IF TRIM(NVL(cDia,'')) <> '' THEN
			IF CAST(cDia AS INTEGER) >= 16 THEN 
				LET cDia = '16';
			ELSE
				LET cDia = '01';
			END IF;
		END IF;

		IF CAST(cDia AS INTEGER) = 1 OR CAST(cDia AS INTEGER) = 16 THEN
			LET cMes = LPAD(MONTH(cFecha),2,'0');
			LET cAnio = YEAR(cFecha);
			LET cFecha = cMes|| '/' || cDia ||'/' || cAnio;

			IF CAST(cDia AS INTEGER) = 1 THEN
				IF CAST(cMes AS INTEGER) = 1 THEN
					LET cFechaAnt =  '12/16/' || CAST(CAST(cAnio AS INTEGER) -1 AS CHAR);
				ELSE
					LET cFechaAnt =  LPAD(CAST(CAST(cMes AS INTEGER) -1 AS CHAR),2,'0') || '/16'|| '/' || cAnio ;
				END IF;	
			ELSE
				LET cFechaAnt = cMes || '/01' || '/' || cAnio ;
			END IF;
			LET dFechaAnt = cFechaAnt;

			SELECT TRIM(valor) INTO cRutaArchivo FROM "informix".sc_param WHERE empresa = pEmpresa AND codparam = 'ruta_rpt_kelloggs';
			SELECT TRIM(valor) INTO cNombreArchivo FROM "informix".sc_param WHERE empresa = pEmpresa AND codparam = 'nombre_rpt_kelloggs';
			SELECT TRIM(valor) INTO cFechaIni FROM "informix".sc_param WHERE empresa = pEmpresa AND codparam = 'Fecha_InicioKelloggs';
			SELECT TRIM(valor) INTO cFechaFin FROM "informix".sc_param WHERE empresa = pEmpresa AND codparam = 'Fecha_Fin_kelloggs';

			LET cDia = LPAD(SUBSTR(cFechaIni,9,2), 2, '0');
			LET cMEs = LPAD(SUBSTR(cFechaIni,6,2), 2, '0');
			LET cAnio = SUBSTR(cFechaIni,1,4); 
			LET cFechaIni = cMes|| '/' || cDia ||'/' || cAnio;

			LET cDia = LPAD(SUBSTR(cFechaFin,9,2), 2, '0');
			LET cMEs = LPAD(SUBSTR(cFechaFin,6,2), 2, '0');
			LET cAnio = SUBSTR(cFechaFin,1,4); 
			LET cFechaFin = cMes || '/' || cDia ||'/' || cAnio;

			LET dFecha = TRIM(cFecha);
			LET dFechaIni = TRIM(cFechaIni);
			LET dFechaFin = TRIM(cFechaFin);

			IF TRIM(NVL(cRutaArchivo,'')) <> '' AND TRIM(NVL(cNombreArchivo,'')) <> '' AND TRIM(NVL(cFechaIni ,'')) <> ''AND TRIM(NVL(cFechaFin,'')) <> '' THEN
				IF dFecha >= dFechaIni AND dFecha <= dFechaFin THEN
					LET cDia = LPAD(SUBSTR(cFecha,4,2), 2, '0');
					LET cMEs = LPAD(SUBSTR(cFecha,1,2), 2, '0');
					LET cAnio = SUBSTR(cFecha,7,4); 

					LET cNombreArchivo = REPLACE(cNombreArchivo,'aaaa',cAnio);
					LET cNombreArchivo = REPLACE(cNombreArchivo,'mm',cMes);
					LET cNombreArchivo = REPLACE(cNombreArchivo,'dd',cDia);

					LET vsql   = 'rm -f ' || TRIM(cRutaArchivo) ||  TRIM(cNombreArchivo);
					SYSTEM vsql;

					FOREACH
						SELECT empresa, folio, cuenta_abono, sucursal,fecha_entrega
						INTO cEmpresa, cFolio, cCuenta, cSucursal, cfechaEntrega
						FROM bdiprem:sc_promocion_kelloggs
						WHERE empresa =  pEmpresa AND entregado = '1' 
						AND fecha_entrega >= dFechaAnt AND fecha_entrega < dFecha

						LET cfechaEntrega= SUBSTR(cfechaEntrega,1,4) || LPAD(SUBSTR(cfechaEntrega,6,2),2,'0') || LPAD(SUBSTR(cfechaEntrega,9,2),2,'0') || SUBSTR(cfechaEntrega,11,9);

						IF TRIM(NVL(cEmpresa,'')) <> '' AND TRIM(NVL(cCuenta,'')) <> '' AND  TRIM(NVL(cCuenta,'')) <> '' THEN
							SELECT fecha_alta INTO cFechaApertura FROM "informix".sc_maenoc WHERE empresa = cEmpresa AND cuenta = cCuenta;

							LET cFechaApertura = YEAR(cFechaApertura) || LPAD(MONTH(cFechaApertura),2,'0') || LPAD(DAY(cFechaApertura),2,'0');

							SELECT nombre1, nombre2, apell_paterno, apell_materno 
							INTO cNombre1, cNombre2, cApellido1, cApellido2
							FROM bdinteg:"informix".si_cliente 
							WHERE empresa = cEmpresa 
							AND numcte = (SELECT num_cte FROM "informix".sc_maechq WHERE empresa = cEmpresa AND cuenta = cCuenta);

							SELECT nombre INTO cNombreSuc FROM bdinteg:"informix".si_sucursales WHERE empresa = cEmpresa AND sucursal = cSucursal;

							IF TRIM(NVL(cNombre1,'')) <> '' AND TRIM(NVL(cApellido1,'')) <> '' AND TRIM(NVL(cNombreSuc,'')) <> '' THEN
								LET cNombreCompleto = TRIM(TRIM (cNombre1) ||' '|| TRIM(cNombre2)) ||' '|| TRIM(TRIM(cApellido1) || ' ' || TRIM(cApellido2));

								LET vsql = 'echo "' || '|' || TRIM(cFolio) || '|' || TRIM(cfechaEntrega) || '|' || TRIM(cCuenta) || '|' || TRIM(cNombreCompleto) || '|' || TRIM(cFechaApertura) || '|' || TRIM(cSucursal) || '|' || TRIM(cNombreSuc) || '|' || '" >> ' || TRIM(cRutaArchivo) || TRIM(cNombreArchivo);
								SYSTEM vsql;

								LET cCodret = '00000';
							ELSE
								LET cCodret = '00001';
							END IF;	
						ELSE
							LET cCodret = '00001';
						END IF;
					END FOREACH;

					IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
						LET vsql = 'echo "" >> ' || TRIM(cRutaArchivo) || TRIM(cNombreArchivo);
						SYSTEM vsql;	
					END IF;
				ELSE
					LET cCodret = '00001';
				END IF;
			ELSE
				LET cCodret = '00001';
			END IF;
		ELSE
			LET cCodret = '00001';
		END IF;
	ELSE
		LET cCodret = '00001';
	END IF;
	RETURN cCodret;	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCIÓN: se creo para realizar un reporte con los folios kelloggs pemiados ya cobrados',
'AUTOR : Felipe Urias',
'FECHA : 11/07/2013',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_portabregistrapagoprogramado_pba (pUsuario CHAR(8))
RETURNING  CHAR(5);
    
    DEFINE cCodRet 							CHAR(5);
    DEFINE cCodRet2							CHAR(5);
    DEFINE iSqlErr							INTEGER;
    DEFINE cEmpresaEmpleado					CHAR(5);
    DEFINE cNumCliente						CHAR(20);
    DEFINE cCuentaOrigen					CHAR(20);
    DEFINE iSecuencia						INTEGER;
    DEFINE cBancoDestino					CHAR(3);
    DEFINE cCuentaDestino					CHAR(20);
    DEFINE cTarjetaDestino					CHAR(20);
    DEFINE cFechaDeposito					CHAR(60);
    DEFINE cEstatus							CHAR(2);
    DEFINE mMontoTotal						MONEY (16,2);
    DEFINE cFolioSuc						CHAR(16);
    DEFINE mSdoDisponible					MONEY (16,2);
    DEFINE dFechaHoy						DATE;
    DEFINE dFechaHoyMov						DATE;
    DEFINE dFechaHoyAnt						DATE;
    DEFINE cConsecutivoCentral				CHAR(8);
    DEFINE cFolioPortabilidad				CHAR(18);
    DEFINE cTransaccUsada					CHAR(4);
    DEFINE cMensaje							CHAR(100);
    DEFINE iCantidadFallos					INTEGER;
    DEFINE iCantidadTomados					INTEGER;
    DEFINE cHoraCierreSPEI					DATETIME HOUR TO SECOND;
    DEFINE cHoraActualServidor				DATETIME HOUR TO SECOND;
    DEFINE cMensajeProcesos					CHAR(250);
    DEFINE cIDClabeOTarjeta					CHAR(2);
    DEFINE cTelefonoCelCte					CHAR(13);
    
    LET cCodRet 			= '00000';
    LET cCodRet2 			= '00000';
    LET iSqlErr				= 0;
    LET cEmpresaEmpleado	= '';
    LET cNumCliente			= '';
    LET cCuentaOrigen		= '';
    LET iSecuencia			= 0;
    LET cBancoDestino		= '';
    LET cIDClabeOTarjeta	= '';
    LET cCuentaDestino		= '';
    LET cTarjetaDestino		= '';
    LET cFechaDeposito		= '';
    LET cEstatus			= '';
    LET mMontoTotal			= 0.00;
    LET cFolioSuc			= '';
    LET mSdoDisponible		= 0.00;
    LET dFechaHoy			= '';
    LET dFechaHoyMov		= '';
    LET dFechaHoyAnt		= '';
    LET cConsecutivoCentral	= '';
    LET cFolioPortabilidad	= '';
    LET cTransaccUsada		= '';
    LET cMensaje			= '';
    LET iCantidadFallos		= 0;
    LET iCantidadTomados	= 0;
    LET cHoraCierreSPEI		= '';
    LET cHoraActualServidor	= '';
    LET cMensajeProcesos	= '';
    LET cTelefonoCelCte		= '';
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr
        IF iSqlErr != 0 THEN
            LET cCodRet= iSqlErr;
            LET cMensaje = 'OCURRIO UN ERROR INESPERADO';
            IF cConsecutivoCentral IS NULL OR cConsecutivoCentral = '' THEN
                LET cConsecutivoCentral = '0';
            END IF;
            CALL bdicheq:sp_PortabRegistraEjecucion('sp_PortabRegistraPagoProgramado', dFechaHoyMov, cCodRet, cMensaje ,cConsecutivoCentral) 
            RETURNING cCodRet2,cMensajeProcesos;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;

    SET DEBUG FILE TO "./sp_PortabRegistraPagoProgramado.trc";
    TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- Obtiene la fecha del sistema de cheques.
    SELECT fecha_hoy 
      INTO dFechaHoy
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';

    LET dFechaHoyMov = dFechaHoy;

    -- Valida que exista el usuario.
    IF NOT EXISTS (SELECT 1 FROM bdinteg:si_ejecut WHERE ejecutivo = pUsuario)  THEN
        LET cCodRet = '00001';
        LET cMensaje = 'EL USUARIO NO SE ENCUENTRA REGISTRADO';
        IF cConsecutivoCentral IS NULL OR cConsecutivoCentral = '' THEN
            LET cConsecutivoCentral = '0';
        END IF;
        CALL bdicheq:sp_PortabRegistraEjecucion('sp_PortabRegistraPagoProgramado', dFechaHoyMov, cCodRet, cMensaje ,cConsecutivoCentral) 
        RETURNING cCodRet2,cMensajeProcesos;
        RETURN cCodRet;
    END IF;

    -- Valida si la fecha hoy es hábil
    CALL bdidomi:sp_ValFeriadoBanca('001',dFechaHoy,0,'S') 
    RETURNING cCodRet2,dFechaHoyAnt;

    IF cCodRet2 <> 0 THEN
        -- Si no es hábil asigna la siguiente fecha hábil.
        CALL bdidomi:sp_ValFeriadoBanca('001',dFechaHoy,1,'S') 
        RETURNING cCodRet2,dFechaHoyAnt;

        IF cCodRet2 = 0 THEN
            LET dFechaHoy = dFechaHoyAnt;
        ELSE
            LET cCodRet = '00002';
            LET cMensaje = 'SE TUVO PROBLEMAS AL INTENTAR OBTENER LA FECHA PROXIMA';
            IF cConsecutivoCentral IS NULL OR cConsecutivoCentral = '' THEN
                LET cConsecutivoCentral = '0';
            END IF;
            CALL bdicheq:sp_PortabRegistraEjecucion('sp_PortabRegistraPagoProgramado', dFechaHoyMov, cCodRet, cMensaje ,cConsecutivoCentral) 
            RETURNING cCodRet2,cMensajeProcesos;
            RETURN cCodRet;
        END IF;
    END IF;

    --Consulta la hora de cierre para SPEI.
    SELECT TRIM(valor) 
      INTO cHoraCierreSPEI
      FROM bdicheq:sc_param
     WHERE codparam = 'PORTAHORACIERRE';

    LET cHoraActualServidor = CURRENT HOUR TO SECOND;

    -- Si la hora es mayor a la parametrizada, se programa el pago al siguiente día hábil de lunes a viernes.
    IF cHoraActualServidor >= cHoraCierreSPEI THEN
        -- Si no es hábil asigna la siguiente fecha hábil.
        CALL bdidomi:sp_ValFeriadoBanca('001',dFechaHoy,1,'S') 
        RETURNING cCodRet2,dFechaHoyAnt;

        IF cCodRet2 = 0 THEN
            LET dFechaHoy = dFechaHoyAnt;
        ELSE
            LET cCodRet = '00002';
            LET cMensaje = 'SE TUVO PROBLEMAS AL INTENTAR OBTENER LA FECHA PROXIMA';
            IF cConsecutivoCentral IS NULL OR cConsecutivoCentral = '' THEN
                LET cConsecutivoCentral = '0';
            END IF;
            CALL bdicheq:sp_PortabRegistraEjecucion('sp_PortabRegistraPagoProgramado', dFechaHoyMov, cCodRet, cMensaje ,cConsecutivoCentral) 
            RETURNING cCodRet2,cMensajeProcesos;
            RETURN cCodRet;
        END IF;
    END IF;

    -- Consulta si el proceso ya se ejecutó ya que este es diario y si no existe ejecución registrada se inicializará.
    IF EXISTS (SELECT 1 FROM bdicheq:sc_portabitacora WHERE proceso = 'sp_PortabRegistraPagoProgramado' AND  fecha_ejec = dFechaHoyMov ) THEN
        -- Asigna una referencia o clave.
        SELECT (TRIM(valor) + 1)::INTEGER
          INTO cConsecutivoCentral
          FROM bdicheq:sc_param
         WHERE codparam = 'PORTACONSEC';
         
        LET cConsecutivoCentral = LPAD(NVL(TRIM(cConsecutivoCentral),'0'),8,'0');
    ELSE
        -- Asigna una referencia o clave.
        LET cConsecutivoCentral = '00000001';	
        
        UPDATE bdicheq:sc_param 
           SET valor = cConsecutivoCentral
         WHERE codparam = 'PORTACONSEC';
    END IF;

    FOREACH WITH HOLD
        -- Consulta que existan cuentas con su portabilidad activa y Consulta el movimiento diario.
        SELECT PN.empresa, PN.cliente, PN.cuenta_abono, PN.secuencia, PN.banco_ref, PN.cuenta_ref, 
               PN.tarjeta_ref, PN.fecha_deposito, PN.estatus,MV.monto_tot, MV.folio_suc, MV.transacc
          INTO cEmpresaEmpleado, cNumCliente, cCuentaOrigen, iSecuencia, cBancoDestino, cCuentaDestino, 
               cTarjetaDestino, cFechaDeposito, cEstatus,mMontoTotal, cFolioSuc, cTransaccUsada
          FROM bdicheq:sc_portabilidadnomina AS PN
         INNER JOIN bdicheq:sc_portaestatus AS PE ON (PN.estatus = PE.estatus)
         INNER JOIN bdicheq:sc_movdia AS MV ON (PN.cuenta_abono = MV.cuenta) AND (fech_alt = dFechaHoyMov)
         INNER JOIN bdicheq:sc_portatransacc AS PT ON (MV.transacc = PT.transacc)
         WHERE PN.estatus =  '01'

        LET iCantidadTomados = iCantidadTomados + 1;

        -- Si no se obtuvo el movimiento.
        IF  mMontoTotal IS NULL OR  cFolioSuc IS NULL OR cFolioSuc = '' OR cTransaccUsada IS NULL OR cTransaccUsada = '' THEN
            LET cMensaje = 'NO SE OBTUVO INFORMACIÓN DE LOS MOVIMIENTOS DIARIOS';
            LET iCantidadFallos = iCantidadFallos + 1;
            CONTINUE FOREACH;
        END IF;

        -- Consulta el saldo de la cuenta origen.
        SELECT sdo_actual-(sdo_cong + sdo_retenido)
          INTO mSdoDisponible
          FROM bdicheq:sc_maechq 
         WHERE empresa = '001'
           AND cuenta = cCuentaOrigen;

        IF mMontoTotal < mSdoDisponible THEN
            LET mSdoDisponible = mMontoTotal;
        END IF;

        -- Obtiene la fecha del sistema de cheques.
        SELECT fecha_hoy 
          INTO dFechaHoy
          FROM bdicheq:sc_fechas
         WHERE empresa = '001';

        LET cHoraActualServidor = CURRENT HOUR TO SECOND;

        -- Si la hora es mayor a la parametrizada, se programa el pago al siguiente día hábil de lunes a viernes.
        IF cHoraActualServidor >= cHoraCierreSPEI THEN
            -- Si no es hábil asigna la siguiente fecha hábil.
            CALL bdidomi:sp_ValFeriadoBanca('001',dFechaHoy,1,'S') 
            RETURNING cCodRet2,dFechaHoyAnt;

            IF cCodRet2 = 0 THEN
                LET dFechaHoy = dFechaHoyAnt;
            ELSE
                LET cCodRet = '00002';
                LET cMensaje = 'SE TUVO PROBLEMAS AL INTENTAR OBTENER LA FECHA PROXIMA';
                IF cConsecutivoCentral IS NULL OR cConsecutivoCentral = '' THEN
                    LET cConsecutivoCentral = '0';
                END IF;
                CALL bdicheq:sp_PortabRegistraEjecucion('sp_PortabRegistraPagoProgramado', dFechaHoyMov, cCodRet, cMensaje ,cConsecutivoCentral) 
                RETURNING cCodRet2,cMensajeProcesos;
                RETURN cCodRet;
            END IF;
        END IF;

        -- Asignación de referencia o fólio.
        LET cFolioPortabilidad = 'PN' || LPAD(YEAR(dFechaHoy),4,'0')||LPAD(MONTH(dFechaHoy),2,'0')|| LPAD(DAY(dFechaHoy),2,'0')||cConsecutivoCentral;

        IF cCuentaDestino <> '' AND LENGTH(cCuentaDestino) = 18 AND  SUBSTR(cCuentaDestino,1,3) = cBancoDestino THEN
            LET cIDClabeOTarjeta = '02';
        ELIF cTarjetaDestino <> '' THEN
            LET cIDClabeOTarjeta = '03';
            LET cCuentaDestino = cTarjetaDestino;
        END IF;

        -- Obtiene el teléfono celular del cliente.
        SELECT telefono 
          INTO cTelefonoCelCte 
          FROM bdinteg:si_telefonos_actual
         WHERE numcte = cNumCliente 
           AND tipo_tel = '2';

        -- Valida si el teléfono se obtuvo si no se obtiene se envía un 0
        IF cTelefonoCelCte IS NULL OR cTelefonoCelCte = '' THEN
            LET cTelefonoCelCte = '0';
        END IF;

        -- Consulta que el movimiento no exista.
        IF EXISTS ( SELECT 1 FROM bdicheq:sc_portamovtos WHERE cliente = cNumCliente AND cuenta_cargo = cCuentaOrigen 
                    AND banco_ref = cBancoDestino AND transaccion = cTransaccUsada AND fecha_envio = dFechaHoy AND estatus = '01' AND folio_suc = cFolioSuc ) THEN
            LET iCantidadFallos = iCantidadFallos + 1; 
            CONTINUE FOREACH;   
        END IF;

        -- Reliza la programación de los pagos.
        CALL bdiprog:sp_altaprogramacion(cNumCliente, cFolioPortabilidad, '07', '01', cCuentaOrigen, cIDClabeOTarjeta, cCuentaDestino, cBancoDestino, cFolioPortabilidad,
                                         cConsecutivoCentral::INTEGER, '0', mSdoDisponible, '', '0.00', '01', 'PORTABILIDAD DE NÓMINA', dFechaHoy, '02', 1, dFechaHoy,
                                         '04', '00', '0', '0', '0', '0', '0', '0', '0', '0', '05', '00', '', '0', cTelefonoCelCte, '00', '', '0', '', '', '0', pUsuario)
        RETURNING cCodRet2,cMensajeProcesos;

        IF cCodRet2 = 0 THEN
            -- Registra el movimiento de portabilidad.		
            INSERT INTO bdicheq:sc_portamovtos 
            (referencia1,empresa,cliente,cuenta_cargo,banco_ref,cuenta_ref,tarjeta_ref,monto_enviar,
             monto_nomina,transaccion,fecha_envio,fecha_recibido,estatus,folio_suc,user_insert,fecha_insert)
            VALUES 	
            (cFolioPortabilidad,cEmpresaEmpleado,cNumCliente,cCuentaOrigen,cBancoDestino,cCuentaDestino,cTarjetaDestino,mSdoDisponible,
             mMontoTotal,cTransaccUsada,dFechaHoy,dFechaHoyMov,'01',cFolioSuc,pUsuario,dFechaHoyMov);

            -- Actualiza el parámetro que utilizó
            UPDATE bdicheq:sc_param 
               SET valor = cConsecutivoCentral::INTEGER 
             WHERE codparam = 'PORTACONSEC';

            -- Obtiene el parámetro.
            SELECT TRIM(valor) :: INTEGER + 1
              INTO cConsecutivoCentral
              FROM bdicheq:sc_param
             WHERE codparam = 'PORTACONSEC';
             
            LET cConsecutivoCentral = LPAD(NVL(TRIM(cConsecutivoCentral),'0'),8,'0');
            LET cMensaje = 'PROCESO EXITOSO';

        -- Consulta si se obtuvo el saldo y si es menor a cero no se procesa la cuenta o si el proceso generó un error.
        ELIF cCodRet2 <> 0 OR mSdoDisponible IS NULL OR mSdoDisponible <= 0.00 THEN
            LET cMensaje = 'EN AL MENOS UNA CUENTA NO SE REALIZO SU PROGRAMACIÓN DE PAGOS';
            LET iCantidadFallos = iCantidadFallos + 1;

            -- Registra el movimiento de portabilidad.	
            INSERT INTO bdicheq:sc_portamovtos 
            (referencia1,empresa,cliente,cuenta_cargo,banco_ref,cuenta_ref,tarjeta_ref,monto_enviar,
             monto_nomina,transaccion,fecha_envio,fecha_recibido,estatus,folio_suc,user_insert,fecha_insert)
            VALUES 	
            (cFolioPortabilidad,cEmpresaEmpleado,cNumCliente,cCuentaOrigen,cBancoDestino,cCuentaDestino,cTarjetaDestino,mSdoDisponible,
             mMontoTotal,cTransaccUsada,dFechaHoy,dFechaHoyMov,'01',cFolioSuc,pUsuario,dFechaHoyMov);

            -- Actualiza el parámetro que utilizó
            UPDATE bdicheq:sc_param 
               SET valor = cConsecutivoCentral::INTEGER 
             WHERE codparam = 'PORTACONSEC';

            -- Obtiene el parámetro.
            SELECT TRIM(valor) :: INTEGER + 1
              INTO cConsecutivoCentral
              FROM bdicheq:sc_param
             WHERE codparam = 'PORTACONSEC';
             
            LET cConsecutivoCentral = LPAD(NVL(TRIM(cConsecutivoCentral),'0'),8,'0');
            
            IF mSdoDisponible IS NULL OR mSdoDisponible <= 0.00 THEN
                LET cMensaje =  'EN AL MENOS UNA CUENTA TUVO PROBLEMAS EN SU SALDO';
            END IF;
            
            CONTINUE FOREACH;
        END IF;	
    END FOREACH
    
    IF iCantidadTomados - iCantidadFallos = 0 THEN
        LET cMensaje = 'NO SE ENCONTRO INFORMACIÓN POR PROCESAR';
        LET cConsecutivoCentral = 1;
    END IF;
    
    IF cConsecutivoCentral IS NULL OR cConsecutivoCentral = '' THEN
        LET cConsecutivoCentral = '1';
    END IF;
    
    CALL bdicheq:sp_PortabRegistraEjecucion('sp_PortabRegistraPagoProgramado', dFechaHoyMov, cCodRet, cMensaje ,cConsecutivoCentral - 1) 
    RETURNING cCodRet2,cMensajeProcesos;		
    
    RETURN cCodRet;
    
    END
    
END PROCEDURE

Document
'DESCRIPCION: Proceso que registra la programación de los pagos con base a un movimiento diario,', 
'			  registra el pago programado y genera el movimiento de portabilidad.',
'AUTOR: Antonio Bastidas',
'FECHA: 08/06/2010',
'VERSION: 20100618.1855',
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_cce_consultar_chequespresentados_pba
(
pEmpresa    CHAR(3),
pFecha      CHAR(8),
pNomArchivo CHAR(22)
)
RETURNING
	CHAR(6) 		AS cod_ret,
	CHAR(3) 		AS banco,
	CHAR(40) 		AS nom_banco,
	CHAR(40) 		AS referencia,
	INTEGER 		AS num_cheque,
	DECIMAL(14,2) 	AS monto_orig,
	CHAR(20) 		AS cuenta,
	CHAR(44) 		AS sucursal,
	CHAR(4) 		AS transacc
	
	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet			CHAR(6);

	
	DEFINE cBanco			CHAR(3);
	DEFINE cNomBanco		CHAR(40);
	DEFINE cReferencia		CHAR(40);
	DEFINE iNumCheque		INTEGER;
	DEFINE dMontoOrig		DECIMAL(14,2);
	DEFINE cCuenta			CHAR(20);
	DEFINE cSucursal		CHAR(44);
	DEFINE cTransacc		CHAR(4);



	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo			= "";
	LET cCodRet             = "000000";
	
	LET cBanco				= "";
	LET cNomBanco			= "";
	LET cReferencia			= "";
	LET iNumCheque			= 0;
	LET dMontoOrig			= 0.0;
	LET cCuenta				= "";
	LET cSucursal			= "";
	LET cTransacc			= "";


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc WITH RESUME;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
--	SET DEBUG FILE TO '/respaldosbd/has/sp_cce_consultar_chequespresentados.out';
--	TRACE ON;



	IF NVL(pEmpresa,"") = "" OR NVL(pFecha,"") = "" OR NVL(pNomArchivo,"") = "" THEN
        -- FALTAN UNO O MAS PARAMETROS
        LET cCodRet = "000001";
		RETURN cCodRet, cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc WITH RESUME;
	ELSE
        FOREACH WITH HOLD
			SELECT ba.banco, ba.descripcion, doc.referencia, doc.num_chq, doc.monto_ori, doc.cuenta, suc.sucursal || " " || suc.nombre,doc.transacc  
			INTO cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc
			FROM bdicheq:sc_docret_sbc doc, 
                 bdinteg:si_bancos ba, 
                 bdinteg:si_sucursales suc, 
                 bditef:cce_detalle cce
			WHERE doc.empresa = pEmpresa
			AND doc.banco = ba.banco  
			AND doc.sucursal = suc.sucursal  
			AND doc.transacc IN (SELECT transacc FROM bditef:cce_mapeo_cecoban)  
			AND doc.cancelado = "T"
			AND doc.banco = cce.bco_receptor
			AND doc.numcuenta::INT8 = cce.num_cuenta::INT8
			AND doc.num_chq = cce.num_cheque::INTEGER
            AND doc.cuenta = cce.cuenta_dep
			AND cce.fecha_transfer = pFecha  
			AND cce.cod_operacion = "40"
			AND cce.nombrearchivo= pNomArchivo
		
            RETURN cCodRet, cBanco, cNomBanco, cReferencia, iNumCheque, dMontoOrig, cCuenta, cSucursal, cTransacc WITH RESUME;
        END FOREACH 	
    
	END IF
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso que consulta los cheques presentados a la cámara de compensación eletrónica',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Octubre 2012',
'VERSION: 20121026.1305';

CREATE PROCEDURE "informix".reverso_atm( psucursal CHAR(4),   --- Sucursal
                                         pfolio    CHAR(16) ) --- Folio Operacion
RETURNING CHAR(5); --- Codigo de Retorno

    DEFINE vcCodRet1    CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE viDescErr    CHAR(50);
    DEFINE viEnTransac  SMALLINT;
    DEFINE viReversado  SMALLINT;
    DEFINE vcCodRetRev  CHAR(5);
    
    LET vcCodRet1   = '00000';
    LET vcCodRet2   = '';
    LET vcCodRet3   = '';
    LET viSqlErr    = 0;
    LET viIsamErr   = 0;
    LET viDescErr   = 0;
    LET viEnTransac = 0;
    LET viReversado = 0;
    LET vcCodRetRev = '';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/reverso_atm.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, viDescErr
        SET DEBUG FILE TO '/resplogifx/conciliachq/reverso_atm.err';
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet1  = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = viDescErr;
            IF viEnTransac = 1 then
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF
            LET vcCodRet1 = '00999';
            RETURN vcCodRet1;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET viEnTransac = 1;
    END EXCEPTION WITH resume;

    IF viEnTransac = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;    
    
    IF ( psucursal is null OR psucursal = '' OR LENGTH(psucursal) <> 4 ) OR
       ( pfolio is null OR pfolio = '' OR LENGTH(pfolio) <> 16 ) THEN
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        LET vcCodRet1 = '00110';
        RETURN vcCodRet1;
    END IF;
    
    SELECT COUNT(*)
      INTO viReversado
      FROM bdicheq:"informix".sc_movdia
     WHERE cancelad = 'S'
       AND folio_suc = pfolio;
       
    IF viReversado > 0 THEN
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        LET vcCodRet1 = '00005';
        RETURN vcCodRet1;
    END IF;
    
    EXECUTE PROCEDURE bdicheq:reversion('001', psucursal, 'informix', pfolio, 'A')
    INTO vcCodRetRev;
    
    IF vcCodRetRev <> '000' THEN
        IF vcCodRetRev = '413' THEN
            LET vcCodRet1 = '00413';
        END IF;
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vcCodRet1;
    END IF;
    
    IF viEnTransac = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK; 
    END IF;
    
    END;
    
    RETURN vcCodRet1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_modctastraspasadas( pempresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;

    DEFINE vcodret1         char(5);
    DEFINE vcodret2         char(5);
    DEFINE vcodret3         char(50);
    DEFINE sql_err          integer;
    DEFINE isam_err         integer;
    DEFINE desc_err         char(50);
    DEFINE vcontador1       integer;
    DEFINE vcontador2       integer;
    DEFINE ven_transacc     smallint;
    DEFINE vcomienza        smallint;
    
    DEFINE vsql             char(600);
    DEFINE vstmt            char(300);
    DEFINE vfecha_hoy       date;
    DEFINE vfecha_ant       date;
    DEFINE vmes_actual      char(2);
    DEFINE vmes_siguiente   char(2);
    DEFINE vaniomes         char(6);
    DEFINE vaniomes2        char(6);
    DEFINE vanio            char(4);
    DEFINE vdia             char(2);
    DEFINE vdia2            char(2);
    DEFINE vmes             char(2);
    DEFINE vprodcrec        char(4);
    DEFINE vcuenta          char(20);
    DEFINE vsucursal        char(4);
    DEFINE vsdo_dia_ant     decimal(18,2);
    DEFINE vimp_chq_sbg     decimal(18,2);
    DEFINE vint_acum        decimal(18,2);
    DEFINE vacum_sdo_int    decimal(18,2);
    DEFINE vproducto        char(4);
    DEFINE vstatus_cta      char(1);
    DEFINE vfecha_proceso   date;
    DEFINE vfec_ult_mov     date;
    DEFINE vsdo_actual      decimal(18,2);
    DEFINE vnum_cte         char(20);
    DEFINE vejecutivo       char(8);
    
    LET vcodret1       = "000";               
    LET vcodret2       = '000';
    LET vcodret3       = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
    LET sql_err        = 0;                   
    LET isam_err       = 0;
    LET desc_err       = '';
    LET vcontador1     = 0;                   
    LET vcontador2     = 0;
    LET ven_transacc   = 0;                   
    LET vcomienza      = -1;  
         
    LET vsql           = '';                  
    LET vstmt          = '';
    LET vfecha_hoy     = '';                  
    LET vfecha_ant     = '';                    
    LET vmes_actual    = 0;                   
    LET vmes_siguiente = 0;                 
    LET vaniomes       = '';   
    LET vaniomes2      = '';    
    LET vdia           = '';     
    LET vdia2          = '';     
    LET vmes           = '';                  
    LET vanio          = '';    
    LET vprodcrec      = '';    
    LET vcuenta        = '';    
    LET vsucursal      = '';    
    LET vsdo_dia_ant   = 0;              
    LET vimp_chq_sbg   = 0;              
    LET vint_acum      = 0;              
    LET vacum_sdo_int  = 0;              
    LET vproducto      = '';    
    LET vstatus_cta    = '';    
    LET vfecha_proceso = '';    
    LET vfec_ult_mov   = '';    
    LET vsdo_actual    = 0;              
    LET vnum_cte       = '';    
    LET vejecutivo     = '';    
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_modctastraspasadas.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_modctastraspasadas.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy, fecha_ant
      INTO vfecha_hoy, vfecha_ant
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    LET vmes_actual    = LPAD(MONTH(vfecha_ant), 2, '0');
    LET vmes_siguiente = LPAD(MONTH(vfecha_hoy), 2, '0');
    LET vaniomes       = YEAR(vfecha_ant)||LPAD(MONTH(vfecha_ant), 2, '0');
    LET vdia           = DAY(vfecha_ant);
    LET vmes           = LPAD(MONTH(vfecha_ant), 2, '0');
    LET vanio          = YEAR(vfecha_ant);
    LET vaniomes2      = YEAR(vfecha_ant - 1 UNITS DAY)||LPAD(MONTH(vfecha_ant - 1 UNITS DAY), 2, '0');
    LET vdia2          = DAY(vfecha_ant - 1 UNITS DAY);
     
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctastraspasadas') THEN
        DROP TABLE "informix".ctastraspasadas;
    END IF;
    
    CREATE RAW TABLE "informix".ctastraspasadas
      ( 
        cuenta char(20) not null 
      ) 
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctatraspasada ON "informix".ctastraspasadas(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/cuentas_traspasar_28112013.unl INSERT INTO ctastraspasadas" > /resplogifx/conciliachq/ctastrasp.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctastrasp.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctastraspasadas;
    
    SELECT valor
      INTO vprodcrec
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PRODCREC';
    
    FOREACH WITH HOLD
        SELECT cta.cuenta, chq.sucursal, chq.sdo_dia_ant, chq.imp_chq_sbg, noc.int_acum, noc.acum_sdo_int, chq.producto, 
               chq.status_cta, chq.fecha_proceso, chq.fec_ult_mov, chq.sdo_actual, chq.num_cte, noc.ejecutivo
          INTO vcuenta, vsucursal, vsdo_dia_ant, vimp_chq_sbg, vint_acum, vacum_sdo_int, vproducto, 
               vstatus_cta, vfecha_proceso, vfec_ult_mov, vsdo_actual, vnum_cte, vejecutivo
          FROM ctastraspasadas cta,
               sc_maechq chq, 
               sc_maenoc noc
         WHERE cta.cuenta = chq.cuenta
           AND chq.producto != vprodcrec 
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
           AND noc.fecha_alta < vfecha_hoy
    
        BEGIN WORK;
        LET ven_transacc = 1;
           
        IF vimp_chq_sbg < 0 THEN
            LET vimp_chq_sbg = vimp_chq_sbg * -1;
        END IF
        
        LET vsdo_dia_ant = vsdo_dia_ant - vimp_chq_sbg;
        
        -- // Actualiza tabla de saldos diarios y provisiones no capitalizadas..        
        CALL sp_actsdodiarioc(vcuenta, vaniomes, vsucursal, vsdo_dia_ant, vint_acum, vdia, vaniomes2, vdia2) 
        RETURNING vcodret1;
        
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    FOREACH WITH HOLD
        SELECT cta.cuenta, chq.sucursal, chq.sdo_dia_ant, chq.imp_chq_sbg, noc.int_acum, noc.acum_sdo_int,
               chq.producto, chq.status_cta, chq.fecha_proceso, chq.fec_ult_mov, chq.sdo_actual, chq.num_cte, noc.ejecutivo
          INTO vcuenta, vsucursal, vsdo_dia_ant, vimp_chq_sbg, vint_acum, vacum_sdo_int,
               vproducto, vstatus_cta, vfecha_proceso, vfec_ult_mov, vsdo_actual, vnum_cte, vejecutivo
          FROM ctastraspasadas cta,
               sc_maechq chq, 
               sc_maenoc noc
         WHERE cta.cuenta = chq.cuenta
           AND ( ( chq.producto = vprodcrec AND chq.status_cta != '2' AND chq.fecultdep < vfecha_hoy ) OR
                 ( chq.producto = vprodcrec AND chq.status_cta  = '2' AND chq.fecha_proceso >= vfecha_ant AND chq.fecultdep < vfecha_hoy ) OR
                 ( chq.producto = vprodcrec AND chq.status_cta  = '2' AND chq.fecha_proceso is null AND chq.fec_ult_mov >= vfecha_ant AND chq.fecultdep < vfecha_hoy ) )
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
        
        BEGIN WORK;
        LET ven_transacc = 1;
        
        IF vimp_chq_sbg < 0 THEN
            LET vimp_chq_sbg = vimp_chq_sbg * -1;
        END IF
        
        LET vsdo_dia_ant = vsdo_dia_ant - vimp_chq_sbg;
        
        IF ( vproducto = vprodcrec AND vstatus_cta = '2' AND vfecha_proceso = vfecha_ant ) OR
           ( vproducto = vprodcrec AND vstatus_cta = '2' AND vfecha_proceso is null AND vfec_ult_mov = vfecha_ant ) THEN
            LET vsdo_dia_ant = vsdo_actual;
        END IF;
        
        -- // Actualiza tabla de saldos diarios y provisiones no capitalizadas..        
        CALL sp_actsdodiarioc(vcuenta, vaniomes, vsucursal, vsdo_dia_ant, vint_acum, vdia, vaniomes2, vdia2) 
        RETURNING vcodret1;
        
        LET vcontador1 = vcontador1 + 1;
        
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".actualiza_ctasnoproc( pEmpresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), INTEGER;
       
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE vcTrxAbierta SMALLINT;
    DEFINE viContador   INTEGER;
    DEFINE vdFechaHoy   DATE;
    DEFINE vcCuenta     CHAR(20);
    
    LET viSqlErr     = 0;
    LET viIsamErr    = 0;
    LET vcDescErr    = '';
    LET vcCodRet     = '000';
    LET vcCodRet2    = '000';
    LET vcCodRet3    = '';
    LET vcTrxAbierta = 0;
    LET viContador   = 0;
    LET vdFechaHoy   = '';
    LET vcCuenta     = '';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/actualiza_ctasnoproc.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/actualiza_ctasnoproc.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            IF vcTrxAbierta = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcCodRet, vcCodRet2, viContador;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vdFechaHoy
      FROM sc_fechas
     WHERE empresa = pEmpresa;
    
    FOREACH WITH HOLD
        SELECT cuenta
          INTO vcCuenta
          FROM sc_valcierre
         WHERE empresa = pEmpresa
           AND cuenta >= '10000000000'
           
        BEGIN WORK;
        LET vcTrxAbierta = 1;
           
        UPDATE sc_maechq
           SET fecha_proceso = vdFechaHoy,
               sdo_dia_ant = sdo_actual
         WHERE empresa = pEmpresa
           AND cuenta = vcCuenta;
           
        IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
            ROLLBACK WORK;
            LET vcTrxAbierta = 0;
        ELSE
            COMMIT WORK;
            LET vcTrxAbierta = 0;
        END IF;
           
        LET viContador = viContador + 1;
    END FOREACH;
    
    RETURN vcCodRet, vcCodRet2, viContador;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".actualiza_ctasnoproc_comp( pEmpresa CHAR(3) )
