    LET viSqlErr     = 0;
    LET viIsamErr    = 0;
    LET vcDescErr    = '';
    LET vcCodRet     = '000';
    LET vcCodRet2    = '000';
    LET vcCodRet3    = '';
    LET vcTrxAbierta = 0;
    LET viContador   = 0;
    
    LET vfecha_hoy     = ''; 
    LET vfecha_ant     = '';                    
    LET vmes_actual    = 0;                   
    LET vmes_siguiente = 0;                 
    LET vaniomes       = '';   
    LET vaniomes2      = '';    
    LET vdia           = '';     
    LET vdia2          = '';     
    LET vmes           = '';                  
    LET vanio          = '';    
    LET vprodcrec      = '';    
    LET vcuenta        = '';    
    LET vsucursal      = '';    
    LET vsdo_dia_ant   = 0;              
    LET vimp_chq_sbg   = 0;              
    LET vint_acum      = 0;              
    LET vacum_sdo_int  = 0;              
    LET vproducto      = '';    
    LET vstatus_cta    = '';    
    LET vfecha_proceso = '';    
    LET vfec_ult_mov   = '';    
    LET vsdo_actual    = 0;              
    LET vnum_cte       = '';    
    LET vejecutivo     = '';  
    LET vfecha_alta    = '';
    LET vfecha_nueva   = '';
    LET vcodretsdo     = '';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/actualiza_ctasnoproc_comp.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/actualiza_ctasnoproc_comp.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            IF vcTrxAbierta = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcCodRet, vcCodRet2, viContador;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy, fecha_ant
      INTO vfecha_hoy, vfecha_ant
      FROM sc_fechas
     WHERE empresa = pEmpresa;
     
    LET vmes_actual    = LPAD(MONTH(vfecha_ant), 2, '0');
    LET vmes_siguiente = LPAD(MONTH(vfecha_hoy), 2, '0');
    LET vaniomes       = YEAR(vfecha_ant)||LPAD(MONTH(vfecha_ant), 2, '0');
    LET vdia           = DAY(vfecha_ant);
    LET vmes           = LPAD(MONTH(vfecha_ant), 2, '0');
    LET vanio          = YEAR(vfecha_ant);
    LET vaniomes2      = YEAR(vfecha_ant - 1 UNITS DAY)||LPAD(MONTH(vfecha_ant - 1 UNITS DAY), 2, '0');
    LET vdia2          = DAY(vfecha_ant - 1 UNITS DAY);
    
    SELECT valor
      INTO vprodcrec
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PRODCREC';
    
    -- // CUENTAS DE CHEQUES
    FOREACH WITH HOLD
        SELECT cta.cuenta, chq.sucursal, chq.sdo_dia_ant, chq.imp_chq_sbg, noc.int_acum, noc.acum_sdo_int, chq.producto, 
               chq.status_cta, chq.fecha_proceso, chq.fec_ult_mov, chq.sdo_actual, chq.num_cte, noc.ejecutivo, noc.fecha_alta
          INTO vcuenta, vsucursal, vsdo_dia_ant, vimp_chq_sbg, vint_acum, vacum_sdo_int, vproducto, 
               vstatus_cta, vfecha_proceso, vfec_ult_mov, vsdo_actual, vnum_cte, vejecutivo, vfecha_alta
          FROM sc_valcierre cta,
               sc_maechq chq, 
               sc_maenoc noc
         WHERE cta.empresa = chq.empresa
           AND cta.cuenta = chq.cuenta
           AND chq.producto != vprodcrec 
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
           AND noc.fecha_alta < vfecha_hoy
           
        BEGIN WORK;
        LET vcTrxAbierta = 1;
        
        IF LPAD(MONTH(vfecha_alta),2,'0') = '02' THEN
            LET vfecha_nueva = vfecha_alta + 1 UNITS DAY;
        ELSE
            LET vfecha_nueva = LPAD(MONTH(vfecha_alta),2,'0') || '30' || YEAR(vfecha_alta);
        END IF;
           
        UPDATE sc_maenoc
           SET fecha_alta = vfecha_nueva
         WHERE empresa = pEmpresa
           AND cuenta = vcuenta;
           
        IF vimp_chq_sbg < 0 THEN
            LET vimp_chq_sbg = vimp_chq_sbg * -1;
        END IF
        
        LET vsdo_dia_ant = vsdo_dia_ant - vimp_chq_sbg;
        
        -- // Actualiza tabla de saldos diarios y provisiones no capitalizadas..        
        CALL sp_actsdodiarioc(vcuenta, vaniomes, vsucursal, vsdo_dia_ant, vint_acum, vdia, vaniomes2, vdia2) 
        RETURNING vcodretsdo;
           
        LET viContador = viContador + 1;
        
        COMMIT WORK;
        LET vcTrxAbierta = 0;
    END FOREACH;
    
    -- // INVERSIONES CRECIENTES
    FOREACH WITH HOLD
        SELECT cta.cuenta, chq.sucursal, chq.sdo_dia_ant, chq.imp_chq_sbg, noc.int_acum, noc.acum_sdo_int,
               chq.producto, chq.status_cta, chq.fecha_proceso, chq.fec_ult_mov, chq.sdo_actual, chq.num_cte, noc.ejecutivo, noc.fecha_alta
          INTO vcuenta, vsucursal, vsdo_dia_ant, vimp_chq_sbg, vint_acum, vacum_sdo_int,
               vproducto, vstatus_cta, vfecha_proceso, vfec_ult_mov, vsdo_actual, vnum_cte, vejecutivo, vfecha_alta
          FROM sc_valcierre cta,
               sc_maechq chq, 
               sc_maenoc noc
         WHERE cta.cuenta = chq.cuenta
           AND ( ( chq.producto = vprodcrec AND chq.status_cta != '2' AND chq.fecultdep < vfecha_hoy ) OR
                 ( chq.producto = vprodcrec AND chq.status_cta  = '2' AND chq.fecha_proceso >= vfecha_ant AND chq.fecultdep < vfecha_hoy ) OR
                 ( chq.producto = vprodcrec AND chq.status_cta  = '2' AND chq.fecha_proceso is null AND chq.fec_ult_mov >= vfecha_ant AND chq.fecultdep < vfecha_hoy ) )
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
        
        BEGIN WORK;
        LET vcTrxAbierta = 1;
        
        IF LPAD(MONTH(vfecha_alta),2,'0') = '02' THEN
            LET vfecha_nueva = vfecha_alta + 1 UNITS DAY;
        ELSE
            LET vfecha_nueva = LPAD(MONTH(vfecha_alta),2,'0') || '30' || YEAR(vfecha_alta);
        END IF;
           
        UPDATE sc_maenoc
           SET fecha_alta = vfecha_nueva
         WHERE empresa = pEmpresa
           AND cuenta = vcuenta;
        
        IF vimp_chq_sbg < 0 THEN
            LET vimp_chq_sbg = vimp_chq_sbg * -1;
        END IF
        
        LET vsdo_dia_ant = vsdo_dia_ant - vimp_chq_sbg;
        
        IF ( vproducto = vprodcrec AND vstatus_cta = '2' AND vfecha_proceso = vfecha_ant ) OR
           ( vproducto = vprodcrec AND vstatus_cta = '2' AND vfecha_proceso is null AND vfec_ult_mov = vfecha_ant ) THEN
            LET vsdo_dia_ant = vsdo_actual;
        END IF;
        
        -- // Actualiza tabla de saldos diarios y provisiones no capitalizadas..        
        CALL sp_actsdodiarioc(vcuenta, vaniomes, vsucursal, vsdo_dia_ant, vint_acum, vdia, vaniomes2, vdia2) 
        RETURNING vcodretsdo;
        
        LET viContador = viContador + 1;
        
        COMMIT WORK;
        LET vcTrxAbierta = 0;
    END FOREACH;
    
    RETURN vcCodRet, vcCodRet2, viContador;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_corrigeprov(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE ven_transacc     SMALLINT;
    
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vfecha_hoy       DATE;
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(14,2);   
    DEFINE vsuc_cta         CHAR(4);
    DEFINE vproducto        CHAR(4);
    DEFINE vsdo_actual      MONEY(16,2);
    DEFINE vtransacc        CHAR(4);
    DEFINE vsucursal        CHAR(4);  
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET vcontador1    = 0;
    LET ven_transacc  = 0;
    
    LET vsql         = '';
    LET vstmt        = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vfecha_hoy   = '';
    LET vcuenta      = '';
    LET vmonto       = 0.00;
    LET vsuc_cta     = '';
    LET vproducto    = '';
    LET vsdo_actual  = 0.00;
    LET vtransacc    = '';
    LET vsucursal    = '9250';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_corrigeprov.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_corrigeprov.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'ctasxprovisionar') THEN
        DROP TABLE "informix".ctasxprovisionar;
    END IF;
    
    CREATE RAW TABLE "informix".ctasxprovisionar
      (
        cuenta  char(20)    not null,
        monto   money(14,2) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_ctaxprov ON "informix".ctasxprovisionar(cuenta) USING BTREE;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/prov_falta_24122013.unl DELIMITER ''","'' INSERT INTO ctasxprovisionar" > /resplogifx/conciliachq/ctasprov.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/ctasprov.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE ctasxprovisionar;
    
    LET vfecha_hoy = '12/24/2013';
    
    LET vhora = CURRENT HOUR TO FRACTION;
    LET vfolio = "informix"||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];
    
    FOREACH WITH HOLD
        SELECT ctas.cuenta, ctas.monto, mae.sucursal, mae.producto, mae.sdo_actual
          INTO vcuenta, vmonto, vsuc_cta, vproducto, vsdo_actual
          FROM ctasxprovisionar ctas,
               sc_maechq mae
         WHERE ctas.cuenta = mae.cuenta
        
        BEGIN WORK;
        LET ven_transacc = 1;
        
        IF vmonto > 0 THEN
            LET vmonto = vmonto;
            LET vtransacc = '3381';
        ELSE
            LET vmonto = vmonto * -1;
            LET vtransacc = '3382';
        END IF;
        
        INSERT INTO sc_movhis VALUES
        ( '201312', 0, vfolio, vsucursal, "informix", vfecha_hoy, vfecha_hoy, vhora, vtransacc, vsuc_cta, vproducto, 
          pempresa, vcuenta, "", 0, vmonto, vmonto, 0, 0, 0, "", "", vsdo_actual, "0000", "", 0, "", "informix", "" );
          
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            UPDATE sc_sdodiarioc
               SET intprovnp24 = 0.00
             WHERE cuenta = vcuenta
               AND aniomes = '201312';
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                COMMIT WORK;
                LET ven_transacc = 0;
            ELSE
                ROLLBACK WORK;
                LET ven_transacc = 0;
            END IF;
        ELSE 
            ROLLBACK WORK;
            LET ven_transacc = 0;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        
        LET vcuenta     = '';
        LET vmonto      = 0.00;
        LET vsuc_cta    = '';
        LET vproducto   = '';
        LET vsdo_actual = 0.00;
        LET vtransacc   = '';
    END FOREACH;
    
    END;
    
    RETURN vcodret1, vcodret2, vcontador1;
    
END PROCEDURE;

