CREATE PROCEDURE "informix".sp_consultatarjeta(pEmpresa CHAR(3), pNumTarjeta CHAR(20))

--DATOS A REGRESAR--
RETURNING
CHAR(5),	--Codigo de Retorno
CHAR(20),	--Numero Cliente
CHAR(20),	--Numero Cuenta
CHAR(4),	--Numero de Producto
CHAR(26),	--Apellido Paterno
CHAR(26),	--Apellido Materno
CHAR(26),	--Nombre1
CHAR(26),	--Nombre2
DATE,		--Expiracion
CHAR(1),	--Tipo Tarjeta
CHAR(1),	--Estatus Tarjeta
MONEY(14,2), --Limite Autorizado
MONEY(14,2), --Disponible Mes
CHAR(2),	--Motivo
CHAR(1),	--Tipo Asignacion
CHAR(1),	--Cobro Comision
CHAR(8);	--Gerente Autoriza

--DEFINICION DE VARIABLES--
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cNumCte CHAR(20);
DEFINE cNumCta CHAR(20);
DEFINE cNumProd CHAR(4);
DEFINE cApellPaterno CHAR(26);
DEFINE cApellMaterno CHAR(26);
DEFINE cNombre1 CHAR(26);
DEFINE cNombre2 CHAR(26);
DEFINE dExpiracion DATE;
DEFINE cTipoTarjeta CHAR(1);
DEFINE cEstatusTarjeta CHAR(1);
DEFINE mLimiteAut MONEY(14,2);
DEFINE mDispMes MONEY(14,2);
DEFINE cMotivo CHAR(2);
DEFINE cTipoAsignacion CHAR(1);
DEFINE cCobroComision CHAR(1);
DEFINE cGerenteAut CHAR(1);

--INICIALIZACION DE VARIABLES--
LET iSqlErr = 0;
LET cCodRet = '000';
LET cNumCte = '';
LET cNumCta = '';
LET cNumProd = '';
LET cApellPaterno = '';
LET cApellMaterno = '';
LET cNombre1 = '';
LET cNombre2 = '';
LET dExpiracion = '';
LET cTipoTarjeta = '';
LET cEstatusTarjeta = '';
LET mLimiteAut = 0;
LET mDispMes = 0;
LET cMotivo = '';
LET cTipoAsignacion = '';
LET cCobroComision = '';
LET cGerenteAut = '';

--SET DEBUG FILE TO "sp_consultatarjeta.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumCte, cNumCta, cNumProd, cApellPaterno, cApellMaterno, cNombre1, cNombre2, 
				dExpiracion, cTipoTarjeta, cEstatusTarjeta, mLimiteAut, mDispMes, cMotivo, cTipoAsignacion, 
				cCobroComision, cGerenteAut;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	SELECT numcte, cuenta, expiracion, tipo_tarjeta, status_tar, limite_aut, disp_mes, motivo, 
		tipo_asignacion, cobro_comision, gerente_autoriza
	INTO cNumCte, cNumCta, dExpiracion, cTipoTarjeta, cEstatusTarjeta, mLimiteAut, mDispMes, cMotivo, 
		cTipoAsignacion, cCobroComision, cGerenteAut
	FROM "informix".sc_tarjeta
	WHERE empresa = pEmpresa AND num_tarjeta = pNumTarjeta; 

	IF NVL(cNumCta,'') <> "" THEN
		SELECT producto INTO cNumProd
		FROM "informix".sc_maechq
		WHERE empresa = pEmpresa AND cuenta = cNumCta; 

		SELECT apell_paterno, apell_materno, nombre1, nombre2
		INTO cApellPaterno, cApellMaterno, cNombre1, cNombre2
		FROM bdinteg:"informix".si_cliente
		WHERE empresa = pEmpresa AND numcte = cNumCte; 
	ELSE
        LET cCodRet = '252';
	END IF
	RETURN cCodRet, cNumCte, cNumCta, cNumProd, cApellPaterno, cApellMaterno, cNombre1, cNombre2, 
		dExpiracion, cTipoTarjeta, cEstatusTarjeta, mLimiteAut, mDispMes, cMotivo, cTipoAsignacion, 
		cCobroComision, cGerenteAut;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultamovtoscortetienda_pba( pTipo SMALLINT, 
                                                          pTienda SMALLINT, 
                                                          pTipoDeposito CHAR(1), 
                                                          pFechaParcialCoppel DATE, 
                                                          pFechaDeposito DATE, 
                                                          pFolioDeposito CHAR(16), 
                                                          pMontoDeposito INTEGER )
RETURNING INTEGER, INTEGER;

    --- #############################################################################################
    --- ## Modifico: Miguel Olivas                                                                 ##
    --- ## Fecha: 18/nov/2008                                                                      ##
    --- ## se modifica para que no haga la consulta a la tabla historica sc_movhis.                ##
    --- ##                                                                                         ##
    --- ## Modifico: Daniel Zambada                                                                ##
    --- ## Fecha: 21/nov/2008                                                                      ##
    --- ## se modifica para que valide  el retorno cuando no exista el registro con regreso 1 o 3. ##
    --- ##                                                                                         ##
    --- ## Modifico: Daniel Zambada                                                                ##
    --- ## Fecha: 21/may/2009                                                                      ##
    --- ## se modifica para que valide  el monto en la movdia por rango inferior  y superior.      ##
    --- #############################################################################################
    
    DEFINE vCodRet    CHAR(5);
    DEFINE vSqlErr    INTEGER;
    DEFINE vSucursal  CHAR(4);
    DEFINE vCSucursal CHAR(4);
    DEFINE vDeposito MONEY(14,2);
    
    LET vCodRet = '000';
    LET vSqlErr = 0;
    LET vSucursal = '0000';
    LET vCSucursal = '0000';
    LET vDeposito = pMontoDeposito/100;
    
    BEGIN
    
    ON EXCEPTION SET vsqlerr
        SET DEBUG FILE TO "/resplogifx/conciliachq/spei/sp_consultamovtoscortetienda.out";
        TRACE ON;
        IF vSqlErr <> 0 THEN
            LET vCodRet = vSqlErr;
            RETURN vCodRet,vSucursal;
        END IF;
    END EXCEPTION;
	--SET DEBUG FILE TO "/respaldosbd/cris/sp_consultamovtoscortetienda.out";
	--TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF pTipo = 1 THEN
    
        IF EXISTS (SELECT {+INDEX(bdicheq:"informix".sc_consultamovtoscortetienda ind_sc_consultamovtoscortetienda_01)} 
					fechadeposito,foliodeposito,montodeposito 
					FROM "informix".sc_consultamovtoscortetienda 
					WHERE fechadeposito = pFechaDeposito 
					AND foliodeposito = pFolioDeposito 
					AND montodeposito = vDeposito 
					AND estado = 1) THEN
                      
            INSERT INTO bdicheq:"informix".sc_consultamovtoscortetienda(fechadeposito,foliodeposito,montodeposito,tienda,tipodeposito,fechaparcialcoppel,estado,fechamov)
            VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 2, CURRENT);

            LET vCodRet = '2';
            LET vSucursal = '0';
            
        ELSE
            
		/* ###############################################
		IF EXISTS (SELECT fech_alt, folio_suc, monto_tot 
				FROM sc_movdia 
				WHERE fech_alt = pFechaDeposito 
				AND folio_suc = pFolioDeposito 
				AND monto_tot = vDeposito) THEN 
		############################################### */
            
		IF EXISTS ( SELECT {+INDEX(bdicheq:"informix".sc_movdia idx_movdia7a)} 
					fech_alt, folio_suc, monto_tot 
					FROM "informix".sc_movdia 
					WHERE cuenta = '16000000012' 
					AND folio_suc = pFolioDeposito
					AND fech_alt = pFechaDeposito 
					AND monto_tot = vDeposito ) THEN 

				/* ################################
					SELECT nvl(sucursal,'') 
					INTO vCSucursal 
					FROM sc_movdia 
					WHERE fech_alt = pFechaDeposito 
					AND folio_suc = pFolioDeposito 
					AND monto_tot = vDeposito; 
				################################ */
			
				SELECT {+INDEX(bdicheq:"informix".sc_movdia idx_movdia7a)} 
				NVL(sucursal,'') 
				INTO vCSucursal 
				FROM "informix".sc_movdia 
				WHERE cuenta = '16000000012' 
				AND folio_suc = pFolioDeposito
				AND fech_alt = pFechaDeposito 
				AND monto_tot = vDeposito;                 
              

                INSERT INTO bdicheq:"informix".sc_consultamovtoscortetienda(fechadeposito,foliodeposito,montodeposito,tienda,tipodeposito,fechaparcialcoppel,estado,fechamov)
                VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 1, CURRENT);

                LET vCodRet = '1';
                LET vSucursal = vCSucursal;
                
            ELSE

			-- // Se modifica para que no haga la consulta a la tabla historica sc_movhis.
			/* ############################################################################################################
			IF EXISTS (SELECT fech_alt, folio_suc, monto_tot 
				FROM sc_movhis 
				WHERE fech_alt = pFechaDeposito 
				AND folio_suc = pFolioDeposito 
				AND monto_tot = vDeposito) THEN

				SELECT nvl(sucursal,'') 
				INTO vCSucursal 
				FROM sc_movhis 
				WHERE fech_alt = pFechaDeposito 
				AND folio_suc = pFolioDeposito 
				AND monto_tot = vDeposito;        

				INSERT INTO sc_consultamovtoscortetienda(fechadeposito, foliodeposito, montodeposito, tienda, tipodeposito, fechaparcialcoppel, estado, fechamov)
				VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 1, CURRENT);

				LET vCodRet = '1';
				LET vSucursal = vCSucursal;
			ELSE
			############################################################################################################ */
                
                INSERT INTO bdicheq:"informix".sc_consultamovtoscortetienda(fechadeposito,foliodeposito,montodeposito,tienda,tipodeposito,fechaparcialcoppel,estado,fechamov)
                VALUES(pFechaDeposito, pFolioDeposito, vDeposito, pTienda, pTipoDeposito, pFechaParcialCoppel, 3, CURRENT);
                
                /* ############################################################################
					IF pFechaDeposito::DATE < (select fecha_hoy::DATE from bdicheq:sc_fechas) THEN	     	
						LET vCodRet = '1';
					ELSE
						LET vCodRet = '3';
					END IF;
				############################################################################ */
                
                LET vCodRet = '3';
                LET vSucursal = '0';

               --- END IF; 
            END IF; 
        END IF;
    END IF;

    RETURN vCodRet, vSucursal;
    
    END;
    
END PROCEDURE

DOCUMENT
"Consulta Movimientos de Cortes de Tienda ",
"AUTOR: Saul Ivanhoe",
