CREATE PROCEDURE "informix".cierrechqinvcrecparam(pempresa CHAR(3))
RETURNING CHAR(5);
     
    --- ################################################################################
    --- ##  Nombre:              cierrechqinvcrecparam                                ##
    --- ##  Version:             1.0.1                                                ##
    --- ##  Objetivo:            Programa inicial del cierre diario de captacion      ##
    --- ##  Creado por:                                                               ##
    --- ##  ModIFicado por:      JICS                                                 ##
    --- ##  Ultima Modificacion: Diciembre 2011                                       ##
    --- ################################################################################

    DEFINE vcodret          CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE vsqlerr          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE error_info       CHAR(50);
    DEFINE vfecha_hoy       DATE;
    DEFINE vpromedio        INTEGER;
    DEFINE vcont            SMALLINT;
    DEFINE vbrinca          INTEGER;
    DEFINE vcuenta          CHAR(20);
    DEFINE vctamin          CHAR(20);
    DEFINE vctamax          CHAR(20);
    
    LET vcodret    = "000";
    LET vcodret2   = "000";
    LET vcodret3   = " ";
    LET vsqlerr    = 0;
    LET isam_err   = 0;
    LET error_info = '';
    LET vfecha_hoy = ' ';    
    LET vpromedio  = 0;
    LET vcont      = 0;
    LET vbrinca    = 0;
    LET vcuenta    = '';
    LET vctamin    = '';
    LET vctamax    = '';
    
    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, error_info
        SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcrecparam.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqinvcrecparam.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    UPDATE sc_fechas
       SET ind_cierre = '0'
     WHERE empresa = pempresa;
     
    SELECT mae.cuenta
      FROM sc_maechq mae,
           sc_maeinstrucc ins
     WHERE mae.producto = '1100'
       AND mae.status_cta <> '2'
       AND ( mae.fecha_proceso is null OR mae.fecha_proceso = "" OR mae.fecha_proceso = vfecha_hoy )
       AND ins.empresa = mae.empresa
       AND ins.cuenta = mae.cuenta
       AND ins.capint = 'R'
       AND ins.instrucc = '01'
    INTO TEMP tmp_invscrec WITH NO LOG;
    CREATE INDEX idxtmp_invcrec ON tmp_invscrec(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_invscrec;
     
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vctamin, vctamax
      FROM tmp_invscrec
     WHERE cuenta >= '10000000000';
     
    LET vctamin = TRIM(vctamin);
    LET vctamax = TRIM(vctamax);
      
    SELECT ROUND(COUNT(*)/5)
      INTO vpromedio
      FROM tmp_invscrec
     WHERE cuenta BETWEEN vctamin AND vctamax;
       
    LET vcont = 1;  
    
    WHILE vcont <= 5 
        IF vcont = 1 THEN 
            LET vcuenta = vctamin;
               
            UPDATE sc_param
               SET valor = vcuenta
             WHERE empresa = pempresa
               AND codparam = 'CtaIniCieInvCreComp1';
        ELIF vcont = 2 THEN
            LET vbrinca = vpromedio;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 cuenta
                  INTO vcuenta
                  FROM tmp_invscrec
                 WHERE cuenta BETWEEN vctamin AND vctamax
                 ORDER BY cuenta
             
                UPDATE sc_param
                   SET valor = vcuenta
                 WHERE empresa = pempresa
                   AND codparam = 'CtaIniCieInvCreComp2';
            END FOREACH;
        ELIF vcont = 3 THEN
            LET vbrinca = vpromedio * 2;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 cuenta
                  INTO vcuenta
                  FROM tmp_invscrec
                 WHERE cuenta BETWEEN vctamin AND vctamax
                 ORDER BY cuenta
                 
                UPDATE sc_param
                   SET valor = vcuenta
                 WHERE empresa = pempresa
                   AND codparam = 'CtaIniCieInvCreComp3';
            END FOREACH;
        ELIF vcont = 4 THEN
            LET vbrinca = vpromedio * 3;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 cuenta
                  INTO vcuenta
                  FROM tmp_invscrec
                 WHERE cuenta BETWEEN vctamin AND vctamax
                 ORDER BY cuenta
                 
                UPDATE sc_param
                   SET valor = vcuenta
                 WHERE empresa = pempresa
                   AND codparam = 'CtaIniCieInvCreComp4';
            END FOREACH;
        ELIF vcont = 5 THEN
            LET vbrinca = vpromedio * 4;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 cuenta
                  INTO vcuenta
                  FROM tmp_invscrec
                 WHERE cuenta BETWEEN vctamin AND vctamax
                 ORDER BY cuenta
                 
                UPDATE sc_param
                   SET valor = vcuenta
                 WHERE empresa = pempresa
                   AND codparam = 'CtaIniCieInvCreComp5';
            END FOREACH;
        END IF;
        
        LET vcont = vcont + 1;  
        LET vcuenta = '';
    END WHILE;    

    RETURN vcodret;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".abono_atm( pc_costos CHAR(4),        --- SUCURSAL
                                       pcta_tar  CHAR(20),       --- CUENTA / TARJETA
                                       pmto_tot  DECIMAL(14,2) ) --- MONTO
RETURNING CHAR(5),  --- CODIGO DE RETORNO
		  CHAR(16), --- FOLIO
          CHAR(9),  --- NO. BOLETO INICIAL SORTEO MILLONARIO
          CHAR(9);  --- NO. BOLETO FINAL SORTEO MILLONARIO

    DEFINE vcCodRet1    CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE viDescErr    CHAR(50);
    DEFINE viEnTransac  SMALLINT;
    DEFINE vcCuenta     CHAR(20);
    DEFINE vcTarjeta    CHAR(16);
    DEFINE vcTransac    CHAR(4);
    DEFINE vcHora       CHAR(15);
    DEFINE vcFolio      CHAR(16);
    DEFINE vcCodRetAbo  CHAR(5);
    DEFINE vcBoletoIni  CHAR(9);
    DEFINE vcBoletoFin  CHAR(9);
    DEFINE vind_dispon  CHAR(1);
    
    LET vcCodRet1   = '00000';
    LET vcCodRet2   = '';
    LET vcCodRet3   = '';
    LET viSqlErr    = 0;
    LET viIsamErr   = 0;
    LET viDescErr   = 0;
    LET viEnTransac = 0;
    LET vcCuenta    = '';
    LET vcTarjeta   = '';
    LET vcTransac   = '';
    LET vcHora      = '';
    LET vcFolio     = '';
    LET vcCodRetAbo = '';
    LET vcBoletoIni = '000000000';
    LET vcBoletoFin = '000000000';
    LET vind_dispon = '0';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/abono_atm.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, viDescErr
        SET DEBUG FILE TO '/resplogifx/conciliachq/abono_atm.err';
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet1  = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = viDescErr;
            IF viEnTransac = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF
            LET vcCodRet1 = '00999';
            LET vcFolio = '';
            RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET viEnTransac = 1;
    END EXCEPTION WITH resume;

    IF viEnTransac = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;    
    
    -- // VALIDA PARAMETROS RECIBIDOS
    IF ( pc_costos is null OR pc_costos = '' )  OR
       ( pcta_tar is null OR pcta_tar = '' )    OR
       ( pmto_tot is null OR pmto_tot <= 0.00 ) THEN
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        LET vcCodRet1 = '00110';
        LET vcFolio = '';
        RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
    END IF;
    
    SELECT ind_disponible
      INTO vind_dispon
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';
     
    IF vind_dispon = '0' THEN
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        LET vcCodRet1 = '00004';
        LET vcFolio = '';
        RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
    END IF;
    
    -- // VALIDA QUE EXISTA LA CUENTA / TARJETA
    IF LENGTH(pcta_tar) = 11 THEN
        SELECT cuenta
          INTO vcCuenta
          FROM bdicheq:sc_maechq
         WHERE empresa = '001'
           AND cuenta = pcta_tar;
           
        IF ( vcCuenta is not null OR vcCuenta <> '' ) THEN
            LET vcCuenta = pcta_tar;
            LET vcTarjeta = '';
        ELSE
            IF viEnTransac = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            LET vcCodRet1 = '00100';
            LET vcFolio = '';
            RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
        END IF;
    ELIF LENGTH(pcta_tar) = 16 THEN
        SELECT mae.cuenta
          INTO vcCuenta
          FROM bdicheq:sc_tarjeta tar,
               bdicheq:sc_maechq mae
         WHERE tar.empresa = '001'
           AND tar.num_tarjeta = pcta_tar
           AND tar.status_tar = 'A'
           AND mae.empresa = tar.empresa
           AND mae.cuenta = tar.cuenta;
           
        IF ( vcCuenta is not null OR vcCuenta <> '' ) THEN
            LET vcCuenta = vcCuenta;
            LET vcTarjeta = pcta_tar;
        ELSE
            IF viEnTransac = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            LET vcCodRet1 = '00100';
            LET vcFolio = '';
            RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
        END IF;
    ELSE
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        LET vcCodRet1 = '00100';
        LET vcFolio = '';
        RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
    END IF;
    
    -- // OBTIENE TRANSACCION DE DEPOSITO
    SELECT valor
      INTO vcTransac
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = "TransaccDepCajero";
       
    IF vcTransac is null OR vcTransac = '' THEN
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        LET vcCodRet1 = '00110';
        LET vcFolio = '';
        RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
    END IF;
    
    -- // ARMA FOLIO DE OPERACION PARA EL DEPOSITO
    LET vcHora = CURRENT HOUR TO FRACTION;
    LET vcFolio = "recicatm"||vcHora[1,2]||vcHora[4,5]||vcHora[7,8]||vcHora[10,11];
    
    -- // APLICA OPERACION DE DEPOSITO EN LA CUENTA DE CAPTACION
    EXECUTE PROCEDURE bdicheq:abono_ref( '001', pc_costos, 'informix', vcTransac, "0000", vcFolio, vcCuenta, 0, pmto_tot, pmto_tot, 0, 0, 0, '01', '', vcTarjeta, '' ) 
    INTO vcCodRetAbo;
    
    -- // VALIDA EL RESULTADO DE LA OPERACION DE DEPOSITO EN LA CUENTA DE CAPTACION
    IF vcCodRetAbo <> '000' THEN
        IF ( vcCodRetAbo = '110' OR vcCodRetAbo = '106' OR vcCodRetAbo = '420' OR vcCodRetAbo = '552' OR 
             vcCodRetAbo = '959' OR vcCodRetAbo = '956' OR vcCodRetAbo = '401' OR vcCodRetAbo = '549' ) THEN
            LET vcCodRet1 = '00110';
        ELIF vcCodRetAbo = '100' THEN
            LET vcCodRet1 = '00100';
        ELIF vcCodRetAbo = '200' THEN
            LET vcCodRet1 = '00200';
        ELIF vcCodRetAbo = '951' THEN
            LET vcCodRet1 = '00951';
        ELIF vcCodRetAbo = '301' THEN
            LET vcCodRet1 = '00302';
        ELSE 
            LET vcCodRet1 = '00999';
        END IF;  
        
        IF viEnTransac = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        
        LET vcFolio = '';
        RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
    END IF;
    
    IF viEnTransac = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;
    
    END;
    
    RETURN vcCodRet1, vcFolio, vcBoletoIni, vcBoletoFin;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtener_status_cuenta(pempresa CHAR(3),pcuenta CHAR(20))
RETURNING CHAR(5);

-------------------------------------------------------------------------------------------------------
	--Realizó: Jose Ruben Lopez Hernadez
	--Fecha: 11/06/2013
	--Actividad:Se verifica el estatus de la cuenta que sea 1
	--BD: bdicheq
-------------------------------------------------------------------------------------------------------
	
	--Define variables
	DEFINE sql_err integer;
	DEFINE cod_ret char (5);
	DEFINE statusCta char(2);

	--Inicializa Variables
	LET sql_err = 0;
	LET cod_ret = '00000';
	LET statusCta='00';
	BEGIN
	
	 ON EXCEPTION SET sql_err
		IF sql_err <> 0 THEN
			LET cod_ret = sql_err;
			RETURN cod_ret;
		END IF;
	 END EXCEPTION;
	 
	SELECT {+INDEX(bdicheq:"informix".sc_maechq idx_sc_maechq3)}status_cta
      INTO statusCta
      FROM bdicheq:"informix".sc_maechq
     WHERE empresa = pempresa
       AND cuenta = pcuenta;

	IF statusCta<>1 THEN
			LET cod_ret = '00001'; --Cuenta diferente 1(estatus invalido)
	 END IF;

	 RETURN cod_ret;

	END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consult_total_movschq_bpi(pEmpresa CHAR(3), pCuenta CHAR(20), pFechaInicial DATE, pFechaFinal DATE)
   RETURNING CHAR(5),INTEGER

-------------------------------------------------------------------------------------------------------
-- Realizó: Jose Ruben Lopez Hernandez
-- Actividad: Obtiene el total de moviemientos de la cuenta para paginar
-- Solicitó: jorge Nuñez
-- Fecha de Solicitud: 26/03/2013
-- BD: bdicheq
-------------------------------------------------------------------------------------------------------

	DEFINE vCodRet					CHAR(5);
	DEFINE vSqlErr, vIsamErr, iAux	INTEGER;
	DEFINE totalReg					INTEGER;
	DEFINE totalReg2				INTEGER;
	DEFINE totalReg3				INTEGER;
  	DEFINE cFech_param				CHAR(10);
	DEFINE cFech_param_ini			CHAR(10);
	DEFINE vFechaHoy				DATE;
	DEFINE dFechaMov				DATE;

	LET vCodRet =		"00000";
	LET dFechaMov =		'01/01/1900';
   	LET vFechaHoy  =	'01/01/1900';
	LET totalReg=        0;
	LET totalReg2=       0;
	LET totalReg3=       0;
	

	BEGIN
		ON EXCEPTION SET vSqlErr, vIsamErr
			IF vSqlErr != 0 THEN
				LET vCodRet = vSqlErr;

				RETURN vCodRet,totalReg;
			END IF;
		END EXCEPTION;

		--Set Debug File To '/home/informix/ivonne/sp_consultmovschq_bpi.out';
		--Trace On;
	
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 2;
    
		--Consulta el valor de fechas limite en tabla de parámetros
		SELECT valor
		INTO cFech_param
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'fechcon_movhis';
		   
		SELECT valor
		INTO cFech_param_ini
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'FechIniCon_movhis_ol';

		--Consulta fecha de sistema
		SELECT fecha_hoy
		INTO vFechaHoy
		FROM bdicheq:"informix".sc_fechas;
		
		-- Obtiene movimientos del día
		IF pFechaInicial = vFechaHoy AND pFechaFinal = vFechaHoy THEN
				SELECT COUNT(*)
					INTO totalReg
					FROM
						bdicheq:"informix".sc_movdia AS mm,
						bdinteg:"informix".si_transacc AS tr 
					WHERE
						mm.empresa = pEmpresa AND
						mm.cuenta = pCuenta   AND
						mm.fech_alt = vFechaHoy AND
						mm.cancelad <> "S" AND
						mm.empresa = tr.empresa AND
						mm.transacc = tr.numero AND
						tr.se_emite_edocta = "S";	

					RETURN vCodRet,totalReg;
			   
		--END IF;	
		--Consulta de movimientos incluyendo la movhis y la movdia
		ELIF pFechaInicial >= cFech_param THEN
			IF pFechaFinal = vFechaHoy THEN
				SELECT COUNT(*)
					INTO totalReg
					FROM
						bdicheq:"informix".sc_movdia AS mm,
						bdinteg:"informix".si_transacc AS tr 
					WHERE
						mm.empresa = pEmpresa AND
						mm.cuenta =pCuenta AND
						mm.fech_alt = vFechaHoy AND
						mm.cancelad <> "S" AND
						mm.empresa = tr.empresa AND
						mm.transacc = tr.numero AND
						tr.se_emite_edocta = "S";
					
					SELECT COUNT(*)  
					INTO totalReg2
					FROM                                                                        			
						bdicheq:"informix".sc_movhis AS mm,                                            			
						bdinteg:"informix".si_transacc AS tr                                           			
					WHERE                                                                       			
						mm.empresa = pEmpresa AND                                           			
						mm.cuenta = pCuenta AND                                             			
						mm.fech_alt BETWEEN pFechaInicial AND pFechaFinal AND    
						mm.fech_alt >= cFech_param AND             			                                    			
						mm.cancelad <> "S" AND                                              			
						mm.transacc = tr.numero AND				            			
						mm.empresa = tr.empresa AND                                         			
						tr.se_emite_edocta = "S" ;  
					
					LET totalReg=totalReg+totalReg2;
					RETURN vCodRet,totalReg;
				
			ELSE 
				
					SELECT COUNT(*)
					INTO totalReg
					FROM                                                                        			
						bdicheq:"informix".sc_movhis AS mm,                                            			
						bdinteg:"informix".si_transacc AS tr                                           			
					WHERE                                                                       			
						mm.empresa = pEmpresa AND                                           			
						mm.cuenta = pCuenta AND                                             			
						mm.fech_alt BETWEEN pFechaInicial  AND pFechaFinal AND               			
						mm.fech_alt >= cFech_param AND                                      			
						mm.cancelad <> "S" AND                                              			
						mm.transacc = tr.numero AND				            			
						mm.empresa = tr.empresa AND                                         			
						tr.se_emite_edocta = "S" ;       		
					RETURN vCodRet,totalReg;
			END IF;	
		
		--Consulta de movimientos incluyendo la movhis_old, la mov_his y la movdia		
		ELIF pFechaInicial >= cFech_param_ini THEN
			IF pFechaFinal = vFechaHoy THEN
					SELECT COUNT(*) 
					INTO totalReg
					FROM
						bdicheq:"informix".sc_movdia AS mm,
						bdinteg:"informix".si_transacc AS tr 
					WHERE
						mm.empresa = pEmpresa AND
						mm.cuenta = pCuenta AND
						mm.fech_alt = vFechaHoy AND
						mm.cancelad <> "S" AND
						mm.empresa = tr.empresa AND
						mm.transacc = tr.numero AND
						tr.se_emite_edocta = "S";
						
					
					SELECT COUNT(*) 
					INTO totalReg2
					FROM                                                                        			
						bdicheq:"informix".sc_movhis AS mm,                                            			
						bdinteg:"informix".si_transacc AS tr                                           			
					WHERE                                                                       			
						mm.empresa = pEmpresa AND                                           			
						mm.cuenta = pCuenta AND                                             			
						mm.fech_alt BETWEEN pFechaInicial AND pFechaFinal AND               			
					    mm.fech_alt >= cFech_param AND                                  			
						mm.cancelad <> "S" AND                                              			
						mm.transacc = tr.numero AND				            			
						mm.empresa = tr.empresa AND                                         			
						tr.se_emite_edocta = "S" ; 
						
					SELECT COUNT(*) 
					INTO totalReg3
					FROM
						bdicheq:"informix".sc_movhis_old AS mm,
						bdinteg:"informix".si_transacc AS tr 
					WHERE
						mm.empresa = pEmpresa AND
						mm.cuenta = pCuenta AND
						mm.fech_alt BETWEEN pFechaInicial AND pFechaFinal AND
						mm.fech_alt >= cFech_param_ini AND 
						mm.cancelad <> "S" AND
						mm.transacc = tr.numero AND				
						mm.empresa = tr.empresa AND
						tr.se_emite_edocta = "S";		

					LET totalReg=totalReg+totalReg2+totalReg3;
					RETURN vCodRet,totalReg;			
			ELSE
				
					SELECT COUNT(*)
					INTO totalReg
					FROM                                                                        			
						bdicheq:"informix".sc_movhis AS mm,                                            			
						bdinteg:"informix".si_transacc AS tr                                           			
					WHERE                                                                       			
						mm.empresa = pEmpresa AND                                           			
						mm.cuenta = pCuenta AND                                             			
						mm.fech_alt BETWEEN pFechaInicial AND pFechaFinal AND               			
						mm.fech_alt >= cFech_param AND                                      			
						mm.cancelad <> "S" AND                                              			
						mm.transacc = tr.numero AND				            			
						mm.empresa = tr.empresa AND                                         			
						tr.se_emite_edocta = "S";   

					SELECT COUNT(*) 
					INTO totalReg2
					FROM                                                                                            
						bdicheq:"informix".sc_movhis_old AS mm,                                                            
						bdinteg:"informix".si_transacc AS tr                                                               
					WHERE                                                                                           
						mm.empresa = pEmpresa  AND                                                               
						mm.cuenta = pCuenta AND                                                                 
						mm.fech_alt BETWEEN pFechaInicial AND pFechaFinal AND                                   
						mm.fech_alt >= cFech_param_ini AND                                                      
						mm.cancelad <> "S" AND                                                                  
						mm.transacc = tr.numero AND				                                
						mm.empresa = tr.empresa AND                                                             
						tr.se_emite_edocta = "S";	
				
					LET totalReg=totalReg+totalReg2;																
					RETURN vCodRet,totalReg;  
			END IF;	
			--Se retorna un código de retorno 100 en caso de que el movimiento este fuera de los parametros establecidos             	
		ELSE
			LET vCodRet = '100';
			RETURN vCodRet,totalReg;                  
		END IF;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtener_primer_deposito_sc_movhis()
RETURNING
	CHAR(6) 	AS cod_ret,
	CHAR(80)	AS desc_ret

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);

	DEFINE vabierto     	CHAR(1);
	DEFINE vcontador3   	INTEGER;
	DEFINE cCuenta     		CHAR(20);
	DEFINE cCuenta2     	CHAR(20);
	DEFINE dFech_alt   		DATE;
	DEFINE dFechPrimDep 	DATE;
	DEFINE mMonto_tot   	MONEY;
	DEFINE iNumSerie    	INT8;
	
	
	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
	LET cDescRet			= "PROCESO EXITOSO";

	LET vabierto   			= '0';
	LET vcontador3 			= 0;
	LET cCuenta    			= "";
	LET cCuenta2    		= "";
	LET dFech_alt  			= DATE(1);
	LET dFechPrimDep 		= DATE(1);
	LET mMonto_tot  		= 0.0;
	LET iNumSerie   		= 0;
	
	
BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_obtener_primer_deposito_sc_movhis.out';
	--TRACE ON;
	
	FOREACH WITH HOLD
		SELECT cuenta, MIN(num_serial)
		INTO cCuenta, iNumSerie
		FROM "informix".sc_movhis t2
		WHERE empresa = "001"
		AND fech_alt > MDY(1,9,2014)
		AND transacc in ("0202","0282","0273","0329","0205") 
		GROUP BY cuenta

		IF vcontador3 = 0 THEN
			BEGIN WORK;
			LET vabierto = '1'; 
		END IF
		
		SELECT fech_alt, monto_tot
		INTO dFech_alt, mMonto_tot
		FROM "informix".sc_movhis t1
		WHERE empresa = "001"
		AND num_serial = iNumSerie
		AND cuenta = cCuenta;

		SELECT cuenta, fec_prim_deposito_orig
		INTO cCuenta2, dFechPrimDep
		FROM "informix".sc_indicadores 
		WHERE cuenta = cCuenta;
		
		IF NVL(cCuenta2,"") <> "" THEN
			IF dFechPrimDep IS NULL THEN		
				UPDATE "informix".sc_indicadores 
				SET fec_prim_deposito_orig = dFech_alt, imp_prim_deposito_orig = mMonto_tot
				WHERE cuenta = cCuenta;
			END IF
		END IF
	
		LET vcontador3 = vcontador3 + 1;
		
		IF vcontador3 = 5000 THEN
			LET vabierto = '0';
			LET vcontador3 = 0;
			COMMIT WORK;
		END IF
		
	END FOREACH
	
	IF vcontador3 > 0 THEN
		COMMIT WORK;
	END IF	

	RETURN cCodRet, cDescRet;
    
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener los primeros depositos de la tabla sc_movhis',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Febrero 2014';

CREATE PROCEDURE "informix".sp_rptmensualproac( pempresa char(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50);
     
    DEFINE vcodret1             char(5);
    DEFINE vcodret2             char(5);
    DEFINE vcodret3             char(50);
    DEFINE sql_err              integer;
    DEFINE isam_err             integer;
    DEFINE desc_err             char(50);
    DEFINE vcontador1           integer;
    DEFINE vcontador2           integer;
    DEFINE vcontador3           integer;
    DEFINE ven_transacc         smallint;
    DEFINE vcomienza            smallint;
    
    DEFINE vfecha_hoy           date;
    DEFINE vfecha_ant           DATE;
    DEFINE vpri_dia_mes         DATE;
    DEFINE vfecha_ini           DATE;
    DEFINE vfecha_fin           DATE;
    DEFINE vfecha_ejecucion     DATE;
    DEFINE vfechaproc           DATE;
    DEFINE vfechconmovhis       char(10);
    DEFINE vfechconmovhisold    char(10);
    
    DEFINE vsucursal            char(4);
    DEFINE vproducto            char(4);
    DEFINE vno_ctes             integer;
    DEFINE vno_ctas             integer;
    DEFINE vsdo_fin_mes         decimal(18,2);
    DEFINE vno_compras          integer;
    DEFINE vmonto_compras       decimal(18,2);
    
    DEFINE vsql                 CHAR(500);
    DEFINE vfechades            CHAR(6);

    LET vcodret1     = "000";               
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
    LET sql_err      = 0;                   
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;                   
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET ven_transacc = 0;                   
    LET vcomienza    = -1;  
       
    LET vfecha_hoy              = ''; 
    LET vfecha_ant              = '';
    LET vpri_dia_mes            = '';
    LET vfecha_ini              = '';
    LET vfecha_fin              = '';
    LET vfecha_ejecucion        = '';
    LET vfechaproc              = '';
    LET vfechconmovhis          = '';
    LET vfechconmovhisold       = '';
    
    LET vsucursal      = '';
    LET vproducto      = '';
    LET vno_ctes       = 0;
    LET vno_ctas       = 0;
    LET vsdo_fin_mes   = 0.00;
    LET vno_compras    = 0;
    LET vmonto_compras = 0.00;
    
    LET vsql      = '';
    LET vfechades = '';

    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_rptmensualproac.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_rptmensualproac.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    SELECT fecha_hoy, fecha_ant, pri_dia_mes
      INTO vfecha_hoy, vfecha_ant, vpri_dia_mes
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    LET vfecha_ini = vpri_dia_mes - 1 UNITS MONTH;
    LET vfecha_fin = vpri_dia_mes - 1 UNITS DAY;
    
    -- // VERIFICA QUE NO SE HAYA EJECUTADO EL PROCESO PARA ESTE PERIODO
    SELECT fecha
      INTO vfecha_ejecucion
      FROM sc_contproc_proac
     WHERE proceso = 'rptmensualproac'
       AND empresa = pempresa;
       
    IF vfecha_ejecucion = vfecha_hoy THEN
        LET vcodret1 = '958';
        LET vcodret2 = '958';
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE codigo_retorno = vcodret1
           AND sistema = '01';
           
        RETURN vcodret1, vcodret2, vcodret3;
    END IF;
	
	IF lpad(day(vfecha_hoy), 2, '0') <> '04' THEN
        LET vcodret1 = '958';
        LET vcodret2 = '958';
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE codigo_retorno = vcodret1
           AND sistema = '01';
           
        RETURN vcodret1, vcodret2, vcodret3;
    END IF;
    
    -- // Verifica se haya efectuado el paso de movs a historico
    SELECT fecha 
      INTO vfechaproc
      FROM sc_contproc
     WHERE empresa = pempresa 
       AND proceso = "pasomovshist"
       AND fecha = vfecha_ant;
       
    IF vfechaproc is null THEN
        LET vcodret1 = '953';
        LET vcodret2 = '953';
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE codigo_retorno = vcodret1
           AND sistema = '01';
           
        RETURN vcodret1, vcodret2, vcodret3;
    END IF;

    -- // PARAMETROS DE CONSULTA PARA MOVIMIENTOS HISTORICOS
    SELECT valor 
      INTO vfechconmovhis
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'fechcon_movhis';
       
    SELECT valor 
      INTO vfechconmovhisold
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'FechIniCon_movhis_ol';
       
    -- // TABLA TEMPORAL DE MOVIMIENTOS DEL MES
    SELECT *
      FROM sc_movhis_old  
     WHERE fech_alt BETWEEN vfecha_ini and vfecha_fin
       AND fech_alt >= vfechconmovhisold
       AND fech_alt < vfechconmovhis
       AND transacc IN('0830','0887')
       AND cancelad <> 'S'
    UNION ALL
    SELECT *
      FROM sc_movhis
     WHERE fech_alt BETWEEN vfecha_ini AND vfecha_fin
       AND fech_alt >= vfechconmovhis
       AND transacc IN('0830','0887')
       AND cancelad <> 'S'
    INTO TEMP tmp_movs WITH NO LOG;
    CREATE INDEX idx_tmpmovs1 ON tmp_movs(suc_cuen, producto);
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_movs;
       
    -- // TABLAS PARA REPORTE
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'sc_rptmensualproac') THEN
        DROP TABLE "informix".sc_rptmensualproac;        
    END IF;
    
    CREATE TABLE "informix".sc_rptmensualproac
      ( 
        sucursal            CHAR(4), 
        producto            CHAR(4), 
        no_clientes         INTEGER,
        no_cuentas          INTEGER,
        sdo_fin_mes         DECIMAL(18,2),
        no_compras_td       INTEGER,
        monto_compras_td    DECIMAL(18,2)
      ) 
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_rptmenproac ON "informix".sc_rptmensualproac(sucursal);
    UPDATE STATISTICS MEDIUM FOR TABLE "informix".sc_rptmensualproac;
    
    FOREACH WITH HOLD
        SELECT sucursal
          INTO vsucursal
          FROM sc_sucsrptsproac
          
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
          
        FOREACH
            SELECT producto
              INTO vproducto
              FROM sc_prodproac
             
            SELECT NVL(COUNT(UNIQUE num_cte),0)
              INTO vno_ctes
              FROM sc_maechq
             WHERE sucursal = vsucursal
               AND producto = vproducto
               AND status_cta <> '2';
               
            SELECT NVL(COUNT(*),0)
              INTO vno_ctas
              FROM sc_maechq
             WHERE sucursal = vsucursal
               AND producto = vproducto
               AND status_cta <> '2';
               
            SELECT NVL(SUM(sdo_dia_ant),0.00)
              INTO vsdo_fin_mes
              FROM sc_maechq
             WHERE sucursal = vsucursal
               AND producto = vproducto
               AND status_cta <> '2';
               
            SELECT NVL(COUNT(*),0)
              INTO vno_compras
              FROM tmp_movs
             WHERE suc_cuen = vsucursal
               AND producto = vproducto;
               
            SELECT NVL(SUM(monto_tot),0.00)
              INTO vmonto_compras
              FROM tmp_movs
             WHERE suc_cuen = vsucursal
               AND producto = vproducto;
               
            INSERT INTO sc_rptmensualproac(sucursal, producto, no_clientes, no_cuentas, sdo_fin_mes, no_compras_td, monto_compras_td)
            VALUES(vsucursal, vproducto, vno_ctes, vno_ctas, vsdo_fin_mes, vno_compras, vmonto_compras);
            
            LET vproducto      = '';
            LET vno_ctes       = 0;
            LET vno_ctas       = 0;
            LET vsdo_fin_mes   = 0.00;
            LET vno_compras    = 0;
            LET vmonto_compras = 0.00;
        END FOREACH;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vsucursal = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    UPDATE STATISTICS MEDIUM FOR TABLE "informix".sc_rptmensualproac;
    
    -- // DESCARGA EL ARCHIVO DE INFORMACIÓN
    LET vfechades = TO_CHAR(vfecha_fin, '%Y%m');
    
    LET vsql = '';
    LET vsql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/rptmensualproac_'||vfechades||'.txt '||
               ' SELECT * FROM sc_rptmensualproac ORDER BY sucursal, producto;" > /resplogifx/conciliachq/rptproac1.sql';
    SYSTEM vsql;
    
    LET vsql = '';
    LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/rptproac1.sql"; 
    SYSTEM vsql;
    
    UPDATE sc_contproc_proac
       SET fecha = vfecha_hoy
     WHERE proceso = 'rptmensualproac'
       AND empresa = pempresa;
    
    END;

    RETURN vcodret1, vcodret2, vcodret3;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtprimerdeposito( pFecha DATE )
RETURNING CHAR(6) 	AS cod_ret,
          CHAR(80)	AS desc_ret;
    
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
    DEFINE cCodRet2         CHAR(6);
	DEFINE cDescRet			CHAR(80);
    
	DEFINE vabierto     	CHAR(1);
	DEFINE vcontador3   	INTEGER;
	DEFINE cCuenta     		CHAR(20);
	DEFINE cCuenta2     	CHAR(20);
	DEFINE dFech_alt   		DATE;
	DEFINE dFechPrimDep 	DATE;
	DEFINE mMonto_tot   	MONEY;
	
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
    LET cCodRet2            = "";
	LET cDescRet			= "PROCESO EXITOSO";
    
	LET vabierto   			= '0';
	LET vcontador3 			= -1;
	LET cCuenta    			= "";
	LET cCuenta2    		= "";
	LET dFech_alt  			= DATE(1);
	LET dFechPrimDep 		= DATE(1);
	LET mMonto_tot  		= 0.0;
	
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
        ---SET DEBUG FILE TO '/informix/moha/sp_obtprimerdeposito.err';
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_obtprimerdeposito.err';
        TRACE ON;
        IF iSqlErr != 0 THEN
			LET cCodRet  = iSqlErr;
            LET cCodRet2 = iIsamErr;
			LET cDescRet = cErrorInfo;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
			RETURN cCodRet, cDescRet;
		END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--- SET DEBUG FILE TO '/informix/moha/sp_obtprimerdeposito.out';
	--- TRACE ON;
    
    SELECT {+INDEX(sc_indicadores idx_indicadores_fechpridep)}
           cuenta
      FROM sc_indicadores
     WHERE (fec_prim_deposito_orig is null OR fec_prim_deposito_orig = '')
       INTO TEMP tmp_ind WITH NO LOG;
    CREATE INDEX idx_indcta ON tmp_ind(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_ind;
    
    SELECT {+INDEX(sc_movhis idx_movhisnew4)}
           mov.cuenta, mov.num_serial, mov.fech_alt, mov.monto_tot
      FROM sc_movhis mov,
           tmp_ind ind
     WHERE mov.empresa = '001'
       AND mov.cuenta = ind.cuenta
       AND mov.fech_alt > pFecha  --- MDY(1,9,2014)
       AND mov.cancelad <> 'S'
       AND mov.transacc IN("0202","0205","0325") 
    INTO TEMP tmp_movs WITH NO LOG;
    CREATE INDEX idx_movcta ON tmp_movs(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_movs;
    
    SELECT UNIQUE cuenta 
      FROM tmp_movs
     WHERE cuenta >= '10000005016'
    INTO TEMP tmp_ctas_ind WITH NO LOG;
    CREATE INDEX idx_ctasind ON tmp_ctas_ind(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_ctas_ind;
	
	FOREACH WITH HOLD
        SELECT cuenta
          INTO cCuenta
          FROM tmp_ctas_ind
         WHERE cuenta >= '10000005016'
         
        IF vcontador3 = -1 THEN
			BEGIN WORK;
			LET vabierto = '1'; 
		END IF;
		
        FOREACH
            SELECT fech_alt, monto_tot
              INTO dFech_alt, mMonto_tot
              FROM tmp_movs 
             WHERE cuenta = cCuenta
             ORDER BY num_serial
             
            IF dFech_alt is not null AND mMonto_tot is not null THEN
                EXIT FOREACH;
            END IF;
        END FOREACH
        
        UPDATE sc_indicadores 
           SET fec_prim_deposito_orig = dFech_alt, 
               imp_prim_deposito_orig = mMonto_tot
         WHERE cuenta = cCuenta;
        
		LET vcontador3 = vcontador3 + 1;
		
		IF vcontador3 >= 1000 THEN
			LET vcontador3 = 0;			
			COMMIT WORK;
            BEGIN WORK;
		END IF;
		
	END FOREACH
	
	IF vabierto = '1' THEN
		COMMIT WORK;
	END IF;
    
	RETURN cCodRet, cDescRet;
    
    END;
    
END PROCEDURE

DOCUMENT
'DESCRIPCION: Proceso para obtener los primeros depositos de la tabla sc_movhis',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Febrero 2014';

create procedure "informix".protsdo_pos(
									pempresa char(3),
                                    suc char(4),
                                    usuariox char(8),
                                    transaccion char(4),
                                    transacc_suc char(4),
                                    folsuc char(16),
                                    cta char(20),
                                    docto integer,
                                    pmonto_concilia money(14,2),
                                    divisa char(2),
                                    clave integer,
									preferencia23 CHAR(23),
									pnum_tarjeta CHAR(16)
									)

returning char(5),char(4);

    --##############################################################################
    --## Procedimiento       : protsdo
    --## Version             : 1.0.0
    --## Objetivo            : Conciliacion de movimientos intercar
    --## Supuestos           :
    --## Modificado por      : Alejandro Rueda Sanchez
    --## Fecha modificacion  : Agosto 2009 PISA
    --## Fecha modificacion  : 01/03/2010 JYDG
    --##############################################################################

    -- // Variables Globales conciliacion 
    DEFINE GLOBAL vg_estatus    VARCHAR(5)  DEFAULT " ";
    DEFINE GLOBAL vgrfc_comer   VARCHAR(20) DEFAULT " ";
    DEFINE GLOBAL vgreferencia  VARCHAR(40) DEFAULT " ";

    -- // Definicion de Variables
    define sql_err,isam_err int;
    define cod_ret char(5);
    define v_tiptran, v_tpcheque, v_moneda, motiv char(2);
    define ctar char(20);
    define v_valdoc,nat char(1);
    define valdoc char(1);
    define suc_cta char(4);
    define v_plaza char(3);
    define prod char(8);
    define horax char(12);
    define fechax date;
    define vfechacalendario date;
    define v_status,cargox char(1);
    define saldo,reten money(16,2);
    define monto_docret, v_montolib money(16,2);
    define v_long_cta,longitud smallint;
    define v_cal_int_chq char(1);
    define tranret char(4);
    define v_clave integer;
    define v_usuario char(8);
    define v_referencia char(40);
    define vnum_tarjeta char(16);
    define vmaxsec smallint;

    -- // Variables para conciliacion
    DEFINE vtamanio      SMALLINT;
    DEFINE vt_indicador  CHAR(1);
    DEFINE vt_newfolio   CHAR(16);
    DEFINE vt_folsucorig CHAR(16);

    DEFINE vstatus_cta CHAR(1);
    DEFINE vexiste CHAR(1);
    define vaceptab char(1);
    define vacepcargo char(1);
	
    --SET DEBUG FILE TO "/informix/HomeInformix/rrm/protsdo.out";
    --TRACE ON;	

    LET sql_err = 0;
    LET isam_err = 0;
    LET v_tiptran = "";
    LET v_tpcheque= "";
    LET v_moneda ="";
    LET motiv = "";
    LET ctar = "";
    LET v_valdoc = "";
    LET nat = "";
    LET valdoc = "";
    LET suc_cta = "";
    LET v_plaza = "";
    LET prod = "";
    LET cod_ret = "000";
    LET horax = "";
    LET fechax = " ";
    LET vfechacalendario = "";
    LET v_status = "";
    LET cargox = "";
    LET saldo = 0;
    LET reten = 0;
    LET monto_docret= 0;
    LET v_montolib = 0;
    LET v_long_cta= 0;
    LET longitud = 0;
    LET v_cal_int_chq = "";
    LET tranret = "";
    LET v_clave = 0;
    LET v_usuario = "";
    LET v_referencia = "";
    LET vnum_tarjeta = "";
    LET vmaxsec = 0;

    LET vtamanio      = 0;
    LET vt_indicador  = "";
    LET vt_newfolio   ="";
    LET vt_folsucorig ="";

    let tranret = transaccion;

    begin

    on exception set sql_err
        if sql_err <> 0  then
            LET vg_estatus = vg_estatus::smallint + 5;
            let cod_ret = sql_err;
            return cod_ret,tranret;
        end if;
    end exception;


    
    ---***********************************************************
    ---* Validacion de datos transmitidos a este Store Procedure *
    ---***********************************************************
    let saldo   = 0;
    let reten   = 0;
    let sql_err = 0;

    set isolation to dirty read;
    set lock mode to wait 3;

    if suc is null or usuariox is null or transaccion is null or
       cta is null or folsuc is null or docto is null or
       suc = "   " or usuariox = "   " or transaccion = "    " or
       cta = " " or folsuc = " " then
            let cod_ret = "110";
            let tranret = transaccion;
            return cod_ret,tranret;
    end if;

    select ejecutivo 
      into v_usuario 
      from bdinteg:si_ejecut
     where empresa = pempresa 
       and ejecutivo = usuariox;

    if v_usuario <> usuariox or v_usuario is null then
        let cod_ret = "106";
        let tranret = transaccion;
        return cod_ret,tranret;
    end if;

    if pmonto_concilia = 0 or pmonto_concilia is null then
        let cod_ret = "110";
        return cod_ret,tranret;
    end if;
    
    ---***************************************
    ---* Validacion del numero de Transaccion*
    ---***************************************
    select numero,naturaleza,valida_docto,tpcheque,tipo_tran
      into tranret,nat,v_valdoc,v_tpcheque,v_tiptran
      from bdinteg:si_transacc
     where empresa = pempresa 
       and numero = transaccion;
     
    if tranret is null then
        let tranret = "XXXX";
    end if;

    if transaccion != tranret then
        let cod_ret = "550";
        let tranret = transaccion;
        return cod_ret,tranret;
    end if;

    if nat != "C" then
        let cod_ret = "560";
        return cod_ret,tranret;
    end if;

    select {+INDEX(sc_fechas idx_fechas1)} fecha_hoy 
      into vfechacalendario 
      from sc_fechas 
     where empresa = pempresa;

    select fecha_proceso, status_cta
      into fechax, vstatus_cta
      from sc_maechq
     where empresa = pempresa
       and cuenta = cta;

    if ( fechax is null or vstatus_cta = '4' or vstatus_cta = '5' ) then
        let fechax = vfechacalendario;
    end if

    if ( fechax < vfechacalendario ) then
        let cod_ret = "549";
        return cod_ret,tranret;
    end if
    
    if ( vstatus_cta in('2','6','7','8') ) then
        let cod_ret = "200";
        return cod_ret,tranret;
    end if
    
    -- // Busca el folio en docret  -- SE pone Case para buscar registro de la transaccion en operación. RRM
    select  monto, referencia 
      INTO monto_docret, v_referencia
      FROM sc_docret
     WHERE empresa = pempresa
       AND cuenta = cta
       AND folio_suc = folsuc
       AND cancelado = "P"
	   and transacc = (CASE WHEN tranret = '0830' THEN '0801'
							WHEN tranret = '0832' THEN '0805'
							WHEN tranret = '0887' THEN '0881'
							END);

    LET vtamanio = length(folsuc);
    LET folsuc = trim(folsuc);
    LET vt_folsucorig = trim(folsuc);
    LET vt_indicador = substr(folsuc,(vtamanio -6),1);

    -- // No encontro el folio en docret
    IF monto_docret = 0 OR monto_docret IS NULL THEN
        -- // Cambio el indicador por 1
        IF vt_indicador = '2' AND folsuc[1,8] = "intercar" THEN 
            LET vt_newfolio = substr(folsuc,1,vtamanio -7);
            LET vt_newfolio = trim(vt_newfolio)||"1"||substr(folsuc,vtamanio -5,vtamanio);
            LET folsuc = trim(vt_newfolio);
            
            -- // Realiza la busqueda con el nuevo folio
            SELECT monto,referencia 
              into monto_docret, v_referencia
              FROM sc_docret
             WHERE empresa = pempresa
               AND cuenta = cta
               AND folio_suc = folsuc
               AND cancelado = "P";
            
            -- // Forzada no encontrada como 2 ni 1...
            IF monto_docret = 0 OR monto_docret IS NULL THEN 
                LET vg_estatus = "3";
                LET folsuc = vt_folsucorig;
            -- // Forzada encontrada como 1..
            ELSE 
                LET vg_estatus = "2";
            END IF
        -- // Normal no encontrada....
        ELSE 
            LET vg_estatus = "1";
        END IF  
    -- // Si encontro el folio en docret...
    ELSE 
        -- // Normal encontrada como Normal
        IF vt_indicador = '1' THEN   
            LET vg_estatus = "0";    
        -- // Mismo folio que transaccion en linea..
        ELIF vt_indicador = '2' THEN
            LET vg_estatus = "4";
        ELSE
            LET vg_estatus = "99";
        END IF
    END IF  

    LET saldo    = 0;
    LET v_status = " ";
    LET ctar     = " ";
    LET v_montolib = 0;

    IF monto_docret IS NULL THEN
        LET monto_docret = 0;
    END IF;

    foreach cargo_cursor for
        select cuenta,sucursal,plaza,producto,status_cta,sdo_actual,sdo_retenido,motivo
          into ctar,suc_cta,v_plaza,prod,v_status,saldo,reten,motiv
          from sc_maechq
         where empresa = pempresa 
           and cuenta = cta

        select divisa 
          into v_moneda
          from sc_producto
         where empresa = pempresa 
           and producto = prod;
           
        if v_moneda != divisa then
            let cod_ret = "951";
            let tranret = transaccion;
            return cod_ret,tranret;
        end if;

        -- ******************************************
        -- Inicio de validaciones MAECHQ y BLOQUEO
        -- ******************************************
        if ctar is null then
            let ctar = "X";
        end if;

        if ctar = cta then
            let cod_ret = "000";
        else
            let cod_ret = "100";
            return cod_ret,tranret;
        end if;

        if v_status in ("2","6","7") then
            let cod_ret = "200";
            return cod_ret,tranret;
        elif v_status = "3" then
            IF transaccion <> '0830' AND transaccion <> '0887' AND transaccion <> '0832' THEN
                SELECT "1" 
                  INTO vexiste
                  FROM sc_ctabloqueo 
                 WHERE cuenta = ctar;

                IF vexiste = "1" THEN      
                    SELECT opcion 
                      INTO vaceptab
                      FROM sc_ctabloqueo 
                     WHERE cuenta = ctar;

                    IF vaceptab = 4 THEN
                        LET cod_ret = "300";
                        RETURN cod_ret,tranret;
                    END IF;

                    IF vaceptab = 3 THEN
                        LET cod_ret = "300";
                        RETURN cod_ret,tranret;
                    END IF;
                ELSE
                    select cargo 
                      into cargox 
                      from sc_bloqueo
                     where codigo = motiv;

                    if cargox = "N" then
                        let cod_ret = "300";
                        return cod_ret,tranret;
                    end if;
                END IF;
            END IF;
        end if;

		/* -- Se comenta porque el flujo se modifico para arrastrar el num_tarjeta 
        select max(secuencia) 
          into vmaxsec
          from sc_tarjeta
         where empresa = pempresa 
           and cuenta = cta 
           and tipo_tarjeta = "T";
           
        select num_tarjeta 
          into vnum_tarjeta
          from sc_tarjeta
         where empresa = pempresa 
           and cuenta = cta 
           and secuencia = vmaxsec;
		*/
		
        -- // Libera proteccion de saldo
        begin
        
        if monto_docret > 0 then
            -- // Monto en linea menor que conciliacion
            IF monto_docret < pmonto_concilia then
                LET vg_estatus = vg_estatus::smallint + 10;
            -- // Monto linea igual que la conciliacion
            ELIF monto_docret = pmonto_concilia THEN 
                LET vg_estatus = vg_estatus::smallint + 0;
            -- // Monto linea mayor  que la conciliacion
            ELSE 
                LET vg_estatus = vg_estatus::smallint + 20;
            END IF
            
            LET v_montolib = pmonto_concilia;
            let horax = current hour to fraction(3);
        end if
        
        end;
        
        if cod_ret = "000" then
            -- // Actualizacion del Maestro (se cambiar para que se libere el monto retenido)
            UPDATE sc_maechq
               SET (sdo_retenido) = (sdo_retenido - monto_docret)
             WHERE empresa = pempresa 
               AND cuenta = cta;

            if v_tpcheque = "01" then
                -- // Libera documento, para efectuar el cargo
                update {+INDEX(sc_histch idx_histch1)} sc_histch
                   set estado = " ",
                       importe = 0
                 where empresa = pempresa 
                   and cuenta = cta 
                   and numero = docto;
            end if
            
            -- // Actualiza documento retenido      Se agrega Case para busqueda de retenido correspondinete a la transaccion RRM
            update sc_docret
               set cancelado = "S",
                   monto = monto - v_montolib
             where empresa = pempresa
               and cuenta = cta
               and folio_suc = folsuc
               and cancelado = "P"
			   and transacc = (CASE WHEN tranret = '0830' THEN '0801'
									WHEN tranret = '0832' THEN '0805'
									WHEN tranret = '0887' THEN '0881'
									END);
			   			
            LET v_referencia = vgrfc_comer || vgreferencia;
            
            -- // Registra movimiento de retiro
            call cargon_ref_pos(pempresa, suc, usuariox, transaccion, transacc_suc, folsuc, cta, 
                            docto, pmonto_concilia, v_moneda, v_referencia, pnum_tarjeta, "", preferencia23)
            returning cod_ret, tranret;
        end if
            
        return cod_ret, tranret;
    
    end foreach;

    end

end procedure;

CREATE PROCEDURE "informix".borramovscfd_pba( pfecha DATE )
RETURNING CHAR(5), INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE vabierto         SMALLINT;
    DEFINE vidreg           INTEGER;
    DEFINE vfecha_emision   DATE;
    DEFINE vnum_cuenta      CHAR(20);
    
    LET vcodret1        = '000';
    LET vcodret2        = '000';
    LET sql_err	        = 0;
    LET isam_err        = 0;
    LET vcontador1      = 0;
    LET vcontador2      = 0;
    LET vcomienza       = -1;
    LET vabierto        = 0;
    LET vidreg          = 0;
    LET vfecha_emision  = '';
    LET vnum_cuenta     = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/borramovscfd.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF vabierto = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcontador1;
        END IF;
    END EXCEPTION;
    
    -- SET DEBUG FILE TO "/resplogifx/conciliachq/borramovscfd.out";
    -- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH cursor_borra WITH HOLD FOR
        SELECT {+INDEX(sc_encabezado_edocta_factelect idx_encabezado_fe)} idreg, fecha_emision, num_cuenta
          INTO vidreg, vfecha_emision, vnum_cuenta
          FROM sc_encabezado_edocta_factelect
         WHERE fecha_emision <= pFecha
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET vabierto = 1;
        END IF;
        
        DELETE FROM sc_encabezado_edocta_factelect 
         WHERE CURRENT OF cursor_borra;
         
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;
        
        IF vcontador2 >= 1000 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF vabierto = 1 THEN
        COMMIT WORK;
    END IF;

    END;

    RETURN vcodret1, vcontador1;

END PROCEDURE;

