        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;
        
        IF vcontador2 >= 100 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF vabierto = 1 THEN
        COMMIT WORK;
    END IF;

    END;

    RETURN vcodret1, vcontador1;

END PROCEDURE;

