    DEFINE vsistema         CHAR(2);
    DEFINE vusuario         CHAR(10);
    DEFINE vexiste_fecha    SMALLINT;
    
    DEFINE vcodretparam     CHAR(5);
    DEFINE vserial_inicial  INTEGER;
    DEFINE vserial_final    INTEGER;
    DEFINE vcomienza        INTEGER;
    DEFINE vcont_commit     INTEGER;
    DEFINE vnum_serial      INTEGER;
    
    LET vcodret1        = '000';
    LET vcodret2        = '000';
    LET sql_err	        = 0;
    LET isam_err        = 0;
    LET vcontador1      = 0;
    LET vcontador2      = 0;
    LET vcontador3      = 0;
    LET ven_transacc    = 0; 
    
    LET vfecha_hoy      = ''; 
    LET vfecha_ant      = '';
    LET vfecha_borrado  = '';
    LET vexiste         = 0;
    LET vexistefin      = 0;
    LET vfechaproc      = 0;
    LET vsql            = '';
    LET vstmt           = '';
    LET vexistefinproc  = '';
    LET vproceso        = 'pasamovshistoldcomp3';
    LET vsistema        = '01';
    LET vusuario        = user;
    LET vexiste_fecha   = 0;
    
    LET vcodretparam    = '';    
    LET vserial_inicial = 0;
    LET vserial_final   = 0;
    LET vcomienza       = -1;
    LET vcont_commit    = 0;
    LET vnum_serial     = 0;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistoldcomp3.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold3.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold3.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/pasamovshistoldcomp3.out";
    --- TRACE ON;
    
    SET OPTIMIZATION HIGH;
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM sc_fechas
     WHERE empresa = pempresa;
     
    SELECT valor
      INTO vfecha_ant
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'PasoMovhis_MovhisOld';
       
    SELECT valor
      INTO vfecha_borrado
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'BorraRegistrosMovhis';
     
    -- // VALIDA HAYA INICIADO EL PROCESO PRINCIPAL
    WHILE vfechaproc = 0
        SET ISOLATION TO DIRTY READ;
    
        SELECT COUNT(*)
          INTO vfechaproc
          FROM sc_contproc
         WHERE empresa = pempresa
           AND proceso = 'ini_pasomovshistold'
           AND fecha = vfecha_ant;
    END WHILE;
      
    -- // Guarda inicio de proceso     
    SELECT COUNT(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vfecha_hoy
       AND sistema = vsistema;

    IF vexiste = 0 THEN
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horaspasamovsold3.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold3.sql';
        SYSTEM vstmt;
    ELSE
        SELECT COUNT(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vfecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";
           
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold3.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold3.sql';
            SYSTEM vstmt;
        ELSE
            SELECT "1"
              INTO vexistefinproc
              FROM sc_contproc
             WHERE empresa = pempresa
               AND proceso = "pasomovshistoldcomp3"
               AND fecha = vfecha_ant;
               
            IF vexistefinproc = "1" THEN
                LET vcodret1 = "958";
                RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
            END IF
        END IF;
    END IF;
    
    -- // OBTIENE VALORES PARA RANGO DE SERIALES A PROCESAR
    SELECT valor::integer
      INTO vserial_inicial
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'SerIniPasoMovHisOld3';
       
    SELECT valor::integer
      INTO vserial_final
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'SerIniPasoMovHisOld4';
       
    -- // OBTIENE EL NUMERO DE REGISTROS A TRASPASAR
    SELECT {+INDEX(sc_movhis idx_movhis_serial)}
           COUNT(*)
      INTO vcontador1
      FROM sc_movhis
     WHERE fech_alt = vfecha_ant
       AND num_serial >= vserial_inicial
       AND num_serial < vserial_final;
    
    FOREACH WITH HOLD 
        SELECT {+INDEX(sc_movhis idx_movhis_serial)}
               num_serial
          INTO vnum_serial
          FROM sc_movhis
         WHERE fech_alt = vfecha_ant
           AND num_serial >= vserial_inicial
           AND num_serial < vserial_final
           
        BEGIN WORK;
        LET ven_transacc = 1;
        
        IF vfecha_ant > vfecha_borrado THEN 
            INSERT INTO sc_movhis_old
            SELECT {+INDEX(sc_movhis idx_movhis_serial)}
                   mov.*
              FROM sc_movhis mov
             WHERE mov.fech_alt = vfecha_ant
               AND mov.num_serial = vnum_serial;
             
            DELETE {+INDEX(sc_movhis idx_movhis_serial)}
              FROM sc_movhis
             WHERE fech_alt = vfecha_ant
               AND num_serial = vnum_serial;
        ELSE
            DELETE {+INDEX(sc_movhis idx_movhis_serial)}
              FROM sc_movhis
             WHERE fech_alt = vfecha_ant
               AND num_serial = vnum_serial;
        END IF;
         
        LET vcont_commit = vcont_commit + 1;
        
        COMMIT WORK;
        LET ven_transacc = 0;
    END FOREACH;
    
    SELECT {+INDEX(sc_movhis_old idx_movhis_serial_old)}
           COUNT(*)
      INTO vcontador2
      FROM sc_movhis_old
     WHERE fech_alt = vfecha_ant
       AND num_serial >= vserial_inicial
       AND num_serial < vserial_final;
     
    SELECT {+INDEX(sc_movhis idx_movhis_serial)}
           COUNT(*)
      INTO vcontador3
      FROM sc_movhis
     WHERE fech_alt = vfecha_ant
       AND num_serial >= vserial_inicial
       AND num_serial < vserial_final;
       
    IF vcontador1 = vcontador2 THEN
        LET vcodret1 = '000'; -- // PROCESO CONCLUIDO SATISFACTORIAMENTE
        LET vcodret2 = '000';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET ejecutivo = '''||vusuario||''','||
                   'status_proc   = '''||'F'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold3.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold3.sql';
        SYSTEM vstmt;
           
        UPDATE sc_contproc
           SET fecha   = vfecha_ant
         WHERE empresa = pempresa
           AND proceso = 'pasomovshistoldcomp3';
    ELSE
        LET vcodret1 = '999'; -- // LOS MOVIMIENTOS TRASPASADOS NO COINCIDEN CON LOS MOVIMIENTOS A TRASAPASAR
        LET vcodret2 = '999';
        
        LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                   'SET status_proc   = '''||'C'||''','||
                   'codret        = '''||vcodret1||''','||
                   'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                   'WHERE empresa = '''||pempresa||''' '||
                   'AND proceso   = '''||vproceso||''' '||
                   'AND fecha     = '''||vfecha_hoy||''' '||
                   'AND sistema   = '''||vsistema||''';" > /tmp/horaspasamovsold3.sql';
        SYSTEM vsql;
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horaspasamovsold3.sql';
        SYSTEM vstmt;
    END IF;
       
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_edoctamovtos_central( pEmpresa  CHAR(3),  
                                                     pCuenta   CHAR(20), 
                                                     pFechaIni DATE,     
                                                     pFechaFin DATE,     
                                                     pRegistro SMALLINT, 
                                                     pUsuario  CHAR(10), 
                                                     iConsMax  INTEGER ) 
RETURNING CHAR(5)      AS cCodRet,      
          CHAR(10)     AS cFechaMov,    
          CHAR(40)     AS cReferencia,  
          CHAR(50)     AS cDescripcion, 
          MONEY(14, 2) AS mRetiro,      
          MONEY(14, 2) AS mDeposito,    
          MONEY(14, 2) AS mSaldo,       
          CHAR(50)     AS cSucursal,    
          CHAR(4)      AS cTransacc,
          CHAR(16)     AS cNumTarjeta;    
    
    DEFINE cCodRet          CHAR(5);
    DEFINE iSqlErr          INTEGER;
    DEFINE iIsamErr         INTEGER;
    DEFINE iAux             INTEGER;
    DEFINE iCiclo           INTEGER;
    DEFINE dFechaMov1       DATE;
    DEFINE cFechaMov        CHAR(10);
    DEFINE cReferencia      CHAR(40);
    DEFINE cDescripcion     CHAR(50);
    DEFINE mRetiro          MONEY(14,2);
    DEFINE mDeposito        MONEY(14,2); 
    DEFINE mSaldo           MONEY(14,2); 
    DEFINE mMonto           MONEY(14,2);
    DEFINE cNaturaleza      CHAR(1);
    DEFINE cSucursal        CHAR(50);
    DEFINE cProducto        CHAR(4);
    DEFINE cconsmovhis      CHAR(10);
    DEFINE cconsmovhisold   CHAR(10);
    DEFINE cconsmovhisold2  CHAR(10);
    DEFINE cconsmovhisold3  CHAR(10);
	DEFINE cTransacc        CHAR(4);
    DEFINE cNumTarjeta      CHAR(16);
    DEFINE cConcepto        CHAR(40);

    LET cCodRet         = "000";
	LET iSqlErr		    = 0;
    LET iIsamErr	    = 0; 
    LET iAux            = 0;
    LET iCiclo          = 0;
    LET dFechaMov1      = "";
    LET cFechaMov       = "";
    LET creferencia     = "";
    LET cDescripcion    = "";
    LET mRetiro         = 0;
    LET mDeposito       = 0;
    LET mSaldo          = 0;
	LET mMonto          = 0;
	LET cNaturaleza     = '';
    LET cSucursal       = "";
    LET cProducto       = '';
    LET cconsmovhis     = '';
	LET cconsmovhisold  = '';
    LET cconsmovhisold2 = '';
    LET cconsmovhisold3 = '';
	LET cTransacc       = '';
    LET cNumTarjeta     = '';
    LET cConcepto       = '';
    
    LET pCuenta = TRIM(pCuenta);
    
   --- SET DEBUG FILE TO "/respaldosbd/hectorb/sp_edoctamovtos_central.out";
   --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION 
        SET iSqlErr, iIsamErr
        IF iSqlErr != 0 THEN
            LET cCodRet = iSqlErr;
            RETURN cCodRet, cFechaMov, cReferencia, cDescripcion, mRetiro, mDeposito, mSaldo,cSucursal, cTransacc, cNumTarjeta;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTENGO EL NUMERO DE PRODUCTO 
    SELECT producto 
      INTO cProducto
      FROM bdicheq:"informix".sc_maechq
     WHERE empresa = pEmpresa
       AND cuenta = pCuenta;
    
    LET pUsuario = pUsuario;
    
    -- // LIMPIO TBABLA PARA REGISTROS NUEVOS 
    -- // Se quita delete para evitar tardanza en la respuesta del SP - 01/06/2010 
    /* ##############################
    DELETE FROM vedoctamov
     WHERE cod_usuario = pUsuario;
    ############################## */

    SELECT valor
      INTO cconsmovhis
      FROM bdicheq:"informix".sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'fechcon_movhis';

    SELECT valor
      INTO cconsmovhisold
      FROM bdicheq:"informix".sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'FechIniCon_movhis_ol';

    SELECT valor
      INTO cconsmovhisold2
      FROM bdicheq:"informix".sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'FechaIniMovhisOld2';
       
    SELECT valor
      INTO cconsmovhisold3
      FROM bdicheq:"informix".sc_param
     WHERE empresa = pEmpresa
       AND codparam = 'vfechconmovhisold3';

    -- // SE OBTIENEN TODOS LAS TRANSACCIONES DE LAS TABLAS HISTORICAS DE MOVIMIENTOS DEL RANGO DE FECHAS SOLICITADAS
    FOREACH
        SELECT {+INDEX(sc_movhis idx_movhisnew4)}
               mm.num_serial, mm.fech_alt, TRIM(tr.descripcion) AS descripcion, NVL(mm.referencia, '') AS referencia, mm.monto_tot, tr.naturaleza, mm.sdo_cuenta,
               CASE WHEN tr.numero in (0202,0223) THEN mm.sucursal||'-'||NVL(TRIM(su.nombre),'')||'-'||fech_hor ELSE '' END AS Sucursal, mm.transacc, NVL(mm.num_tarjeta,' ')
          INTO iAux, dFechaMov1, cDescripcion, cReferencia, mMonto, cNaturaleza, mSaldo, cSucursal, cTransacc, cNumTarjeta
          FROM bdicheq:"informix".sc_movhis AS mm,
               bdinteg:"informix".si_transacc AS tr,
         OUTER bdinteg:"informix".si_sucursales su
         WHERE mm.empresa = pEmpresa
           AND mm.cuenta = pCuenta
           AND mm.fech_alt BETWEEN pFechaIni AND pFechaFin
           AND mm.fech_alt >= cconsmovhis
           AND mm.cancelad <> "S"
           AND mm.transacc = tr.numero
           AND tr.empresa = mm.empresa
           AND tr.numero = mm.transacc
           AND tr.se_emite_edocta = "S"
           AND su.sucursal = mm.sucursal
           AND su.empresa = tr.empresa
         UNION ALL
        SELECT {+INDEX(sc_movhis_old movhis1)}
               mm.num_serial, mm.fech_alt, TRIM(tr.descripcion) AS descripcion, NVL(mm.referencia, '') AS referencia, mm.monto_tot, tr.naturaleza, mm.sdo_cuenta,
               CASE WHEN tr.numero in (0202,0223) THEN mm.sucursal||'-'||NVL(TRIM(su.nombre),'')||'-'||fech_hor ELSE '' END AS Sucursal, mm.transacc, NVL(mm.num_tarjeta,' ')
		  FROM bdicheq:"informix".sc_movhis_old AS mm,
               bdinteg:"informix".si_transacc AS tr,
         OUTER bdinteg:"informix".si_sucursales su
         WHERE mm.empresa = pEmpresa
           AND mm.cuenta = pCuenta
           AND mm.fech_alt BETWEEN pFechaIni AND pFechaFin
           AND mm.fech_alt >= cconsmovhisold
           AND mm.fech_alt < cconsmovhis
           AND mm.cancelad <> "S"
           AND mm.transacc = tr.numero
           AND tr.empresa = mm.empresa
           AND tr.numero = mm.transacc
           AND tr.se_emite_edocta = "S"
           AND su.sucursal = mm.sucursal
           AND su.empresa = tr.empresa
		UNION ALL
        SELECT {+INDEX(sc_movhis_old2 movhis1_old2)}
               mm.num_serial, mm.fech_alt, TRIM(tr.descripcion) AS descripcion, NVL(mm.referencia, '') AS referencia, mm.monto_tot, tr.naturaleza, mm.sdo_cuenta,
               CASE WHEN tr.numero in (0202,0223) THEN mm.sucursal||'-'||NVL(TRIM(su.nombre),'')||'-'||fech_hor ELSE '' END AS Sucursal, mm.transacc, NVL(mm.num_tarjeta,' ')
          FROM bdicheq:"informix".sc_movhis_old2 AS mm,
               bdinteg:"informix".si_transacc AS tr,
         OUTER bdinteg:"informix".si_sucursales su
         WHERE mm.empresa = pEmpresa
           AND mm.cuenta = pCuenta
           AND mm.fech_alt BETWEEN pFechaIni AND pFechaFin
           AND mm.fech_alt >= cconsmovhisold2
           AND mm.fech_alt < cconsmovhisold
           AND mm.cancelad <> "S"
           AND mm.transacc = tr.numero
           AND tr.empresa = mm.empresa
           AND tr.numero = mm.transacc
           AND tr.se_emite_edocta = "S"
           AND su.sucursal = mm.sucursal
           AND su.empresa = tr.empresa
        UNION ALL
        SELECT {+INDEX(sc_movhis_old3 movhis1_old3)}
               mm.num_serial, mm.fech_alt, TRIM(tr.descripcion) AS descripcion, NVL(mm.referencia, '') AS referencia, mm.monto_tot, tr.naturaleza, mm.sdo_cuenta,
               CASE WHEN tr.numero in (0202,0223) THEN mm.sucursal||'-'||NVL(TRIM(su.nombre),'')||'-'||fech_hor ELSE '' END AS Sucursal, mm.transacc, NVL(mm.num_tarjeta,' ')
          FROM bdicheq:"informix".sc_movhis_old3 AS mm,
               bdinteg:"informix".si_transacc AS tr,
         OUTER bdinteg:"informix".si_sucursales su
         WHERE mm.empresa = pEmpresa
           AND mm.cuenta = pCuenta
           AND mm.fech_alt BETWEEN pFechaIni AND pFechaFin
           AND mm.fech_alt >= cconsmovhisold3
           AND mm.fech_alt < cconsmovhisold2
           AND mm.cancelad <> "S"
           AND mm.transacc = tr.numero
           AND tr.empresa = mm.empresa
           AND tr.numero = mm.transacc
           AND tr.se_emite_edocta = "S"
           AND su.sucursal = mm.sucursal
           AND su.empresa = tr.empresa
         ORDER BY mm.fech_alt DESC, mm.num_serial DESC, fech_alt DESC, num_serial DESC
         
        IF cTransacc = '0273' THEN
			SELECT FIRST 1 vchrconceptopago
			  INTO cConcepto
			  FROM bdispei:tblhistpago
			 WHERE vchrclaverastreo = cReferencia
			   AND dtfechavalor = dFechaMov1
			   AND intcvetipopago <> 0;
               
            IF cConcepto is null OR cConcepto = '' THEN
                LET cDescripcion = TRIM(cDescripcion);
            ELSE
                LET cDescripcion = TRIM(cDescripcion) ||' '|| TRIM(cConcepto);
            END IF;
		END IF;

	    IF cTransacc = '0274' THEN
            IF SUBSTR(cReferencia,1, 9) = 'BANCOPPEL' THEN
                SELECT FIRST 1 vchrconceptopago
                  INTO cConcepto
                  FROM bdispei:tblhistpago
                 WHERE vchrclaverastreo = cReferencia
                   AND dtfechavalor = dFechaMov1
                   AND intcvetipopago <> 0;
            ELSE
                SELECT FIRST 1 vchrconceptopago2
                  INTO cConcepto
                  FROM bdispei:tblhistpago
                 WHERE vchrclaverastreo = cReferencia
                   AND dtfechavalor = dFechaMov1
                   AND intcvetipopago <> 0;
            END IF;
            
            IF cConcepto is null OR cConcepto = '' THEN
                LET cDescripcion = TRIM(cDescripcion);
            ELSE
                LET cDescripcion = TRIM(cDescripcion) ||' '|| TRIM(cConcepto);
            END IF;
		END IF;
			   
        LET mRetiro = 0;
        LET mDeposito = 0;

        IF cNaturaleza = 'C' THEN
            LET mRetiro = mMonto;
        END IF;

        IF cNaturaleza = 'A' OR cNaturaleza = 'R' THEN
            LET mDeposito = mMonto;
        END IF;

        LET iCiclo = iCiclo + 1;
        
        -- // PAGINACION
        IF iCiclo <= pRegistro THEN 
            CONTINUE FOREACH;
        END IF;
        
        LET cFechaMov = SUBSTR(dFechaMov1, 7, 10) || "/" || SUBSTR(dFechaMov1, 1, 2)  || "/" || SUBSTR(dFechaMov1, 4, 5);
        
        IF cProducto = '1600' THEN
            INSERT INTO bdicheq:"informix".vedoctamov 
            (empresa,cod_usuario,secuencia,cuenta,fechamov,referencia,descripcion,retiro,deposito,saldo,generico_1,generico_2,generico_3,generico_4,generico_5,generico_6,consulta)
            VALUES 
            (pEmpresa, pUsuario, iCiclo, pCuenta, dFechaMov1, '', '', mRetiro, mDeposito, mSaldo, cDescripcion, cReferencia, cSucursal, '', '', '', iConsMax);
        ELSE
            RETURN TRIM(cCodRet), cFechaMov, cReferencia, cDescripcion, mRetiro, mDeposito, mSaldo, cSucursal, cTransacc, cNumTarjeta WITH RESUME;
        END IF;
    END FOREACH;
    
    LET cCodRet = '100'; 
    
    RETURN TRIM(cCodRet), cFechaMov, cReferencia, cDescripcion, mRetiro, mDeposito, mSaldo, cSucursal, cTransacc, cNumTarjeta WITH RESUME;

    END;

END PROCEDURE

DOCUMENT
'CAMBIO     : Abigail Vasavilbazo, Armando Mercado',
'DESCRIPCION: Se modifico para validar si el producto es 1600 y en dado caso se insertan los reg. directo en la tabla si retornar los movimientos',
'FECHA      : Febrero 2009',
'VERSION    : 200902',
'BD         : BDICHEQ',
'CAMBIO     : Hector Bojorquez',
'DESCRIPCION: Se modifico para que recibiera el folio de la ultima consulta.',
'             Se quito delete para evitar tardanza en la respuesta del sp, se agrego en el insert de la tabla vedoctamov que tambien se inserte el folio de la consulta recibido',
'FECHA      : Junio 2010',
'VERSION    : 201006',
'BD         : BDICHEQ',
'CAMBIO     : Héctor Bojórquez',
'DESCRIPCION: Se modificó para que regrese el número de transacción de cada movimento',
'FECHA      : Agosto 2011',
'VERSION    : 201108',
'BD         : BDICHEQ';

CREATE PROCEDURE "informix".sp_desc_archivos_conc(pEmpresa CHAR(3), pFechaInicio DATE, pFechaFin DATE)
RETURNING CHAR(5);
    
    
    DEFINE vcodret                  CHAR(5);
	DEFINE vfechafin                DATE;
    DEFINE vsqlerr 					INTEGER;
	DEFINE vfecha1					CHAR(8);
	DEFINE vfecha2					CHAR(2);
    DEFINE vcSql                    CHAR(600);
	DEFINE vcStmt                   CHAR(250);
	DEFINE vruta_descarga           CHAR(60);
	
	
    LET vcodret   = "00000";                                                                                  
	LET vsqlerr   = 0; 
	LET vfecha1   = "";
	LET vfecha2   = "";
	LET vcSql     = "";
	LET vcStmt    = "";
	LET vruta_descarga = '';
	
    
    
     --SET DEBUG FILE TO "/tmp/sp_desc_archivos_conc.out";
     --TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET vsqlerr
        IF vsqlerr != 0 THEN
            SET DEBUG FILE TO "/tmp/sp_desc_archivos_conc.err";
            TRACE ON;
            LET vcodret = vsqlerr;
            RETURN vcodRet;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF pEmpresa IS NULL OR pFechaInicio IS NULL OR pFechaFin IS NULL THEN
        LET vcodret = '001';
        RETURN vcodret;
    END IF; 
    
	SELECT valor
      INTO vruta_descarga
      FROM sc_param
      WHERE empresa = pEmpresa
		AND codparam = 'RutaDescargaFED';
	

	LET vfecha1 = TO_CHAR(pFechaFin, '%d%m%Y');
	LET vfecha2 = SUBSTR(pFechaInicio,4,2);
	    
    -- // GENERA EL ARCHIVO DE LA TABLA sc_encabezado_edocta_factelect
    LET vcSql = '';
    LET vcSql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '|| TRIM(vruta_descarga) ||'con_captacion_'||vfecha2||'-'||vfecha1||'.txt'||
                '  SELECT num_cuenta,fechafinal,substr(mensajeproducto,0,4),rfc FROM sc_encabezado_edocta_factelect_old WHERE fechafinal BETWEEN '''|| pFechaInicio ||''' AND '''|| pFechaFin ||'''" > '|| TRIM(vruta_descarga) ||'descarga_con.sql';
    SYSTEM vcSql;
	
    
    LET vcStmt = '';
    
	LET vcStmt = 'dbaccess bdicheq /resplogifx/conciliachq/edoctacfd/descarga_con.sql'; 
    SYSTEM vcStmt;
    
    	
    
    RETURN vcodret;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_dispersionnominatransacciones( pTipEmpresa SMALLINT, pConcepto SMALLINT )
RETURNING CHAR(3), CHAR(3), CHAR(4), Money(16,2), CHAR(4), CHAR(4), CHAR(4), MONEY(16,2), MONEY(16,2), CHAR(4), MONEY(16,2); 
    
    DEFINE vCodRet          CHAR(3);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE iSqlErr          INTEGER;
    DEFINE iSamErr          INTEGER;
    DEFINE cDesErr          CHAR(50);
    DEFINE cTipoTransac     CHAR(3);
    DEFINE cTransaccion     CHAR(4);
    DEFINE cTransacAbono    CHAR(4);
    DEFINE cTransacCom      CHAR(4);
    DEFINE cTransacIva      CHAR(4);
    DEFINE cTransacCargo    CHAR(4);
    DEFINE mMontoFijo       MONEY(16,2);
    DEFINE mMontoCom        MONEY(16,2);
    DEFINE mMontoIva        MONEY(16,2);
    DEFINE mMontoComAper    MONEY(16,2);
    
    LET vCodRet       = "000";
    LET vCodRet2      = '';
    LET vCodRet3      = '';
    LET iSqlErr       = 0;
    LET iSamErr       = 0;
    LET cDesErr       = '';
    LET cTipoTransac  = "";
    LET cTransaccion  = "";
    LET cTransacAbono = "";
    LET cTransacCom   = "";
    LET cTransacIva   = "";
    LET cTransacCargo = "";
    LET mMontoFijo    = 0.00;
    LET mMontoCom     = 0.00;
    LET mMontoIva     = 0.00;
    LET mMontoComAper = 0.00;
    
    BEGIN
    
    ON EXCEPTION SET iSqlerr, iSamErr, cDesErr
        SET DEBUG FILE TO '/tmp/sp_dispersionnominatransacciones.err';
        TRACE ON;
        IF iSqlerr <> 0 THEN
            LET vCodRet  = iSqlerr; 
            LET vCodRet2 = iSamErr;
            LET vCodRet3 = cDesErr;
            RETURN vCodRet, cTipoTransac, cTransaccion, mMontoFijo, cTransacAbono, cTransacCargo, cTransacCom, mMontoCom, mMontoComAper, cTransacIva, mMontoIva;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ; 
    SET LOCK MODE TO WAIT 3; 
    
    --- SET DEBUG FILE TO '/tmp/sp_dispersionnominatransacciones.out';
    --- TRACE ON;
    
    /* EMPRESA EXTERNA */
    IF pTipEmpresa <> 2 THEN
        FOREACH
            SELECT nom.tipo_transaccion, nom.transacc, tran.monto_fijo 
              INTO cTipoTransac, cTransaccion, mMontoFijo
              FROM bdicheq:sc_nominatransacciones As nom,
                   bdinteg:si_transacc As tran
             WHERE nom.tipo_empresa = pTipEmpresa
               AND nom.tipo_codigo = pConcepto 
               AND nom.transacc = tran.numero
             ORDER BY nom.tipo_transaccion
            
            IF cTipoTransac   = '001'  THEN /* Aqui se traera el 0202 */
                LET cTransacAbono = cTransaccion;   
            ElIF cTipoTransac = '002'  THEN /* Aqui se traera el 0395 */
                LET cTransacCargo = cTransaccion;     
            ElIF cTipoTransac = '003'  THEN /* Aqui se traera el 0394 */
                LET cTransacCom = cTransaccion;   
                LET mMontoCom = mMontoFijo;
            ElIF cTipoTransac = '004'  THEN
                LET mMontoComAper = mMontoFijo;
            ElIF cTipoTransac = '005'  THEN /* Aqui se traera el 0396 */
                LET cTransacIva = cTransaccion;   
            ElIF cTipoTransac = '006'  THEN
                LET mMontoIva = mMontoFijo;
            END IF;
        END FOREACH;
        
        IF   ( cTransacAbono = "" Or cTransacAbono = " " Or cTransacAbono = "0" Or cTransacAbono Is Null ) THEN  /*  Transaccion Abono Invalida  */
            LET vCodRet = '840';  
        ElIF ( cTransacCargo = "" Or cTransacCargo = " " Or cTransacCargo = "0" Or cTransacCargo Is Null ) THEN  /*  Transaccion Cargo Invalida  */
            LET vCodRet = '845';  
        ElIF ( cTransacCom   = "" Or cTransacCom   = " " Or cTransacCom   = "0" Or cTransacCom   Is Null ) THEN  /*  Transaccion Comision Invalida  */
            LET vCodRet = '850';  
        ElIF ( cTransacIva   = "" Or cTransacIva   = " " Or cTransacIva   = "0" Or cTransacIva   Is Null ) THEN  /*  Transaccion Iva Invalida  */
            LET vCodRet = '855';  
        END IF;
    END IF;
    
    /* EMPRESA INTERNA O PROPIA */
    IF pTipEmpresa = 2 THEN
        SELECT nom.transacc 
          INTO cTransacAbono /* Aqui traera 0202 */
          FROM bdicheq:sc_nominatransacciones AS nom,
               bdinteg:si_transacc AS tran
         WHERE nom.tipo_empresa = pTipEmpresa
           AND nom.tipo_codigo = pConcepto 
           AND nom.tipo_transaccion = '001'
           AND nom.transacc = tran.numero;
        
        /*  Transaccion Abono Invalida  */
        IF ( cTransacAbono = "" OR cTransacAbono = " " OR cTransacAbono = "0" OR cTransacAbono IS NULL ) THEN
            LET vCodRet = '840';  
        END IF;
    END IF; 
    
    RETURN vCodRet, cTipoTransac, cTransaccion, mMontoFijo, cTransacAbono, cTransacCargo, cTransacCom, mMontoCom, mMontoComAper, cTransacIva, mMontoIva;
    
    END;
    
END PROCEDURE
    
DOCUMENT 
'DESCRIPCION: Retornar las transacciones a utilizar para la dispersion de nomina"', 
'AUTOR: Jesus Antonio Bastidas Lopez', 
'FECHA: Abril de 2009', 
'VERSION: 200904', 
'BD: BDICHEQ';

CREATE PROCEDURE "informix".sp_consulta_nominatransacciones(pEmpresa char(3), pRegistros SMALLINT)
	returning char(5), char(3),integer, char(60);

	--****************************************************************************************************
	-- DESCRIPCION:  OBTIENE LA TRANSACCION PARA CONSULTAR EL CONCEPTO DE LA DISPERSION
	-- AUTOR : Francisco Rodríguez Ibarra
	-- FECHA : 26/08/2011
	-- BD: bdicheq
	-- SOLICITO :Mauricio León
	-- Modificado por: Berenice Noriega
	-- Fecha: 23 de Mayo 2014.
	-- Descripciòn: la busqueda de concepto se cambio por tipo de empresa en lugar de por cada empresa
	--****************************************************************************************************
	--DEFINICION DE VARIABLES
	DEFINE vCodRet char(5);
    DEFINE sql_err integer;
	DEFINE vTipoTran char(3);
	DEFINE iCodConcepto integer;
	DEFINE vDescripcion varchar(100);
	DEFINE iCont integer;
	DEFINE VTipEmpresa SMALLINT;
	
	
	--asigacion de valores a variables
	LET vCodRet='00000';
	LET vTipoTran='';
	LET vDescripcion='';
	LET iCont=0;
	LET iCodConcepto=0;
	LET VTipEmpresa=0;
	
	
	--*********************************************
	--- SET debug FILE TO "/home/informix/BereniceOut/sp_consulta_nominatransacciones.out";
	--- Trace ON;
	--*********************************************
	
	
	
  BEGIN


   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let vCodRet = sql_err;
            RETURN vCodRet, '',0, '';
      END IF ;
   END EXCEPTION ;
	
	SET LOCK MODE TO WAIT ;
	SET ISOLATION DIRTY READ ;
	
	
	
	---Sacar el tipo de empresa de la tabla -------------
	
	SELECT tipo_empresa 
	INTO VTipEmpresa
	FROM sc_nominaempresas
	WHERE codigo=pEmpresa;

	---Se buscan las transacciones/conceptos por tipo de empresa -------------
	
	FOREACH
		SELECT b.tipo_transaccion, a.codigoconcepto, a.descripcion INTO vTipoTran, iCodConcepto, vDescripcion
			FROM bdicheq:"informix".sc_nominaconceptos as a, bdicheq:"informix".sc_nominatransacciones as b
			WHERE b.tipo_empresa = VTipEmpresa 
			AND b.tipo_transaccion = '001'
			AND a.codigoconcepto = b.tipo_codigo
			
		LET iCont=1;
		
		RETURN vCodRet,vTipoTran,iCodConcepto,vDescripcion WITH RESUME;
	END FOREACH;
	
	IF(iCont=0) THEN
		LET vCodRet='00001';
		RETURN vCodRet,vTipoTran,iCodConcepto,vDescripcion;
	END IF;
	END;
END PROCEDURE
;

Create Procedure "informix".sp_nominaconsultasaldoeje
(
pCuenta            Char(20),
pTotalRegistros    Integer,
pImporteTotal      Money(18,2),
pEmpresa           Char(3),
pConcepto          Smallint
)

RETURNING CHAR(5), Integer ;

DEFINE cCodRet                                              CHAR(5);
DEFINE vSqlErr                                                 INTEGER ;
DEFINE mSaldo                                                Money(16,2);
Define mValorIva                                                Money(4,2);
Define mMontoComisionDispercion                     Money(14,2);
Define mTotaliva                                                Money(14,2);
Define mTotalComision                                       Money(14,2);
Define cValorTransComiDisp                              Char(4);    --Aqui se traera el 0394
Define cValorTransIvaDisp                                  Char(4);    --Aqui se traera el 0396
Define cValorTransaccion                                   Char(4);
Define mMontoFijo                                             Money(16,2);
Define cValorTipoTransaccion                             Char(3);
Define siTipoEmpresa                                        Smallint ;
Define bParametroErroneo                                  Boolean  ;
Define iSaldo                                                     Integer ;

LET cCodRet = "000";
LET vSqlErr = 0;
LET mSaldo = 0;
Let mValorIva = 0;
Let mMontoComisionDispercion = 0;
Let mTotaliva = 0;
Let mTotalComision = 0;
Let cValorTransComiDisp = '';
Let cValorTransIvaDisp = '';
Let cValorTransaccion = '';
Let mMontoFijo = 0;
Let cValorTipoTransaccion = '';
Let siTipoEmpresa = 0;
Let bParametroErroneo = "F";
Let iSaldo = 0;

--set debug file to "/tmp/sp_obtieneSaldoCuenta.out";
--Trace on;

BEGIN
        ON EXCEPTION SET vSqlErr
                IF vSqlErr != 0 THEN
                        LET cCodRet = vSqlErr;
                        RETURN cCodRet, mSaldo;
                END IF;
        END EXCEPTION;
		
--VALIDACIONES DE PARAMETROS DE ENTRADA
If (pCuenta = "") Or (pCuenta = " ") Or (pCuenta Is Null) Then
    Let bParametroErroneo = "T";  
Elif (pTotalRegistros = 0) Or (pTotalRegistros = "") Or (pTotalRegistros Is Null) Then
    Let bParametroErroneo = "T";
Elif (pImporteTotal = 0) Or (pImporteTotal = "") Or (pImporteTotal Is Null) Then
    Let bParametroErroneo = "T";
Elif (pEmpresa = '000') Or (pEmpresa = "") Or (pEmpresa Is Null) Then
    Let bParametroErroneo = "T";
Elif (pConcepto = 0) Or (pConcepto = "") Or (pConcepto Is Null) Or (pConcepto = " ") Then
	Let bParametroErroneo = "T";
End If

If bParametroErroneo = "T" Then
     Let cCodRet = '800';
     Let iSaldo = 0;
     Return cCodRet, iSaldo;
End If

        Select tipo_empresa Into siTipoEmpresa From bdicheq:sc_nominaempresas Where codigo = pEmpresa;
        
        If siTipoEmpresa <> 2 Then
			If Exists (Select 1 From bdicheq:sc_maechq Where empresa = '001' And cuenta = pCuenta) Then

				Select sdo_actual Into mSaldo From bdicheq:sc_maechq Where empresa = '001' And  cuenta = pCuenta;
	                        
	                         --CICLO PARA VALIDAR LOS VALORES DE LAS TRANSACCIONES Y SE OBTIENEN LOS MONTOS
					ForEach
						Select nomina.tipo_transaccion, nomina.transacc, transacc.monto_fijo Into cValorTipoTransaccion,cValorTransaccion, mMontoFijo
						From bdicheq:sc_nominatransacciones as nomina
						inner join bdinteg:si_transacc as transacc on nomina.transacc = transacc.numero
						Where nomina.tipo_codigo = pConcepto And nomina.tipo_empresa = siTipoEmpresa
						Order By nomina.tipo_transaccion
														  
						If cValorTipoTransaccion = '003' Then
							Let cValorTransComiDisp = cValorTransaccion;   --Aqui me trae el 0394
							Let mMontoComisionDispercion = mMontoFijo;                            
						Elif cValorTipoTransaccion = '005' Then
							Let cValorTransIvaDisp = cValorTransaccion;   --Aqui me trae el 0396                                    
						End If

					End ForEach
										 
					If (cValorTransComiDisp = "") Or (cValorTransComiDisp = " ") Or (cValorTransComiDisp Is Null) Then
						Let cCodRet = '850';   --Dispercion No Ejecutada: El Numero de Transaccion de la ComisiÃ³o es Valido                       
						Return cCodRet, mSaldo;
					Elif (cValorTransIvaDisp = "") Or (cValorTransIvaDisp = " ") Or (cValorTransIvaDisp Is Null) Then
						Let cCodRet = '855';   --Dispercion No Ejecutada: El Numero de Transaccion del Iva No es Valido                           
						Return cCodRet, mSaldo;
					End If

					Select valor 
					  Into mValorIva 
					  From bdinteg:si_param   --Aqui se obtiene el valor del Iva
					 Where cod_param = 47
					   AND empresa = "001";
					   
					If (mValorIva = "") Or (mValorIva = " ") Or (mValorIva Is Null) Then
						Let cCodRet = '855';  --Dispercion No Ejecutada: El Numero de Transaccion del Iva No es Valido
						Let mSaldo = 0;
						Return cCodRet, mSaldo;
					End If

					--Let mTotalComision = pTotalRegistros * mMontoComisionDispercion;
					--Let mTotaliva = pTotalRegistros * mValorIva;
					Let mTotalComision = pTotalRegistros * mMontoComisionDispercion;
					Let mTotaliva = mTotalComision * mValorIva;  --Nueva Forma de Calcular el Iva

				Let mSaldo = mSaldo - (pImporteTotal + mTotalComision + mTotaliva);  --Aqui se suma el total del importe mas los costos de comision y de iva de todos los registros

				If mSaldo < 0 Then
					-- CUENTA CON SALDO INSUFICIENTE
					Let cCodRet = "006";
					Let mSaldo = mSaldo * -1;
	            Elif mSaldo >= 0 Then
					Let mSaldo = 0;    --Aqui se regresa 0, cuando hay saldo suficiente
				End If
			Else
				-- CUENTA NO ENCONTRADA
				Let cCodRet = "005";
			End If

                --se cambia a char por el inet
		Let iSaldo = Cast(round(mSaldo + 0.4) as char(20));

        Elif siTipoEmpresa = 2 Then   
            Let iSaldo = 0;    --Aqui se regresa 0, cuando hay saldo suficiente
        End If

        RETURN cCodRet, iSaldo;
End
End Procedure
DOCUMENT
'Modifico :Armando Mercado',
'DESCRIPCION: Se agrego un parametro mas "Concepto", asi se ya se va a considerar cual es el cobro de comision,',
'dado a que la consulta estaba fija hacia nomina "1"',
'FECHA : Abril de 2009',
'VERSION: 200904',
'BD    : BDICHEQ',
'Modifico :Jesus Antonio Bastidas Lopez',
'DESCRIPCION: Se modifica la validacion para tipo de empresa externa y del grupo coppel "siTipoEmpresa <> 2" ',
'FECHA : mayo de 2009',
'VERSION: 200905',
'BD    : BDICHEQ';

CREATE PROCEDURE "informix".sp_nominaprocesadanoprocesada(pNombreArchivo CHAR(17), pTpoOperacion  CHAR(1))
--valores a regresar
RETURNING   CHAR(5), CHAR(10), CHAR(30), CHAR(20), CHAR(30), CHAR (20), MONEY, CHAR(20), CHAR(4),
            CHAR(4), CHAR (50), CHAR(30),  INTEGER, INTEGER, CHAR(4);


--Declaracion de variables
DEFINE  v_cCodRet        CHAR(5);
DEFINE v_cNumEmp         CHAR(10);
DEFINE v_cApellPaterno   CHAR(30);
DEFINE v_cApellMaterno   CHAR(20);
DEFINE v_cNombres        CHAR(30);
DEFINE v_cCuentaAbono    CHAR(20);
DEFINE v_mImporte        MONEY;
DEFINE v_cConcepto       CHAR(30);
DEFINE v_cStatus         CHAR(1);
DEFINE v_cDescStatus     CHAR(30);
DEFINE v_cNumCte         CHAR(20);
DEFINE  v_cProducto      CHAR(4);
DEFINE v_cTransaccion    CHAR(4);
DEFINE v_cDesTransacc    CHAR(50);
DEFINE v_iPagadas        INTEGER;
DEFINE v_iNoPagadas      INTEGER;
DEFINE v_iSqlErr         INTEGER;
Define cEmpresa          Char(3);
DEFINE v_cSucursal       CHAR(4);
DEFINE cConcepto         CHAR(1);
DEFINE iTipoEmpresa      SMALLINT;
---Inicializacion de variables
LET v_cCodRet = "00000";
LET v_cNumEmp = "";
LET v_cApellPaterno = "";
LET v_cApellMaterno = "";
LET v_cNombres = "";
LET v_cCuentaAbono = "";
LET  v_mImporte  = 0;
LET  v_cConcepto  = "";
LET  v_cStatus  = "";
LET v_cDescStatus = "";
LET v_cNumCte = "";
LET  v_cProducto = "";
LET v_cDesTransacc = "";
LET  v_iPagadas  = 0;
LET v_iNoPagadas = 0;
LET  v_iSqlErr = 0;
Let cEmpresa = '';
LET v_cSucursal='';
LET cConcepto = '';
LET v_cTransaccion='';
LET iTipoEmpresa = 0;

BEGIN
    ON EXCEPTION SET v_iSqlErr
        IF v_iSqlErr <> 0 THEN            
            LET v_cCodRet  = v_iSqlErr;
            RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,  
                    v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal;
        END IF;
    END EXCEPTION

    --SET DEBUG FILE TO  "/tmp/sp_NominaProcesadaNoProcesada.out";
    --TRACE ON;

    IF pNombreArchivo = "" OR pTpoOperacion = "" THEN
        LET  v_cCodRet  = "00110"; --datos insufucientes
        RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,  
                v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal;
    END IF;

    --Se obtiene la Empresa Cliente
    SELECT empresa INTO cEmpresa 
    FROM bdicheq:sc_nominaencabezadosumariohist
    WHERE nombre_archivo = pNombreArchivo;
    
    SELECT tipo_empresa into iTipoEmpresa
      FROM bdicheq:sc_nominaempresas
     WHERE codigo = cEmpresa;

   IF pTpoOperacion = '1' THEN --Nominas Procesadas
   
      FOREACH	  
			
			SELECT nommov.num_empleado, nommov.apell_paterno, nommov.apell_materno, nommov.nombres, nommov.cuenta_abono, nommov.importe, 
                   NVL(nom.descripcion, ''), NVL(mae.num_cte, ''), NVL(mae.producto,'0'), NVL(transacc.descripcion, ''),NVL(mae.sucursal,'0'),transacc.numero			  
			INTO  v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cDescStatus,  v_cNumCte,
                  v_cProducto, v_cDesTransacc, v_cSucursal,v_cTransaccion
            FROM bdicheq:sc_nominamovimientoshist nommov,
                Outer bdicheq:sc_nominaestatus nom,
                Outer bdicheq:sc_maechq mae,		
                bdinteg:si_transacc transacc
            WHERE  nom.cod_status  = nommov.status
               AND nommov.cuenta_abono=mae.cuenta            
               AND transacc.numero = ( SELECT transacc FROM bdicheq:sc_nominatransacciones WHERE tipo_transaccion = '001'  --Identificador del Abono
                                                                                            AND tipo_codigo = nommov.concepto  
                                                                                            AND tipo_empresa = iTipoEmpresa )
               AND nom.tpo_status = 2   --Es el status de los movimientos
               AND nommov.status = '1'
               AND nommov.nombre_archivo = pNombreArchivo 
			  			   
            RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,  
                    v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal WITH RESUME;        
      END FOREACH;

   ELIF pTpoOperacion = '2' THEN --Nominas no procesadas

      FOREACH
			   SELECT nommov.num_empleado, nommov.apell_paterno, nommov.apell_materno, nommov.nombres, nommov.cuenta_abono, nommov.importe, 
                   NVL(nom.descripcion, ''), NVL(mae.num_cte, ''), NVL(mae.producto,'0'), NVL(transacc.descripcion, ''),NVL(mae.sucursal,'0'),transacc.numero	
				INTO  v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cDescStatus,  v_cNumCte,
                  v_cProducto, v_cDesTransacc, v_cSucursal,v_cTransaccion				   
			   FROM bdicheq:sc_nominamovimientoshist nommov,
                Outer bdicheq:sc_nominaestatus nom,
                Outer bdicheq:sc_maechq mae,		
                bdinteg:si_transacc transacc
               WHERE  nom.cod_status  = nommov.status
               AND nommov.cuenta_abono=mae.cuenta            
               AND transacc.numero = ( SELECT transacc FROM bdicheq:sc_nominatransacciones WHERE tipo_transaccion = '001'  --Identificador del Abono
                                                                                            AND tipo_codigo = nommov.concepto  
                                                                                            AND tipo_empresa = iTipoEmpresa )
               AND nom.tpo_status = 2   --Es el status de los movimientos
               AND nommov.status > '1'
               AND nommov.nombre_archivo = pNombreArchivo 

            RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,  
                    v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal WITH RESUME;
      END FOREACH;

   END IF;
 END;
END PROCEDURE
    DOCUMENT
    'DESCRIPCION: Programa que genera informacion para los reportes de procesados y no procesados',
    'EJECUTADO O LLAMADO POR: Dispersion de Nomina Manual',
    'AUTOR: Armando Mercado Figueroa',
    'FECHA: 00/2008',
    'BD: BDCHEQ',
    'CAMBIOS: Se agrego validacion para tomar transaccion de los diferentes conceptos como: nomina,gastos,fondo,capacitacion',
    'AUTOR: Armando Mercado Figueroa',
    'Fecha: 17/Enero/2009',
	'MODIFICÓ :Maria Elena Angulo Aispuro',
	'DESCRIPCION:  Se reemplazan las consultas a las tablas principales sc_nominamovimientos y sc_nominaencabezadosumario por sus tablas historicas (sc_nominamovimientoshist,sc_nominaencabezadosumario) con el fin de regresar la información de cuentas al reporte de dispersion manual que se encuentran en la historica,',
	'además se agregó una mejora al realizar cambio para que realice con éxito la consulta a un archivo con mas de un concepto diferente ya que este devolvía un error si se presentabá este caso.',
	'FECHA : 24/Enero/2011',
	'BD    : BDICHEQ',
	'VERSION: 20110124.1706';

CREATE PROCEDURE "informix".sp_nominaprocesadanoprocesada_bei(pIdEmp CHAR(3), pFecDisp date,pTipoOpe char(1),psNombreArchivo CHAR(17),pRegistro smallint)
--valores a regresar
RETURNING   CHAR(5), CHAR(10), CHAR(30), CHAR(20), CHAR(30), CHAR (20), MONEY(16,2), CHAR(20), CHAR(4),
            CHAR(4), CHAR (50), CHAR(30),  INTEGER, INTEGER, CHAR(4);


	--****************************************************************************************************
	-- DESCRIPCION:  Obtiene los registros procesados y no procesados de nomina
	-- AUTOR : Francisco Rodríguez Ibarra
	-- FECHA : 26/08/2011
	-- BD: bdicheq
	-- SOLICITO :Mauricio León
	--
	-- DESCRIPCION:  Se agregó el filtrado por nombre de archivo y orden por numero de empleado
	-- AUTOR : Alfonso Antonio Cruz Alvarez
	-- FECHA : 07/01/2013
	-- BD: bdicheq
	-- SOLICITO :	José de Jesus Nevarez
	--***************************************************************************************************


	--Declaracion de variables
	DEFINE v_cNomArchivo	 CHAR(17);
	DEFINE  v_cCodRet        CHAR(5);
	DEFINE v_cNumEmp         CHAR(10);
	DEFINE v_cApellPaterno   CHAR(30);
	DEFINE v_cApellMaterno   CHAR(20);
	DEFINE v_cNombres        CHAR(30);
	DEFINE v_cCuentaAbono    CHAR(20);
	DEFINE v_mImporte        MONEY;
	DEFINE v_cConcepto       CHAR(30);
	DEFINE v_cStatus         CHAR(1);
	DEFINE v_cDescStatus     CHAR(30);
	DEFINE v_cNumCte         CHAR(20);
	DEFINE  v_cProducto      CHAR(4);
	DEFINE v_cTransaccion    CHAR(4);
	DEFINE v_cDesTransacc    CHAR(50);
	DEFINE v_iPagadas        INTEGER;
	DEFINE v_iNoPagadas      INTEGER;
	DEFINE v_iSqlErr         INTEGER;
	Define cEmpresa          Char(3);
	DEFINE v_cSucursal       CHAR(4);
	DEFINE cConcepto         CHAR(1);
	DEFINE  iCont  			 INTEGER;
	DEFINE  iContReg  		 INTEGER;
    DEFINE iTipoEmpresa      SMALLINT;
	
	---Inicializacion de variables
	LET v_cCodRet = "00000";
	LET v_cNomArchivo="";
	LET v_cNumEmp = "";
	LET v_cApellPaterno = "";
	LET v_cApellMaterno = "";
	LET v_cNombres = "";
	LET v_cCuentaAbono = "";
	LET  v_mImporte  = 0;
	LET  v_cConcepto  = "";
	LET  v_cStatus  = "";
	LET v_cDescStatus = "";
	LET v_cNumCte = "";
	LET  v_cProducto = "";
	LET v_cDesTransacc = "";
	LET  v_iPagadas  = 0;
	LET v_iNoPagadas = 0;
	LET  v_iSqlErr = 0;
	Let cEmpresa = '';
	LET v_cSucursal='';
	LET cConcepto = '';
	LET v_cTransaccion='';
	LET iCont=0;
	LET iContReg=0;
    LET iTipoEmpresa = 0;

	BEGIN
    ON EXCEPTION SET v_iSqlErr
        IF v_iSqlErr <> 0 THEN
            LET v_cCodRet  = v_iSqlErr;
            RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,
                    v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal;
        END IF;
    END EXCEPTION;
	
		SET LOCK MODE TO WAIT 3;
		SET ISOLATION DIRTY READ ;

	   IF (TRIM(NVL(pIdEmp,"")) = "") OR (TRIM(NVL(pTipoOpe,"")) = "") OR (TRIM(NVL(psNombreArchivo,"")) = "") THEN
	        LET  v_cCodRet  = "00001";
	        RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,
	                v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal;
	   END IF;
       
       SELECT tipo_empresa 
         INTO iTipoEmpresa
         FROM bdicheq:sc_nominaempresas
        WHERE codigo = pIdEmp;
	   
	  		 IF pTipoOpe = '1' THEN --Nominas Procesadas

			  FOREACH
					SELECT SKIP pRegistro FIRST 10 nommov.num_empleado, nommov.apell_paterno, nommov.apell_materno, nommov.nombres, nommov.cuenta_abono, nommov.importe,
						   NVL(nom.descripcion, ''), NVL(mae.num_cte, ''), NVL(mae.producto,'0'), NVL(transacc.descripcion, ''),NVL(mae.sucursal,'0'),transacc.numero
					INTO  v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cDescStatus,  v_cNumCte,
						  v_cProducto, v_cDesTransacc, v_cSucursal,v_cTransaccion
					FROM bdicheq:"informix".sc_nominamovimientoshist nommov,
						Outer bdicheq:"informix".sc_nominaestatus nom,
						Outer bdicheq:"informix".sc_maechq mae,
						bdinteg:"informix".si_transacc transacc,
						bdibpi:"informix".bpi_dispersarchivo dispersa
					WHERE  nom.cod_status = nommov.status
					   AND nommov.cuenta_abono = mae.cuenta
					   AND transacc.numero = ( SELECT transacc 
                                                 FROM bdicheq:"informix".sc_nominatransacciones 
                                                WHERE tipo_transaccion = '001'  --Identificador del Abono
                                                  AND tipo_codigo = nommov.concepto
                                                  AND tipo_empresa = iTipoEmpresa )
					   AND nom.tpo_status = 2   --Es el status de los movimientos
					   AND nommov.status = '1'
					   AND nommov.nombre_archivo =dispersa.nombre_archivo
                       AND dispersa.f_dispersion=pFecDisp
					   AND dispersa.id_empresa =pIdEmp
					   AND nommov.nombre_archivo = psNombreArchivo    --Filtrado por nombre de archivo
					   ORDER BY nommov.num_empleado
					--LET iContReg = iContReg + 1;

					LET iCont=1;
					RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,
							v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal WITH RESUME;

			  END FOREACH;

		   ELIF pTipoOpe = '2' THEN --Nominas no procesadas

			  FOREACH
					   SELECT SKIP pRegistro FIRST 10 nommov.num_empleado, nommov.apell_paterno, nommov.apell_materno, nommov.nombres, nommov.cuenta_abono, nommov.importe,
						   NVL(nom.descripcion, ''), NVL(mae.num_cte, ''), NVL(mae.producto,'0'), NVL(transacc.descripcion, ''),NVL(mae.sucursal,'0'),transacc.numero
						INTO  v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cDescStatus,  v_cNumCte,
						  v_cProducto, v_cDesTransacc, v_cSucursal,v_cTransaccion
					   FROM bdicheq:"informix".sc_nominamovimientoshist nommov,
						Outer bdicheq:"informix".sc_nominaestatus nom,
						Outer bdicheq:"informix".sc_maechq mae,
						bdinteg:"informix".si_transacc transacc,
						bdibpi:"informix".bpi_dispersarchivo dispersa
					   WHERE  nom.cod_status  = nommov.status
					   AND nommov.cuenta_abono=mae.cuenta
					   AND transacc.numero = ( SELECT transacc 
                                                 FROM bdicheq:"informix".sc_nominatransacciones 
                                                WHERE tipo_transaccion = '001'  --Identificador del Abono		
                                                  AND tipo_codigo = nommov.concepto
                                                  AND tipo_empresa = iTipoEmpresa )
					   AND nom.tpo_status = 2   --Es el status de los movimientos
					   AND nommov.status > '1'
					   AND nommov.nombre_archivo =dispersa.nombre_archivo
                       AND  dispersa.f_dispersion=pFecDisp
					   AND dispersa.id_empresa =pIdEmp
					   AND  nommov.nombre_archivo = psNombreArchivo 	--Filtrado por nombre de archivo
						ORDER BY nommov.num_empleado
						
						LET iCont=1;
						RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,
							v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal WITH RESUME;

			  END FOREACH;

		   END IF;
        
		IF(iCont = 0) THEN
				LET v_cCodRet='00002';
				 RETURN  v_cCodRet, v_cNumEmp, v_cApellPaterno, v_cApellMaterno, v_cNombres, v_cCuentaAbono, v_mImporte,  v_cNumCte,  v_cTransaccion,
	                v_cProducto, v_cDesTransacc,  v_cDescStatus, v_iPagadas, v_iNoPagadas, v_cSucursal;
		END IF;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_conciliaciondispersionnomina(pNombreArchivo CHAR(17))
RETURNING CHAR(5),CHAR(18);  
    
    DEFINE v_cCodRet         		CHAR(5);
    DEFINE v_cNumEmpleado    		CHAR(10);
    DEFINE v_cCuentaAbono    		CHAR(20);
    DEFINE v_cNumTarjeta     		CHAR(20);
    DEFINE v_mImporte        		MONEY(18,2);
    DEFINE v_cStatus         		CHAR(1);
    DEFINE v_mComDis         		MONEY(18,2);
    DEFINE v_mIvaDis         		MONEY(18,2);
    DEFINE v_cHoraAplicada   		CHAR(8);
    DEFINE v_cNomArchivo     		CHAR(18);
    DEFINE v_cdirectorio     		CHAR(100);
    DEFINE v_cvsql           		CHAR(600);
    DEFINE vSqlErr           		SMALLINT;
    DEFINE v_iSqlErr         		INTEGER;
    DEFINE cNumeroEmpresa    		CHAR(3);
    DEFINE cFolioDispersion  		CHAR(16);
    DEFINE dFechaAplicado    		Date ;
    DEFINE cHoraAplicado     		DateTime Hour to Second;
    DEFINE cImporteTotalAplicadoCh 	CHAR(19);
    DEFINE cComisionAplicadoCh 		CHAR(19);
    DEFINE cIvaAplicadoCh 			CHAR(19);
    DEFINE sTipoEmpresa   			SMALLINT;
    DEFINE cPunto 					CHAR(1);
    DEFINE cConcepto         		INTEGER;
    
    LET cConcepto  				= 0;
    LET sTipoEmpresa			= 0;
    LET cNumeroEmpresa  		= "";
    LET cFolioDispersion  		= "";
    LET dFechaAplicado  		= '';
    LET cHoraAplicado  			= current;
    LET cImporteTotalAplicadoCh = "";
    LET cComisionAplicadoCh 	= "";
    LET cIvaAplicadoCh 			= "";
    LET v_cCodRet 				= "000";
    LET v_cNumEmpleado 			= "";
    LET v_cCuentaAbono 			= "";
    LET v_cNumTarjeta  			= "";
    LET v_mImporte  			= 0;
    LET v_cStatus 				= "";
    LET v_mComDis 				= 0.00;
    LET v_mIvaDis  				= 0.00;
    LET v_cHoraAplicada 		= "";
    LET v_cNomArchivo  			= "";
    LET v_cdirectorio 			= "";
    LET v_cvsql 				= "";
    LET vSqlErr 				= 0;
    LET v_iSqlErr  				= 0;
    LET cPunto					= "";

    BEGIN
    
    ON EXCEPTION SET vSqlErr
        IF vSqlErr <> 0 THEN
            LET v_cCodRet  = vSqlErr;
            RETURN  v_cCodRet,v_cNomArchivo; --Se quitaron  los valores de retoorno v_mComDis, v_mIvaDis, v_cHoraAplicada ;
        END IF
    END EXCEPTION
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    --- SET DEBUG FILE TO "/tmp/sp_ConciliacionDispersionNomina.out";
    --- TRACE ON;

    IF EXISTS (SELECT dbsname, tabname FROM sysmaster:systabnames WHERE tabname = 'sc_tmpconciliacion_nomina') THEN
        DROP TABLE sc_tmpconciliacion_nomina;
    END IF;

    CREATE TABLE sc_tmpconciliacion_nomina
    (
        empleado      CHAR(10), 
        cuenta        CHAR(20), 
        tarjeta       CHAR(20), 
        importe       MONEY, 
        status        CHAR(1), 
        apell_paterno CHAR(26), 
        apell_materno CHAR(26), 
        nombre1       CHAR(26), 
        nombre2       CHAR(26)
    );

    /* Valida que el nombre de archivo  sea correcto */
    LET cPunto = substr(pNombreArchivo, 14, 1);

    /* Valida el parametro de entrada */
    IF Length(pNombreArchivo) <> 17 or cPunto <> '.' THEN  
        LET v_cCodRet = "110"; /* datos insuficientes */
        DROP TABLE sc_tmpconciliacion_nomina;
        RETURN v_cCodRet,v_cNomArchivo;
    END IF;

    /* Obtener los datos para la generacion del archivo */
    /* Se agrego el nombre del cliente */
    INSERT INTO sc_tmpconciliacion_nomina (empleado, cuenta, tarjeta, importe, status, apell_paterno, apell_materno, nombre1, nombre2)
    SELECT nommov.num_empleado, nommov.cuenta_abono, NVL(tar.num_tarjeta, ''), nommov.importe, nommov.status, nvl(cli.apell_paterno, ''), nvl(cli.apell_materno, ''), nvl(cli.nombre1,''), nvl(cli.nombre2,'')
      FROM bdicheq:sc_nominamovimientos nommov 
      LEFT outer JOIN bdicheq:sc_maechq chq  ON (chq.cuenta = nommov.cuenta_abono)
      LEFT outer JOIN bdinteg:si_cliente cli ON (cli.numcte = chq.num_cte)
      LEFT outer JOIN bdicheq:sc_tarjeta tar ON (tar.empresa = '001' AND tar.numcte = cli.numcte AND tar.cuenta = nommov.cuenta_abono AND tar.tipo_tarjeta = 'T' AND tar.status_tar = 'A')
     WHERE nombre_archivo = pNombreArchivo;

    /* Generar el nombre de archivo .dat */
    LET v_cNomArchivo = "C" || TRIM(pNombreArchivo);

    /* Generar Archivo Plano */
    LET v_cdirectorio = "/tmp/traspasobanco/archivosnomina/conciliacion/originales/" || TRIM(v_cNomArchivo);
    LET v_cvsql = '';
    LET v_cvsql = 'echo "UNLOAD TO ' || TRIM(v_cdirectorio) ||
                  ' SELECT empleado, cuenta, tarjeta, importe, status, apell_paterno, apell_materno, nombre1, nombre2 FROM sc_tmpconciliacion_nomina;" > /tmp/querydisnom.sql';

    SYSTEM v_cvsql;
    LET v_cvsql = '';
    LET v_cvsql = "/ifxsif01/bin/dbaccess bdicheq /tmp/querydisnom.sql "; /* Produccion, se debe quitar lo comentariado cuando pase a produccion */
    --- LET v_cvsql = "dbaccess bdicheq /tmp/querydisnom.sql "; /* Desarrollo, se debe comentar esta linea al pasar a produccion */
    SYSTEM v_cvsql;
    
    /* Obtener los datos para guardar en la tabla  sc_nominaresultadosdispercionautomatica */
    SELECT {+INDEX(bdicheq:sc_nominaencabezadosumario idx_sc_nomencsum)}
           empresa, folio_dispersion, fecha_aplicado, importe_aplicado, comision, iva
      INTO cNumeroEmpresa, cFolioDispersion, dFechaAplicado, cImporteTotalAplicadoCh, cComisionAplicadoCh, cIvaAplicadoCh
      FROM bdicheq:sc_nominaencabezadosumario
     WHERE nombre_archivo = pNombreArchivo 
       AND status in ("2", "3");

    /* Obtiene el tipo de empresa, para de este establecer si pertenece o no al Grupo Coppel, (interna o externa) */
    SELECT tipo_empresa 
      INTO sTipoEmpresa 
      FROM sc_nominaempresas 
     WHERE codigo = cNumeroEmpresa;
    
    /* OBTENER EL CONCEPTO PARA VALIDARLO */
    SELECT {+INDEX(bdicheq:sc_nominamovimientos idx_nominamovimientos1)}
           LIMIT 1 concepto 
      INTO cConcepto 
      FROM bdicheq:sc_nominamovimientos 
      WHERE nombre_archivo = pNombreArchivo;
    
    /* Valida que el tipo de empresa partenece al Grupo Coppel, y guarda los datos del resultado de la dispersion */
    IF sTipoEmpresa < 3  AND cConcepto <> 5 THEN
        INSERT INTO bdicheq:sc_nominaresultadosdispercionautomatica 
        (Codigo_Retorno, Mensaje, Folio_Dispercion, Importe_Total_Aplicado, Comision_Aplicada, Iva_Aplicado, Nombre_Archivo_Conciliacion, hora_aplicado)
        Values(v_cCodRet,'DispersiÃ³n ejecutada correctamente', cFolioDispersion, cImporteTotalAplicadoCh, cComisionAplicadoCh, cIvaAplicadoCh, v_cNomArchivo, cHoraAplicado);
    END IF
    
    --- Se implementara hasta que se modiquen los reportes de nomina. 
    /* 
    --- Guarda historial de la  tabla encabezado sumario
    INSERT INTO sc_nominaencabezadosumariohist (empresa, fecha_gen, folio_archivo, nombre_archivo, sentido, cuenta_cargo, fecha_aplicacion, total_registros,
    importe_tot, status, fecha_insert, importe_aplicado, importe_no_aplicado, folio_acuserecibo, folio_dispersion, iva, comision, fecha_aplicado, hora_aplicado)
    SELECT empresa, fecha_gen, folio_archivo, nombre_archivo, sentido, cuenta_cargo, fecha_aplicacion, total_registros, importe_tot, status, fecha_insert,
    importe_aplicado, importe_no_aplicado, folio_acuserecibo, folio_dispersion, iva, comision, fecha_aplicado, hora_aplicado
    FROM bdicheq:sc_nominaencabezadosumario WHERE nombre_archivo = pNombreArchivo AND status > 1;

    --- Limpia la tabla base de encabezado sumario
    DELETE FROM bdicheq:sc_nominaencabezadosumario WHERE status > 1;

    --- Guarda historial de la tabla de movimientos
    INSERT INTO sc_nominamovimientoshist (nombre_archivo, num_empleado, apell_paterno, apell_materno, nombres, cuenta_abono, importe, concepto, status)
    SELECT nombre_archivo, num_empleado, apell_paterno, apell_materno, nombres, cuenta_abono, importe, concepto, status
    FROM bdicheq:sc_nominamovimientos WHERE nombre_archivo = pNombreArchivo AND status > 0;

    --- Limpia la tabla base de movimientos
    DELETE FROM bdicheq:sc_nominamovimientos WHERE nombre_archivo = pNombreArchivo AND status > 0;
    */
    
    DROP TABLE sc_tmpconciliacion_nomina;
    
    RETURN  v_cCodRet,v_cNomArchivo; /* Se quitaron  los valores de retoorno v_mComDis,   v_mIvaDis, v_cHoraAplicada ; */
    
    END
    
END PROCEDURE

DOCUMENT
'DESCRIPCION: Programa que genera archivo de conciliacion de Nomina,Gastos,Fondo,Capacitacion',
'EJECUTADO O LLAMADO POR: Dispersion de Nomina Automatica/Manual',
'AUTOR: Armando Mercado Figueroa',
'FECHA: 00/2008',
'BD: BDCHEQ',
'CAMBIOS: Se agrego validacion de status a la tarjeta de cliente',
'AUTOR: Armando Mercado Figueroa',
'Fecha: 15/Enero/2009',

'CAMBIOS: valida que la empresa sea externa para registrar en la tabla de dispersion de nomina automatica ',
'y genera un historial de procesos de movimientos y encabezado',
'Modifico: Cristian Valentina Aguilar, Antonio Bastidas Lopez',
'Fecha: 23/Abril/2009',
'BD: BDCHEQ',

'CAMBIOS: Se modifico la tabla temporal para que reciba el nombre del cliente, para que se guarde en el archivo',
'Modifico: Abraham Ayala Aguilar',
'Fecha: 24/Abril/2009',

'CAMBIOS: Se modifico para que cuando el archivo sea de concepto 5 no se mande a la tabla sc_nominaresultadosdispercionautomatica',
'Modifico: CÃ©sar ValdÃ©z Figueroa',
'Fecha: 14/Octubre/2009',
'BD: BDICHEQ',
