	LET vdate 		 = '';
	LET vcliente	 = '';
	
    BEGIN
    
    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET vcodret = sql_err;
            RETURN vcodret;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_basectescat.out";
