    DEFINE dFecha_hoy DATE;
	DEFINE dFecha_Alta DATE;
	DEFINE dFecha_Canc DATE;
	DEFINE dFecha_MesIversario DATE;
	DEFINE dFecha_MesIversario1 DATE;
	DEFINE dFecha_MesIversario2 DATE;
