CREATE PROCEDURE "informix".sp_insertar_registros_indicadores()
RETURNING
	CHAR(6),
	CHAR(80)

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);
	
	DEFINE iUnTercio		INT8;
	DEFINE cCuenta			CHAR(20);
	DEFINE cAnioMesActual	CHAR(6);

	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
	LET cDescRet			= "PROCESO EXITOSO";

	LET iUnTercio			= 0;
	LET cCuenta				= "";
	LET cAnioMesActual		= "";


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_insertar_registros_indicadores.out';
	--TRACE ON;

	SELECT YEAR(fecha_hoy) || LPAD(MONTH(fecha_hoy),2,"0")
	INTO cAnioMesActual
	FROM "informix".sc_fechas
	WHERE empresa = "001";
	
	UPDATE "informix".sc_param
	SET valor = ""
	WHERE empresa = "001"
	AND codparam IN ("CtaInsRegIndic_uno","CtaInsRegIndic_dos");
	
	SELECT (COUNT(*)) / 3
	INTO iUnTercio
	FROM "informix".sc_indicadores
	WHERE cuenta >= "10000005016"
	AND anio_mes = cAnioMesActual;
	
	FOREACH
		SELECT SKIP iUnTercio LIMIT 1 cuenta
		INTO cCuenta
		FROM "informix".sc_indicadores
		WHERE cuenta >= "10000005016"
		AND anio_mes = cAnioMesActual
	
	END FOREACH
	
	UPDATE "informix".sc_param
	SET valor = cCuenta
	WHERE empresa = "001"
	AND codparam = 'CtaInsRegIndic_uno';
	
	LET cCuenta = "";
	
	LET iUnTercio = iUnTercio * 2;
	
	FOREACH
		SELECT SKIP iUnTercio LIMIT 1 cuenta
		INTO cCuenta
		FROM "informix".sc_indicadores
		WHERE cuenta >= "10000005016"
		AND anio_mes = cAnioMesActual
	
	END FOREACH
	
	UPDATE "informix".sc_param
	SET valor = cCuenta
	WHERE empresa = "001"
	AND codparam = "CtaInsRegIndic_dos";
	
	RETURN cCodRet, cDescRet;
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obetener los rangos de las ctas para posteriormente ejecutar tres procesos en paralelo.',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Julio 2014';

CREATE PROCEDURE "informix".sp_conctas_activas_cte(pEmpresa CHAR(3),pNumCte CHAR(9))

	RETURNING
	CHAR(6)		AS CodRet,
	CHAR(20) 	AS NumCta,
	CHAR(4) 	AS NumProd;

	--DEFINICION DE VARIABLES	
	DEFINE cCodRet 		CHAR(6);
	DEFINE cCuenta  	CHAR(20);
	DEFINE cProducto 	CHAR(4);
	DEFINE iSqlErr      INTEGER;

	--INICIALIZACION DE VARIABLES
	LET cCodRet 	= '000000';
	LET cCuenta 	= '';
	LET cProducto 	= '';
	LET iSqlErr 	= 0;	
	
	
	--SET DEBUG FILE TO "/respaldosbd/isarai/sp_conctas_activas.out";
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
		
			IF iSqlErr != 0 THEN
			
				LET cCodRet = iSqlErr;
				RETURN cCodRet, NVL(cCuenta,''), NVL(cProducto,'');
				
			END IF;
			
		END EXCEPTION;

		IF NVL(pEmpresa,'') = '' OR  NVL(pNumCte,'') = '' THEN
		
			LET cCodRet = '000001'; --PARAMETROS VACIOS
			RETURN cCodRet, NVL(cCuenta,''), NVL(cProducto,'');
		
		END IF;
		
		SET LOCK MODE TO WAIT 3;
		
		--SE OBTIENEN LAS CUENTAS DE CAPTACION ACTIVAS DEL CLIENTE
		FOREACH
			
			SELECT mae.cuenta, Mae.producto
			INTO cCuenta, cProducto
			FROM  "informix".sc_maechq Mae
			INNER JOIN  bdicred: "informix".sd_productos_sdoret prod ON (Mae.empresa = prod.empresa 
																	AND mae.producto = prod.num_producto)
			WHERE  Mae.num_cte = pNumCte
			AND Mae.status_cta = '1'
			AND Mae.empresa = Mae.empresa
			AND Mae.empresa = pEmpresa
			ORDER BY mae.cuenta

			RETURN TRIM(cCodRet), TRIM(NVL(cCuenta,'')), TRIM(NVL(cProducto,'')) WITH RESUME;
			
		END FOREACH;
		
		IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
		
			LET cCodRet = '000002'; -- CLIENTE NO TIENE CUENTAS ACTIVAS
			RETURN cCodRet, NVL(cCuenta,''), NVL(cProducto,'');
		
		END IF;
		
	 END
	 
END PROCEDURE
DOCUMENT
'BD : BDICHEQ',
'AUTOR: ISARAI BOJORQUEZ',
'DESCRIPCION:SE CREA PROCEDIMIENTO PARA OBTENER LAS CUENTAS DE CAPTACION ACTIVAS DEL CLIENTE',
'FECHA: 29/07/2014',
'VERSION: 20140729.0942';

CREATE PROCEDURE "informix".sp_cargadividearchivonomina_bpi(pnombrearchivo CHAR(20))
	RETURNING CHAR(5), CHAR(16), CHAR(50);

-------------------------------------------------------------------------------------------------------
--Realizó: Jose Ruben Lopez
--Solicito:Jorge Nuñez
--Fecha: 28/06/2013
--Actividad:Se agrego codigo de retorno del sp_validadatostempnomina_bpi para cuando se repita un empleado en el archivo
--BD:bdicheq.
-------------------------------------------------------------------------------------------------------

---- VARIABLES  GENERALES---
DEFINE cSqlerr			 INTEGER;
DEFINE cCodret      	 CHAR(5);
DEFINE cCodret2      	 CHAR(3);
DEFINE cNombreArchivo    CHAR(23);
DEFINE vsSQL    CHAR(100);
DEFINE cFolio CHAR(16);
DEFINE cRuta CHAR(60);
DEFINE cMensaje CHAR(50);
Define cSQL CHAR(250);
DEFINE cLinea LVARCHAR(500);
DEFINE cBandera CHAR(1);
DEFINE cBan INTEGER;
DEFINE iContador SMALLINT;
DEFINE iNumCaracteres INTEGER;
DEFINE iNumReg INTEGER;
Define cRenglon CHAR(134);
DEFINE dFecha1 DATE;
DEFINE dFecha2 DATE;

--Variables de encabezado
Define cTipoRegistroE CHAR(1);  --clave para identificar registro  (1)
Define cSecuenciaE CHAR(5);      --numero de archivos en el dia
Define cSentidoE CHAR(1);               --control bancoppel
Define cFechaGenE CHAR(8);      --fecha generacion
Define cCuentaCargoE CHAR(16);  --cuenta cargo
Define cFechaAplicE CHAR(8);      --fecha para aplicacion
Define clf_crE CHAR(2);                --control fin de linea

--Variables de detalle
Define cTipoRegistroD CHAR(1);                 --clave para identificar registro  (2)
Define cSecuenciaD CHAR(5); 	          --numero de archivos en el dia
Define cNumeroEmpleadoD CHAR(10);     --clave del empleado
Define cApellidoPaternoD CHAR(30);      --ape del empleado
Define cApellidoMaternoD CHAR(20);    --ape del empleado
Define cNombreD CHAR(30);                  --nombre del empleado
Define cCuentaAbonoD CHAR(18);        --cuenta destino del empleado
Define cConceptoD CHAR(2);                --no existe en el layout, incluirlo para saber el motivo del depósito
Define cImporteD CHAR(18);                   --importe a pagar
Define clf_crD CHAR(2);                          --control fin de linea

--Variables de  sumario
Define cTipoRegistroS CHAR(1);          --clave para identificar registro  (3)
Define cSecuenciaS CHAR(5);           --numero de archivo en el dia
Define cTotalRegistrosS CHAR(5);    --total de empleados que van en el archivo
Define cImporteTotalS CHAR(18);    --total a pagar de los empleados
Define clf_crS CHAR(2);
DEFINE vcomienza SMALLINT; 
DEFINE ven_transacc SMALLINT; 

DEFINE vexiste SMALLINT;
DEFINE vexistehist SMALLINT;

--VALORES INICIALES
LET cSqlerr = '';
LET cCodret = '00000';
LET cCodret2 = '000';
LET cNombreArchivo = '';
LET vsSQL    = '';
LET cFolio = '';
LET cRuta = '';
LET cSQL = '';
LET cLinea = '';
LET cRenglon = '';
LET cBandera = "F";
LET iContador = 0;
LET iNumCaracteres = 0;
LET iNumReg = 0;
LET cBan = 0;
LET dFecha1 = CURRENT;
LET dFecha2 = CURRENT;
LET cMensaje = 'LA APLICACION SE EJECUTO EXITOSAMENTE';

--Variables de encabezado
LET cTipoRegistroE = '';  
LET cSecuenciaE = '';      
LET cSentidoE = '';               
LET cFechaGenE = '';       
LET cCuentaCargoE = '';   
LET cFechaAplicE = '';      
LET clf_crE = '';               

--Variables de detalle
LET cTipoRegistroD = '';                  
LET cSecuenciaD = ''; 	          
LET cNumeroEmpleadoD = '';    
LET cApellidoPaternoD = '';      
LET cApellidoMaternoD = '';    
LET cNombreD = '';                  
LET cCuentaAbonoD = '';       
LET cConceptoD = '';              
LET cImporteD = '';                   
LET clf_crD = '';                      

--Variables de  sumario
LET cTipoRegistroS = '';          
LET cSecuenciaS = '';            
LET cTotalRegistrosS = '';     
LET cImporteTotalS = '';    
LET clf_crS = '';
LET vcomienza = -1;
LET ven_transacc = 0;
LET vexiste = 0;
LET vexistehist = 0;

--SET debug FILE TO "/home/informix/ivonne/sp_cargadividearchivonomina_bpi.out";
--Trace ON;

BEGIN
	------  Control de Errores no Controlados
    ON EXCEPTION SET cSqlerr
        IF cSqlerr <> 0 THEN
            Let cCodret = cSqlerr;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;			
            RETURN cCodret, cFolio, cMensaje;
        END IF;
	END EXCEPTION;
	
	on exception in (-535)
       let ven_transacc = 1;
    end exception with resume;
    
    SELECT COUNT(*)
      INTO vexistehist
      FROM sc_nominaencabezadosumariohist
     WHERE nombre_archivo = pnombrearchivo;
     
    SELECT COUNT(*)
      INTO vexiste
      FROM sc_nominaencabezadosumario
     WHERE nombre_archivo = pnombrearchivo;
     
    IF vexistehist > 0 OR vexiste > 0 THEN
        Let cCodret = '';
        RETURN cCodret, cFolio, cMensaje;
    END IF;
	
	--Se leerá de la tabla de parámetros (pp_parametros), aquellos datos fijos(ruta,  nombre de archivo, número de contrato, etc.).
	SELECT valor INTO cRuta 
	  FROM bdicheq:"informix".sc_param 
	 WHERE empresa = "001" 
	   AND codparam = 'NomRutaDestino_BPI';
	--------------Validar que el archivo exista en la ruta del servidor ---------------------------------------------
	--- BORRAR  LA TABLA DE TEMPORAL EN CASO DE QUE EXISTA
	IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'nomi_tmp_bpi') THEN
		DROP TABLE nomi_tmp_bpi;
	END IF

	--- CREAR LA TABLA DE TEMPORAL
	CREATE TABLE nomi_tmp_bpi (linea LVARCHAR(500));

	LET cSQL = '';
	--- GUARDA LOS NOMBRES DE LOS ARCHIVOS EXISTENTES EN LA RUTA EL CARPETA.CAR
	LET cSQL = 'ls ' || TRIM(cRuta) || ' > ' || TRIM(cRuta) || 'carpeta_bpi.car';
	SYSTEM cSQL;

	IF (vcomienza = -1) THEN
       LET vcomienza = 0;
       BEGIN WORK;
    END IF;
	
	LET cSQL = '';
	--- GUARDA EL QUERY DEL LOAD EN EL ARCHIVO   *.SQL
	LET cSQL = 'echo "LOAD FROM ' || TRIM(cRuta) || 'carpeta_bpi.car' || ' INSERT INTO nomi_tmp_bpi" > '|| TRIM(cRuta) || 'Temporal_bpi.sql';
	SYSTEM cSQL;

	COMMIT WORK;
	BEGIN WORK;
	
	LET cSQL = '';
	--- EJECUTA LAS INSTRUCCIONES QUE ESTAN DENTRO DEL ARCHIVO  *.SQL
	LET cSQL = '/ifxsif01/bin/dbaccess bdicheq ' || TRIM(cRuta) || 'Temporal_bpi.sql';	--LET cSQL = 'dbaccess bdicheq ' || TRIM(cRuta) || 'Temporal_bpi.sql';--se activa para desarrollo
	SYSTEM cSQL;

	COMMIT WORK;
	
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	--- CICLO PARA BUSCAR EL NOMBRE DEL ARCHIVO
	FOREACH
		SELECT linea INTO cLinea FROM nomi_tmp_bpi
		IF cLinea = pNombreArchivo THEN
			LET cBandera = "T";
			EXIT FOREACH;
		END IF
	END FOREACH

	--- BORRAR LA TABLA TEMPORAL
	DROP TABLE nomi_tmp_bpi;

	--- VALIDA QUE EL ARCHIVO EXISTA
	IF cBandera = "F" THEN
		--LET cMensaje = 'El Archivo no Existe en la ruta parametrizada';
		LET cCodret = '191';
		--Obtener los mensajes de retorno 
		SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
		RETURN cCodret, cFolio, cMensaje;
	ELSE
		-----------------------------------	
		--LIMPIAR LAS TABLAS TEMPORALES
		DELETE FROM bdicheq:"informix".sc_NominaArchTemp WHERE num_serial is not null;
		DELETE FROM bdicheq:"informix".sc_nominaencabezadosumariotemp WHERE nombre_archivo = pNombreArchivo;
		DELETE FROM bdicheq:"informix".sc_nominamovimientostemp WHERE nombre_archivo = pNombreArchivo;

		---------Se carga archivo ( LOAD)---------
		Let cSQL = '';
		Let  cSQL = 'echo "load from '||TRIM(cRuta) || TRIM(pNombreArchivo) ||
					' insert into sc_NominaArchTemp(columna); " > '||TRIM(cRuta) ||'querynom_bpi.sql';
		System cSQL;
		Let cSQL = '';
		--Let cSQL = 'dbaccess bdicheq '||TRIM(cRuta) ||'querynom_bpi.sql';  --Se activa para desarrollo   
		Let cSQL = '/ifxsif01/bin/dbaccess bdicheq '||TRIM(cRuta) ||'querynom_bpi.sql ';  --Se activa para Produccion
		System cSQL;
		------------------------------------------------------------------------------------------
		------------------VALIDACIONES SOBRE EL ARCHIVO----------------------
		--- VALIDA QUE NO EXISTAN TIPOS DE REGISTROS AJENOS A LOS AUTORIZADOS
		IF EXISTS(SELECT columna FROM bdicheq:"informix".sc_NominaArchTemp WHERE SUBSTR(columna,1,1) NOT IN ("1","2","3")) THEN
			--Existe un tipo de registro que no es autorizado
			LET cCodret = '175';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		END IF
		--- VALIDA QUE EXISTAN LOS NUEMROS DE REGISTROS CORRESPONDIENTES
		LET iNumReg = 0;
		--- OBTENER EL NUMERO DE REGISTROS DE ENCABEZADO
		SELECT COUNT(*)::INTEGER INTO iNumReg FROM  bdicheq:"informix".sc_NominaArchTemp WHERE SUBSTR(columna,1,1) = "1";
		IF iNumReg = 0 THEN
			--No Existe Encabezado en el archivo
			LET cCodret = '176';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		ELIF iNumReg > 1 THEN
			--Existe mas de un Encabezado en el archivo
			LET cCodret = '177';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		END IF
		LET iNumReg		= 0;
		--- OBTENER EL NUMERO DE REGISTROS DE SUMARIO
		SELECT COUNT(*)::INTEGER INTO iNumReg FROM  bdicheq:"informix".sc_NominaArchTemp WHERE SUBSTR(columna,1,1) = "3";
		IF iNumReg = 0 THEN
			--No Existe Sumario en el archivo
			LET cCodret = '178';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		ELIF iNumReg > 1 THEN
			--Existe mas de un Sumario en el archivo
			LET cCodret = '179';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		END IF
		LET iNumReg		= 0;
		--- OBTENER EL NUMERO DE REGISTROS DE DETALLE
		SELECT COUNT(*)::INTEGER INTO iNumReg FROM  bdicheq:"informix".sc_NominaArchTemp WHERE SUBSTR(columna,1,1) = "2";
		IF iNumReg = 0 THEN
			--No Existe Detalle en el archivo
			LET cCodret = '180';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		END IF
		--- BORRAR  LA TABLA DE TEMPORAL EN CASO DE QUE EXISTA
		IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'Nomi_tmp_secuencia_bpi') THEN
			DROP TABLE Nomi_tmp_secuencia_bpi;
		END IF
		---VALIDAR LA SECUENCIA DE LOS REGISTROS
		--- CREAR LA TABLA DE SECUENCIA
		CREATE TABLE Nomi_tmp_secuencia_bpi (secuencia CHAR(5));
				
		INSERT INTO Nomi_tmp_secuencia_bpi
		SELECT SUBSTR(columna,2,5) AS SECUENCIA FROM  bdicheq:"informix".sc_NominaArchTemp WHERE SUBSTR(columna,1,1) = "2" ;
		---VERIFICAR QUE NO VENGAN REPETIDOS LOS NUMEROS DE SECUENCIA
		IF EXISTS(SELECT SECUENCIA FROM Nomi_tmp_secuencia_bpi GROUP BY SECUENCIA HAVING COUNT(*) > 1) THEN
			DROP TABLE Nomi_tmp_secuencia_bpi;
			--La secuencia en el detalle no es correcta
			LET cCodret = '181';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		END IF
		---BORRAR LA TABLA DE SECUENCIA
		DROP TABLE Nomi_tmp_secuencia_bpi;
		---------Se valida la estructura del archivo---------
		FOREACH
			SELECT columna INTO cRenglon FROM bdicheq:"informix".sc_NominaArchTemp ORDER BY(num_serial)
			--aSIGNACION DE VALORES A LAS VARIABLES
			IF SUBSTR(cRenglon,1,1) = "1" THEN --- ENCABEZADO
				LET cTipoRegistroE = SUBSTR(cRenglon,1,1);  
				LET cSecuenciaE = SUBSTR(cRenglon,2,5);      
				LET cSentidoE = SUBSTR(cRenglon,7,1);               
				LET cFechaGenE = SUBSTR(cRenglon,8,8);       
				LET cCuentaCargoE = SUBSTR(cRenglon,16,16);   
				LET cFechaAplicE = SUBSTR(cRenglon,32,8);      
				--Validar si son nullos
				IF TRIM(cTipoRegistroE) = '' OR (cTipoRegistroE IS null) OR TRIM(cSecuenciaE) = '' OR (cSecuenciaE IS null) OR 
				   TRIM(cSentidoE) = '' OR (cSentidoE IS null) OR TRIM(cFechaGenE) = '' OR (cFechaGenE IS null) OR
				   TRIM(cCuentaCargoE) = '' OR (cCuentaCargoE IS null) OR TRIM(cFechaAplicE) = '' OR (cFechaAplicE IS null)  THEN
					--Error Un valor nULLOS En EL Archivo
					LET cCodret = '182';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				--Validar si son numericos
				IF bdiprog:"informix".isnumeric(cTipoRegistroE) <> '1' OR bdiprog:"informix".isnumeric(cSecuenciaE) <> '1' OR  bdiprog:"informix".isnumeric(cFechaGenE) <> '1' 
					OR bdiprog:"informix".isnumeric(cCuentaCargoE) <> '1' OR bdiprog:"informix".isnumeric(cFechaAplicE) <> '1'THEN
					--Error Un valor No Es  Numerico En Encabezado
					LET cCodret = '183';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				--Validar si son cadenas
				IF bdiprog:"informix".isnumeric(cSentidoE) <> '0' THEN
					--Error Un valor Es  Numerico En Encabezado
					LET cCodret = '184';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				--VALIDAR LAS FECHAS
				IF NOT ((SUBSTR(cFechaGenE,1,2) > 0 AND  SUBSTR(cFechaGenE,1,2) < 13) AND (SUBSTR(cFechaGenE,3,2) > 0 AND SUBSTR(cFechaGenE,3,2) < 32) 
					AND (SUBSTR(cFechaGenE,5,4) > 2000 AND SUBSTR(cFechaGenE,5,4) < 3000 ) )  THEN
					--Error en una fecha  en Encabezado
					LET cCodret = '185';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				--VALIDAR LAS FECHAS
				IF NOT ((SUBSTR(cFechaAplicE,1,2) > 0 AND  SUBSTR(cFechaAplicE,1,2) < 13) AND (SUBSTR(cFechaAplicE,3,2) > 0 AND SUBSTR(cFechaAplicE,3,2) < 32) 
					AND (SUBSTR(cFechaAplicE,5,4) > 2000 AND SUBSTR(cFechaAplicE,5,4) < 3000)) THEN
					--Error en una fecha  en Encabezado
					LET cCodret = '185';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				LET cBan = cBan + 1;
			ELIF SUBSTR(cRenglon,1,1) = "2" THEN --- DETALLE
				LET cTipoRegistroD = SUBSTR(cRenglon,1,1);                  
				LET cSecuenciaD = SUBSTR(cRenglon,2,5); 	          
				LET cNumeroEmpleadoD = SUBSTR(cRenglon,7,10);    
				LET cApellidoPaternoD = SUBSTR(cRenglon,17,30);      
				LET cApellidoMaternoD = SUBSTR(cRenglon,47,20);    
				LET cNombreD = SUBSTR(cRenglon,67,30);                  
				LET cCuentaAbonoD = SUBSTR(cRenglon,97,18);       
				LET cConceptoD = SUBSTR(cRenglon,115,2);              
				LET cImporteD = SUBSTR(cRenglon,117,18);                   
				--Validar si son nullos
				IF TRIM(cTipoRegistroD) = '' OR (cTipoRegistroD IS null) OR TRIM(cSecuenciaD) = '' OR (cSecuenciaD IS null) OR 
				   TRIM(cNumeroEmpleadoD) = '' OR (cNumeroEmpleadoD IS null) OR TRIM(cApellidoPaternoD) = '' OR (cApellidoPaternoD IS null) OR
				   TRIM(cApellidoMaternoD) = '' OR (cApellidoMaternoD IS null) OR TRIM(cNombreD) = '' OR (cNombreD IS null) OR 
				   TRIM(cCuentaAbonoD) = '' OR (cCuentaAbonoD IS null) OR TRIM(cConceptoD) = '' OR (cConceptoD IS null) OR TRIM(cImporteD) = '' 
				   OR (cImporteD IS null) THEN
					--Error Un valor nULLOS En EL Archivo
					LET cCodret = '182';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;				
				--Validar si son numericos
				IF bdiprog:"informix".isnumeric(cTipoRegistroD) <> '1' OR bdiprog:"informix".isnumeric(cSecuenciaD) <> '1' --OR  bdiprog:isnumeric(cNumeroEmpleadoD) <> '1' 
					OR bdiprog:"informix".isnumeric(cCuentaAbonoD) <> '1' OR bdiprog:"informix".isnumeric(cConceptoD) <> '1' OR bdiprog:"informix".isnumeric(cImporteD) <> '1' THEN
					--Error Un valor No Es  Numerico En detalle
					LET cCodret = '187';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				--HAcer el inser a la temporal para una siguiente validacion
				INSERT INTO  bdicheq:"informix".sc_nominamovimientostemp (nombre_archivo, num_empleado, apell_paterno, apell_materno, nombres, cuenta_abono, importe, concepto, status)
				VALUES (pNombreArchivo, cNumeroEmpleadoD, cApellidoPaternoD, cApellidoMaternoD, cNombreD, cCuentaAbonoD, (cImporteD), cConceptoD, '0');
			ELIF SUBSTR(cRenglon,1,1) = "3" THEN --- SUMARIO
				LET cTipoRegistroS = SUBSTR(cRenglon,1,1);          
				LET cSecuenciaS = SUBSTR(cRenglon,2,5);            
				LET cTotalRegistrosS = SUBSTR(cRenglon,7,5);     
				LET cImporteTotalS = SUBSTR(cRenglon,12,18);    
				--Validar si son nullos
				IF TRIM(cTipoRegistroS) = '' OR (cTipoRegistroS IS null) OR TRIM(cSecuenciaS) = '' OR (cSecuenciaS IS null) OR 
				   TRIM(cTotalRegistrosS) = '' OR (cTotalRegistrosS IS null) OR TRIM(cImporteTotalS) = '' OR (cImporteTotalS IS null) THEN
					--Error Un valor nULLOS En EL Archivo
					LET cCodret = '182';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				--Validar si son numericos
				IF bdiprog:"informix".isnumeric(cTipoRegistroS) <> '1' OR bdiprog:"informix".isnumeric(cSecuenciaS) <> '1' OR  bdiprog:"informix".isnumeric(cTotalRegistrosS) <> '1' 
					OR bdiprog:"informix".isnumeric(cImporteTotalS) <> '1' THEN
					--Error Un valor No Es  Numerico En Sumario
					LET cCodret = '189';
					--Obtener los mensajes de retorno 
					SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
					RETURN cCodret, cFolio, cMensaje;
				END IF;
				LET cBan = cBan + 1;
			END IF;
		END FOREACH;
        IF cBan = 2 THEN--06302009   2009-06-30    empresa + fecha + folio (2)     aaaammdd   mmddaaaa
		--LET cFechaFormateada = SUBSTR(cFecha_presentacionD,5,2) ||'/'|| SUBSTR(cFecha_presentacionD,7,2) ||'/'|| SUBSTR(cFecha_presentacionD,1,4);
			INSERT INTO bdicheq:"informix".sc_nominaencabezadosumariotemp (empresa, fecha_gen, folio_archivo, nombre_archivo, sentido, cuenta_cargo, fecha_aplicacion, 
			            total_registros, importe_tot, status, fecha_insert)
			VALUES (SUBSTR(pNombreArchivo,1,3),SUBSTR(cFechaGenE,1,2) ||'/'||SUBSTR(cFechaGenE,3,2) ||'/'|| SUBSTR(cFechaGenE,5,4), 
			        SUBSTR(pNombreArchivo,12,2), pNombreArchivo, cSentidoE, cCuentaCargoE,SUBSTR(cFechaAplicE,1,2) ||'/'||
					SUBSTR(cFechaAplicE,3,2) ||'/'|| SUBSTR(cFechaAplicE,5,4), cTotalRegistrosS, (cImporteTotalS), '0', CURRENT::DATE);
		ELSE
			--No se Obtuvo Encabezado o Suamrio
			LET cCodret = '190';
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio, cMensaje;
		END IF;
       -- Se manda llamar el sp sp_validadatostempnomina
		EXECUTE PROCEDURE BDICHEQ: sp_validadatostempnomina_bpi(SUBSTR(pNombreArchivo,1,3), SUBSTR(cFechaGenE,1,2) ||'/'||SUBSTR(cFechaGenE,3,2) ||'/'||
			    SUBSTR(cFechaGenE,5,4),  SUBSTR(pNombreArchivo,12,2)) INTO cCodret2,cFolio;
		IF cCodret2 <> '000' THEN
			--Error en el sp de valida datos
			--192 - 199
			IF cCodret2 = '600' THEN
				LET cCodret = '192';
			ELIF cCodret2 = '100' THEN
				LET cCodret = '193';
			ELIF cCodret2 = '150' THEN
				LET cCodret = '194';
			ELIF cCodret2 = '200' THEN
				LET cCodret = '195';
			ELIF cCodret2 = '250' THEN
				LET cCodret = '196';
			ELIF cCodret2 = '550' THEN
				LET cCodret = '197';
			ELIF cCodret2 = '551' THEN--Empleado Repetido en el archivo
				LET cCodret = '189';
			ELIF cCodret2 = '300' THEN
				LET cCodret = '198';
			ELIF cCodret2 = '350' THEN
				LET cCodret = '199';
			ELIF cCodret2 = '400' THEN
				LET cCodret = '186';
			ELIF cCodret2 = '450' THEN
				LET cCodret = '188';
			END IF;
			--Obtener los mensajes de retorno 
			SELECT DESCRIPCION INTO cMensaje FROM bdinteg:"informix".si_codret WHERE sistema = '01' AND codigo_retorno = cCodret;
			RETURN cCodret, cFolio,cMensaje;
		END IF;
		--------------------------------------------------------------
	END IF;
	RETURN cCodret, cFolio, cMensaje;
    
    END

END PROCEDURE;

CREATE PROCEDURE "informix".sp_actual_ctaclabe( pempresa CHAR(3), psucursal CHAR(4) )
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcuenta          CHAR(20);
    DEFINE vctaclabe        CHAR(18);    
    DEFINE vnewctaclabe     CHAR(18);
    DEFINE vcodret_ctaclabe CHAR(5);
    
    LET vcodret1         = '000';
    LET vcodret2         = '';
    LET vcodret3         = '';
    LET sql_err	         = 0;
    LET isam_err         = 0;
    LET desc_err         = '';
    LET vcontador1       = 0;
    LET vcontador2       = 0;
    LET vcomienza        = -1;
    LET ven_transacc     = 0;    
    LET vcuenta          = '';
    LET vctaclabe        = '';
    LET vnewctaclabe     = '';
    LET vcodret_ctaclabe = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actual_ctaclabe.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actual_ctaclabe.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH WITH HOLD
        SELECT cuenta, cuenta_clabe
          INTO vcuenta, vctaclabe
          FROM sc_maechq
         WHERE empresa = pempresa
           AND sucursal = psucursal
           AND status_cta <> '2'
           AND producto <> '1100'
        
        IF (vcomienza = -1) THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        
        CALL ctaclabe( pempresa, vcuenta, psucursal )
        RETURNING vcodret_ctaclabe, vnewctaclabe;
        
        IF ( vcodret_ctaclabe = '000' AND ( vctaclabe <> vnewctaclabe ) ) THEN
            UPDATE sc_maechq
               SET cuenta_clabe = vnewctaclabe
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
               
            IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
                LET vcontador2 = vcontador2 + 1;
                COMMIT WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
                BEGIN WORK;
            END IF;
        END IF;
        
        LET vcuenta = '';
        LET vctaclabe = '';
        LET vnewctaclabe = '';
        LET vcodret_ctaclabe = '';
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    END;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2;

END PROCEDURE;

CREATE PROCEDURE "informix".verificatarjetacancelada_transfer(pEmpresa CHAR(3), pNumTarjeta CHAR(16))
	--DATOS A REGRESAR---
	RETURNING
			CHAR(5) AS CodRet;
 
	--DEFINICION DE VARIABLES--
	DEFINE iSqlErr          INTEGER;
    DEFINE sCantReg         SMALLINT;
    DEFINE cCodRet          CHAR(5);
    DEFINE cCodStatusint    CHAR(3);
    DEFINE cCodStatuschq    CHAR(1);

	--INICIALIZACION DE VARIABLES--
	LET iSqlErr        = 0;
	LET sCantReg       = 0;
	LET cCodRet        = "00000";
    LET cCodStatusint  = "";
    LET cCodStatuschq  = "";

--SET DEBUG FILE TO '/respaldosbd/felipe/Sps/verificatarjetacancelada_transfer.out';
--TRACE ON;

BEGIN

	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	IF TRIM(NVL(pEmpresa,'')) <> '' AND TRIM(NVL(pNumTarjeta,''))  <> ''  THEN
	
		SELECT inttar.codstatustarjeta, chqtar.status_tar
		INTO  cCodStatusint, cCodStatuschq
		FROM intercard:"informix".tarjeta inttar,
			bdicheq:"informix".sc_tarjeta chqtar
		WHERE inttar.numtarjeta = chqtar.num_tarjeta 
		AND chqtar.empresa = TRIM(pEmpresa)
		AND chqtar.num_tarjeta = TRIM(pNumTarjeta);
	 
		LET sCantReg = DBINFO("sqlca.sqlerrd2");
		
		IF sCantReg = 0 THEN
			LET cCodRet = "132";
		ELSE	
			IF cCodStatusint <> 'ACT' THEN
				IF cCodStatusint = 'BLT' OR cCodStatusint = 'BLO' OR cCodStatusint = 'NOA' THEN 
					LET cCodRet = "011";
				END IF
			END IF
		END IF
	ELSE
		LET cCodRet = "001";
	END IF

    RETURN cCodRet;
END
END PROCEDURE
DOCUMENT
'FOLIO: 1600',
'AUTOR : 94972834',
'FECHA : 30/06/2014',
'SOLICITA: Rodolfo Gomez',
'BD: bdicheq';

CREATE PROCEDURE "informix".cierrechqra(pempresa CHAR(3))
RETURNING CHAR(5);
    
    --//*******************************************************************
    --
    --      Nombre:                cierrechqra
    --      Version:               1.0.1
    --      Objetivo:              Programa principal cierre cuentas de chequera producto "1900"
    --      Creado por:
    --      ModIFicado por:        Alejandro Rueda Sanchez
    --      Ultima Modificacion:   Junio 2010
    --
    --//*******************************************************************
    
    -- // Definicion de Variables Globales
    DEFINE GLOBAL vgrausuario                   CHAR(8)   DEFAULT " ";
    DEFINE GLOBAL vgraprox_fecha                DATE      DEFAULT " ";
    DEFINE GLOBAL vgrafecha_hoy                 DATE      DEFAULT " ";
    DEFINE GLOBAL vgrapri_hab_mes               DATE      DEFAULT " ";
    DEFINE GLOBAL vgrapri_dia_mes               DATE      DEFAULT " ";
    DEFINE GLOBAL vgrault_hab_mes               DATE      DEFAULT " ";
    DEFINE GLOBAL vgrault_dia_mes               DATE      DEFAULT " ";
    DEFINE GLOBAL vgratrans_pag_int             CHAR(4)   DEFAULT " ";
    DEFINE GLOBAL vgratransisr                  CHAR(4)   DEFAULT " ";
    DEFINE GLOBAL vgratranprov                  CHAR(4)   DEFAULT " ";
    DEFINE GLOBAL vgratranabotrasp              CHAR(4)   DEFAULT " ";
    DEFINE GLOBAL vgratranrevprov               CHAR(4)   DEFAULT " ";
    DEFINE GLOBAL vgraProdCreciente             CHAR(4)   DEFAULT " ";
    DEFINE GLOBAL vgrafecha_mod                 DATE      DEFAULT " ";
    DEFINE GLOBAL vgrafecha_alta                DATE      DEFAULT " ";
    DEFINE GLOBAL vgrastatus_cta                CHAR(1)   DEFAULT " ";
    DEFINE GLOBAL vgratranrecrece               CHAR(4)   DEFAULT " ";

    DEFINE vcuenta                            CHAR(20);
    DEFINE vfcuenta                           CHAR(20);
    DEFINE vtotsuc                            INTEGER;
    DEFINE vcontproc                          INTEGER;
    DEFINE vdiaspri                           INTEGER;
    DEFINE vdias                              INTEGER;
    DEFINE vcodret                            CHAR(5);
    DEFINE vcodret2                           CHAR(5);
    DEFINE vcodret3                           CHAR(50);
    DEFINE vsqlerr                            INTEGER;
    DEFINE vcontprocie                        CHAR(1);
    DEFINE vexiste                            CHAR(1);
    DEFINE vcierre_ejercicio                  SMALLINT;
    DEFINE vproddiv                           CHAR(4);
    DEFINE vfecinidiv                         DATETIME YEAR TO MONTH;
    DEFINE vfecfindiv                         DATETIME YEAR TO MONTH;
    DEFINE vstmt                              CHAR(800);
    DEFINE vfolio_suc                         CHAR(16);
    DEFINE vcontador                          INTEGER;
    DEFINE vregproc                           INTEGER;
    DEFINE vporcentajerror                    INTEGER;
    DEFINE vcontvalcie                        INTEGER;
    DEFINE vregistros                         INTEGER;
    DEFINE vexiste2                           INTEGER;
    DEFINE vexistefin                         INTEGER;
    DEFINE vsistema                           CHAR(2);
    DEFINE vproceso                           CHAR(20);
    DEFINE FechaProc                          DATE;
    DEFINE vProducto                          CHAR(4);
    DEFINE vSucursal                          CHAR(4);
    DEFINE vSdoActual                         DECIMAL(14,2);
    DEFINE isam_err                           SMALLINT;
    DEFINE error_info                         CHAR(40);
    DEFINE vmes                               CHAR(2);
    DEFINE vdia                               CHAR(2);
    DEFINE vanio                              CHAR(4);
    DEFINE vBandNva                           SMALLINT;
    DEFINE vaniomes                           CHAR(6);
    DEFINE vtfechaxxx                         DATE;
    DEFINE vsdo_cuenta                        MONEY(14,2);
    DEFINE vmto_pag_int                       MONEY(14,2);
    DEFINE vfecha_alta                        DATE;
    DEFINE vnumdias                           SMALLINT;
    DEFINE vsdo_actual                        MONEY(14,2);
    DEFINE vimp_chq_sbc						  MONEY(14,2);
    DEFINE vimp_abonos_mes					  MONEY(14,2);
    DEFINE vpago_interes                      CHAR(1);
    DEFINE vacum_sdo_pos                      MONEY(18,2);
    DEFINE vdia_sdo_pos                       SMALLINT;
    DEFINE vult_chq		                      INTEGER;
    DEFINE vfechafin                          DATE;
    DEFINE vfechaini                          DATE;
    DEFINE vfecha_pago                        DATE;
    DEFINE vstatuscierreinv                   CHAR(1);
    DEFINE vstatuscobroreestruc               CHAR(1);
    DEFINE vtprodtmp                          CHAR(4);

    DEFINE vProdEfeChq                        CHAR(4);
    DEFINE vdummy                             CHAR(100);
    DEFINE vProdEmpChq                        CHAR(4);
    DEFINE vProdEmpChqNostro                  CHAR(4);
	DEFINE vProdEfePla                        CHAR(4);
    DEFINE cNumcte							  CHAR(20);
    DEFINE cNumtarj							  CHAR(20);	
    DEFINE iExiste							SMALLINT;
    
    BEGIN
    
    ON EXCEPTION SET vsqlerr, isam_err, error_info
        IF vsqlerr <> 0 THEN
            SET DEBUG FILE TO "/resplogifx/conciliachq/cierrechqra.err";
            TRACE ON;
            
            LET vcodret = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = error_info;
            
            UPDATE bdinteg:"informix".sx_contproc
               SET hora_fin = current hour to fraction,
                   ejecutivo = vgrausuario,
                   status_proc = "C",
                   codret      = vcodret
             WHERE empresa = pempresa
               AND proceso = vproceso
               AND fecha   = vgrafecha_hoy
               AND sistema = vsistema;
            
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/tmp/cierrechqra.out";
    --- TRACE ON;

    LET vgrausuario       = USER;
    LET vcodret           = "000";
    LET vsistema          = "01";
    LET vproceso          = "cierrechqra";
    LET vfcuenta          = '';
    LET vcuenta           = '';
    LET vProdEfeChq       = "1900";
	LET vProdEmpChq       = '2200';
	LET vProdEmpChqNostro = '2700';
	LET vProdEfePla       = '2400';
	LET cNumcte		      = '';
	LET cNumtarj	      = '';
	LET iExiste		      = 0;
    
    SET ISOLATION TO DIRTY READ;
    SET ISOLATION TO COMMITTED READ LAST COMMITTED;
    --- SET PDQPRIORITY 10;
    
    SELECT fecha_hoy,pri_dia_mes,pri_hab_mes,
           ult_dia_mes,ult_hab_mes,prox_fecha
      INTO vgrafecha_hoy,vgrapri_dia_mes,vgrapri_hab_mes,
           vgrault_dia_mes,vgrault_hab_mes,vgraprox_fecha
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    SELECT valor
      INTO vgratrans_pag_int
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranpagint";
    
    SELECT valor
      INTO vgratransisr
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranisr";
    
    SELECT valor
      INTO vgratranprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranprov";
    
    SELECT valor
      INTO vgratranrevprov
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranrevprov";
    
    SELECT valor
      INTO vgratranabotrasp
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "tranabotrasp";
    
    SELECT valor
      INTO vcierre_ejercicio
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "cierre_ejercicio";
    
    SELECT valor
      INTO vgratranrecrece
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "trenocre";
       
    /* #####################################################################################################
    --// VALIDA QUE ESTE FINALIZADO CIERRE DE INVERSIONES
    SELECT status_proc
      INTO vstatuscierreinv
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'CierreInv'
       AND fecha   = vgrafecha_hoy
       AND sistema = '03';
    
    IF vstatuscierreinv is null OR vstatuscierreinv <> 'F' THEN
        LET vcodret = "959";
        
        UPDATE bdinteg:sx_contproc
           SET hora_fin     = current hour to fraction,
               ejecutivo    = vgrausuario,
               status_proc  = "C",
               codret       = vcodret
         WHERE empresa      = pempresa
           AND proceso      = vproceso
           AND fecha        = vgrafecha_hoy
           AND sistema      = vsistema;
           
        RETURN vcodret;
    END IF
    ##################################################################################################### */
        
    /* #####################################################################################################
    -- // VALIDA HAYA FINALIZADO COBRO DE REESTRUCTURA
    SELECT status_proc
      INTO vstatuscobroreestruc
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = 'CobroAutRe'
       AND fecha   = vgrafecha_hoy
       AND sistema = '06';
    
    IF vstatuscobroreestruc is null OR vstatuscobroreestruc <> 'F' THEN
        LET vcodret = "954";
        
        UPDATE bdinteg:sx_contproc
           SET hora_fin     = current hour to fraction,
               ejecutivo    = vgrausuario,
               status_proc  = "C",
               codret       = vcodret
         WHERE empresa      = pempresa
           AND proceso      = vproceso
           AND fecha        = vgrafecha_hoy
           AND sistema      = vsistema;
           
        RETURN vcodret;
    END IF
    ##################################################################################################### */
    
    -- // VALIDA HAYA FINALIZADO RESPALDO
    SELECT 1
      INTO vexiste
      FROM sc_contproc
     WHERE empresa = pempresa
       AND proceso = "respacie"
       AND fecha = vgrafecha_hoy;
    
    IF vexiste is null THEN
        LET vcodret = "965";
    
        UPDATE bdinteg:sx_contproc
           SET hora_fin = current hour to fraction,
               ejecutivo = vgrausuario,
               status_proc = "C",
               codret      = vcodret
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgrafecha_hoy
           AND sistema = vsistema;
    
        RETURN vcodret;
    END IF
    
    SELECT count(*)
      INTO vexiste2
      FROM bdinteg:sx_contproc
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgrafecha_hoy
       AND sistema = vsistema;
    
    IF vexiste2 = 0 THEN
        INSERT INTO bdinteg:sx_contproc VALUES (
        pempresa,vproceso,vgrafecha_hoy,vsistema,"I",
        vgrausuario,current hour to fraction,null,null);
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa = pempresa
           AND proceso = vproceso
           AND fecha   = vgrafecha_hoy
           AND sistema = vsistema
           AND status_proc = "F";
    
        IF vexistefin = 0 THEN
            UPDATE bdinteg:sx_contproc
               SET hora_ini = current hour to fraction,
                   ejecutivo = vgrausuario,
                   status_proc = "I",
                   codret      = vcodret
            WHERE  empresa = pempresa
               AND proceso = vproceso
               AND fecha   = vgrafecha_hoy
               AND sistema = vsistema;
        ELSE
            LET vcodret = "966";
        
            UPDATE bdinteg:sx_contproc
               SET hora_fin = current hour to fraction,
                   ejecutivo = vgrausuario,
                   status_proc = "C",
                   codret      = vcodret
             WHERE empresa = pempresa
               AND proceso = vproceso
               AND fecha   = vgrafecha_hoy
               AND sistema = vsistema;
        
            -- RETURN vcodret;
        END IF
    END IF;
    
    --// Valida no se halla realizado cierre
    SELECT 1
      INTO vexiste
      FROM sc_contproc
     WHERE empresa = pempresa
       AND proceso = "cierreqra"
       AND fecha = vgrafecha_hoy;
    
    IF vexiste  = "1" THEN
        LET vcodret = "966";
        RETURN vcodret;
    END IF
    
    --//Guarda historial de valcierreqra y limpia la tabla
    SELECT count(*)
      INTO vcontvalcie
      FROM sc_valcierreqra
     WHERE empresa = pempresa
       AND cuenta <> '';
        
    IF vcontvalcie <> 0 THEN
        INSERT INTO sc_valcierre_his
        SELECT a.*, b.fecha_ant
          FROM sc_valcierreqra a,
               sc_fechas b
         WHERE a.empresa = pempresa
           AND a.cuenta <> ''
           AND b.empresa = a.empresa;

        DELETE FROM sc_valcierreqra
         WHERE empresa = pempresa
           AND cuenta <> '';
    END IF
    
    -- // Valida se halla efectuado el Pase Contable en Sucursales
    SELECT count(*) 
      INTO vtotsuc
      FROM bdinteg:si_sucursales su
     WHERE empresa = pempresa
       AND tpo_sucursal = "01"
       AND not exists (SELECT fecha 
                         FROM bdinteg:si_feriadsuc fs
                        WHERE fs.empresa = pempresa
                          AND fecha = vgrafecha_hoy
                          AND su.sucursal = fs.sucursal);
    
    SELECT count(*)
      INTO vcontproc
      FROM bdisuc:ss_contproc
     WHERE fecha = vgrafecha_hoy
       AND proceso = "pase";
       
    SET LOCK MODE TO WAIT 2;
    
    -- // Producto de chequeras
    SELECT valor
      INTO vProdEfeChq
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechq";
    
    -- // Producto de chequeras empresarial
    SELECT valor
      INTO vProdEmpChq
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodempchq";
       
	   -- // Producto de chequeras nostro
    SELECT valor
      INTO vProdEmpChqNostro
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefechqnostro";
	   
	   -- // Producto Cuenta Efectiva Platino con chequera
    SELECT valor
      INTO vProdEfePla
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "prodefepla";
	   
    /* ########################################################################################
    -- // Verfica cuentas con status 4 (Inactivas)
    LET vcuenta      = '';
    LET vsdo_cuenta  = 0.00;
    LET vmto_pag_int = 0.00;
    
    FOREACH
        SELECT mae.cuenta, mae.sdo_actual, pro.mto_pag_int
          INTO vcuenta, vsdo_cuenta, vmto_pag_int
          FROM sc_maechq mae,
               sc_producto pro
         WHERE mae.empresa = pempresa
           AND mae.status_cta = '4'
           AND mae.sdo_actual >= pro.mto_pag_int
           AND pro.empresa = mae.empresa
           AND pro.producto = mae.producto
           AND mae.producto IN(vProdEfeChq, vProdEmpChq, vProdEmpChqNostro, vProdEfePla)
           
        IF vsdo_cuenta >= vmto_pag_int THEN
            UPDATE sc_maechq
               SET status_cta = '1',
                   fecha_proceso = vgrafecha_hoy
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
            
            UPDATE sc_maenoc
               SET dia_sdo_pos = 0,
                   acum_sdo_pos = 0.00,
                   int_acum = 0.00,
                   dias_acum_int = 0,
                   acum_sdo_int = 0.00
             WHERE empresa = pempresa
               AND cuenta = vcuenta;
        END IF;
    END FOREACH;
    ######################################################################################## */
    
    -- // Obtiene numero de dias a procesar
    IF vgrafecha_hoy = vgrault_hab_mes THEN
        LET vdias = vgrault_dia_mes - vgrafecha_hoy + 1;
    
        IF vgraprox_fecha > vgrault_dia_mes THEN
            LET vdias = vdias + ((vgraprox_fecha-1) - vgrault_dia_mes);
        END IF
    ELSE
        LET vdias = vgraprox_fecha - vgrafecha_hoy;
    END IF
    
    /* ########################################################
    SELECT control
      INTO vcontprocie
      FROM sc_folsuc
     WHERE empresa = pempresa
       AND control = "2";

    IF vcontprocie is null THEN
        INSERT INTO sc_folsuc values(pempresa,"2","1");
        LET vcontprocie = "1";
    END IF

    IF vcontprocie = "1" THEN
        UPDATE sc_folsuc
           SET control = "2"
         WHERE empresa = pempresa;
    END IF
    ######################################################## */
    
    -- // Obtiene registros a procesar
    SELECT count(*)
      INTO vregproc
      FROM sc_maechq
     WHERE empresa = pempresa
       AND producto IN(vProdEfeChq, vProdEmpChq, vProdEmpChqNostro, vProdEfePla)
       AND status_cta not in("2","6","7","8")
       AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgrafecha_hoy);
    
    -- // Obtiene parametro de porcentajes de error por proceso
    SELECT ROUND(valor)
      INTO vporcentajerror
      FROM sc_param
     WHERE empresa  = pempresa
       AND codparam = "porcentajerror";
    
    -- // Producto Inversion Creciente
    SELECT valor
      INTO vgraProdCreciente
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = "PRODCREC";
        
    LET vfcuenta       = '';
    LET FechaProc      = '';
    LET vProducto      = '';
    LET vSdoActual     = 0.00;
    LET vgrastatus_cta = '';
    LET vSucursal      = '';
    
    -- //+++++++++++++++++++++++++++++++++++++++++++++++++
    -- //+ FOREACH PRINCIPAL DEL CIERRE PARA CHEQUERAS
    -- //+++++++++++++++++++++++++++++++++++++++++++++++++
    FOREACH principal WITH HOLD FOR
        SELECT cuenta, fecha_proceso, producto, sdo_actual, imp_chq_sbc, imp_abonos_mes, status_cta, sucursal, ult_chq
          INTO vfcuenta, FechaProc, vProducto, vSdoActual, vimp_chq_sbc, vimp_abonos_mes, vgrastatus_cta, vSucursal, vult_chq
          FROM sc_maechq
         WHERE empresa = pempresa
           AND producto IN(vProdEfeChq, vProdEmpChq, vProdEmpChqNostro, vProdEfePla)
           AND status_cta not in("2","6","7","8")
           AND (fecha_proceso is null OR fecha_proceso = " " OR fecha_proceso = vgrafecha_hoy)
                
        -- ****************************************************************
        -- Valida el saldo de Cta con Chequera al dia de la Apertura
        -- ****************************************************************
        --- IF vproducto = vProdEfeChq AND FechaProc IS NULL THEN
        IF vproducto = vProdEfeChq THEN
            IF vult_chq = 0 THEN
                -- // Cancela la cuenta, si el cliente no realizó el deposito de apertura
                IF vimp_abonos_mes = 0 and vSdoActual = 0 THEN 
                    UPDATE sc_maechq
                       SET status_cta = "2",
                           fec_cancelac = vgrafecha_hoy,
                           fecha_proceso = vgrafecha_hoy
                     WHERE empresa = pempresa
                       AND cuenta = vfcuenta;
                    
                    SELECT NVL(COUNT(*),0) 
                      INTO iExiste 
                      FROM sc_tarjeta 
                     WHERE empresa = pempresa 
                       AND cuenta = vfcuenta 
                       and status_tar='A'; 
                    
                    IF iExiste > 0 THEN
                        FOREACH
                            SELECT num_tarjeta, numcte 
                              INTO cNumtarj,cNumcte 
                              FROM sc_tarjeta
                             WHERE empresa = pempresa
                               AND cuenta = vfcuenta 
                               AND status_tar='A'
                            
                            UPDATE intercard:tarjeta 
                               SET codstatustarjeta='CAN',
                                   fechaultmodif=CURRENT,
                                   usuarioultmodif='informix'
                             WHERE numcliente=cNumcte 
                               AND numtarjeta=cNumtarj 
                               AND codstatustarjeta='ACT';
                        
                            INSERT INTO intercard:bitacoracancelaciontarjetas(tarjeta,codigoproductotarjeta,fecha,resultado,descripcion,usuario)
                            VALUES(cNumtarj,'501',CURRENT,0,'CANCELACION DE TARJETA','CIERRECH');
                        
                            UPDATE sc_tarjeta 
                               SET status_tar='C' 
                             WHERE empresa = pempresa 
                               AND cuenta = vfcuenta 
                               and status_tar='A';
                        END FOREACH;
                    END IF;	
                    
                    LET vcodret = "000";
                    CONTINUE FOREACH;
            --- ELIF vimp_chq_sbc = 0 and vSdoActual = 0 and vimp_abonos_mes > 0 and chq_dev_obco > 0 THEN
            ---     UPDATE sc_maechq
            ---        SET status_cta = "2",
            ---            fec_cancelac = vgrafecha_hoy,
            ---            fecha_proceso = vgrafecha_hoy
            ---      WHERE empresa = pempresa
            ---        AND cuenta = vfcuenta;
            ---
            ---     LET vcodret = "000";
            ---     CONTINUE FOREACH;
                ELIF (vimp_abonos_mes > 0 or vSdoActual > 0) and vimp_chq_sbc = 0 THEN --//Envia la solicitud de la Primera Chequera
                    CALL bdicntchq:sp_altachequeras(pempresa,vfcuenta,1, "01", vgrausuario)
                    RETURNING vdummy;
                    
                    LET vcodret = "000";
                END IF
            END IF
        ELSE
            CALL bdicntchq:sp_altachequeras(pempresa,vfcuenta,1, "03", vgrausuario)
            RETURNING vdummy;
            LET vcodret = "000";
        END IF
        
        CALL cierrechqra_reg (pempresa, vdias, vfcuenta, vProducto, vSdoActual, vSucursal)
        RETURNING vcodret;
        
        IF vcodret <> "000" THEN
            -- // Conteo de Errores generados por el cierre
            SELECT count(*)
              INTO vcontvalcie
              FROM sc_valcierreqra
             WHERE empresa = pempresa
               AND cuenta <> '';
                
            LET vregistros = round(vregproc * vporcentajerror / 100);
            
            IF vcontvalcie <= vregistros THEN
                CONTINUE FOREACH;
            ELSE
                LET vcodret = "997";
                
                UPDATE bdinteg:sx_contproc
                   SET hora_fin = current hour to fraction,
                       ejecutivo = vgrausuario,
                       status_proc = "C",
                       codret = vcodret
                 WHERE empresa = pempresa
                   AND proceso = vproceso
                   AND fecha = vgrafecha_hoy
                   AND sistema = vsistema;
                
                RETURN vcodret;
            END IF;
        END IF;
    END FOREACH;
        
    SET LOCK MODE TO WAIT 2;
    
    -- // Actualiza saldo y fecha de proceso de cuentas inactivas    
    FOREACH
        SELECT cuenta
          INTO vcuenta
          FROM sc_maechq
         WHERE status_cta = '4'
           AND fecha_proceso < vgrafecha_hoy
           AND producto IN(vProdEfeChq, vProdEmpChq, vProdEmpChqNostro, vProdEfePla)
        
        UPDATE sc_maechq
           SET sdo_dia_ant = sdo_actual
         WHERE empresa = pempresa
           AND cuenta = vcuenta;
    END FOREACH
    
    -- // Actualiza saldo y fecha de proceso de cuentas desconcentradas ART 61 LIC
    FOREACH
        SELECT cuenta
          INTO vcuenta
          FROM sc_maechq
         WHERE status_cta = '8'
           AND fecha_proceso < vgrafecha_hoy
           AND producto IN(vProdEfeChq, vProdEmpChq, vProdEmpChqNostro, vProdEfePla)
        
        UPDATE sc_maechq
           SET sdo_dia_ant = sdo_actual
         WHERE empresa = pempresa
           AND cuenta = vcuenta;
    END FOREACH
    
    --- SET LOCK MODE TO WAIT 2;
    
    -- // Registra fin de cierres
    UPDATE bdinteg:sx_contproc
       SET hora_fin = current hour to fraction,
           status_proc = "F",
           codret      = vcodret
     WHERE empresa = pempresa
       AND proceso = vproceso
       AND fecha   = vgrafecha_hoy
       AND sistema = vsistema;
    
    UPDATE sc_contproc
       SET fecha = vgrafecha_hoy
     WHERE empresa = pempresa
       AND proceso = "cierreqra";
    
    RETURN vcodret;
    
    END
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ctamvl_asociactatel
(
	pTipo		SMALLINT,
	pCte		CHAR(20),
	pCta		CHAR(20),
	pTel		CHAR(10),
	pCarrier	SMALLINT,
	pTransfer	CHAR(1),
	pUsuario	CHAR(8)
)

RETURNING
	CHAR(5) AS cCodRet;
	
	DEFINE cCodRet		CHAR(5);
	DEFINE iSqlErr 		INTEGER;
	
	LET	cCodRet 		= '00000';
	LET iSqlErr			= 0;
		
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
		-- SET DEBUG FILE TO '/tmp/sp_ctamvl_asociactatel.out';
		-- TRACE ON;
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;  
		
		--VALIDAR PARÁMETROS OBLIGATORIOS
			IF pTipo = 1 THEN
				IF NVL(pCte, '') = '' OR NVL(pCta,'') = '' OR NVL(pTel,'') = '' OR NVL(pCarrier,0) = 0 OR NVL(pTransfer,'') = '' OR NVL(pUsuario,'') = '' THEN
					LET cCodRet = '00001';
					RETURN cCodRet;
				END IF 
				
				--Funcionalidad pTipo = 1												 						
				-- VERIFICAR SI EXISTE LA CUENTA EN LA TABLA BDICHEQ:"INFORMIX".SC_CUENTA_TELEFONO.
				IF EXISTS(SELECT cuenta FROM "informix".sc_cuenta_telefono WHERE num_cte = pCte) THEN
					LET cCodRet = '00002';
					RETURN cCodRet;
				END IF
				
				IF EXISTS(SELECT cuenta FROM "informix".sc_cuenta_telefono WHERE cuenta = pCta) THEN
					LET cCodRet = '00002';
					RETURN cCodRet;
				END IF
				
				IF EXISTS(SELECT cuenta FROM "informix".sc_cuenta_telefono WHERE telefono = pTel) THEN
					LET cCodRet = '00002';
					RETURN cCodRet;
				END IF
				
				-- SI NO SE ENCUENTRA LA CUENTA EN LA TABLA SE INSERTA EL REGISTRO EN LA TABLA 	BDICHEQ:"INFORMIX".SC_CUENTA_TELEFONO.
				INSERT INTO "informix".sc_cuenta_telefono (num_cte, cuenta, telefono, canal, es_transfer, user_insert, fecha_hora_insert) 
				VALUES (pCte, pCta, pTel, pCarrier, pTransfer, pUsuario, CURRENT YEAR TO SECOND);						
				
				IF DBINFO("sqlca.sqlerrd2") = 0 THEN
					LET cCodRet = '00003';
				END IF
				
				RETURN cCodRet;
						
			ELIF pTipo = 2 THEN
			--Validar parámetros obligatorios
					--pCte,  pCta,  pTel.
					IF NVL(pCte,'') = '' OR NVL (pCta,'') = '' OR NVL(pTel,'') = '' THEN
						LET cCodRet = '00001';						
						RETURN  cCodRet;
								
					ELSE
						--FUNCIONALIDAD PTIPO = 2
						--PRIMERO SE DEBERÁ INSERTAR EL REGISTRO ACTUAL EN LA TABLA NUEVA BDICHEQ:"INFORMIX".SC_CUENTA_TELEFONO_HIST 
						--PARA RESPALDAR EL REGISTRO EN LA TABLA DE HISTORIAL.						
							
							INSERT INTO "informix".sc_cuenta_telefono_hist
							SELECT num_cte, cuenta, telefono, canal, es_transfer, user_insert, fecha_hora_insert
							FROM "informix".sc_cuenta_telefono
							WHERE num_cte = pCte AND cuenta = pCta AND telefono = pTel;
							
							IF DBINFO("sqlca.sqlerrd2") = 0 THEN
								LET cCodRet = '00003';
							END IF
				
						--DESPUÉS SE ELIMINARA EL REGISTRO EN LA TABLA BDICHEQ:"INFORMIX".SC_CUENTA_TELEFONO.
							DELETE FROM "informix".sc_cuenta_telefono
							WHERE num_cte = pCte AND cuenta = pCta AND telefono = pTel;
							
							IF DBINFO("sqlca.sqlerrd2") = 0 THEN
								LET cCodRet = '00003'; -- NO SE REALIZO EL DELETE DE LA CUENTA MOVIL.
							END IF
							
							RETURN cCodRet;
							
					END IF
						
			ELIF pTipo = 3 THEN
			--VALIDAR PARÁMETROS OBLIGATORIOS
					--pCte,  pCta,  pTel.
					IF NVL(pCte,'') = '' OR NVL (pCta,'') = '' OR NVL (pTel,'') = '' THEN
						LET cCodRet = '00001';						
						RETURN  cCodRet;																
					ELSE	
					--FUNCIONALIDAD PTIPO = 3
						--PRIMERO SE DEBERÁ INSERTAR EL REGISTRO ACTUAL EN LA TABLA NUEVA  	BDICHEQ:"INFORMIX".SC_CUENTA_TELEFONO_HIST --PARA RESPALDAR EL REGISTRO EN LA TABLA DE 	HISTORIAL.
						
							INSERT INTO "informix".sc_cuenta_telefono_hist
							SELECT num_cte, cuenta, telefono, canal, es_transfer, user_insert, fecha_hora_insert
							FROM "informix".sc_cuenta_telefono
							WHERE num_cte = pCte AND cuenta = pCta ; 
						IF DBINFO("sqlca.sqlerrd2") = 0 THEN
							LET cCodRet = '00003'; -- NO SE REALIZO EL INSERT DE LA CUENTA MOVIL.
						END IF
						
						--DESPUÉS SE ACTUALIZARA EL TELÉFONO MÓVIL A LA CUENTA QUE SE SELECCIONO.
						UPDATE "informix".sc_cuenta_telefono
						SET telefono = pTel
						WHERE num_cte = pCte AND cuenta = pCta ;
						
						IF DBINFO("sqlca.sqlerrd2") = 0 THEN
							LET cCodRet = '00003'; -- NO SE REALIZO EL UPDATE DE LA CUENTA MOVIL.
						END IF
						
						RETURN cCodRet;	
					END IF
			ELSE
				LET cCodRet = '00001';
				RETURN cCodRet;				
			END IF				
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que realiza la asociación, desasociación y cambio de un número telefónico a una cuenta de débito previa validación de los parámetros de entrada ',
'AUTOR: Antonio Cebreros Perez',
'FECHA DE CREACION: 08 de Octubre del 2014',
'VERSION: 20141008.1554',
'BD: bdicheq',
'Folio: 1463 - NumMovilCtasSPEI',
'---------------------------------------------------------';

CREATE PROCEDURE "informix".sp_edoctagenerales_central(pempresa CHAR(3), pcuenta CHAR(20), paniomes CHAR(6), ptipo CHAR(1))

	RETURNING CHAR(5), CHAR(45), CHAR(10), CHAR(16), CHAR(18), DATE, DATE,
			  MONEY(14, 2), MONEY(16, 2), MONEY(16, 2), MONEY(16, 2), MONEY(16, 2),
			  MONEY(16, 2), MONEY(14, 2), MONEY(14, 2), MONEY(16, 2), MONEY(16, 2),
			  SMALLINT, DECIMAL(9, 6), CHAR(20), CHAR(107), CHAR(10),
			  CHAR(10), CHAR(30), CHAR(30), CHAR(30), CHAR(30),
			  CHAR(5), CHAR(13), CHAR(20), DATE, CHAR(40), MONEY (15,2), MONEY (16,2), DECIMAL(9,4), MONEY(16,2);
			  

	DEFINE vcodret, cCodPostal CHAR(5);
	DEFINE cNumExt, cNumInt, cNumProducto CHAR(10);
	DEFINE cRFC CHAR(13);
	DEFINE cRFC_alterno CHAR(13);
	DEFINE cNumTarjeta CHAR(16);
	DEFINE cClabe CHAR(18);
	DEFINE cNumcte, cCurp CHAR(20);
	DEFINE cNomCalle, cNomColonia, cNomCiudad, cNomEstado CHAR(30);
	DEFINE cNomSucursal CHAR(40);
	DEFINE cProducto CHAR(45);
	DEFINE cNomcte CHAR(107);
	DEFINE dFechaini, dFechafin, dFechaAlta DATE;
	DEFINE mSaldoAnterior, mSaldoCorte, mAux1, mSaldoPromedio MONEY(14, 2);
	DEFINE mDepositos, mRetiros, mInteresesPagados, mRetencionIsr, mIvaOtrosCargos, mOtrosCargos, mInteresesNetos MONEY(16, 2);
	DEFINE dTasaBruta DECIMAL(9, 6);
	DEFINE iDias, vsec_dir, iAnioMes SMALLINT;
	DEFINE vsqlerr, visamerr INTEGER;
	DEFINE v_mes, v_mes2 CHAR(2);
    DEFINE mSaldoRet MONEY(15,2);
	DEFINE cTipoPersona Char(2);	
	DEFINE mtotOtroscargos MONEY(16,2);
	DEFINE mGat DECIMAL(9,4);
	DEFINE mTotretirosefe MONEY(16,2);
	
	DEFINE cSufijos CHAR(60);

	LET vcodret = "000";
	LET cProducto = "";
	LET cNumProducto = "";
	LET cNumTarjeta = "";
	LET cClabe = "";
	LET cNumcte = "";
	LET cNomcte = "";
	LET cNumExt = "";
	LET cNumInt = "";
	LET cNomCalle = "";
	LET cNomColonia = "";
	LET cNomCiudad = "";
	LET cNomEstado = "";
	LET cCodPostal = "";
	LET cRFC = "";
	LET cCurp = "";
	LET cNomSucursal = "";
	LET dFechaini = "";
	LET dFechafin = "";
	LET dFechaAlta = "";
	LET mSaldoPromedio= 0;
	LET mInteresesNetos = 0;
	LET mSaldoAnterior = 0;
	LET mDepositos = 0;
	LET mRetiros = 0;
	LET mInteresesPagados = 0;
	LET mOtrosCargos = 0;
	LET mIvaOtrosCargos = 0;
	LET mSaldoCorte = 0;
	LET mRetencionIsr = 0;
	LET iDias = 0;
	LET dTasaBruta = 0;
	LET mAux1 = 0;
	LET vsec_dir = 0;
	LET iAnioMes = 0;
	LET pcuenta = TRIM(pcuenta);
	LET mSaldoRet = '';
	LET cTipoPersona = ""; 
	LET mtotOtroscargos= 0;
	LET mGat = 0;
	LET mTotretirosefe = 0;
	LET cRFC_alterno = "";
	
	LET  cSufijos = '';
	
	--SET DEBUG FILE TO "/respaldosbd/josue/sp_edoctagenerales_central.out";
	--TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	BEGIN
    
    ON EXCEPTION SET vsqlerr, visamerr
        IF vsqlerr != 0 THEN
            LET vcodret=vsqlerr;

            RETURN vcodret, cProducto, cNumProducto, cNumTarjeta, cClabe, dFechaini, dFechafin,
                   mSaldoAnterior, mDepositos, mInteresesPagados, mRetiros, mOtrosCargos,
                   mIvaOtrosCargos, mSaldoCorte, mSaldoPromedio, mRetencionIsr, mInteresesNetos,
                   iDias, dTasaBruta, cNumcte, cNomcte, cNumExt,
                   cNumInt, cNomCalle, cNomColonia, cNomCiudad, cNomEstado,
                   cCodPostal, cRFC, cCurp, dFechaAlta, cNomSucursal, mSaldoRet,mtotOtroscargos, mGat, mTotretirosefe;
        END IF;
    END EXCEPTION;

    IF EXISTS (SELECT cuenta 
                 FROM bdicheq:sc_maechq 
                WHERE cuenta = pcuenta) THEN
                
        IF ptipo = '1' THEN
            IF EXISTS (SELECT aniomes 
                         FROM sc_maehis mc 
                        WHERE mc.empresa = pempresa 
                          AND mc.cuenta = pcuenta 
                          AND mc.aniomes = paniomes) THEN
                LET iAnioMes = 1;
            END IF;
        END IF;

        IF ptipo = '0' THEN
            Select tpo_persona 
              Into cTipoPersona 
              From bdinteg:si_cliente 
             Where numcte = (Select num_cte 
                               From bdicheq:sc_maechq 
                              Where empresa = pempresa
                                And cuenta = Trim(pcuenta));	
            
            /* -- Obtener el estado de cuenta -- */
            SELECT TRIM(ap.producto) || ' ' || TRIM(ap.nombre) AS producto, mc.producto,
                   TRIM(mc.num_cte), mc.cuenta_clabe, NVL(mc.fechaini, MDY(1, 1, 1900)), NVL(mc.fechafin, MDY(1, 1, 1900)),
                   NVL(sdo_mes_ant, 0), NVL(totdepositos, 0), NVL(totintpag, 0), NVL(totretiros, 0),
                   NVL(totcomcobrada, 0), NVL(totivacobrado, 0), NVL(sdo_actual, 0), NVL(totisrcobrado, 0),
                   NVL(dia_sdo_pos, 0), (NVL(tasabruta, 0) * 100), NVL(acum_sdo_pos, 0), NVL(sdo_retenido, 0),
                   NVL(tototroscargos,0),	(NVL(gat,0) * 100), nvl(totretirosefec,0)
              INTO cProducto, cNumProducto, cNumcte, cClabe, dFechaini, dFechafin,
                   mSaldoAnterior, mDepositos, mInteresesPagados, mRetiros,
                   mOtrosCargos, mIvaOtrosCargos, mSaldoCorte,
                   mRetencionIsr, iDias, dTasaBruta, mAux1, mSaldoRet, mtotOtroscargos, mGat, mTotretirosefe
              FROM sc_maehis AS mc,
                   sc_producto AS ap
             WHERE mc.empresa = pempresa 
               AND mc.cuenta = pcuenta 
               AND mc.aniomes = paniomes 
               AND mc.empresa = ap.empresa 
               AND mc.producto = ap.producto;
            
            /* -- Persona Fisica -- */
            If Trim(cTipoPersona) = '01' Then 				
                Select num_tarjeta 
                  Into cNumTarjeta 
                  From bdicheq:sc_tarjeta
                 Where empresa = pempresa 
                   And cuenta = pcuenta 
                   And tipo_tarjeta = "T" 
                   And status_tar = "A";
            End If
            
        ELIF ptipo = '1' AND iAnioMes = 0 THEN
        
            LET dFechaini = "";
            LET dFechafin = "";
            LET v_mes = "";
            LET v_mes2 = "";
            
            SELECT TRIM(ap.producto) || ' ' || TRIM(ap.nombre) AS producto, mc.producto, tj.num_tarjeta,
                   TRIM(mc.num_cte), mc.cuenta_clabe, MDY(1, 1, 1900), MDY(1, 1, 1900),
                   NVL(mc.sdo_dia_ant, 0), NVL(mc.depositos_cantidad, 0), 0, NVL(mc.retiros_cantidad, 0),
                   0, 0, NVL(mc.sdo_actual, 0), 0, 0, 0, 0, NVL(sdo_retenido, 0)
              INTO cProducto, cNumProducto, cNumTarjeta, cNumcte, cClabe, dFechaini, dFechafin,
                   mSaldoAnterior, mDepositos, mInteresesPagados, mRetiros,
                   mOtrosCargos, mIvaOtrosCargos, mSaldoCorte,
                   mRetencionIsr, iDias, dTasaBruta, mAux1, mSaldoRet
              FROM sc_maechq AS mc,
                   sc_producto AS ap,
                   sc_tarjeta AS tj
             WHERE mc.empresa = pempresa 
               AND mc.cuenta = pcuenta 
               AND mc.empresa = ap.empresa 
               AND mc.producto = ap.producto 
               AND mc.empresa = tj.empresa 
               AND mc.cuenta = tj.cuenta 
               AND tj.tipo_tarjeta = "T" 
               AND tj.status_tar = "A";
            
            /* -- Verificar cual es la fecha final del ultimo estado de cuenta -- */
            SELECT MAX(fechafin) 
              INTO dFechaini 
              FROM sc_maehis 
             WHERE empresa = pempresa 
               AND cuenta = pcuenta;
            
            LET dFechaini = dFechaini + 1 units day;
                
            IF dFechaini IS NULL THEN
                LET dFechaini = "";
            END IF;
            
            IF dFechafin IS NULL THEN
                LET dFechafin = "";
            END IF;
            
        ELSE
            LET vcodret = "005";
        END IF;

        IF vcodret <> '005' THEN
           /* -- Extrae la Ultima Secuencia de Tipo casa de Direcciones MEL -- */
            SELECT secuencia
              INTO vsec_dir
              FROM bdinteg:si_direcciones_actual
             WHERE numcte = cnumcte 
               AND tipo_dir = 1;
           
            IF vsec_dir IS NULL THEN
                SELECT secuencia
                  INTO vsec_dir
                  FROM bdinteg:si_direcciones_actual
                 WHERE numcte = cnumcte 
                   AND tipo_dir = 2;
                   
                IF vsec_dir IS NULL THEN
                    SELECT secuencia
                      INTO vsec_dir
                      FROM bdinteg:si_direcciones_actual
                     WHERE numcte = cnumcte 
                       AND tipo_dir = 3;
                       
                    IF vsec_dir IS NULL THEN
                        LET vsec_dir = 1;
                    END IF;
                END IF;
            END IF

            IF iDias = 0 THEN
               LET mSaldoPromedio= 0;
            ELSE
               LET mSaldoPromedio= mAux1 / iDias;
            END IF;

            LET mInteresesNetos = mInteresesPagados - mRetencionIsr;

            IF cNumcte IS NULL THEN
                LET vcodret = "003";
                
                SELECT TRIM(ap.producto) || ' ' || TRIM(ap.nombre) AS producto, mc.producto,
                       TRIM(mc.num_cte), mc.cuenta_clabe
                  INTO cProducto, cNumProducto, cNumcte, cClabe
                  FROM sc_maechq AS mc,
                       sc_producto AS ap
                 WHERE mc.empresa = pempresa 
                   AND mc.cuenta = pcuenta 
                   AND mc.empresa = ap.empresa 
                   AND mc.producto = ap.producto;

                SELECT NVL(TRIM(cte.razon_social), "") || ' ' || NVL(TRIM(cte.nombre1), "") || ' ' || NVL(TRIM(cte.nombre2), "") || ' ' || 
                       NVL(TRIM(cte.apell_paterno), "") || ' ' || NVL(TRIM(cte.apell_materno), "") AS nombrex,
                       suc.nombre, cte.fecha_insert, cte.rfc, cte.rfc_alterno, cpf.curp, dir.numeroextcalle, dir.numerointcalle,
                       TRIM(cal.nombrecalle), TRIM(zon.nombrezona), TRIM(ciu.nombre), TRIM(edo.nombre), dir.cod_postal
                  INTO cNomcte, cNomSucursal, dFechaAlta, cRFC, cRFC_alterno, cCurp, cNumExt, cNumInt, cNomCalle,
                       cNomColonia, cNomCiudad, cNomEstado, cCodPostal
                  FROM bdinteg:si_cliente AS cte
                  LEFT JOIN bdinteg:si_ctepf cpf ON (cpf.numcte = cte.numcte)
                  LEFT JOIN bdinteg:si_direcciones_actual AS dir ON (dir.numcte = cte.numcte)
                  LEFT JOIN bdinteg:si_estados AS edo ON (edo.estado = dir.estado AND edo.pais = "001")
                  LEFT JOIN bdinteg:si_ciudades AS ciu ON (ciu.ciudad = dir.ciudad AND ciu.estado = dir.estado AND ciu.pais = "001")
                  LEFT JOIN bdinteg:si_catzonas AS zon ON (zon.numerociudad = dir.numerociudad AND zon.numerocolonia = dir.numerocolonia )
                  LEFT JOIN bdinteg:si_catcalles AS cal ON (cal.numerocalle = dir.numerocalle)
                  LEFT JOIN bdinteg:si_sucursales AS suc ON (suc.sucursal = cte.sucursal)
                 WHERE cte.empresa = pempresa 
                   AND cte.numcte = cNumcte 
                   AND dir.secuencia = vsec_dir;
           
                LET dFechaini = "";
                LET dFechafin = "";
                LET mSaldoAnterior = 0;
                LET mDepositos = 0;
                LET mInteresesPagados = 0;
                LET mRetiros = 0;
                LET mOtrosCargos = 0;
                LET mIvaOtrosCargos = 0;
                LET mSaldoCorte = 0;
                LET mSaldoPromedio = 0;
                LET mRetencionIsr = 0;
                LET mInteresesNetos = 0;
                LET iDias = 0;
                LET dTasaBruta = 0;
            ELSE
                SELECT NVL(TRIM(cte.razon_social), "") || NVL(TRIM(cte.nombre1), "") || ' ' || NVL(TRIM(cte.nombre2), "") || ' ' || 
                       NVL(TRIM(cte.apell_paterno), "") || ' ' || NVL(TRIM(cte.apell_materno), "") AS nombrex,
                       suc.nombre, cte.fecha_insert, cte.rfc, cte.rfc_alterno, cpf.curp, dir.numeroextcalle, dir.numerointcalle,
                       TRIM(cal.nombrecalle), TRIM(zon.nombrezona), TRIM(ciu.nombre), TRIM(edo.nombre), dir.cod_postal
                  INTO cNomcte, cNomSucursal, dFechaAlta, cRFC, cRfC_alterno, cCurp, cNumExt, cNumInt, cNomCalle, cNomColonia,
                       cNomCiudad, cNomEstado, cCodPostal
                  FROM bdinteg:si_cliente AS cte
                  LEFT JOIN bdinteg:si_ctepf AS cpf ON (cpf.numcte = cte.numcte)
                  LEFT JOIN bdinteg:si_direcciones_actual AS dir ON (dir.numcte = cte.numcte)
                  LEFT JOIN bdinteg:si_estados AS edo ON (edo.estado = dir.estado AND edo.pais = "001")
                  LEFT JOIN bdinteg:si_ciudades AS ciu ON (ciu.ciudad = dir.ciudad AND ciu.estado = dir.estado AND ciu.pais = "001")
                  LEFT JOIN bdinteg:si_catzonas AS zon ON (zon.numerociudad = dir.numerociudad AND zon.numerocolonia = dir.numerocolonia )
                  LEFT JOIN bdinteg:si_catcalles AS cal ON (cal.numerocalle = dir.numerocalle)
                  LEFT JOIN bdinteg:si_sucursales AS suc ON (suc.sucursal = cte.sucursal)
                 WHERE cte.empresa = pempresa 
                   AND cte.numcte = cNumcte 
                   AND dir.secuencia = vsec_dir;
            END IF;
        END IF;
    ELSE
        LET vcodret = "100";
    END IF;

	IF cRFC_alterno is not null and cRFC_alterno <> "" THEN
       LET cRFC = cRFC_alterno;
    END IF;	
	
	-- SE OBTINE EL SUBFIJO DE LA EMPRESA Y SE AGREGA AL NOMBRE
	IF cTipoPersona NOT IN('01','03') THEN
		SELECT TRIM(suf.descripcion) 
 		INTO cSufijos
		FROM bdinteg: "informix".si_sufijos suf, bdinteg: "informix".si_ctepm pm
		WHERE pm.empresa = '001'
		AND pm.numcte = cNumcte
		AND suf.codigo = pm.sufijo;
		
		LET cNomcte = TRIM(cNomcte)||" "||TRIM(cSufijos);
	END IF;

	RETURN vcodret, cProducto, cNumProducto, cNumTarjeta, cClabe, dFechaini, dFechafin,
           mSaldoAnterior, mDepositos, mInteresesPagados, mRetiros, mOtrosCargos,
           mIvaOtrosCargos, mSaldoCorte, mSaldoPromedio, mRetencionIsr, mInteresesNetos,
           iDias, dTasaBruta, cNumcte, TRIM(cNomcte), cNumExt,
           cNumInt, cNomCalle, cNomColonia, cNomCiudad, cNomEstado,
           cCodPostal, cRFC, cCurp, dFechaAlta, cNomSucursal, mSaldoRet,mtotOtroscargos, mGat, mTotretirosefe;
           
	END;
    
END PROCEDURE

DOCUMENT
'CAMBIO     : Hector Bojorquez',
'DESCRIPCION: Se modifico para que solo se utilize la consulta de estados de cuenta en central',
'Incidencias',
'FECHA      : Junio 2010',
'VERSION    : 201006',
'BD         : BDICHEQ',
'CAMBIO     : Abigail Vasavilbazo Cañedo',
'DESCRIPCION: Se agregaron 3 campos (tototroscargos, gat, totretirosefec) a la consulta a la sc_maehis y estos mismos se agregaron en el retorno',
'VERSION    : 20101125.0929',
'Folio: 1450',
'*******************************************************',
'Autor: 94912599',
'Fecha: 07/10/2013',
