CREATE PROCEDURE "informix".sp_guardabittascomi_pm(pNumCte CHAR(20),
												pCuenta 			CHAR(20),
												pComision           CHAR(4),
												pTasaRend 			DECIMAL(11,6),
												pSdoPromMM 			MONEY(14,2),
												pMonMinAper 		MONEY(14,2),
												pComCgoNoSmm		MONEY(14,2),
												pComCboAclaNP		MONEY(14,2),
												pComChqGirCob		MONEY(14,2),
												pComInaCta			MONEY(14,2),
												pServTranSpei		MONEY(14,2),
												pServTranTef		MONEY(14,2),
												pServAnualidad		MONEY(14,2),
												pServReenvToken		MONEY(14,2),
												pServReepToken		MONEY(14,2),
												pDispCtaBcoppel		MONEY(14,2),
												pDispCtaOtrobco		MONEY(14,2),
												pDispLinea			MONEY(14,2),
												pUsuarioMod			CHAR(8))
RETURNING 	CHAR(6) AS cCodRet,
			CHAR(100) AS cMensajeRet;

--DECLARACIONES DE VARIABLES Y SU TIPO DE DATO
DEFINE cCodRet    		CHAR(6);
DEFINE iSqlErr    		INTEGER;	
DEFINE cMensajeRet		CHAR(100);
DEFINE cFecha			CHAR(10);		

DEFINE dcTasa_rend       	DECIMAL(14,2);
DEFINE mSdo_prom_mm      	MONEY(14,2);
DEFINE mMon_min_aper        MONEY(14,2);
DEFINE mCom_cgo_no_smm      MONEY(14,2);
DEFINE mCom_cbo_acla_np     MONEY(14,2);
DEFINE mCom_chq_gir_cob     MONEY(14,2);
DEFINE mCom_ina_cta         MONEY(14,2);
DEFINE mServ_tran_spei      MONEY(14,2);
DEFINE mServ_tran_tef   	MONEY(14,2);
DEFINE mServ_anualidad      MONEY(14,2);
DEFINE mServ_reenv_token    MONEY(14,2);
DEFINE mServ_reep_token     MONEY(14,2);
DEFINE mDisp_cta_bcoppel    MONEY(14,2);
DEFINE mDisp_cta_otrobco    MONEY(14,2);
DEFINE mDisp_linea          MONEY(14,2);
DEFINE iSecuen		        INTEGER;	
DEFINE cProd				CHAR(4);
DEFINE cTasa				CHAR(8);
DEFINE dfecha				CHAR(10);

--INICIALIZACIONES DEVALORES DEFAULT DE VARIABLES
LET cCodRet            = '000000';
LET iSqlErr            = 0;	
LET cMensajeRet        = "";
LET cFecha        	   = "";			

LET dcTasa_rend       	 = NULL;
LET mSdo_prom_mm      	 = NULL;
LET mMon_min_aper        = NULL;
LET mCom_cgo_no_smm      = NULL;
LET mCom_cbo_acla_np     = NULL;
LET mCom_chq_gir_cob     = NULL;
LET mCom_ina_cta         = NULL;
LET mServ_tran_spei      = NULL;
LET mServ_tran_tef   	 = NULL;
LET mServ_anualidad      = NULL;
LET mServ_reenv_token    = NULL;
LET mServ_reep_token     = NULL;
LET mDisp_cta_bcoppel    = NULL;
LET mDisp_cta_otrobco    = NULL;
LET mDisp_linea          = NULL;	
LET iSecuen		         = 0;	
LET cProd        	     = "";
LET cTasa				 = "";
LET dfecha				 = "";		
			
	--SET DEBUG FILE TO '/respaldosbd/josue/sp_guardabittascomi_pm.out';
	--TRACE ON;				
			
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr =0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cMensajeRet;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;	
		
		 SELECT fecha_hoy INTO cFecha
         FROM "informix".sc_fechas WHERE empresa = '001';

		IF (NVL(pNumcte,'') = '') OR (NVL(pCuenta,'')='') THEN
			LET cCodRet = '000001';
			LET cMensajeRet = 'PARAMETROS VACIOS';
			
		ELSE
		
			SELECT LIMIT 1 secuencia
			INTO iSecuen
			FROM "informix".sc_bitcomtasserv_pm 
			WHERE num_cte = pNumCte
			AND cuenta = pCuenta
			AND comision_id = pComision;
			
			IF DBINFO('sqlca.sqlerrd2') = 0  THEN	
				IF (pTasaRend <> -1) OR (pSdoPromMM <> -1) OR (pMonMinAper <> -1) OR (pServTranTef <> -1) THEN 					
					SELECT producto INTO cProd
					FROM "informix".sc_maechq 
					WHERE num_cte = pNumCte
					AND cuenta = pCuenta;
				END IF;
				
				IF pTasaRend <> -1 THEN
					SELECT tasa INTO cTasa
					FROM "informix".sc_producto 
					WHERE  producto = cProd;
					
					-- SE TOMA EL VALOR DE LA TASA DE RENDIMIENTO
					SELECT MAX(fecha), valor 
					INTO dfecha,dcTasa_rend
					FROM bdinteg:"informix".si_fechavalor 
					WHERE tasa = cTasa
					GROUP BY valor;
				END IF;
				
				IF pSdoPromMM <> -1 THEN 						
					SELECT sdoprommen INTO mSdo_prom_mm
					FROM "informix".sc_producto 
					WHERE  producto = cProd;     
				END IF;	
				
				IF pMonMinAper <> -1 THEN 
					SELECT mtominape INTO mMon_min_aper
					FROM "informix".sc_producto 
					WHERE  producto = cProd;    
				END IF;		
				
				IF pComCgoNoSmm <> -1 THEN 
					SELECT monto_aplica INTO mCom_cgo_no_smm
					FROM "informix".sc_comisiones 
					WHERE empresa = '001'
					AND comision = '3262';   
				END IF;	
				
				IF pComCboAclaNP <> -1 THEN   
				END IF;		
				
				IF pComChqGirCob <> -1 THEN 
					SELECT monto_aplica INTO mCom_chq_gir_cob
					FROM "informix".sc_comisiones 
					WHERE empresa = '001'
					AND comision = '3228';  
				END IF;			
				
				IF pComInaCta <> -1 THEN
					SELECT monto_aplica INTO mCom_ina_cta
					FROM "informix".sc_comisiones 
					WHERE empresa = '001'
					AND comision = '3232';    
				END IF;

				IF pServTranSpei <> -1 THEN
					-- TRANSFERENCIA SPEI.
					SELECT mnycomision INTO mServ_tran_spei
					FROM bdispei:"informix".tblcomision
					WHERE mnycomision = 5;
				END IF;				
				--TRANSFERENCIA TEF
				IF pServTranTef <> -1 THEN 
					SELECT importe_comision INTO mServ_tran_tef
					FROM bditef:"informix".tef_prod_permitidos
					WHERE cve_producto = cProd
					AND permitido = 'S'
					AND cobra_comision = 'S';
				END IF;
				
				IF pServAnualidad <> -1 THEN 
					--ANUALIDAD DEL SERVICIO.
					SELECT monto_aplica INTO mServ_anualidad
					FROM "informix".sc_comisiones
					WHERE comision = '3270';
				END IF;
				
				IF pServReenvToken <> -1 THEN 
					-- REENVIO DE TOKEN.
					SELECT valor INTO mServ_reenv_token
					FROM bdibpi:"informix".tkn_parametros 
					WHERE id_param = '08';
				END IF;
				
				IF pServReepToken <> -1 THEN 
					-- REPOSICIÓN DE TOKEN.
					SELECT valor INTO mServ_reep_token
					FROM bdibpi:"informix".bpi_param
					WHERE  id_param = '01';
				END IF;
				
				-- COMISION POR DISPERSION DE REGISTRO EN CUENTA BANCOPPEL.
				IF pDispCtaBcoppel <> -1 THEN 
					SELECT monto_fijo INTO mDisp_cta_bcoppel
					FROM bdinteg:"informix".si_transacc
					WHERE numero = '3256';			
				END IF;
				
				-- COMISION POR DISPERSION DE REGISTRO EN CUENTA DE OTRO BANCO.
				IF pDispCtaOtrobco <> -1 THEN 
					SELECT monto_fijo INTO mDisp_cta_otrobco
					FROM bdinteg:"informix".si_transacc
					WHERE numero = '3257';			
				END IF;
				
				-- COMISION POR DISPERSION EN LINEA.
				IF pDispLinea <> -1 THEN 
					SELECT monto_fijo INTO mDisp_linea
					FROM bdinteg:"informix".si_transacc
					WHERE numero = '3255';			
				END IF;

				INSERT INTO "informix".sc_bitcomtasserv_pm (num_cte,cuenta,comision_id,secuencia,tasa_rend,sdo_prom_mm,mon_min_aper,
				com_cgo_no_smm,com_cbo_acla_np,com_chq_gir_cob,com_ina_cta,serv_tran_spei,serv_tran_tef,serv_anualidad,serv_reenv_token,
				serv_reep_token,disp_cta_bcoppel,disp_cta_otrobco,disp_linea,usuario_mod,fecha_oper) 
				VALUES(pNumCte,pCuenta,pComision,1,dcTasa_rend,mSdo_prom_mm,mMon_min_aper,mCom_cgo_no_smm,mCom_cbo_acla_np,mCom_chq_gir_cob,mCom_ina_cta,
				mServ_tran_spei,mServ_tran_tef,mServ_anualidad,mServ_reenv_token,mServ_reep_token,mDisp_cta_bcoppel,
				mDisp_cta_otrobco,mDisp_linea,pUsuarioMod,cFecha);
			END IF;
							
			SELECT MAX(secuencia) + 1
			INTO iSecuen
			FROM "informix".sc_bitcomtasserv_pm 
			WHERE num_cte = pNumCte
			AND cuenta = pCuenta
			AND comision_id = pComision;				
			
			IF pTasaRend 	   <> -1 THEN LET dcTasa_rend       = pTasaRend;      END IF;					
			IF pSdoPromMM 	   <> -1 THEN LET mSdo_prom_mm      = pSdoPromMM;     END IF;					
			IF pMonMinAper 	   <> -1 THEN LET mMon_min_aper     = pMonMinAper;    END IF;					
			IF pComCgoNoSmm    <> -1 THEN LET mCom_cgo_no_smm   = pComCgoNoSmm;   END IF;		
			IF pComCboAclaNP   <> -1 THEN LET mCom_cbo_acla_np  = pComCboAclaNP;  END IF;		
			IF pComChqGirCob   <> -1 THEN LET mCom_chq_gir_cob  = pComChqGirCob;  END IF;						
			IF pComInaCta 	   <> -1 THEN LET mCom_ina_cta      = pComInaCta;     END IF;		
			IF pServTranSpei   <> -1 THEN LET mServ_tran_spei   = pServTranSpei;  END IF;		
			IF pServTranTef    <> -1 THEN LET mServ_tran_tef    = pServTranTef;   END IF;		
			IF pServAnualidad  <> -1 THEN LET mServ_anualidad   = pServAnualidad; END IF;		
			IF pServReenvToken <> -1 THEN LET mServ_reenv_token = pServReenvToken;END IF;				
			IF pServReepToken  <> -1 THEN LET mServ_reep_token  = pServReepToken; END IF;		
			IF pDispCtaBcoppel <> -1 THEN LET mDisp_cta_bcoppel = pDispCtaBcoppel;END IF;		
			IF pDispCtaOtrobco <> -1 THEN LET mDisp_cta_otrobco = pDispCtaOtrobco;END IF;		
			IF pDispLinea      <> -1 THEN LET mDisp_linea       = pDispLinea;     END IF;	
								
			INSERT INTO "informix".sc_bitcomtasserv_pm (num_cte,cuenta,comision_id,secuencia,tasa_rend,sdo_prom_mm,mon_min_aper,
			com_cgo_no_smm,com_cbo_acla_np,com_chq_gir_cob,com_ina_cta,serv_tran_spei,serv_tran_tef,serv_anualidad,serv_reenv_token,
			serv_reep_token,disp_cta_bcoppel,disp_cta_otrobco,disp_linea,usuario_mod,fecha_oper)
			VALUES (pNumCte,pCuenta,pComision,iSecuen,dcTasa_rend,mSdo_prom_mm,mMon_min_aper,mCom_cgo_no_smm,mCom_cbo_acla_np,mCom_chq_gir_cob,mCom_ina_cta,
			mServ_tran_spei,mServ_tran_tef,mServ_anualidad,mServ_reenv_token,mServ_reep_token,mDisp_cta_bcoppel,
			mDisp_cta_otrobco,mDisp_linea,pUsuarioMod,cFecha);
		END IF;
		
		RETURN cCodRet,cMensajeRet;
	END;
END PROCEDURE
DOCUMENT
'Folio: 1409',
'Autor: 94912599 ',
'Fecha: 27/02/2014',
'Descripción: Guarda la bitácora del cambio de tasas y comisiones,este procedimiento solo se deberá ejecutar',
'una vez por comisión modificada para guardar un registro por cada cambio y si es el primer registro de la secuencia',
'insertar primeramente un registro con el valor general pero solo con la comisión que se esta modificando.',
'Sustento: RQM10-360 Param de Comi Emp_firma_color.pdf',
'Solicita: Daniel Mayén Rivas',
'BD:BDICHEQ';

CREATE PROCEDURE "informix".sp_guardatascomi_pm(pNumCte CHAR(20),
												pCuenta 			CHAR(20),
												pTasaRend 			DECIMAL(11,6),
												pSdoPromMM 			MONEY(14,2),
												pMonMinAper 		MONEY(14,2),
												pComCgoNoSmm		MONEY(14,2),
												pComCboAclaNP		MONEY(14,2),
												pComChqGirCob		MONEY(14,2),
												pComInaCta			MONEY(14,2),
												pServTranSpei		MONEY(14,2),
												pServTranTef		MONEY(14,2),
												pServAnualidad		MONEY(14,2),
												pServReenvToken		MONEY(14,2),
												pServReepToken		MONEY(14,2),
												pDispCtaBcoppel		MONEY(14,2),
												pDispCtaOtrobco		MONEY(14,2),
												pDispLinea			MONEY(14,2))
RETURNING 	CHAR(6) AS cCodRet,
			CHAR(100) AS cMensajeRet;

--DECLARACIONES DE VARIABLES Y SU TIPO DE DATO
DEFINE cCodRet    		CHAR(6);
DEFINE iSqlErr    		INTEGER;	
DEFINE cMensajeRet		CHAR(100);
DEFINE cFecha			CHAR(10);		

DEFINE dcTasa_rend       	DECIMAL(14,2);
DEFINE mSdo_prom_mm      	MONEY(14,2);
DEFINE mMon_min_aper        MONEY(14,2);
DEFINE mCom_cgo_no_smm      MONEY(14,2);
DEFINE mCom_cbo_acla_np     MONEY(14,2);
DEFINE mCom_chq_gir_cob     MONEY(14,2);
DEFINE mCom_ina_cta         MONEY(14,2);
DEFINE mServ_tran_spei      MONEY(14,2);
DEFINE mServ_tran_tef   	MONEY(14,2);
DEFINE mServ_anualidad      MONEY(14,2);
DEFINE mServ_reenv_token    MONEY(14,2);
DEFINE mServ_reep_token     MONEY(14,2);
DEFINE mDisp_cta_bcoppel    MONEY(14,2);
DEFINE mDisp_cta_otrobco    MONEY(14,2);
DEFINE mDisp_linea          MONEY(14,2);
DEFINE iBand         		INTEGER;		

--INICIALIZACIONES DEVALORES DEFAULT DE VARIABLES
LET cCodRet            = '000000';
LET iSqlErr            = 0;	
LET cMensajeRet        = "";
LET cFecha        	   = "";			

LET dcTasa_rend       	 = NULL;
LET mSdo_prom_mm      	 = NULL;
LET mMon_min_aper        = NULL;
LET mCom_cgo_no_smm      = NULL;
LET mCom_cbo_acla_np     = NULL;
LET mCom_chq_gir_cob     = NULL;
LET mCom_ina_cta         = NULL;
LET mServ_tran_spei      = NULL;
LET mServ_tran_tef   	 = NULL;
LET mServ_anualidad      = NULL;
LET mServ_reenv_token    = NULL;
LET mServ_reep_token     = NULL;
LET mDisp_cta_bcoppel    = NULL;
LET mDisp_cta_otrobco    = NULL;
LET mDisp_linea          = NULL;
LET iBand         	     = 0;		
			
	--SET DEBUG FILE TO '/respaldosbd/josue/sp_guardatascomi_pm.out';
	--TRACE ON;				
			
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cMensajeRet;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;	
		
		 SELECT fecha_hoy INTO cFecha
         FROM "informix".sc_fechas WHERE empresa = '001';

		IF (NVL(pNumcte,'') = '') OR (NVL(pCuenta,'')='') THEN
			LET cCodRet = '000001';
			LET cMensajeRet = 'PARAMETROS VACIOS';
		ELSE
			SELECT tasa_rend,sdo_prom_mm,mon_min_aper, com_cgo_no_smm,com_cbo_acla_np,com_chq_gir_cob,
			com_ina_cta, serv_tran_spei, serv_tran_tef, serv_anualidad,serv_reenv_token,serv_reep_token, 
			disp_cta_bcoppel,disp_cta_otrobco,disp_linea 
			INTO dcTasa_rend,mSdo_prom_mm,mMon_min_aper,mCom_cgo_no_smm,mCom_cbo_acla_np,mCom_chq_gir_cob,mCom_ina_cta,
			mServ_tran_spei,mServ_tran_tef,mServ_anualidad,mServ_reenv_token,mServ_reep_token,mDisp_cta_bcoppel,
			mDisp_cta_otrobco,mDisp_linea
			FROM "informix".sc_maecomtasserv_pm 
			WHERE num_cte = pNumCte
			AND cuenta = pCuenta;
			
			IF DBINFO('sqlca.sqlerrd2') = 0  THEN	
				LET iBand = 1;				
				LET cMensajeRet = 'SE INSERTO EL REGISTRO';
			END IF;
			
				IF pTasaRend 	   <> -1 THEN LET dcTasa_rend       = pTasaRend;      END IF;					
				IF pSdoPromMM 	   <> -1 THEN LET mSdo_prom_mm      = pSdoPromMM;     END IF;					
				IF pMonMinAper 	   <> -1 THEN LET mMon_min_aper     = pMonMinAper;    END IF;					
				IF pComCgoNoSmm    <> -1 THEN LET mCom_cgo_no_smm   = pComCgoNoSmm;   END IF;		
				IF pComCboAclaNP   <> -1 THEN LET mCom_cbo_acla_np  = pComCboAclaNP;  END IF;		
				IF pComChqGirCob   <> -1 THEN LET mCom_chq_gir_cob  = pComChqGirCob;  END IF;						
				IF pComInaCta 	   <> -1 THEN LET mCom_ina_cta      = pComInaCta;     END IF;		
				IF pServTranSpei   <> -1 THEN LET mServ_tran_spei   = pServTranSpei;  END IF;		
				IF pServTranTef    <> -1 THEN LET mServ_tran_tef    = pServTranTef;   END IF;		
				IF pServAnualidad  <> -1 THEN LET mServ_anualidad   = pServAnualidad; END IF;		
				IF pServReenvToken <> -1 THEN LET mServ_reenv_token = pServReenvToken;END IF;				
				IF pServReepToken  <> -1 THEN LET mServ_reep_token  = pServReepToken; END IF;		
				IF pDispCtaBcoppel <> -1 THEN LET mDisp_cta_bcoppel = pDispCtaBcoppel;END IF;		
				IF pDispCtaOtrobco <> -1 THEN LET mDisp_cta_otrobco = pDispCtaOtrobco;END IF;		
				IF pDispLinea      <> -1 THEN LET mDisp_linea       = pDispLinea;     END IF;	
				
				IF iBand = 0 THEN
					UPDATE "informix".sc_maecomtasserv_pm SET 	tasa_rend 		=  dcTasa_rend , 
																sdo_prom_mm 	=  mSdo_prom_mm, 
																mon_min_aper 	=  mMon_min_aper,
																com_cgo_no_smm 	=  mCom_cgo_no_smm,
																com_cbo_acla_np =  mCom_cbo_acla_np,
																com_chq_gir_cob =  mCom_chq_gir_cob,
																com_ina_cta 	=  mCom_ina_cta,
																serv_tran_spei 	=  mServ_tran_spei,
																serv_tran_tef 	=  mServ_tran_tef, 
																serv_anualidad 	=  mServ_anualidad,
																serv_reenv_token = mServ_reenv_token,
																serv_reep_token  = mServ_reep_token, 
																disp_cta_bcoppel = mDisp_cta_bcoppel, 
																disp_cta_otrobco = mDisp_cta_otrobco,
																disp_linea 		 = mDisp_linea,
																fec_ult_mov_cmspm = cFecha
					WHERE num_cte = pNumCte
					AND cuenta = pCuenta;

					LET cMensajeRet = 'SE ACTUALIZO EL REGISTRO';
				ELSE 
					INSERT INTO "informix".sc_maecomtasserv_pm (num_cte,cuenta,tasa_rend,sdo_prom_mm,mon_min_aper,
					com_cgo_no_smm,com_cbo_acla_np,com_chq_gir_cob,com_ina_cta,serv_tran_spei,serv_tran_tef,serv_anualidad,serv_reenv_token,
					serv_reep_token,disp_cta_bcoppel,disp_cta_otrobco,disp_linea,fech_alta_cmspm,fec_ult_mov_cmspm)
					VALUES (pNumCte,pCuenta,dcTasa_rend,mSdo_prom_mm,mMon_min_aper,mCom_cgo_no_smm,mCom_cbo_acla_np,mCom_chq_gir_cob,mCom_ina_cta,
					mServ_tran_spei,mServ_tran_tef,mServ_anualidad,mServ_reenv_token,mServ_reep_token,mDisp_cta_bcoppel,
					mDisp_cta_otrobco,mDisp_linea,cFecha,cFecha);
				END IF;
		END IF;
		
		RETURN cCodRet,cMensajeRet;
	END;
END PROCEDURE
DOCUMENT
'Folio: 1409',
'Autor: 94912599 ',
'Fecha: 27/02/2014',
'Descripción: Guarda el primer registro o en su caso el cambio de la tasa y comisión que se le aplique',
'determinada cuenta de un cliente.',
'Sustento: RQM10-360 Param de Comi Emp_firma_color.pdf',
'Solicita: Daniel Mayén Rivas',
'BD:BDICHEQ';

CREATE PROCEDURE "informix".sp_consultabittascomi_pm(pCliente CHAR(20), pCuenta CHAR(20),pComision CHAR(4),pFechaInicial CHAR(10),pFechaFinal CHAR(10))
RETURNING 	CHAR(6)  AS cCodRet,
			CHAR(10) AS Fecha,
			CHAR(50) AS Nombre_Comision,
			CHAR(20) AS Cuenta,
			CHAR(30) AS ValorAnterior,
			CHAR(30) AS ValorFinal,
			CHAR(45) AS Nombre_usuario;
			

--DECLARACIONES DE VARIABLES Y SU TIPO DE DATO
DEFINE cCodRet  CHAR(6);
DEFINE iSqlErr  INTEGER;	
DEFINE cDescripcion CHAR(50);
DEFINE cfecha		CHAR(10);
DEFINE iSecuen		INTEGER;
DEFINE cUsu_mod		CHAR(8);
DEFINE cNombre		CHAR(45);
DEFINE dtFecha_ini	DATE;
DEFINE dtFecha_fin	DATE;	
DEFINE cCuenta		CHAR(20);
DEFINE cCod_Comi	CHAR(4);	

DEFINE dcTasa_rend       	DECIMAL(14,2);
DEFINE mSdo_prom_mm      	MONEY(14,2);
DEFINE mMon_min_aper        MONEY(14,2);
DEFINE mCom_cgo_no_smm      MONEY(14,2);
DEFINE mCom_cbo_acla_np     MONEY(14,2);
DEFINE mCom_chq_gir_cob     MONEY(14,2);
DEFINE mCom_ina_cta         MONEY(14,2);
DEFINE mServ_tran_spei      MONEY(14,2);
DEFINE mServ_tran_tef   	MONEY(14,2);
DEFINE mServ_anualidad      MONEY(14,2);
DEFINE mServ_reenv_token    MONEY(14,2);
DEFINE mServ_reep_token     MONEY(14,2);
DEFINE mDisp_cta_bcoppel    MONEY(14,2);
DEFINE mDisp_cta_otrobco    MONEY(14,2);
DEFINE mDisp_linea          MONEY(14,2);
DEFINE mValorAnterior       CHAR(30);
DEFINE mValorFinal          CHAR(30);
DEFINE cCadena		        CHAR(30);
DEFINE i                    INTEGER;
DEFINE ilongi               INTEGER;
DEFINE cPar					CHAR(4);
DEFINE cPar1				CHAR(4);
DEFINE cPar2				CHAR(4);

DEFINE cCadena1		        CHAR(30);
DEFINE i1                   INTEGER;
DEFINE ilongi1              INTEGER;
DEFINE cParc				CHAR(4);
DEFINE cPar11				CHAR(4);
DEFINE cPar21				CHAR(4);

DEFINE dcTasa_rend1       	DECIMAL(14,2);
DEFINE mSdo_prom_mm1      	MONEY(14,2);
DEFINE mMon_min_aper1       MONEY(14,2);
DEFINE mCom_cgo_no_smm1     MONEY(14,2);
DEFINE mCom_cbo_acla_np1    MONEY(14,2);
DEFINE mCom_chq_gir_cob1    MONEY(14,2);
DEFINE mCom_ina_cta1        MONEY(14,2);
DEFINE mServ_tran_spei1     MONEY(14,2);
DEFINE mServ_tran_tef1   	MONEY(14,2);
DEFINE mServ_anualidad1     MONEY(14,2);
DEFINE mServ_reenv_token1   MONEY(14,2);
DEFINE mServ_reep_token1    MONEY(14,2);
DEFINE mDisp_cta_bcoppel1   MONEY(14,2);
DEFINE mDisp_cta_otrobco1   MONEY(14,2);
DEFINE mDisp_linea1         MONEY(14,2);

--INICIALIZACIONES DEVALORES DEFAULT DE VARIABLES
LET cCodRet			= '000000';
LET iSqlErr			= 0;	
LET cDescripcion	= "";	
LET cfecha			= "";	
LET iSecuen		    = 0;
LET cUsu_mod		= "";
LET cNombre			= "";
LET dtFecha_ini    	= "";
LET dtFecha_fin    	= "";	
LET cCuenta	    	= "";	
LET cCod_Comi    	= "";		

LET dcTasa_rend       	 = NULL;
LET mSdo_prom_mm      	 = NULL;
LET mMon_min_aper        = NULL;
LET mCom_cgo_no_smm      = NULL;
LET mCom_cbo_acla_np     = NULL;
LET mCom_chq_gir_cob     = NULL;
LET mCom_ina_cta         = NULL;
LET mServ_tran_spei      = NULL;
LET mServ_tran_tef   	 = NULL;
LET mServ_anualidad      = NULL;
LET mServ_reenv_token    = NULL;
LET mServ_reep_token     = NULL;
LET mDisp_cta_bcoppel    = NULL;
LET mDisp_cta_otrobco    = NULL;
LET mDisp_linea          = NULL;
LET mValorFinal          = NULL;
LET mValorAnterior       = NULL;

LET dcTasa_rend1       	= NULL;
LET mSdo_prom_mm1      	= NULL;
LET mMon_min_aper1      = NULL;
LET mCom_cgo_no_smm1    = NULL;
LET mCom_cbo_acla_np1   = NULL;
LET mCom_chq_gir_cob1   = NULL;
LET mCom_ina_cta1       = NULL;
LET mServ_tran_spei1    = NULL;
LET mServ_tran_tef1   	= NULL;
LET mServ_anualidad1    = NULL;
LET mServ_reenv_token1  = NULL;
LET mServ_reep_token1   = NULL;
LET mDisp_cta_bcoppel1  = NULL;
LET mDisp_cta_otrobco1  = NULL;
LET mDisp_linea1        = NULL;
LET cCadena				= "";
LET i					= 0;
LET ilongi				= 0;
LET cPar				= "";
LET cParc				= "";
LET cPar2				= "";
LET cCadena1			= "";
LET i1					= 0;
LET ilongi1				= 0;
LET cPar1				= "";
LET cPar11				= "";
LET cPar21				= "";
		
	--SET DEBUG FILE TO '/respaldosbd/josue/sp_consultabittascomi_pm.out';
	--TRACE ON;				
			
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cfecha,cDescripcion,pCuenta,mValorAnterior,mValorFinal,cNombre;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;	

		IF NVL(pCliente,'') = '' OR NVL(pFechaInicial,'') = '' OR NVL(pFechaFinal,'') = '' THEN
			LET cCodRet = '000001'; -- 'PARAMETROS VACIOS';
		ELSE	
			LET dtFecha_ini = TO_DATE(pFechaInicial,"%Y-%m-%d");
			LET dtFecha_fin = TO_DATE(pFechaFinal,"%Y-%m-%d");

			FOREACH				
				SELECT cuenta,comision_id,secuencia,tasa_rend,sdo_prom_mm,mon_min_aper,com_cgo_no_smm,com_cbo_acla_np,com_chq_gir_cob,com_ina_cta,serv_tran_spei,
				serv_tran_tef,serv_anualidad,serv_reenv_token,serv_reep_token,disp_cta_bcoppel,disp_cta_otrobco,disp_linea,fecha_oper, usuario_mod
				INTO cCuenta,cCod_Comi,iSecuen,dcTasa_rend,mSdo_prom_mm,mMon_min_aper,mCom_cgo_no_smm,mCom_cbo_acla_np,mCom_chq_gir_cob,mCom_ina_cta,
				mServ_tran_spei,mServ_tran_tef,mServ_anualidad,mServ_reenv_token,mServ_reep_token,mDisp_cta_bcoppel,
				mDisp_cta_otrobco,mDisp_linea,cfecha,cUsu_mod
				FROM "informix".sc_bitcomtasserv_pm 
				WHERE num_cte = pCliente
				AND cuenta = DECODE(pCuenta,'',cuenta,pCuenta)
				AND comision_id = DECODE(pComision,'',comision_id,pComision)
				AND fecha_oper BETWEEN dtFecha_ini AND dtFecha_fin
				ORDER BY fecha_oper,cuenta,comision_id,secuencia
				
				IF NVL(iSecuen,0) > 1 THEN
				
					IF dcTasa_rend IS NOT NULL THEN
						LET cCadena1 = dcTasa_rend;
						LET ilongi1 = LENGTH(cCadena1);
						
						FOR i1 = 1 TO ilongi1
							LET cParc = SUBSTR(cCadena1,i1,1);
							IF cParc = "." THEN
								LET cPar11 = SUBSTR(cCadena1,i1 + 1,2);
								IF cPar11 = "00" THEN
									LET	cPar21 = SUBSTR(cCadena1,1,i1 - 1);								
									LET cCadena1 = TRIM(cpar21)||"% CETES mes anterior";
									LET mValorFinal = cCadena1;
									
								ELSE
									LET mValorFinal = dcTasa_rend||"% CETES mes anterior";
								END IF
							END IF;
						END FOR
						
					END IF;
				
					--IF dcTasa_rend       IS NOT NULL THEN  LET mValorFinal = dcTasa_rend||"% CETES mes anterior";       END IF;					
					IF mSdo_prom_mm      IS NOT NULL THEN  LET mValorFinal = mSdo_prom_mm;      END IF;					
					IF mMon_min_aper 	 IS NOT NULL THEN  LET mValorFinal = mMon_min_aper;     END IF;					
					IF mCom_cgo_no_smm   IS NOT NULL THEN  LET mValorFinal = mCom_cgo_no_smm;   END IF;		
					IF mCom_cbo_acla_np  IS NOT NULL THEN  LET mValorFinal = mCom_cbo_acla_np;  END IF;		
					IF mCom_chq_gir_cob  IS NOT NULL THEN  LET mValorFinal = mCom_chq_gir_cob;  END IF;						
					IF mCom_ina_cta 	 IS NOT NULL THEN  LET mValorFinal = mCom_ina_cta;      END IF;		
					IF mServ_tran_spei   IS NOT NULL THEN  LET mValorFinal = mServ_tran_spei;   END IF;		
					IF mServ_tran_tef    IS NOT NULL THEN  LET mValorFinal = mServ_tran_tef;    END IF;		
					IF mServ_anualidad   IS NOT NULL THEN  LET mValorFinal = mServ_anualidad;   END IF;		
					IF mServ_reenv_token IS NOT NULL THEN  LET mValorFinal = mServ_reenv_token; END IF;				
					IF mServ_reep_token  IS NOT NULL THEN  LET mValorFinal = mServ_reep_token;  END IF;		
					IF mDisp_cta_bcoppel IS NOT NULL THEN  LET mValorFinal = mDisp_cta_bcoppel; END IF;		
					IF mDisp_cta_otrobco IS NOT NULL THEN  LET mValorFinal = mDisp_cta_otrobco; END IF;		
					IF mDisp_linea       IS NOT NULL THEN  LET mValorFinal = mDisp_linea;       END IF;
					
					SELECT tasa_rend,sdo_prom_mm,mon_min_aper,com_cgo_no_smm,com_cbo_acla_np,com_chq_gir_cob,com_ina_cta,serv_tran_spei,
					serv_tran_tef,serv_anualidad,serv_reenv_token,serv_reep_token,disp_cta_bcoppel,disp_cta_otrobco,disp_linea
					INTO dcTasa_rend1,mSdo_prom_mm1,mMon_min_aper1,mCom_cgo_no_smm1,mCom_cbo_acla_np1,mCom_chq_gir_cob1,mCom_ina_cta1,
					mServ_tran_spei1,mServ_tran_tef1,mServ_anualidad1,mServ_reenv_token1,mServ_reep_token1,mDisp_cta_bcoppel1,
					mDisp_cta_otrobco1,mDisp_linea1
					FROM "informix".sc_bitcomtasserv_pm 
					WHERE num_cte = pCliente
					AND cuenta = cCuenta
					AND comision_id = cCod_Comi
					AND secuencia = iSecuen -1;
					
					IF dcTasa_rend1 IS NOT NULL THEN
						LET cCadena = dcTasa_rend1;
						LET ilongi = LENGTH(cCadena);
						
						FOR i = 1 TO ilongi
							LET cPar = SUBSTR(cCadena,i,1);
							IF cPar = "." THEN
								LET cPar1 = SUBSTR(cCadena,i + 1,2);
								IF cPar1 = "00" THEN
									LET	cPar2 = SUBSTR(cCadena, 1,i -1);								
									LET cCadena = TRIM(cPar2)||"% CETES mes anterior";
									LET mValorAnterior = cCadena;									
								ELSE
									LET mValorAnterior = dcTasa_rend1||"% CETES mes anterior";
								END IF
							END IF;
						END FOR
						
					END IF;
				
					--IF dcTasa_rend1       IS NOT NULL THEN  LET mValorAnterior = dcTasa_rend1||"% CETES mes anterior";       END IF;					
					IF mSdo_prom_mm1      IS NOT NULL THEN  LET mValorAnterior = mSdo_prom_mm1;      END IF;					
					IF mMon_min_aper1 	  IS NOT NULL THEN  LET mValorAnterior = mMon_min_aper1;     END IF;					
					IF mCom_cgo_no_smm1   IS NOT NULL THEN  LET mValorAnterior = mCom_cgo_no_smm1;   END IF;		
					IF mCom_cbo_acla_np1  IS NOT NULL THEN  LET mValorAnterior = mCom_cbo_acla_np1;  END IF;		
					IF mCom_chq_gir_cob1  IS NOT NULL THEN  LET mValorAnterior = mCom_chq_gir_cob1;  END IF;						
					IF mCom_ina_cta1 	  IS NOT NULL THEN  LET mValorAnterior = mCom_ina_cta1;      END IF;		
					IF mServ_tran_spei1   IS NOT NULL THEN  LET mValorAnterior = mServ_tran_spei1;   END IF;		
					IF mServ_tran_tef1    IS NOT NULL THEN  LET mValorAnterior = mServ_tran_tef1;    END IF;		
					IF mServ_anualidad1   IS NOT NULL THEN  LET mValorAnterior = mServ_anualidad1;   END IF;		
					IF mServ_reenv_token1 IS NOT NULL THEN  LET mValorAnterior = mServ_reenv_token1; END IF;				
					IF mServ_reep_token1  IS NOT NULL THEN  LET mValorAnterior = mServ_reep_token1;  END IF;		
					IF mDisp_cta_bcoppel1 IS NOT NULL THEN  LET mValorAnterior = mDisp_cta_bcoppel1; END IF;		
					IF mDisp_cta_otrobco1 IS NOT NULL THEN  LET mValorAnterior = mDisp_cta_otrobco1; END IF;		
					IF mDisp_linea1       IS NOT NULL THEN  LET mValorAnterior = mDisp_linea1;       END IF;
					
					IF NVL(cCod_Comi,'') <> '' THEN
						SELECT nombre INTO cDescripcion
						FROM "informix".sc_catcomtasserv_pm  
						WHERE idcomision = cCod_Comi;
					ELSE
						LET cDescripcion = '';
					END IF;				
					
					SELECT nombre INTO cNombre
					FROM bdinteg: "informix".si_ejecut WHERE ejecutivo = cUsu_mod;
					
				RETURN cCodRet,cfecha,cDescripcion,cCuenta,mValorAnterior,mValorFinal,cNombre WITH RESUME;
				END IF; 
				
				LET dcTasa_rend       	 = NULL;
				LET mSdo_prom_mm      	 = NULL;
				LET mMon_min_aper        = NULL;
				LET mCom_cgo_no_smm      = NULL;
				LET mCom_cbo_acla_np     = NULL;
				LET mCom_chq_gir_cob     = NULL;
				LET mCom_ina_cta         = NULL;
				LET mServ_tran_spei      = NULL;
				LET mServ_tran_tef   	 = NULL;
				LET mServ_anualidad      = NULL;
				LET mServ_reenv_token    = NULL;
				LET mServ_reep_token     = NULL;
				LET mDisp_cta_bcoppel    = NULL;
				LET mDisp_cta_otrobco    = NULL;
				LET mDisp_linea          = NULL;
				LET mValorFinal          = NULL;
				LET mValorAnterior       = NULL;

				LET dcTasa_rend1       	= NULL;
				LET mSdo_prom_mm1      	= NULL;
				LET mMon_min_aper1      = NULL;
				LET mCom_cgo_no_smm1    = NULL;
				LET mCom_cbo_acla_np1   = NULL;
				LET mCom_chq_gir_cob1   = NULL;
				LET mCom_ina_cta1       = NULL;
				LET mServ_tran_spei1    = NULL;
				LET mServ_tran_tef1   	= NULL;
				LET mServ_anualidad1    = NULL;
				LET mServ_reenv_token1  = NULL;
				LET mServ_reep_token1   = NULL;
				LET mDisp_cta_bcoppel1  = NULL;
				LET mDisp_cta_otrobco1  = NULL;
				LET mDisp_linea1        = NULL;				
			END FOREACH;
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '000002'; -- NO SE ENCONTRARON REGISTROS.
				RETURN cCodRet,cfecha,cDescripcion,cCuenta,mValorAnterior,mValorFinal,cNombre;
			END IF	
			
		END IF;

	END; 
END PROCEDURE
DOCUMENT
'Folio: 1409',
'Autor: 94912599',
'Fecha: 11/03/2014',
'Descripción: Se crea procedimiento para consultar la bitácora del cambio de tasas y comisiones',
'ya sea por cliente,cte y cuenta o por cte-cuenta-comision',
'Sustento: RQM10-360 Param de Comi Emp_firma_color.pdf',
'Solicita: Daniel Mayén Rivas',
'BD:BDICHEQ';

CREATE PROCEDURE "informix".sp_consultacatcomisiones_pm(pEmpresa CHAR(3),pIdComision CHAR(4))
RETURNING 	CHAR(6) AS cCodRet,
			CHAR(4) AS cComi,
			CHAR(50) AS cDescripcion;

--DECLARACIONES DE VARIABLES Y SU TIPO DE DATO
DEFINE cCodRet  CHAR(6);
DEFINE iSqlErr  INTEGER;	

DEFINE cComi        CHAR(4);
DEFINE cDescripcion CHAR(50);

--INICIALIZACIONES DEVALORES DEFAULT DE VARIABLES
LET cCodRet			= '000000';
LET iSqlErr			= 0;	
LET cComi        	= "";
LET cDescripcion	= "";		
			
	--SET DEBUG FILE TO '/respaldosbd/josue/sp_consultacatcomisiones_pm.out';
	--TRACE ON;				
			
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cComi,cDescripcion;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;	

		IF NVL(pEmpresa,'') = '' THEN
			LET cCodRet = '000001'; -- 'PARAMETROS VACIOS';
		ELSE
			FOREACH
			  SELECT idcomision,nombre INTO cComi,cDescripcion
			  FROM "informix".sc_catcomtasserv_pm  
			  WHERE NVL(idcomision,'') = DECODE(pIdComision,'',idcomision,pIdComision)
			  
			  RETURN cCodRet,cComi,cDescripcion WITH RESUME;
			END FOREACH;
		END IF;

	END; 
END PROCEDURE
DOCUMENT
'Folio: 1409',
'Autor: 94912599 ',
'Fecha: 27/02/2014',
'Descripción: Consulta el catalogo de los diferentes tipos de comisiones que existen ',
'de la tabla sc_catcomtasserv_pm, puede ser de uno por uno mandando el numero de comision deseada',
'y o todos mandando vacia la comision',
'Sustento: RQM10-360 Param de Comi Emp_firma_color.pdf',
'Solicita: Daniel Mayén Rivas',
'BD:BDICHEQ';

CREATE PROCEDURE "informix".sp_corrigecomisiones( pEmpresa CHAR(3) )
RETURNING CHAR(5), INTEGER;
    
    DEFINE cCodRet          CHAR(5);
    DEFINE cCodRet2         CHAR(5);
    DEFINE cCodRet3         CHAR(5);
    DEFINE iSqlErr          INTEGER;
    DEFINE iSamErr          INTEGER;
    DEFINE cDesErr          CHAR(50);
    DEFINE iTransacc        SMALLINT;
    DEFINE iContador        INTEGER;
    DEFINE iSerialCom       INTEGER;
    DEFINE cCuenta          CHAR(20);
    DEFINE cFolioSuc        CHAR(16);
    DEFINE mMontoCom        DECIMAL(14,2);
    DEFINE cCodRetAbo       CHAR(5);
    DEFINE iExisteIva       SMALLINT;
    DEFINE iSerialIva       INTEGER;
    DEFINE mMontoIva        DECIMAL(14,2);
    DEFINE iExisComPend     SMALLINT;
    DEFINE mMontoComPend    DECIMAL(14,2);
    
    LET cCodRet       = '000';
    LET cCodRet2      = '';
    LET cCodRet3      = '';
    LET iSqlErr       = 0;
    LET iSamErr       = 0;
    LET cDesErr       = 0;
    LET iTransacc     = 0;
    LET iContador     = 0;    
    LET iSerialCom    = 0;
    LET cCuenta       = '';
    LET cFolioSuc     = '';
    LET mMontoCom     = 0.00;
    LET cCodRetAbo    = '';
    LET iExisteIva    = 0;
    LET iSerialIva    = 0;
    LET mMontoIva     = 0.00;
    LET iExisComPend  = 0;
    LET mMontoComPend = 0.00;
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_corrigecomisiones.err";
        TRACE ON;
        IF iSqlErr <> 0 THEN
            LET cCodRet  = iSqlErr;
            LET cCodRet2 = iSamErr;
            LET cCodRet3 = cDesErr;
            IF iTransacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN cCodRet, iContador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_corrigecomisiones.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
        
    FOREACH WITH HOLD
        SELECT num_serial, cuenta, folio_suc, monto_tot
          INTO iSerialCom, cCuenta, cFolioSuc, mMontoCom
          FROM sc_movdia
         WHERE transacc = '3290'
           AND cancelad <> 'S'
           AND producto IN('9900','9901','2600','2700','2800','8000')
           
        BEGIN WORK;
        LET iTransacc = 1;
        
        -- // CANCELA TRANSACCION DE COMISION
        UPDATE sc_movdia 
           SET cancelad = 'S'
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta
           AND num_serial = iSerialCom;
        
        -- // ACTUALIZA EL SALDO DE LA CUENTA
        UPDATE sc_maechq
           SET sdo_actual = sdo_actual + mMontoCom
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta;
            
        -- // VERIFICA SI COBRO IVA DE LA COMISION
        SELECT COUNT(*)
          INTO iExisteIva
          FROM sc_movdia
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta
           AND folio_suc = cFolioSuc
           AND transacc = '0260'
           AND cancelad <> 'S';
                   
        IF iExisteIva > 0 THEN
            SELECT num_serial, monto_tot
              INTO iSerialIva, mMontoIva
              FROM sc_movdia
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND folio_suc = cFolioSuc
               AND transacc = '0260'
               AND cancelad <> 'S';
               
            -- // CANCELA TRANSACCION DE IVA
            UPDATE sc_movdia 
               SET cancelad = 'S'
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND num_serial = iSerialIva;
               
            -- // ACTUALIZA EL SALDO DE LA CUENTA
            UPDATE sc_maechq
               SET sdo_actual = sdo_actual + mMontoIva
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta;
        END IF;
        
        -- // VERIFICA SI EL COBRO DE COMISION DEJO COMISION PENDIENTE
        SELECT COUNT(*), SUM(monto_com)
          INTO iExisComPend, mMontoComPend
          FROM sc_detcomis
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta
           AND folio_suc = cFolioSuc
           AND comision = '3290'
           AND fecha_alta = today
           AND estado_com = 'P';
                   
        IF iExisComPend > 0 THEN
            -- // ELIMINA RGISTROS DE COMISION PENDIENTE
            DELETE FROM sc_detcomis
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND folio_suc = cFolioSuc
               AND comision = '3290'
               AND fecha_alta = today
               AND estado_com = 'P';
               
            -- // ACTUALIZA EL SALDO DE LA CUENTA Y LA COMISION PENDIENTE
            UPDATE sc_maechq 
               SET sdo_actual = sdo_actual + mMontoComPend,
                   com_pendiente = com_pendiente - mMontoComPend
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta;
        END IF;
        
        LET iContador = iContador + 1;
        
        COMMIT WORK;
        LET iTransacc = 0;
        
        LET iSerialCom    = 0;
        LET cCuenta       = '';
        LET cFolioSuc     = '';
        LET mMontoCom     = 0.00;
        LET cCodRetAbo    = '';
        LET iExisteIva    = 0;
        LET iSerialIva    = 0;
        LET mMontoIva     = 0.00;
        LET iExisComPend  = 0;
        LET mMontoComPend = 0.00;
    END FOREACH;
    
    END;
    
    RETURN cCodRet, iContador; 
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_corrigecomisionescomp( pEmpresa CHAR(3) )
RETURNING CHAR(5), INTEGER;
    
    DEFINE cCodRet          CHAR(5);
    DEFINE cCodRet2         CHAR(5);
    DEFINE cCodRet3         CHAR(5);
    DEFINE iSqlErr          INTEGER;
    DEFINE iSamErr          INTEGER;
    DEFINE cDesErr          CHAR(50);
    DEFINE iTransacc        SMALLINT;
    DEFINE iContador        INTEGER;
    DEFINE cCuenta          CHAR(20);
    DEFINE cFolioSuc        CHAR(16);
    DEFINE mMontoCom        DECIMAL(14,2);
    DEFINE cCodRetAbo       CHAR(5);
    DEFINE iExisteIva       SMALLINT;
    DEFINE iSerialIva       INTEGER;
    DEFINE mMontoIva        DECIMAL(14,2);
    DEFINE iExisComPend     SMALLINT;
    DEFINE mMontoComPend    DECIMAL(14,2);
    DEFINE cHora            CHAR(15);
    DEFINE cFolio           CHAR(16);
    
    LET cCodRet       = '000';
    LET cCodRet2      = '';
    LET cCodRet3      = '';
    LET iSqlErr       = 0;
    LET iSamErr       = 0;
    LET cDesErr       = 0;
    LET iTransacc     = 0;
    LET iContador     = 0;    
    LET cCuenta       = '';
    LET cFolioSuc     = '';
    LET mMontoCom     = 0.00;
    LET cCodRetAbo    = '';
    LET iExisteIva    = 0;
    LET mMontoIva     = 0.00;
    LET iExisComPend  = 0;
    LET mMontoComPend = 0.00;
    LET cHora         = '';
    LET cFolio        = '';
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_corrigecomisionescomp.err";
        TRACE ON;
        IF iSqlErr <> 0 THEN
            LET cCodRet  = iSqlErr;
            LET cCodRet2 = iSamErr;
            LET cCodRet3 = cDesErr;
            IF iTransacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN cCodRet, iContador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_corrigecomisionescomp.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // OBTIENE CUENTAS COBRO DE COMISION 3290
    SELECT UNIQUE cuenta 
      FROM sc_movhis  
     WHERE fech_alt = '06/01/2015' 
       AND transacc = '3290'
       AND cancelad <> 'S'
      INTO TEMP ctaspmxcobmal WITH NO LOG;
    CREATE INDEX idxtmp_comcobmal ON ctaspmxcobmal(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE ctaspmxcobmal;
    
    -- // GENERA FOLIO PARA TRANSACCIONES DE ABONO
    LET cHora = CURRENT HOUR TO FRACTION;
    LET cFolio = 'informix'||cHora[1,2]||cHora[4,5]||cHora[7,8]||cHora[10,11];
    
    FOREACH WITH HOLD
        SELECT mae.cuenta
          INTO cCuenta
          FROM ctaspmxcobmal tmp, 
               sc_maehis mae
         WHERE mae.empresa = pEmpresa
           AND mae.cuenta = tmp.cuenta
           AND mae.fechaini = '05/01/2015'
           AND mae.fechafin = '05/31/2015'
           AND mae.dia_sdo_pos > 0
           AND ( mae.acum_sdo_pos / mae.dia_sdo_pos ) >= 2000.00
        
        BEGIN WORK;
        LET iTransacc = 1;
        
        -- // BONIFICA COBRO DE COMISION
        FOREACH WITH HOLD
            SELECT folio_suc, monto_tot
              INTO cFolioSuc, mMontoCom
              FROM sc_movhis
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND fech_alt >= '06/01/2015'
               AND cancelad <> 'S'
               AND transacc = '3290'
            UNION ALL
            SELECT folio_suc, monto_tot
              FROM sc_movdia
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND fech_alt = today 
               AND cancelad <> 'S'
               AND transacc = '3290'
           
            CALL abono_ref( pEmpresa, '9250', 'informix', '0263', '0000', cFolio, cCuenta, 0, mMontoCom, mMontoCom, 0, 0, 0, '01', 'BONIFICACION COMISION POR BAJO PROMEDIO', '', '' )
            RETURNING cCodRetAbo;
        
            -- // VERIFICA SI COBRO IVA DE LA COMISION PARA BONIFICARLO
            SELECT COUNT(*), SUM(monto_tot)
              INTO iExisteIva, mMontoIva
              FROM sc_movhis
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND folio_suc = cFolioSuc
               AND transacc = '0260'
               AND cancelad <> 'S';
               
            IF iExisteIva = 0 THEN
                SELECT COUNT(*), SUM(monto_tot)
                  INTO iExisteIva, mMontoIva
                  FROM sc_movdia
                 WHERE empresa = pEmpresa
                   AND cuenta = cCuenta
                   AND folio_suc = cFolioSuc
                   AND transacc = '0260'
                   AND cancelad <> 'S';
            END IF;
                       
            IF iExisteIva > 0 THEN
                CALL abono_ref( pEmpresa, '9250', 'informix', '0263', '0000', cFolio, cCuenta, 0, mMontoIva, mMontoIva, 0, 0, 0, '01', 'BONIFICACION IVA COMISION', '', '' )
                RETURNING cCodRetAbo;
            END IF;
            
            LET cFolioSuc     = '';
            LET mMontoCom     = 0.00;
            LET iExisteIva    = 0;
            LET mMontoIva     = 0.00;
            LET cCodRetAbo    = '';
        END FOREACH;
        
        -- // VERIFICA SI EL COBRO DE COMISION DEJO COMISION PENDIENTE
        SELECT COUNT(*), SUM(monto_com)
          INTO iExisComPend, mMontoComPend
          FROM sc_detcomis
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta
           AND comision = '3290'
           AND fecha_alta >= '06/01/2015'
           AND estado_com = 'P';
               
        IF iExisComPend > 0 THEN
            -- // ELIMINA REGISTROS DE COMISION PENDIENTE
            DELETE FROM sc_detcomis
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta
               AND comision = '3290'
               AND fecha_alta >= '06/01/2015'
               AND estado_com = 'P';
               
            -- // ACTUALIZA LA COMISION PENDIENTE EN EL MAESTRO DE CHEQUES
            UPDATE sc_maechq 
               SET com_pendiente = com_pendiente - mMontoComPend
             WHERE empresa = pEmpresa
               AND cuenta = cCuenta;
        END IF;
        
        LET iContador = iContador + 1;
        
        COMMIT WORK;
        LET iTransacc = 0;
        
        LET cCuenta = '';
        LET iExisComPend = 0;
        LET mMontoComPend = 0.00;
    END FOREACH;
    
    END;
    
    RETURN cCodRet, iContador; 
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_pasamovsret( pempresa CHAR(3) )
RETURNING CHAR(5);
    
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
	DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE vabierto     CHAR(1);
    DEFINE vcomienza    SMALLINT;
    DEFINE vcuenta      CHAR(20); 
    DEFINE vfolio_suc   CHAR(16); 
    DEFINE vfecha_alta  DATE;
    DEFINE vtransacc    CHAR(4);
    DEFINE vmonto_ori   MONEY(14,2);
    DEFINE vmincta      CHAR(20);
    DEFINE vmaxcta      CHAR(20);
    
    LET sql_err	    = 0;
    LET isam_err    = 0;
    LET desc_err    = '';
	LET vcodret1    = '';
    LET vcodret2    = '';
    LET vcodret3    = '';
    LET vabierto    = '0';
    LET vcomienza   = -1;
    LET vcuenta     = '';
    LET vfolio_suc  = '';
    LET vfecha_alta = '';
    LET vtransacc   = '';
    LET vmonto_ori  = 0;
    LET vmincta     = '';
    LET vmaxcta     = '';
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_pasamovsret.err";
        TRACE ON;
        IF sql_err <> 0 THEN
			LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_pasamovsret.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT MIN(cuenta), MAX(cuenta)
      INTO vmincta, vmaxcta
      FROM sc_docret;
    
    -- // DEPURA REGISTROS DE LA sc_docret
    FOREACH cursor_depura WITH HOLD FOR      
        SELECT cuenta, folio_suc, fecha_alta, transacc, monto_ori
          INTO vcuenta, vfolio_suc, vfecha_alta, vtransacc, vmonto_ori
          FROM sc_docret    
         WHERE empresa = pempresa
           AND cuenta BETWEEN vmincta AND vmaxcta
           AND siglas IN('SC','SD')
           AND cancelado IN('S','L')
           
        BEGIN WORK;
        LET vabierto = '1'; 
        
        -- // TRASPASA REGISTRO A sc_docret_pos
        INSERT INTO sc_docret_pos
        SELECT *
          FROM sc_docret
         WHERE empresa = pempresa
           AND cuenta = vcuenta
           AND folio_suc = vfolio_suc
           AND fecha_alta = vfecha_alta
           AND transacc = vtransacc
           AND monto_ori = vmonto_ori;
         
        -- // SI EL REGISTRO SE RESPALDO, ELIMINA EL REGISTRO DE sc_docret
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            DELETE FROM sc_docret
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND folio_suc = vfolio_suc
               AND fecha_alta = vfecha_alta
               AND transacc = vtransacc
               AND monto_ori = vmonto_ori;
        ELSE
            ROLLBACK WORK;
            LET vabierto = '0';
            CONTINUE FOREACH;
        END IF;
             
        COMMIT WORK;
        LET vabierto = '0';
        
        LET vcuenta     = '';
        LET vfolio_suc  = '';
        LET vfecha_alta = '';
        LET vtransacc   = '';
        LET vmonto_ori  = 0;
    END FOREACH;
    
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
    
    END;
    
    RETURN vcodret1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".cons_sdoschq_bpi_pba(pEmpresa char(3),
                                       pCuenta char(20),
                                       pNumTarjeta char(16))
   returning char(5), money(14,2), money(14,2), money(14,2),
                     char(40), money(14,2), char(18);

   -- Modificó: Mauricio León
   -- Actividad: Se agrega instrucción SET ISOLATION
   -- Fecha:  22/06/2009
					 
-- Definición de variables
   define vCodRet             char(5);
   define vCuenta              char(20);
   define vSdoCta             money(14,2);
   define vSdoRet             money(14,2);
   define vSdoCong            money(14,2);
   define vSdoDisp            money(14,2);
   define vImpChqSbg         money(14,2);
   define vProducto            char(4);
   define vProdNom             char(35);
   define vDescripcion            char(40);
   define vCtaClabe           char(18);
   define sql_err              integer;

--- Inicializa Variables de Salida
    let vCodRet   = "000";
    let vCuenta    = pcuenta;
    let vSdoDisp  = 0 ;
    let vSdoRet   = 0 ;
    let vSdoCta   = 0 ;
    let vDescripcion = "";
    let vSdoCong  = 0 ;
    let vProducto = " ";
    let vProdNom = " ";
    let vCtaClabe = "";
    let vImpChqSbg = 0;

BEGIN

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
         let vCodRet = sql_err;
         RETURN vCodRet, vSdoDisp, vSdoRet, vSdoCta,
                         vDescripcion, vSdoCong, vCtaClabe;
      END IF ;
   END EXCEPTION ;

--SET DEBUG FILE TO "/tmp/cons_sdos1.out";
--TRACE ON;

--- Valida que la Cuenta  no sea Blanco
   IF (pCuenta = "00000000000" or pCuenta="") AND pNumTarjeta = "0000000000000000" THEN
      let vCodRet = "110";
       RETURN vCodRet, vSdoDisp, vSdoRet, vSdoCta,
                         vDescripcion, vSdoCong, vCtaClabe;
   END IF ;

   SET ISOLATION DIRTY READ ;

    IF TRIM(NVL(pCuenta,'')) = '' OR pCuenta IS NULL THEN
        SELECT cuenta INTO vCuenta FROM sc_tarjeta WHERE  empresa = pEmpresa and  num_tarjeta = pNumTarjeta;
    ELSE
        LET vCuenta = pCuenta;
    END IF

      SELECT cuenta, sdo_retenido, sdo_cong, sdo_actual,
                     mc.producto, pr.nombre, cuenta_clabe, imp_chq_sbg
      INTO vCuenta, vSdoRet, vSdoCong, vSdoCta, vProducto, vProdNom, vCtaClabe, vImpChqSbg
      FROM sc_maechq mc,sc_producto pr
      WHERE mc.empresa = pEmpresa AND cuenta = pCuenta
            AND pr.empresa = mc.empresa AND pr.producto = mc.producto;

      IF vCuenta IS NULL THEN
         let vCodRet = "100";
         RETURN vCodRet, vSdoDisp, vSdoRet, vSdoCta,
                         vDescripcion, vSdoCong, vCtaClabe;
      END IF ;

--- Calcula Saldo Disponible
    let vSdoDisp = vSdoCta - vSdoRet - vSdoCong - vImpChqSbg;

    { IF vSdoDisp < 0 THEN
        let vSdoDisp = 0;
    END IF }

--- Regresa Variables de Salida
    let vDescripcion = vProducto || " " || vProdNom;
    RETURN vCodRet, vSdoDisp, vSdoRet, vSdoCta,
                         vDescripcion, vSdoCong, vCtaClabe;

END
END PROCEDURE ;

CREATE PROCEDURE "informix".spsctransctaspropias_pba(pEmpresa char(3),
                                                pSucursal char(4),
                                                pUsuario char(8),
                                                pTransCargo char(4),
                                                pTransAbono char(4),
                                                pTransSuc char(4),
                                                pFolioSuc char(16),
                                                pNumCtaOrigen char(12),
                                                pNumCtaDestino char(12),
                                                pCheque integer,
                                                pMonto money(14,2),
                                                pMoneda char(2),
                                                pReferencia char(40),
                                                pNumTarjetaOrigen char(16),
                                                pNumTarjetaDestino char(16),
                                                pUsuAutoriza char(8),
                                                pMontoTotal money(14,2),
                                                pMontoFirme money(14,2),
                                                pMontoSBC money(14,2),
                                                pMontoRem money(14,2),
                                                pDiasRet smallint,
                                                pDocto integer)
        RETURNING char(5), char(5);

    -- Realizo   : Javier Humberto Calderon Zazueta
    -- Actividad : Transferencia entre cuentas propias
    -- Solicitó  : Diana Castellanos
    -- Fecha     :  20/05/2008
	--******************************************************
	-- Modificó		: Nydia Payán
	-- Actividad	: Se agrega validación para Asignación y concatenación de Cuenta del Cargo y/o
    --                la Cuenta Abono, y la Referencia para el Estado de Cuenta    
	-- Solicitó		: Alejandro vazquez
	-- Fecha		: 27/04/2015
	--******************************************************

       DEFINE vcodret   char(5);
       DEFINE vcodretRev   char(5);
       DEFINE sql_err   integer;
       DEFINE vTrans    char(4);
       DEFINE vFechaHoy date;
       DEFINE vSdoDisp  money(14,2);
       DEFINE vMontoRet money(14,2);
       DEFINE vPasoCargo char(1);
       DEFINE vMensajeRet char(100);
	   
	   DEFINE cReferencia varchar(40); 
       DEFINE aReferencia varchar(40);

ON EXCEPTION SET sql_err
       IF sql_err <> 0 THEN
        IF vPasoCargo = '1' THEN
            EXECUTE PROCEDURE reversion(pEmpresa,
                                        pSucursal,
                                        pUsuario,
                                        pFolioSuc,
                                        'A') INTO vcodretRev;
        END IF;
        IF vcodretRev = '000' THEN
            LET vcodretRev = '001';
        END IF;

        LET vcodret = sql_err;
        RETURN vcodret, vcodretRev;
       END IF;
END EXCEPTION;

LET vPasoCargo = '0';
LET vcodret = '000';
LET vcodretRev = '000';
LET vMensajeRet = '';
--Set debug file to '/tmp/traspasobanco/bpi_trasacciones.out';
--trace on;

LET cReferencia = '';
LET aReferencia = '';

---Asignación y concatenación de Cuenta del Cargo/Abono y la Referencia para el Estado de Cuenta
LET cReferencia = TRIM(pNumCtaDestino) || ' ' || pReferencia;LET aReferencia = TRIM(pNumCtaOrigen) || ' ' || pReferencia;
BEGIN

    EXECUTE PROCEDURE sp_validatransferencias_bpi(pEmpresa, pNumCtaOrigen, pNumCtaDestino)
    INTO vcodret, vMensajeRet ;

    IF  vcodret = '00000'  THEN
            EXECUTE PROCEDURE cargo_ref(pEmpresa,
                                        pSucursal,
                                        pUsuario,
                                        pTransCargo,
                                        pTransSuc,
                                        pFolioSuc,
                                        pNumCtaOrigen,
                                        pCheque,
                                        pMonto,
                                        pMoneda,
                                        cReferencia,
                                        pNumTarjetaOrigen,
                                        pUsuAutoriza) INTO vcodret,
                                                           vTrans,
                                                           vFechaHoy,
                                                           vSdoDisp,
                                                           vMontoRet;

            IF vcodret <> '000' THEN
                RETURN vcodret, vcodretRev;
            ELSE
                LET vPasoCargo = '1';
            END IF;

            EXECUTE PROCEDURE abono_ref(pEmpresa,
                                        pSucursal,
                                        pUsuario,
                                        pTransAbono,
                                        pTransSuc,
                                        pFolioSuc,
                                        pNumCtaDestino,
                                        pDocto,
                                        pMontoTotal,
                                        pMontoFirme,
                                        pMontoSBC,
                                        pMontoRem,
                                        pDiasRet,
                                        pMoneda,
                                        aReferencia,
                                        pNumTarjetaDestino,
                                        pUsuAutoriza) INTO vcodret;

            IF vcodret <> '000' THEN
                EXECUTE PROCEDURE reversion(pEmpresa,
                                            pSucursal,
                                            pUsuario,
                                            pFolioSuc,
                                            'A') INTO vcodretRev;
                IF vcodretRev = '000' THEN
                    LET vcodretRev = '001';
                END IF;
                RETURN vcodret, vcodretRev;
            END IF;
    ELSE
        RETURN vcodret, vcodretRev;
    END IF;

END;
RETURN vcodret, vcodretRev;


END PROCEDURE;

CREATE PROCEDURE "informix".spsctransctaspropias_pba(pEmpresa char(3),
                                                pSucursal char(4),
                                                pUsuario char(8),
                                                pTransCargo char(4),
                                                pTransAbono char(4),
                                                pTransSuc char(4),
                                                pFolioSuc char(16),
                                                pNumCtaOrigen char(12),
                                                pNumCtaDestino char(12),
                                                pCheque integer,
                                                pMonto money(14,2),
                                                pMoneda char(2),
                                                pReferencia char(40),
						pReferenciaBe char(40),
                                                pNumTarjetaOrigen char(16),
                                                pNumTarjetaDestino char(16),
                                                pUsuAutoriza char(8),
                                                pMontoTotal money(14,2),
                                                pMontoFirme money(14,2),
                                                pMontoSBC money(14,2),
                                                pMontoRem money(14,2),
                                                pDiasRet smallint,
                                                pDocto integer)
        RETURNING char(5), char(5);

    -- Realizo   : Javier Humberto Calderon Zazueta
    -- Actividad : Transferencia entre cuentas propias
    -- Solicitó  : Diana Castellanos
    -- Fecha     :  20/05/2008
	--******************************************************
	-- Modificó		: Walber Castro
	-- Actividad	: Se agrega nuevo parámetro de entrada pReferenciaBe.
	-- Solicitó		: Pachín
	-- Fecha		: 25/01/2012
	--******************************************************
	-- Modificó		: Berenice Noriega
	-- Actividad	: Se agrega validación para saber si las cuentas pertenecen al mismo cliente.
	--                si es del mimo cliente envia la transaccion 0309, si no lo es envia 0239    
	-- Solicitó		: Alejandro vazquez
	-- Fecha		: 14/Julio/2014
	-- Base Datos	: bdicheq
	--******************************************************
	-- Modificó		: Berenice Noriega
	-- Actividad	: Se agrega validación para saber si las cuentas pertenecen al mismo cliente.
	--                si es del mismo cliente envia la transaccion de abono 0313, si no lo es, envia 0205    
	-- Solicitó		: Alejandro vazquez
	-- Fecha		: 25/Septiembre/2014
	-- Base Datos	: bdicheq		
	--******************************************************
    -- Modificó		: Nydia Payán
	-- Actividad	: Se agrega validación para Asignación y concatenación de Cuenta del Cargo y/o
    --                la Cuenta Abono, y la Referencia para el Estado de Cuenta    
	-- Solicitó		: Alejandro vazquez
	-- Fecha		: 04/Marzo/2015
	--******************************************************

	DEFINE vcodret   char(5);
       	DEFINE vcodretRev   char(5);
       	DEFINE sql_err   integer;
       	DEFINE vTrans    char(4);
	DEFINE vFechaHoy date;
	DEFINE vSdoDisp  money(14,2);
	DEFINE vMontoRet money(14,2);
	DEFINE vPasoCargo char(1);
	DEFINE vMensajeRet char(100);
	DEFINE vReferencia	char(40);
	DEFINE vTransCargo char(4);
	DEFINE vCliente1 CHAR(20);
	DEFINE vCuenta1 char(12);
	DEFINE vTransAbono CHAR(4);
    DEFINE cReferencia varchar(40);
    DEFINE aReferencia varchar(40);
	   
	LET vReferencia ='' ;
   	LET vTransCargo ='';
	  
	LET vCliente1 ='';
	LET vCuenta1 ='';
	LET vTransAbono='';
	   
	SET LOCK MODE TO WAIT 10;
	
BEGIN
ON EXCEPTION SET sql_err
       IF sql_err <> 0 THEN
        IF vPasoCargo = '1' THEN
            EXECUTE PROCEDURE bdicheq:"informix".reversion(pEmpresa,
                                        pSucursal,
                                        pUsuario,
                                        pFolioSuc,
                                        'A') INTO vcodretRev;
        END IF;
        IF vcodretRev = '000' THEN
            LET vcodretRev = '001';
        END IF;

        LET vcodret = sql_err;
        RETURN vcodret, vcodretRev;
       END IF;
END EXCEPTION;

LET vPasoCargo = '0';
LET vcodret = '000';
LET vcodretRev = '000';
LET vMensajeRet = '';

LET cReferencia = '';
LET aReferencia = '';

	/*IF pReferenciaBe  = '' THEN
		LET vReferencia = pReferencia;
    ELSE
		LET vReferencia = pReferenciaBe;
    END IF;*/

---Asignación y concatenación de Cuenta del Cargo/Abono y la Referencia para el Estado de Cuenta
LET cReferencia = TRIM(pNumCtaDestino) || ' ' || pReferencia; --cargo y la Referencia 
LET aReferencia = TRIM(pNumCtaOrigen) || ' ' || pReferenciaBe; --abono y la Referencia del Beneficiario


	EXECUTE PROCEDURE bdicheq:"informix".sp_validatransferencias_bpi(pEmpresa, pNumCtaOrigen, pNumCtaDestino)
    INTO vcodret, vMensajeRet ;
	--*********************************************************************--
	IF pTransCargo='0239' THEN
			
		select count(distinct num_cte), count(cuenta)
        into vCliente1, vCuenta1
        from bdicheq:"informix".sc_maechq
        where ( cuenta=pNumCtaOrigen  or cuenta=pNumCtaDestino)
        and empresa ='001';
		
	    IF vCliente1 = 1 AND vCuenta1 = 2 THEN
         	LET vTransCargo='0309';
			--**Cambia ID de Abono a **********--
				LET vTransAbono='0313';
                LET aReferencia = TRIM(pNumCtaOrigen) || ' ' || pReferencia;			--*********************************--
		ELSE	
			LET vTransCargo=pTransCargo;
			LET vTransAbono=pTransAbono;		

	    END IF
	
		
	END IF
	--*********************************************************************--
		
	
    IF  vcodret = '00000'  THEN
            EXECUTE PROCEDURE bdicheq:"informix".cargo_ref(pEmpresa,
                                        pSucursal,
                                        pUsuario,
                                        vTransCargo, --Envia 0309 si es entre cuentas del mismo cliente sino envia el de entrada 0239.
                                        pTransSuc,
                                        pFolioSuc,
                                        pNumCtaOrigen,
                                        pCheque,
                                        pMonto,
                                        pMoneda,
                                        cReferencia,
                                        pNumTarjetaOrigen,
                                        pUsuAutoriza) INTO vcodret,
                                                           vTrans,
                                                           vFechaHoy,
                                                           vSdoDisp,
                                                           vMontoRet;

            IF vcodret <> '000' THEN
                RETURN vcodret, vcodretRev;
            ELSE
                LET vPasoCargo = '1';
            END IF;

            EXECUTE PROCEDURE bdicheq:"informix".abono_ref(pEmpresa,
                                        pSucursal,
                                        pUsuario,
                                        vTransAbono, --Envia 0313 si es entre cuentas del mismo cliente sino envia el de entrada 0205.
                                        pTransSuc,
                                        pFolioSuc,
                                        pNumCtaDestino,
                                        pDocto,
                                        pMontoTotal,
                                        pMontoFirme,
                                        pMontoSBC,
                                        pMontoRem,
                                        pDiasRet,
                                        pMoneda,
                                        aReferencia,
                                        pNumTarjetaDestino,
                                        pUsuAutoriza) INTO vcodret;

            IF vcodret <> '000' THEN
                EXECUTE PROCEDURE bdicheq:"informix".reversion(pEmpresa,
                                            pSucursal,
                                            pUsuario,
                                            pFolioSuc,
                                            'A') INTO vcodretRev;
                IF vcodretRev = '000' THEN
                    LET vcodretRev = '001';
                END IF;
                RETURN vcodret, vcodretRev;
            END IF;
    ELSE
        RETURN vcodret, vcodretRev;
    END IF;

END;
RETURN vcodret, vcodretRev;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_del_reg_2015()
RETURNING 	CHAR(3) 	AS cod_ret,	CHAR(80)	AS desc_ret

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);

	DEFINE vabierto     CHAR(1);
	DEFINE vcontador   INTEGER;
	DEFINE idRow		INT8;
	
	
	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000";
	LET cDescRet			= "PROCESO EXITOSO";

	LET vabierto   = '0';
	LET vcontador = 0;
	LET idRow 	   = 0;


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/jcgk/sp_del_reg_2015.out';
	--TRACE ON;
	
	FOREACH WITH HOLD
	
		SELECT ROWID
		INTO idRow
		FROM "informix".sc_isr
		WHERE secuencia >= 201501

		DELETE "informix".sc_isr WHERE ROWID = idRow;
		
		IF vcontador = 0 THEN
			BEGIN WORK;
			LET vabierto = '1'; 
		END IF
	
		LET vcontador = vcontador + 1;
		
		IF vcontador = 5000 THEN
			LET vabierto = '0';
			LET vcontador = 0;
			COMMIT WORK;
		END IF
		
	END FOREACH

	IF vcontador > 0 THEN
		COMMIT WORK;
	END IF	

	RETURN cCodRet, cDescRet;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para eliminar los registros previamente respaldados de enero del 2015 a la fecha de la tabla sc_isr',
'BD: bdicheq', 
'AUTOR: José Carlos Guerrero Karass ',
'FECHA: Junio 2015';

CREATE PROCEDURE "informix".sp_cce_consultarchqsxpresentar_pba
(
pEmpresa            CHAR(3)
)
RETURNING
	CHAR(6)         AS cod_ret,
    CHAR(80)        AS desc_ret,
	CHAR(4)         AS sucursal,
	CHAR(40)        AS desc_sucursal,
	CHAR(10)        AS fecha_presentacion,
	CHAR(20)        AS cuenta_deposito,
	CHAR(3)         AS cve_banco,
	CHAR(40)        AS desc_banco,
	CHAR(20)        AS cuenta_cheque,
	INTEGER        	AS numero_cheque,
	MONEY(14,2)     AS importe,
	CHAR(10)		AS fecha_hoy
	
	---DECLARACIONES
    DEFINE iSqlErr          INTEGER;
    DEFINE iIsamErr         INTEGER;
    DEFINE cErrorInfo       CHAR(80);
    DEFINE cDescRet         CHAR(80);
    DEFINE cCodRet          CHAR(6);

	DEFINE cSucursal		CHAR(4);
	DEFINE cDescSucursal	CHAR(40);
	DEFINE cFechaPres		CHAR(10);
	DEFINE cCtaDeposito		CHAR(20);
	DEFINE cBanco           CHAR(3);
	DEFINE cDescBanco       CHAR(40);
	DEFINE cCtaDelCheque    CHAR(20);
	DEFINE iNumCheque    	INTEGER;
	DEFINE mImporte         MONEY(14,2);
	DEFINE cFechaHoy		CHAR(10);

	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
    LET cDescRet		    = "PROCESO EXITOSO";
	LET cCodRet				= "000000";
	
	LET cSucursal			= "";
	LET cDescSucursal		= "";
	LET cFechaPres			= "";
	LET cCtaDeposito		= "";
	LET cBanco				= "";
	LET cDescBanco			= "";
	LET cCtaDelCheque		= "";
	LET iNumCheque    		= 0;
    LET mImporte		    = 0.0;
	LET cFechaHoy			= "";
	


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
            LET cDescRet = cErrorInfo;
			RETURN cCodRet,cDescRet,cSucursal,cDescSucursal,cFechaPres,cCtaDeposito,cBanco,cDescBanco,cCtaDelCheque,iNumCheque,mImporte,cFechaHoy;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/respaldosbd/has/sp_cce_consultarchqsxpresentar.out';
	--TRACE ON;

	IF NVL(pEmpresa,"") = "" THEN
        LET cCodRet = "000001";
        LET cDescRet = "FALTAN PARAMETROS DE ENTRADA";
		RETURN cCodRet,cDescRet,cSucursal,cDescSucursal,cFechaPres,cCtaDeposito,cBanco,cDescBanco,cCtaDelCheque,iNumCheque,mImporte,cFechaHoy;
	ELSE
		--OBTIENE LA FECHA DEL SISTEMA
		SELECT fecha_hoy
		INTO cFechaHoy
		FROM "informix".sc_fechas;
		
        FOREACH	WITH HOLD
			SELECT doc.sucursal, suc.nombre, cce.fechapresenta, doc.cuenta AS CTA_DEPOSITO, ba.banco, ba.descripcion, doc.numcuenta AS CTA_CHEQUE, doc.num_chq, doc.monto
			INTO cSucursal, cDescSucursal, cFechaPres, cCtaDeposito, cBanco, cDescBanco, cCtaDelCheque, iNumCheque, mImporte
			FROM "informix".sc_docret_sbc doc, bditef:"informix".cce_cheques_det cce, bdinteg:"informix".si_bancos ba, bdinteg:"informix".si_sucursales suc
			WHERE doc.empresa = pEmpresa
			AND doc.banco = ba.banco
			AND doc.transacc IN (SELECT transacc FROM bditef:cce_mapeo_cecoban where empresa = pEmpresa and transacc = transacc and tipo_cta_dep = tipo_cta_dep)
			AND doc.cancelado = "T"
			AND doc.banco = cce.cvebanco
			AND doc.numcuenta::INT8 = cce.numcuenta::INT8
			AND doc.num_chq = cce.numcheque::INTEGER
			AND cce.fechapresenta < cFechaHoy
			AND cce.presentado = "0"
			AND doc.sucursal = suc.sucursal
			
            RETURN cCodRet,cDescRet,NVL(cSucursal,""),NVL(cDescSucursal,""),
				SUBSTR(cFechaPres,7,4) || "/" || SUBSTR(cFechaPres,1,2) || "/" || SUBSTR(cFechaPres,4,2),
				NVL(cCtaDeposito,""),NVL(cBanco,""),NVL(cDescBanco,""),NVL(cCtaDelCheque,""),NVL(iNumCheque,0),NVL(mImporte,0.0)
				,NVL(SUBSTR(cFechaHoy,7,4) || "/" || SUBSTR(cFechaHoy,1,2) || "/" || SUBSTR(cFechaHoy,4,2),"") 
			WITH RESUME;
        END FOREACH	
        IF dbinfo("sqlca.sqlerrd2") = 0 THEN
            LET cCodRet = "000002";
            LET cDescRet = "NO EXISTEN DATOS";
            RETURN cCodRet,cDescRet,cSucursal,cDescSucursal,cFechaPres,cCtaDeposito,cBanco,cDescBanco,cCtaDelCheque,iNumCheque,mImporte,cFechaHoy;
        END IF
	END IF
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener los datos de los cheques que no se encuentran presentados porque tienen fecha de presentacion anterior a la fecha de hoy del sistema', 
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Febrero 2013',
'VERSION: 20130222.1720';

CREATE PROCEDURE "informix".sp_dispercionnominaautomatico_pba()
RETURNING CHAR(5);
    
    -- ******************************************************************************************
    -- Realizo   : Martin Valenzuela Ojeda, Armando Mercado
    -- Proyecto  : Dispersion Nomina BanCoppel
    -- Actividad : Ejecuta el proceso para la dispersion de la nomina,
    --             actualiza el campo status en el detalle de aquellos empleados
    --             que si se les ejecuto el pago de la nomina y
    --             aquellos que por algun motivo no se les disperso su sueldo.
    --             Tambien actualiza el encabezado para aquellos archivos que fueron dispersados,
    --             ejecutando las validaciones correspondientes.
    --             Este store sera ejecutado para varios archivos en Batch
    -- Fecha     : Abril de 2008
    -- ******************************************************************************************
    
    DEFINE vsqlerr                          INTEGER;
    DEFINE visamerr                         INTEGER;
    DEFINE vdescerr                         CHAR(60);
    DEFINE vcodret                          VARCHAR(6);
    DEFINE vcodret2                         VARCHAR(6);
    DEFINE vcodret3                         VARCHAR(60);
    DEFINE p_mensaje                        VARCHAR(100);
    DEFINE cNumeroEmpresa                   CHAR(3);
    DEFINE dFechaGeneracion                 DATE;
    DEFINE IFolioArchivo                    INTEGER;
    DEFINE dFechaActual                     DATE;
    DEFINE cEstatusCta                      CHAR(1);
    DEFINE cNumeroCuentaEmpleado            CHAR(20);
    DEFINE cNumeroEmpleado                  CHAR(10);
    DEFINE mImporteEmpleado                 MONEY(14,3);
    DEFINE dFechaAplicacion                 DATE;
    DEFINE cHoraActual                      DATETIME HOUR TO SECOND;
    DEFINE cNumeroTarjeta                   CHAR(20);
    DEFINE mImporteAbonado                  MONEY(16,3);
    DEFINE mImporteNoAbonado                MONEY(16,3);
    DEFINE mImporteTotalAplicado            MONEY(16,3);
    DEFINE siSaldoDisponible                SMALLINT;
    DEFINE mTotalNoPagado                   MONEY(16,3);
    DEFINE mTotalComisionDispercionIvaEmp   MONEY(14,3);
    DEFINE mImporteTotalEnc                 MONEY(14,3);
    DEFINE mSaldoActual                     MONEY(14,3);
    DEFINE iNumeroRegistros                 INTEGER;
    DEFINE bPrimerEmpleado                  BOOLEAN;
    DEFINE bSiguienteEmpleado               BOOLEAN;
    DEFINE cCodRet                          CHAR(3);
    DEFINE cMensaje                         CHAR(100);
    DEFINE mTotaliva                        MONEY(14,3);
    DEFINE mTotalComision                   MONEY(14,3);
    DEFINE iCodigoEstatus                   INTEGER;
    DEFINE cNumeroFolio                     CHAR(16);
    DEFINE cNombreArchivo                   CHAR(30);
    DEFINE vtranret                         CHAR(4);
    DEFINE vfechoy                          DATE;
    DEFINE vsdodisp                         MONEY(14,2);
    DEFINE vmontoret                        MONEY(14,2);
    DEFINE cFolioDispercion                 CHAR(16);
    DEFINE mComisionAplicado                MONEY(16,3);
    DEFINE mIvaAplicado                     MONEY(16,3);
    DEFINE cNombreArchivoConciliacion       CHAR(20);
    DEFINE cCuentaEje                       CHAR(20);
    DEFINE cUsuarioAutoriza                 CHAR(8);
    DEFINE siValorStatus					SMALLINT;
    DEFINE v_cCodRet                        CHAR(5);
    DEFINE siValorConcepto                  SMALLINT;
    DEFINE siValorConceptoAnterior          SMALLINT;
    DEFINE cValorTransaccion                CHAR(4);
    DEFINE cValorTipoTransaccion            CHAR(3);
    DEFINE cTransaccAbono                   CHAR(4);
    DEFINE cTransaccCargo                   CHAR(4);
    DEFINE mMontoTransComiDisp              MONEY(16,2);
    DEFINE mMontoTransComiAper              MONEY(16,2);
    DEFINE mMontoTransIvaDisp               MONEY(16,2);
    DEFINE mMontoTransIvaAper               MONEY(16,2);
    DEFINE mMontoFijo                       MONEY(16,2);
    DEFINE mTotalPagado                     MONEY(16,3);
    DEFINE mTotalCargo                      MONEY(16,3);
    DEFINE cTransaccComiDisp                CHAR(4);    -- // Aqui se traera el 0394
    DEFINE cTransacIvaDisp                  CHAR(4);    -- // Aqui se traera el 0396
    DEFINE mImporteEmpleadoCuentaEje        MONEY(16,3);
    DEFINE mImporteEmpleadoComisionMasIva   MONEY(16,3);
    DEFINE cEstatusCuenta                   CHAR(1);
    DEFINE vcodretCargo1                    CHAR(6);
    DEFINE vcodretCargo2                    CHAR(6);
    DEFINE vcodretCargo3                    CHAR(6);
    DEFINE vBegin                           CHAR(1);
    DEFINE mIvaPorEmpleado                  MONEY(16,2);
    DEFINE siTipoEmpresa                    SMALLINT ;
    DEFINE cSucursalAbono                   CHAR(4);
    DEFINE cSucursalCargo                   CHAR(4);
    DEFINE cRecDatonoUtilizableNOperacion   CHAR(4);
    DEFINE siVuelta                         INTEGER ;
    DEFINE cCargo               			CHAR(2);
    DEFINE cAbono               			CHAR(2);
    DEFINE cAceptaProducto         			CHAR(50);
    DEFINE iContador						INTEGER;
    DEFINE vexiste_encab                    CHAR(17);
    DEFINE vexiste_ctaeje                   CHAR(20);
    DEFINE vexiste_sec                      SMALLINT;
    DEFINE cProducto                        CHAR(20);
    DEFINE iNumeroRegistrosAplicados        INTEGER ;
    DEFINE vind_cierre                      CHAR(1);
    DEFINE vind_dispon                      CHAR(1);
	DEFINE mDispCtaBcoppel					MONEY;
    
    LET vsqlerr                         = 0;
    LET visamerr                        = 0;
    LET vdescerr                        = '' ;
    LET vcodret                         = '' ;
    LET vcodret2                        = '' ;
    LET vcodret3                        = '' ;
    LET p_mensaje                       = ' ' ;
    LET cNumeroEmpresa                  = '';
    LET dFechaGeneracion                = '';
    LET IFolioArchivo                   = 0;
    LET dFechaActual                    = '' ;
    LET cEstatusCta                     = '' ;
    LET cNumeroCuentaEmpleado           = '';
    LET cNumeroEmpleado                 = '';
    LET mImporteEmpleado                = 0;
    LET dFechaAplicacion                = '';
    LET cHoraActual                     = '' ;
    LET cNumeroTarjeta                  = '';
    LET mImporteAbonado                 = 0;
    LET mImporteNoAbonado               = 0;
    LET mImporteTotalAplicado           = 0;
    LET siSaldoDisponible               = 0;
    LET mTotalNoPagado                  = 0;
    LET mTotalComisionDispercionIvaEmp  = 0;
    LET mImporteTotalEnc                = 0;
    LET mSaldoActual                    = 0;
    LET iNumeroRegistros                = 0;
    LET bPrimerEmpleado                 = "T" ;
    LET bSiguienteEmpleado              = "F" ;
    LET cCodRet                         = '';
    LET cMensaje                        = '';
    LET mTotaliva                       = 0.00;
    LET mTotalComision                  = 0.00;
    LET iCodigoEstatus                  = 0;
    LET cNumeroFolio                    = '';
    LET cNombreArchivo                  = "";
    LET vtranret                        = '';
    LET vfechoy                         = '';
    LET vsdodisp                        = 0.00;
    LET vmontoret                       = 0.00;
    LET cFolioDispercion                = '';
    LET mComisionAplicado               = 0.00;
    LET mIvaAplicado                    = 0.00;
    LET cNombreArchivoConciliacion      = '';
    LET cCuentaEje                      = '';
    LET cUsuarioAutoriza                = '';
    LET siValorStatus                   = 0;
    LET v_cCodRet                       = '';
    LET siValorConcepto                 = 0;
    LET siValorConceptoAnterior         = 0;
    LET cValorTransaccion               = '';
    LET cValorTipoTransaccion           = '';
    LET cTransaccAbono                  = '';
    LET cTransaccCargo                  = '';
    LET mMontoTransComiDisp             = 0;
    LET mMontoTransComiAper             = 0;
    LET mMontoTransIvaDisp              = 0;
    LET mMontoTransIvaAper              = 0;
    LET mMontoFijo                      = 0;
    LET mTotalPagado                    = 0;
    LET mTotalCargo                     = 0;
    LET cTransaccComiDisp               = '';
    LET cTransacIvaDisp                 = '';
    LET mImporteEmpleadoCuentaEje       = 0;
    LET mImporteEmpleadoComisionMasIva  = 0;
    LET cEstatusCuenta                  = '';
    LET vcodretCargo1                   = '';
    LET vcodretCargo2                   = '';
    LET vcodretCargo3                   = '';
    LET vBegin                          = 'S';
    LET mIvaPorEmpleado                 = 0;
    LET siTipoEmpresa                   = 0;
    LET cSucursalAbono                  = '';
    LET cSucursalCargo                  = '';
    LET cRecDatonoUtilizableNOperacion  = '';
    LET siVuelta                        = 0;
    LET cCargo                          ='';
    LET cAbono                          ='';
    LET cAceptaProducto                 = '';
    LET iContador                       = 0;
    LET vexiste_encab                   = '';
    LET vexiste_ctaeje                  = '';
    LET vexiste_sec                     = 0;
    LET cProducto                       = '';
    LET iNumeroRegistrosAplicados       = 0;
    LET vind_cierre                     = '0';
    LET vind_dispon                     = '0';
	LET mDispCtaBcoppel	= 0.0;
    
    --- SET DEBUG FILE TO '/tmp/sp_dispercionnominaautomatico.out';
	--SET DEBUG FILE TO '/informix/moha/sp_dispercionnominaautomatico.out';
     --TRACE ON;
    
    BEGIN
    
	ON EXCEPTION SET vsqlerr, visamerr, vdescerr
        SET DEBUG FILE TO '/tmp/sp_dispercionnominaautomatico.out';
        TRACE ON;
		IF vsqlerr <> 0 OR vsqlerr <> -206 THEN
			LET vcodret  = vsqlerr;  --- Dispercion No Ejecutada
            LET vcodret2 = visamerr;
            LET vcodret3 = vdescerr;
			LET cFolioDispercion = "";
			LET mImporteTotalAplicado = 0;
			LET mComisionAplicado = 0;
			LET mIvaAplicado = 0;
			LET cNombreArchivoConciliacion = "";
			IF vBegin = 'S' THEN
				ROLLBACK WORK;
			END IF;
			RETURN vcodret;
		END IF;
	END EXCEPTION;
    
	SET ISOLATION TO CURSOR STABILITY; 
	SET ISOLATION TO DIRTY READ; 
	SET LOCK MODE TO WAIT 5; 
    
	SELECT fecha_hoy, ind_cierre, ind_disponible
	  INTO dFechaActual, vind_cierre, vind_dispon
	  FROM bdicheq:sc_fechas
	 WHERE empresa = "001";
     
    IF ( vind_cierre = '0' OR vind_dispon = '0' ) THEN
        LET vcodret = '004';
        RETURN vcodret;
    END IF;
    
	SELECT FIRST 1 nombre_archivo
	  INTO vexiste_encab
	  FROM bdicheq:sc_nominaencabezadosumario
	 WHERE status = '1'
	   AND fecha_aplicacion = dFechaActual;
    
	IF vexiste_encab IS NULL OR vexiste_encab = '' THEN
		LET vcodret = '805'; --- Dispercion No Ejecutada: No Existe el Encabezado del Archivo Ã?el Estatus No es el Correcto;
		RETURN vcodret;
	END IF;
    
	LET cHoraActual = CURRENT;
    
	-- // Se borra la tabla de control al inicio de cada ciclo
	TRUNCATE TABLE bdicheq:sc_nominaresultadosdispercionautomatica;
    
	SELECT valor
	  INTO mMontoTransIvaDisp
	  FROM bdinteg:si_param
	 WHERE cod_param = 47
	   AND empresa = "001";
    
	IF (mMontoTransIvaDisp = "") OR (mMontoTransIvaDisp = " ") OR (mMontoTransIvaDisp IS NULL) THEN
		LET vcodret = '855';  --- Dispercion No Ejecutada: El Valor del Iva No es Valido
		RETURN vcodret;
	END IF;
    
	FOREACH WITH HOLD
		SELECT empresa, fecha_gen, folio_archivo, nombre_archivo, cuenta_cargo, fecha_aplicacion, total_registros, importe_tot
		  INTO cNumeroEmpresa, dFechaGeneracion, IFolioArchivo, cNombreArchivo, cCuentaEje, dFechaAplicacion, iNumeroRegistros, mImporteTotalEnc
		  FROM bdicheq:sc_nominaencabezadosumario
		 WHERE status = '1'
		   AND fecha_aplicacion <= dFechaActual
		 ORDER BY empresa, nombre_archivo
        
		BEGIN WORK;
		LET vBegin = 'S';
		LET vcodret = '000';
        
		-- // Consulta el Tipo de empresa
		SELECT tipo_empresa, TRIM(acepta_producto)
		  INTO siTipoEmpresa, cAceptaProducto
		  FROM bdicheq:sc_nominaempresas
		 WHERE codigo = cNumeroEmpresa;
        
		SELECT LIMIT 1 concepto --, nombre_archivo
		  INTO siValorConcepto --, cNombre
		  FROM bdicheq:sc_nominamovimientos
		 WHERE nombre_archivo = cNombreArchivo
		   AND status = '0';
        
		-- // Cambio Validacion para que si la empresa es interna pero tiene un concepto dIFerente a nomina se tome como externa para el cobro de impuestos
		IF (siTipoEmpresa = 2) AND (siValorConcepto <> 1) AND (siValorConcepto <> 5) THEN
			LET siTipoEmpresa = 1;
		END IF;
        
		-- // Inicio de validacion de tipo de empresa externas
		IF siTipoEmpresa <> 2  THEN
			SELECT cuenta
			  INTO vexiste_ctaeje
			  FROM bdicheq:sc_maechq
			 WHERE empresa = '001'
			   AND cuenta = cCuentaEje;
            
			--- IF NOT Exists (SELECT cuenta FROM bdicheq:sc_maechq WHERE empresa = '001' AND cuenta = cCuentaEje) THEN
			--- IF vexiste_ctaeje <> cCuentaEje THEN
			IF vexiste_ctaeje IS NULL THEN
				LET vcodret  = "810"; --- La cuenta NO Existe en la Base de Datos
                
				-- // Nueva Instruccion Para actualizar el encabezado y saber porque no se disperso el Archivo
				UPDATE bdicheq:sc_nominaencabezadosumario
				   SET status = '7', 
					   fecha_aplicado = dFechaActual,
					   hora_aplicado = cHoraActual
				 WHERE empresa = cNumeroEmpresa
				   AND fecha_gen = dFechaGeneracion
				   AND folio_archivo = IFolioArchivo;
                
				COMMIT WORK;
				LET vBegin = 'N';
                
				-- // Genera respuesta para el cliente
				CALL sp_conciliaciondispersionnomina (cNombreArchivo)
				RETURNING v_cCodRet, cNombreArchivoConciliacion;
                
				-- // Continua con el siguiente archivo
				CONTINUE FOREACH;
			ELSE
				CALL sp_dispersionnominavalidacionestatus(cCuentaEje, cNumeroEmpresa, dFechaGeneracion, iFolioArchivo, dFechaActual, cHoraActual, '', '', '', '', '')
				RETURNING vcodret, cEstatusCuenta, cCargo, mImporteNoAbonado, cSucursalCargo, cRecDatonoUtilizableNOperacion;
                
				IF vcodret <> '000' THEN
					COMMIT WORK;
					LET vBegin = 'N';
                    
					-- // Genera respuesta para el cliente
					CALL sp_conciliaciondispersionnomina (cNombreArchivo)
					RETURNING v_cCodRet, cNombreArchivoConciliacion;
                    
					-- // Continua con el siguiente archivo
					CONTINUE FOREACH;
				END IF;
			END IF;
		END IF; -- // Fin de validacion de tipo de empresa externas
        
		LET cUsuarioAutoriza = "informix";
		LET mTotalNoPagado = 0;
		LET mImporteAbonado = 0;
		LET mImporteNoAbonado = 0;
		LET mImporteTotalAplicado = 0;
		LET mTotalPagado = 0;
		LET iNumeroRegistrosAplicados = 0;
		LET mTotalCargo = 0;
        
		IF (cNombreArchivo IS NULL) OR (cNombreArchivo = "") OR (cNombreArchivo = " ") THEN
			LET vcodret = '830';
			LET p_mensaje = "Dispercion No Ejecutada: Existe el Encabezado Pero No Existe el Detalle del Archivo";
			LET cFolioDispercion = "";
			LET mImporteTotalAplicado = 0;
			LET mComisionAplicado = 0;
			LET mIvaAplicado = 0;
			LET cNombreArchivoConciliacion = "";
            LET vcodret = '000'; --- Este codigo se deja en 000 porque el ciclo continua ejecutandose para otro archivo y necesita llevar este valor
            
			UPDATE bdicheq:sc_nominaencabezadosumario
			   SET status = '6', --- Importe restaurado a la cuenta
				   fecha_aplicado = dFechaActual,
				   hora_aplicado = cHoraActual
			 WHERE empresa = cNumeroEmpresa
			   AND fecha_gen = dFechaGeneracion
			   AND folio_archivo = IFolioArchivo;
            
			COMMIT WORK;
			LET vBegin = 'N';
            
			-- // Genera respuesta para el cliente
			CALL sp_conciliaciondispersionnomina (cNombreArchivo)
			RETURNING v_cCodRet, cNombreArchivoConciliacion;
            
			-- // Continua con el siguiente archivo
			CONTINUE FOREACH;
		END IF;
        
		LET siValorConceptoAnterior = 0; --- Aqui inicializo la variable cada vez que se vaya a procesar otro archivo
        
		-- // Se Limpian las Variables en Cada Vuelta
		LET cTransaccAbono = "";
		LET cTransaccCargo = "";
		LET cTransaccComiDisp = "";
		LET cTransacIvaDisp = "";
		LET vcodret = '000';
        
		-- // Inicio de validacion de tipo de empresa externas
		IF siTipoEmpresa <> 2 THEN
			SELECT sdo_actual
			  INTO mSaldoActual
			  FROM bdicheq:sc_maechq
			 WHERE empresa ='001'
			   AND cuenta = cCuentaEje;
            
			SELECT MIN(importe)
			  INTO mImporteEmpleado
			  FROM bdicheq:sc_nominamovimientos
			 WHERE nombre_archivo = cNombreArchivo
			   AND status = '0'; --- Con status <> 1 tomo todos los registros que no hayan sido procesados
            
			LET mIvaPorEmpleado = mMontoTransComiDisp * mMontoTransIvaDisp;
			LET mTotalComisionDispercionIvaEmp = mMontoTransComiDisp + mIvaPorEmpleado;
			LET mImporteEmpleadoCuentaEje = mImporteEmpleado + mTotalComisionDispercionIvaEmp;
            
			--- // Linea nueva aqui valido que por lo menos exista saldo para pagar a un empleado
			IF (mSaldoActual <= 0) OR (mSaldoActual < mImporteEmpleadoCuentaEje) THEN
				LET siSaldoDisponible = 0;
				LET vcodret = '835';
				LET p_mensaje = "Dispercion No Ejecutada: La Cuenta Eje No Tiene Saldo";
				LET cFolioDispercion = "";
				LET mImporteTotalAplicado = 0;
				LET mComisionAplicado = 0;
				LET mIvaAplicado = 0;
				LET cNombreArchivoConciliacion = "";
				LET vcodret = '000'; --- Este codigo se deja en 000 porque el ciclo continua para otro archivo y necesita llevar este valor
                
				UPDATE bdicheq:sc_nominaencabezadosumario
				   SET status = '5', --Saldo insuficiente
					   fecha_aplicado = dFechaActual,
					   hora_aplicado = cHoraActual
				 WHERE empresa = cNumeroEmpresa
				   AND fecha_gen = dFechaGeneracion
				   AND folio_archivo = IFolioArchivo;
                
				COMMIT WORK;
				LET vBegin = 'N';
				
				-- // Genera respuesta para el cliente
				CALL sp_conciliaciondispersionnomina (cNombreArchivo)
				RETURNING v_cCodRet, cNombreArchivoConciliacion;
				
				CONTINUE FOREACH;
			ELSE
				LET siSaldoDisponible = 1;
				LET mImporteEmpleado = 0;
				LET mTotalComisionDispercionIvaEmp = 0;
				LET mImporteEmpleadoCuentaEje = 0;
			END IF;
            
			LET cNumeroEmpresa = cNumeroEmpresa;
			LET siValorConcepto = siValorConcepto;
		END IF; -- // Fin de validacion de tipo de empresa externas
        
		-- // CICLO PARA VALIDAR LOS VALORES DE LAS TRANSACCIONES
		--- CALL sp_dispersionnominatransacciones (siTipoEmpresa, cNumeroEmpresa, siValorConcepto)
        CALL sp_dispersionnominatransacciones (siTipoEmpresa, siValorConcepto)
		RETURNING vcodret, cValorTipoTransaccion, cValorTransaccion, mMontoFijo, cTransaccAbono, cTransaccCargo,
				  cTransaccComiDisp, mMontoTransComiDisp, mMontoTransComiAper, cTransacIvaDisp, mMontoTransIvaAper;
        
		IF vcodret <> '000' THEN
			-- // El Numero De transaccion es Invalido o No Existe
			UPDATE bdicheq:sc_nominaencabezadosumario
			   SET status = '4', --No aplicado cuenta inexistente
				   fecha_aplicado = dFechaActual,
				   hora_aplicado = cHoraActual
			 WHERE empresa = cNumeroEmpresa
			   AND fecha_gen = dFechaGeneracion
			   AND folio_archivo = IFolioArchivo;
            
			COMMIT WORK;
			LET vBegin = 'N';
            
			-- // Genera respuesta para el cliente
			CALL sp_conciliaciondispersionnomina (cNombreArchivo)
			RETURNING v_cCodRet, cNombreArchivoConciliacion;
			
			CONTINUE FOREACH;
		END IF;
        
		LET siVuelta = 0;
        
		FOREACH WITH HOLD
			SELECT mov.num_empleado, mov.cuenta_abono, mov.importe, mov.concepto, mae.status_cta, mae.producto
			  INTO cNumeroEmpleado, cNumeroCuentaEmpleado, mImporteEmpleado, siValorConcepto,siValorStatus, cProducto
			  FROM bdicheq:sc_nominamovimientos mov
			  LEFT JOIN bdicheq:sc_maechq mae ON (mae.empresa = '001' AND mov.cuenta_abono = mae.cuenta)
			 WHERE mov.nombre_archivo = cNombreArchivo
			   AND mov.status = 0 --- Con status <> 1 tomo todos los registros que no hayan sido procesados
			ORDER BY mov.importe
            
			LET siVuelta = siVuelta + 1;
			LET iContador = iContador + 1;
            
			IF (siValorConcepto <> 0) AND (siValorConceptoAnterior <> siValorConcepto) THEN
				LET siValorConceptoAnterior = siValorConcepto;
			END IF;
            
			-- // CICLO PARA VALIDAR LOS VALORES DE LAS TRANSACCIONES
			--- CALL sp_dispersionnominatransacciones(siTipoEmpresa, cNumeroEmpresa, siValorConcepto)
            CALL sp_dispersionnominatransacciones(siTipoEmpresa, siValorConcepto)
			RETURNING vcodret, cValorTipoTransaccion, cValorTransaccion, mMontoFijo, cTransaccAbono, cTransaccCargo,
					  cTransaccComiDisp, mMontoTransComiDisp, mMontoTransComiAper, cTransacIvaDisp, mMontoTransIvaAper;
            
			IF vcodret <> '000' THEN
				-- // El Numero De transaccion es Invalido o No Existe
				UPDATE bdicheq:sc_nominaencabezadosumario
				   SET status = '4', --- Error
					   fecha_aplicado = dFechaActual,
					   hora_aplicado = cHoraActual
				 WHERE empresa = cNumeroEmpresa
				   AND fecha_gen = dFechaGeneracion
				   AND folio_archivo = IFolioArchivo;
                
				COMMIT WORK;
				LET vBegin = 'N';
				CONTINUE FOREACH;
			END IF;
            
			LET cAceptaProducto = TRIM(cAceptaProducto);
            
			--- IF cProducto IS NULL OR cProducto <> cAceptaProducto THEN
			IF cProducto IS NULL THEN
				-- // Cuenta no existe
				UPDATE bdicheq:sc_nominamovimientos
				   SET status = '4'
				 WHERE nombre_archivo = cNombreArchivo
				   AND num_empleado = cNumeroEmpleado;
                
				IF siTipoEmpresa = 2 THEN
					LET mImporteNoAbonado = mImporteNoAbonado + mImporteEmpleado;
				END IF;
                
				CONTINUE FOREACH;
	        END IF;
			
			-- // Inicio de validacion de tipo de empresa externas
			IF siTipoEmpresa <> 2 THEN
				LET mIvaPorEmpleado = mMontoTransComiDisp * mMontoTransIvaDisp;
				LET mTotalComisionDispercionIvaEmp = mMontoTransComiDisp + mIvaPorEmpleado;
				LET mImporteEmpleadoComisionMasIva = mImporteEmpleado + mTotalComisionDispercionIvaEmp;
                
                /* Aqui se le resta 1 centavo, porque cuando el saldo inicial de la cuenta eje es igual a la suma del  monto a dispersar + su comision + su iva
				   cuando ya esta en el ultimo empleado el proceso le suma 1 centavo a mTotalCargo + mImporteEmpleadoComisionMasIva, por lo tango el mSaldoActual 
				   es menor que mTotalCargo + mImporteEmpleadoComisionMasIva, cuando la realidad es que deben de ser iguales. */
				IF siVuelta = iNumeroRegistros THEN
					LET mTotalCargo = mTotalCargo - 0.01;
				END IF;
                
				-- // Si el saldo sobrante que me queda es Mayor o Igual al importe a pagar, le pago al empleado
				IF mSaldoActual >= (mTotalCargo + mImporteEmpleadoComisionMasIva) THEN
					LET bSiguienteEmpleado = "T" ;
					LET siSaldoDisponible = 1;
				ELSE
					LET bSiguienteEmpleado = "F" ;
					LET siSaldoDisponible = 0;
				END IF;
			END IF; -- // Fin de validacion de tipo de empresa externas
            
			-- // Inicio de validacion de tipo de empresa = 2
			IF siTipoEmpresa = 2 THEN
				LET bPrimerEmpleado = "T";
				LET bSiguienteEmpleado = "T";
				LET siSaldoDisponible = 1;
			END IF; -- // Fin de validacion de tipo de empresa = 2
            
			IF (bPrimerEmpleado = "T") OR (bSiguienteEmpleado = "T") THEN
				IF siValorStatus > 1 THEN
					CALL sp_dispersionnominavalidacionestatus(cNumeroCuentaEmpleado, '', '', 0, '', '' ,cNombreArchivo, cNumeroEmpleado, mImporteEmpleado, mImporteNoAbonado, siTipoEmpresa)
					RETURNING vcodret, cEstatusCta, cAbono, mImporteNoAbonado, cRecDatonoUtilizableNOperacion, cSucursalAbono;
				ELSE
					LET cEstatusCta = 1;
				END IF;
                
				-- // Estatus 1 = Cuenta Activa, Estatus 3 = Cuenta Bloqueada, Se modifica que pudiera abonarse a la cuenta bloqueada, si el motivo del bloqueo lo permite
				IF ((siSaldoDisponible = 1) AND (cEstatusCta = '1' )) OR ((siSaldoDisponible = 1) AND (cAbono = 'S')) THEN
					SELECT MAX(secuencia)
					  INTO vexiste_sec
					  FROM bdicheq:sc_tarjeta
					 WHERE empresa = '001'
					   AND cuenta = cNumeroCuentaEmpleado
					   AND tipo_tarjeta = "T"
					   AND status_tar = "A";
                    
					IF vexiste_sec IS NOT NULL OR vexiste_sec <> '' OR vexiste_sec > 0 THEN
						SELECT NVL(num_tarjeta, '')
						  INTO cNumeroTarjeta
						  FROM bdicheq:sc_tarjeta
						 WHERE empresa = '001'
						   AND cuenta = cNumeroCuentaEmpleado
						   AND tipo_tarjeta = "T"
						   AND status_tar = "A"
						   AND secuencia = vexiste_sec;
					ELSE
						LET cNumeroTarjeta = '';
					END IF;
                    
					CALL sp_generafolionomina ("informix")
					RETURNING cCodRet, cNumeroFolio;
                    
					-- // Aqui siempre se mandara la empresa 001 independientemente del numero de empresa que se este ejecutando tanto para el abono_ref y el cargo_ref
					LET cSucursalAbono = "9103";
                    
					CALL abono_ref ("001", cSucursalAbono, "informix", cTransaccAbono, "0000", cNumeroFolio, cNumeroCuentaEmpleado,
									0, mImporteEmpleado, mImporteEmpleado, 0, 0, 0, "01", " ", cNumeroTarjeta, cUsuarioAutoriza)
					RETURNING vcodret;
                    
					IF vcodret = '000' THEN
						UPDATE bdicheq:sc_nominamovimientos
						   SET status = '1'  --- Aqui actualizo el status = 1  (Aplicado)
						 WHERE nombre_archivo = cNombreArchivo
						   AND num_empleado = cNumeroEmpleado;
						
						LET mImporteAbonado = mImporteAbonado + mImporteEmpleado;
						
						LET iNumeroRegistrosAplicados = iNumeroRegistrosAplicados +1;
						
						LET mTotalComision = iNumeroRegistrosAplicados * mMontoTransComiDisp;
						LET mTotaliva = mTotalComision * mMontoTransIvaDisp;  --- Nueva Forma de Calcular el Iva
						LET mTotalPagado = mTotalPagado + mImporteEmpleado;
						LET mTotalCargo = mTotalPagado + mTotalComision + mTotaliva;
					ELSE
						UPDATE bdicheq:sc_nominamovimientos
						   SET status = '9'  --- Aqui actualizo el status = 9  (Error en la transaccion del sp abono_ref)
						 WHERE nombre_archivo = cNombreArchivo
						   AND num_empleado = cNumeroEmpleado;
                        
						LET mImporteNoAbonado = mImporteNoAbonado + mImporteEmpleado;
					END IF;
				END IF;
			ELSE
				UPDATE bdicheq:sc_nominamovimientos
				   SET status = '5' --- Saldo Insuficiente
				 WHERE nombre_archivo = cNombreArchivo
				   AND num_empleado = cNumeroEmpleado;
                
				IF siTipoEmpresa = 2 THEN
					LET mImporteNoAbonado = mImporteNoAbonado + mImporteEmpleado;
				END IF;
			END IF;  -- // FIN de: IF (bPrimerEmpleado = "T") OR  (bSiguienteEmpleado = "T")
            
			LET bPrimerEmpleado = "F" ;
		END FOREACH;
        
		-- // Inicio de validacion de tipo de empresa externas
		IF siTipoEmpresa <> 2 THEN
			CALL sp_generafolionomina ("informix")
			RETURNING cCodRet, cNumeroFolio;
            
			IF cProducto <> "2600" THEN
				--// OBTIENE EL VALOR DE LA COMISION POR DISPERSION EN LA TABLA MAESTRA DE COMISIONES DE PERSONAS MORALES
				SELECT disp_cta_bcoppel
				INTO mDispCtaBcoppel
				FROM "informix".sc_maecomtasserv_pm
				WHERE cuenta = cCuentaEje;
				
				IF mDispCtaBcoppel IS NOT NULL THEN
					LET mMontoTransComiDisp = mDispCtaBcoppel;
				END IF
			END IF
			
			-- // Aqui se manda llamar el sp que obtiene los totales del IVA y de la comision de los empleados Aplicados
			CALL sp_nominatotalivacomision (cNombreArchivo, mMontoTransIvaDisp, mMontoTransComiDisp)
			RETURNING cCodRet, cMensaje, mTotaliva, mTotalComision, mTotalPagado, mTotalNoPagado, mTotalCargo;
            
			IF mTotalNoPagado <> 0 THEN
				LET iCodigoEstatus = 3;
			ELSE
				LET iCodigoEstatus = 2;
			END IF;
            
			IF cCodRet = '000' THEN
				UPDATE bdicheq:sc_nominaencabezadosumario
				   SET status = iCodigoEstatus,
					   importe_aplicado = mTotalPagado,
					   importe_no_aplicado = mTotalNoPagado,
					   folio_dispersion = cNumeroFolio,
					   iva = mTotaliva,
					   comision = mTotalComision,
					   fecha_aplicado = dFechaActual,
					   hora_aplicado = cHoraActual
				 WHERE empresa = cNumeroEmpresa
				   AND fecha_gen = dFechaGeneracion
				   AND folio_archivo = IFolioArchivo;
			ELSE
				UPDATE bdicheq:sc_nominaencabezadosumario
				   SET status = iCodigoEstatus,
					   importe_no_aplicado = mTotalNoPagado,
					   fecha_aplicado = dFechaActual,
					   hora_aplicado = cHoraActual
				 WHERE empresa = cNumeroEmpresa
				   AND fecha_gen = dFechaGeneracion
				   AND folio_archivo = IFolioArchivo;
			END IF;
            
			LET cNumeroTarjeta = '';
			LET vcodretCargo1 = '000';
			LET vcodretCargo2 = '000';
			LET vcodretCargo3 = '000';
            
			IF mTotalPagado > 0 or mTotalComision > 0 THEN
				IF mTotalPagado > 0 THEN
					CALL cargo_ref ("001", cSucursalCargo, "informix", cTransaccCargo, "0000", cNumeroFolio,cCuentaEje, 0, mTotalPagado, "01", " ", cNumeroTarjeta, cUsuarioAutoriza)
					RETURNING vcodretCargo1, vtranret, vfechoy, vsdodisp, vmontoret;
				ELSE
					LET vcodretCargo1 = '000';
				END IF;
				
				IF vcodretCargo1 = '000' AND mTotalComision > 0 THEN
					CALL cargo_ref ("001", cSucursalCargo, "informix", cTransaccComiDisp, "0000", cNumeroFolio,cCuentaEje, 0, mTotalComision, "01", " ", cNumeroTarjeta, cUsuarioAutoriza)
					RETURNING vcodretCargo2, vtranret, vfechoy, vsdodisp, vmontoret;
                    
					IF vcodretCargo2 = '000' THEN
						CALL cargo_ref ("001", cSucursalCargo, "informix", cTransacIvaDisp, "0000", cNumeroFolio,cCuentaEje, 0, mTotaliva, "01", " ", cNumeroTarjeta, cUsuarioAutoriza)
						RETURNING vcodretCargo3,vtranret,vfechoy,vsdodisp,vmontoret;
					END IF;
				ElIF (vcodretCargo1 = '000') AND (mTotalComision = 0) THEN
					LET vcodretCargo2 = '000';
					LET vcodretCargo3 = '000';
				END IF;
			END IF;
			
			IF (vcodretCargo1 = '000') AND (vcodretCargo2 = '000') AND (vcodretCargo3 = '000') THEN
				COMMIT WORK;
			ELSE
				ROLLBACK WORK;
                
				-- // El archivo no efectuo el cargo y deja movimientos en cero pero actualiza el status de encabezado sumario a 9
				UPDATE bdicheq:sc_nominaencabezadosumario
				   SET status = '9', --Error del cargo_ref
					   fecha_aplicado = dFechaActual,
					   hora_aplicado = cHoraActual
				 WHERE empresa = cNumeroEmpresa
				   AND fecha_gen = dFechaGeneracion
				   AND folio_archivo = iFolioArchivo;
			END IF;
            
			LET vBegin = 'N';
		END IF;  -- // Fin de validacion de tipo de empresa externas
        
		-- // Inicio de validacion de tipo de empresa = 2
		IF siTipoEmpresa = 2 THEN
			IF mImporteNoAbonado > 0 THEN
				LET iCodigoEstatus = 3;
			ELSE
				LET iCodigoEstatus = 2;
			END IF;
            
			UPDATE bdicheq:sc_nominaencabezadosumario
			   SET status = iCodigoEstatus,
				   importe_aplicado = mImporteAbonado,
				   importe_no_aplicado = mImporteNoAbonado,
				   folio_dispersion = cNumeroFolio,
				   iva = 0,
				   comision = 0,
				   fecha_aplicado = dFechaActual,
				   hora_aplicado = cHoraActual
			 WHERE empresa = cNumeroEmpresa
			   AND fecha_gen = dFechaGeneracion
			   AND folio_archivo = IFolioArchivo;
            
			COMMIT WORK;
            
			CALL sp_conciliaciondispersionnomina (cNombreArchivo)
			RETURNING v_cCodRet, cNombreArchivoConciliacion;
            
			CONTINUE FOREACH;
		END IF;  -- // Fin de validacion de tipo de empresa = 2
            
		-- // Procedimiento para generar conciliacion del archivo dispersado
		CALL sp_conciliaciondispersionnomina (cNombreArchivo)
		RETURNING v_cCodRet, cNombreArchivoConciliacion;
        
		CONTINUE FOREACH;
	END FOREACH;
    
	LET vcodret ='00000';
    
	-- // Se Corre este procedimiento para enviar los registros procesados a las tablas historicas.
	EXECUTE PROCEDURE sp_dispersiontraspasomovtos()
	INTO v_cCodRet;
    
	IF v_cCodRet <> "00000" AND v_cCodRet <> "00001" THEN
	   LET vcodret = '100'; --los registros ya fueron enviados a la tabla historica
	END IF;
    
	RETURN vcodret;
    
    END;
    
END PROCEDURE

DOCUMENT
'MODIFICO :Jesus Antonio Bastidas Lopez',
'DESCRIPCION: Se valida Si la empresa es interna y su concepto distinto a nomina entonces se toma como externa para generar cobros correspondientes.',
'Captacion',
'FECHA : Octubre de 2008',
'VERSION: 200810',
'BD    : BDICHEQ',
'MODIFICO :Cristian Valentina Aguilar',
'DESCRIPCION: El cambio realizado permite que la dispersión de la nómina se ejecute, aún cuando las cuentas estén bloqueadas, dependiendo si el motivo permite cargos o abonos',
'Captacion',
'FECHA : Marzo de 2009',
'VERSION: 200903',
'MODIFICO: Jesus Antonio Bastidas Lopez',
'DESCRIPCION: Se optimizo y se generaron 2 procesos de complemento"',
'FECHA: Abril de 2009',
'VERSION: 200904',
'MODIFICO: Jesus Antonio Bastidas Lopez',
'DESCRIPCION: Se optimizo para una mejor lectura de codigo y se generaron 2 procesos de complemento donde se valida el estatus de las cuentas y otro que obtiene"',
'las transacciones utilizadas en el proceso de dispercion, adapto para nomina altas nuevas empresa 001',
'FECHA : Octubre de 2009',
'VERSION: 20091013',
'MODIFICO: Valentin Lopez Valenzuela',
'DESCRIPCION: Se cambia los estatus <> 1 por estatus =0, se realiza una consulta al tabla sc_nominamovimientos con left join a la sc_maecheq y se sustituye la funcionalidad del sp_nominatotalivacomision por variables acumuladas.',
'Captacion',
'FECHA : Enero de 2011',
'VERSION: 201101';

CREATE PROCEDURE "informix".sp_ctamec_generarrpthojadefirmas_pba (pEmpresa CHAR(3), pCuenta CHAR(20))

	-- DATOS A REGRESAR --
RETURNING	CHAR(6)		AS COD_RET,			 -- Codigo de retorno
			CHAR(60)	AS MENSAJE_EJEC,	 -- Mensaje de la ejecucion
			CHAR(40)	AS DESC_PRODUCTO,	 -- Descripcion del producto
			CHAR(20)	AS NUM_CTE,			 -- Numero de cliente
			CHAR(104) 	AS NOMBRE_CTE,    	 -- Nombre de cliente
			CHAR(4)		AS COD_SUCURSAL,	 -- Codigo de sucursal
			CHAR(30)	AS DESC_MONEDA,		 -- Descripcion de la moneda
			DATE		AS FECHA_ALTA,		 -- Fecha de alta de la cuenta
			DATE		AS FECHA_MODIFIC,	 -- Fecha de modificacion de firmantes
			CHAR(20)	AS REGIMEN,			 -- Regimen de firma relacionado a la cuenta
			CHAR(20)    AS ESPECIF_MANEJO,	 -- Especificaciones de manejo del regimen de la firma
			CHAR(104)	AS NOMBRE_FIRMANTE1,  -- Nombre del firmante	
			CHAR(20)    AS FIRMANTE1,
			CHAR(104)	AS NOMBRE_FIRMANTE2,  -- Nombre del firmante	
			CHAR(20)    AS FIRMANTE2,
			CHAR(104)	AS NOMBRE_FIRMANTE3,  -- Nombre del firmante	
			CHAR(20)    AS FIRMANTE3,
			CHAR(104)	AS NOMBRE_FIRMANTE4,  -- Nombre del firmante	
			CHAR(20)    AS FIRMANTE4;
	
	--	VARIABLES CONTROL DE ERRORES --
	
	DEFINE cCodRet			CHAR(6);
	DEFINE sql_err			INTEGER;
	DEFINE cMensaje			CHAR(60);
	
	-- VARIABLES --
	
	DEFINE cNumcte			CHAR(20);
	DEFINE cNombre			CHAR(104);
	DEFINE cCodSuc			CHAR(4);	
	DEFINE cCodProd			CHAR(4);
	DEFINE cNomProd			CHAR(40);
	DEFINE cCodMoneda		CHAR(2);
	DEFINE dfecha_alta		DATE;
	DEFINE cCodRegimen		CHAR(1);
	DEFINE cDescRegimen		CHAR(20);
	DEFINE cCombinacion		CHAR(20);
	DEFINE cDescMoneda		CHAR(30);
	DEFINE dUltModif		DATE;
	DEFINE cNumcteFirm		CHAR(20);
	DEFINE cNombreFirm		CHAR(104);
	DEFINE cNombreFirm1		CHAR(104);
	DEFINE cFirma1          CHAR(20);
	DEFINE cNombreFirm2		CHAR(104);
	DEFINE cFirma2          CHAR(20);
	DEFINE cNombreFirm3		CHAR(104);
	DEFINE cFirma3          CHAR(20);
	DEFINE cNombreFirm4		CHAR(104);
	DEFINE cFirma4          CHAR(20);
    DEFINE sSecuencia       SMALLINT;
    DEFINE iNumRegs         INTEGER;
    DEFINE iContador        INTEGER;
	DEFINE cSufijo          CHAR(60);	--DSB 16/05/2013
	
	-- INICIALIZACION DE VARIABLES --
	
	LET cCodRet			= '000000';
	LET cMensaje		= 'LA EJECUCION SE REALIZO EXITOSAMENTE';
	LET cCodSuc			= '';
	LET cNumcte			= '';
	LET cCodProd		= '';
	LET cNomProd		= '';
	LET cCodMoneda		= '';
	LET cNombre			= '';
	LET dfecha_alta		= '';
	LET cCodRegimen		= '';
	LET cDescRegimen	= '';
	LET cCombinacion	= '';
	LET cDescMoneda		= '';
	LET dUltModif		= '01/01/2000';
	LET cNumcteFirm		= '';
	LET cNombreFirm     = '';
	LET cNombreFirm1    = '';
	LET cFirma1         = 'C A N C E L A D O';
	LET cNombreFirm2    = '';
	LET cFirma2         = 'C A N C E L A D O';
	LET cNombreFirm3    = '';
	LET cFirma3         = 'C A N C E L A D O';
    LET cNombreFirm4    = '';
    LET cFirma4         = 'C A N C E L A D O';
    LET sSecuencia      = 0;
    LET iNumRegs        = 0;
    LET iContador       = 0;
	LET cSufijo         = '';	--DSB 16/05/2013

	-- CONTROL DE ERRORES --	
	BEGIN
	ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET cCodRet = sql_err;
            LET cMensaje = 'ERROR INESPERADO EN LA EJECUCION';
			
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
        END IF
	END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
    --SET DEBUG FILE TO "/respaldosbd/joseluis/sp_ctamec_generarrpthojadefirmas.out";
    --TRACE ON;
	
	-- VALIDACION DE PARAMETROS
	IF pEmpresa = '' OR pEmpresa IS NULL OR pCuenta = '' OR pCuenta IS NULL THEN
		LET cCodRet = '100';
		LET cMensaje = 'ERROR EN LOS PARAMETROS; AMBOS PARAMETROS SON OBLIGATORIOS';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
					
	ELIF LENGTH(pEmpresa) <> 3 OR pEmpresa <> '001' THEN
		LET cCodRet = '500';
		LET cMensaje = 'PARAMETRO EMPRESA NO VALIDO; VERIFIQUE';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	END IF;
	
	-- CONSULTA DE INFORMACION DE LA CUENTA
	SELECT sucursal, num_cte, producto
	INTO cCodSuc, cNumcte, cCodProd
	FROM bdicheq:'informix'.sc_maechq
	WHERE empresa = pEmpresa
	AND cuenta = pCuenta;
	
	-- SE VALIDA SI LA CUENTA EXISTE
	IF cNumcte IS NULL OR cNumcte = '' THEN
		LET cCodRet = '200';
		LET cMensaje = 'ERROR; NO EXISTE LA CUENTA';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	END IF;
	
	-- SE TOMA INFORMACION DE LA MONEDA
	SELECT nombre, divisa
	INTO cNomProd, cCodMoneda
	FROM bdicheq:'informix'.sc_producto
	WHERE empresa = pEmpresa
	AND producto = cCodProd;
	
	-- SE VALIDA SI EL PRODUCTO EXISTE
	IF cNomProd IS NULL OR cNomProd = '' THEN
		LET cCodRet = '210';
		LET cMensaje = 'ERROR; NO EXISTE EL PRODUCTO';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	END IF;

	-- SE TOMA EL NOMBRE DEL CLIENTE .. YA SEA PERSONA FISICA O MORAL
	SELECT TRIM(nombre1)|| ' ' || TRIM(nombre2) || ' ' || TRIM(apell_paterno) || ' ' || TRIM(apell_materno) || ' ' || TRIM(razon_social)
	INTO cNombre
	FROM bdinteg:'informix'.si_cliente
	WHERE empresa = pEmpresa
	AND numcte = cNumcte;	
	
	--DSB 16/05/2013
	SELECT NVL(descripcion, '')
	INTO cSufijo
	FROM bdinteg:"informix".si_sufijos suf,
	bdinteg:"informix".si_ctepm cte
	WHERE suf.codigo = cte.sufijo 
	AND cte.numcte = cNumCte;
	LET cNombre = TRIM(cNombre)||" "||TRIM(NVL(cSufijo, ''));
	
	-- SE CONSULTA INFORMACION DE LA CUENTA
	SELECT fecha_alta, reg_firmas
	INTO dfecha_alta, cCodRegimen
	FROM bdicheq:'informix'.sc_maenoc
	WHERE empresa = pEmpresa
	AND cuenta = pCuenta;
	
	-- SE CONSULTA INFORMACION DEL REGIMEN DE FIRMA RELACIONADO CON LA CUENTA
	SELECT descripcion, combinacion
	INTO cDescRegimen, cCombinacion
	FROM bdicntchq:'informix'.sq_catregimen
	WHERE cve_regimen = cCodRegimen;
	
	-- SE VALIDA QUE EL REGIMEN ES CORRECTO
	IF cDescRegimen IS NULL OR cDescRegimen = '' THEN
		LET cCodRet = '220';
		LET cMensaje = 'ERROR; NO EXISTE EL REGIMEN DE FIRMAS';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	END IF;
	
	-- SE TOMA INFORMACION DE LA MONEDA
	SELECT descripcion
	INTO cDescMoneda
	FROM bdinteg:'informix'.si_divisas
	WHERE divisa = cCodMoneda;
	
	-- SE VALIDA QUE LA MONEDA EXISTE
	IF cDescMoneda IS NULL OR cDescMoneda = '' THEN
		LET cCodRet = '230';
		LET cMensaje = 'ERROR; NO EXISTE LA MONEDA';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	END IF;
	
	-- SE TOMA LA FECHA DEL MAS RECIENTE REGISTRO DE FIRMANTES
	SELECT {+INDEX(bdinteg:si_cterelacionado idx_si_cterelacionado3)} MAX(fecha_insert)
	INTO dUltModif
	FROM bdinteg:'informix'.si_cterelacionado
	WHERE empresa = pEmpresa
	AND cuenta = pCuenta;
	
	-- SE VALIDA QUE EXISTAN FIRMANTES
	IF dUltModif IS NULL OR dUltModif = '' THEN
		LET cCodRet = '333';
		LET cMensaje = 'LA CUENTA NO TIENE FIRMANTES RELACIONADOS';
		
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	
	ELIF dfecha_alta = dUltModif THEN -- NO EXISTE FECHA DE MODIFICACION, SOLO DE CREACION
		LET dUltModif = '01/01/2000';	
	END IF;
	
	-- SE HACE MAYUSCULA LA DESCRIPCION DEL REGIMEN
	LET cDescRegimen = UPPER(cDescRegimen);	
  
	-- SE CONSULTAN LOS FIRMANTES RELACIONADOS CON LA CUENTA
	FOREACH
		SELECT numcte, secuencia
		INTO cNumcteFirm, sSecuencia
		FROM bdicheq:'informix'.sc_firmantes
		WHERE empresa = pEmpresa
		AND cuenta = pCuenta
		ORDER BY secuencia
		
		-- SE INCREMENTA CONTADOR PARA IDENTIFICAR LA POSICION QUE OCUPARA EN EL REPORTE
		LET iContador = iContador + 1;
		
		-- SE CONSULTA EL NOMBRE DEL FIRMANTE .. SOLO PERSONA FISICA
		SELECT TRIM(nombre1)|| ' ' || TRIM(nombre2) || ' ' || TRIM(apell_paterno) || ' ' || TRIM(apell_materno)
		INTO cNombreFirm
		FROM bdinteg:'informix'.si_cliente
		WHERE empresa = pEmpresa
		AND numcte = cNumcteFirm;
		
			-- SE VALIDA SI ES EL FIRMANTE TITULAR DE LA CUENTA
			IF iContador = 1 THEN
			   LET cNombreFirm1 = cNombreFirm;
			   IF cNombreFirm1 <> '' THEN
			       LET cFirma1 = '';
			   END IF;
			   
			ELIF iContador = 2 THEN -- SE VALIDA SI ES EL FIRMANTE ADICIONAL 1 DE LA CUENTA
			   LET cNombreFirm2 = cNombreFirm;
			   IF cNombreFirm2 <> '' THEN
			       LET cFirma2 = '';
			   END IF;
			   
			ELIF iContador = 3 THEN -- SE VALIDA SI ES EL FIRMANTE ADICIONAL 2 DE LA CUENTA
			   LET cNombreFirm3 = cNombreFirm;
			   IF cNombreFirm3 <> '' THEN
			       LET cFirma3 = '';
			   END IF;
			   
			ELIF iContador = 4 THEN -- SE VALIDA SI ES EL FIRMANTE ADICIONAL 3 DE LA CUENTA
			   LET cNombreFirm4 = cNombreFirm;
			   IF cNombreFirm4 <> '' THEN
			       LET cFirma4 = '';
			   END IF;

			END IF;
            
	END FOREACH;
		-- SE REALIZA SOLO UN RETORNO QUE INCLUYE TODA LA INFORMACION DE LA CUENTA.
		RETURN	TRIM(cCodRet), TRIM(cMensaje), TRIM(cNomProd), TRIM(cNumcte), TRIM(cNombre), TRIM(cCodSuc), TRIM(cDescMoneda), dfecha_alta, dUltModif, TRIM(cDescRegimen), TRIM(cCombinacion),
				TRIM(cNombreFirm1), TRIM(cFirma1), TRIM(cNombreFirm2), TRIM(cFirma2), TRIM(cNombreFirm3), TRIM(cFirma3), TRIM(cNombreFirm4), TRIM(cFirma4);
	
END
END PROCEDURE 
DOCUMENT
'MODIFICO: Valentin Lopez',
'FECHA: 20 de Junio del 2011',
'DESCRIPCION: Procedimiento que llena el reporte de hoja de firmas.',
'VERSION: 20110620.1042',
'BD: BDICHEQ',
'Modifico: Jose Luis Polanco B.',
'Fecha: DSB 16/05/2013',
'Descripcion: Se agrega el "sufijo" a la variable de retorno "cNombre" para que aparesca en los reportes';

CREATE PROCEDURE "informix".sp_rptctasinactivascnvb( pEmpresa CHAR(3), pTipoEjec SMALLINT )
RETURNING CHAR(5), INTEGER;
       
    DEFINE Sql_Err                  INTEGER;
    DEFINE Isam_Err                 INTEGER;
    DEFINE Desc_Err                 CHAR(50);
    DEFINE vCodRet1                 CHAR(5);
    DEFINE vCodRet2                 CHAR(5);
    DEFINE vCodRet3                 CHAR(50);
    DEFINE vContador                INTEGER;
    DEFINE vContador2               INTEGER;
    DEFINE vdFechMovHisOld4         DATE;
    DEFINE vdFechMovHisOld3         DATE;
    DEFINE vdFechMovHisOld2         DATE;
    DEFINE vdFechMovHisOld          DATE;
    DEFINE vdFechMovHis             DATE;
    DEFINE vcCuenta                 CHAR(20);
    DEFINE vcProducto               CHAR(40);
    DEFINE vcNumCte                 CHAR(20);
    DEFINE vcTarjeta                CHAR(16);
    DEFINE vcSucursal               CHAR(4);
    DEFINE vcNombreCte              CHAR(100);
    DEFINE vmSdoActual              DECIMAL(18,2);
    DEFINE vdFechaUltDep            DATE;
    DEFINE vdFechaUltRet            DATE;
    DEFINE vcDomicilio              CHAR(200);
    DEFINE vcCalle                  CHAR(40);
    DEFINE vcNoExt                  CHAR(10);
    DEFINE vcNoInt                  CHAR(10);
    DEFINE vcDepto                  CHAR(10);
    DEFINE vcColonia                CHAR(40);
    DEFINE vcMuicipio               CHAR(30);
    DEFINE vcCiudad                 CHAR(20);
    DEFINE vcEstado                 CHAR(10);
    DEFINE vcCodPos                 CHAR(10);
    DEFINE vdFechaNotific           DATE;
    DEFINE vmSdoInform              DECIMAL(18,2);
    DEFINE vdFechaInactividad       DATE;
    DEFINE vdFechaMov               DATE;
    DEFINE vmMontoMov               DECIMAL(14,2);
    DEFINE iExisteConcentra         SMALLINT;
    DEFINE vdFechaConcentra         DATE;
    DEFINE vmSdoConcentra           DECIMAL(18,2);
    DEFINE vcUsuarioConcentra       CHAR(8);
    DEFINE vcResulConcentra         CHAR(10);
    DEFINE vcFolioConcentra         CHAR(16);
    DEFINE vdFechaDesconcentra      DATE;
    DEFINE vmSdoDesconcentra        DECIMAL(18,2);
    DEFINE vcUsuarioDesconcentra    CHAR(8);
    DEFINE vcFolioDesconcentra      CHAR(16);
    DEFINE vdFechaReConcentra       DATE;
    DEFINE vmSdoReConcentra         DECIMAL(18,2);
    DEFINE vcResulReConcentra       CHAR(10);
    DEFINE vcFolioReConcentra       CHAR(16);
    DEFINE vdFechaTraspBenef        DATE;
    DEFINE vmSdoTraspBenef          DECIMAL(18,2);
    DEFINE vcDescTraspBenef         CHAR(10);
    DEFINE vcResulTraspBenef        CHAR(10);
    DEFINE vcFolioTraspBenef        CHAR(16);
    DEFINE vcUsuarioTraspBenef      CHAR(8);
    DEFINE vdValorSM                DECIMAL(14,2);
    DEFINE vdFechaMin               DATE;
    DEFINE vcStatusMov              CHAR(1);
    
    LET Sql_Err	= 0;
    LET Isam_Err = 0;
    LET Desc_Err = '';
    LET vCodRet1 = '000';
    LET vCodRet2 = '';
    LET vCodRet3 = '';
    LET vContador = 0;
    LET vContador2 = 0;
    LET vdFechMovHisOld4 = '';
    LET vdFechMovHisOld3 = '';
    LET vdFechMovHisOld2 = '';
    LET vdFechMovHisOld = '';
    LET vdFechMovHis = '';
    LET vcCuenta = '';
    LET vcProducto = '';
    LET vcNumCte = '';
    LET vcTarjeta = '';
    LET vcSucursal = '';
    LET vcNombreCte = '';
    LET vmSdoActual = 0.00;
    LET vdFechaUltDep = '';
    LET vdFechaUltRet = '';
    LET vcDomicilio = '';
    LET vcCalle = '';
    LET vcNoExt = '';
    LET vcNoInt = '';
    LET vcDepto = '';
    LET vcColonia = '';
    LET vcMuicipio = '';
    LET vcCiudad = '';
    LET vcEstado = '';
    LET vcCodPos = '';
    LET vdFechaNotific = '';
    LET vmSdoInform = '';
    LET vdFechaInactividad = '';
    LET vdFechaMov = '';
    LET vmMontoMov = 0.00;
    LET iExisteConcentra = 0;
    LET vdFechaConcentra = '';
    LET vmSdoConcentra = 0.00;
    LET vcUsuarioConcentra = '';
    LET vcResulConcentra = '';
    LET vcFolioConcentra = '';
    LET vdFechaDesconcentra = '';
    LET vmSdoDesconcentra = 0.00;
    LET vcUsuarioDesconcentra = '';
    LET vcFolioDesconcentra = '';
    LET vdFechaReConcentra = '';
    LET vmSdoReConcentra = 0.00;
    LET vcResulReConcentra = '';
    LET vcFolioReConcentra = '';
    LET vdFechaTraspBenef = '';
    LET vmSdoTraspBenef = 0.00;
    LET vcDescTraspBenef = '';
    LET vcResulTraspBenef = '';
    LET vcFolioTraspBenef = '';
    LET vcUsuarioTraspBenef = '';
    LET vdValorSM = 0.00;
    LET vdFechaMin = '';
    LET vcStatusMov = '';
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        SET DEBUG FILE TO "/resplogifx/conciliachq/jivan/sp_rptctasinactivascnvb.err";
        TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            LET vcCuenta = vcCuenta;
            RETURN vCodRet1, vContador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/jivan/sp_rptctasinactivascnvb.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    CREATE TEMP TABLE sc_rptctasinactivascnvb
      (
        producto char(40),
        numcte char(20),
        num_tarjeta char(16),
        cuenta char(20),
        sucursal char(4),
        nombre_cte char(100),
        sdo_actual decimal(18,2), 
        fecha_inactividad date,
        fecha_ult_dep date,
        fecha_ult_ret date,
        domicilio char(200),
        calle char(40),
        no_ext char(10),
        no_int char(10),
        depto char(10),
        colonia char(40),
        muicipio char(30),
        ciudad char(20),
        estado char(10),
        cod_pos char(10),
        fecha_notific date,
        sdo_inform decimal(18,2),
        fecha_mov date,
        monto_mov decimal(14,2),
        status_cta char(1),
        fecha_concentra date,
        sdo_concentra decimal(18,2),
        usuario_concentra char(8),
        resul_concentra char(10),
        folio_concentra char(16),
        fecha_desconcentra date,
        sdo_desconcentra decimal(18,2),
        usuario_desconcentra char(8),
        folio_desconcentra char(16),
        fecha_reconcentra date,
        sdo_reconcentra decimal(18,2),
        resul_reconcentra char(10),
        folio_reconcentra char(16),
        fecha_trasp_benef date,
        sdo_trasp_benef decimal(18,2),
        desc_trasp_benef char(10),
        resul_trasp_benef char(10),
        folio_trasp_benef char(16),
        usuario_trasp_benef char(8)
      ) 
    WITH NO LOG LOCK MODE ROW;
    
    SELECT valor * 300
      INTO vdValorSM
      FROM sc_param
     WHERE codparam = 'smdf';
    
    SELECT valor
      INTO vdFechMovHisOld4
      FROM sc_param
     WHERE codparam = 'FechaIniMovhisOld4';
     
    SELECT valor
      INTO vdFechMovHisOld3
      FROM sc_param
     WHERE codparam = 'vfechconmovhisold3';
     
    SELECT valor
      INTO vdFechMovHisOld2
      FROM sc_param
     WHERE codparam = 'FechaIniMovhisOld2';
     
    SELECT valor
      INTO vdFechMovHisOld
      FROM sc_param
     WHERE codparam = 'FechIniCon_movhis_ol';
     
    SELECT valor
      INTO vdFechMovHis
      FROM sc_param
     WHERE codparam = 'fechcon_movhis';
     
    SELECT ina.cuenta
      FROM sc_ctasinformadas ina,
           sc_ctasinactinfor3anios inf
     WHERE ina.cuenta = inf.cuenta
    INTO TEMP tmp_ctasinactivas WITH NO LOG;
    CREATE INDEX idxtmp_ctasinactivas_cta ON tmp_ctasinactivas(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_ctasinactivas;
    
    SELECT UNIQUE cuenta
      FROM tmp_ctasinactivas
    INTO TEMP tmp_ctainactiva WITH NO LOG;
    CREATE INDEX idxtmp_ctainactiva_cta ON tmp_ctainactiva(cuenta) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_ctainactiva;
    
    IF pTipoEjec = 1 THEN
        FOREACH 
            SELECT ina.cuenta
              INTO vcCuenta
              FROM tmp_ctainactiva ina
             WHERE ina.cuenta IN ( SELECT cuenta FROM sc_maechq WHERE cuenta = ina.cuenta AND status_cta IN('5','6','7','8') )
             
            SELECT MIN(fecha_rep) 
              INTO vdFechaMin
              FROM sc_ctasinactinfor3anios 
             WHERE cuenta = vcCuenta;
              
            SELECT UNIQUE inf.producto, inf.num_cte, inf.num_tarjeta, mae.sucursal, inf.cliente, mae.sdo_actual, inf.fech_ult_dep, inf.fech_ult_ret,
                   inf.domicilio, inf.calle, inf.no_ext, inf.no_int, inf.depto, inf.colonia, inf.municipio, inf.ciudad, inf.estado, inf.codpos,
                   inf.fecha_rep, inf.sdo_actual
              INTO vcProducto, vcNumCte, vcTarjeta, vcSucursal, vcNombreCte, vmSdoActual, vdFechaUltDep, vdFechaUltRet, 
                   vcDomicilio, vcCalle, vcNoExt, vcNoInt, vcDepto, vcColonia, vcMuicipio, vcCiudad, vcEstado, vcCodPos,
                   vdFechaNotific, vmSdoInform
              FROM sc_ctasinactinfor3anios inf,
                   sc_maechq mae,
                   sc_maenoc noc
             WHERE inf.cuenta = vcCuenta
               AND inf.fecha_rep = vdFechaMin
               AND inf.cuenta = mae.cuenta
               AND mae.empresa = noc.empresa
               AND mae.cuenta = noc.cuenta;
            
            -- // CALCULA FECHA DE INACTIVIDAD
            IF vdFechaUltRet >= vdFechaUltDep THEN
                LET vdFechaInactividad = vdFechaUltRet + 3 UNITS YEAR;
            ELSE
                LET vdFechaInactividad = vdFechaUltDep + 3 UNITS YEAR;
            END IF;
            
            -- // VERIFICA SI LA CUENTA TUVO MOVIMIENTOS PARA ACTIVARSE
            SELECT FIRST 1 fech_alt, monto_tot
              INTO vdFechaMov, vmMontoMov
              FROM sc_movhis_old4
             WHERE empresa = pEmpresa
               AND cuenta = vcCuenta
               AND ( fech_alt >= vdFechMovHisOld4 AND fech_alt < vdFechMovHisOld3 )
               AND fech_alt > vdFechaNotific
               AND cancelad <> 'S'
               AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' )
               AND num_serial = ( SELECT MIN(num_serial)
                                    FROM sc_movhis_old4
                                   WHERE empresa = pEmpresa
                                     AND cuenta = vcCuenta
                                     AND ( fech_alt >= vdFechMovHisOld4 AND fech_alt < vdFechMovHisOld3 )
                                     AND fech_alt > vdFechaNotific
                                     AND cancelad <> 'S' 
                                     AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' ) );
            
            IF vdFechaMov is null OR vdFechaMov = '' THEN
                SELECT FIRST 1 fech_alt, monto_tot
                  INTO vdFechaMov, vmMontoMov
                  FROM sc_movhis_old3
                 WHERE empresa = pEmpresa
                   AND cuenta = vcCuenta
                   AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                   AND fech_alt > vdFechaNotific
                   AND cancelad <> 'S'
                   AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' )
                   AND num_serial = ( SELECT MIN(num_serial)
                                        FROM sc_movhis_old3
                                       WHERE empresa = pEmpresa
                                         AND cuenta = vcCuenta
                                         AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                                         AND fech_alt > vdFechaNotific
                                         AND cancelad <> 'S'
                                         AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' ) );
                
                IF vdFechaMov is null OR vdFechaMov = '' THEN
                    SELECT FIRST 1 fech_alt, monto_tot
                      INTO vdFechaMov, vmMontoMov
                      FROM sc_movhis_old2
                     WHERE empresa = pEmpresa
                       AND cuenta = vcCuenta
                       AND ( fech_alt >= vdFechMovHisOld2 AND fech_alt < vdFechMovHisOld )
                       AND fech_alt > vdFechaNotific
                       AND cancelad <> 'S'
                       AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' )
                       AND num_serial = ( SELECT MIN(num_serial)
                                            FROM sc_movhis_old2
                                           WHERE empresa = pEmpresa
                                             AND cuenta = vcCuenta
                                             AND ( fech_alt >= vdFechMovHisOld2 AND fech_alt < vdFechMovHisOld )
                                             AND fech_alt > vdFechaNotific
                                             AND cancelad <> 'S'
                                             AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' ) );
                                             
                    IF vdFechaMov is null OR vdFechaMov = '' THEN
                        SELECT FIRST 1 fech_alt, monto_tot
                          INTO vdFechaMov, vmMontoMov
                          FROM sc_movhis_old
                         WHERE empresa = pEmpresa
                           AND cuenta = vcCuenta
                           AND ( fech_alt >= vdFechMovHisOld AND fech_alt < vdFechMovHis )
                           AND fech_alt > vdFechaNotific
                           AND cancelad <> 'S'
                           AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' )
                           AND num_serial = ( SELECT MIN(num_serial)
                                                FROM sc_movhis_old
                                               WHERE empresa = pEmpresa
                                                 AND cuenta = vcCuenta
                                                 AND ( fech_alt >= vdFechMovHisOld AND fech_alt < vdFechMovHis )
                                                 AND fech_alt > vdFechaNotific
                                                 AND cancelad <> 'S' 
                                                 AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' ) );
                                                 
                        IF vdFechaMov is null OR vdFechaMov = '' THEN
                            SELECT FIRST 1 fech_alt, monto_tot
                              INTO vdFechaMov, vmMontoMov
                              FROM sc_movhis
                             WHERE empresa = pEmpresa
                               AND cuenta = vcCuenta
                               AND fech_alt >= vdFechMovHis
                               AND fech_alt > vdFechaNotific
                               AND cancelad <> 'S'
                               AND transacc NOT IN ( '0320','0321','0322','0323','0324','0242' )
                               AND num_serial = ( SELECT MIN(num_serial)
                                                    FROM sc_movhis
                                                   WHERE empresa = pEmpresa
                                                     AND cuenta = vcCuenta
                                                     AND fech_alt >= vdFechMovHis
                                                     AND fech_alt > vdFechaNotific
                                                     AND cancelad <> 'S' 
