                                             AND cancelad <> 'S'
                                             AND transacc = '0324');
                                             
                    IF vcFolioDesconcentra is null OR vcFolioDesconcentra = '' THEN
                        SELECT FIRST 1 usuario, folio_suc
                          INTO vcUsuarioDesconcentra, vcFolioDesconcentra
