                         WHERE empresa = pEmpresa
                           AND cuenta = vcCuenta
                           AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                           AND fech_alt > vdFechaConcentra
                           AND cancelad <> 'S'
                           AND transacc = '0324'
                           AND num_serial = ( SELECT MIN(num_serial)
                                                FROM sc_movhis_old3
                                               WHERE empresa = pEmpresa
                                                 AND cuenta = vcCuenta
                                                 AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                                                 AND fech_alt > vdFechaConcentra
                                                 AND cancelad <> 'S'
                                                 AND transacc = '0324');
                        
                        IF vcFolioDesconcentra is null OR vcFolioDesconcentra = '' THEN
                            SELECT FIRST 1 usuario, folio_suc
                              INTO vcUsuarioDesconcentra, vcFolioDesconcentra
                              FROM sc_movhis_old2
                             WHERE empresa = pEmpresa
                               AND cuenta = vcCuenta
                               AND ( fech_alt >= vdFechMovHisOld2 AND fech_alt < vdFechMovHisOld )
                               AND fech_alt > vdFechaConcentra
                               AND cancelad <> 'S'
                               AND transacc = '0324'
                               AND num_serial = ( SELECT MIN(num_serial)
                                                    FROM sc_movhis_old2
                                                   WHERE empresa = pEmpresa
                                                     AND cuenta = vcCuenta
                                                     AND ( fech_alt >= vdFechMovHisOld2 AND fech_alt < vdFechMovHisOld )
                                                     AND fech_alt > vdFechaConcentra
                                                     AND cancelad <> 'S'
                                                     AND transacc = '0324');
                                                     
                            IF vcFolioDesconcentra is null OR vcFolioDesconcentra = '' THEN
                                SELECT FIRST 1 usuario, folio_suc
                                  INTO vcUsuarioDesconcentra, vcFolioDesconcentra
                                  FROM sc_movhis_old
                                 WHERE empresa = pEmpresa
                                   AND cuenta = vcCuenta
                                   AND ( fech_alt >= vdFechMovHisOld AND fech_alt < vdFechMovHis )
                                   AND fech_alt > vdFechaConcentra
                                   AND cancelad <> 'S'
                                   AND transacc = '0324'
                                   AND num_serial = ( SELECT MIN(num_serial)
                                                        FROM sc_movhis_old
                                                       WHERE empresa = pEmpresa
                                                         AND cuenta = vcCuenta
                                                         AND ( fech_alt >= vdFechMovHisOld AND fech_alt < vdFechMovHis )
                                                         AND fech_alt > vdFechaConcentra
                                                         AND cancelad <> 'S'
                                                         AND transacc = '0324');
                                                         
                                IF vcFolioDesconcentra is null OR vcFolioDesconcentra = '' THEN
                                    SELECT FIRST 1 usuario, folio_suc
                                      INTO vcUsuarioDesconcentra, vcFolioDesconcentra
                                      FROM sc_movhis
                                     WHERE empresa = pEmpresa
                                       AND cuenta = vcCuenta
                                       AND fech_alt >= vdFechMovHis
                                       AND fech_alt > vdFechaConcentra
                                       AND cancelad <> 'S'
                                       AND transacc = '0324'
                                       AND num_serial = ( SELECT MIN(num_serial)
                                                            FROM sc_movhis
                                                           WHERE empresa = pEmpresa
                                                             AND cuenta = vcCuenta
                                                             AND fech_alt >= vdFechMovHis
                                                             AND fech_alt > vdFechaConcentra
                                                             AND cancelad <> 'S'
                                                             AND transacc = '0324');
                                                             
                                    IF vcFolioDesconcentra is null OR vcFolioDesconcentra = '' THEN
                                        LET vdFechaDesconcentra = '';
                                        LET vmSdoDesconcentra = null;
                                        LET vcUsuarioDesconcentra = '';
                                        LET vcFolioDesconcentra = '';
                                    END IF;
                                END IF;
