                   AND ( fech_alt >= vdFechMovHisOld4 AND fech_alt < vdFechMovHisOld3 )
                   AND fech_alt > vdFechaConcentra
                   AND cancelad <> 'S'
                   AND transacc = '0320'
                   AND num_serial = ( SELECT MIN(num_serial)
                                        FROM sc_movhis_old4
                                       WHERE empresa = pEmpresa
                                         AND cuenta = vcCuenta
                                         AND ( fech_alt >= vdFechMovHisOld4 AND fech_alt < vdFechMovHisOld3 )
                                         AND fech_alt > vdFechaConcentra
                                         AND cancelad <> 'S'
                                         AND transacc = '0320');
                       
                IF vdFechaReConcentra is null OR vdFechaReConcentra = '' THEN
                    SELECT FIRST 1 fech_alt, folio_suc
                      INTO vdFechaReConcentra, vcFolioReConcentra
                      FROM sc_movhis_old3
                     WHERE empresa = pEmpresa
                       AND cuenta = vcCuenta
                       AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                       AND fech_alt > vdFechaConcentra
                       AND cancelad <> 'S'
                       AND transacc = '0320'
                       AND num_serial = ( SELECT MIN(num_serial)
                                            FROM sc_movhis_old3
                                           WHERE empresa = pEmpresa
                                             AND cuenta = vcCuenta
                                             AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                                             AND fech_alt > vdFechaConcentra
                                             AND cancelad <> 'S'
                                             AND transacc = '0320');
                                             
                    IF vdFechaReConcentra is null OR vdFechaReConcentra = '' THEN
                        SELECT FIRST 1 fech_alt, folio_suc
                          INTO vdFechaReConcentra, vcFolioReConcentra
                          FROM sc_movhis_old2
                         WHERE empresa = pEmpresa
                           AND cuenta = vcCuenta
                           AND ( fech_alt >= vdFechMovHisOld2 AND fech_alt < vdFechMovHisOld )
                           AND fech_alt > vdFechaConcentra
                           AND cancelad <> 'S'
                           AND transacc = '0320'
                           AND num_serial = ( SELECT MIN(num_serial)
                                                FROM sc_movhis_old2
                                               WHERE empresa = pEmpresa
                                                 AND cuenta = vcCuenta
                                                 AND ( fech_alt >= vdFechMovHisOld2 AND fech_alt < vdFechMovHisOld )
                                                 AND fech_alt > vdFechaConcentra
                                                 AND cancelad <> 'S'
                                                 AND transacc = '0320');
                                                 
                        IF vdFechaReConcentra is null OR vdFechaReConcentra = '' THEN
                            SELECT FIRST 1 fech_alt, folio_suc
                              INTO vdFechaReConcentra, vcFolioReConcentra
                              FROM sc_movhis_old
                             WHERE empresa = pEmpresa
                               AND cuenta = vcCuenta
                               AND ( fech_alt >= vdFechMovHisOld AND fech_alt < vdFechMovHis )
                               AND fech_alt > vdFechaConcentra
                               AND cancelad <> 'S'
                               AND transacc = '0320'
                               AND num_serial = ( SELECT MIN(num_serial)
                                                    FROM sc_movhis_old
                                                   WHERE empresa = pEmpresa
                                                     AND cuenta = vcCuenta
                                                     AND ( fech_alt >= vdFechMovHisOld AND fech_alt < vdFechMovHis )
                                                     AND fech_alt > vdFechaConcentra
                                                     AND cancelad <> 'S'
                                                     AND transacc = '0320');
                                                     
                            IF vdFechaReConcentra is null OR vdFechaReConcentra = '' THEN
                                SELECT FIRST 1 fech_alt, folio_suc
                                  INTO vdFechaReConcentra, vcFolioReConcentra
                                  FROM sc_movhis
                                 WHERE empresa = pEmpresa
                                   AND cuenta = vcCuenta
                                   AND fech_alt >= vdFechMovHis 
                                   AND fech_alt > vdFechaConcentra
                                   AND cancelad <> 'S'
                                   AND transacc = '0320'
                                   AND num_serial = ( SELECT MIN(num_serial)
                                                        FROM sc_movhis
                                                       WHERE empresa = pEmpresa
                                                         AND cuenta = vcCuenta
                                                         AND fech_alt >= vdFechMovHis 
                                                         AND fech_alt > vdFechaConcentra
                                                         AND cancelad <> 'S'
                                                         AND transacc = '0320');
                            END IF;
                        END IF;
                    END IF;
                END IF;
                
                IF vdFechaReConcentra is not null OR vdFechaReConcentra <> '' THEN
                    LET vdFechaReConcentra = vdFechaReConcentra;
                    LET vmSdoReConcentra = vmSdoConcentra;
                    LET vcResulReConcentra = 'EXITOSO';
                    LET vcFolioReConcentra = vcFolioReConcentra;
                ELSE
                    LET vdFechaReConcentra = '';
                    LET vmSdoReConcentra = null;
                    LET vcResulReConcentra = '';
                    LET vcFolioReConcentra = '';
                END IF;
                
                -- // VALIDA DATOS DE TRASPASO A LA BENEFICENCIA PUBLICA
                SELECT FIRST 1 folio_suc
                  INTO vcFolioTraspBenef
                  FROM sc_movhis_old4
                 WHERE empresa = pEmpresa
                   AND cuenta = vcCuenta
                   AND ( fech_alt >= vdFechMovHisOld4 AND fech_alt < vdFechMovHisOld3 )
                   AND fech_alt > vdFechaConcentra
                   AND cancelad <> 'S'
                   AND transacc = '0322'
                   AND num_serial = ( SELECT MIN(num_serial)
                                        FROM sc_movhis_old4
                                       WHERE empresa = pEmpresa
                                         AND cuenta = vcCuenta
                                         AND ( fech_alt >= vdFechMovHisOld4 AND fech_alt < vdFechMovHisOld3 )
                                         AND fech_alt > vdFechaConcentra
                                         AND cancelad <> 'S'
                                         AND transacc = '0322');
                       
                IF vcFolioTraspBenef is null OR vcFolioTraspBenef = '' THEN
                    SELECT FIRST 1 folio_suc
                      INTO vcFolioTraspBenef
                      FROM sc_movhis_old3
                     WHERE empresa = pEmpresa
                       AND cuenta = vcCuenta
                       AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                       AND fech_alt > vdFechaConcentra
                       AND cancelad <> 'S'
                       AND transacc = '0322'
                       AND num_serial = ( SELECT MIN(num_serial)
                                            FROM sc_movhis_old3
                                           WHERE empresa = pEmpresa
                                             AND cuenta = vcCuenta
                                             AND ( fech_alt >= vdFechMovHisOld3 AND fech_alt < vdFechMovHisOld2 )
                                             AND fech_alt > vdFechaConcentra
                                             AND cancelad <> 'S'
                                             AND transacc = '0322');
                                             
                    IF vcFolioTraspBenef is null OR vcFolioTraspBenef = '' THEN
                        SELECT FIRST 1 folio_suc
