CREATE PROCEDURE "informix".sp_actualiza_acumtrapres( pEmpresa CHAR(3) )
RETURNING CHAR(5), INTEGER, INTEGER;
    
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE iContador1   INTEGER;
    DEFINE iContador2   INTEGER;
    DEFINE cCuenta      CHAR(20);
    DEFINE cNumCte      CHAR(20);
    
    LET sql_err  = 0;
    LET isam_err = 0;
    LET desc_err = '';
    LET vcodret1 = '000';
    LET vcodret2 = '';
    LET vcodret3 = '';
    LET iContador1 = 0;
    LET iContador2 = 0;
    LET cCuenta = '';
    LET cNumCte = '';
    
    --- SET DEBUG FILE TO "sp_actualiza_acumtrapres.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err
        -- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actualiza_acumtrapres.err";
        -- TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1, iContador1, iContador2;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH WITH HOLD
        SELECT UNIQUE cuenta
          INTO cCuenta
          FROM sc_acumtrapres
          
        LET iContador1 = iContador1 + 1;  
        
        BEGIN WORK;
          
        SELECT num_cte
          INTO cNumCte
          FROM sc_maechq
         WHERE empresa = pEmpresa
           AND cuenta = cCuenta;
           
        UPDATE sc_acumtrapres
           SET numcte = cNumCte
         WHERE cuenta = cCuenta;
         
        IF ( dbinfo('sqlca.sqlerrd2') > 0 ) THEN
            LET iContador2 = iContador2 + 1;
            COMMIT WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        
        LET cCuenta = '';
        LET cNumCte = '';
    END FOREACH;

    RETURN vcodret1, iContador1, iContador2;

    END;

END PROCEDURE;

create procedure "informix".sp_carga_coresponsal(pempresa char(3) )
       returning char(5);

define vsqlerr integer;
define vcodret char(5);
define vfecha_hoy date;
define vconreg smallint;
define vsql char(800);
define vaniomes  CHAR(6);
define parchivo  CHAR(60);

LET vaniomes           = '';


begin
   on exception set vsqlerr
      if vsqlerr <> 0  then
         let vcodret = "00970";
         return vcodret;
      end if;
   end exception;

--SET DEBUG FILE TO "/resplogifx/conciliachq/respaldos/sp_carga_corresponsal.out";
--TRACE ON;

   let vcodret = "00000";
   select fecha_hoy into vfecha_hoy from sc_fechas where empresa = pempresa;

	/* FORMA NOMECLARUTA DEL NOMBRE DEL ARCHIVO */
    LET vaniomes = TO_CHAR(vfecha_hoy, '%Y%m');
    --perfil_AAAAMM.unl
	LET parchivo ='perfil_'||vaniomes||'.unl';
   
  
   
   select count(*) into vconreg from bdicheq:sc_param 
    where codparam ='ult_corresp'
	and valor = parchivo;
      
   if vconreg > 0 then
      let vcodret = "00969"; -- EL ARCHIVO QUE INTENTA CARGAR YA FUE CARGADO.
      return vcodret;
   
   else
   
	/* RESPALDA LA INFORMACION LA TABLA SC_CORRESPONSAL DE LA BDICHEQ */
	   let vsql = 'echo "unload to /resplogifx/conciliachq/respaldos/' || 'respaldo_corresponsales_'||vaniomes||'.unl' ||
					 ' select * from  bdicheq:sc_corresponsal; "' || ' > /resplogifx/conciliachq/respaldos/query_resp.sql';
	   system vsql;
	   let vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/respaldos/query_resp.sql";
	   system vsql;
	   
	/* Vacia tabla de informacino de corresponsales */
	
	--	begin;
			TRUNCATE TABLE "informix".sc_corresponsal;
	--	commit;
	   
	   
	/* CARGA LA LA INFORMACION DE CORRESPONSALES A LA TABLA SC_CORRESPONSAL DE LA BDICHEQ */
	   --let vsql = 'echo "load from /resplogifx/conciliachq/respaldos/' || trim'perfil_'(vaniomes)'.unl ||
	   let vsql = 'echo "load from /resplogifx/conciliachq/respaldos/' || 'perfil_'||vaniomes||'.unl' ||
				  ' insert into bdicheq:sc_corresponsal "' || ' > /resplogifx/conciliachq/respaldos/query_load.sql';
	   system vsql;
	   let vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/respaldos/query_load.sql";
	   system vsql;
	   
	   
	   
		begin;
		update "informix".sc_corresponsal
		set estatus ='Reprobado'
		where estatus ='No Aprobado';
		commit;

		begin;
		update "informix".sc_corresponsal
		set estatus ='No ha presentado'
		where estatus ='Pendiente';
		commit;
   
   
		UPDATE bdicheq:sc_param  set valor = parchivo
		where codparam ='ult_corresp';
	
   
   end if

   return vcodret;
end
end procedure;

CREATE PROCEDURE "informix".upd_movdia_pba(pempresa char(3))

RETURNING CHAR(5);

   DEFINE vcodret     	CHAR(5);
   DEFINE sql_err     	INTEGER;
   DEFINE vcuenta	CHAR(20);
   DEFINE vnum_serial 	INTEGER;

   LET vcodret = "000";

   BEGIN

   ON EXCEPTION
       SET sql_err
       IF sql_err <> 0 THEN
	    LET vcodret = sql_err;
           RETURN vcodret;
       END IF;
   END EXCEPTION;

   -- SET DEBUG FILE TO "./upd_movdia.out";
   -- TRACE ON;

   SET ISOLATION TO DIRTY READ;
   SET LOCK MODE TO WAIT 3;
   
   FOREACH
       SELECT {+ INDEX(sc_movdia idx_movdia1a)}
	      num_serial, cuenta
	 INTO vnum_serial, vcuenta
         FROM sc_movdia
        WHERE empresa = pempresa
	  AND cuenta IS NOT NULL
          AND transacc = "0270"
          AND usuario = "informix"

       UPDATE {+ INDEX(sc_movdia idx_movdia1a)} sc_movdia
          SET transacc = "0830",
	      transacc_suc = "0830"
	WHERE empresa = pempresa
	  AND cuenta = vcuenta
          AND transacc = "0270"
	  AND num_serial = vnum_serial
        AND usuario = "informix";

   END FOREACH

   END;

   RETURN vcodret;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_conciliachq_pba( pempresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER;
    
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vcontador1   INTEGER;
    DEFINE vcontador2   INTEGER;
    DEFINE vcontador3   INTEGER;
    DEFINE vcomienza1   SMALLINT;
    DEFINE ven_transacc SMALLINT;
    
    DEFINE vsql          CHAR(600);
    DEFINE vstmt         CHAR(250);
    DEFINE vfecha_hoy    DATE;
    DEFINE vfecha_ant    DATE;
    DEFINE vpri_hab_mes  DATE;
    DEFINE vfecha_actual DATE;
    DEFINE vproceso      CHAR(11);
    DEFINE vsistema      CHAR(2);
    DEFINE vexiste       INTEGER;
    DEFINE vexistefin    INTEGER;
    DEFINE vusuario      CHAR(10);
    DEFINE vfechaprocsdo DATE;
    
    DEFINE vcuenta      CHAR(20);
    DEFINE vnum_cte     CHAR(20);
    DEFINE vsucursal    CHAR(4);
    DEFINE vejecutivo   CHAR(8);
    DEFINE vproducto    CHAR(4);
    
    DEFINE vcapital_anterior    MONEY(18,2);
    DEFINE vcapital_calculado   MONEY(18,2);
    DEFINE vmovs_cargo_capital  MONEY(18,2);
    DEFINE vmovs_abono_capital  MONEY(18,2);
    DEFINE vcapital_actual      MONEY(18,2);
    DEFINE vdiferencia_capital  MONEY(18,2);
    
    DEFINE vinteres_anterior    MONEY(18,2);
    DEFINE vinteres_calculado   MONEY(18,2);
    DEFINE vmovs_cargo_interes  MONEY(18,2);
    DEFINE vmovs_abono_interes  MONEY(18,2);
    DEFINE vinteres_actual      MONEY(18,2);
    DEFINE vdiferencia_interes  MONEY(18,2);
    
    DEFINE vcuentafin           CHAR(20);    
    DEFINE vcuenta_cargo        CHAR(12);  
    DEFINE vcuenta_abono        CHAR(12);  
    DEFINE vmonto_tot           MONEY(14,2);
    DEFINE vexiste_cta          SMALLINT;
    
    LET vcodret1     = '000';
    LET vcodret2     = '000';
    LET vcodret3     = 'PROCESO CONCLUIDO SATISFACTORIAMENTE';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    LET vcontador1   = 0;
    LET vcontador2   = 0;
    LET vcontador3   = 0;
    LET vcomienza1   = -1;
    LET ven_transacc = 0; 
    
    LET vsql          = '';
    LET vstmt         = '';
    LET vfecha_hoy    = ''; 
    LET vfecha_ant    = '';
    LET vpri_hab_mes  = '';
    LET vfecha_actual = '';
    LET vproceso      = 'conciliachq';
    LET vsistema      = '01';
    LET vexiste       = 0;
    LET vexistefin    = 0;
    LET vusuario      = user;
    LET vfechaprocsdo = '';
    
    LET vcuenta      = ''; 
    LET vproducto    = '';
    LET vnum_cte     = '';
    LET vsucursal    = '';
    LET vejecutivo   = '';
    
    LET vcapital_anterior   = 0.00;
    LET vcapital_calculado  = 0.00;
    LET vmovs_cargo_capital = 0.00;
    LET vmovs_abono_capital = 0.00;
    LET vcapital_actual     = 0.00;
    LET vdiferencia_capital = 0.00;
    
    LET vinteres_anterior   = 0.00;
    LET vinteres_calculado  = 0.00;
    LET vmovs_cargo_interes = 0.00;
    LET vmovs_abono_interes = 0.00;
    LET vinteres_actual     = 0.00;
    LET vdiferencia_interes = 0.00;
    
    LET vcuentafin = '';
    LET vcuenta_cargo   = '';
    LET vcuenta_abono   = '';
    LET vmonto_tot      = 0.00;
    LET vexiste_cta     = 0;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_conciliachq.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasconcilchq.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_conciliachq.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE LAS FECHAS DEL SISTEMA
    SELECT fecha_hoy, fecha_ant, pri_hab_mes, fecha_hoy
      INTO vfecha_hoy, vfecha_ant, vpri_hab_mes, vfecha_actual
      FROM sc_fechas
     WHERE empresa = pempresa;
    
    -- // VALIDA LA FECHA DE AYER
    LET vfecha_hoy = vfecha_hoy - 1 UNITS DAY;
    
    CALL sp_valfechabil(vfecha_hoy, '-') 
    RETURNING vcodret1, vfecha_hoy;
    
    -- // VALIDA LA FECHA DE ANTIER
    LET vfecha_ant = vfecha_ant - 1 UNITS DAY;
    
    CALL sp_valfechabil(vfecha_ant, '-') 
    RETURNING vcodret1, vfecha_ant;
    
    -- // VERIFICA SE HAYA ACTUALIZADO LA TABLA DE SALDOS DIARIOS (SEGUNDA PARTE)
    select fecha 
      into vfechaprocsdo
      from bdinteg:sx_contproc
     where empresa = pempresa 
       and proceso = "sdoschqdes"
       and fecha   = vfecha_actual
       and sistema = vsistema
       and status_proc = 'F';
    
    if vfechaprocsdo is null then
        let vcodret1 = "950";
        let vcodret2 = "950";
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE sistema = vsistema
           AND codigo_retorno = vcodret1;
        
        return vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
    end if;
     
    -- // GUARDA REGISTRO DE CONTROL EN TABLA DE INTEGRAL
    select count(*)
      into vexiste
      from bdinteg:sx_contproc
     where empresa = pempresa
       and proceso = vproceso
       and fecha   = vfecha_hoy
       and sistema = vsistema;
    
    if vexiste = 0 then
        LET vsql = 'echo " INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||pempresa||''', '''||vproceso||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''','||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horasconcilchq.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq.sql';
        SYSTEM vstmt;
    else
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa     = pempresa
           AND proceso     = vproceso
           AND fecha       = vfecha_hoy
           AND sistema     = vsistema
           AND status_proc = "F";
           
        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||pempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horasconcilchq.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq.sql';
            SYSTEM vstmt;
        ELSE
            LET vcodret1 = "958";
            LET vcodret2 = "958";
            
            SELECT descripcion
              INTO vcodret3
              FROM bdinteg:si_codret
             WHERE sistema = vsistema
               AND codigo_retorno = vcodret1;
            
            RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
        END IF;
    end if;
      
    -- // OBTIENE EL RANGO DE CUENTAS A PROCESAR
    SELECT valor
      INTO vcuentafin
      FROM sc_param
     WHERE empresa = pempresa
       AND codparam = 'CtaIniActuaSdosComp1';
    
    -- // TABLA TEMPORAL DE MOVIMIENTOS
    SELECT { +INDEX(sc_movdia_concil idx_movdiaconc_1),
             +INDEX(bdinteg:si_transacc idx_si_transacc4),
             +INDEX(bdinteg:si_prodtran idx01_prodtran) } 
           mov.cuenta, mov.transacc, mov.monto_tot,
           TRIM(prod.c_ccmayor)||TRIM(prod.c_ccsub)||TRIM(prod.c_ccsubsub)||TRIM(prod.c_ccsssub)||TRIM(prod.c_ccssssub) AS cta_cargo,
           TRIM(prod.a_ccmayor)||TRIM(prod.a_ccsub)||TRIM(prod.a_ccsubsub)||TRIM(prod.a_ccsssub)||TRIM(prod.a_ccssssub) AS cta_abono
      FROM sc_movdia_concil mov,
           bdinteg:si_transacc tran,
           bdinteg:si_prodtran prod
     WHERE mov.fech_alt = vfecha_hoy
       AND mov.cancelad != 'S'
       AND mov.cuenta < vcuentafin
       AND mov.producto <> '1100'
       AND tran.empresa = mov.empresa
       AND tran.numero = mov.transacc
       AND tran.se_contabiliza = 'S'
       AND tran.sistema = '01'
       AND prod.transaccion = tran.numero
       AND prod.producto = mov.producto
       AND prod.sistema = tran.sistema
      INTO TEMP tmp_concilia WITH NO LOG;
      
    CREATE INDEX idx_concilia ON tmp_concilia(cuenta) ONLINE;
    CREATE INDEX idx_concilia2 ON tmp_concilia(cuenta, cta_cargo) ONLINE;
    CREATE INDEX idx_concilia3 ON tmp_concilia(cuenta, cta_abono) ONLINE;
    
    UPDATE STATISTICS HIGH FOR TABLE tmp_concilia(cuenta, cta_cargo, cta_abono);
    
    -- // FOREACH CUENTAS 
    FOREACH WITH HOLD
        SELECT chq.cuenta, chq.producto, chq.num_cte, chq.sucursal, noc.ejecutivo
          INTO vcuenta, vproducto, vnum_cte, vsucursal, vejecutivo
          FROM sc_maechq chq,
               sc_maenoc noc
         WHERE chq.empresa = pempresa
           AND chq.cuenta < vcuentafin
           AND chq.producto <> '1100'
           AND ( chq.status_cta <> '2' OR chq.fecha_proceso >= vfecha_hoy )
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
           AND noc.fecha_alta < vfecha_actual
           
        IF vcomienza1 = -1 THEN
            LET vcomienza1 = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        -- // OBTIENE SALDOS ANTERIORES
        EXECUTE PROCEDURE sp_capintafecha(vcuenta, vfecha_ant) 
        INTO vcodret1, vcapital_anterior, vinteres_anterior;
        
        IF vcodret1 = '100' THEN
            LET vcapital_anterior = 0.00;
            LET vinteres_anterior = 0.00;
            LET vcodret1 = '000';
        END IF;
        
        LET vcapital_calculado = vcapital_anterior;
        LET vinteres_calculado = vinteres_anterior;
        
        -- // OBTIENE LOS MOVIMIENTOS DE CAPITAL E INTERES
        FOREACH
            SELECT {+INDEX(tmp_concilia idx_concilia)} 
                   cta_cargo, cta_abono, monto_tot
              INTO vcuenta_cargo, vcuenta_abono, vmonto_tot
              FROM tmp_concilia
             WHERE cuenta = vcuenta
             
            IF vcuenta_cargo IN( SELECT cta_contable FROM sc_ctascontchq WHERE producto = vproducto AND tipo IN('CAPITAL','SOBREGIRO') ) THEN
                LET vcapital_calculado = vcapital_calculado - vmonto_tot;
                LET vmovs_cargo_capital = vmovs_cargo_capital + vmonto_tot;
            END IF;
                    
            IF vcuenta_abono IN( SELECT cta_contable FROM sc_ctascontchq WHERE producto = vproducto AND tipo IN('CAPITAL','SOBREGIRO') ) THEN
                LET vcapital_calculado = vcapital_calculado + vmonto_tot;
                LET vmovs_abono_capital = vmovs_abono_capital + vmonto_tot;
            END IF;
                                
            IF vcuenta_cargo IN( SELECT cta_contable FROM sc_ctascontchq WHERE producto = vproducto AND tipo = 'INTERES' ) THEN
                LET vinteres_calculado = vinteres_calculado - vmonto_tot;
                LET vmovs_cargo_interes = vmovs_cargo_interes + vmonto_tot;
            END IF;
                
            IF vcuenta_abono IN( SELECT cta_contable FROM sc_ctascontchq WHERE producto = vproducto AND tipo = 'INTERES' ) THEN
                LET vinteres_calculado = vinteres_calculado + vmonto_tot;
                LET vmovs_abono_interes = vmovs_abono_interes + vmonto_tot;
            END IF;
            
            LET vcuenta_cargo = '';
            LET vcuenta_abono = '';
            LET vmonto_tot    = 0.00;
        END FOREACH;
        
        -- // OBTIENE SALDOS ACTUALES
        EXECUTE PROCEDURE sp_capintafecha(vcuenta, vfecha_hoy) 
        INTO vcodret1, vcapital_actual, vinteres_actual;
        
        IF vcodret1 = '100' THEN
            LET vcapital_actual = 0.00;
            LET vinteres_actual = 0.00;
            LET vcodret1 = '000';
        END IF;
        
        -- // OBTIENE DIFERENCIAS
        LET vdiferencia_capital = vcapital_actual - vcapital_calculado;
        LET vdiferencia_interes = vinteres_actual - vinteres_calculado;
        
        -- // LLENA TABLA DE TODAS LAS CUENTAS
        SELECT COUNT(*)
          INTO vexiste_cta
          FROM conciliachq
         WHERE cuenta = vcuenta;
         
        IF vexiste_cta > 0 THEN
            UPDATE conciliachq
               SET fecha              = vfecha_hoy,
                   capital_anterior   = vcapital_anterior,
                   movs_cargo         = vmovs_cargo_capital,
                   movs_abono         = vmovs_abono_capital,
                   capital_calculado  = vcapital_calculado,
                   capital_actual     = vcapital_actual,
                   diferencia_capital = vdiferencia_capital,
                   interes_anterior   = vinteres_anterior,
                   movs_cargo_interes = vmovs_cargo_interes,
                   movs_abono_interes = vmovs_abono_interes,
                   interes_calculado  = vinteres_calculado,
                   interes_actual     = vinteres_actual,
                   diferencia_interes = vdiferencia_interes
             WHERE cuenta = vcuenta;
        ELSE
            INSERT INTO conciliachq VALUES
            (vfecha_hoy, vcuenta, vproducto, vnum_cte, vsucursal, vejecutivo,
             vcapital_anterior, vmovs_cargo_capital, vmovs_abono_capital, vcapital_calculado, vcapital_actual, vdiferencia_capital, 
             vinteres_anterior, vmovs_cargo_interes, vmovs_abono_interes, vinteres_calculado, vinteres_actual, vdiferencia_interes);
        END IF;
        
        -- // LLENA TABLA DE DIFERENCIAS
        IF (vdiferencia_capital != 0.00 OR vdiferencia_interes != 0.00) THEN
            INSERT INTO conciliachq_dif VALUES
            (vfecha_hoy, vcuenta, vproducto, vnum_cte, vsucursal, vejecutivo,
             vcapital_anterior, vmovs_cargo_capital, vmovs_abono_capital, vcapital_calculado, vcapital_actual, vdiferencia_capital, 
             vinteres_anterior, vmovs_cargo_interes, vmovs_abono_interes, vinteres_calculado, vinteres_actual, vdiferencia_interes); 
             
            LET vcontador2 = vcontador2 + 1;
        END IF;
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador3 = vcontador3 + 1;
        
        IF vcontador3 >= 1000 THEN
            LET vcontador3 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vcuenta      = ''; 
        LET vproducto    = '';
        LET vnum_cte     = '';
        LET vsucursal    = '';
        LET vejecutivo   = '';
        
        LET vcapital_anterior   = 0.00;
        LET vcapital_calculado  = 0.00;
        LET vmovs_cargo_capital = 0.00;
        LET vmovs_abono_capital = 0.00;
        LET vcapital_actual     = 0.00;
        LET vdiferencia_capital = 0.00;
        
        LET vinteres_anterior   = 0.00;
        LET vinteres_calculado  = 0.00;
        LET vmovs_cargo_interes = 0.00;
        LET vmovs_abono_interes = 0.00;
        LET vinteres_actual     = 0.00;
        LET vdiferencia_interes = 0.00;
        
        LET vcuenta_cargo   = '';
        LET vcuenta_abono   = '';
        LET vmonto_tot      = 0.00;
        LET vexiste_cta     = 0;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
	LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET ejecutivo = '''||vusuario||''','||
               'status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret1||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||pempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horasconcilchq.sql';
    SYSTEM vsql;
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horasconcilchq.sql';
    SYSTEM vstmt;
           
    END;
    
    RETURN vcodret1, vcodret2, vcodret3, vcontador1, vcontador2;
    
END PROCEDURE;

CREATE PROCEDURE "informix".gen_archsdos_des_comp3_pba()
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER;
    
    DEFINE vsql             char(600);
    DEFINE vstmt            char(300);
    DEFINE vaniomes         char(6);
    DEFINE vempresa         char(3);
    DEFINE vstatus_cta      char(1);
    DEFINE vcodret1         char(5); 
    DEFINE vcodret2         char(5);
    DEFINE desc_err         char(50);
    DEFINE vcodret3         char(50);
    DEFINE vproceso         char(15);
    DEFINE vusuario         char(10);
    DEFINE vcuenta          char(20);
    DEFINE vexiste_cta      char(20);
    DEFINE vexisteproc      char(20);
    DEFINE vexisteproc2     char(20);
    DEFINE vanio            char(4);
    DEFINE vsucursal        char(4);
    DEFINE vprodcrec        char(4);
    DEFINE vproducto        char(4);
    DEFINE vtrancobsbg      char(4);
    DEFINE vtranprovint     char(4);
    DEFINE vtrandesprovint  char(4);
    DEFINE vtranpagoint     char(4);
    DEFINE vmes_actual      char(2);
    DEFINE vmes_siguiente   char(2);
    DEFINE vdia             char(2);
    DEFINE vmes             char(2);
    DEFINE vsistema         char(2);
    DEFINE vcomienza        smallint;
    DEFINE ven_transacc     smallint;
    DEFINE vsqlerr          integer;
    DEFINE isam_err         integer;
    DEFINE vcontador1       integer;
    DEFINE vcontador2       integer;
    DEFINE vexiste          integer;
    DEFINE vexistefin       integer;
    DEFINE vexistecobsbg    integer;
    DEFINE vprovint         decimal(18,2);
    DEFINE vdesprov         decimal(18,2);
    DEFINE vpagoint         decimal(18,2);
    DEFINE vcap_ant         decimal(18,2);
    DEFINE vsdo_dia_ant     decimal(18,2);
    DEFINE vimp_chq_sbg     decimal(18,2);
    DEFINE vint_acum        decimal(18,2);
    DEFINE vacum_sdo_int    decimal(18,2);
    DEFINE vsdo_actual      decimal(18,2);
    DEFINE vmonto_sbg       decimal(18,2);
    DEFINE vfecha_hoy       date;
    DEFINE vfecha_ant       date;
    DEFINE vfecha_con       date;
    DEFINE vpri_hab_mes     date;
    DEFINE vfecha_alta      date;
    DEFINE vfecha_proceso   date;
    DEFINE vfec_ult_mov     date;
    DEFINE vult_hab_mes_ant DATE;
    
    LET vsql           = '';    
    LET vstmt          = '';   
    LET vaniomes       = '';  
    LET vempresa       = '001';   
    LET vstatus_cta    = '';   
    LET vcodret1       = "000";               
    LET vcodret2       = '000';
    LET desc_err       = '';  
    LET vcodret3       = 'PROCESO CONCLUIDO SATISFACTORIAMENTE'; 
    LET vproceso       = 'sdoschqdescomp3';   
    LET vusuario       = user;    
    LET vcuenta        = ''; 
    LET vexiste_cta    = ''; 
    LET vexisteproc    = '';
    LET vexisteproc2   = '';    
    LET vanio          = ''; 
    LET vsucursal      = '';
    LET vprodcrec      = '';  
    LET vproducto      = '';  
    LET vmes_actual    = '';                  
    LET vmes_siguiente = '';  
    LET vdia           = '';         
    LET vmes           = '';    
    LET vsistema       = '01';   
    LET vcomienza      = -1;                  
    LET ven_transacc   = 0; 
    LET vsqlerr        = 0;                   
    LET isam_err       = 0;
    LET vcontador1     = 0;                   
    LET vcontador2     = 0;
    LET vexiste        = 0;                   
    LET vexistefin     = 0;
    LET vprovint       = 0.00;
    LET vdesprov       = 0.00;              
    LET vpagoint       = 0.00;
    LET vcap_ant       = 0.00; 
    LET vsdo_dia_ant   = 0.00;  
    LET vimp_chq_sbg   = 0.00;
    LET vint_acum      = 0.00;   
    LET vacum_sdo_int  = 0.00;
    LET vsdo_actual    = 0.00;
    LET vfecha_hoy     = '';                  
    LET vfecha_ant     = '';                
    LET vfecha_con     = '';                  
    LET vpri_hab_mes   = '';   
    LET vfecha_alta    = '';  
    LET vfecha_proceso = '';           
    LET vfec_ult_mov   = '';   
    LET vexistecobsbg  = 0;
    LET vmonto_sbg     = 0.00;    
    LET vtranprovint   = '';
    LET vtrandesprovint = '';
    LET vtranpagoint   = '';
    LET vult_hab_mes_ant = '';
                  
    BEGIN

    ON EXCEPTION SET vsqlerr, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/gen_archsdos_des_comp3.err";
        TRACE ON;
        IF vsqlerr <> 0 THEN
            LET vcodret1 = vsqlerr;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'C'||''','||
                       'codret        = '''||vcodret1||''','||
                       'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||vempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horassdosdia3.sql';
            SYSTEM vsql;
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horassdosdia3.sql';
            SYSTEM vstmt;
            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/gen_archsdos_des_comp3.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE FECHAS DEL SISTEMA
    SELECT fecha_hoy, fecha_ant, fecha_ant - 1 UNITS DAY, pri_hab_mes, pri_hab_mes - 1 UNITS DAY
      INTO vfecha_hoy, vfecha_ant, vfecha_con, vpri_hab_mes, vult_hab_mes_ant
      FROM sc_fechas
     WHERE empresa = vempresa;
    
    /* ######################################################
    -- // VERIFICA PASO DE MOVS A HISTORICO DE CHEQUES
    SELECT proceso
      INTO vexisteproc
      FROM sc_contproc
     WHERE empresa = vempresa
       AND proceso = 'movdia_concil'
       AND fecha = vfecha_ant;
       
    IF vexisteproc is null OR vexisteproc = '' THEN 
        LET vcodret1 = '953';
        LET vcodret2 = '953';
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE sistema = vsistema
           AND codigo_retorno = vcodret1;
        
        RETURN vcodret1, vcodret2, vcodret3, vcontador1;
    END IF;
    ###################################################### */
    
    -- // VERIFICA FINALIZACION DE ACTUALIZACION DE LA TABLA DE SALDOS (PRIMERA PARTE)
    SELECT proceso
      INTO vexisteproc2
      FROM bdinteg:sx_contproc
     WHERE sistema = vsistema
       AND proceso = 'sdoschqant'
       AND fecha = vfecha_hoy
       AND status_proc = 'F';
       
    IF vexisteproc2 is null OR vexisteproc2 = '' THEN 
        LET vcodret1 = '952';
        LET vcodret2 = '952';
        
        SELECT descripcion
          INTO vcodret3
          FROM bdinteg:si_codret
         WHERE sistema = vsistema
           AND codigo_retorno = vcodret1;
        
        RETURN vcodret1, vcodret2, vcodret3, vcontador1;
    END IF;
    
    CALL sp_valfechabil(vfecha_con, '-')
    RETURNING vcodret1, vfecha_con;
    
    -- // Guarda proceso en tabla de control de proceso de integral
    SELECT count(*)
      INTO vexiste
      FROM bdinteg:sx_contproc
     WHERE empresa = vempresa
       AND proceso = vproceso
       AND fecha   = vfecha_hoy
       AND sistema = vsistema;

    IF vexiste = 0 THEN
        LET vsql = 'echo "INSERT INTO bdinteg:sx_contproc VALUES '||
                   '('''||vempresa||''', '''||vproceso||''', '''||vfecha_hoy||''', '''||vsistema||''', '''||'I'||''', '''||vusuario||''', '||
                   '(SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas), NULL, NULL);" > /tmp/horassdosdia3.sql';
        SYSTEM vsql;
        
        LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horassdosdia3.sql';
        SYSTEM vstmt;
    ELSE
        SELECT count(*)
          INTO vexistefin
          FROM bdinteg:sx_contproc
         WHERE empresa     = vempresa
           AND proceso     = vproceso
           AND fecha       = vfecha_hoy
           AND sistema     = vsistema
           AND status_proc = "F";

        IF vexistefin = 0 THEN
            LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
                       'SET ejecutivo = '''||vusuario||''','||
                       'status_proc   = '''||'I'||''','||
                       'codret        = '''||' '||''','||
                       'hora_fin      = '''||' '||''','||
                       'hora_ini      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
                       'WHERE empresa = '''||vempresa||''' '||
                       'AND proceso   = '''||vproceso||''' '||
                       'AND fecha     = '''||vfecha_hoy||''' '||
                       'AND sistema   = '''||vsistema||''';" > /tmp/horassdosdia3.sql';
            SYSTEM vsql;
            
            LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horassdosdia3.sql';
            SYSTEM vstmt;
        ELSE
            LET vcodret1 = "958";
            LET vcodret2 = "958";
            
            SELECT descripcion
              INTO vcodret3
              FROM bdinteg:si_codret
             WHERE sistema = vsistema
               AND codigo_retorno = vcodret1;

            RETURN vcodret1, vcodret2, vcodret3, vcontador1;
        END IF;
    END IF;
    
    SELECT valor
      INTO vprodcrec
      FROM sc_param
     WHERE empresa = vempresa
       AND codparam = 'PRODCREC';
       
    SELECT valor
      INTO vtrancobsbg
      FROM sc_param
     WHERE empresa = vempresa
       AND codparam = 'tranpagosbg';
       
    SELECT valor
      INTO vtranprovint
      FROM sc_param
     WHERE empresa = vempresa
       AND codparam = 'tranprov';
       
    SELECT valor
      INTO vtrandesprovint
      FROM sc_param
     WHERE empresa = vempresa
       AND codparam = 'tranrevprov';
       
    SELECT valor
      INTO vtranpagoint
      FROM sc_param
     WHERE empresa = vempresa
       AND codparam = 'tranpagint';
    
    LET vmes_actual    = LPAD(MONTH(vfecha_ant), 2, '0');
    LET vmes_siguiente = LPAD(MONTH(vfecha_hoy), 2, '0');
    LET vaniomes       = YEAR(vfecha_ant)||LPAD(MONTH(vfecha_ant), 2, '0');
    LET vdia           = DAY(vfecha_ant);
    LET vmes           = LPAD(MONTH(vfecha_ant), 2, '0');
    LET vanio          = YEAR(vfecha_ant);
    
    FOREACH WITH HOLD
        SELECT UNIQUE chq.cuenta, chq.sucursal, chq.sdo_dia_ant, chq.imp_chq_sbg, noc.int_acum, noc.acum_sdo_int, noc.fecha_alta,
               chq.producto, chq.status_cta, chq.fecha_proceso, chq.fec_ult_mov, chq.sdo_actual
          INTO vcuenta, vsucursal, vsdo_dia_ant, vimp_chq_sbg, vint_acum, vacum_sdo_int, vfecha_alta,
               vproducto, vstatus_cta, vfecha_proceso, vfec_ult_mov, vsdo_actual
          FROM sc_maechq chq, 
               sc_maenoc noc,
               sc_movdia_concil mov
         WHERE chq.empresa = vempresa
           AND chq.cuenta = noc.cuenta
           AND ( ( chq.producto = vprodcrec AND chq.status_cta != '2' AND chq.fecultdep < vfecha_hoy ) OR
                 ( chq.producto = vprodcrec AND chq.status_cta  = '2' AND chq.fecha_proceso >= vfecha_ant AND chq.fecultdep < vfecha_hoy ) OR
                 ( chq.producto = vprodcrec AND chq.status_cta  = '2' AND chq.fecha_proceso is null AND chq.fec_ult_mov >= vfecha_ant AND chq.fecultdep < vfecha_hoy ) )
           AND noc.empresa = chq.empresa
           AND noc.cuenta = chq.cuenta
           AND mov.empresa = chq.empresa
           AND mov.cuenta = chq.cuenta
           AND mov.fech_alt = vfecha_ant
           AND mov.cancelad <> 'S'
           AND mov.transacc IN(vtranprovint,vtrandesprovint,vtranpagoint) 
           
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        SELECT COUNT(*)
          INTO vexistecobsbg
          FROM sc_movdia
         WHERE empresa = vempresa
           AND cuenta = vcuenta
           AND cancelad <> 'S'
           AND transacc = vtrancobsbg
           AND fech_alt = vfecha_hoy;
           
        IF vexistecobsbg > 0 THEN
            SELECT SUM(monto_tot)
              INTO vmonto_sbg
              FROM sc_movdia
             WHERE empresa = vempresa
               AND cuenta = vcuenta
               AND cancelad <> 'S'
               AND transacc = vtrancobsbg
               AND fech_alt = vfecha_hoy;
               
            LET vimp_chq_sbg = vimp_chq_sbg + vmonto_sbg;
        END IF;

        IF vimp_chq_sbg < 0 THEN
            LET vimp_chq_sbg = vimp_chq_sbg * -1;
        END IF

        LET vsdo_dia_ant = vsdo_dia_ant - vimp_chq_sbg;
        
        IF ( vproducto = vprodcrec AND vstatus_cta = '2' AND vfecha_proceso = vfecha_ant ) OR
           ( vproducto = vprodcrec AND vstatus_cta = '2' AND vfecha_proceso is null AND vfec_ult_mov = vfecha_ant ) THEN
            LET vsdo_dia_ant = vsdo_actual;
        END IF;
        
        -- // PROVISIONES
        SELECT NVL(SUM(monto_tot), 0.00)
          INTO vprovint 
          FROM sc_movdia_concil
         WHERE empresa = vempresa
           AND cuenta = vcuenta
           AND fech_alt = vfecha_ant
           AND cancelad <> 'S'
           AND transacc = vtranprovint;
         
        -- // DESPROVISIONES
        SELECT NVL(SUM(monto_tot), 0.00)
          INTO vdesprov
          FROM sc_movdia_concil
         WHERE empresa = vempresa
           AND cuenta = vcuenta
           AND fech_alt = vfecha_ant
           AND cancelad <> 'S'
           AND transacc = vtrandesprovint;
         
        -- // PAGO DE INTERESES
        SELECT NVL(SUM(monto_tot), 0.00)
          INTO vpagoint
          FROM sc_movdia_concil
         WHERE empresa = vempresa
           AND cuenta = vcuenta
           AND fech_alt = vfecha_ant
           AND cancelad <> 'S'
           AND transacc = vtranpagoint;
        
        IF DAY(vfecha_alta) = DAY(vfecha_hoy) THEN
            CALL sp_capintafecha(vcuenta, vfecha_con)
            RETURNING vcodret1, vcap_ant, vint_acum;
        END IF;
        
        IF vfecha_hoy = vpri_hab_mes THEN 
            IF DAY(vfecha_alta) <> DAY(vfecha_hoy) THEN 
                LET vint_acum = vprovint;
            END IF; 
            
            IF DAY(vfecha_alta) > DAY(vult_hab_mes_ant) THEN
                LET vint_acum = 0.00;
            END IF;
        ELSE 
            LET vprovint = vprovint - vdesprov;
            LET vint_acum = ((vint_acum + vprovint) - vpagoint);
        END IF; 
        
        -- // Actualiza tabla de saldos diarios y provisiones no capitalizadas..        
        SELECT cuenta
          INTO vexiste_cta
          FROM sc_sdodiarioc
         WHERE cuenta = vcuenta
           AND aniomes = vaniomes;
           
        IF vexiste_cta is not null OR vexiste_cta <> '' THEN
            UPDATE sc_sdodiarioc 
               SET intprovnp1  =  DECODE(vdia,1,vint_acum,intprovnp1),
                   intprovnp2  =  DECODE(vdia,2,vint_acum,intprovnp2),
                   intprovnp3  =  DECODE(vdia,3,vint_acum,intprovnp3),
                   intprovnp4  =  DECODE(vdia,4,vint_acum,intprovnp4),
                   intprovnp5  =  DECODE(vdia,5,vint_acum,intprovnp5),
                   intprovnp6  =  DECODE(vdia,6,vint_acum,intprovnp6),
                   intprovnp7  =  DECODE(vdia,7,vint_acum,intprovnp7),
                   intprovnp8  =  DECODE(vdia,8,vint_acum,intprovnp8),
                   intprovnp9  =  DECODE(vdia,9,vint_acum,intprovnp9),
                   intprovnp10 =  DECODE(vdia,10,vint_acum,intprovnp10),
                   intprovnp11 =  DECODE(vdia,11,vint_acum,intprovnp11),
                   intprovnp12 =  DECODE(vdia,12,vint_acum,intprovnp12),
                   intprovnp13 =  DECODE(vdia,13,vint_acum,intprovnp13),
                   intprovnp14 =  DECODE(vdia,14,vint_acum,intprovnp14),
                   intprovnp15 =  DECODE(vdia,15,vint_acum,intprovnp15),
                   intprovnp16 =  DECODE(vdia,16,vint_acum,intprovnp16),
                   intprovnp17 =  DECODE(vdia,17,vint_acum,intprovnp17),
                   intprovnp18 =  DECODE(vdia,18,vint_acum,intprovnp18),
                   intprovnp19 =  DECODE(vdia,19,vint_acum,intprovnp19),
                   intprovnp20 =  DECODE(vdia,20,vint_acum,intprovnp20),
                   intprovnp21 =  DECODE(vdia,21,vint_acum,intprovnp21),
                   intprovnp22 =  DECODE(vdia,22,vint_acum,intprovnp22),
                   intprovnp23 =  DECODE(vdia,23,vint_acum,intprovnp23),
                   intprovnp24 =  DECODE(vdia,24,vint_acum,intprovnp24),
                   intprovnp25 =  DECODE(vdia,25,vint_acum,intprovnp25),
                   intprovnp26 =  DECODE(vdia,26,vint_acum,intprovnp26),
                   intprovnp27 =  DECODE(vdia,27,vint_acum,intprovnp27),
                   intprovnp28 =  DECODE(vdia,28,vint_acum,intprovnp28),
                   intprovnp29 =  DECODE(vdia,29,vint_acum,intprovnp29),
                   intprovnp30 =  DECODE(vdia,30,vint_acum,intprovnp30),
                   intprovnp31 =  DECODE(vdia,31,vint_acum,intprovnp31)
             WHERE cuenta = vcuenta
               AND aniomes = vaniomes;
        ELSE
            INSERT INTO sc_sdodiarioc 
            VALUES (vcuenta, vaniomes, vsucursal,
                    DECODE(vdia,1,vsdo_dia_ant,0),
                    DECODE(vdia,1,vint_acum,0),
                    DECODE(vdia,2,vsdo_dia_ant,0),
                    DECODE(vdia,2,vint_acum,0),
                    DECODE(vdia,3,vsdo_dia_ant,0),
                    DECODE(vdia,3,vint_acum,0),
                    DECODE(vdia,4,vsdo_dia_ant,0),
                    DECODE(vdia,4,vint_acum,0),
                    DECODE(vdia,5,vsdo_dia_ant,0),
                    DECODE(vdia,5,vint_acum,0),
                    DECODE(vdia,6,vsdo_dia_ant,0),
                    DECODE(vdia,6,vint_acum,0),
                    DECODE(vdia,7,vsdo_dia_ant,0),
                    DECODE(vdia,7,vint_acum,0),
                    DECODE(vdia,8,vsdo_dia_ant,0),
                    DECODE(vdia,8,vint_acum,0),
                    DECODE(vdia,9,vsdo_dia_ant,0),
                    DECODE(vdia,9,vint_acum,0),
                    DECODE(vdia,10,vsdo_dia_ant,0),
                    DECODE(vdia,10,vint_acum,0),
                    DECODE(vdia,11,vsdo_dia_ant,0),
                    DECODE(vdia,11,vint_acum,0),
                    DECODE(vdia,12,vsdo_dia_ant,0),
                    DECODE(vdia,12,vint_acum,0),
                    DECODE(vdia,13,vsdo_dia_ant,0),
                    DECODE(vdia,13,vint_acum,0),
                    DECODE(vdia,14,vsdo_dia_ant,0),
                    DECODE(vdia,14,vint_acum,0),
                    DECODE(vdia,15,vsdo_dia_ant,0),
                    DECODE(vdia,15,vint_acum,0),
                    DECODE(vdia,16,vsdo_dia_ant,0),
                    DECODE(vdia,16,vint_acum,0),
                    DECODE(vdia,17,vsdo_dia_ant,0),
                    DECODE(vdia,17,vint_acum,0),
                    DECODE(vdia,18,vsdo_dia_ant,0),
                    DECODE(vdia,18,vint_acum,0),
                    DECODE(vdia,19,vsdo_dia_ant,0),
                    DECODE(vdia,19,vint_acum,0),
                    DECODE(vdia,20,vsdo_dia_ant,0),
                    DECODE(vdia,20,vint_acum,0),
                    DECODE(vdia,21,vsdo_dia_ant,0),
                    DECODE(vdia,21,vint_acum,0),
                    DECODE(vdia,22,vsdo_dia_ant,0),
                    DECODE(vdia,22,vint_acum,0),
                    DECODE(vdia,23,vsdo_dia_ant,0),
                    DECODE(vdia,23,vint_acum,0),
                    DECODE(vdia,24,vsdo_dia_ant,0),
                    DECODE(vdia,24,vint_acum,0),
                    DECODE(vdia,25,vsdo_dia_ant,0),
                    DECODE(vdia,25,vint_acum,0),
                    DECODE(vdia,26,vsdo_dia_ant,0),
                    DECODE(vdia,26,vint_acum,0),
                    DECODE(vdia,27,vsdo_dia_ant,0),
                    DECODE(vdia,27,vint_acum,0),
                    DECODE(vdia,28,vsdo_dia_ant,0),
                    DECODE(vdia,28,vint_acum,0),
                    DECODE(vdia,29,vsdo_dia_ant,0),
                    DECODE(vdia,29,vint_acum,0),
                    DECODE(vdia,30,vsdo_dia_ant,0),
                    DECODE(vdia,30,vint_acum,0),
                    DECODE(vdia,31,vsdo_dia_ant,0),
                    DECODE(vdia,31,vint_acum,0),
                    vsdo_dia_ant, 1, 'F');
        END IF;
        
        -- // Actualiza tabla de saldos mensuales y provisiones no capitalizadas..
        IF vmes_actual <> vmes_siguiente THEN
            CALL sp_actsdomensualc(vcuenta, vsucursal, vsdo_dia_ant, vacum_sdo_int, vanio, vmes) 
            RETURNING vcodret1;
        END IF
        
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;

        IF (vcontador2 >= 7500) THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET vcuenta        = '';
        LET vsucursal      = '';
        LET vsdo_dia_ant   = 0.00;
        LET vimp_chq_sbg   = 0.00;
        LET vint_acum      = 0.00;
        LET vacum_sdo_int  = 0.00;
        LET vfecha_alta    = '';
        LET vprovint       = 0.00;
        LET vdesprov       = 0.00;
        LET vpagoint       = 0.00;
        LET vcap_ant       = 0.00;
        LET vproducto      = '';
        LET vstatus_cta    = '';                
        LET vfecha_proceso = '';
        LET vsdo_actual    = 0.00;
        LET vfec_ult_mov   = '';
        LET vexistecobsbg  = 0;
        LET vmonto_sbg     = 0.00;
    END FOREACH;
    
    IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
    END IF;
    
    LET vsql = 'echo "UPDATE bdinteg:sx_contproc '||
               'SET ejecutivo = '''||vusuario||''','||
               'status_proc   = '''||'F'||''','||
               'codret        = '''||vcodret1||''','||
               'hora_fin      = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdicheq:sc_fechas) '||
               'WHERE empresa = '''||vempresa||''' '||
               'AND proceso   = '''||vproceso||''' '||
               'AND fecha     = '''||vfecha_hoy||''' '||
               'AND sistema   = '''||vsistema||''';" > /tmp/horassdosdia3.sql';
    SYSTEM vsql;
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdicheq /tmp/horassdosdia3.sql';
    SYSTEM vstmt;
    
    END;

    RETURN vcodret1, vcodret2, vcodret3, vcontador1;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_primdiames_indicadores_pba()
RETURNING
	CHAR(6),
	CHAR(80)

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);
	
	DEFINE dCapvig1			DECIMAL(14,2);
	DEFINE dCapvig2			DECIMAL(14,2);
	DEFINE dCapvig3			DECIMAL(14,2);
	DEFINE dCapvig4			DECIMAL(14,2);
	DEFINE dCapvig5			DECIMAL(14,2);
	DEFINE dCapvig6			DECIMAL(14,2);
	DEFINE dCapvig7			DECIMAL(14,2);
	DEFINE dCapvig8			DECIMAL(14,2);
	DEFINE dCapvig9			DECIMAL(14,2);
	DEFINE dCapvig10		DECIMAL(14,2);
	DEFINE dCapvig11		DECIMAL(14,2);
	DEFINE dCapvig12		DECIMAL(14,2);
	DEFINE dCapvig13		DECIMAL(14,2);
	DEFINE dCapvig14		DECIMAL(14,2);
	DEFINE dCapvig15		DECIMAL(14,2);
	DEFINE dCapvig16		DECIMAL(14,2);
	DEFINE dCapvig17		DECIMAL(14,2);
	DEFINE dCapvig18		DECIMAL(14,2);
	DEFINE dCapvig19		DECIMAL(14,2);
	DEFINE dCapvig20		DECIMAL(14,2);
	DEFINE dCapvig21		DECIMAL(14,2);
	DEFINE dCapvig22		DECIMAL(14,2);
	DEFINE dCapvig23		DECIMAL(14,2);
	DEFINE dCapvig24		DECIMAL(14,2);
	DEFINE dCapvig25		DECIMAL(14,2);
	DEFINE dCapvig26		DECIMAL(14,2);
	DEFINE dCapvig27		DECIMAL(14,2);
	DEFINE dCapvig28		DECIMAL(14,2);
	DEFINE dCapvig29		DECIMAL(14,2);
	DEFINE dCapvig30		DECIMAL(14,2);
	DEFINE dCapvig31		DECIMAL(14,2);

	DEFINE cFecha_Hoy		DATE;
	DEFINE cPrimDiaHabil	DATE;
	DEFINE cAnioMes			CHAR(6);
	DEFINE cAnioMesAnte		CHAR(6);
	DEFINE cCuenta			CHAR(20);
	DEFINE dSdoMaximoMes	DECIMAL(14,2);
	DEFINE dSdoMaximoAnt	DECIMAL(14,2);
	DEFINE sDia				SMALLINT;
	DEFINE dMontoCapvig		DECIMAL(14,2);
	DEFINE iDiaHabilAnt		SMALLINT;
	DEFINE dSaldoPromedio	DECIMAL(14,2);
	DEFINE iUltCheque		INTEGER;
	DEFINE dtFecUltPagoInt	DATE;
	DEFINE dAcumSBC			DECIMAL(14,2);
	DEFINE dAcumRemesa		DECIMAL(14,2);
	DEFINE dIntAcum			DECIMAL(14,2);
	DEFINE dISRAcum			DECIMAL(14,2);
	


	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
	LET cDescRet			= "PROCESO EXITOSO";
	
	LET dCapvig1			= 0.0;
	LET dCapvig2			= 0.0;
	LET dCapvig3			= 0.0;
	LET dCapvig4			= 0.0;
	LET dCapvig5			= 0.0;
	LET dCapvig6			= 0.0;
	LET dCapvig7			= 0.0;
	LET dCapvig8			= 0.0;
	LET dCapvig9			= 0.0;
	LET dCapvig10			= 0.0;
	LET dCapvig11			= 0.0;
	LET dCapvig12			= 0.0;
	LET dCapvig13			= 0.0;
	LET dCapvig14			= 0.0;
	LET dCapvig15			= 0.0;
	LET dCapvig16			= 0.0;
	LET dCapvig17			= 0.0;
	LET dCapvig18			= 0.0;
	LET dCapvig19			= 0.0;
	LET dCapvig20			= 0.0;
	LET dCapvig21			= 0.0;
	LET dCapvig22			= 0.0;
	LET dCapvig23			= 0.0;
	LET dCapvig24			= 0.0;
	LET dCapvig25			= 0.0;
	LET dCapvig26			= 0.0;
	LET dCapvig27			= 0.0;
	LET dCapvig28			= 0.0;
	LET dCapvig29			= 0.0;
	LET dCapvig30			= 0.0;
	LET dCapvig31			= 0.0;

	LET cFecha_Hoy			= DATE(1);
	LET cPrimDiaHabil		= DATE(1);
	LET cAnioMes			= "";
	LET cAnioMesAnte		= "";
	LET cCuenta				= "";
	LET dSdoMaximoMes		= 0.0;
	LET dSdoMaximoAnt		= 0.0;
	LET sDia				= 0;
	LET dMontoCapvig		= 0;
	LET iDiaHabilAnt		= 0;
	LET dSaldoPromedio		= 0.0;
	LET iUltCheque			= 0;
	LET dtFecUltPagoInt		= DATE(1);
	LET dAcumSBC			= 0.0;
	LET dAcumRemesa			= 0.0;
	LET dIntAcum			= 0.0;
	LET dISRAcum			= 0.0;



BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_primdiames_indicadores.out';
	--TRACE ON;
		
	-- OBTIENE EL AÑO Y EL MES ACTUAL
	SELECT fecha_hoy, pri_hab_mes, YEAR(fecha_hoy) || LPAD(MONTH(fecha_hoy),2,"0"), YEAR(fecha_hoy - 1 units MONTH) || LPAD(MONTH(fecha_hoy - 1 units MONTH),2,"0")
	,DAY(fecha_ant)
	INTO cFecha_Hoy, cPrimDiaHabil, cAnioMes, cAnioMesAnte, iDiaHabilAnt
	FROM "informix".sc_fechas
	WHERE empresa = "001";

	LET sDia = DAY(cFecha_Hoy);
	
	FOREACH {+INDEX(sc_sdodiarioc isdodiario)}
		SELECT i.cuenta, i.saldo_maximo_mes, DECODE(sd.diacum,0,0,(sd.capvigacum / sd.diacum))::DECIMAL(14,2) AS sdo_prom,
		capvig1,capvig2,capvig3,capvig4,capvig5,capvig6,capvig7,capvig8,capvig9,capvig10,capvig11,capvig12,
		capvig13,capvig14,capvig15,capvig16,capvig17,capvig18,capvig19,capvig20,capvig21,capvig22,capvig23,
		capvig24,capvig25,capvig26,capvig27,capvig28,capvig29,capvig30,capvig31
		INTO cCuenta, dSdoMaximoAnt, dSaldoPromedio,
		dCapvig1,dCapvig2,dCapvig3,dCapvig4,dCapvig5,dCapvig6,dCapvig7,dCapvig8,dCapvig9,dCapvig10,dCapvig11,dCapvig12,
		dCapvig13,dCapvig14,dCapvig15,dCapvig16,dCapvig17,dCapvig18,dCapvig19,dCapvig20,dCapvig21,dCapvig22,dCapvig23,
		dCapvig24,dCapvig25,dCapvig26,dCapvig27,dCapvig28,dCapvig29,dCapvig30,dCapvig31
		FROM "informix".sc_indicadores i, "informix".sc_sdodiarioc sd
		WHERE sd.aniomes = cAnioMesAnte
		AND i.anio_mes = sd.aniomes
		AND i.cuenta = sd.cuenta
				
		-- OBTIENE EL MONTO DE SALDO DEL DIA QUE VA CORRIENDO
		LET dMontoCapvig = DECODE(iDiaHabilAnt,1,dCapvig1,2,dCapvig2,3,dCapvig3,4,dCapvig4,5,dCapvig5,6,dCapvig6,7,dCapvig7,8,dCapvig8,9,dCapvig9,10,dCapvig10,11,dCapvig11,12,dCapvig12,13,dCapvig13,14,dCapvig14,15,dCapvig15,16,dCapvig16,17,dCapvig17,18,dCapvig18,19,dCapvig19,20,dCapvig20,21,dCapvig21,22,dCapvig22,23,dCapvig23,24,dCapvig24,25,dCapvig25,26,dCapvig26,27,dCapvig27,28 ,dCapvig28,29,dCapvig29,30,dCapvig30,31,dCapvig31);
		
		-- VALIDA QUE SI EL SALDO DEL DIA ES MAYOR AL SALDO MAXIMO QUE SE VA ARRASTRANDO EN EL MES PARA ACTUALIZARLO
		IF dMontoCapvig > dSdoMaximoAnt THEN
			UPDATE  "informix".sc_indicadores SET saldo_maximo_mes = dMontoCapvig 
			WHERE anio_mes = cAnioMesAnte AND cuenta = cCuenta;
			
			UPDATE  "informix".sc_indicadores SET saldo_maximo_ant = dMontoCapvig 
			WHERE anio_mes = cAnioMes AND cuenta = cCuenta;
			
		ELSE
			UPDATE  "informix".sc_indicadores SET saldo_maximo_ant = dSdoMaximoAnt 
			WHERE anio_mes = cAnioMes AND cuenta = cCuenta;			
		END IF
	
		SELECT ult_chq, ultpagoint
		INTO iUltCheque, dtFecUltPagoInt
		FROM "informix".sc_maechq
		WHERE empresa = "001"
		AND cuenta = cCuenta;
		
		-- CONSULTA LOS INDICADORES YA EXISTENTES DE LA TABLA MAESTRA COMPLEMENTARIA DE CHEQUES
		SELECT acum_sbc, acum_rem, int_acum, isr_acum
		INTO dAcumSBC, dAcumRemesa, dIntAcum, dISRAcum
		FROM "informix".sc_maenoc
		WHERE empresa = "001"
		AND cuenta = cCuenta;
		
		UPDATE "informix".sc_indicadores 
		SET saldo_promedio = dSaldoPromedio,
		ultimo_cheque = iUltCheque,
		acum_sbc = dAcumSBC, 
		acum_remesas = dAcumRemesa, 
		interes_acum = dIntAcum, 
		isr_acum = dISRAcum, 
		fec_ult_pago_int = dtFecUltPagoInt
		WHERE anio_mes = cAnioMesAnte AND cuenta = cCuenta;

	END FOREACH

	RETURN cCodRet, cDescRet;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso que corre el primer dia del mes que actualiza los saldos promedios en el mes anterior',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Junio 2014';

CREATE PROCEDURE "informix".sp_obt_comprobantes_spei (pCuenta CHAR (20), pdFechaDesde DATE, pdFechaHasta DATE,pSalto INT)
RETURNING	CHAR (5) as codret, 
			CHAR (4) as tipotransacc, 
			DATE as fechaApl, 
			CHAR (20) as cuenta, 
			CHAR(100) as conceptoPago, 
			CHAR(20) AS ImporteAbono, 
			CHAR(20) AS ImporteCargo, 
			CHAR(1) AS banderaInhabil,
			CHAR (40) AS RefCveRastreo,
			CHAR(18) AS CLABE,
			INT AS TotalRenglones;

	--// ***************************************************************************
	--//sp_obt_comprobantes_spei
	--//Version:			 	1.0
	--//Objetivo:			Obtener los comprobantes SPEI.
	--//Autor:	Moises Eduardo Soriano Guerrero
	--//Fecha: 20 Agosto 2015
	--// ***************************************************************************

DEFINE v_sCodRet CHAR(5);
DEFINE intcodret        INTEGER;
DEFINE vcTipoTransacc CHAR(4);
DEFINE vdFechaAplicacion DATE;
DEFINE vcCuenta CHAR(20);
DEFINE vcReferencia CHAR(40);
DEFINE vcConceptoPago CHAR (100);
DEFINE vdImporteAux DECIMAL (14,2);
DEFINE vdImporteAbono CHAR(20);
DEFINE vdImporteCargo CHAR(20);
DEFINE vcNumCte CHAR (20);
DEFINE vcHora DATETIME HOUR TO SECOND;
DEFINE vcCtaClabe CHAR(18);
DEFINE vTotalRegistros  INT;
DEFINE vTotalRegistrosHis INT;
DEFINE v_FechaHoraInsert	DATETIME YEAR TO FRACTION;	
DEFINE vcBanderaInhabil CHAR(1);


LET vcTipoTransacc = "";
LET vdFechaAplicacion = "";
LET vcCuenta = "";
LET vcReferencia = "";
LET vcConceptoPago ="";
LET vdImporteAux = 0;
LET vdImporteAbono = "";
LET vdImporteCargo = "";
LET vcNumCte = "";
LET v_sCodRet = '00000';
LET vcHora = "";
LET vcCtaClabe = "";
LET vTotalRegistros = 0;
LET vTotalRegistrosHis = 0;
LET vcBanderaInhabil = "0";

BEGIN
	ON EXCEPTION SET intcodret
		IF intcodret <> 0 THEN
			LET v_sCodRet  = intcodret;
			RETURN v_sCodRet, vcTipoTransacc, vdFechaAplicacion, vcCuenta, vcConceptoPago, vdImporteAbono, vdImporteCargo,vcBanderaInhabil,vcReferencia,vcCtaClabe,vTotalRegistros;
		END IF;
	END EXCEPTION;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	--SET DEBUG FILE TO "/home/sysifx/moises/bdicheq/sp_obt_comprobantes_spei.out"; 
	--TRACE ON;

	SELECT num_cte INTO vcNumCte FROM bdicheq:"informix".sc_maechq WHERE cuenta = pCuenta;
	IF NVL(vcNumCte,"") = "" THEN
		LET v_sCodRet= "00001";
		RETURN v_sCodRet, vcTipoTransacc, vdFechaAplicacion, vcCuenta, vcConceptoPago, vdImporteAbono, vdImporteCargo,vcBanderaInhabil,vcReferencia,vcCtaClabe,vTotalRegistros;
	END IF;
	
	SELECT  NVL(COUNT(num_serial),0)
			INTO vTotalRegistros
			FROM bdicheq:"informix".sc_movdia 
			WHERE cuenta = pCuenta 
			AND fech_alt BETWEEN pdFechaDesde AND pdFechaHasta 
			AND transacc IN ('0273','0274');

	SELECT  NVL(COUNT(num_serial),0)
			INTO vTotalRegistrosHis
			FROM bdicheq:"informix".sc_movhis
			WHERE cuenta = pCuenta 
			AND fech_alt BETWEEN pdFechaDesde AND pdFechaHasta 
			AND transacc IN ('0273','0274');
	
	LET vTotalRegistros = vTotalRegistros + vTotalRegistrosHis;
	
	FOREACH
		
		SELECT SKIP pSalto FIRST 10 transacc,fech_alt,cuenta,referencia,monto_tot,fech_hor  
			INTO vcTipoTransacc,vdFechaAplicacion,vcCuenta,vcReferencia,vdImporteAux,vcHora 
		FROM bdicheq:"informix".sc_movdia 
		WHERE cuenta = pCuenta 
		AND fech_alt BETWEEN pdFechaDesde AND pdFechaHasta 
		AND transacc IN ('0273','0274')
			UNION ALL
		SELECT transacc,fech_alt,cuenta,referencia,monto_tot,fech_hor
		FROM bdicheq:"informix".sc_movhis
		WHERE cuenta = pCuenta 
		AND fech_alt BETWEEN pdFechaDesde AND pdFechaHasta 
		AND transacc IN ('0273','0274')
		ORDER BY fech_alt
		
		LET v_FechaHoraInsert = ( YEAR(vdFechaAplicacion) || '-' || MONTH(vdFechaAplicacion) || '-' || DAY(vdFechaAplicacion) || ' ' || vcHora)::DATETIME YEAR TO FRACTION;
		IF (current - v_FechaHoraInsert) < '0 00:30:00' THEN	
			LET vcBanderaInhabil = "1";
		END IF;
		
		SELECT cuenta_clabe 
		INTO vcCtaClabe 
		FROM bdicheq:"informix".sc_maechq 
		WHERE cuenta = vcCuenta;
		
		IF (vcTipoTransacc IS NOT NULL AND vcTipoTransacc = '0273') THEN
			LET vcConceptoPago = TRIM(vcReferencia) || ", Abono SPEI" ;
			LET vdImporteAbono = vdImporteAux;
			LET vdImporteCargo = "";
		ELSE 
			IF(vcTipoTransacc IS NOT NULL AND vcTipoTransacc = '0274') THEN
				LET vcConceptoPago = TRIM(vcReferencia) || ", Cargo SPEI" ;
				LET vdImporteCargo = vdImporteAux;
				LET vdImporteAbono = "";
			END IF;
		END IF;
		
		RETURN v_sCodRet, vcTipoTransacc, vdFechaAplicacion, vcCuenta, vcConceptoPago, vdImporteAbono, vdImporteCargo,vcBanderaInhabil,vcReferencia,vcCtaClabe,vTotalRegistros
		WITH RESUME;
	
	END FOREACH;
	
END;
END PROCEDURE;

CREATE PROCEDURE "informix".consbeneficiario(pEmpresa CHAR(3), pNumeroCuenta CHAR(20))

	--DATOS A REGRESAR---
	RETURNING
	CHAR(5),  -- Codigo de Retorno
	CHAR(20), -- Numero de Cuenta
	CHAR(20), -- Numero de Cliente
	CHAR(9),  -- Porcentaje
	CHAR(26), -- Apellido Paterno
	CHAR(26), -- Apellido Materno
	CHAR(26), -- Nombre1
	CHAR(26), -- Nombre2
	CHAR(13), -- RFC
	CHAR(10), -- Fecha Nacimiento
	CHAR(20); -- Parentesco

	--DEFINICION DE VARIABLES--
	DEFINE iSqlErr		INTEGER;
	DEFINE sCantReg		SMALLINT;
	DEFINE cCodRet		CHAR(5);
	DEFINE cNumCuenta	CHAR(20);
	DEFINE cNumCliente	CHAR(20);
	DEFINE cPorcentaje  CHAR(9);
	DEFINE cApePat		CHAR(26);
	DEFINE cApeMat		CHAR(26);
	DEFINE cNombre1		CHAR(26);
	DEFINE cNombre2		CHAR(26);
	DEFINE cRFC			CHAR(13);
	DEFINE cFechaNac	CHAR(10);
	DEFINE cParentesco	CHAR(20);
	DEFINE cProducto	CHAR(4);
	DEFINE cProdTransfer	CHAR(4);

	--INICIALIZACION DE VARIABLES--
	LET iSqlErr		= 0;
	LET sCantReg 	= 0;
	LET cCodRet 	= '000';
	LET cNumCuenta 	= '';
	LET cNumCliente = '';
	LET cPorcentaje = '';
	LET cApePat 	= '';
	LET cApeMat 	= '';
	LET cNombre1 	= '';
	LET cNombre2 	= '';
	LET cRFC 		= '';
	LET cFechaNac 	= '';
	LET cParentesco = '';
	LET cProducto	= '';
	LET cProdTransfer= '';

BEGIN
	ON EXCEPTION SET iSqlErr
	   IF (iSqlErr != 0) THEN
		LET cCodRet = iSqlErr;
		RETURN cCodRet, cNumCuenta, cNumCliente, cPorcentaje, cApePat, cApeMat, cNombre1, cNombre2, cRFC, cFechaNac, cParentesco;		
	   END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO '/respaldosbd/claudio/consbeneficiario.out';
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	IF NVL(pEmpresa,'') <> '' AND NVL(pNumeroCuenta,'') <> '' THEN

		FOREACH
			SELECT bdi_scbene.cuenta,bdi_scbene.numcte,bdi_scbene.porcentaje,bdi_scbene.parentesco,bdi_sicte.apell_paterno,bdi_sicte.apell_materno,bdi_sicte.nombre1,bdi_sicte.nombre2,bdi_sicte.rfc,bdi_sictepf.fecha_nac
			INTO cNumCuenta, cNumCliente, cPorcentaje, cParentesco, cApePat, cApeMat, cNombre1, cNombre2, cRFC, cFechaNac
			FROM bdicheq:"informix".sc_beneficiario bdi_scbene, bdinteg:"informix".si_cliente bdi_sicte, bdinteg:"informix".si_ctepf bdi_sictepf
			WHERE bdi_scbene.empresa = pEmpresa AND bdi_scbene.cuenta = pNumeroCuenta AND bdi_scbene.numcte = bdi_sicte.numcte
			AND bdi_sicte.empresa = pEmpresa AND bdi_sicte.tpo_persona = '01' AND bdi_sicte.numcte = bdi_sictepf.numcte

			LET sCantReg = sCantReg + 1;
			RETURN cCodRet, cNumCuenta, cNumCliente, cPorcentaje, cApePat, cApeMat, cNombre1, cNombre2, cRFC, cFechaNac, cParentesco WITH RESUME;
		END FOREACH;

		IF sCantReg = 0 THEN
			SELECT valor INTO cProdTransfer
			FROM bditransfer:"informix".tf_param
			WHERE empresa = pEmpresa AND cod_param = '4';

			SELECT producto	INTO cProducto
			FROM bditransfer:"informix".tf_maecte
			WHERE empresa = pEmpresa AND cuenta_tf = pNumeroCuenta;

			IF NVL(cProducto,'') = '' THEN
				SELECT producto	INTO cProducto
				FROM bdicheq:"informix".sc_maechq
				WHERE empresa = pEmpresa AND cuenta = pNumeroCuenta;
			END IF
			
			IF NVL(cProdTransfer,'') = NVL(cProducto,'') THEN
				LET cCodRet	= '01221';			ELSE
				LET cCodRet	= '128';			END IF

			RETURN cCodRet, cNumCuenta, cNumCliente, cPorcentaje, cApePat, cApeMat, cNombre1, cNombre2, cRFC, cFechaNac, cParentesco;
		END IF
	ELSE
		LET cCodRet	= '128';
		RETURN cCodRet, cNumCuenta, cNumCliente, cPorcentaje, cApePat, cApeMat, cNombre1, cNombre2, cRFC, cFechaNac, cParentesco;
	END IF
END;
END PROCEDURE
DOCUMENT
'000 - exito',
'128 - sin beneficiarios bancoppel',
'01221 - sin beneficiarios tranfer',
'MODIFICO : Claudio Almodovar',
'FECHA : 16/06/2015',
'BD: bditransfer';

CREATE PROCEDURE "informix".sp_validador24d(pfechaejecuta date) 
    RETURNING VARCHAR(5),VARCHAR(255);
	
	DEFINE cVarDataErr              VARCHAR(64);
    DEFINE iSqlErr                  INTEGER;
    DEFINE iSamErr                  INTEGER;
    DEFINE vCodRet                  CHAR(5);
	DEFINE vdesc 					VARCHAR(255);
	DEFINE v_extracdia              INTEGER; 
    --VARIABLES CONTROL CICLO RECORRIDO DEL 
	--DEFINE v_tipo					CHAR(1);
	DEFINE v_porcentaje				FLOAT;
	DEFINE v_ultimodia              INTEGER;
	DEFINE v_dias_ret    			INTEGER;
	DEFINE v_rango					CHAR(5);
	
	LET vcodret = '00000';
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
BEGIN
--Manejo del error
		ON EXCEPTION SET iSqlErr, iSamErr, cVarDataErr
         SET DEBUG FILE TO "/informix/Cheques/sp_validador24d.err";
			IF iSqlErr <> 0 THEN
				LET vCodret=iSqlErr;
				RETURN vCodret, iSamErr || ' ' ||cVarDataErr;
			END IF;
		END EXCEPTION;  
		
		--SET DEBUG FILE TO "/informix/Cheques/sp_validador24d.out";
        --TRACE ON;	 
									
-- // Valida la fecha del Movimiento
    IF (pfechaejecuta is null) or (pfechaejecuta = '') then
        LET vcodret = '00001'; -- Falta parametro Fecha de Operacion
        LET cVarDataErr = 'Falta parametro Fecha de Operacion';
        RETURN vcodret, cVarDataErr;
    END IF;
	
	
	-- GENERA LA EXTRACCION DE LA INFORMACION
	    LET v_ultimodia = day(pfechaejecuta);
	WHILE v_ultimodia > 0  
		
		IF NOT EXISTS (SELECT fecha FROM sc_fechvalr24d WHERE fecha = pfechaejecuta) THEN	
			INSERT INTO sc_valr24d
			SELECT {+INDEX("informix".sc_movhis idx_movhisnew4)} 
			a.fech_alt, a.transacc, sum (a.monto_tot) as montototal, count(a.transacc) as numerotransacciones
			FROM bdicheq:sc_movhis as a, bdinteg: si_transacc as b
			WHERE a.empresa= '001'
			AND a.fech_alt = pfechaejecuta
			AND a.cancelad <> 'S'
			AND a.transacc = b.numero
			AND b.regulatorios = '1'
			GROUP BY 1,2;
			--ORDER BY 2;
			
			
			INSERT INTO sc_fechvalr24d(fecha)
			VALUES (pfechaejecuta);
		END IF
						
	   LET v_ultimodia = v_ultimodia - 1;
	   LET pfechaejecuta = pfechaejecuta - 1 UNITS DAY;
	   
	END WHILE
	
	return vcodret, 'Exitoso';
		
END;	
END PROCEDURE;

Create Procedure "informix".sp_nominatotalivacomision_bpi( cNombreArchivo           Char(17),
                                                       mValorIva                Money(14,2),
                                                       mValorComisionDispercion Money(14,2) )
Returning Char(3),
          Char(100),
          Money(14,3),
          Money(14,3),
          Money(14,3),
          Money(14,3),
          Money(14,3);

    --- Realizo   : Martín Valenzuela Ojeda
    --- Proyecto  : Dispercion Nomina BanCoppel
    --- Actividad : Calcula el Total del Iva y de la Comision de Disperción para todos los Empleados que hayan sido Aplicados (status = 1,3)
    --- Fecha     : Abril-2008

	DEFINE GLOBAL mtotalregspei         INTEGER		DEFAULT 0;
    Define mImporteTotalAplicado        Money(14,3);
    Define cCodRet                      Char(3);
    Define cMensaje                     Char(100);
    Define iNumeroRegistrosAplicados    Integer ;
    Define mTotaliva                    Money(14,3);
    Define mTotalComision               Money(14,3);
    Define mTotalPagado                 Money(14,3);
    Define mTotalCargo                  Money(14,3);
    Define mTotalNoPagado			    Money(14,3);
    DEFINE  vsqlerr                     Integer ;

    Let cCodRet = '000';
    Let cMensaje = "";
    Let mImporteTotalAplicado = 0;
    Let iNumeroRegistrosAplicados = 0;
    Let mTotaliva = 0;
    Let mTotalComision = 0;
    Let mTotalPagado = 0;
    Let mTotalCargo = 0;
    Let mTotalNoPagado = 0;

    --Set debug file to "informix/dmr2/sp_nominatotalivacomision.out";
    --Trace on;

    Begin

    ON EXCEPTION SET vsqlerr
        IF vsqlerr <> 0 THEN
            Let cCodRet = vsqlerr;
            Let cMensaje  = "Error Marcado Por Informix";
            Return cCodRet, cMensaje, null, null, null, null, null;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    If (Trim(cNombreArchivo) <> "") And (mValorIva is not Null Or mValorComisionDispercion is not Null ) Then
        Select {+INDEX(bdicheq:sc_nominamovimientos_bpi idx_nominamovimientos_bpi2)}
               NVL(Count(*),0)
          Into iNumeroRegistrosAplicados
          From bdicheq:sc_nominamovimientos_bpi
         Where nombre_archivo = cNombreArchivo
           And (status = '1' Or status = '3');  /* El valor 1 es de Aplicados y el 3 de Cuentas Bloqueadas */

        --- Let mTotaliva = iNumeroRegistrosAplicados * mValorIva;
        --- Let mTotalComision = iNumeroRegistrosAplicados * mValorComisionDispercion;
		
		IF iNumeroRegistrosAplicados > mtotalregspei THEN 
		   LET iNumeroRegistrosAplicados = iNumeroRegistrosAplicados - mtotalregspei;
		ELSE
		   LET iNumeroRegistrosAplicados = 0;
		END IF;

        Let mTotalComision = iNumeroRegistrosAplicados * mValorComisionDispercion;
        Let mTotaliva = mTotalComision * mValorIva; /* Nueva Forma de Calcular el Iva */
        Let cMensaje = "Calculos de Iva y Comision Efectuados Correctamente";

        /* Se saca el importe abonado a cuentas */
        Select {+INDEX(bdicheq:sc_nominamovimientos_bpi idx_nominamovimientos_bpi2)}
               NVL(sum(importe),0)
          Into mTotalPagado
          From bdicheq:sc_nominamovimientos_bpi
         Where nombre_archivo = cNombreArchivo
           And status = '1';

        /* Se saca el importe No abonado a cuentas */
        Select {+INDEX(bdicheq:sc_nominamovimientos_bpi idx_nominamovimientos_bpi2)}
               NVL(sum(importe),0)
          Into mTotalNoPagado
          From bdicheq:sc_nominamovimientos_bpi
         Where nombre_archivo = cNombreArchivo
           And status > '1';

        /* Se saca el cargo total, para evaluar el saldo */
        Let mTotalCargo = mTotalPagado + mTotalComision + mTotaliva;
    Else
        Let cCodRet = '170';
        Let cMensaje = "Error: Nombre de Archivo No Valido";
        Let mTotaliva = 0;
        Let mTotalComision = 0;

        Return cCodRet, cMensaje, mTotaliva, mTotalComision, mTotalPagado, mTotalNoPagado, mTotalCargo;
    End If

    Return cCodRet, cMensaje, mTotaliva, mTotalComision, mTotalPagado, mTotalNoPagado, mTotalCargo;

    End

End Procedure;

CREATE PROCEDURE "informix".sp_del_reg_edocta()
RETURNING 	CHAR(3) 	AS cod_ret,	CHAR(80)	AS desc_ret

	---DECLARACIONES
DEFINE iSqlErr			INTEGER;
DEFINE iIsamErr			INTEGER;
DEFINE cErrorInfo		CHAR(80);
DEFINE cCodRet			CHAR(6);
DEFINE cDescRet			CHAR(80);
DEFINE vabierto     	CHAR(1);
DEFINE vcontador   		INTEGER;
DEFINE vidreg			INTEGER;
	
	
---INICIALIZACIONES
LET iSqlErr             = 0;
LET iIsamErr            = 0;
LET cErrorInfo          = "";
LET cCodRet             = "000";
LET cDescRet			= "PROCESO EXITOSO";
LET vabierto   = '0';
LET vcontador = 0;
LET vidreg 	   = 0;


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/jcgk/sp_del_reg_edocta.out';
	--TRACE ON;
	
	FOREACH WITH HOLD
	
		SELECT NVL(idreg, 0)
        INTO vidreg
        FROM "informix".sc_encabezado_edocta_factelect
		WHERE	 
		idreg >= '4918141'
		
		IF vcontador = 0 THEN
			BEGIN WORK;
			LET vabierto = '1'; 
		END IF
		
		--BORRADO DE ENCABEZADOS  
		DELETE "informix".sc_encabezado_edocta_factelect WHERE idreg = vidreg;
		
		--BORRADO DE ENCABEZADOS 2
		DELETE "informix".sc_encabezado2_edocta_factelect WHERE idreg = vidreg;
		
		--BORRADO DE DETALLES
		DELETE "informix".sc_detalle_edocta_factelect WHERE idreg = vidreg;
		
		--BORRADO DE MENSAJES
		DELETE "informix".sc_mensajes_edocta_factelect WHERE idreg = vidreg;
		
		--BORRADO DE PIES DE PAGINA
		DELETE "informix".sc_piepagina_edocta_factelect WHERE idreg = vidreg;
		
		--BORRADO DE GRAFICAS
		DELETE "informix".sc_grafica_fe WHERE id_reg = vidreg;
		
		--BORRADO DE ACLARACIONES
		DELETE "informix".sc_aclaraciones_edocta_factelect WHERE idreg = vidreg;

		LET vcontador = vcontador + 1;
		
		IF vcontador = 2000 THEN
			LET vabierto = '0';
			LET vcontador = 0;
			COMMIT WORK;
		END IF
		
	END FOREACH

	IF vcontador > 0 THEN
		COMMIT WORK;
	END IF	

	RETURN cCodRet, cDescRet;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para eliminar los registros generados para los estados de cuenta con idreg duplicado',
'BD: bdicheq', 
'AUTOR: José Carlos Guerrero Karass ',
'FECHA: Octubre 2015';

create procedure "informix".digver10(pcuenta char(15))
  returning char(5), char(1);

  define cod_ret char(5);
  define p		integer;
  define n1  	integer;
  define n2  	integer;
  define n  	integer;
  define i  	integer;
  define k  	integer;
  define vaux	char(2);
  define digito10	integer;
  

-- ********************************************************************
-- Inicializa variables
-- ********************************************************************
	let cod_ret = "000";
	let p		= 0;
	let n1  	= 0;
	let n2  	= 0;
	let n  		= 0;
	let i  		= 0;
	let k  		= 0;
	let vaux	= "";
	let digito10	= 0;

    If pcuenta = "" Then
        LET digito10 = 0;
    Else
        For i = 1 To length(TRIM(pcuenta))
            LET k = SUBSTR(pcuenta, i, 1);
            If MOD(i,2) = 0 Then
                LET p = 1;
            Else
                LET p = 2;
            End If
            LET vaux = LPAD(k * p, 2, "0");
            LET n1 = SUBSTR(vaux, 1, 1);
            LET n2 = SUBSTR(vaux, 2, 1);
            LET n = n + n1 + n2;
        end for
    End If
    If MOD(n,10) = 0 Then
        LET k = n;
    Else
        LET k = n - MOD(n,10) + 10;
    End If

	LET digito10 = k - n;
return cod_ret, digito10;
end procedure;

CREATE PROCEDURE "informix".sp_portanom_consultasolicitudes(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaRegistro DATE, pCodigoOperacion INTEGER, pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
				CHAR(20) AS numero_cliente,
				CHAR(30) AS folio,
				CHAR(20) AS banco_ordenante,
				CHAR(30) AS estatus_respuesta,
				INTEGER AS no_registro,
				INTEGER AS total_registros;
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(3);
	DEFINE iCodRetSp INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iNoRegistrosTmp INTEGER;
	DEFINE cNumeroCliente CHAR(20);
	DEFINE cFolio CHAR(30);
	DEFINE cBancoOrdenante CHAR(20);
	DEFINE cEstatusRespuesta CHAR(30);
	DEFINE iNoRegistro INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iNoRegistros = 0;
	LET iNoRegistrosTmp = 0;
	LET cNumeroCliente = '';
	LET cFolio = '';
	LET cBancoOrdenante = '';
	LET cEstatusRespuesta = '';
	LET iNoRegistro = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
		END EXCEPTION;
		
		-- SET DEBUG FILE TO '/tmp/mfinis/sp_portanom_consultasolicitudes.out';
		-- TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaRegistro IS NULL OR pCodigoOperacion IS NULL OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
		END IF;
		
		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
		END IF;
		
		FOREACH EXECUTE PROCEDURE bdicheq:'informix'.sp_consultsolicitudes(pFechaRegistro, pCodigoOperacion, pRegistros, pRecuperacion)
			INTO cCodRetSp, iNoRegistro, cFolio, cNumeroCliente, cBancoOrdenante, cEstatusRespuesta, iNoRegistros
			
			LET iCodRetSp = cCodRetSp::INTEGER;
			IF iCodRetSp < 0 THEN
				RAISE EXCEPTION iCodRetSp, 0, "ERROR EN LA EJECUCION DEL SP bdicheq:'informix'.sp_consultsolicitudes";
			ELIF iCodRetSp = 2 THEN
				LET cCodRet = '00003';
				RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
			ELIF iCodRetSp = 3 THEN
				LET cCodRet = '00232';
				RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
			ELIF iCodRetSp = 1 AND pRegistros = 0 THEN
				LET cCodRet = '00021';
				RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
			ELIF iCodRetSp = 1 AND pRegistros > 0 THEN
				EXIT FOREACH;
			END IF;
			
			LET iNoRegistrosTmp = iNoRegistrosTmp + 1;
			RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros WITH RESUME;
		
		END FOREACH;
		
		IF iNoRegistrosTmp = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cNumeroCliente, cFolio, cBancoOrdenante, cEstatusRespuesta, iNoRegistro, iNoRegistros;
		END IF;
	
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Oscar Flores Conde',
'FECHA: 08/09/2015',
'MODULO: Operaciones',
'FUNCIONALIDAD: Portabilidad de nÃ³mina - Solicitudes',
'DESCRIPCION: Consulta las solicitudes de portabilidad generadas en BanCoppel',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_rptportab2_totales(fInicial date, fFinal date, TpoSol int)
					RETURNING       CHAR(5),        -- COD-RET
									INTEGER;        -- REGISTROS ENCONTRADOS

	DEFINE sql_err          INTEGER;
	DEFINE vcodret1     CHAR(5);
	DEFINE vtotalregistros     INTEGER;
	DEFINE vfechaini        CHAR(8);
	DEFINE vfechafin        CHAR(8);

	LET vcodret1 = "000";
	LET sql_err  = 0;
	LET vtotalregistros = 0;
	LET vfechaini = "";
	LET vfechafin = "";	

	BEGIN

		------  Control de Errores no Controlados
		ON EXCEPTION SET sql_err
			IF sql_err <> 0 THEN
				Let vcodret1 = sql_err;    
				RETURN vcodret1, vtotalregistros;
			END IF;
		END EXCEPTION;

		--SET DEBUG FILE TO "/informix/PORTABILIDAD_NOMINA/sp_rptportab.out";
		--TRACE ON;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		IF LENGTH(NVL(fInicial,'')) = 0 OR LENGTH(NVL(fFinal,'')) = 0 OR LENGTH(NVL(TpoSol,'')) = 0  THEN
			LET vcodret1='001';
			RETURN vcodret1, vtotalregistros;
		END IF;

		LET vfechaini = YEAR(fInicial)||LPAD(MONTH(fInicial),2,0)||LPAD(DAY(fInicial),2,0); 
		LET vfechafin = YEAR(fFinal)||LPAD(MONTH(fFinal),2,0)||LPAD(DAY(fFinal),2,0); 

		-- SOLICITUDES ENVIADAS 
		IF TpoSol=1 THEN
			SELECT COUNT(*)
			INTO vtotalregistros
			FROM "informix".sc_portacec_solicitud sol 
				INNER JOIN "informix".sc_portacec_estatus_portabilidad ep ON sol.estatus_portabilidad=ep.estatus_portabilidad
				LEFT JOIN "informix".sc_portacec_estatus_respuesta er ON sol.estatus_respuesta=er.estatus_respuesta
				INNER JOIN bdinteg:si_bancos bco ON sol.bco_ordenante=bco.cvecesif
				INNER JOIN bdinteg:si_cliente cte ON sol.num_cte=cte.numcte
			WHERE fecha_presentacion between vfechaini and vfechafin
				AND clave_origen in (1,2);
			
			LET vcodret1='000';
			RETURN vcodret1, vtotalregistros;
		-- SOLICITUDES RECIBIDAS
		ELIF TpoSol=2 THEN
			SELECT COUNT(*)
			INTO  vtotalregistros
			FROM "informix".sc_portacec_solicitud sol 
				INNER JOIN "informix".sc_portacec_estatus_portabilidad ep ON sol.estatus_portabilidad=ep.estatus_portabilidad
				LEFT JOIN "informix".sc_portacec_estatus_respuesta er ON sol.estatus_respuesta=er.estatus_respuesta
				INNER JOIN bdinteg:si_bancos bco ON sol.bco_ordenante=bco.cvecesif
				LEFT JOIN bdinteg:si_cliente cte ON sol.num_cte=cte.numcte
			WHERE fecha_presentacion between vfechaini and vfechafin
				AND clave_origen = 3;

			LET vcodret1='000';
			RETURN vcodret1, vtotalregistros;
		-- TIPO SOLICITUD INCORRECTA
		ELSE
			LET vcodret1='002';
			RETURN vcodret1, vtotalregistros;
		END IF;

	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_genera_folio_portabilidad(pEmpresa CHAR(3),pSucursal CHAR(4),pTipoOperacion CHAR(2),pIdentificador CHAR(1))
--DATOS A REGRESAR---
RETURNING	CHAR(6) AS cCodRet,
			CHAR(30) AS cFolio;

--DEFINICION DE VARIABLES--
DEFINE  cCodRet 		CHAR(6);
DEFINE  cSucursal		CHAR(8);
DEFINE  cFolio			CHAR(30);
DEFINE  cCveSPEI		CHAR(5);
DEFINE  cHoraUno		CHAR(8);
DEFINE  cHora			CHAR(6);
DEFINE  cFecha			CHAR(8);
DEFINE  cFechaNormal	CHAR(10);
DEFINE  iSqlErr			INTEGER;

--INICIALIZACION DE VARIABLES--
LET cCodRet 		= '000000';
LET cSucursal		= '';
LET cFolio			= '';
LET cCveSPEI		= '';
LET cHoraUno		= '';
LET cHora			= '';
LET cFecha			= '';
LET cFechaNormal	= '';
LET iSqlErr			= 0;

BEGIN
	ON EXCEPTION SET iSqlErr
	   IF (iSqlErr != 0) THEN
		  LET cCodRet = iSqlErr;
		  RETURN cCodRet,cFolio;
	   END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO '/respaldosbd/claudio/sp_genera_folio_portabilidad.out';
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	IF NVL(pEmpresa,'') <> '' AND NVL(pSucursal,'') <> '' AND NVL(pTipoOperacion,'') <> '' AND NVL(pIdentificador,'') <> '' THEN
		SELECT fecha_hoy INTO cFechaNormal FROM bdicheq:"informix".sc_fechas
		WHERE empresa = pEmpresa;

		LET cFecha = TRIM(SUBSTR(cFechaNormal,7,4) || SUBSTR(cFechaNormal,1,2) || SUBSTR(cFechaNormal,4,2));

		SELECT FIRST 1 CURRENT HOUR TO SECOND INTO cHoraUno FROM "informix".systables;
		LET cHora =  REPLACE(cHoraUno,':','');

		SELECT cvecesif INTO cCveSPEI FROM bdinteg:"informix".si_bancos
		WHERE banco = '137';

		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodret = '001289';
		END IF;

		SELECT clave_tipo INTO cFechaNormal
		FROM bdicheq:"informix".sc_portacec_tipo_operacion
		WHERE clave_tipo = pTipoOperacion;

		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodret = '001289';
		ELSE
			LET cSucursal = LPAD(pSucursal,8,"0");
			LET cFolio = TRIM(cFecha||cHora||cCveSPEI||pTipoOperacion||pIdentificador||cSucursal);
		END IF;

	ELSE
		LET cCodRet ='001288';
	END IF
	RETURN cCodRet,cFolio;
END;
END PROCEDURE
DOCUMENT
'000000 - Se genera el folio',
'001289 - No existe el banco o tipo operacion',
'001288 - Parametros incompletos',
'DESCRIPCION: Genera el folio de solicitud de portabilidad de nomina',
'AUTOR : Claudio Almodovar',
'Folio:1748',
'Solicita: Rodolfo Gómez',
'FECHA : 31/08/2015',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_obten_info_cancelacion(pEmpresa CHAR(3),pNumCta CHAR(20),pNumCte CHAR(20))
--DATOS A REGRESAR---
RETURNING	CHAR(6) AS cCodRet,
			CHAR(40) AS cBancoOrdenante,
			CHAR(18) AS cCuentaCLABEOrdenante,
			CHAR(40) AS cBancoReceptor,
			CHAR(18) AS cCuentaCLAVEReceptor,
			CHAR(30) AS cFolioSolicitud;

--DEFINICION DE VARIABLES--
DEFINE  cCodRet 				CHAR(6);
DEFINE  cBancoOrdenante			CHAR(40);
DEFINE  cCuentaCLABEOrdenante	CHAR(18);
DEFINE  cBancoReceptor			CHAR(40);
DEFINE  cCuentaCLAVEReceptor	CHAR(18);
DEFINE  cFolioSolicitud			CHAR(30);
DEFINE  iSqlErr					INTEGER;

--INICIALIZACION DE VARIABLES--
LET cCodRet 				= '000000';
LET cBancoOrdenante			= '';
LET cCuentaCLABEOrdenante	= '';
LET cBancoReceptor			= '';
LET cCuentaCLAVEReceptor	= '';
LET cFolioSolicitud			= '';
LET iSqlErr					= 0;

BEGIN
	ON EXCEPTION SET iSqlErr
	   IF (iSqlErr != 0) THEN
		  LET cCodRet = iSqlErr;
		  RETURN cCodRet,cBancoOrdenante,cCuentaCLABEOrdenante,cBancoReceptor,cCuentaCLAVEReceptor,cFolioSolicitud;
	   END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO '/respaldosbd/claudio/sp_obten_info_cancelacion.out';
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	IF NVL(pEmpresa,'') <> '' AND NVL(pNumCta,'') <> '' AND NVL(pNumCte,'') <> '' THEN

	SELECT cta_ordenante, bco_ordenante, cta_receptora, bco_receptor, folio_solicitud
		INTO cCuentaCLABEOrdenante,cBancoOrdenante,cCuentaCLAVEReceptor,cBancoReceptor,cFolioSolicitud
		FROM bdicheq:"informix".sc_portacec_solicitud
		WHERE empresa = pEmpresa AND num_cte = pNumCte AND cta_ordenante = pNumCta
            and folio_solicitud = (SELECT max(folio_solicitud)
                                               FROM bdicheq:"informix".sc_portacec_solicitud
                                               WHERE empresa = pEmpresa 
                                                 AND num_cte = pNumCte
                                                 AND cta_ordenante = pNumCta
                                                  AND clave_sentido in ('1', '0')
                                                   And estatus_portabilidad = '1');

		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodret = '001289';
		ELSE
			SELECT descripcion INTO cBancoOrdenante FROM bdinteg:"informix".si_bancos
			WHERE cvecesif = cBancoOrdenante;

			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				LET cCodret = '001289';
			ELSE
				SELECT descripcion INTO cBancoReceptor FROM bdinteg:"informix".si_bancos
				WHERE cvecesif = cBancoReceptor;
				
				IF DBINFO('sqlca.sqlerrd2') = 0 THEN
					LET cCodret = '001289';
				END IF;
			END IF;
		END IF;
	ELSE
		LET cCodRet ='001288';
	END IF
	RETURN cCodRet,cBancoOrdenante,cCuentaCLABEOrdenante,cBancoReceptor,cCuentaCLAVEReceptor,cFolioSolicitud;
END;
END PROCEDURE
DOCUMENT
'000000 - Retorna Datos',
'001289 - No existe el Cliente',
'001288 - Parametros incompletos',
'DESCRIPCION: obtener la información de la orden de cancelación de transferencia',
'AUTOR : Claudio Almodovar',
'Folio:1748',
'Solicita: Rodolfo Gómez',
'FECHA : 31/08/2015',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_verificatarjetaotrosbancos(pClaveBanco CHAR(3),pNumtarjeta CHAR(16))
--DATOS A REGRESAR---
RETURNING	CHAR(6) AS cCodRet;

--DEFINICION DE VARIABLES--
DEFINE  cCodRet 		CHAR(6);
DEFINE  cCve_banco		CHAR(3);
DEFINE  cbin			CHAR(6);
DEFINE  cCreditodebito	CHAR(1);
DEFINE  iSqlErr			INTEGER;

--INICIALIZACION DE VARIABLES--
LET cCodRet 		= '000000';
LET cCve_banco		= '';
LET cbin			= '';
LET cCreditodebito	= '';
LET iSqlErr			= 0;

BEGIN
	ON EXCEPTION SET iSqlErr
	   IF (iSqlErr != 0) THEN
		  LET cCodRet = iSqlErr;
		  RETURN cCodRet;
	   END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO '/respaldosbd/claudio/sp_verificatarjetaotrosbancos.out';
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	IF NVL(pClaveBanco,'') <> '' AND NVL(pNumtarjeta,'') <> '' THEN

		LET cbin = TRIM(SUBSTR(pNumtarjeta,1,6));

		SELECT creditodebito,cve_banco INTO cCreditodebito,cCve_banco
		FROM bdicheq:"informix".sc_bines
		WHERE bin = cbin;

		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodret = '000245';
		ELSE
			IF NVL(cCreditodebito,'') <> 'd' THEN
				LET cCodret = '000245';			
			ELSE
				IF NVL(cCve_banco,'') <> NVL(pClaveBanco,'') THEN
					LET cCodret = '001270';
				END IF;
			END IF;
		END IF;
	ELSE
		LET cCodRet ='001288';
	END IF
	RETURN cCodRet;
END;
END PROCEDURE
DOCUMENT
'000000 - Exito',
'000245 - Tarjeta de credito o no existe el bin',
'001270 - claves de bancos distintos',
'001288 - Parametros incompletos',
'DESCRIPCION: Verifica la tarjeta de otros bancos',
'AUTOR : Claudio Almodovar',
'Folio:1748',
'Solicita: Rodolfo Gómez',
'FECHA : 31/08/2015',
'BD: bdicheq';

CREATE PROCEDURE "informix".sp_valida_portabilidad(pEmpresa CHAR(3),pNumCte CHAR(20),pNumCtaOrd CHAR(20))
--DATOS A REGRESAR---
RETURNING	CHAR(6) AS cCodRet,
			CHAR(20) AS cCuentaOrd;

--DEFINICION DE VARIABLES--
DEFINE  cCodRet 	CHAR(6);
DEFINE  cCuentaOrd	CHAR(20);
DEFINE  iSqlErr		INTEGER;

--INICIALIZACION DE VARIABLES--
LET cCodRet 	= '000000';
LET cCuentaOrd	= '';
LET iSqlErr		= 0;

BEGIN
	ON EXCEPTION SET iSqlErr
	   IF (iSqlErr != 0) THEN
		  LET cCodRet = iSqlErr;
		  RETURN cCodRet,cCuentaOrd;
	   END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO '/respaldosbd/claudio/sp_valida_portabilidad.out';
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	IF NVL(pEmpresa,'') <> '' AND NVL(pNumCte,'') <> '' AND NVL(pNumCtaOrd,'') <> '' THEN
		SELECT numcte INTO cCuentaOrd FROM bdinteg:"informix".si_cliente
		WHERE empresa = pEmpresa AND numcte = pNumCte;

		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodret = '001289';
		ELSE
			SELECT cta_receptora INTO cCuentaOrd FROM bdicheq:"informix".sc_portacec_solicitud
			WHERE empresa = pEmpresa AND num_cte = pNumCte AND cta_ordenante = pNumCtaOrd
			AND estatus_portabilidad = '1';

			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				LET cCodret = '000000';
			ELSE
				LET cCodret = '000001';
			END IF;
		END IF;
	ELSE
		LET cCodRet ='001288';
	END IF
	RETURN cCodRet,cCuentaOrd;
END;
END PROCEDURE
DOCUMENT
'000000 - Retorna Cuenta',
'000001 - Sin Cuenta',
'001289 - No existe el Cliente',
'001288 - Parametros incompletos',
'DESCRIPCION: Validar si la cuenta ordenante a la que se desea generar una solicitud de portabilidad ya tiene una cuenta con portabilidad Activa',
'AUTOR : Claudio Almodovar',
'Folio:1748',
'Solicita: Rodolfo Gómez',
'FECHA : 31/08/2015',
'BD: bdicheq';

CREATE PROCEDURE "informix".cargo_retenido_comp_pba(pempresa char(3))

RETURNING CHAR(5), CHAR(5), INTEGER;
     
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE nComit           INTEGER;
    DEFINE vcuantos         INTEGER;
    
    DEFINE vfecha           DATE;
    DEFINE vhora            CHAR(15);
    DEFINE vsql             CHAR(200);
    DEFINE vfolio           CHAR(20);
    DEFINE vcuenta          CHAR(20);
    DEFINE vstatus          CHAR(1);
    DEFINE vimporte         MONEY(14,2);
    DEFINE vimport          MONEY(14,2);
    DEFINE vdisp            MONEY(14,2);
    DEFINE vmaxsec          SMALLINT;
    DEFINE vtarjeta         CHAR(16);
    DEFINE vsucursal        CHAR(4);
    DEFINE vtransacc        CHAR(4);
    DEFINE vfecha_cargo     DATE;
    DEFINE vdispo           MONEY(14,2);
    DEFINE vcargo           MONEY(14,2);
    DEFINE vdescripcion     CHAR(40);
    DEFINE vexiste          INTEGER;
    DEFINE vfechades        CHAR(10);
    DEFINE vfechadescarga   CHAR(6);
    DEFINE vdia             CHAR(2);
    DEFINE vmes             CHAR(2);
    DEFINE vanio            CHAR(2);
    DEFINE vnombre          VARCHAR(50);
    DEFINE vcargado         MONEY(14,2);
    DEFINE whora1           CHAR(5);
    DEFINE whora2           CHAR(2);
    DEFINE whora3           CHAR(2);
    DEFINE whora            CHAR(4);
    DEFINE vfecha_mov       DATE;
    DEFINE vfecha1          CHAR(10);

    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF nComit = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcuantos;
        END IF;
    END EXCEPTION;

    -- SET DEBUG FILE TO "/resplogifx/conciliachq/cargo_retenido_comp.out";
    -- TRACE ON;

    LET vcodret1     = "000";
    LET vcodret2     = "000";
    LET nComit      = 0;
    LET vcuantos    = -1;
    
    LET vfecha       = '';
    LET vhora        = '';
    LET vfolio       = '';
    LET vcuenta      = ''; 
    LET vimporte     = 0.00; 
    LET vdescripcion = ''; 
    LET vfecha_mov   = '';  
    LET vdisp        = 0.00; 
    LET vsucursal    = ''; 
    LET vstatus      = '';  
    LET vmaxsec      = '';  
    LET vtarjeta     = '';  
    LET vexiste      = '';  
    LET vtransacc    = '';  
    LET vfecha_cargo = '';  
    LET vdispo       = 0.00; 
    LET vcargo       = 0.00; 
    LET vimport      = 0.00;

    SET ISOLATION TO DIRTY READ;

    SELECT fecha_hoy
      INTO vfecha
      FROM sc_fechas
     WHERE empresa = pempresa;

    LET vhora = CURRENT HOUR TO FRACTION;
    LET vfolio = "informix"||vhora[1,2]||vhora[4,5]||vhora[7,8]||vhora[10,11];
    
    TRUNCATE TABLE "informix".cargos;

    FOREACH WITH HOLD
        SELECT cuenta, importe, descripcion, fecha
          INTO vcuenta, vimporte, vdescripcion, vfecha_mov
          FROM cuentas

        SELECT sdo_actual - sdo_cong - sdo_retenido, sucursal, status_cta
          INTO vdisp, vsucursal, vstatus
          FROM sc_maechq
         WHERE empresa = pempresa
           AND cuenta = vcuenta;
           
        IF vcuantos = -1 THEN
            BEGIN WORK;
            LET nComit = 1;
            LET vcuantos = 0;
        END IF

        IF vdisp > 0.00 THEN
        
            SELECT MAX(secuencia)
              INTO vmaxsec
              FROM sc_tarjeta
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND tipo_tarjeta = "T";

            SELECT num_tarjeta
              INTO vtarjeta
              FROM sc_tarjeta
             WHERE empresa = pempresa
               AND cuenta = vcuenta
               AND secuencia = vmaxsec;

            IF vstatus = 3 THEN
                UPDATE sc_maechq
                   SET status_cta = "1",
                       motivo = " "
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta;

                SELECT COUNT(*)
                  INTO vexiste
                  FROM sc_ctabloqueo
                 WHERE cuenta = vcuenta;

                IF vexiste <> 0 THEN
                    DELETE FROM sc_ctabloqueo
                     WHERE cuenta = vcuenta;
                END IF

                SELECT COUNT(*)
                  INTO vexiste
                  FROM sc_histbloq
                 WHERE cuenta = vcuenta
                   AND status_blo = "B"
                   AND tipo_mov = "B"
                   AND empresa = pempresa;

                IF vexiste <> 0 THEN
                     INSERT INTO sc_histbloq (empresa,cuenta,tipo_mov,motivo,opcion,importe,usuario,fecha,hora,clave,status_blo,folio_suc,referencia)  
					 VALUES(pempresa, vcuenta, "D", "00", " ",0.00, "informix", vfecha,current hour to fraction,"1111", "D", vfolio, " ");
                END IF

            END IF

            IF vdisp >= vimporte THEN

                CALL cargo_ref(pempresa, vsucursal, "informix", "0270", 
                               "0270", vfolio, vcuenta, 0, vimporte, "01", 
                               vdescripcion, vtarjeta, "informix")
                RETURNING vcodret1, vtransacc, vfecha_cargo, vdispo, vcargo;
				
                IF vcodret1 = "000" THEN

                    LET vcargo = vcargo;

                ELSE

                    UPDATE sc_maechq
                       SET status_cta = "3",
                           motivo = "09"
                     WHERE empresa = pempresa
                       AND cuenta = vcuenta;

                    SELECT COUNT(*)
                      INTO vexiste
                      FROM sc_ctabloqueo
                     WHERE cuenta = vcuenta;

                    IF vexiste = 0 THEN
                        INSERT INTO sc_ctabloqueo (cuenta,clave,opcion) VALUES(vcuenta, "09", "3");
                    ELSE
                        UPDATE sc_ctabloqueo
                           SET clave = "09",
                               opcion = "3"
                         WHERE cuenta = vcuenta;
                    END IF

                    INSERT INTO sc_ctabloqueohist VALUES (vcuenta, "09", "3");

                    INSERT INTO sc_histbloq (empresa,cuenta,tipo_mov,motivo,opcion,importe,usuario,fecha,hora,clave,status_blo,folio_suc,referencia)  
					VALUES(pempresa,vcuenta,"B","09",3,0.00,"informix",vfecha, current hour to fraction,"1111","B",vfolio," ");

                    LET vcargo = 0;

                END IF

                INSERT INTO cargos VALUES(vcuenta,vimporte,vcargo,vdescripcion, " ", vfecha_mov);

            ELSE

                LET vimport = vdisp;

                CALL cargo_ref(pempresa, vsucursal, "informix", "0270", 
                               "0270", vfolio, vcuenta, 0, vimport, "01",
                               vdescripcion, vtarjeta, "informix")
                RETURNING vcodret1, vtransacc, vfecha_cargo, vdispo, vcargo;

                IF vcodret1 = "000" THEN

                    UPDATE sc_maechq
                       SET status_cta = "3",
                           motivo = "09"
                     WHERE empresa = pempresa
                       AND cuenta = vcuenta;

                    SELECT COUNT(*)
                      INTO vexiste
                      FROM sc_ctabloqueo
                     WHERE cuenta = vcuenta;

                    IF vexiste = 0 THEN
                        INSERT INTO sc_ctabloqueo (cuenta,clave,opcion) VALUES (vcuenta, "09", "3");
                    ELSE 
                        UPDATE sc_ctabloqueo
                           SET clave = "09",
                               opcion = "3"
                         WHERE cuenta = vcuenta;
                    END IF

                    INSERT INTO sc_ctabloqueohist VALUES (vcuenta, "09", "3");

                     INSERT INTO sc_histbloq (empresa,cuenta,tipo_mov,motivo,opcion,importe,usuario,fecha,hora,clave,status_blo,folio_suc,referencia)  
					 VALUES(pempresa,vcuenta,"B","09",3,0.00,"informix",vfecha,current hour to fraction,"1111","B",vfolio," ");

                    LET vcargo = vcargo;

                ELSE

                    UPDATE sc_maechq
                       SET status_cta = "3",
                           motivo = "09"
                     WHERE empresa = pempresa
                       AND cuenta = vcuenta;

                    SELECT COUNT(*)
                      INTO vexiste
                      FROM sc_ctabloqueo
                     WHERE cuenta = vcuenta;

                    IF vexiste = 0 THEN
                        INSERT INTO sc_ctabloqueo (cuenta,clave,opcion) VALUES (vcuenta, "09", "3");
                    ELSE 
                        UPDATE sc_ctabloqueo
                           SET clave = "09",
                               opcion = "3"
                         WHERE cuenta = vcuenta;
                    END IF

                    INSERT INTO sc_ctabloqueohist VALUES (vcuenta, "09", "3");

                     INSERT INTO sc_histbloq (empresa,cuenta,tipo_mov,motivo,opcion,importe,usuario,fecha,hora,clave,status_blo,folio_suc,referencia)  
					 VALUES(pempresa,vcuenta,"B","09",3,0.00,"informix",vfecha, current hour to fraction,"1111","B",vfolio," ");

                    LET vcargo = 0;

                END IF

                INSERT INTO cargos VALUES(vcuenta,vimporte,vcargo,vdescripcion, " ", vfecha_mov);

            END IF

        ELSE
        
            IF vstatus <> 3 THEN
                UPDATE sc_maechq
                   SET status_cta = "3",
                       motivo = "09"
                 WHERE empresa = pempresa
                   AND cuenta = vcuenta;

                SELECT COUNT(*)
                  INTO vexiste
                  FROM sc_ctabloqueo
                 WHERE cuenta = vcuenta;

                IF vexiste = 0 THEN
                    INSERT INTO sc_ctabloqueo (cuenta,clave,opcion) VALUES (vcuenta, "09", "3");
                ELSE 
                    UPDATE sc_ctabloqueo
                       SET clave = "09",
                           opcion = "3"
                     WHERE cuenta = vcuenta;
                END IF

                INSERT INTO sc_ctabloqueohist VALUES (vcuenta, "09", "3");

                 INSERT INTO sc_histbloq (empresa,cuenta,tipo_mov,motivo,opcion,importe,usuario,fecha,hora,clave,status_blo,folio_suc,referencia)  
				 VALUES(pempresa,vcuenta,"B","09",3,0.00,"informix",vfecha,current hour to fraction,"1111","B",vfolio," ");

            END IF
            
            LET vcargo = 0;

            INSERT INTO cargos VALUES(vcuenta,vimporte,vcargo,vdescripcion, " ", vfecha_mov);
            
            LET vcuantos = vcuantos + 1;
            
            COMMIT WORK;
            BEGIN WORK;
            
            LET vcuenta      = ''; 
            LET vimporte     = 0.00; 
            LET vdescripcion = ''; 
            LET vfecha_mov   = '';  
            LET vdisp        = 0.00; 
            LET vsucursal    = ''; 
            LET vstatus      = '';  
            LET vmaxsec      = '';  
            LET vtarjeta     = '';  
            LET vexiste      = '';  
            LET vtransacc    = '';  
            LET vfecha_cargo = '';  
            LET vdispo       = 0.00; 
            LET vcargo       = 0.00; 
            LET vimport      = 0.00;

            CONTINUE FOREACH;

        END IF;
        
        LET vcuantos = vcuantos + 1;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vcuenta      = ''; 
        LET vimporte     = 0.00; 
        LET vdescripcion = ''; 
        LET vfecha_mov   = '';  
        LET vdisp        = 0.00; 
        LET vsucursal    = ''; 
        LET vstatus      = '';  
        LET vmaxsec      = '';  
        LET vtarjeta     = '';  
        LET vexiste      = '';  
        LET vtransacc    = '';  
        LET vfecha_cargo = '';  
        LET vdispo       = 0.00; 
        LET vcargo       = 0.00; 
        LET vimport      = 0.00;
    END FOREACH

    IF nComit = 1 THEN
        COMMIT WORK;
        LET nComit = 0;
    END IF;

    UPDATE STATISTICS MEDIUM FOR TABLE cargos;

    LET whora1 = CURRENT HOUR TO MINUTE;
    LET whora2 = whora1[1,2];
    LET whora3 = whora1[4,5];
    LET whora = whora2||whora3;
    LET vfechades = TO_CHAR(vfecha, '%Y/%m/%d');
    LET vdia = vfechades[9,10];
    LET vmes = vfechades[6,7];
    LET vanio = vfechades[3,4];
    LET vfechadescarga = vdia||vmes||vanio;
    LET vnombre = 'aplicados_'||vfechadescarga||'_'||whora||'.txt';

    LET vsql = "";
    -- LET vsql = 'echo "UNLOAD TO ./'||vnombre||' SELECT * FROM cargos " > ./cargos.sql';
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/'||vnombre||' SELECT * FROM cargos WHERE cargado > 0" > /resplogifx/conciliachq/cargos.sql';
    SYSTEM vsql;
    LET vsql = "";
    -- LET vsql = "dbaccess bdicheq ./cargos.sql";
    LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/cargos.sql";
    SYSTEM vsql;
    LET vsql = "";
    -- LET vsql = 'chmod 664 ./'||vnombre;
    LET vsql = '/usr/bin/chmod 664 /resplogifx/conciliachq/'||vnombre;
    SYSTEM vsql;
    LET vsql = "";
    
    TRUNCATE TABLE "informix".cuentas;
    
    LET vcuenta      = '';
    LET vcargo       = 0.00;
    LET vcargado     = 0.00;
    LET vdescripcion = '';
    LET vfecha_mov   = '';
    
    FOREACH WITH HOLD
        SELECT cuenta, cargo, cargado, descripcion, fecha
          INTO vcuenta, vcargo, vcargado, vdescripcion, vfecha_mov
          FROM cargos
        
        BEGIN WORK;
        
        LET vcargo = vcargo - vcargado;
          
        IF vcargo > 0 THEN
            INSERT INTO cuentas VALUES(vcuenta, vcargo, vdescripcion, vfecha_mov);
        END IF;
        
        COMMIT WORK;
        
        LET vcuenta      = '';
        LET vcargo       = 0.00;
        LET vcargado     = 0.00;
        LET vdescripcion = '';
        LET vfecha_mov   = '';
    END FOREACH;
    
    UPDATE STATISTICS MEDIUM FOR TABLE cuentas;

    END;

    RETURN vcodret1, vcodret2, vcuantos;

END PROCEDURE
DOCUMENT 
'Se realiza modificacion al procedimiento en los inserts a la tablas sc_ctabloqueo y sc_histbloq ',
'Modifico : Jesús Manuel Aguilar Heredia',
'FECHA : 13/SEPTIEMBRE/2010',
'BD    : BDICHEQ';

CREATE PROCEDURE "informix".sp_inserta_portabilidad(pEmpresa CHAR(3), 
													  pNumCte CHAR(20), 
													  pCuentaAbono CHAR(20),
													  pCuentaCLABERef CHAR(18),
													  pTarjetaRef CHAR(20),													  
													  pFechaDeposito CHAR(60), 
													  pEstatus CHAR(2), 
													  pOrigenAlta CHAR(20), 
													  pSucursalAlta CHAR(4),
													  pUserInsert CHAR(8),
													  pBancoRec CHAR(3))
--DATOS A REGRESAR---												 
	RETURNING
	CHAR(6) AS cCodRet;

---DECLARACIONES
DEFINE iSqlErr  	INTEGER;
DEFINE cCodRet  	CHAR(6);
DEFINE cProducto  	CHAR(4);
DEFINE cStatusCta  	CHAR(1);
DEFINE cValor	  	CHAR(60);
DEFINE cStatusPorta	CHAR(2);
DEFINE sClaveDest	CHAR(3);
DEFINE cCuenta		CHAR(20);
DEFINE iTransaccion INTEGER;
DEFINE iSecuencia   INTEGER;
DEFINE dFecha		DATE;

DEFINE vcuenta      CHAR(20);

---INICIALIZACIONES
LET iSqlErr      = 0;
LET cCodRet      = "000000";
LET cProducto    = "";
LET cStatusCta   = "";
LET cValor	     = "";
LET cStatusPorta = "";
LET sClaveDest	 = "";
LET cCuenta	 	 = "";
LET iTransaccion = 0;
LET iSecuencia	 = 0;
LET dFecha		 = DATE(1);

LET vcuenta      = ''; 

BEGIN	

	ON EXCEPTION SET iSqlErr --Manejador de Errores	
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
			IF iTransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                
				 BEGIN WORK;
            END IF;
		DELETE bdicheq:"informix".sc_portacec_solicitud 
		WHERE empresa = pEmpresa
		AND num_cte = pNumCte 
		AND cta_ordenante = pCuentaAbono
		AND cta_receptora = CASE WHEN pCuentaCLABERef = '' THEN pTarjetaRef ELSE pCuentaCLABERef END;
		
		LET cCodRet = "001272";
		RETURN cCodRet;
			
        END IF;		
    END EXCEPTION;
	
	ON EXCEPTION IN (-535)
        LET iTransaccion = 1;
    END EXCEPTION WITH RESUME;
	
    IF iTransaccion = 1 THEN
         COMMIT WORK;
         BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;

	
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	--SET DEBUG FILE TO "/respaldosbd/martin/sp_inserta_portabilidad.out";
	--TRACE ON;
		
	IF NVL(pEmpresa,"") = "" OR NVL(pNumCte,"") = "" OR NVL(pCuentaAbono,"") = "" OR NVL(pFechaDeposito,"") = "" OR NVL(pEstatus,"") = "" OR NVL(pOrigenAlta,"") = "" OR NVL(pSucursalAlta,"") = "" OR NVL(pUserInsert,"") = "" THEN			
		LET cCodRet = "001288"; --PARAMETROS VACIOS		
		RETURN cCodRet;												  
	ELSE			
				
		SELECT fecha_hoy
		INTO dFecha
		FROM bdicheq:"informix".sc_fechas 
		WHERE empresa = pEmpresa;
					
					
		LET vcuenta = substr(pCuentaAbono, 7, 11);			
					
					
		SELECT producto, status_cta,cuenta
		INTO cProducto, cStatusCta,cCuenta
		FROM bdicheq:"informix".sc_maechq
		WHERE empresa = pEmpresa
		AND cuenta = vcuenta;
		--AND cuenta_clabe = pCuentaAbono;
			
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN		
			LET cCodRet = "001289";			
			RETURN cCodRet;	
		END IF;
	
		IF (SELECT COUNT(valor) FROM bdicheq:"informix".sc_param WHERE empresa = pEmpresa AND codparam = "PORTAPRODPERM" AND valor LIKE '%'||cProducto||'%') = 1 THEN			
	
		ELSE			
			LET cCodRet = "001285";			
			RETURN cCodRet;	
		END IF;
		
		IF cStatusCta = "2" OR cStatusCta = "6" OR cStatusCta = "7" OR cStatusCta = "8" THEN		
			LET cCodRet = "001290";			
			RETURN cCodRet;			
		END IF;
				
		SELECT NVL(MAX(secuencia),0)
		INTO iSecuencia
		FROM bdicheq:"informix".sc_portabilidadnomina 
		WHERE empresa = pEmpresa
		AND cliente = pNumCte
		AND cuenta_abono = pCuentaAbono;
		

		SELECT estatus
		INTO cStatusPorta
		FROM bdicheq:"informix".sc_portabilidadnomina 
		WHERE empresa = pEmpresa
		AND cliente = pNumCte
		AND cuenta_abono = pCuentaAbono
		AND secuencia = iSecuencia;
		
		IF NVL(cStatusPorta,"") = "01" THEN		
			LET cCodRet = "001291"; --"LA CUENTA BANCOPPEL YA CUENTA CON EL SERVICIO DE PORTABILIDAD ACTIVO"				
			RETURN cCodRet;				
		END IF;
		
		IF iSecuencia IS NULL THEN
			LET iSecuencia = 1;
		ELSE
			LET iSecuencia = iSecuencia+1;
		END IF;
		
		LET sClaveDest = pBancoRec; 
		
		IF EXISTS (SELECT banco FROM bdinteg:"informix".si_bancos WHERE banco = sClaveDest) THEN
						
		ELSE
			LET cCodRet = "001289"; --Codigo del BancoDestino no valido; No existe en el catálogo de Bancos.		
			RETURN cCodRet;			
			
		END IF;
		
		INSERT INTO bdicheq:"informix".sc_portabilidadnomina (empresa,cliente,cuenta_abono,secuencia,banco_ref,cuenta_ref,tarjeta_ref,fecha_deposito,estatus,user_cancel,fecha_cancel,origen_alta,sucursal_alta,origen_cancel,sucursal_cancel,user_insert,fecha_insert) 
		VALUES (pEmpresa,pNumCte,cCuenta,iSecuencia,sClaveDest,pCuentaCLABERef,pTarjetaRef,pFechaDeposito,pEstatus,USER,dFecha,pOrigenAlta,pSucursalAlta,'OFI','0002',pUserInsert,CURRENT);
		
		RETURN cCodRet;
	
	END IF;
END;
END PROCEDURE
DOCUMENT
"Descripcion: Se crea procedimiento para insertar en la tabla sc_portabilidadnomina la informacion cuando el proceso de alta.",
"			  sea de BanCoppel a otro banco u Otro Banco a BanCoppel.",
"Codigos de Error: ",
"",
"			cCodRet = 001272 El proceso de Activacion de Portabilidad de Nomina de Bancoppel a Otro Banco no fue satisfactorio.",
"			cCodRet = 001285 La persona no tiene una cuenta de captacion valida.",
"			cCodRet = 001288 Parametros de Entrada vacios, verifique.",
"			cCodRet = 001289 No existe informacion. Favor de verificar.",
"			cCodRet = 001290 La cuenta BanCoppel se encuentra cancelada.",
"			cCodRet = 001291 La cuenta Bancoppel ya cuenta con el Servicio de Portabilidad activo.",
"			cCodRet = ",	
"Autor  : Jairo Valdez Gonzalez",
"Solicito: Ivan Castillo Montalvo",
"Folio: 1748",
"Sustento: RQM 10 610 Cambios en el Servicio de Portabilidad",
"Fecha  : 31/08/2015",
"BD     : bdicheq";

create procedure "informix".sp_registra_evento (
					pTipoMsj char(1), pIdMsj char(10),pIdPlantilla char(12), pNumclt char(20),
					pNumcta char(20), pNumTarjeta char(16),pTipoproc char(1), pStr1 char(30), 
					pStr2 char(30), pStr3 char(30), pStr4 char (30), 
					pStr5 char(150), pStr6 char(100), pStr7 char(60), pStr8 char(60), 
					pStr9 char(15), pStr10 char(100), pcorreo_alterno char(100), pcelular_alterno char(10), 
					pImporte1 money (16,2), pImporte2 money (16,2),
					pImporte3 money (16,2), pImporte4 money (16,2), pImporte5 money (16,2), 
					pfecha1 datetime year to fraction(3), pfecha2 datetime year to fraction(3)
				    )

RETURNING CHAR(5) as cCodRet;  -- Codigo de Retorno.


    --*******************************************************************************************************
    -- Realizo   :Angel Rene de la Llave
    -- Proyecto : Latinia registro de eventos.
    -- Actividad : Se registran los eventos para el envÃÆÃÂ­o de mnsjr y emails a un cliente
    --                  basados en las transacciones que haya efectuado.
    -- Fecha     : 26/03/2012
    -- ModificaciÃÆÃÂ³n: Incluir campos string adicionales. JGP-19/09/2012
    -- Fecha:       19/09/2012
    -- ModificaciÃÆÃÂ³n: Incluir registro de eventos pendientes de confirmar "PENDIENTE", hasta que sean 
    --               confirmados por Intercard. JGP-09/11/2012
    -- Fecha:       09/11/2012
	-- Realizo  : Manuel Osuna V.  
	-- ModificaciÃÂ³n: Se agrega parametro pIdPlantilla,para que explotar la funcionalidad de que una alerta
	-- pueda manejar multiples plantillas.
    -- Fecha:       15/10/2013
	-- Realizo  : Cristo Lugo  
	-- ModificaciÃÂ³n: Se agrega validaciÃÂ³n pIdMsj,para que evitar enviar la misma alerta durante el dia.
    -- Fecha:       28/08/2014
    --*******************************************************************************************************
 
--DefiniciÃÆÃÂ³n de Variables
DEFINE cCodRet CHAR(5);
DEFINE iexiste INTEGER;
DEFINE iexiste2 INTEGER;
DEFINE iexiste3 INTEGER;
DEFINE iexistec INTEGER;
DEFINE vnumcte CHAR(20);
DEFINE vsqlerr INTEGER;
DEFINE vtransaction_id CHAR(10);
DEFINE cDia CHAR (2);
DEFINE cAnio CHAR (4);
DEFINE cMes CHAR(2);
DEFINE cMes1 CHAR (10);
DEFINE cFechaH CHAR (10);


--Inicializa Variables
LET cCodRet = '00000';
LET iexiste = 0;
LET iexiste2 = 0;
LET iexiste3 = 0;
LET iexistec = 0;
LET vsqlerr = 0;
LET vnumcte = '';
LET cDia ='';
LET cAnio  ='';
LET cMes  ='';
LET cMes1 ='';
LET cFechaH ='';


BEGIN
   ON EXCEPTION SET vsqlerr
      IF vsqlerr <> 0 THEN
         return vsqlerr;
      END IF;
   END EXCEPTION;
	--SET DEBUG FILE TO "/informix/cristo/sp_registra_evento.out";
	--TRACE ON;

-- VERIFICA QUE LOS PARAMETROS DE ENTRADA NO ESTEN VACIOS O NULLS
	IF (pTipoMsj IS NULL OR pTipoMsj = '') OR
	   (pIdMsj IS NULL OR pIdMsj = '') OR
	   (pTipoproc IS NULL OR pTipoproc = '') OR
	   (pIdPlantilla IS NULL OR pIdPlantilla = '') THEN	   
	   LET cCodRet = '00005';
	   RETURN cCodRet;
	END IF;
	
--VERIFICA SI SE TRATA DE UN PROCESO VALIDO
	IF pTipoproc > '2' OR pTipoproc = '0'THEN
	   LET cCodRet = '00020';
	   RETURN cCodRet;
	END IF;
	
-- VERIFICA QUE SE UN TIPO DE MENSAJE VALIDO
	IF pTipoMsj > '3' OR pTipoMsj = '0' THEN
		LET cCodRet = '00103';
	    RETURN cCodRet;
	END IF;
--VARIFICA QUE UNO DE ESTOS TRES DATOS OBLIGATORIOS DEL CLIENTE VENGA INFORMACION	
	IF (pNumclt IS NULL OR pNumclt = '') AND (pNumcta IS NULL OR pNumcta ='') AND (pNumTarjeta IS NULL OR pNumTarjeta = '') THEN
	   LET cCodRet = '00110';
	   RETURN cCodRet;
	END IF;
	
--VALIDACION DE FECHA FORMATO DE MES NOMBRE COMPLETO
        
IF pIdMsj = 'POS_CREDE' OR pIdMsj = 'ATM_CREDE'THEN

	select DAY(fecha_hoy),MONTH(fecha_hoy),YEAR(fecha_hoy) into cDia,cMes,cAnio
    from bdinteg:"informix".si_fechas where empresa ='001';

	IF (cMes ='1') THEN LET cMes1 = 'ENERO';  
		ELIF (cMes ='2') THEN LET cMes1 = 'FEBRERO';
		ELIF (cMes ='3') THEN LET cMes1 = 'MARZO';
		ELIF (cMes ='4') THEN LET cMes1 = 'ABRIL';
		ELIF (cMes ='5') THEN LET cMes1 = 'MAYO';
		ELIF (cMes ='6') THEN LET cMes1 = 'JUNIO';
		ELIF (cMes ='7') THEN LET cMes1 = 'JULIO';
		ELIF (cMes ='8') THEN LET cMes1 = 'AGOSTO';
		ELIF (cMes ='9') THEN LET cMes1 = 'SEPTIEMBRE';
		ELIF (cMes ='10') THEN LET cMes1 = 'OCTUBRE';
		ELIF (cMes ='11') THEN LET cMes1 = 'NOVIEMBRE';
		ELIF (cMes ='12') THEN LET cMes1 = 'DICIEMBRE';
	END IF;
		
		LET pStr5 = trim(cDia)||'-'||trim(cMes1)||'-'||trim(cAnio);
END IF;	


--VALIDA QUE SI NO CONTIENE COMO PARAMETRO DE ENTRADA EL NUMERO DE CLIENTE, BÃÆÃÂ¡SQUE POR TARJETA O CUENTA.

	IF SUBSTR(pIdMsj,1,3)<>"WEB" THEN	
		IF trim(pNumclt) <> ''  THEN
			IF (trim(pNumclt) <> '000000000') THEN
				SELECT {+index (bdinteg:si_cliente,  224_479)} nvl(count(numcte),0) INTO iexistec FROM bdinteg:"informix".si_cliente WHERE numcte = pNumclt;
				IF (iexistec = 0 or iexistec is null) then
					LET cCodRet = '00100';
					RETURN cCodRet;
				END IF;
			END IF;	
		ELSE -- SE BUSCA EL CLIENTE
			IF TRIM(pNumcta) <> '' THEN
				SELECT {+index (bdicheq:sc_maechq, 174_183)} NVL(COUNT(CUENTA),0),NVL(num_cte, 0) INTO iexiste, vnumcte FROM bdicheq:"informix".sc_maechq WHERE CUENTA = pNumcta group by num_cte;
				IF (iexiste = 0 or iexiste is null) THEN
					SELECT {+index (bdicred:sd_maecred, idx_idx_maecredb)} NVL(COUNT(num_credito),0), NVL(numcte,0) INTO iexiste2, vnumcte FROM bdicred:"informix".sd_maecred WHERE num_credito = pNumcta group by numcte;
					IF (iexiste2 = 0 or iexiste2 is null) THEN
						IF TRIM(pNumTarjeta) <> '' THEN
							select {+index (intercard:tarjeta, 144_89)} nvl(count(numtarjeta),0), nvl(numcliente,0) into iexiste3, vnumcte from intercard:tarjeta where numtarjeta = pNumTarjeta group by numcliente;
							IF (iexiste3 = 0 or iexiste3 is null) then
								LET cCodRet = '00115';
								RETURN cCodRet;
							END IF;
						ELSE
							LET cCodRet = '00100';
							RETURN cCodRet;
						END IF;	
					END IF;
				END IF;
			ELIF TRIM(pNumTarjeta) <> '' THEN
				select {+index (intercard:tarjeta, 144_89)} nvl(count(numtarjeta),0), nvl(numcliente,0) into iexiste3, vnumcte from intercard:tarjeta where numtarjeta = pNumTarjeta group by numcliente;
				IF (iexiste3 = 0 or iexiste3 is null) then
					LET cCodRet = '00115';
					RETURN cCodRet;
				END IF;
			END IF;
			IF (iexiste = 0 or iexiste is null) and (iexiste2 = 0 or iexiste2 is null) and (iexiste3 = 0 or iexiste3 is null) THEN
				LET cCodRet = '00112';
				RETURN cCodRet;
			END IF;		
		END IF;
	END IF;		
	if vnumcte = '' or vnumcte is null  then
		LET vnumcte  = pNumclt;
	END IF;

	-- Eventos que requieren confirmaciÃÆÃÂ³n se registran como temporales. JGP-17/09/2012
	IF pIdMsj IN ('POS_DEBS','POS_CREDS','ATM_DEBS','ATM_CREDS','POS_DEBE','POS_CREDE','ATM_DEBE','ATM_CREDE') THEN -- Posible MigraciÃÆÃÂ³n a Tabla
		LET vtransaction_id ='PENDIENTE';
	ELSE
		LET vtransaction_id = NULL;
	END IF;	

	IF pTipoproc = '1' THEN
		IF pIdMsj = 'OFI_AVSMS' THEN
		
			IF NOT EXISTS(SELECT  {+AVOID_FULL(bdimnsj:"informix".mnsjr_trx_online)} cliente FROM bdimnsj:"informix".mnsjr_trx_online WHERE cliente = vnumcte AND id_mensaje = pIdMsj AND celular_alterno = pcelular_alterno AND fecha_hora_registro >= today) THEN
				INSERT INTO bdimnsj:"informix".mnsjr_trx_online
				(tipo_mensaje, id_mensaje,id_plantilla,cliente, cuenta, tarjeta, transaction_id, estatus, fecha_hora_registro, fecha_hora_recuperado, string1, string2, string3,		
				string4, string5, string6, string7, string8, string9, string10, correo_alterno, celular_alterno, 
				importe1, importe2, importe3, importe4, importe5, fecha1, fecha2)
				VALUES
				(pTipoMsj, pIdMsj,pIdPlantilla,vnumcte, pNumcta, pNumTarjeta, vtransaction_id, null, CURRENT, '', pStr1, pStr2, pStr3, pStr4, pStr5, pStr6, pStr7, pStr8, pStr9, pStr10,
				pcorreo_alterno, pcelular_alterno, pImporte1, pImporte2, pImporte3, pImporte4, pImporte5, pfecha1, pfecha2 );
			END IF;
		ELSE
			INSERT INTO bdimnsj:"informix".mnsjr_trx_online
				(tipo_mensaje, id_mensaje,id_plantilla,cliente, cuenta, tarjeta, transaction_id, estatus, fecha_hora_registro, fecha_hora_recuperado, string1, string2, string3,		
				string4, string5, string6, string7, string8, string9, string10, correo_alterno, celular_alterno, 
				importe1, importe2, importe3, importe4, importe5, fecha1, fecha2)
				VALUES
				(pTipoMsj, pIdMsj,pIdPlantilla,vnumcte, pNumcta, pNumTarjeta, vtransaction_id, null, CURRENT, '', pStr1, pStr2, pStr3, pStr4, pStr5, pStr6, pStr7, pStr8, pStr9, pStr10,
				pcorreo_alterno, pcelular_alterno, pImporte1, pImporte2, pImporte3, pImporte4, pImporte5, pfecha1, pfecha2 );
		END IF;
	ELSE
		
		INSERT INTO bdimnsj:"informix".mnsjr_trx_batch
		(tipo_mensaje, id_mensaje,id_plantilla,cliente, cuenta, tarjeta, transaction_id, estatus, fecha_hora_registro, fecha_hora_recuperado, string1, string2, string3,	
		string4, string5, string6, string7, string8, string9, string10, correo_alterno, celular_alterno, 
		importe1, importe2, importe3, importe4, importe5, fecha1, fecha2)
		VALUES
		(pTipoMsj, pIdMsj,pIdPlantilla, vnumcte, pNumcta, pNumTarjeta, vtransaction_id, null, CURRENT, '', pStr1, pStr2, pStr3, pStr4, pStr5, pStr6, pStr7, pStr8, pStr9, pStr10,
		pcorreo_alterno, pcelular_alterno, pImporte1, pImporte2, pImporte3, pImporte4, pImporte5, pfecha1, pfecha2 );
	 
	END IF;
		
END;	
RETURN 	cCodRet;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualiza_portabilidad(pEmpresa CHAR(3), 
													  pFolio CHAR(30), 
													  pClaveOrigen CHAR(1),
													  pEstatusPortabilidad CHAR(2), 
													  pSucursal CHAR(4), 
													  pUserInsert CHAR(8), 
													  pEstatus CHAR(2), 
													  pOrigenCancel CHAR(20), 
                                                      pFolioCancel CHAR(30) )
RETURNING CHAR(6);

--Declaracion de variables
DEFINE cCodRet 		CHAR(10);
DEFINE iTransaccion INTEGER;
DEFINE iSqlErr 		INTEGER;
DEFINE cFecha		DATE;
DEFINE cNumCte		CHAR(10);
DEFINE cNumCtaCbe	CHAR(18);
DEFINE cCuenta		CHAR(20);
DEFINE dFecha		CHAR(10);
DEFINE cCodRetSP    CHAR(5);
DEFINE cMenRetSp    CHAR(100);

--Asignacion de variables
LET cCodRet 	 = '000000';
LET iTransaccion = 0;
LET iSqlErr 	 = 0;
LET cFecha	 	 = DATE(1);
LET dFecha 		 = '01/01/1990';

LET cNumCte		 = '';
LET cNumCtaCbe	 = '';
LET cCuenta	 	 = '';
LET cCodRetSP 	 = '00000';
LET cMenRetSp    = '';

BEGIN

    ON EXCEPTION SET iSqlErr --Manejador de Errores	
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            IF iTransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;


            END IF;
			RETURN cCodRet;
        END IF;		
    END EXCEPTION;
	
    ON EXCEPTION IN (-535)
       LET iTransaccion = 1;
       COMMIT WORK;
       BEGIN WORK;
    END EXCEPTION WITH RESUME;
	


    BEGIN WORK;



        
	SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	--SET DEBUG FILE TO "/informix/sp_actualiza_portabilidad.out";
	--TRACE ON;

    IF NVL(pEmpresa, '') = '' OR  NVL(pFolio, '') = '' OR NVL(pClaveOrigen, '') = ''  OR  NVL(pEstatusPortabilidad, '') = '' OR NVL(pSucursal, '') = '' OR NVL(pUserInsert, '') = '' OR NVL(pEstatus, '') = '' OR NVL(pOrigenCancel, '') = '' THEN --Valida que  no sean nulo o espacio en blanco
		LET cCodRet = '001288';       
		RETURN cCodRet;
    END IF;

	SELECT fecha_hoy
	INTO cFecha

	FROM bdicheq:"informix".sc_fechas 
	WHERE empresa = pEmpresa;

	LET dFecha = TO_CHAR(cFecha, '%Y%m%d');
			
	SELECT num_cte, cta_ordenante
	INTO cNumCte, cNumCtaCbe
	FROM bdicheq:"informix".sc_portacec_solicitud 
	WHERE empresa = '001'
	AND folio_solicitud = pFolio;
	
	IF DBINFO('sqlca.sqlerrd2') = 0 THEN	
		LET cCodRet = "001289";
		RETURN cCodRet;
	END IF;
	
	SELECT cuenta
	INTO cCuenta
	FROM bdicheq:"informix".sc_maechq
	WHERE empresa = pEmpresa
	AND cuenta_clabe = cNumCtaCbe;
	
	IF DBINFO('sqlca.sqlerrd2') = 0 THEN	
		LET cCodRet = "001289";
		RETURN cCodRet;
	END IF;
	
	UPDATE bdicheq:"informix".sc_portacec_solicitud  
	SET clave_origen = '1', estatus_portabilidad = '4', clave_sentido = '0',
		fecha_estatus_portabilidad = dFecha, suc_cancela = pSucursal, 
		user_cancela = pUserInsert, fecha_solca_portabilidad = dFecha,
		folio_cancelacion= pFolioCancel
	WHERE  empresa = pEmpresa AND folio_solicitud = pFolio; 
	
/*
	UPDATE bdicheq:"informix".sc_portabilidadnomina  
	SET estatus = '02', user_cancel = pUserInsert, 
		fecha_cancel = dFecha, origen_cancel = 'OFI', 
		sucursal_cancel = pSucursal 
	WHERE empresa = pEmpresa 
	AND cliente = cNumCte
	AND cuenta_abono = cCuenta
	AND secuencia = (SELECT MAX(secuencia) 
							FROM bdicheq:"informix".sc_portabilidadnomina 
							WHERE empresa = pEmpresa 
							AND cuenta_abono = cCuenta);	
*/

    EXECUTE PROCEDURE bdicheq:sp_PortabCancela(cNumCte, cCuenta, 'OFI', pSucursal, pUserInsert)
    INTO cCodRetSP, cMenRetSp;

    IF cCodRetSP <> '00000' THEN
        LET cCodRet = '001280';
    END IF;

    IF  iTransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
       COMMIT WORK;
    END IF;

	RETURN cCodRet;
END
END PROCEDURE
DOCUMENT
"Descripcion: Se crea procedimiento para que actualice la informacion cuando se realice una cancelacion de portabilidad de nomina.",
"Codigos de Error: ",
"",
"			cCodRet = 001288 Parametros de Entrada vacios, verifique.",
"			cCodRet = 001289 No existe informacion. Favor de verificar",
"",			
"Autor  : Jairo Valdez Gonzalez",
"Solicito: Ivan Castillo Montalvo",
"Folio: 1748",
"Sustento: RQM 10 610 Cambios en el Servicio de Portabilidad",
"Fecha  : 27/08/2015",
"BD     : bdicheq";

