CREATE PROCEDURE "informix".sp_consulta_com_disp(pNumCta char(20), pNumCliente char(20))
	returning char(5), money, money, money, money;

	--****************************************************************************************************
	-- DESCRIPCION:  Obtiene la comision para dispLinea, Disp OB, Disp MB, SPEI
	-- AUTOR : Jesus Ferruzca Luna - SOLSER
	-- FECHA : 02/Diciembre/2015
	-- BD: bdicheq
	-- SOLICITADO POR: Alejandro Vazquez - Coordinación Internet - GM3  - BanCoppel
	-- Liberado a produccion: 28/Enero/2016
	--****************************************************************************************************

	--Definicion de Variables
	DEFINE vCodRet char(5);
    DEFINE sql_err integer;
	DEFINE mDisp_cta_bcoppel money;
   	DEFINE mDisp_cta_otrobco money;
    DEFINE mDisp_linea money;
    DEFINE mServ_tran_spei money;
    DEFINE iCont integer;
	
	--asigacion de valores a variables
	LET vCodRet='00000';
	LET mDisp_cta_bcoppel=0;
	LET mDisp_cta_otrobco=0;
	LET mDisp_linea=0;
	LET mServ_tran_spei=0;
    LET iCont = 0;
	
	
  BEGIN


   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let vCodRet = sql_err;
            RETURN vCodRet, mDisp_linea, mDisp_cta_bcoppel, mDisp_cta_otrobco,  mServ_tran_spei;
      END IF ;
   END EXCEPTION ;
	
	SET LOCK MODE TO WAIT ;
	SET ISOLATION DIRTY READ ;
	
	
	---Buscar comisiones de acuerdo al numCte y a la Cuenta -------------
	
	FOREACH
        SELECT disp_linea, disp_cta_bcoppel, disp_cta_otrobco, serv_tran_spei
        INTO   mDisp_linea, mDisp_cta_bcoppel, mDisp_cta_otrobco,  mServ_tran_spei
        FROM   bdicheq:"informix".sc_maecomtasserv_pm
        WHERE  num_cte = pNumCliente
        AND    cuenta = pNumCta
			
		LET iCont=1;
		
		RETURN vCodRet,  NVL(mDisp_linea,-1), NVL(mDisp_cta_bcoppel,-1), NVL(mDisp_cta_otrobco,-1), NVL(mServ_tran_spei,-1) WITH RESUME;
	END FOREACH;
	
	IF(iCont = 0) THEN
		LET vCodRet='00001';
		RETURN vCodRet, mDisp_linea, mDisp_cta_bcoppel, mDisp_cta_otrobco,  mServ_tran_spei;
	END IF;
	END;
END PROCEDURE
;

CREATE PROCEDURE "informix".sp_consulta_idoperctab(pTipoEmp SMALLINT, pConcepto SMALLINT, pTipoTransac char(3))
	returning char(5), char(4);

	--****************************************************************************************************
	-- DESCRIPCION:  Obtiene el ID de la operacion para Otros Bancos
	-- AUTOR : Jesus Ferruzca Luna - SOLSER
	-- FECHA : 02/Diciembre/2015
	-- BD: bdicheq
	-- SOLICITADO POR: Alejandro Vazquez - Coordinación Internet - GM3  - BanCoppel
	-- Liberado a produccion: 28 Enero 2016
	--****************************************************************************************************

	--Definicion de Variables
	DEFINE vCodRet char(5);
    DEFINE sql_err integer;
	DEFINE vTransaccion char(4);
    DEFINE iCont integer;
	
	--asigacion de valores a variables
	LET vCodRet='00000';
	LET vTransaccion='';
    LET iCont = 0;
	
	
  BEGIN


   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let vCodRet = sql_err;
            RETURN vCodRet, vTransaccion;
      END IF ;
   END EXCEPTION ;
	
	SET LOCK MODE TO WAIT ;
	SET ISOLATION DIRTY READ ;
	
		
	FOREACH
                
        SELECT  transacc
        INTO    vTransaccion
        FROM    "informix".sc_nominatransacciones
        WHERE   tipo_empresa = pTipoEmp
        AND     tipo_codigo = pConcepto
        AND     tipo_transaccion = pTipoTransac
			
		LET iCont=1;
		
		RETURN vCodRet, NVL(vTransaccion,'') WITH RESUME;
	END FOREACH;
	
	IF(iCont = 0) THEN
		LET vCodRet='00001';
		RETURN vCodRet, vTransaccion;
	END IF;
	END;
END PROCEDURE
;

CREATE FUNCTION "informix".valrfcemp_cecoban(pRFC CHAR(13))
	RETURNING --CHAR(5), -- codret,
              CHAR(1); -- Resp


    --DEFINE cCodRet 		CHAR(5);
	--DEFINE iSqlErr 		INTEGER;
    DEFINE cRespuesta	CHAR(1);
	DEFINE cValRFC1		CHAR(1);
	DEFINE cRFC1		CHAR(1);
    DEFINE iRFC1		SMALLINT;
	DEFINE i			SMALLINT;
    DEFINE iBandEspacio SMALLINT;
	DEFINE Var_rfcchar   VARCHAR(13);
	
	
	
    --LET cCodRet 	= "000";
    --LET iSqlErr  	= 0;
    LET cRespuesta	= "0";
	LET cValRFC1	= "";
	LET	cRFC1		= "";
    LET Var_rfcchar  = "";
	
	
	
BEGIN
    /*
	------  Control de Errores no Controlados
		ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;    
            RETURN cCodRet, cRespuesta;
        END IF;
		END EXCEPTION;
   */
	
		  --  SET DEBUG FILE TO "/informix/oper-prod/valrfcemp_cecoban.out";
		  --  TRACE ON;
   
    LET pRFC = TRIM(pRFC);

	
	IF LENGTH (pRFC) > 0 AND LENGTH (pRFC) < 13  THEN
      -- VALIDA QUE LOS PRIMEROS 3 CARACTERES SEAN LETRAS
		
			LET Var_rfcchar = TRIM(pRFC);
			
			LET iBandEspacio = INSTR (Var_rfcchar,' ',1);
			
			IF iBandEspacio = 0  THEN     
			
			
						FOR i=1 to 3
							LET cRFC1=SUBSTR(pRFC,i,1);
							CALL bdiprog:isnumeric(cRFC1) RETURNING cValRFC1;
							IF cValRFC1 = 1 THEN	
								LET cRespuesta = 1;  -- RFC INCORRECTO
								--EXIT FOR
								RETURN cRespuesta;
							END IF;
						END FOR
						
						
					   -- VALIDA QUE LOS CARACTES DE LA POSICION 4 A LA 9 SEAN NUMEROS
						FOR i=4 to 9
							LET cRFC1=SUBSTR(pRFC,i,1);
							CALL bdiprog:isnumeric(cRFC1) RETURNING cValRFC1;
							IF cValRFC1 = 0 THEN	
								LET cRespuesta = 1;  -- RFC INCORRECTO
								--EXIT FOR
								RETURN cRespuesta;
							END IF;
						END FOR
				   
				   
						-- VALIDACION DE FECHA
						LET iRFC1=SUBSTR(pRFC,6,2)::SMALLINT;

						
						IF  iRFC1 > 12 THEN
							LET cRespuesta = 1;  -- RFC INCORRECTO
						END IF;

						LET iRFC1=SUBSTR(pRFC,8,2)::SMALLINT;
					
						
						IF iRFC1 > 31 THEN
							LET cRespuesta = 1;  -- RFC INCORRECTO
						END IF;
				
			ELSE
			LET cRespuesta = 1;  -- RFC INCORRECTO
			
			END IF	
				
				
	 ELSE
	 LET cRespuesta = 1;  -- RFC INCORRECTO
				
				
     END IF
	
	RETURN cRespuesta;

END;
END FUNCTION
;